private const val DEFAULT_FUSION_BADGE_URL = "https://pastebin.com/raw/5xiu5fLL"
private const val MAX_FUSION_BADGE_URLS = 3
private const val LANGUAGE_BADGE_GROUP_ID = "gl"
private val DEFAULT_RATING_PROVIDER_ORDER = listOf("imdb", "tmdb", "tomatoes", "metacritic", "trakt", "letterboxd", "audience")
private val DEFAULT_RATING_PROVIDER_IDS = DEFAULT_RATING_PROVIDER_ORDER.toSet()

private val streamSizeLabelPattern = Regex("""(\d+(?:[.,]\d+)?)\s*(TB|TiB|GB|GiB|MB|MiB)\b""", RegexOption.IGNORE_CASE)

/**
 * The size to show on a stream card, or null when there isn't one.
 *
 * The badge used to print `stream.size` verbatim and uppercase it, which is only safe when that
 * field really holds a size. Plenty of sources put something else there — a release group, an
 * audio layout, a whole language list — and the card then rendered "ENGLISH • HINDI • TAMIL •
 * TELUGU" as a size pill wide enough to squeeze the title into a three-line column. Requiring the
 * value to actually parse as a size keeps the badge to what it claims to be, and falling back to
 * the stream's own text recovers a size for sources that only mention it in the title.
 */
internal fun streamSizeLabel(stream: AddonStream): String? {
  fun normalize(match: MatchResult): String {
    val amount = match.groupValues[1].replace(',', '.')
    val unit = when (match.groupValues[2].lowercase()) {
      "tb" -> "TB"
      "tib" -> "TiB"
      "gb" -> "GB"
      "gib" -> "GiB"
      "mb" -> "MB"
      "mib" -> "MiB"
      else -> match.groupValues[2].uppercase()
    }
    return "$amount $unit"
  }
  stream.size?.let { declared -> streamSizeLabelPattern.find(declared)?.let { return normalize(it) } }
  val text = listOfNotNull(stream.title, stream.name, stream.description, stream.filename).joinToString(" ")
  return streamSizeLabelPattern.find(text)?.let(::normalize)
}

/**
 * The quality band a result is filed under, in the order the bands are shown on Auto.
 *
 * Deliberately coarse. Sources describe quality in whatever words they like — "4K", "2160p", "UHD",
 * "FullHD", "HDRip" — and a list that made a separate heading of each spelling would be as hard to
 * read as the ungrouped one it replaced. [Unknown] is a real band rather than a bin for failures:
 * plenty of sources genuinely do not say, and those results still have to appear.
 */
internal enum class StreamQualityTier(val label: String) {
  Uhd("4K"),
  Qhd("1440p"),
  Fhd("1080p"),
  Hd("720p"),
  Sd("480p"),
  Ld("360p"),
  Unknown("Other"),
  // Last whatever else is present. A camera recording is not a quality tier so much as a warning,
  // and it belongs under the results somebody actually wants.
  Cam("CAM"),
}

/**
 * Matched against the whole of a result's text, most specific first.
 *
 * Word boundaries throughout, because the loose forms are the dangerous ones: a bare `hd` matches
 * inside "UHD", "FHD" and "HDR", and `ts` matches inside any number of release names — which is why
 * the camera-recording forms below are spelled out rather than abbreviated.
 */
private val streamQualityTierPatterns: List<Pair<Regex, StreamQualityTier>> = listOf(
  Regex("""\b(cam|camrip|hdcam|hdts|hdtc|telesync|telecine|ts-?rip)\b""", RegexOption.IGNORE_CASE) to StreamQualityTier.Cam,
  Regex("""\b(2160p?|4k|uhd|ultra\s?hd)\b""", RegexOption.IGNORE_CASE) to StreamQualityTier.Uhd,
  Regex("""\b(1440p?|2k|qhd)\b""", RegexOption.IGNORE_CASE) to StreamQualityTier.Qhd,
  Regex("""\b(1080p?|fhd|full\s?hd)\b""", RegexOption.IGNORE_CASE) to StreamQualityTier.Fhd,
  Regex("""\b(720p?|hd\s?rip|hdtv|hd)\b""", RegexOption.IGNORE_CASE) to StreamQualityTier.Hd,
  Regex("""\b(480p?|sd|dvd\s?rip|dvdrip)\b""", RegexOption.IGNORE_CASE) to StreamQualityTier.Sd,
  Regex("""\b(360p?|240p?|144p?)\b""", RegexOption.IGNORE_CASE) to StreamQualityTier.Ld,
)

/**
 * Which band a result belongs to.
 *
 * The source's own `quality` field is asked first and on its own: it is the only field that means
 * one thing, and reading it together with the title lets a filename like "Movie.2160p.sample" pull
 * a 720p stream into the 4K band.
 */
internal fun streamQualityTier(stream: AddonStream): StreamQualityTier {
  fun classify(text: String?): StreamQualityTier? {
    if (text.isNullOrBlank()) return null
    return streamQualityTierPatterns.firstOrNull { (pattern, _) -> pattern.containsMatchIn(text) }?.second
  }
  classify(stream.quality)?.let { return it }
  return classify(listOfNotNull(stream.name, stream.title, stream.filename, stream.description).joinToString(" "))
    ?: StreamQualityTier.Unknown
}

/** The band's accent. Distinct enough to be scanned down the page, quiet enough to sit under text. */
private fun streamQualityTierColor(tier: StreamQualityTier, fallback: Color): Color = when (tier) {
  StreamQualityTier.Uhd -> Color(0xFFF59E0B)
  StreamQualityTier.Qhd -> Color(0xFFA78BFA)
  StreamQualityTier.Fhd -> Color(0xFF38BDF8)
  StreamQualityTier.Hd -> Color(0xFF34D399)
  StreamQualityTier.Sd -> Color(0xFF94A3B8)
  StreamQualityTier.Ld -> Color(0xFF94A3B8)
  StreamQualityTier.Cam -> Color(0xFFF87171)
  StreamQualityTier.Unknown -> fallback.copy(alpha = 0.55f)
}

/**
 * Where a band sits under the viewer's chosen quality.
 *
 * The choice already decides what gets played; this makes it decide what gets seen first too, so
 * the setting means the same thing on a list as it does on a press. Everything else keeps its
 * natural order behind the preferred band, so the list is still highest-first below the top.
 */
internal fun streamQualityBandOrder(tier: StreamQualityTier, preferredQuality: String): Int {
  val preferred = when (preferredQuality.trim().lowercase()) {
    "2160p", "4k" -> StreamQualityTier.Uhd
    "1440p", "2k" -> StreamQualityTier.Qhd
    "1080p" -> StreamQualityTier.Fhd
    "720p" -> StreamQualityTier.Hd
    "480p" -> StreamQualityTier.Sd
    "360p" -> StreamQualityTier.Ld
    else -> null
  }
  return if (preferred != null && tier == preferred) -1 else tier.ordinal
}

/**
 * Words that describe a file rather than name it.
 *
 * Used to decide whether a source actually told us what this result is. Several plugin sources
 * answer with nothing but a resolution and a size — a row reading "1080p • 2.3 GB" is not a result
 * anyone can identify, and five of them from one source are indistinguishable from each other.
 */
private val streamDescriptorTokens = setOf(
  "4k", "uhd", "fhd", "qhd", "hd", "sd", "hq", "lq",
  "hdr", "hdr10", "hdr10+", "dv", "dolby", "vision", "atmos", "dts", "dtshd", "truehd", "ddp", "dd",
  "ac3", "eac3", "aac", "aac2", "opus", "flac", "mp3", "mp4", "mkv", "m3u8", "avi", "mpd",
  "x264", "x265", "h264", "h265", "hevc", "avc", "av1", "10bit", "8bit",
  "web", "webdl", "webrip", "bluray", "brrip", "bdrip", "dvdrip", "hdrip", "hdtv", "remux", "proper", "repack",
  "cam", "camrip", "ts", "tc", "telesync", "telecine", "multi", "dual", "audio", "sub", "subs", "subbed", "dubbed",
  "gb", "mb", "tb", "gib", "mib", "tib", "kb", "kbps", "mbps", "fps", "ch", "bit",
  "auto", "unknown", "stream", "link", "video", "file", "size", "quality", "source",
)

/**
 * Whether [value] contains anything that names the thing being watched.
 *
 * A token counts if it is not a descriptor, not a bare number and not a resolution. Two characters
 * is the floor, so "4k" and separators do not rescue an otherwise empty label.
 */
internal fun streamTextNamesTitle(value: String?): Boolean {
  if (value.isNullOrBlank()) return false
  return value.lowercase()
    .split(Regex("""[^\p{L}\p{N}+]+"""))
    .any { token ->
      token.length > 1 &&
        token !in streamDescriptorTokens &&
        !token.matches(Regex("""\d{2,4}p""")) &&
        !token.matches(Regex("""\d+"""))
    }
}

/**
 * What to call a result on the list.
 *
 * The source's own words come first, in the order Stremio's convention puts them: `name` is the
 * short label, `title` and `description` the detail block. The first of them that actually names
 * something wins — a field holding only "1080p" is skipped rather than printed, which is the whole
 * fix here, because several plugin sources fill `name` with the resolution and nothing else and
 * their results all rendered as identical unlabelled rows.
 *
 * [fallbackName] — the title being watched — stands in when no field named anything. Nothing is
 * hidden either way: a result that cannot describe itself still appears, under the name of the
 * thing it is a copy of.
 */
internal fun streamDisplayName(stream: AddonStream, fallbackName: String): String =
  listOf(stream.name, stream.title, stream.filename, stream.description)
    .firstNotNullOfOrNull { candidate -> streamSingleLine(candidate)?.takeIf(::streamTextNamesTitle) }
    ?: fallbackName

/** Collapses an add-on's multi-line text onto one line so a formatted row stays one line tall. */
private fun streamSingleLine(value: String?): String? =
  value?.replace(Regex("\\s+"), " ")?.trim()?.takeIf { it.isNotEmpty() }

/** Whitespace and case removed, so two spellings of the same sentence compare equal. */
internal fun streamTextFingerprint(value: String): String =
  value.replace(Regex("\\s+"), " ").trim().lowercase()

private fun parseStreamSizeGiB(size: String?): Double? {
  val raw = size?.trim().orEmpty()
  if (raw.isBlank()) return null
  // The trailing boundary keeps bitrates out: without it "~7.71 Mbps" matches as "7.71 MB", so a
  // 6 GB result reads as 7 MB and slips straight past the max-size cap.
  val match = Regex("""([\d.]+)\s*(GB|GiB|MB|MiB|TB|TiB)\b""", RegexOption.IGNORE_CASE).find(raw) ?: return null
  val value = match.groupValues[1].toDoubleOrNull() ?: return null
  return when (match.groupValues[2].lowercase()) {
    "tb", "tib" -> value * 1024.0
    "mb", "mib" -> value / 1024.0
    else -> value
  }
}

// Some addons only report the size inside the title/description, so fall back to
// scanning the stream text — otherwise those results bypass the max size cap.
private fun streamSizeGiB(stream: AddonStream): Double? =
  parseStreamSizeGiB(stream.size)
    ?: parseStreamSizeGiB(listOfNotNull(stream.title, stream.name, stream.filename, stream.description).joinToString(" "))

private fun preferredQualityBoost(stream: AddonStream, preferredQuality: String): Int {
  val quality = preferredQuality.trim()
  if (quality.equals("Auto", ignoreCase = true)) return 0
  val text = listOfNotNull(stream.title, stream.name, stream.filename, stream.description, stream.quality).joinToString(" ").lowercase()
  // An exact match must dominate every other tag bonus combined (codec/audio/remux
  // add up to roughly +300) so the chosen quality genuinely wins the ranking.
  return when (quality) {
    "2160p" -> when {
      "2160" in text || "4k" in text -> 520
      "1080" in text -> 200
      "720" in text -> 90
      else -> 20
    }
    "1080p" -> when {
      "1080" in text -> 520
      "720" in text -> 200
      "2160" in text || "4k" in text -> 120
      else -> 20
    }
    "720p" -> when {
      "720" in text -> 520
      "1080" in text -> 160
      "2160" in text || "4k" in text -> 40
      else -> 20
    }
    else -> 0
  }
}

/** Whether a stream, whichever add-on or plugin produced it, is pornography. */
private fun streamIsAdult(stream: AddonStream): Boolean = AdultContentFilter.isBlocked(
  stream.name,
  stream.title,
  stream.filename,
  stream.addonName,
  // Unlike a catalogue entry, a stream's description is usually the release name rather than a
  // synopsis, and that is exactly where the marker tends to sit.
  stream.description,
)

private fun rankedStreams(
  streams: List<AddonStream>,
  hasDebrid: Boolean,
  preferredQuality: String = "Auto",
  maxFileSizeGb: Int = 0,
  favouriteAddonIds: Set<String> = emptySet(),
  favouritePluginProviderIds: Set<String> = emptySet(),
): List<AddonStream> =
  streams
    // Every list that reaches the viewer is ranked here first, whatever produced it, so this is
    // the one place the block cannot be routed around by a new caller.
    .filterNot(::streamIsAdult)
    .filter { stream ->
      val sizeGiB = streamSizeGiB(stream)
      maxFileSizeGb <= 0 || sizeGiB == null || sizeGiB <= maxFileSizeGb.toDouble()
    }
    .sortedWith(
      compareByDescending<AddonStream> { stream ->
        stream.addonId in favouriteAddonIds || stream.addonId.removePrefix("plugin:") in favouritePluginProviderIds
      }
        .thenByDescending { streamScore(it, hasDebrid, preferredQuality, maxFileSizeGb) }
        .thenBy { it.title ?: it.name ?: it.filename ?: "" },
    )

private fun streamIdentity(stream: AddonStream): String =
  listOf(stream.addonId, stream.url.orEmpty(), stream.infoHash.orEmpty(), stream.name.orEmpty(), stream.title.orEmpty()).joinToString("|")

private val liveMediaTypes = setOf("sport", "sports", "channel", "live", "iptv", "events")

/** Stable id for a Media3 download derived from the stream's URL, so re-downloading the
 * same source resumes/reuses the same entry instead of creating a duplicate. */
private fun downloadIdFor(stream: AddonStream): String = "dl:" + (stream.url ?: "").hashCode().toUInt().toString(16)

/**
 * Marks a stream as coming from the offline download cache. Only Media3's data source chain can
 * read that cache, so a stream carrying this source forces the Media3 engine no matter what the
 * player-engine setting says — resuming a downloaded title through mpv would fail to open it.
 */
private const val DOWNLOAD_STREAM_SOURCE = "download"

/**
 * Whether an id is a download key rather than a catalogue id. Downloads saved before the media
 * record existed are keyed this way, and sending one to the details API resolves it to an
 * unrelated title — so these ids play the saved file instead of ever being looked up.
 */
private fun isDownloadMediaId(id: String): Boolean = id.startsWith("dl:")

private fun downloadStreamFor(entry: DownloadEntry): AddonStream = AddonStream(
  addonId = "streamdek:downloads",
  addonName = "Downloads",
  name = "Downloaded",
  title = entry.media.title,
  description = null,
  url = entry.url,
  infoHash = null,
  fileIdx = null,
  filename = null,
  quality = null,
  size = null,
  cachedBy = emptyList(),
  source = DOWNLOAD_STREAM_SOURCE,
)

// Manifest types that mean an add-on serves live TV. Per the Stremio protocol "tv"
// is live channels; series add-ons declare "series".
private val liveAddonTypes = setOf("tv", "channel", "live", "iptv", "sport", "sports", "events")

// In the Stremio addon protocol, catalog type "tv" means Live TV channels
// (series catalogs use type "series"). Some non-standard addons use "tv" for
// series, but those always carry IMDb/TMDB database ids — live channels never do.
private fun looksLikeSeriesDatabaseId(id: String): Boolean {
  val base = id.trim().substringBefore(":")
  return base.matches(Regex("^tt\\d+$", RegexOption.IGNORE_CASE)) ||
    id.startsWith("tmdb:", ignoreCase = true) ||
    id.startsWith("tvdb:", ignoreCase = true) ||
    base.matches(Regex("^\\d+$"))
}

// Scales the page background tint by the user's ambient tint preference so the
// ambient glow can show through more (lower percent = more transparent tint).
private fun ambientTintAlpha(base: Float, percent: Int): Float =
  (base * (percent.coerceIn(20, 100) / 100f)).coerceIn(0f, 1f)

private fun MediaItem.isLiveCatalogItem(): Boolean {
  val catalogText = listOfNotNull(sourceAddonName, sourceCatalogType, sourceCatalogId, sourceCatalogName).joinToString(" ").lowercase()
  val isLiveTvChannel = sourceCatalogType == "tv" && !looksLikeSeriesDatabaseId(id)
  return sourceCatalogType in liveMediaTypes ||
    isLiveTvChannel ||
    directStreamUrl != null ||
    listOf("live", "channel", "sport", "ultra max tv", "iptv").any { it in catalogText }
}

/**
 * Finds a stored favourite channel matching [item].
 *
 * The same channel reaches this from three places that do not agree on its metadata: a catalog
 * card (full source fields), the player (addon id taken from the resolved stream, which is often a
 * different addon), and the detail page (sometimes only the id and title). Matching on the full
 * tuple therefore fails in exactly the case that matters — a channel that IS favourited looking as
 * if it is not — so the addon id is only used to disambiguate between several entries sharing an
 * id, never as a requirement. Type is deliberately ignored: "live", "tv" and "channel" all occur
 * for the same channel depending on which catalog it came through.
 */
/**
 * Override key for a linked TV's name. The name comes from the TV itself (usually a generic model
 * string, and several TVs on one account often report the same one), so like add-on and plugin
 * names it is renamed locally rather than pushed back to the device.
 */
private fun tvDisplayNameKey(deviceId: String): String = "tv:$deviceId"

private fun tvDisplayName(device: LinkedTvDevice): String = DisplayNameOverrides.resolve(tvDisplayNameKey(device.id), device.name)

private fun withTvDisplayName(device: LinkedTvDevice): LinkedTvDevice = device.copy(name = tvDisplayName(device))

private fun List<MediaItem>.findFavouriteChannel(item: MediaItem): MediaItem? =
  firstOrNull { it.id == item.id && it.sourceAddonId == item.sourceAddonId } ?: firstOrNull { it.id == item.id }

private fun List<MediaItem>.hasFavouriteChannel(item: MediaItem): Boolean = findFavouriteChannel(item) != null

/**
 * Drops [item] from a favourites list. Every entry for the channel goes, not just the first
 * match: a list written before duplicates were prevented can hold several copies of one channel,
 * and removing them one at a time leaves the star lit after the tap that was supposed to clear it.
 */
private fun List<MediaItem>.withoutFavouriteChannel(item: MediaItem): List<MediaItem> = filterNot { it.id == item.id }

// Addons are installed dynamically by manifest URL, so there is no vendor flag
// declaring "this addon proxies its streams" — instead we infer it: either the
// stream URL resolves back to the addon's own host (rather than a third-party
// origin/CDN), or the addon supplies custom request headers (Stremio
// behaviorHints.proxyHeaders) needed to reach the real origin through it.
private fun AddonStream.isLikelyProxied(addon: InstalledAddon?): Boolean {
  val streamHost = url?.let { runCatching { java.net.URI(it).host }.getOrNull() }?.lowercase()
  val addonHost = listOfNotNull(addon?.transportUrl, addon?.baseUrl, addon?.url)
    .firstNotNullOfOrNull { runCatching { java.net.URI(it).host }.getOrNull() }
    ?.lowercase()
  return requestHeaders.isNotEmpty() || (streamHost != null && addonHost != null && streamHost == addonHost)
}

private fun streamMatchesSportsAddon(stream: AddonStream): Boolean {
  val text = listOf(stream.addonId, stream.addonName, stream.description, stream.name, stream.title).joinToString(" ").lowercase()
  return "sport" in text || "sports" in text || "espn" in text || "football" in text || "cricket" in text || "ufc" in text || "live tv" in text || "live-tv" in text || "live event" in text
}

private fun mediaStreamsOnly(streams: List<AddonStream>, detail: MediaDetail): List<AddonStream> =
  if (detail.type == "movie" || detail.type == "tv" || detail.type == "series") streams.filterNot(::streamMatchesSportsAddon) else streams

private fun MediaDetail.withCatalogFallback(item: MediaItem?): MediaDetail {
  if (item == null) return this
  return copy(
    type = type.takeIf { it == "movie" || it == "tv" } ?: if (item.type == "series") "tv" else item.type,
    title = title.ifBlank { item.title },
    titleLogo = titleLogo ?: item.titleLogo,
    year = year ?: item.year,
    description = description.ifBlank { item.description },
    poster = poster ?: item.poster,
    backdrop = backdrop ?: item.backdrop,
    rating = rating ?: item.rating,
    tmdbRating = tmdbRating ?: item.rating,
    genres = genres.ifEmpty { item.genres },
  )
}

private fun LocalAddonMeta.seasonSummaries(): List<SeasonSummary> = episodes
  .groupBy(EpisodeItem::seasonNumber)
  .toSortedMap()
  .map { (seasonNumber, seasonEpisodes) ->
    SeasonSummary(
      seasonNumber = seasonNumber,
      name = "Season $seasonNumber",
      episodeCount = seasonEpisodes.size,
      poster = poster,
      airDate = seasonEpisodes.mapNotNull(EpisodeItem::airDate).minOrNull(),
    )
  }.filter(::isSeasonAvailable)

private fun MediaDetail.withLocalAddonMeta(meta: LocalAddonMeta): MediaDetail {
  val bridgeSeasons = meta.seasonSummaries()
  return copy(
    type = if (meta.episodes.isNotEmpty()) "tv" else type,
    title = meta.title.ifBlank { title },
    year = year ?: meta.year,
    releaseDate = releaseDate ?: meta.releaseDate,
    description = meta.description.ifBlank { description },
    poster = poster ?: meta.poster,
    backdrop = backdrop ?: meta.backdrop ?: meta.poster,
    genres = genres.ifEmpty { meta.genres },
    runtimeMinutes = runtimeMinutes ?: meta.runtimeMinutes,
    seasonsCount = if (bridgeSeasons.isNotEmpty()) bridgeSeasons.size else seasonsCount,
    imdbId = imdbId ?: meta.imdbId,
    seasons = if (bridgeSeasons.isNotEmpty()) bridgeSeasons else seasons,
    cast = cast.ifEmpty { meta.cast },
  )
}

private fun LocalAddonMeta.toFallbackDetail(item: MediaItem): MediaDetail =
  item.toFallbackDetail().copy(
    id = id,
    type = if (episodes.isNotEmpty()) "tv" else item.type,
    title = title.ifBlank { item.title },
    year = year ?: item.year,
    releaseDate = releaseDate,
    description = description.ifBlank { item.description.ifBlank { "No synopsis available." } },
    poster = poster ?: item.poster,
    backdrop = backdrop ?: item.backdrop ?: poster,
    genres = genres.ifEmpty { item.genres },
    runtimeMinutes = runtimeMinutes,
    seasonsCount = seasonSummaries().size.takeIf { it > 0 },
    imdbId = imdbId,
    seasons = seasonSummaries(),
    cast = cast,
  )

private fun MediaItem.toFallbackDetail(): MediaDetail =
  MediaDetail(
    id = id,
    type = if (isLiveCatalogItem()) "live" else if (type == "series") "tv" else type,
    title = title,
    titleLogo = null,
    tagline = null,
    year = year,
    releaseDate = null,
    description = if (isLiveCatalogItem()) description else description.ifBlank { "No synopsis available." },
    poster = poster,
    backdrop = backdrop,
    trailerUrl = null,
    rating = rating,
    imdbRating = null,
    tmdbRating = rating,
    genres = genres,
    runtimeMinutes = null,
    seasonsCount = null,
    imdbId = id.takeIf { it.startsWith("tt") },
    seasons = emptyList(),
  )

private fun streamScore(stream: AddonStream, hasDebrid: Boolean, preferredQuality: String = "Auto", maxFileSizeGb: Int = 0): Int {
  val text = listOfNotNull(stream.title, stream.name, stream.filename, stream.description, stream.quality, stream.addonName).joinToString(" ").lowercase()
  val sizeGiB = streamSizeGiB(stream)
  var score = 0
  if (maxFileSizeGb > 0 && sizeGiB != null && sizeGiB > maxFileSizeGb.toDouble()) return Int.MIN_VALUE / 4
  if (!stream.url.isNullOrBlank()) score += 380
  if (hasDebrid && !stream.infoHash.isNullOrBlank()) score += 260
  if (stream.cachedBy.isNotEmpty()) score += 400 + ((stream.cachedBy.size - 1).coerceAtLeast(0) * 45)
  score += when {
    "2160" in text || "4k" in text -> 90
    "1080" in text -> 75
    "720" in text -> 45
    else -> 20
  }
  if ("english" in text || "multi" in text) score += 70
  if ("remux" in text) score += 35
  if ("web-dl" in text || "webdl" in text) score += 26
  if ("bluray" in text || "blu-ray" in text) score += 12
  if ("aac" in text || "flac" in text || "mp3" in text || "opus" in text) score += 90
  if ("ac3" in text || "eac3" in text || "dd+" in text) score += 40
  if ("dts:x" in text) score -= 160
  else if ("dts" in text) score -= 90
  if ("h264" in text || "h.264" in text || "avc" in text || "x264" in text) score += 120
  if ("av1" in text) score -= 80
  if ("hevc" in text || "x265" in text || "h265" in text) score += 20
  if ("cam" in text) score -= 200
  if ("telesync" in text) score -= 120
  score += preferredQualityBoost(stream, preferredQuality)
  if (sizeGiB != null) {
    score += when {
      sizeGiB in 0.6..12.5 -> 30
      sizeGiB > 30.0 -> -65
      sizeGiB < 0.25 -> -55
      else -> 0
    }
  }
  return score
}

private class AuthEntryStore(context: Context) {
  private val prefs = context.getSharedPreferences("streamdek_native_auth_entry", Context.MODE_PRIVATE)

  fun loadEmail(): String = prefs.getString("last_email", "").orEmpty()

  fun saveEmail(email: String) {
    prefs.edit().putString("last_email", email).apply()
  }
}

/**
 * Subtitle sizing bounds, shared by the settings screen, the in-player controls and the store.
 *
 * The numbers are mpv's own: `sub-font-size` defaults to 55, and `sub-pos` is a percentage down the
 * frame where 100 is the very bottom. Media3 scales the same values into its own units, so one
 * setting drives both engines.
 */
internal val SUBTITLE_TEXT_SIZE_RANGE = 28..84
internal val SUBTITLE_OFFSET_RANGE = 50..110

/**
 * The colours offered for subtitle text, background and outline.
 *
 * A fixed palette rather than a free-form picker: these are the shades that stay legible over
 * video, and naming them keeps the setting readable in the list instead of showing a hex code.
 */
internal val SUBTITLE_COLOR_CHOICES: List<Pair<String, String>> = listOf(
  "White" to "#FFFFFFFF",
  "Soft White" to "#FFE8E8E8",
  "Yellow" to "#FFFFEB3B",
  "Amber" to "#FFFFC107",
  "Cyan" to "#FF4DD0E1",
  "Green" to "#FF81C784",
  "Black" to "#FF000000",
)

/** Background and outline can also be turned off entirely, which text cannot. */
internal val SUBTITLE_FILL_CHOICES: List<Pair<String, String>> = listOf("Transparent" to "#00000000") +
  SUBTITLE_COLOR_CHOICES.map { (name, value) -> name to value } +
  listOf("Dimmed Black" to "#A6000000")

internal fun subtitleColorLabel(value: String): String =
  SUBTITLE_FILL_CHOICES.firstOrNull { it.second.equals(value, ignoreCase = true) }?.first ?: value

private class AppSettingsStore(context: Context) {
  private val prefs = context.getSharedPreferences(APP_SETTINGS_PREFERENCES, Context.MODE_PRIVATE)
  private val appContext = context.applicationContext
  private var profilePrefs = prefs
  private val profileSettingKeys = setOf(
    "detail_page_style", "season_tab_style", "show_streams_list", "hero_trailer_autoplay", "hero_trailer_resolution",
    "hero_trailer_delay_seconds",
    "hero_trailer_muted", "show_hero_synopsis", "continue_watching_style", "live_landscape_cards", "live_favourite_drawer_cards",
    "live_categories_enabled", "live_progress_bar", "mdblist_api_key", "primary_sync_service",
    "remember_last_source", "skip_intro_enabled", "skip_segments_enabled", "skip_recap_enabled", "skip_ending_enabled",
    "auto_skip_intro_enabled", "auto_skip_recap_enabled", "auto_skip_ending_enabled",
    "introdb_api_key",
    "auto_play_next_episode", "prefer_binge_group", "auto_load_subtitles", "blur_unwatched_episodes", "favorite_source_keys",
    "subtitle_text_size", "subtitle_vertical_offset", "subtitle_bold", "subtitle_text_color",
    "subtitle_background_color", "subtitle_outline", "subtitle_outline_color", "subtitle_default_source",
    "next_episode_threshold_mode", "next_episode_threshold_percent", "next_episode_threshold_minutes",
    "end_of_playback_recommendations_enabled", "recommendation_timing", "recommendation_item_count",
    "ratings_enabled", "external_ratings_enabled", "enabled_rating_providers", "vivid_ambient", "ambient_tint_percent",
    "detail_ambient_tint_percent",
    "default_app_catalogs_enabled", "home_catalog_rows", "fusion_badges", "show_size_badges",
    "preferred_quality", "max_file_size_gb", "badge_position", "fusion_badge_urls", "active_fusion_badge_url",
  )

  fun selectProfileStorage(ownerKey: String) {
    val safeOwner = ownerKey.ifBlank { GUEST_OWNER_KEY }
    profilePrefs = appContext.getSharedPreferences(
      "streamdek_native_profile_settings_" + safeOwner.hashCode().toUInt().toString(16),
      Context.MODE_PRIVATE,
    )
    if (profilePrefs.all.isEmpty()) {
      val editor = profilePrefs.edit()
      profileSettingKeys.forEach { key ->
        when (val value = prefs.all[key]) {
          is Boolean -> editor.putBoolean(key, value)
          is Int -> editor.putInt(key, value)
          is Long -> editor.putLong(key, value)
          is Float -> editor.putFloat(key, value)
          is String -> editor.putString(key, value)
          is Set<*> -> @Suppress("UNCHECKED_CAST") editor.putStringSet(key, value as Set<String>)
        }
      }
      editor.apply()
    }
  }

  fun applyTo(state: AppUiState): AppUiState = state.copy(
    rememberLastProfileAtStartup = prefs.getBoolean("remember_last_profile_at_startup", false),
    showProfilePicker = state.showProfilePicker && !prefs.getBoolean("remember_last_profile_at_startup", false),
    appAppearance = runCatching { AppAppearance.valueOf(prefs.getString("app_appearance", AppAppearance.System.name) ?: AppAppearance.System.name) }.getOrDefault(AppAppearance.System),
    animationSpeed = AnimationSpeed.fromKey(prefs.getString(ANIMATION_SPEED_PREFERENCE, null)),
    appLanguage = normalizeAppLanguage(prefs.getString(APP_LANGUAGE_PREFERENCE, "en")),
    themePreset = runCatching { AppThemePreset.valueOf(prefs.getString("theme_preset", AppThemePreset.Monochrome.name) ?: AppThemePreset.Monochrome.name) }.getOrDefault(AppThemePreset.Monochrome),
    headerStyle = runCatching { HeaderStyle.valueOf(prefs.getString("header_style", HeaderStyle.Classic.name) ?: HeaderStyle.Classic.name) }.getOrDefault(HeaderStyle.Classic),
    pictureInPictureEnabled = prefs.getBoolean("pip_enabled", false),
    decoderMode = normalizeDecoderModeSetting(prefs.getString("decoder_mode", "HW+") ?: "HW+"),
    renderSurface = normalizeRenderSurfaceSetting(prefs.getString("render_surface", "Standard") ?: "Standard"),
    playerEngine = normalizePlayerEngineSetting(prefs.getString("player_engine", "Auto") ?: "Auto"),
    preferredAudioLanguage = normalizePreferredAudioLanguage(prefs.getString("preferred_audio_language", "en")),
    secondaryAudioLanguage = Languages.normalize(prefs.getString("secondary_audio_language", Languages.NONE)),
    preferredSubtitleLanguage = Languages.normalize(prefs.getString("preferred_subtitle_language", "en")),
    secondarySubtitleLanguage = Languages.normalize(prefs.getString("secondary_subtitle_language", Languages.NONE)),
    useForcedSubtitles = prefs.getBoolean("use_forced_subtitles", false),
    showOnlyPreferredSubtitleLanguages = prefs.getBoolean("show_only_preferred_subtitle_languages", false),
    addonSubtitleLoading = prefs.getString("addon_subtitle_loading", ADDON_SUBTITLE_LOADING_ALL) ?: ADDON_SUBTITLE_LOADING_ALL,
    detailPageStyle = runCatching { DetailPageStyle.valueOf(profilePrefs.getString("detail_page_style", DetailPageStyle.Classic.name) ?: DetailPageStyle.Classic.name) }.getOrDefault(DetailPageStyle.Classic),
    seasonTabStyle = runCatching { SeasonTabStyle.valueOf(profilePrefs.getString("season_tab_style", SeasonTabStyle.Regular.name) ?: SeasonTabStyle.Regular.name) }.getOrDefault(SeasonTabStyle.Regular),
    showNavLabels = prefs.getBoolean("show_nav_labels", true),
    collapsibleNavigationEnabled = prefs.getBoolean("collapsible_navigation_enabled", false),
    downloadsEnabled = prefs.getBoolean("downloads_enabled", false),
    dv7HevcFallback = prefs.getBoolean("dv7_hevc_fallback", false),
    tunneledPlayback = prefs.getBoolean("tunneled_playback", false),
    navigationAutoCollapseSeconds = prefs.getInt("navigation_auto_collapse_seconds", 5).coerceIn(2, 15),
    showStreamsList = profilePrefs.getBoolean("show_streams_list", true),
    heroTrailerAutoplay = profilePrefs.getBoolean("hero_trailer_autoplay", true),
    heroTrailerResolution = profilePrefs.getInt("hero_trailer_resolution", 2160).coerceIn(360, 2160),
    heroTrailerDelaySeconds = profilePrefs.getInt("hero_trailer_delay_seconds", DEFAULT_TRAILER_DELAY_SECONDS)
      .coerceIn(0, MAX_TRAILER_DELAY_SECONDS),
    heroTrailerMuted = profilePrefs.getBoolean("hero_trailer_muted", true),
    debridCloudSync = prefs.getBoolean("debrid_cloud_sync", true),
    showHeroSynopsis = profilePrefs.getBoolean("show_hero_synopsis", false),
    continueWatchingStyle = runCatching { ContinueWatchingStyle.valueOf(profilePrefs.getString("continue_watching_style", ContinueWatchingStyle.Glass.name) ?: ContinueWatchingStyle.Glass.name) }.getOrDefault(ContinueWatchingStyle.Glass),
    networkCardStyle = runCatching { NetworkCardStyle.valueOf(profilePrefs.getString("network_card_style", NetworkCardStyle.Branded.name) ?: NetworkCardStyle.Branded.name) }.getOrDefault(NetworkCardStyle.Branded),
    liveLandscapeCards = profilePrefs.getBoolean("live_landscape_cards", true),
    newEpisodesLandscape = profilePrefs.getBoolean("new_episodes_landscape", true),
    liveCategoriesEnabled = profilePrefs.getBoolean("live_categories_enabled", true),
    liveProgressBarEnabled = profilePrefs.getBoolean("live_progress_bar", false),
    primarySyncService = normalizedPrimarySyncService(profilePrefs.getString("primary_sync_service", null)),
    liveFavouriteDrawerCards = profilePrefs.getBoolean("live_favourite_drawer_cards", false),
    favoriteSourceKeys = profilePrefs.getStringSet("favorite_source_keys", emptySet()).orEmpty(),
    rememberLastSource = profilePrefs.getBoolean("remember_last_source", true),
    syncOnCellular = prefs.getBoolean("sync_on_cellular", false),
    holdToSpeedEnabled = prefs.getBoolean("hold_to_speed_enabled", true),
    holdToSpeedMultiplier = prefs.getFloat("hold_to_speed_multiplier", 2f),
    swipeToSeekEnabled = prefs.getBoolean("swipe_to_seek_enabled", true),
    doubleTapSeekEnabled = prefs.getBoolean("double_tap_seek_enabled", true),
    doubleTapSeekSeconds = prefs.getInt("double_tap_seek_seconds", 10).takeIf { it in setOf(5, 10, 15) } ?: 10,
    doubleTapPlayPauseEnabled = prefs.getBoolean("double_tap_play_pause_enabled", true),
    showPlayerControlLabels = prefs.getBoolean("show_player_control_labels", true),
    // Compact was retired; profiles carrying the old value transparently return to Normal.
    playerControlLayout = prefs.getString("player_control_layout", "Normal").takeIf { it in setOf("Normal", "Minimal") } ?: "Normal",
    fullscreenStatusBar = prefs.getString("fullscreen_status_bar", "Automatic").takeIf { it in setOf("Always show", "Hide in fullscreen", "Automatic") } ?: "Automatic",
    playerTitleDisplay = prefs.getString("player_title_display", "Single line").takeIf { it in setOf("Single line", "Scrolling", "Hidden") } ?: "Single line",
    // Defaults on, which is what the player has always done, so nobody's gestures change because
    // the switch arrived.
    playerLevelGesturesEnabled = prefs.getBoolean("player_level_gestures_enabled", true),
    skipIntroEnabled = profilePrefs.getBoolean("skip_intro_enabled", profilePrefs.getBoolean("skip_segments_enabled", true)),
    skipRecapEnabled = profilePrefs.getBoolean("skip_recap_enabled", true),
    skipEndingEnabled = profilePrefs.getBoolean("skip_ending_enabled", true),
    autoSkipIntroEnabled = profilePrefs.getBoolean("auto_skip_intro_enabled", false),
    autoSkipRecapEnabled = profilePrefs.getBoolean("auto_skip_recap_enabled", false),
    autoSkipEndingEnabled = profilePrefs.getBoolean("auto_skip_ending_enabled", false),
    introdbApiKey = profilePrefs.getString("introdb_api_key", "") ?: "",
    autoPlayNextEpisode = profilePrefs.getBoolean("auto_play_next_episode", true),
    preferBingeGroup = profilePrefs.getBoolean("prefer_binge_group", true),
    autoLoadSubtitles = profilePrefs.getBoolean("auto_load_subtitles", true),
    subtitleTextSize = profilePrefs.getInt("subtitle_text_size", 55).coerceIn(SUBTITLE_TEXT_SIZE_RANGE),
    subtitleVerticalOffset = profilePrefs.getInt("subtitle_vertical_offset", 92).coerceIn(SUBTITLE_OFFSET_RANGE),
    subtitleBold = profilePrefs.getBoolean("subtitle_bold", false),
    subtitleTextColor = profilePrefs.getString("subtitle_text_color", null) ?: "#FFFFFFFF",
    subtitleBackgroundColor = profilePrefs.getString("subtitle_background_color", null) ?: "#00000000",
    subtitleOutline = profilePrefs.getBoolean("subtitle_outline", true),
    subtitleOutlineColor = profilePrefs.getString("subtitle_outline_color", null) ?: "#FF000000",
    subtitleDefaultSource = normalizeSubtitleDefaultSource(profilePrefs.getString("subtitle_default_source", null)),
    blurUnwatchedEpisodes = profilePrefs.getBoolean("blur_unwatched_episodes", true),
    nextEpisodeThresholdMode = profilePrefs.getString("next_episode_threshold_mode", "minutes") ?: "minutes",
    nextEpisodeThresholdPercent = profilePrefs.getInt("next_episode_threshold_percent", 95).coerceIn(50, 99),
    nextEpisodeThresholdMinutes = profilePrefs.getInt("next_episode_threshold_minutes", 2).coerceIn(1, 15),
    endOfPlaybackRecommendationsEnabled = profilePrefs.getBoolean("end_of_playback_recommendations_enabled", false),
    recommendationTiming = profilePrefs.getString("recommendation_timing", "standard").takeIf { it in setOf("early", "standard", "late") } ?: "standard",
    recommendationItemCount = profilePrefs.getInt("recommendation_item_count", 1).coerceIn(1, 2),
    peerStreamSettings = PeerStreamSettings(
      enabled = prefs.getBoolean("torrent_enabled", true),
      streamingMode = prefs.getString("torrent_streaming_mode", "server") ?: "server",
      profile = prefs.getString("torrent_profile", "default") ?: "default",
      cacheSizeGb = prefs.getInt("torrent_cache_size_gb", 5),
      port = prefs.getInt("torrent_port", 11100),
      runAsForegroundService = prefs.getBoolean("torrent_run_foreground", false),
    ),
    ratingsEnabled = profilePrefs.getBoolean("ratings_enabled", true),
    externalRatingsEnabled = profilePrefs.getBoolean("external_ratings_enabled", true),
    enabledRatingProviders = parseRatingProviderIds(profilePrefs.getString("enabled_rating_providers", null)),
    vividAmbient = profilePrefs.getBoolean("vivid_ambient", true),
    detailBackgroundMode = runCatching {
      BackgroundMode.valueOf(
        profilePrefs.getString("detail_background_mode", null)
        // No stored mode means an account from before this setting existed: whatever its blurred
        // backdrop was set to is the mode it should carry on with.
          ?: if (profilePrefs.getBoolean("vivid_ambient", true)) BackgroundMode.Cinematic.name else BackgroundMode.Normal.name,
      )
    }.getOrDefault(BackgroundMode.Cinematic),
    homeBackgroundMode = runCatching {
      BackgroundMode.valueOf(
        profilePrefs.getString("home_background_mode", null)
          ?: if (profilePrefs.getBoolean("vivid_ambient", true)) BackgroundMode.Cinematic.name else BackgroundMode.Normal.name,
      )
    }.getOrDefault(BackgroundMode.Cinematic).takeIf { it in homeBackgroundModes } ?: BackgroundMode.Cinematic,
    // Device-local, like the animation speed and the player gestures: it describes how close this
    // particular screen is held, which is not something the account can answer for the television.
    homeDensity = HomeDensity.fromKey(prefs.getString(HOME_DENSITY_PREFERENCE, null)),
    trailerCacheClearHours = profilePrefs.getInt("trailer_cache_clear_hours", DEFAULT_TRAILER_CACHE_CLEAR_HOURS),
    ambientTintPercent = profilePrefs.getInt("ambient_tint_percent", 100).coerceIn(20, 100),
    // Seeded from the single value the two pages used to share, so an account that had already
    // chosen a strength keeps it on both pages rather than snapping back to full on one of them.
    detailAmbientTintPercent = profilePrefs.getInt(
      "detail_ambient_tint_percent",
      profilePrefs.getInt("ambient_tint_percent", 100),
    ).coerceIn(20, 100),
    defaultAppCatalogsEnabled = profilePrefs.getBoolean("default_app_catalogs_enabled", true),
    homeCatalogRows = parseHomeCatalogRows(profilePrefs.getString("home_catalog_rows", null)),
    fusionBadgesEnabled = profilePrefs.getBoolean("fusion_badges", true),
    streamDekFormattingEnabled = profilePrefs.getBoolean("streamdek_stream_formatting", false),
    showSizeBadges = profilePrefs.getBoolean("show_size_badges", true),
    preferredQuality = profilePrefs.getString("preferred_quality", "Auto") ?: "Auto",
    maxFileSizeGb = profilePrefs.getInt("max_file_size_gb", 0),
    badgePosition = profilePrefs.getString("badge_position", "Bottom") ?: "Bottom",
    fusionBadgeUrls = parseFusionBadgeUrls(profilePrefs.getString("fusion_badge_urls", null)),
    activeFusionBadgeUrl = profilePrefs.getString("active_fusion_badge_url", null),
    autoUpdateChecksEnabled = prefs.getBoolean("auto_update_checks", true),
  )

