private fun parseFusionBadgeUrls(raw: String?): List<String> {
  if (raw.isNullOrBlank()) return listOf(DEFAULT_FUSION_BADGE_URL)
  return runCatching {
    val source = JSONArray(raw)
    buildList {
      for (index in 0 until source.length()) {
        val url = source.optString(index).trim()
        if (url.isNotBlank() && !contains(url)) add(url)
      }
    }.take(MAX_FUSION_BADGE_URLS).ifEmpty { listOf(DEFAULT_FUSION_BADGE_URL) }
  }.getOrDefault(listOf(DEFAULT_FUSION_BADGE_URL))
}

private fun parseRatingProviderIds(raw: String?): Set<String> {
  if (raw.isNullOrBlank()) return DEFAULT_RATING_PROVIDER_IDS
  return runCatching {
    val source = JSONArray(raw)
    buildSet {
      for (index in 0 until source.length()) {
        source.optString(index).trim().lowercase().ifBlank { null }?.let(::add)
      }
    }.ifEmpty { DEFAULT_RATING_PROVIDER_IDS }
  }.getOrDefault(DEFAULT_RATING_PROVIDER_IDS)
}

private fun normalizeDecoderModeSetting(raw: String): String = when (raw.trim()) {
  "Prefer Device", "HW+" -> "HW+"
  "Device Only", "HW" -> "HW"
  "Prefer App", "SW" -> "SW"
  else -> "HW+"
}

private fun normalizeRenderSurfaceSetting(raw: String): String = when (raw.trim()) {
  "Texture", "Standard" -> "Standard"
  "Compatibility" -> "Compatibility"
  else -> "Standard"
}

internal fun normalizePlayerEngineSetting(raw: String): String = when (raw.trim().lowercase(Locale.US)) {
  "media3", "exo", "exoplayer" -> "Media3"
  "mpv" -> "MPV"
  else -> "Auto"
}

private fun PeerStreamSettings.toServiceConfig(): PeerStreamConfig = PeerStreamConfig(
  enabled = enabled,
  streamingMode = streamingMode,
  profile = profile,
  cacheSizeGb = cacheSizeGb,
  port = port,
  runAsForegroundService = runAsForegroundService,
)

private fun peerStreamStatusFromSnapshot(snapshot: Map<String, Any>, fallback: PeerStreamSettings): PeerStreamStatus {
  val port = (snapshot["port"] as? Number)?.toInt() ?: fallback.port
  return PeerStreamStatus(
    isOnline = snapshot["isOnline"] as? Boolean ?: false,
    isForeground = snapshot["isForeground"] as? Boolean ?: false,
    requestedForeground = snapshot["requestedForeground"] as? Boolean ?: fallback.runAsForegroundService,
    port = port,
    url = snapshot["url"] as? String ?: "http://127.0.0.1:$port",
    cacheDirectory = snapshot["cacheDirectory"] as? String ?: "",
    peerStoreDirectory = snapshot["peerStoreDirectory"] as? String ?: "",
    cacheUsageBytes = (snapshot["cacheUsageBytes"] as? Number)?.toLong() ?: 0L,
    profile = snapshot["profile"] as? String ?: fallback.profile,
    cacheSizeGb = (snapshot["cacheSizeGb"] as? Number)?.toInt() ?: fallback.cacheSizeGb,
    recoveryMode = snapshot["recoveryMode"] as? String ?: "idle",
    lastStartupError = snapshot["lastStartupError"] as? String ?: "",
    foregroundDowngradeReason = snapshot["foregroundDowngradeReason"] as? String ?: "",
    lifecycleState = snapshot["lifecycleState"] as? String ?: "idle",
  )
}

/**
 * Bumped when trailer state is cleared; read by everything that resolves or plays a trailer.
 *
 * Observable global state rather than a parameter or a composition local: three screens raise
 * trailers through two layers of composables, and a reset that only some of them noticed would be
 * worse than none — the page would re-resolve while the WebView beneath it kept the failing session.
 * Reading it in a composable subscribes that composable, so a bump reaches every trailer surface
 * currently on screen and nothing else.
 */
internal object TrailerResetSignal {
  private val state = androidx.compose.runtime.mutableIntStateOf(0)

  @Composable
  fun current(): Int = state.intValue

  fun bump() {
    state.intValue += 1
  }
}

/** How much subtitle add-ons are asked for. */
internal const val ADDON_SUBTITLE_LOADING_PREFERRED = "preferred"
internal const val ADDON_SUBTITLE_LOADING_ALL = "all"
internal const val ADDON_SUBTITLE_LOADING_OFF = "off"

internal val addonSubtitleLoadingChoices: List<Pair<String, String>> = listOf(
  ADDON_SUBTITLE_LOADING_PREFERRED to "Preferred languages",
  ADDON_SUBTITLE_LOADING_ALL to "All languages",
  ADDON_SUBTITLE_LOADING_OFF to "Off",
)

internal fun addonSubtitleLoadingLabel(value: String): String =
  addonSubtitleLoadingChoices.firstOrNull { it.first == value }?.second ?: "Preferred languages"

internal val subtitleSourceChoices: List<Pair<String, String>> = listOf(
  "All" to "All sources",
  "BuiltIn" to "Built-in",
  "Addons" to "Add-ons",
)

internal fun normalizeSubtitleDefaultSource(value: String?): String = when (value?.trim()?.lowercase()) {
  "builtin", "built-in", "embedded" -> "BuiltIn"
  "addons", "add-ons", "addon" -> "Addons"
  else -> "All"
}

internal fun subtitleSourceLabel(value: String?): String =
  subtitleSourceChoices.first { it.first == normalizeSubtitleDefaultSource(value) }.second

internal fun subtitleSourceIncludesBuiltIn(value: String?): Boolean =
  normalizeSubtitleDefaultSource(value) != "Addons"

internal fun subtitleSourceIncludesAddons(value: String?): Boolean =
  normalizeSubtitleDefaultSource(value) != "BuiltIn"

/**
 * The subtitle languages a viewer has asked for, most wanted first, with nothing repeated.
 *
 * "None" as the secondary means exactly that, so it contributes nothing rather than an empty string
 * that would match every untagged track.
 */
internal fun preferredSubtitleLanguages(primary: String, secondary: String): List<String> =
  listOf(primary, secondary)
    .map(Languages::normalize)
    .filter { it.isNotEmpty() && it != Languages.NONE && it != Languages.ORIGINAL }
    .distinct()

/**
 * How long a notice stays up before it withdraws on its own.
 *
 * A provider refusal is given twelve seconds because it names a service and a reason the viewer may
 * want to act on; an error is given ten, and a plain confirmation five — long enough to read, short
 * enough not to sit over the player.
 */
private const val PLAYBACK_NOTICE_DURATION_MS = 12_000L
private const val APP_NOTICE_ERROR_DURATION_MS = 10_000L
private const val APP_NOTICE_DURATION_MS = 5_000L
private const val CROSS_DEVICE_CONTINUE_NOTICE_DURATION_MS = 7_000L

internal fun crossDeviceContinueNotice(
  mediaType: String,
  seasonNumber: Int? = null,
  episodeNumber: Int? = null,
): String {
  val isSeries = mediaType.trim().lowercase() in setOf("tv", "series", "show")
  val kind = if (isSeries) "series" else "movie"
  val sourceTarget = if (isSeries && seasonNumber != null && episodeNumber != null) {
    " for Season $seasonNumber, Episode $episodeNumber"
  } else {
    ""
  }
  return "You started this $kind on another device. Choose a source$sourceTarget to continue watching from where you left off."
}

internal fun appInfoNoticeDuration(message: String): Long =
  if (message.startsWith("You started this ") && message.contains(" on another device.")) {
    CROSS_DEVICE_CONTINUE_NOTICE_DURATION_MS
  } else {
    APP_NOTICE_DURATION_MS
  }

/** Trailer cache housekeeping: daily, at nine in the morning. */
internal const val DEFAULT_TRAILER_CACHE_CLEAR_HOURS = 24
internal const val TRAILER_CACHE_CLEAR_HOUR_OF_DAY = 9

/** The intervals offered for automatic trailer-cache clearing, as hours to label. */
internal val trailerCacheClearChoices: List<Pair<Int, String>> = listOf(
  12 to "Every 12 hours",
  24 to "Every 24 hours",
  48 to "Every 48 hours",
)

internal fun trailerCacheClearLabel(hours: Int): String =
  trailerCacheClearChoices.firstOrNull { it.first == hours }?.second ?: "Every $hours hours"

/** What the trailer cache currently holds, and when it was last thrown away. */
internal fun trailerCacheStatusLabel(sizeBytes: Long, lastClearedAt: Long): String {
  val size = if (sizeBytes <= 0L) "Nothing stored" else formatBytesLabel(sizeBytes)
  if (lastClearedAt <= 0L) return "$size · never cleared"
  val hoursAgo = ((System.currentTimeMillis() - lastClearedAt) / 3_600_000L).toInt()
  val cleared = when {
    hoursAgo <= 0 -> "cleared less than an hour ago"
    hoursAgo == 1 -> "cleared an hour ago"
    hoursAgo < 24 -> "cleared $hoursAgo hours ago"
    hoursAgo < 48 -> "cleared yesterday"
    else -> "cleared ${hoursAgo / 24} days ago"
  }
  return "$size · $cleared"
}

/**
 * What to tell the viewer when premium services turn a source down.
 *
 * Keeps each service's own words — providers explain a dead subscription, a torrent limit and
 * refused content in prose rather than in codes, so the text is the only thing that distinguishes
 * "renew your subscription" from "delete a torrent" from "this one is never going to work".
 * Two at most: the point is to explain, not to list.
 */
private fun debridRejectionNotice(failures: List<net.streamdek.mobile.debrid.DebridFailure>): String? {
  val meaningful = failures.filter {
    it.code != net.streamdek.mobile.debrid.DebridFailureCode.NotConfigured &&
      it.code != net.streamdek.mobile.debrid.DebridFailureCode.Downloading &&
      it.message.isNotBlank()
  }
  if (meaningful.isEmpty()) return null
  val listed = meaningful.take(2).joinToString(" · ") { failure ->
    "${debridProviderLabel(failure.provider)}: ${failure.message.trim().removeSuffix(".").take(90)}"
  }
  return if (meaningful.size > 2) "$listed · and ${meaningful.size - 2} more" else listed
}

/** How long playback waits for the local torrent engine to come up: 250ms x 80 = twenty seconds. */
private const val TORRENT_SERVER_READY_POLL_MS = 250L
private const val TORRENT_SERVER_READY_ATTEMPTS = 80

/**
 * The magnet handed to the local engine and to the premium services.
 *
 * Carries the add-on's own announce list (or the public fallback) rather than the hash alone —
 * see [buildMagnetLink]. A trackerless magnet is why torrent sources found no peers.
 */
private fun buildPeerMagnet(stream: AddonStream, infoHash: String): String =
  buildMagnetLink(infoHash, stream.filename, stream.sources)


/**
 * [color] mixed into white, so a container tint is an opaque colour rather than a translucent one.
 *
 * Material's container roles are painted straight onto a surface and are also used as the parent
 * for other translucent overlays; leaving them at an alpha means whatever sits behind the surface
 * — an ambient backdrop, a scrim — bleeds through a chip that was meant to read as solid.
 */
private fun tintOnWhite(color: Color, amount: Float): Color = Color(
  red = color.red * amount + (1f - amount),
  green = color.green * amount + (1f - amount),
  blue = color.blue * amount + (1f - amount),
)

private data class ThemeAccentPalette(
  val accent: Color,
  val tertiary: Color,
)

/**
 * A preset's accent, for the mode it is being shown in.
 *
 * Two palettes rather than one, because an accent is a foreground colour: `primary` is what
 * Material paints a filled button, a focused text field's border, a checked switch, a spinner and
 * every `TextButton` label with. The dark palette is deliberately pale so it reads against black —
 * and that is exactly what made it disappear in light mode, where the surface behind those same
 * controls is white. Monochrome was the extreme case (a white button on a white card), but every
 * preset lost its buttons and field borders to some degree.
 *
 * The light column is the same hue taken down to something that carries text at ~4.5:1 on white,
 * so `onPrimary` can be white and a filled button reads as a button.
 */
private fun themeAccentPalette(theme: AppThemePreset, darkMode: Boolean = true): ThemeAccentPalette =
  if (darkMode) when (theme) {
    AppThemePreset.Monochrome -> ThemeAccentPalette(accent = Color(0xFFFFFFFF), tertiary = Color(0xFFE5E7EB))
    AppThemePreset.Ocean -> ThemeAccentPalette(accent = Color(0xFF60A5FA), tertiary = Color(0xFF38BDF8))
    AppThemePreset.Emerald -> ThemeAccentPalette(accent = Color(0xFF34D399), tertiary = Color(0xFF10B981))
    AppThemePreset.Amber -> ThemeAccentPalette(accent = Color(0xFFFBBF24), tertiary = Color(0xFFF59E0B))
    AppThemePreset.Crimson -> ThemeAccentPalette(accent = Color(0xFFFB7185), tertiary = Color(0xFFE11D48))
    AppThemePreset.Rose -> ThemeAccentPalette(accent = Color(0xFFF9A8D4), tertiary = Color(0xFFF472B6))
    AppThemePreset.Violet -> ThemeAccentPalette(accent = Color(0xFFC4B5FD), tertiary = Color(0xFFA78BFA))
    AppThemePreset.White -> ThemeAccentPalette(accent = Color(0xFFE2E8F0), tertiary = Color(0xFFCBD5E1))
  } else when (theme) {
    AppThemePreset.Monochrome -> ThemeAccentPalette(accent = Color(0xFF1F2937), tertiary = Color(0xFF4B5563))
    AppThemePreset.Ocean -> ThemeAccentPalette(accent = Color(0xFF1D4ED8), tertiary = Color(0xFF0369A1))
    AppThemePreset.Emerald -> ThemeAccentPalette(accent = Color(0xFF047857), tertiary = Color(0xFF0F766E))
    AppThemePreset.Amber -> ThemeAccentPalette(accent = Color(0xFFB45309), tertiary = Color(0xFF92400E))
    AppThemePreset.Crimson -> ThemeAccentPalette(accent = Color(0xFFBE123C), tertiary = Color(0xFF9F1239))
    AppThemePreset.Rose -> ThemeAccentPalette(accent = Color(0xFFDB2777), tertiary = Color(0xFFBE185D))
    AppThemePreset.Violet -> ThemeAccentPalette(accent = Color(0xFF6D28D9), tertiary = Color(0xFF5B21B6))
    AppThemePreset.White -> ThemeAccentPalette(accent = Color(0xFF334155), tertiary = Color(0xFF475569))
  }

private fun appColorScheme(theme: AppThemePreset, darkMode: Boolean) = themeAccentPalette(theme, darkMode).let { palette ->
  if (darkMode) {
    darkColorScheme(
      primary = palette.accent,
      secondary = palette.accent.copy(alpha = 0.92f),
      tertiary = palette.tertiary,
      background = Color.Black,
      surface = Color(0xFF111111),
      surfaceVariant = Color(0xFF1D1D1D),
      onPrimary = Color(0xFF06243B),
      onBackground = Color(0xFFF5F7FB),
      onSurface = Color(0xFFF5F7FB),
    )
  } else {
    lightColorScheme(
      primary = palette.accent,
      secondary = palette.tertiary,
      tertiary = palette.tertiary,
      background = Color(0xFFF5F4F0),
      surface = Color.White,
      // Not the raw accent at 12%: several of these presets are warm, and Material paints an
      // unselected chip and a text field's own container with this. A near-neutral slate keeps
      // those controls looking like controls rather than like tinted slabs.
      surfaceVariant = Color(0xFFE7E9EE),
      onSurfaceVariant = Color(0xFF334155),
      // The accent is now dark enough to carry white text, which is what a filled button needs.
      // It was black before, against an accent chosen to sit on black — so the button and its
      // label were both near-white and the control vanished into the card behind it.
      onPrimary = Color.White,
      onSecondary = Color.White,
      onTertiary = Color.White,
      primaryContainer = tintOnWhite(palette.accent, 0.14f),
      onPrimaryContainer = palette.accent,
      secondaryContainer = tintOnWhite(palette.tertiary, 0.14f),
      onSecondaryContainer = palette.tertiary,
      outline = Color(0xFF94A3B8),
      outlineVariant = Color(0xFFCBD5E1),
      onBackground = Color(0xFF0F172A),
      onSurface = Color(0xFF0F172A),
    )
  }
}

private class WatchedEpisodeStore(context: Context) {
  private val prefs = context.getSharedPreferences("streamdek_native_watched_episodes", Context.MODE_PRIVATE)

  private fun storageKey(ownerKey: String, showId: String): String = "watched:$ownerKey:$showId"

  fun load(ownerKey: String, showId: String): List<String> {
    val raw = prefs.getString(storageKey(ownerKey, showId), null) ?: return emptyList()
    return runCatching {
      val source = JSONArray(raw)
      buildList {
        for (index in 0 until source.length()) {
          source.optString(index).trim().ifBlank { null }?.let(::add)
        }
      }
    }.getOrDefault(emptyList())
  }

  fun save(ownerKey: String, showId: String, watchedEpisodeIds: List<String>) {
    prefs.edit().putString(storageKey(ownerKey, showId), JSONArray(watchedEpisodeIds.distinct()).toString()).apply()
  }
}

private class WatchedMovieStore(context: Context) {
  private val prefs = context.getSharedPreferences("streamdek_native_watched_movies", Context.MODE_PRIVATE)

  private fun storageKey(ownerKey: String): String = "watched_movies:$ownerKey"

  fun load(ownerKey: String): List<String> {
    val raw = prefs.getString(storageKey(ownerKey), null) ?: return emptyList()
    return runCatching {
      val source = JSONArray(raw)
      buildList {
        for (index in 0 until source.length()) {
          source.optString(index).trim().ifBlank { null }?.let(::add)
        }
      }
    }.getOrDefault(emptyList())
  }

  fun save(ownerKey: String, movieIds: List<String>) {
    prefs.edit().putString(storageKey(ownerKey), JSONArray(movieIds.distinct()).toString()).apply()
  }
}

private class WatchedTitleStore(context: Context) {
  private val prefs = context.getSharedPreferences("streamdek_native_watched_titles", Context.MODE_PRIVATE)
  private fun storageKey(ownerKey: String): String = "watched_titles:$ownerKey"

  fun load(ownerKey: String): Set<String> = runCatching {
    val source = JSONArray(prefs.getString(storageKey(ownerKey), "[]"))
    buildSet { for (index in 0 until source.length()) source.optString(index).takeIf { it.isNotBlank() }?.let(::add) }
  }.getOrDefault(emptySet())

  fun add(ownerKey: String, item: MediaItem) {
    val key = watchedTitleKey(item.type, item.id)
    prefs.edit().putString(storageKey(ownerKey), JSONArray((load(ownerKey) + key).toList()).toString()).apply()
  }

  fun addAll(ownerKey: String, items: List<MediaItem>) {
    if (items.isEmpty()) return
    val keys = items.map { watchedTitleKey(it.type, it.id) }
    prefs.edit().putString(storageKey(ownerKey), JSONArray((load(ownerKey) + keys).toList()).toString()).apply()
  }
}

private data class PlaybackMemoryEntry(
  val mediaId: String,
  val mediaType: String,
  val title: String,
  val year: String? = null,
  val poster: String? = null,
  val backdrop: String? = null,
  val seasonNumber: Int? = null,
  val episodeNumber: Int? = null,
  val progressPercent: Double = 0.0,
  val positionSeconds: Double? = null,
  val durationSeconds: Int? = null,
  val stream: AddonStream? = null,
  val isLive: Boolean = false,
  val updatedAt: Long = System.currentTimeMillis(),
  val lastDevice: String? = null,
  val lastPlatform: String? = null,
  /**
   * When this entry last reached the account, or null if it never has.
   *
   * It is what makes "the server does not have this" readable. A row missing from the server is
   * either one that was removed on another device or one this phone has never managed to send --
   * opposite meanings, and deleting the second kind would throw away a position recorded on a
   * train. Only an entry that is known to have been up there is treated as deliberately gone.
   */
  val syncedAt: Long? = null,
)

private fun resumePositionLabel(entry: PlaybackMemoryEntry): String? {
  val durationSeconds = entry.durationSeconds ?: return null
  if (durationSeconds <= 0) return null
  val positionSeconds = entry.positionSeconds?.toInt()
    ?: (durationSeconds * entry.progressPercent / 100.0).toInt()
  return "%02d:%02d".format(positionSeconds / 3600, (positionSeconds % 3600) / 60)
}

private class PlaybackResumeStore(context: Context) {
  private val prefs = context.getSharedPreferences("streamdek_native_playback_resume", Context.MODE_PRIVATE)

  private fun storageKey(ownerKey: String): String = "resume:$ownerKey"

  fun loadAll(ownerKey: String): List<PlaybackMemoryEntry> {
    val raw = prefs.getString(storageKey(ownerKey), null) ?: return emptyList()
    return runCatching {
      val source = JSONArray(raw)
      buildList {
        for (index in 0 until source.length()) {
          parsePlaybackMemoryEntry(source.optJSONObject(index) ?: continue)?.let(::add)
        }
      }.sortedByDescending { it.updatedAt }
    }.getOrDefault(emptyList())
  }

  /**
   * @param touch stamps the entry with now. False when the entry came from the account, whose own
   *   timestamp is the one the newest-wins merge has to compare against -- overwriting it with the
   *   moment it happened to be downloaded made every pulled row look newer than the server's copy.
   */
  fun save(ownerKey: String, entry: PlaybackMemoryEntry, touch: Boolean = true) {
    val updated = loadAll(ownerKey)
      .filterNot { playbackMemoryKey(it.mediaId, it.mediaType, it.seasonNumber, it.episodeNumber) == playbackMemoryKey(entry.mediaId, entry.mediaType, entry.seasonNumber, entry.episodeNumber) }
      .toMutableList()
    updated.add(0, if (touch) entry.copy(updatedAt = System.currentTimeMillis()) else entry)
    persist(ownerKey, updated.take(80))
  }

  /** Records that the account now holds this entry, so its later absence can be read as a removal. */
  fun markSynced(ownerKey: String, mediaId: String, mediaType: String, seasonNumber: Int?, episodeNumber: Int?, stamp: Long) {
    val target = playbackMemoryKey(mediaId, mediaType, seasonNumber, episodeNumber)
    val entries = loadAll(ownerKey)
    if (entries.none { playbackMemoryKey(it.mediaId, it.mediaType, it.seasonNumber, it.episodeNumber) == target }) return
    persist(
      ownerKey,
      entries.map { entry ->
        if (playbackMemoryKey(entry.mediaId, entry.mediaType, entry.seasonNumber, entry.episodeNumber) == target) {
          entry.copy(syncedAt = stamp)
        } else {
          entry
        }
      },
    )
  }

  fun removeTitle(ownerKey: String, mediaId: String, mediaType: String) {
    val targetType = normalizedMediaType(mediaType)
    persist(ownerKey, loadAll(ownerKey).filterNot { it.mediaId == mediaId && normalizedMediaType(it.mediaType) == targetType })
  }
  fun remove(ownerKey: String, mediaId: String, mediaType: String, seasonNumber: Int?, episodeNumber: Int?) {
    val key = playbackMemoryKey(mediaId, mediaType, seasonNumber, episodeNumber)
    persist(ownerKey, loadAll(ownerKey).filterNot { playbackMemoryKey(it.mediaId, it.mediaType, it.seasonNumber, it.episodeNumber) == key })
  }

  /**
   * Drops every resume position that Continue Watching can show. Live entries are kept: they hold
   * the remembered source for a channel (see rememberLiveSource) and never appear in Continue
   * Watching anyway, so clearing that list should not forget which live source last worked.
   */
  fun clearResumable(ownerKey: String) {
    persist(ownerKey, loadAll(ownerKey).filter { it.isLive })
  }

  private fun persist(ownerKey: String, entries: List<PlaybackMemoryEntry>) {
    prefs.edit().putString(storageKey(ownerKey), JSONArray(entries.map(::playbackMemoryToJson)).toString()).commit()
  }
}

private fun playbackMemoryKey(mediaId: String, mediaType: String, seasonNumber: Int?, episodeNumber: Int?): String =
  listOf(mediaType, mediaId, seasonNumber ?: -1, episodeNumber ?: -1).joinToString(":")

private fun playbackMemoryToJson(entry: PlaybackMemoryEntry): JSONObject = JSONObject()
  .put("mediaId", entry.mediaId)
  .put("mediaType", entry.mediaType)
  .put("title", entry.title)
  .put("year", entry.year)
  .put("poster", entry.poster)
  .put("backdrop", entry.backdrop)
  .put("seasonNumber", entry.seasonNumber)
  .put("episodeNumber", entry.episodeNumber)
  .put("progressPercent", entry.progressPercent)
  .put("positionSeconds", entry.positionSeconds)
  .put("durationSeconds", entry.durationSeconds)
  .put("isLive", entry.isLive)
  .put("updatedAt", entry.updatedAt)
  .put("lastDevice", entry.lastDevice)
  .put("lastPlatform", entry.lastPlatform)
  .put("syncedAt", entry.syncedAt)
  .put("stream", entry.stream?.let(::addonStreamToJson))

/**
 * A stored string that may be absent, or may be the word "null".
 *
 * Entries written before the pull parser was fixed hold the literal "null" where artwork should
 * be. Reading them through this repairs those rows in place the next time they are saved, rather
 * than leaving a set of permanently blank cards behind.
 */
private fun JSONObject.storedStringOrNull(name: String): String? =
  if (isNull(name)) null else optString(name).trim().takeIf { it.isNotEmpty() && it != "null" && it != "undefined" }

private fun parsePlaybackMemoryEntry(json: JSONObject): PlaybackMemoryEntry? {
  val mediaId = json.optString("mediaId").trim()
  val mediaType = json.optString("mediaType").trim()
  val title = json.optString("title").trim()
  if (mediaId.isBlank() || mediaType.isBlank() || title.isBlank()) return null
  return PlaybackMemoryEntry(
    mediaId = mediaId,
    mediaType = mediaType,
    title = title,
    year = json.storedStringOrNull("year"),
    poster = json.storedStringOrNull("poster"),
    backdrop = json.storedStringOrNull("backdrop"),
    seasonNumber = json.optInt("seasonNumber").takeIf { it > 0 },
    episodeNumber = json.optInt("episodeNumber").takeIf { it > 0 },
    progressPercent = json.optDouble("progressPercent").takeIf { it.isFinite() }?.coerceIn(0.0, 100.0) ?: 0.0,
    positionSeconds = json.optDouble("positionSeconds").takeIf { json.has("positionSeconds") && it.isFinite() && it >= 0.0 },
    durationSeconds = json.optInt("durationSeconds").takeIf { it > 0 },
    isLive = json.optBoolean("isLive", false),
    stream = json.optJSONObject("stream")?.let(::parseAddonStreamJson),
    updatedAt = json.optLong("updatedAt").takeIf { it > 0L } ?: 0L,
    lastDevice = json.storedStringOrNull("lastDevice"),
    lastPlatform = json.storedStringOrNull("lastPlatform"),
    // Absent on entries written before the field existed, which is the honest answer for them:
    // unknown, so leave them alone.
    syncedAt = json.optLong("syncedAt").takeIf { it > 0L },
  )
}

private fun addonStreamToJson(stream: AddonStream): JSONObject = JSONObject()
  .put("addonId", stream.addonId)
  .put("addonName", stream.addonName)
  .put("source", stream.source)
  .put("name", stream.name)
  .put("title", stream.title)
  .put("description", stream.description)
  .put("url", stream.url)
  .put("infoHash", stream.infoHash)
  .put("fileIdx", stream.fileIdx)
  .put("filename", stream.filename)
  .put("quality", stream.quality)
  .put("size", stream.size)
  .put("cachedBy", JSONArray(stream.cachedBy))
  .put("bingeGroup", stream.bingeGroup)
  .put("requestHeaders", JSONObject(stream.requestHeaders))

private fun parseAddonStreamJson(json: JSONObject): AddonStream = AddonStream(
  addonId = json.optString("addonId"),
  addonName = json.optString("addonName"),
  name = json.optString("name").ifBlank { null },
  title = json.optString("title").ifBlank { null },
  description = json.optString("description").ifBlank { null },
  url = json.optString("url").ifBlank { null },
  infoHash = json.optString("infoHash").ifBlank { null },
  fileIdx = json.optInt("fileIdx").takeIf { it >= 0 },
  filename = json.optString("filename").ifBlank { null },
  quality = json.optString("quality").ifBlank { null },
  size = json.optString("size").ifBlank { null },
  bingeGroup = json.optString("bingeGroup").ifBlank { null },
  requestHeaders = json.optJSONObject("requestHeaders")?.toStringMap().orEmpty(),
  source = json.optString("source").ifBlank { null },
  cachedBy = json.optJSONArray("cachedBy")?.let { source ->
    buildList {
      for (index in 0 until source.length()) {
        source.optString(index).trim().ifBlank { null }?.let(::add)
      }
    }
  } ?: emptyList(),
)

private fun JSONObject.toStringMap(): Map<String, String> = buildMap {
  keys().forEach { key -> optString(key).trim().takeIf { it.isNotBlank() }?.let { put(key, it) } }
}
private fun normalizedMediaType(type: String): String = when (type.trim().lowercase()) {
  "tv", "series", "show" -> "tv"
  else -> type.trim().lowercase()
}

internal fun progressCameFromAnotherPlatform(lastPlatform: String?, destination: String): Boolean {
  val origin = lastPlatform?.trim()?.lowercase().orEmpty()
  if (origin.isBlank()) return false
  return when (destination.trim().lowercase()) {
    "mobile" -> origin !in setOf("mobile", "android", "android-mobile")
    "tv" -> origin !in setOf("tv", "androidtv", "firetv")
    else -> origin != destination.trim().lowercase()
  }
}

/**
 * Keeps the Stremio resource type used by the catalog that produced a card.
 *
 * UI models normalize `series` to `tv`, but add-on routes do not: metadata add-ons such as
 * AIOMetadata publish `/meta/series/...` and answer `/meta/tv/...` with no item. Prefer the
 * original catalog type, falling back to Stremio's canonical `series` spelling for TV cards.
 */
internal fun addonMetaRequestType(type: String, sourceCatalogType: String?): String =
  sourceCatalogType?.trim()?.lowercase()?.takeIf { it.isNotBlank() }
    ?: if (normalizedMediaType(type) == "tv") "series" else type.trim().lowercase()

/** Watchlist/library identity. Types reach us as "tv", "series" or "show" depending on the
 *  source (Trakt, add-on catalogues, TMDB), so membership has to compare the normalized form —
 *  otherwise the same title looks like two different entries and toggles never line up. */
private fun mediaKey(type: String, id: String): String = "${normalizedMediaType(type)}:$id"

/**
 * Whether the add-on publishes a Stremio `meta` resource covering this content type — i.e. it can
 * describe its own catalog items rather than leaving them to be looked up by id on TMDB.
 *
 * The manifest's per-resource type lists are flattened to names when it is parsed, so the type
 * test falls back to `manifest.types`; an add-on that declares no types is treated as covering
 * everything, matching Stremio. The backend repeats this check precisely before it picks an
 * add-on to answer with.
 */
/**
 * Whether an add-on's `meta` answer actually describes the item that was asked for.
 *
 * Advertising a `meta` resource is not the same as being able to serve one. AIOStreams, for one,
 * answers every `/meta` call with a placeholder whose id encodes the failure
 * ("aiostreamserror.%7B…%7D") and whose name is the error text. Taken at face value that replaced
 * the title on screen with an error message and then sent the stream add-ons an id nothing has
 * ever heard of — so the page came up empty in both halves.
 *
 * The test is about substance rather than any one add-on's error format: a usable answer either
 * keeps an id that can still drive a stream lookup (the id that was requested, or an IMDb id) or
 * brings episodes with it. A local bridge is exempt — swapping the browsing id for a different
 * canonical one is exactly what it exists to do.
 */
internal fun isUsableAddonMeta(meta: LocalAddonMeta, requestedId: String, isLocalAddon: Boolean): Boolean {
  if (meta.title.isBlank()) return false
  if (isLocalAddon) return meta.id.isNotBlank()
  if (!meta.imdbId.isNullOrBlank()) return true
  if (meta.episodes.isNotEmpty()) return true
  return meta.id.equals(requestedId, ignoreCase = true)
}

private fun AddonManifest.providesMetaFor(type: String): Boolean {
  if (resources.none { it.trim().equals("meta", ignoreCase = true) }) return false
  if (types.isEmpty()) return true
  val nativeType = if (type.trim().lowercase() in setOf("tv", "show", "series")) "series" else type.trim().lowercase()
  return types.any { declared ->
    val value = declared.trim().lowercase()
    value == nativeType || (nativeType == "series" && value == "tv")
  }
}

/**
 * How long a freshly opened detail page gets to itself before the heavy background work starts.
 *
 * Sources go first because they are what the viewer is waiting for; the hero trailer follows,
 * because it is decoration and it brings a video pipeline up with it. Both are short enough to be
 * imperceptible if the page has already settled, and long enough to stop the two of them
 * competing with the page's own artwork and layout.
 */
private const val DETAIL_SOURCES_DELAY_MS = 450L

/** Measured from the page having content, not from navigation — see the gate in MediaDetailScreen. */
/**
 * How long a title page is left alone before its trailer starts, and the range it is held to.
 *
 * The same numbers the television and the web portal use, because it is the same synced setting.
 * The ceiling is a product decision: past about five seconds the viewer has finished with the page
 * and the trailer lands as an interruption rather than as the next thing.
 */
const val DEFAULT_TRAILER_DELAY_SECONDS = 3
/** How often a foregrounded app asks whether the plugin document moved somewhere else. */
private const val PLUGIN_WATCH_INTERVAL_MS = 15_000L

const val MAX_TRAILER_DELAY_SECONDS = 5

private fun trailerDelayLabel(seconds: Int): String = when (seconds) {
  0 -> "Immediately"
  1 -> "1 second"
  else -> "$seconds seconds"
}

/** Read back through the same labels rather than by parsing them, so the two cannot drift apart. */
private fun trailerDelaySecondsFrom(label: String): Int =
  (0..MAX_TRAILER_DELAY_SECONDS).firstOrNull { trailerDelayLabel(it) == label } ?: DEFAULT_TRAILER_DELAY_SECONDS

/** TMDB artwork recovered for a tracking-service row that arrived without any. */
private data class TrackingArtwork(val poster: String?, val backdrop: String?)
private fun List<MediaItem>.containsMedia(item: MediaItem): Boolean =
  any { it.id == item.id && normalizedMediaType(it.type) == normalizedMediaType(item.type) }

private fun watchedTitleKey(type: String, id: String): String = "${normalizedMediaType(type)}:$id"
private fun watchedEpisodeKey(showId: String, seasonNumber: Int, episodeNumber: Int): String =
  "episode:$showId:$seasonNumber:$episodeNumber"

internal fun completedEpisodeWatchedIds(existing: List<String>, watchedKey: String): List<String> =
  if (watchedKey in existing) existing else existing + watchedKey

private fun watchedOwnerKey(session: AuthSession?, activeProfileId: String?): String {
  val userId = session?.user?.uid
  return when {
    userId.isNullOrBlank() -> activeProfileId?.let { "guest:$it" } ?: GUEST_OWNER_KEY
    activeProfileId.isNullOrBlank() -> userId
    else -> "$userId:$activeProfileId"
  }
}
private const val GUEST_OWNER_KEY = "guest"

private fun serializeHomeCatalogRows(rows: List<HomeCatalogRow>): String = JSONArray().apply {
  rows.forEach { row ->
    put(JSONObject().put("id", row.id).put("enabled", row.enabled))
  }
}.toString()

private fun parseHomeCatalogRows(raw: String?): List<HomeCatalogRow> {
  if (raw.isNullOrBlank()) return emptyList()
  return runCatching {
    val source = JSONArray(raw)
    buildList {
      for (index in 0 until source.length()) {
        val item = source.optJSONObject(index) ?: continue
        val id = item.optString("id").trim()
        if (id.isEmpty()) continue
        add(HomeCatalogRow(id = id, title = id, subtitle = "", builtin = false, enabled = item.optBoolean("enabled", true)))
      }
    }
  }.getOrDefault(emptyList())
}

private fun isBuiltinHomeCatalog(id: String): Boolean = !id.startsWith("addon:")

/**
 * The default catalogs, as the app believes them to be before the backend's registry arrives.
 *
 * The backend owns the real list — this is what the row-management screen and the home layout
 * fall back to when the manifest request has not landed yet or failed, so a viewer never sees an
 * empty "Home rows" screen. Ids and order match the server registry; titles are only a fallback,
 * since the manifest's titles win the moment it loads.
 */
internal val fallbackCatalogDefinitions: List<CatalogDefinition> = listOf(
  Triple("trending_movies", "Trending Movies", "movie"),
  Triple("trending_series", "Trending Series", "tv"),
  Triple("new_movies", "New Movies", "movie"),
  Triple("in_theatres", "In Theatres", "movie"),
  Triple("new_series", "New Series", "tv"),
  Triple("tmdb_airing_today", "TMDB Airing Today", "tv"),
  Triple("streaming_networks", "Streaming Networks", "network"),
  Triple("tmdb_popular_movies", "TMDB Popular Movies", "movie"),
  Triple("tmdb_popular_series", "TMDB Popular Series", "tv"),
  Triple("top_100_movies", "Top 100 Movies", "movie"),
  Triple("top_100_series", "Top 100 Series", "tv"),
  Triple("acclaimed_this_year", "Critically Acclaimed", "movie"),
  Triple("action_movies", "Action & Adventure", "movie"),
  Triple("comedy_movies", "Comedy Movies", "movie"),
  Triple("crime_series", "Crime Series", "tv"),
  Triple("horror_movies", "Horror Movies", "movie"),
  Triple("scifi_movies", "Sci-Fi & Fantasy", "movie"),
  Triple("animated_movies", "Animated Movies", "movie"),
  Triple("animated_series", "Animated Series", "tv"),
  Triple("anime_series", "Anime", "tv"),
  Triple("family_movies", "Family Movies", "movie"),
  Triple("family_series", "Family Series", "tv"),
  Triple("studio_a24", "A24", "movie"),
  Triple("studio_blumhouse", "Blumhouse", "movie"),
  Triple("studio_20th_century", "20th Century", "movie"),
  Triple("documentary_movies", "Documentaries", "movie"),
  Triple("hidden_gems_movies", "Hidden Gems", "movie"),
  Triple("classic_movies", "Timeless Classics", "movie"),
).map { (id, title, mediaType) ->
  CatalogDefinition(
    id = id,
    title = title,
    mediaType = mediaType,
    group = "default",
    previewLimit = 20,
    maxItems = if (id.startsWith("top_100")) 100 else null,
    paginated = mediaType != "network",
  )
}

/** The five rows StreamDek shipped before the catalog registry, used to spot an old saved layout. */
private val legacyDefaultCatalogIds = setOf(
  "new_movies",
  "new_series",
  "streaming_networks",
  "trending_movies",
  "trending_series",
)

/**
 * StreamDek rows that Home assembles itself rather than fetching from the catalog registry.
 *
 * They are listed as ordinary built-in rows so they can be switched on and off beside the rest,
 * under the same master switch -- but they are not catalog ids, so they must never be asked for
 * from `/tmdb/home`. See [streamDekFeatureRowIds].
 */
internal val streamDekFeatureRows: List<HomeCatalogRow> = listOf(
  HomeCatalogRow("recommended", "Recommended For You", "Provided by StreamDek", builtin = true),
  HomeCatalogRow("trending", "Trending On Trakt", "Provided by StreamDek", builtin = true),
  HomeCatalogRow("watchlist", "Watchlist", "Provided by StreamDek", builtin = true),
)

internal val streamDekFeatureRowIds: Set<String> = streamDekFeatureRows.mapTo(mutableSetOf()) { it.id }

internal fun builtinHomeCatalogCandidates(definitions: List<CatalogDefinition>): List<HomeCatalogRow> =
  definitions.ifEmpty { fallbackCatalogDefinitions }.map { definition ->
    HomeCatalogRow(definition.id, definition.title, "Provided by StreamDek", builtin = true)
  } + streamDekFeatureRows

private fun addonHomeCatalogTitle(addonName: String, catalogName: String, type: String, needsDifferentiator: Boolean): String {
  val cleaned = cleanAddonCatalogLabel(catalogName, addonName)
  val base = cleaned.ifBlank { cleanAddonCatalogLabel(addonName).ifBlank { addonName } }
  return if (!needsDifferentiator) base else "$base ${
    when (type) {
      "movie" -> "Movies"
      "series", "show" -> "Series"
      "tv", "channel", "live", "iptv" -> "Live"
      "sport", "sports", "events" -> "Sports"
      else -> "Series"
    }
  }"
}

internal fun addonHomeCatalogCandidates(addons: List<InstalledAddon>): List<HomeCatalogRow> {
  val enabledAddons = addons.filter { it.enabled }.sortedBy { it.position }
  val duplicateCatalogNames = enabledAddons
    .flatMap { addon -> addon.manifest.catalogs.map { catalog -> catalog.name.trim().lowercase() to catalog.type.trim().lowercase() } }
    .filter { (_, type) -> type in setOf("movie", "series", "tv", "sport", "sports", "channel", "live", "other") }
    .groupBy({ it.first }, { it.second })
    .mapValues { (_, values) -> values.toSet().size > 1 }
  return enabledAddons.flatMap { addon ->
    addon.manifest.catalogs.mapIndexedNotNull { index, catalog ->
      val rawType = catalog.type.trim().lowercase()
      val mappedType = when (rawType) {
        "movie" -> "movie"
        "series", "tv", "sport", "sports", "channel", "live", "other" -> "tv"
        else -> null
      } ?: return@mapIndexedNotNull null
      val title = addonHomeCatalogTitle(addon.manifest.name, catalog.name.ifBlank { catalog.id }, rawType, duplicateCatalogNames[catalog.name.trim().lowercase()] == true)
      HomeCatalogRow(
        id = "addon:${addon.id}:$rawType:${catalog.id}:$index",
        title = title,
        subtitle = "From ${addon.manifest.name}",
        builtin = false,
      )
    }
  }
}

/**
 * The part of a row id that names the catalogue rather than where it sat in a manifest.
 *
 * Add-on row ids are `addon:<addonId>:<type>:<catalogId>:<index>`, and that trailing index is the
 * catalogue's position in the add-on's manifest. It moves whenever the add-on reorders, adds or
 * removes a catalogue — and when it moved, every saved row stopped matching its candidate and the
 * viewer's whole layout was rebuilt from defaults. Matching on everything but the index survives
 * that, and the row quietly adopts the new id.
 */
internal fun homeCatalogRowMatchKey(id: String): String {
  if (!id.startsWith("addon:")) return id
  val parts = id.split(":")
  return if (parts.size >= 5) parts.take(4).joinToString(":") else id
}

/** The add-on a saved row came from, or null when the row is a built-in one. */
internal fun homeCatalogRowAddonId(id: String): String? =
  if (id.startsWith("addon:")) id.split(":").getOrNull(1)?.takeIf { it.isNotBlank() } else null

private fun isLiveHomeCatalogRowId(id: String): Boolean {
  if (!id.startsWith("addon:")) return false
  val rawType = id.split(":").getOrNull(2)?.lowercase().orEmpty()
  return rawType in setOf("tv", "channel", "live", "iptv", "sport", "sports", "events")
}

internal fun mergeHomeCatalogRows(
  existing: List<HomeCatalogRow>,
  addons: List<InstalledAddon>,
  definitions: List<CatalogDefinition> = fallbackCatalogDefinitions,
): List<HomeCatalogRow> {
  val builtins = builtinHomeCatalogCandidates(definitions)
  val candidates = (builtins + addonHomeCatalogCandidates(addons)).associateBy { it.id }
  val candidatesByMatchKey = candidates.values.associateBy { homeCatalogRowMatchKey(it.id) }
  // Which sources have actually reported in. An add-on list that has not loaded yet says nothing
  // about whether a catalogue still exists, and neither does an empty registry.
  val liveAddonIds = addons.filter { it.enabled }.map { it.id }.toSet()
  val registryKnown = definitions.isNotEmpty()

  /**
   * The candidate a saved row now corresponds to, the row itself when its source has not reported
   * in, or null when the source is present and has genuinely dropped it.
   *
   * This used to be a plain `candidates[row.id]` lookup, so a row with no candidate was forgotten.
   * On a cold start the home load runs before the add-on list arrives, which meant every add-on row
   * was dropped from the layout and immediately saved that way -- and when the add-ons did land a
   * moment later, all of them looked new and came back switched on, in registry order. A viewer who
   * had turned nineteen of seventy rows on found all seventy on again after every restart, however
   * many times they set it.
   */
  fun resolve(row: HomeCatalogRow): HomeCatalogRow? {
    val candidate = candidates[row.id] ?: candidatesByMatchKey[homeCatalogRowMatchKey(row.id)]
    if (candidate != null) return candidate.copy(enabled = row.enabled)
    val addonId = homeCatalogRowAddonId(row.id)
    return when {
      // The add-on is installed and switched on, and no longer offers this catalogue. Gone.
      addonId != null && addonId in liveAddonIds -> null
      // The add-on has not loaded, or is switched off. Keep the row and its switch: the viewer's
      // arrangement outlives a list that is merely absent.
      addonId != null -> row
      // Same reasoning for the built-in registry.
      registryKnown -> null
      else -> row
    }
  }
  // A layout saved before the catalog registry existed knows nothing but the original five rows,
  // so honouring its order would bury twenty-five new rows underneath them. Those five carried no
  // deliberate arrangement worth keeping — but a viewer who switched one off meant it, and one who
  // lifted an add-on row above them meant that too, so the registry order is adopted underneath
  // whatever the viewer put on top, and the off switches are carried across.
  val savedBuiltinIds = existing.filter { isBuiltinHomeCatalog(it.id) }.map { it.id }
  val isLegacyLayout = savedBuiltinIds.isNotEmpty() && savedBuiltinIds.all { it in legacyDefaultCatalogIds }
  val persisted = if (isLegacyLayout) {
    val disabled = existing.filterNot { it.enabled }.map { it.id }.toSet()
    val addonRows = existing.filterNot { isBuiltinHomeCatalog(it.id) }.mapNotNull(::resolve)
    val pinnedToTop = existing.indexOfFirst { isBuiltinHomeCatalog(it.id) }.let { firstBuiltin ->
      existing.take(firstBuiltin).count { !isBuiltinHomeCatalog(it.id) }
    }
    addonRows.take(pinnedToTop) +
      builtins.map { candidate -> candidate.copy(enabled = candidate.id !in disabled) } +
      addonRows.drop(pinnedToTop)
  } else {
    existing.mapNotNull(::resolve)
  }

  // Two saved rows can resolve onto one candidate when an add-on's manifest reorders, and a
  // repeated id is a crash in a lazy list rather than a cosmetic duplicate.
  val merged = persisted.distinctBy { it.id }.toMutableList()
  val builtinOrder = builtins.withIndex().associate { (index, row) -> row.id to index }
  candidates.values.forEach { candidate ->
    if (merged.any { it.id == candidate.id }) return@forEach
    val insertAt = when {
      // New live TV rows default to sitting just below Streaming Networks.
      // Users can still re-arrange them from the Home rows settings page —
      // persisted arrangements above always win.
      isLiveHomeCatalogRowId(candidate.id) -> {
        var index = merged.indexOfFirst { it.id == "streaming_networks" } + 1
        if (index <= 0) {
          merged.size
        } else {
          while (index < merged.size && isLiveHomeCatalogRowId(merged[index].id)) index++
          index
        }
      }
      // A default row added by a later backend deploy lands beside its registry neighbours rather
      // than at the bottom, so the intended discovery order survives without disturbing rows the
      // viewer has already moved: directly after the last row the registry puts ahead of it, or
      // else in front of the first row the registry puts behind it.
      builtinOrder.containsKey(candidate.id) -> {
        val position = builtinOrder.getValue(candidate.id)
        val after = merged.withIndex()
          .filter { (_, row) -> builtinOrder[row.id]?.let { it < position } == true }
          .maxByOrNull { (_, row) -> builtinOrder.getValue(row.id) }
          ?.index
        if (after != null) {
          after + 1
        } else {
          merged.indexOfFirst { row -> builtinOrder[row.id]?.let { it > position } == true }
            .takeIf { it >= 0 } ?: merged.size
        }
      }
      else -> merged.size
    }
    merged.add(insertAt, candidate)
  }
  return if (merged.isEmpty()) candidates.values.toList() else merged
}

internal fun applyHomeCatalogLayout(sections: List<MediaSection>, rows: List<HomeCatalogRow>, defaultBuiltinsEnabled: Boolean): List<MediaSection> {
  val sectionMap = sections.associateBy { it.id }
  return rows.mapNotNull { row ->
    if (!row.enabled) return@mapNotNull null
    if (row.builtin && !defaultBuiltinsEnabled) return@mapNotNull null
    sectionMap[row.id]
  }
}

/** Provider-advertised catalogs worth fetching for the spotlight, independent of row visibility. */
internal fun heroCatalogIds(definitions: List<CatalogDefinition>, limit: Int = 6): List<String> {
  if (definitions.isEmpty()) {
    // Compatibility with a backend predating the catalog registry. These are the legacy provider
    // endpoints fetchHomeSections already knows how to resolve, and none implies a visible row.
    return listOf("new_movies", "new_series", "trending_movies", "trending_series").take(limit.coerceAtLeast(1))
  }
  fun rank(definition: CatalogDefinition): Int {
    val identity = "${definition.id} ${definition.title} ${definition.group}".lowercase()
    return when {
      "recommend" in identity -> 0
      "trending" in identity -> 1
      "popular" in identity -> 2
      "new release" in identity || "new_release" in identity || "recent" in identity -> 3
      "top rated" in identity || "top_rated" in identity -> 4
      "theatre" in identity || "cinema" in identity -> 5
      else -> 10
    }
  }
  fun isEligible(definition: CatalogDefinition): Boolean {
    if (!definition.mediaType.equals("movie", true) &&
      !definition.mediaType.equals("tv", true) &&
      !definition.mediaType.equals("series", true)
    ) return false
    val identity = "${definition.id} ${definition.title} ${definition.group}".lowercase()
    return listOf("streaming_network", "streaming network", "live tv", "live_tv", "live-tv", "iptv", "channel").none { it in identity }
  }
  return definitions
    .filter(::isEligible)
    .withIndex()
    .sortedWith(compareBy<IndexedValue<CatalogDefinition>>({ rank(it.value) }, { it.index }))
    .map { it.value.id }
    .distinct()
    .take(limit.coerceAtLeast(1))
}

private fun normalizeFusionBadgeSource(json: JSONObject, url: String): FusionBadgeSource {
  val payloadGroups = json.optJSONArray("groups") ?: JSONArray()
  val payloadFilters = json.optJSONArray("filters") ?: json.optJSONArray("__array") ?: json.optJSONArray("badges") ?: JSONArray()
  val groups = mutableListOf<FusionBadgeGroup>()
  val knownGroupIds = linkedSetOf<String>()
  for (index in 0 until payloadGroups.length()) {
    val group = payloadGroups.optJSONObject(index) ?: continue
    val id = group.optString("id").ifBlank { "group-$index" }
    val name = group.optString("name").ifBlank { group.optString("label").ifBlank { "Group ${index + 1}" } }
    if (id.isNotBlank() && name.isNotBlank()) {
      groups += FusionBadgeGroup(id, name)
      knownGroupIds += id
    }
  }
  val filters = buildList {
    for (index in 0 until payloadFilters.length()) {
      val filter = payloadFilters.optJSONObject(index) ?: continue
      val groupId = filter.optString("groupId").ifBlank { filter.optString("group").ifBlank { filter.optString("category") } }
      val imageUrl = filter.optString("imageURL").ifBlank { filter.optString("imageUrl").ifBlank { filter.optString("image").ifBlank { filter.optString("url") } } }
      val pattern = filter.optString("pattern").ifBlank { filter.optString("regex") }
      val name = filter.optString("name").ifBlank { filter.optString("label").ifBlank { "Badge ${index + 1}" } }
      if (groupId.isBlank() || imageUrl.isBlank() || pattern.isBlank() || name.isBlank()) continue
      if (knownGroupIds.add(groupId)) groups += FusionBadgeGroup(groupId, groupId)
      add(
        FusionBadgeFilter(
          id = filter.optString("id").ifBlank { "$groupId-$index" },
          groupId = groupId,
          name = name,
          pattern = pattern,
          imageUrl = imageUrl,
          isEnabled = if (filter.has("isEnabled")) filter.optBoolean("isEnabled", true) else true,
        )
      )
    }
  }
  if (filters.isEmpty()) error("This URL does not contain any Fusion badge filters")
  return FusionBadgeSource(url = url, groups = groups, filters = filters)
}

private fun fusionStreamSearchText(stream: AddonStream): String = listOfNotNull(
  stream.name,
  stream.title,
  stream.description,
  stream.filename,
  stream.quality,
).joinToString(" ").take(700)

private val fusionRegexCache = object : LinkedHashMap<String, Regex?>(128, 0.75f, true) {
  override fun removeEldestEntry(eldest: MutableMap.MutableEntry<String, Regex?>): Boolean = size > 128
}

@Synchronized
private fun fusionRegex(pattern: String): Regex? {
  if (fusionRegexCache.containsKey(pattern)) return fusionRegexCache[pattern]
  val compiled = runCatching {
    if (pattern.startsWith("(?i)")) Regex(pattern.drop(4), RegexOption.IGNORE_CASE) else Regex(pattern, RegexOption.IGNORE_CASE)
  }.getOrNull()
  fusionRegexCache[pattern] = compiled
  return compiled
}

private fun matchFusionBadgeFilters(stream: AddonStream, sources: List<FusionBadgeSource>): List<FusionBadgeFilter> {
  val text = fusionStreamSearchText(stream)
  if (text.isBlank() || sources.isEmpty()) return emptyList()
  val seen = linkedSetOf<String>()
  return buildList {
    sources.forEach { source ->
      source.filters.forEach { filter ->
        if (!filter.isEnabled) return@forEach
        val key = filter.imageUrl.ifBlank { "${filter.groupId}:${filter.id}" }
        if (key in seen) return@forEach
        val regex = fusionRegex(filter.pattern) ?: return@forEach
        val matched = runCatching { regex.containsMatchIn(text) }.getOrDefault(false)
        if (!matched) return@forEach
        seen += key
        add(filter)
      }
    }
  }
}

/**
 * Badge matches, kept for the session.
 *
 * Matching runs every enabled filter's regex against a stream's text — with a full badge set that
 * is dozens of patterns per stream, and forty streams on screen. Results are keyed on the stream's
 * own text rather than the stream object, so the many results that share a release name resolve to
 * one entry, and reopening a title reuses what was already worked out. The badge configuration is
 * part of the key, so changing or switching a badge source invalidates naturally rather than
 * needing to be cleared.
 */
private const val FUSION_BADGE_CACHE_LIMIT = 600
private val fusionBadgeMatchCache =
  object : LinkedHashMap<String, List<FusionBadgeFilter>>(0, 0.75f, true) {
    override fun removeEldestEntry(eldest: Map.Entry<String, List<FusionBadgeFilter>>): Boolean =
      size > FUSION_BADGE_CACHE_LIMIT
  }

private fun cachedFusionBadges(
  stream: AddonStream,
  sources: List<FusionBadgeSource>,
  configKey: String,
): List<FusionBadgeFilter> {
  val key = configKey + "␀" + fusionStreamSearchText(stream)
  synchronized(fusionBadgeMatchCache) { fusionBadgeMatchCache[key] }?.let { return it }
  val matched = matchFusionBadgeFilters(stream, sources)
  synchronized(fusionBadgeMatchCache) { fusionBadgeMatchCache[key] = matched }
  return matched
}

private fun activeFusionSources(uiState: AppUiState): List<FusionBadgeSource> {
  val active = uiState.activeFusionBadgeUrl?.takeIf { it in uiState.fusionBadgeUrls }
  val urls = if (active != null) listOf(active) else uiState.fusionBadgeUrls
  return urls.mapNotNull { uiState.fusionBadgeSources[it]?.source }
}

private fun fusionBadgeSourceSummary(uiState: AppUiState): String {
  val loaded = uiState.fusionBadgeUrls.mapNotNull { uiState.fusionBadgeSources[it]?.source }
  val active = uiState.activeFusionBadgeUrl ?: uiState.fusionBadgeUrls.firstOrNull().orEmpty()
  val activeSource = uiState.fusionBadgeSources[active]?.source
  val count = activeSource?.filters?.count { it.isEnabled } ?: loaded.sumOf { it.filters.count { filter -> filter.isEnabled } }
  val groups = activeSource?.filters?.map { it.groupId }?.distinct()?.size ?: loaded.flatMap { it.filters.map { filter -> filter.groupId } }.distinct().size
  return if (count > 0) "$count badge styles ready${if (groups > 0) " in $groups groups" else ""}" else "No badge styles selected"
}

private data class LiveChannelSwitchSnapshot(
  val detail: MediaDetail?,
  val detailIsLive: Boolean,
  val fallbackItem: MediaItem?,
  val selectedEpisode: EpisodeItem?,
  val availableStreams: List<AddonStream>,
  val sourceAddonId: String?,
  val sourceCatalogType: String?,
  val directStream: AddonStream?,
  val playerSession: PlayerSession?,
)

private class NativeAppViewModel(application: Application) : AndroidViewModel(application) {
  private val sessionStore = SessionStore(application.applicationContext)
  private val profileSelectionStore = ProfileSelectionStore(application.applicationContext)
  private val guestProfileStore = GuestProfileStore(application.applicationContext)
  private val watchlistStore = WatchlistStore(application.applicationContext)
  private val favouriteChannelStore = FavouriteChannelStore(application.applicationContext)
  private val authEntryStore = AuthEntryStore(application.applicationContext)
  private val appSettingsStore = AppSettingsStore(application.applicationContext)
  private val playbackResumeStore = PlaybackResumeStore(application.applicationContext)
  private val watchedEpisodeStore = WatchedEpisodeStore(application.applicationContext)
  private val watchedMovieStore = WatchedMovieStore(application.applicationContext)
  private val watchedTitleStore = WatchedTitleStore(application.applicationContext)
  private var torrentStatusRefreshJob: Job? = null
  private var pluginSyncJob: Job? = null
  private var episodeReminderJob: Job? = null
  private var pluginWatchJob: Job? = null
  /** The document stamp this device last wrote or read, so a poll knows what "changed" means. */
  private var lastKnownPluginVersion: Long = 0L
  private var pluginRefreshJob: Job? = null
  private var cloudStreamLoadJob: Job? = null
  private val apiClient = StreamDekApiClient(application.applicationContext)

  /** Keeps the viewer's normal quality/debrid ordering inside two collection-priority groups. */
  private fun rankedProfileStreams(streams: List<AddonStream>): List<AddonStream> {
    val pluginState = StreamDekPlugins.manager.state
    val favouriteRepos = pluginState.repos.filter { it.favourite }.mapTo(mutableSetOf()) { it.url }
    val favouriteCloudStreamIds = if (CloudStreamPlugins.isInitialized) {
      val state = CloudStreamPlugins.manager.state
      val repos = state.repos.filter { it.favourite }.mapTo(hashSetOf()) { it.url }
      state.providers.filter { it.repoUrl in repos }.mapTo(hashSetOf()) { "cloudstream:${it.name}" }
    } else emptySet()
    val favouriteSkyStreamIds = if (SkyStreamPlugins.isInitialized) {
      val state = SkyStreamPlugins.manager.state
      val repos = state.repos.filter { it.favourite }.mapTo(hashSetOf()) { it.url }
      state.providers.filter { it.repoUrl in repos }.mapTo(hashSetOf()) { "sky:${it.packageName}" }
    } else emptySet()
    return rankedStreams(
      streams = streams,
      hasDebrid = uiState.debridAccounts.any { it.enabled },
      preferredQuality = uiState.preferredQuality,
      maxFileSizeGb = uiState.maxFileSizeGb,
      favouriteAddonIds = uiState.addons.filter { it.favourite }.mapTo(mutableSetOf()) { it.id } + favouriteCloudStreamIds + favouriteSkyStreamIds,
      favouritePluginProviderIds = pluginState.providers.filter { it.repoUrl in favouriteRepos }.mapTo(mutableSetOf()) { it.id },
    )
  }

  /**
   * One playback attempt as the user experiences it, which is not the same as one call to
   * [playStream] — a failed source is retried against the next ranked one, and all of those
   * retries are still the single attempt the viewer is waiting on.
   */
  private data class PlaybackAttempt(
    val correlationId: String,
    val startedAt: Long,
    val mediaId: String,
    val mediaType: String,
    val seasonNumber: Int?,
    val episodeNumber: Int?,
    var sourcesTried: Int,
  ) {
    fun owns(detail: MediaDetail, episode: EpisodeItem?): Boolean =
      mediaId == detail.id &&
        normalizedMediaType(mediaType) == normalizedMediaType(detail.type) &&
        seasonNumber == episode?.seasonNumber &&
        episodeNumber == episode?.episodeNumber
  }

  private var playbackAttempt: PlaybackAttempt? = null

  /**
   * Correlation id for the title currently open.
   *
   * Created when a title is opened and sent on the stream request, so the add-on calls and
   * debrid resolves the backend makes on this device's behalf line up with what the device
   * reports back about whether anything actually played.
   */
  private var detailCorrelationId: String? = null

  private var searchRequestGeneration: Long = 0L
  private var streamRequestGeneration: Long = 0L
  private var playbackRequestGeneration: Long = 0L
  private var watchlistMutationGeneration: Long = 0L
  private var liveChannelCatalogGeneration: Long = 0L
  private var m3uLoadGeneration: Long = 0L
  private var liveChannelSwitchSnapshot: LiveChannelSwitchSnapshot? = null
  private var pendingStreamLoad: PendingStreamLoad? = null
  private var pendingDirectContinueEntry: PlaybackMemoryEntry? = null
  private var pendingDirectContinueFallback: (() -> Unit)? = null

  /**
   * The episode a Continue Watching tap was for.
   *
   * Held so that a remembered source which no longer works lands on that episode's own list of
   * sources. Sending the viewer to the series page instead makes them find their place again,
   * which is the one thing tapping Continue Watching was meant to save them.
   */
  private var pendingDirectContinueEpisode: EpisodeItem? = null
  private val pendingHomeHeroLogoKeys = mutableSetOf<String>()
  private val pendingAddonRatingKeys = mutableSetOf<String>()
  private var trackingArtworkJob: Job? = null
  // TMDB artwork recovered for tracking-service rows that arrived without any, keyed by mediaKey.
  // Cached for the session so a dashboard refresh does not re-fetch the same titles, and negative
  // results are remembered too (null value) so an id TMDB cannot resolve is only attempted once.
  private val trackingArtworkCache = mutableMapOf<String, TrackingArtwork?>()
  // Items whose fetchDetails() call already came back empty/failed once (e.g. a bridge item
  // with a placeholder title and an id TMDB can never resolve). Without this, resolveAddonCatalogRatings
  // re-fetches these same doomed items on every retrigger of its LaunchedEffect (which itself
  // fires again each time addonCatalogRatings.size changes from a *different* item succeeding),
  // producing a burst of repeated identical failing requests (e.g. /tmdb/search?query=_) instead
  // of one failed attempt per item.
  private val heroLogoFailedKeys = mutableSetOf<String>()
  private val addonRatingFailedKeys = mutableSetOf<String>()
  private var detailSourceAddonId: String? = null
  private var detailSourceCatalogType: String? = null
  private var detailDirectStream: AddonStream? = null
  // For a local add-on item, detail.id needs to stay the TMDB id so season/rating/Trakt
  // follow-up calls keep working once TMDB enrichment succeeds -- but the add-on's own
  // /stream endpoint needs its OWN canonical id (from resolveLocalAddonStreamId), which is
  // often not the same value at all. Kept as a separate field rather than overloading detail.id
  // for this one case. Null whenever the open detail isn't a local add-on item.
  // Bumped by every openDetail. launchWork does not cancel the call it supersedes, so without a
  // generation to compare against, a slow detail load that has since been navigated away from
  // still lands: it overwrites uiState.detail with the old title and can start its playback.
  private var detailRequestGeneration = 0
  private var detailSettleJob: Job? = null
  private var detailLocalStreamId: String? = null
  // The canonical id a remote metadata add-on gave for the open detail (e.g. "tmdb:1234"). Unlike
  // detailLocalStreamId this does not replace the normal id list — stream add-ons key on IMDb ids
  // — it is appended as a last-resort candidate for titles TMDB could not resolve.
  private var detailAddonMetaId: String? = null
  private var detailLocalEpisodes: List<EpisodeItem> = emptyList()
  private var routeAfterProfileRefresh = false

  private val restoredSession = sessionStore.load()
  private val restoredGuestProfiles = if (restoredSession == null) guestProfileStore.load() else emptyList()
  private val restoredGuestProfile = restoredGuestProfiles.firstOrNull { it.id == profileSelectionStore.load(GUEST_OWNER_KEY) }
    ?: restoredGuestProfiles.firstOrNull { it.isDefault }
    ?: restoredGuestProfiles.firstOrNull()

  var uiState by mutableStateOf(
    appSettingsStore.applyTo(
      AppUiState(
        booting = false,
        rememberedEmail = authEntryStore.loadEmail(),
        session = restoredSession,
        profilesLoading = restoredSession != null,
        profiles = restoredGuestProfiles,
        activeProfileId = restoredGuestProfile?.id,
        showProfilePicker = restoredSession != null || restoredGuestProfiles.size > 1,
        mergedWatchlist = if (restoredSession == null) {
          watchlistStore.load(restoredGuestProfile?.id?.let { "guest:$it" } ?: GUEST_OWNER_KEY)
        } else {
          emptyList()
        },
        favouriteChannels = if (restoredSession == null) {
          favouriteChannelStore.load(restoredGuestProfile?.id?.let { "guest:$it" } ?: GUEST_OWNER_KEY)
        } else {
          emptyList()
        },
      ),
    ),
  )
    private set

  init {
    // The session is read lazily rather than captured: events queued before sign-in still get
    // attributed once one exists, and signed-out activity is sent anonymously rather than lost.
    Telemetry.configure(apiClient) { uiState.session }
    Telemetry.sessionStarted()
    DisplayNameOverrides.initialize(application.applicationContext)
    LocalAddonManager.initialize(application.applicationContext)
    M3uPlaylistManager.initialize(application.applicationContext)
    StreamDekDownloads.initialize(application.applicationContext)
    // Downloads persist across restarts, but nothing read them back until the Downloads page
    // opened and started polling — so Settings reported "0 downloads" on every cold start until
    // the user went in and out again.
    refreshDownloads()
    val initialOwnerKey = activeOwnerKey() ?: GUEST_OWNER_KEY
    LocalAddonManager.selectProfileStorage(initialOwnerKey)
    M3uPlaylistManager.selectProfileStorage(initialOwnerKey)
    appSettingsStore.selectProfileStorage(initialOwnerKey)
    uiState = appSettingsStore.applyTo(uiState)
    StreamDekPlugins.initialize(application.applicationContext)
    // Read once, into the copy the player consults when it is built.
    PlaybackCodecOptions.initialize(application.applicationContext)
    // Both engines write into the same profile document, so neither may push its own half on its
    // own -- whichever went last would drop the other's. They signal, and the composer below reads
    // both and sends one document.
    //
    // Each callback goes on after its own engine exists. CloudStreamPlugins holds its manager in a
    // lateinit, so touching it before initialize() below is an immediate crash on launch rather
    // than a missed callback -- which is exactly what it was.
    StreamDekPlugins.manager.onStateChanged = { _ -> syncActiveProfilePlugins() }
    StreamDekPlugins.manager.selectProfileStorage(activeOwnerKey() ?: GUEST_OWNER_KEY)
    CloudStreamPlugins.initialize(application.applicationContext)
    CloudStreamPlugins.manager.onStateChanged = { _ -> syncActiveProfilePlugins() }
    SkyStreamPlugins.initialize(application.applicationContext)
    // .cs3 providers only exist for as long as their classes are loaded, so anything the user
    // already enabled has to be re-loaded on every cold start before it can answer a stream request.
    refreshProfileCloudStreamPlugins()
    syncPeerEngine()
    runTrailerCacheHousekeeping()
    restore()
  }

  fun clearTransientMessage() { uiState = uiState.copy(errorMessage = null, infoMessage = null) }

  fun clearPlaybackNotice() { uiState = uiState.copy(playbackNotice = null) }

  /**
   * Clears the trailer cache when its schedule says it is due, on the way in.
   *
   * Checked at launch rather than through a background worker: the state it clears only matters to a
   * viewer who is about to watch something, and a job that wakes the process to delete cookies would
   * cost battery for no one's benefit.
   */
  private fun runTrailerCacheHousekeeping() {
    val app = getApplication<Application>()
    viewModelScope.launch {
      // WebView and CookieManager are main-thread only, which is where this already runs.
      if (TrailerCache.isClearDue(app, uiState.trailerCacheClearHours, TRAILER_CACHE_CLEAR_HOUR_OF_DAY)) {
        TrailerCache.clear(app, "scheduled every ${uiState.trailerCacheClearHours}h")
        resetTrailerMemory()
      }
      refreshTrailerCacheStatus()
    }
  }

  /**
   * Drops what a clear cannot reach on its own: the resolver's decisions, KinoCheck's answers, and
   * whatever the open page and its WebView are still holding.
   *
   * This is the difference between a clear that works and a clear that works after an app restart.
   */
  private fun resetTrailerMemory() {
    resetKinocheckHttpClient()
    resetTrailerResolverMemory()
    TrailerResetSignal.bump()
  }

  private fun refreshTrailerCacheStatus() {
    val app = getApplication<Application>()
    viewModelScope.launch {
      val size = withContext(Dispatchers.IO) { TrailerCache.sizeBytes(app) }
      uiState = uiState.copy(
        trailerCacheSizeBytes = size,
        trailerCacheLastClearedAt = TrailerCache.lastClearedAt(app),
      )
    }
  }

  fun setTrailerCacheClearHours(hours: Int) {
    appSettingsStore.saveTrailerCacheClearHours(hours)
    uiState = uiState.copy(trailerCacheClearHours = hours)
    syncCloudPreferences()
  }

  /**
   * Clears trailer state now, at the viewer's request.
   *
   * The manual route exists because this is the fix for a trailer that has stopped playing, and
   * waiting until nine in the morning is not a fix. Clearing app data by hand did the same thing but
   * took settings, watchlist and premium keys with it.
   */
  fun clearTrailerCacheNow() {
    val app = getApplication<Application>()
    viewModelScope.launch {
      val freed = TrailerCache.clear(app, "requested from settings")
      resetTrailerMemory()
      refreshTrailerCacheStatus()
      // Names what went, so the row is visibly answering rather than leaving the viewer to wonder
      // whether the tap registered — the whole reason they are on this screen is that trailers are
      // not playing, and "nothing appeared to happen" is the worst possible response to that.
      uiState = uiState.copy(
        infoMessage = if (freed > 0L) {
          "Trailer cache cleared — ${formatBytesLabel(freed)} and stored site data removed."
        } else {
          "Trailer cache cleared — stored site data removed."
        },
      )
    }
  }

  fun rememberAuthEmail(email: String) {
    authEntryStore.saveEmail(email)
    uiState = uiState.copy(rememberedEmail = email)
  }

  fun signOut() {
    sessionStore.clear()
    // The premium service keys belong to the account that just left, not to the device.
    DebridKeyStore.clear(getApplication())
    // Same reasoning for the content-service keys, including a device-only one: it was this
    // viewer's key, and leaving it behind would hand it to whoever signs in next.
    apiClient.serviceCredentials?.clearAll()
    deviceDebridManager = null
    uiState = appSettingsStore.applyTo(AppUiState(booting = false, rememberedEmail = authEntryStore.loadEmail(), mergedWatchlist = watchlistStore.load(GUEST_OWNER_KEY), favouriteChannels = favouriteChannelStore.load(GUEST_OWNER_KEY)))
    bootstrapAfterAuth(forceHome = true)
  }

  fun signIn(email: String, password: String, rememberSession: Boolean) {
    rememberAuthEmail(email)
    submitAuth { apiClient.login(email, password) }
  }

  fun signUp(email: String, password: String, rememberSession: Boolean) {
    rememberAuthEmail(email)
    // Capture the guest identity being left behind *before* auth changes activeOwnerKey().
    val guestKey = if (uiState.session == null) activeOwnerKey() else null
    val mergeSourceKey = guestKey?.takeIf(::hasGuestDataFor)
    submitAuth(guestDataOwnerKey = mergeSourceKey) { apiClient.register(email, password) }
  }

  private fun hasGuestDataFor(ownerKey: String): Boolean =
    watchlistStore.load(ownerKey).isNotEmpty() ||
      favouriteChannelStore.load(ownerKey).isNotEmpty() ||
      playbackResumeStore.loadAll(ownerKey).isNotEmpty() ||
      LocalAddonManager.list().isNotEmpty()

  fun requestPasswordReset(email: String) {
    launchWork(
      onStart = { uiState = uiState.copy(errorMessage = null, infoMessage = null) },
      block = { apiClient.requestPasswordReset(email) },
      onSuccess = { code -> uiState = uiState.copy(infoMessage = if (code.isNullOrBlank()) "Reset request sent." else "Reset code: $code") },
    )
  }

  fun confirmPasswordReset(email: String, token: String, newPassword: String) {
    launchWork(
      onStart = { uiState = uiState.copy(errorMessage = null, infoMessage = null) },
      block = { apiClient.confirmPasswordReset(email, token, newPassword) },
      onSuccess = { uiState = uiState.copy(infoMessage = "Password updated. You can sign in now.") },
    )
  }

  /**
   * Resets a password without a code, then signs in with it.
   *
   * Signing in here rather than sending the viewer back to the form is the point of it: the
   * reset invalidates every existing session for the account, so there is nothing to return to.
   */
  fun resetPasswordDirect(email: String, newPassword: String) {
    launchWork(
      onStart = { uiState = uiState.copy(errorMessage = null, infoMessage = null) },
      block = { apiClient.resetPasswordDirect(email, newPassword) },
      onSuccess = {
        uiState = uiState.copy(infoMessage = "Password updated.")
        signIn(email, newPassword, true)
      },
    )
  }

  private fun invalidatePendingPlaybackRequest(clearPendingContinue: Boolean = true) {
    playbackRequestGeneration += 1
    playbackAttempt = null
    if (clearPendingContinue) {
      pendingDirectContinueEntry = null
      pendingDirectContinueFallback = null
      pendingDirectContinueEpisode = null
    }
  }

  fun dismissPlayer(progressPercent: Double? = null) {
    invalidatePendingPlaybackRequest()
    liveChannelSwitchSnapshot = null
    progressPercent?.let {
      saveCurrentPlaybackSnapshot(it)
      scrobbleCurrentPlayer("pause", it)
    }
    uiState = uiState.copy(playerSession = null, playerLaunchSession = null, playerLaunching = false, playerLaunchingLabel = null, playerLaunchingPeerHash = null, streamLoading = false, nextEpisodeLoading = false, nextEpisodeLoadingLabel = null)
    stopOnDemandPeerEngine()
    // Closes the news server connections and drops the partially assembled file. A no-op unless
    // what just stopped was a usenet source.
    UsenetPlayback.release()
  }

  fun playRecommendedFromEnding(item: MediaItem) {
    saveCurrentPlaybackSnapshot(100.0)
    dismissPlayer(100.0)
    uiState = uiState.copy(pendingEndRecommendation = item)
    loadDetail(item.type, item.id, item)
  }

  fun consumeEndRecommendation() {
    uiState = uiState.copy(pendingEndRecommendation = null)
  }

  fun cancelPlayerLaunch() {
    invalidatePendingPlaybackRequest()
    uiState = uiState.copy(
      playerLaunchSession = null,
      playerLaunching = false,
      playerLaunchingLabel = null,
      playerLaunchingPeerHash = null,
      streamLoading = false,
      // A cancelled launch still belongs to the title it was opened from. Keeping this true lets
      // MainScene restore that detail route instead of exposing the Activity as the next back target.
      returnToDetailAfterPlayer = uiState.detail != null,
      playerReturnEpisodeId = null,
    )
  }

  fun setBrowseRow(row: HomeRow?) {
    uiState = if (row == null) {
      uiState.copy(browseRow = null, browseLoadedItems = emptyList(), browseReturnItemId = null)
    } else {
      // Opening a row starts again from what the home preview holds, so the paging cursor has to
      // go back to where that preview stopped. Left where the last visit finished, a second visit
      // would show twenty items and then jump straight to page six.
      val restart = uiState.allHomeSections.firstOrNull { it.id == row.id }?.nextPage
      uiState.copy(
        browseRow = row,
        browseLoadedItems = row.items,
        browseReturnItemId = null,
        catalogNextPages = if (restart != null) uiState.catalogNextPages + (row.id to restart) else uiState.catalogNextPages,
      )
    }
  }

  fun rememberBrowseReturnItem(item: MediaItem) {
    uiState = uiState.copy(browseReturnItemId = item.id)
  }

  fun playLiveChannel(item: MediaItem) {
    if (!item.isLiveCatalogItem() || uiState.liveChannelSwitching) return
    liveChannelSwitchSnapshot = LiveChannelSwitchSnapshot(
      detail = uiState.detail,
      detailIsLive = uiState.detailIsLive,
      fallbackItem = uiState.detailFallbackItem,
      selectedEpisode = uiState.selectedEpisode,
      availableStreams = uiState.availableStreams,
      sourceAddonId = detailSourceAddonId,
      sourceCatalogType = detailSourceCatalogType,
      directStream = detailDirectStream,
      playerSession = uiState.playerSession,
    )
    uiState = uiState.copy(liveChannelSwitching = true, liveChannelSwitchingLabel = item.title, errorMessage = null)
    loadDetail(item.type, item.id, item)
    playBestStream()
  }

  fun hasLiveChannelFallback(): Boolean = liveChannelSwitchSnapshot?.playerSession != null

  fun cancelLiveChannelSwitch() {
    val snapshot = liveChannelSwitchSnapshot ?: return
    playbackRequestGeneration += 1
    streamRequestGeneration += 1
    detailSourceAddonId = snapshot.sourceAddonId
    detailSourceCatalogType = snapshot.sourceCatalogType
    detailDirectStream = snapshot.directStream
    uiState = uiState.copy(
      detail = snapshot.detail, detailIsLive = snapshot.detailIsLive, detailFallbackItem = snapshot.fallbackItem,
      selectedEpisode = snapshot.selectedEpisode, availableStreams = snapshot.availableStreams, playerSession = snapshot.playerSession,
      streamLoading = false, playerLaunchSession = null, playerLaunching = false, playerLaunchingLabel = null, playerLaunchingPeerHash = null,
      liveChannelSwitching = false, liveChannelSwitchingLabel = null, errorMessage = null,
    )
    liveChannelSwitchSnapshot = null
  }

  private fun loadPlayerLiveChannels(anchor: MediaItem) {
    val addonId = anchor.sourceAddonId ?: return
    val catalogType = anchor.sourceCatalogType ?: return
    val catalogId = anchor.sourceCatalogId ?: return
    val matchesCatalog: (MediaItem) -> Boolean = {
      // Match cheap source fields first. Calling isLiveCatalogItem() for every entry compiles
      // regexes and was especially costly when a large enabled M3U playlist leaked into a
      // different add-on's card click.
      it.sourceAddonId == addonId && it.sourceCatalogType == catalogType &&
        it.sourceCatalogId == catalogId && it.sourceCatalogGenre == anchor.sourceCatalogGenre
    }
    val generation = ++liveChannelCatalogGeneration
    val sourceLists = if (M3uPlaylistManager.isM3uSourceId(addonId)) {
      listOf(uiState.m3uChannels)
    } else {
      // Keep M3U channels out of other add-ons' player catalogs. Any previously selected M3U
      // catalog may still be present in playerLiveChannels, so source-field filtering remains
      // mandatory even though the explicit m3uChannels list is not included here.
      listOf(
        uiState.playerLiveChannels,
        uiState.browseLoadedItems,
        *uiState.allHomeSections.map { it.items }.toTypedArray(),
        *uiState.homeSections.map { it.items }.toTypedArray(),
      )
    }
    // A live-card tap must only do constant work on the main thread. Enabled IPTV playlists can
    // contain tens of thousands of channels; concatenating, filtering, regex-checking and
    // de-duplicating those lists synchronously caused the observed five-second input ANR.
    uiState = uiState.copy(playerLiveChannels = listOf(anchor), playerLiveChannelsLoading = true)
    viewModelScope.launch {
      var loaded = withContext(Dispatchers.Default) {
        sequence {
          sourceLists.forEach { list -> yieldAll(list) }
          yield(anchor)
        }.filter(matchesCatalog).distinctBy { "${it.type}-${it.id}" }.toList()
          .ifEmpty { listOf(anchor) }
      }
      if (generation != liveChannelCatalogGeneration) return@launch
      uiState = uiState.copy(playerLiveChannels = loaded)
      if (M3uPlaylistManager.isM3uSourceId(addonId)) {
        uiState = uiState.copy(playerLiveChannelsLoading = false)
        return@launch
      }
      val addon = uiState.addons.firstOrNull { it.id == addonId && it.enabled }
      if (addon == null) {
        uiState = uiState.copy(playerLiveChannelsLoading = false)
        return@launch
      }
      var pages = 0
      while (pages++ < 250 && loaded.size < 5_000) {
        val page = apiClient.fetchMoreCatalogItems(
          uiState.session, addon, catalogType, catalogId, anchor.sourceCatalogName ?: catalogType,
          anchor.sourceCatalogGenre, loaded.size, uiState.activeProfileId,
        ).getOrElse { emptyList() }.filter(matchesCatalog)
        if (generation != liveChannelCatalogGeneration) return@launch
        val merged = withContext(Dispatchers.Default) {
          (loaded.asSequence() + page.asSequence()).distinctBy { "${it.type}-${it.id}" }.toList()
        }
        if (merged.size == loaded.size) break
        loaded = merged
        uiState = uiState.copy(playerLiveChannels = loaded)
      }
      if (generation == liveChannelCatalogGeneration) {
        uiState = uiState.copy(playerLiveChannels = loaded, playerLiveChannelsLoading = false)
      }
    }
  }

  fun setNetworkBrowseItem(item: MediaItem?) { uiState = uiState.copy(networkBrowseItem = item) }

  fun clearBrowseNavigation() { uiState = uiState.copy(browseRow = null, networkBrowseItem = null) }

  fun clearPlayerReturnTarget() {
    uiState = uiState.copy(returnToDetailAfterPlayer = false, playerReturnEpisodeId = null)
  }

  fun onPlayerPlaybackEnded() {
    val completedPlayer = uiState.playerSession
    if (completedPlayer?.mediaType == "tv" && completedPlayer.seasonNumber != null && completedPlayer.episodeNumber != null) {
      val ownerKey = watchedOwnerKey(uiState.session, uiState.activeProfileId)
      val watchedKey = watchedEpisodeKey(completedPlayer.mediaId, completedPlayer.seasonNumber, completedPlayer.episodeNumber)
      val existing = watchedEpisodeStore.load(ownerKey, completedPlayer.mediaId)
      if (watchedKey !in existing) {
        watchedEpisodeStore.save(ownerKey, completedPlayer.mediaId, completedEpisodeWatchedIds(existing, watchedKey))
        uiState = uiState.copy(watchedEpisodeRevision = uiState.watchedEpisodeRevision + 1)
      }
    }
    val player = uiState.playerSession ?: return
    saveCurrentPlaybackSnapshot(100.0)
    val detail = uiState.detail
    val currentEpisode = uiState.selectedEpisode
    if (!player.autoPlayNextEpisode || detail == null || detail.type != "tv" || currentEpisode == null) {
      dismissPlayer(100.0)
      return
    }
    val loadedNextEpisode = uiState.selectedSeasonEpisodes
      .filter { it.seasonNumber == currentEpisode.seasonNumber && it.episodeNumber > currentEpisode.episodeNumber }
      .minByOrNull { it.episodeNumber }
    val nextSeasonNumber = detail.seasons
      .map { it.seasonNumber }
      .filter { it > currentEpisode.seasonNumber }
      .minOrNull()
    if (loadedNextEpisode == null && nextSeasonNumber == null) {
      dismissPlayer(100.0)
      return
    }
    val currentStream = player.currentStream
    launchWork(
      onStart = { uiState = uiState.copy(streamLoading = true, nextEpisodeLoading = true, nextEpisodeLoadingLabel = loadedNextEpisode?.let { "S${it.seasonNumber} • E${it.episodeNumber}" } ?: nextSeasonNumber?.let { "Season $it" }, errorMessage = null) },
      block = {
        val nextEpisode = loadedNextEpisode ?: apiClient.fetchSeason(detail.id, nextSeasonNumber!!)
          .getOrElse { return@launchWork Result.failure(it) }
          .minByOrNull { it.episodeNumber }
          ?: return@launchWork Result.failure(IllegalStateException("The next season has no playable episodes."))
        val ids = streamLookupIds(detail).distinct()
          .map { "$it:${nextEpisode.seasonNumber}:${nextEpisode.episodeNumber}" }
        fetchStreamsForPlayback("series", ids).map { streams -> nextEpisode to streams }
      },
      onSuccess = { (nextEpisode, streams) ->
        val ranked = rankedProfileStreams(mediaStreamsOnly(streams, detail))
        val sameBingeGroup = currentStream?.bingeGroup?.takeIf { it.isNotBlank() }?.let { group -> ranked.firstOrNull { it.bingeGroup == group } }
        val sameAddonAndQuality = currentStream?.let { current -> ranked.firstOrNull { it.addonId == current.addonId && it.quality == current.quality } }
        val selected = if (player.preferBingeGroup) sameBingeGroup ?: sameAddonAndQuality ?: ranked.firstOrNull() else ranked.firstOrNull()
        val selectionStrategy = when {
          selected == null -> "none"
          sameBingeGroup != null && selected == sameBingeGroup -> "binge-group"
          sameAddonAndQuality != null && selected == sameAddonAndQuality -> "addon-quality"
          else -> "ranked-fallback"
        }
        android.util.Log.i("StreamDekPlayback", "next-source strategy=$selectionStrategy currentGroup=${currentStream?.bingeGroup ?: "none"} selectedGroup=${selected?.bingeGroup ?: "none"} addon=${selected?.addonName ?: "none"} quality=${selected?.quality ?: "unknown"}")
        uiState = uiState.copy(selectedEpisode = nextEpisode, availableStreams = ranked)
        if (selected == null) {
          dismissPlayer(100.0)
          uiState = uiState.copy(errorMessage = "No playable source was found for the next episode.")
        } else {
          playStream(selected, nextEpisode)
        }
      },
      onFailure = { message -> dismissPlayer(100.0); uiState = uiState.copy(streamLoading = false, nextEpisodeLoading = false, nextEpisodeLoadingLabel = null, errorMessage = message) },
    )
  }
  fun playAdjacentEpisode(direction: Int) {
    val detail = uiState.detail ?: return
    val current = uiState.selectedEpisode ?: return
    if (detail.type != "tv" || direction == 0) return
    val sameSeason = uiState.selectedSeasonEpisodes
      .filter { it.seasonNumber == current.seasonNumber }
      .sortedBy { it.episodeNumber }
    val sameSeasonTarget = if (direction > 0) sameSeason.firstOrNull { it.episodeNumber > current.episodeNumber } else sameSeason.lastOrNull { it.episodeNumber < current.episodeNumber }
    val adjacentSeason = detail.seasons.map { it.seasonNumber }
      .filter { if (direction > 0) it > current.seasonNumber else it < current.seasonNumber }
      .let { values -> if (direction > 0) values.minOrNull() else values.maxOrNull() }
    if (sameSeasonTarget == null && adjacentSeason == null) return
    val currentStream = uiState.playerSession?.currentStream
    launchWork(
      onStart = {
        val label = sameSeasonTarget?.let { "S${it.seasonNumber} • E${it.episodeNumber}" } ?: adjacentSeason?.let { "Season $it" }
        uiState = uiState.copy(streamLoading = true, nextEpisodeLoading = true, nextEpisodeLoadingLabel = label, errorMessage = null)
      },
      block = {
        val target = sameSeasonTarget ?: apiClient.fetchSeason(detail.id, adjacentSeason!!)
          .getOrElse { return@launchWork Result.failure(it) }
          .let { episodes -> if (direction > 0) episodes.minByOrNull { it.episodeNumber } else episodes.maxByOrNull { it.episodeNumber } }
          ?: return@launchWork Result.failure(IllegalStateException("No adjacent episode was found."))
        val ids = streamLookupIds(detail).distinct()
          .map { "$it:${target.seasonNumber}:${target.episodeNumber}" }
        fetchStreamsForPlayback("series", ids).map { streams -> target to streams }
      },
      onSuccess = { (target, streams) ->
        val ranked = rankedProfileStreams(mediaStreamsOnly(streams, detail))
        val bingeMatch = currentStream?.bingeGroup?.takeIf { it.isNotBlank() }?.let { group -> ranked.firstOrNull { it.bingeGroup == group } }
        val addonMatch = currentStream?.let { source -> ranked.firstOrNull { it.addonId == source.addonId && it.quality == source.quality } }
        val selected = if (uiState.preferBingeGroup) bingeMatch ?: addonMatch ?: ranked.firstOrNull() else ranked.firstOrNull()
        uiState = uiState.copy(selectedEpisode = target, availableStreams = ranked)
        if (selected == null) {
          uiState = uiState.copy(streamLoading = false, nextEpisodeLoading = false, nextEpisodeLoadingLabel = null, errorMessage = "No playable source was found for S${target.seasonNumber} E${target.episodeNumber}.")
        } else {
          playStream(selected, target)
        }
      },
      onFailure = { message -> uiState = uiState.copy(streamLoading = false, nextEpisodeLoading = false, nextEpisodeLoadingLabel = null, errorMessage = message) },
    )
  }

  /** Completes only the episode whose legitimate ending CTA initiated the transition. */
  fun playNextEpisodeFromEnding() {
    val player = uiState.playerSession ?: return
    if (player.mediaType != "tv" || player.seasonNumber == null || player.episodeNumber == null) {
      playAdjacentEpisode(1)
      return
    }
    val ownerKey = watchedOwnerKey(uiState.session, uiState.activeProfileId)
    val watchedKey = watchedEpisodeKey(player.mediaId, player.seasonNumber, player.episodeNumber)
    val existing = watchedEpisodeStore.load(ownerKey, player.mediaId)
    if (watchedKey !in existing) {
      watchedEpisodeStore.save(ownerKey, player.mediaId, completedEpisodeWatchedIds(existing, watchedKey))
      uiState = uiState.copy(watchedEpisodeRevision = uiState.watchedEpisodeRevision + 1)
    }
    if (lastPlaybackDurationSec > 0.0) lastPlaybackPositionSec = lastPlaybackDurationSec
    saveCurrentPlaybackSnapshot(100.0)
    scrobbleCurrentPlayer("stop", 100.0)
    Log.i("StreamDekPlayback", "[EpisodeTransition] from=S${player.seasonNumber}E${player.episodeNumber} previousEpisodeCompleted=true")
    playAdjacentEpisode(1)
  }

  fun scrobblePlayer(action: String, progressPercent: Double) { scrobbleCurrentPlayer(action, progressPercent) }

  /**
   * Where the player has got to, in seconds as well as percent.
   *
   * The seconds are what the account stores and what another device resumes from; the percent is
   * what this app's own row uses. The player knew both all along and only passed the percent on,
   * which is why nothing could be shared.
   */
  fun savePlayerProgressCheckpoint(positionSec: Double, durationSec: Double) {
    if (uiState.playerSession == null) return
    lastPlaybackPositionSec = positionSec
    lastPlaybackDurationSec = durationSec
    val percent = if (durationSec > 0.0) ((positionSec / durationSec) * 100.0).coerceIn(0.0, 100.0) else 0.0
    saveCurrentPlaybackSnapshot(percent)
  }

  fun refreshHandoffDevices() {
    val session = uiState.session ?: run {
      uiState = uiState.copy(handoffDevices = emptyList())
      return
    }
    viewModelScope.launch {
      apiClient.fetchLinkedTvDevices(session, uiState.activeProfileId)
        // Renaming happens here, at the one place linked TVs enter app state, so every picker
        // that offers a TV shows the user's own label without knowing about the override store.
        .onSuccess { devices -> uiState = uiState.copy(handoffDevices = devices.filterNot { it.isCurrent }.map(::withTvDisplayName)) }
        .onFailure { uiState = uiState.copy(handoffDevices = emptyList()) }
    }
  }

  suspend fun handoffCurrentPlayback(device: LinkedTvDevice, positionSeconds: Double): Result<PlaybackHandoffReceipt> {
    val session = uiState.session ?: return Result.failure(IllegalStateException("Sign in to hand off playback to a TV."))
    val player = uiState.playerSession ?: return Result.failure(IllegalStateException("Playback is no longer active."))
    return apiClient.sendPlaybackHandoff(session, uiState.activeProfileId, device, player, positionSeconds)
  }
  suspend fun handoffLiveChannel(item: MediaItem, device: LinkedTvDevice): Result<PlaybackHandoffReceipt> = runCatching {
    require(item.isLiveCatalogItem()) { "Only live channels can be sent from this menu." }
    val session = uiState.session ?: throw IllegalStateException("Sign in to watch this channel on a TV.")
    val detail = item.toFallbackDetail()
    val directStream = item.directStreamUrl?.takeIf { it.isNotBlank() }?.let { url ->
      AddonStream(
        addonId = item.sourceAddonId.orEmpty(),
        addonName = uiState.addons.firstOrNull { it.id == item.sourceAddonId }?.manifest?.name ?: "Live TV",
        name = item.title,
        title = item.title,
        description = item.description.ifBlank { null },
        url = url,
        infoHash = null,
        fileIdx = null,
        filename = null,
        quality = null,
        size = null,
        cachedBy = emptyList(),
        requestHeaders = item.requestHeaders,
        drmLicenseType = item.drmLicenseType,
        drmClearKeys = item.drmClearKeys,
      )
    }
    val streams = if (directStream != null) {
      listOf(directStream)
    } else {
      val addonId = item.sourceAddonId ?: throw IllegalStateException("The addon for this channel is no longer available.")
      val addon = uiState.addons.firstOrNull { it.id == addonId && it.enabled }
        ?: throw IllegalStateException("Enable this channel's addon before sending it to a TV.")
      val typeCandidates = buildList {
        item.sourceCatalogType?.takeIf { it.isNotBlank() }?.let(::add)
        item.type.takeIf { it.isNotBlank() }?.let(::add)
        addAll(listOf("live", "channel", "tv", "sport", "sports", "other"))
      }.map { it.lowercase() }.distinct()
      var lastFailure: Throwable? = null
      var resolved = emptyList<AddonStream>()
      for (type in typeCandidates) {
        apiClient.fetchStreamsFromAddon(session, addon.id, type, item.id, uiState.activeProfileId)
          .onSuccess { if (it.isNotEmpty()) resolved = it }
          .onFailure { lastFailure = it }
        if (resolved.isNotEmpty()) break
      }
      if (resolved.isEmpty()) {
        for (type in typeCandidates.take(3)) {
          apiClient.fetchFreshStreamsFromAddon(addon, type, item.id)
            .onSuccess { if (it.isNotEmpty()) resolved = it }
            .onFailure { lastFailure = it }
          if (resolved.isNotEmpty()) break
        }
      }
      if (resolved.isEmpty()) throw lastFailure ?: IllegalStateException("No playable stream was found for this channel.")
      resolved
    }
    val ranked = rankedProfileStreams(mediaStreamsOnly(streams, detail))
    val selected = ranked.firstOrNull() ?: throw IllegalStateException("No playable stream was found for this channel.")
    val directUrl = selected.url?.takeIf { it.isNotBlank() && !it.startsWith("magnet:", ignoreCase = true) }
    val playback = if (directUrl != null) ResolvedPlayback(directUrl, selected) else resolvePlayback(selected, detail, null).getOrThrow()
    val player = buildPlayerSession(playback.url, detail, buildSourceLabel(playback.stream), null, playback.stream)
      .copy(isLive = true, synopsis = null)
    apiClient.sendPlaybackHandoff(session, uiState.activeProfileId, device, player, 0.0).getOrThrow()
  }

  /**
   * Sends a Continue Watching card straight to a TV without opening the player first.
   *
   * The remembered source (the same [PlaybackMemoryEntry.stream] that makes tapping the card
   * resume instantly) is preferred so the TV gets the exact source that was already working. When
   * nothing is remembered — "Remember last source" off, or the entry came from Trakt rather than
   * local playback — this falls back to a fresh ranked stream search for the resume episode.
   */
  suspend fun handoffContinueWatching(item: MediaItem, device: LinkedTvDevice): Result<PlaybackHandoffReceipt> = runCatching {
    val session = uiState.session ?: throw IllegalStateException("Sign in to watch this on a TV.")
    val ownerKey = activeOwnerKey() ?: GUEST_OWNER_KEY
    val mediaType = normalizedMediaType(item.type)
    val entry = playbackResumeStore.loadAll(ownerKey)
      .filter { it.mediaId == item.id && normalizedMediaType(it.mediaType) == mediaType && !it.isLive }
      .maxByOrNull { it.updatedAt }
    val detail = apiClient.fetchDetails(item.type, item.id, item.title, item.year).getOrNull() ?: item.toFallbackDetail()
    val seasonNumber = entry?.seasonNumber ?: item.resumeSeasonNumber
    val episodeNumber = entry?.episodeNumber ?: item.resumeEpisodeNumber
    val episode = if (mediaType == "tv" && seasonNumber != null && episodeNumber != null) {
      EpisodeItem(
        id = "${detail.id}:$seasonNumber:$episodeNumber",
        episodeNumber = episodeNumber,
        seasonNumber = seasonNumber,
        name = "Episode $episodeNumber",
        overview = "",
        still = null,
        runtime = entry?.durationSeconds?.div(60),
      )
    } else {
      null
    }
    val remembered = entry?.stream?.takeIf { !it.url.isNullOrBlank() || !it.infoHash.isNullOrBlank() }
    val stream = remembered ?: run {
      val streamType = if (mediaType == "tv") "series" else mediaType
      val baseIds = listOfNotNull(detail.imdbId?.takeIf { it.isNotBlank() }, detail.id, item.id).distinct()
      val videoIds = baseIds.map { base -> episode?.let { "$base:${it.seasonNumber}:${it.episodeNumber}" } ?: base }
      val fetched = fetchStreamsForPlayback(streamType, videoIds, live = false, detail = detail).getOrThrow()
      rankedProfileStreams(mediaStreamsOnly(fetched, detail))
        .firstOrNull() ?: throw IllegalStateException("No playable source was found for ${item.title}.")
    }
    val playback = resolvePlayback(stream, detail, episode).getOrThrow()
    val progressPercent = (entry?.progressPercent ?: item.progress ?: 0.0).coerceIn(0.0, 100.0)
    val durationSeconds = entry?.durationSeconds ?: (episode?.runtime ?: detail.runtimeMinutes)?.times(60)
    val positionSeconds = durationSeconds?.let { it * progressPercent / 100.0 } ?: 0.0
    val player = buildPlayerSession(playback.url, detail, buildSourceLabel(playback.stream), episode, playback.stream, progressPercent)
      .copy(isLive = false)
    apiClient.sendPlaybackHandoff(session, uiState.activeProfileId, device, player, positionSeconds).getOrThrow()
  }
  /**
   * Loads the home rows.
   *
   * [silent] leaves `homeLoading` alone. That flag does double duty -- it draws the splash while
   * there is nothing to show, and it drives the pull-to-refresh indicator once there is -- so a
   * refresh the app started by itself, after the first load has landed, renders exactly like one
   * the viewer pulled down for. Background reloads pass `silent` and simply swap the rows in when
   * they arrive.
   */
  /**
   * Puts a set of home rows on screen.
   *
   * Shared by the progressive hand-off and the final result so the two cannot drift: the partial
   * publish has to produce exactly the screen the complete one would, only with fewer rows in it.
   */
  /** Releases the coalescing latch and runs the one reload any mid-flight caller asked for. */
  private fun finishHomeLoad() {
    homeLoadInFlight = false
    if (homeReloadPending) {
      homeReloadPending = false
      loadHome(force = true, silent = true)
    }
  }

  private fun publishHomeSections(
    sections: List<MediaSection>,
    definitions: List<CatalogDefinition>,
    rows: List<HomeCatalogRow>,
  ) {
    val mergedRows = if (definitions.isEmpty()) rows else mergeHomeCatalogRows(uiState.homeCatalogRows, uiState.addons, definitions)
    // homeLoading is cleared either way: a silent load never set it, and clearing a flag that
    // is already false costs nothing and keeps the two paths from drifting apart.
    uiState = uiState.copy(
      homeLoading = false,
      allHomeSections = sections,
      catalogDefinitions = definitions.ifEmpty { uiState.catalogDefinitions },
      catalogNextPages = sections.mapNotNull { section -> section.nextPage?.let { section.id to it } }.toMap(),
      homeCatalogRows = mergedRows,
      homeSections = applyHomeCatalogLayout(sections, mergedRows, uiState.defaultAppCatalogsEnabled),
    )
    appSettingsStore.saveHomeCatalogRows(mergedRows)
  }

  /**
   * Whether a home load is running, and whether another was asked for while it was.
   *
   * A cold start fires [loadHome] from several independent places — the first composition, the
   * session bootstrap, the profile becoming active, the add-on list arriving — and each of them
   * legitimately wants fresh rows. Measured on a cold start that was five full loads: five
   * catalog-manifest reads, five `/tmdb/home` requests and five add-on fan-outs for one screen.
   *
   * They are coalesced rather than suppressed. A request that arrives mid-flight sets
   * [homeReloadPending] instead of starting a second pass, and one more load runs when the
   * current one finishes — so the last caller's intent is still honoured, once.
   */
  private var homeLoadInFlight = false
  private var homeReloadPending = false

  fun loadHome(force: Boolean = false, silent: Boolean = false) {
    if (uiState.homeSections.isNotEmpty() && !force) return
    if (homeLoadInFlight) {
      if (force) homeReloadPending = true
      return
    }
    homeLoadInFlight = true
    launchWork(
      onStart = { if (!silent) uiState = uiState.copy(homeLoading = true, errorMessage = null) },
      block = {
        val perf = Perf.span("home", if (force) "forced" else "normal")
        // The registry says which default rows exist; the viewer's saved layout says which of
        // them to actually fetch, so switching rows off makes the home request smaller rather
        // than fetching thirty rows and throwing most of them away.
        val definitions = apiClient.fetchCatalogManifest().getOrElse { error ->
          android.util.Log.w("StreamDekCatalogs", "catalog manifest unavailable, using built-in defaults", error)
          emptyList()
        }
        val rows = mergeHomeCatalogRows(uiState.homeCatalogRows, uiState.addons, definitions.ifEmpty { uiState.catalogDefinitions })
        val visibleIds = if (!uiState.defaultAppCatalogsEnabled) emptyList() else rows
          .filter { it.builtin && it.enabled && it.id !in streamDekFeatureRowIds }
          .map { it.id }
        // The spotlight is a consumer of the active catalog provider, not a Home row. Fetch a
        // small provider-ranked fallback set even when the matching visible row is switched off.
        // applyHomeCatalogLayout still decides which rows are actually rendered below it.
        val heroIds = if (!uiState.defaultAppCatalogsEnabled) emptyList() else heroCatalogIds(
          definitions.ifEmpty { uiState.catalogDefinitions },
        )
        val wantedIds = (visibleIds + heroIds).distinct()
        // Recorded before the call, not after: what came back cannot answer "did we ask for
        // this", because the backend omits a row that turned out to be empty.
        requestedHomeCatalogIds = wantedIds.toSet()
        perf.mark("catalogManifest", "rows=${wantedIds.size}")
        apiClient
          .fetchHomeSections(
            uiState.session,
            uiState.addons,
            uiState.activeProfileId,
            catalogIds = wantedIds,
            // The built-in rows go on screen the moment they land, so the add-on fan-out no
            // longer holds the whole screen behind a splash. The complete set replaces them
            // below; until then the viewer has something real to look at and scroll.
            //
            // Nothing to hand over early when there are no built-in rows to fetch - StreamDek
            // Home Rows switched off, so the batched request is answered empty by construction.
            // Publishing that empty answer cleared homeLoading and wiped the rows already on
            // screen while the add-on fan-out, the only thing that was ever going to produce
            // rows here, was still running: Home looked finished and empty until something
            // unrelated happened to reload it. Skipping the hand-off leaves the loading state
            // (or the previous rows) up until the real answer lands.
            onDefaults = { defaults ->
              if (defaults.isNotEmpty()) {
                withContext(Dispatchers.Main) {
                  perf.mark("publishDefaults", "count=${defaults.size}")
                  publishHomeSections(defaults, definitions, rows)
                }
              }
            },
          )
          .also { perf.mark("sections", "count=${it.getOrNull()?.size ?: -1}") }
          .map { sections -> Triple(sections, definitions, rows) }
          .also { perf.end("loaded") }
      },
      onSuccess = { (sections, definitions, rows) ->
        publishHomeSections(sections, definitions, rows)
        finishHomeLoad()
      },
      // A background reload that fails leaves the rows already on screen alone rather than
      // replacing them with an error the viewer did not ask for and cannot act on.
      onFailure = { message ->
        uiState = if (silent) {
          uiState.copy(homeLoading = false)
        } else {
          uiState.copy(homeLoading = false, errorMessage = message)
        }
        finishHomeLoad()
      },
    )
  }

  /**
   * What the home screen's shape depends on, as one comparable value.
   *
   * Used to decide whether synced preferences arriving are worth a reload at all. Most launches
   * they are not: the rows are the same ones the device already had, and the second fetch was a
   * full home request whose answer was identical to the first.
   */
  private fun homeLayoutSignature(): String =
    uiState.homeCatalogRows.joinToString(",") { row -> row.id + ":" + row.enabled } +
      "|" + uiState.defaultAppCatalogsEnabled

  fun resolveHomeHeroTitleLogos(items: List<MediaItem>) {
    val requests = items
      .asSequence()
      .filter { it.titleLogo.isNullOrBlank() }
      .distinctBy(::homeHeroMediaKey)
      .filter { homeHeroMediaKey(it) !in uiState.homeHeroTitleLogos }
      .filter { homeHeroMediaKey(it) !in heroLogoFailedKeys }
      .filter { pendingHomeHeroLogoKeys.add(homeHeroMediaKey(it)) }
      .take(12)
      .toList()
    if (requests.isEmpty()) return
    viewModelScope.launch {
      try {
        val resolved = supervisorScope {
          requests.map { item ->
            async {
              val logo = apiClient.fetchDetails(item.type, item.id, item.title, item.year).getOrNull()?.titleLogo?.takeIf { it.isNotBlank() }
              homeHeroMediaKey(item) to logo
            }
          }.awaitAll().toMap()
        }
        val succeeded = resolved.filterValues { !it.isNullOrBlank() }.mapValues { it.value!! }
        if (succeeded.isNotEmpty()) uiState = uiState.copy(homeHeroTitleLogos = uiState.homeHeroTitleLogos + succeeded)
        resolved.keys.filter { it !in succeeded }.forEach { heroLogoFailedKeys.add(it) }
      } finally {
        requests.forEach { pendingHomeHeroLogoKeys.remove(homeHeroMediaKey(it)) }
      }
    }
  }

  // Third-party addon catalogs rarely carry ratings, so resolve TMDB scores for
  // their items on demand (same batched/cached approach as hero title logos).
  fun resolveAddonCatalogRatings(items: List<MediaItem>) {
    if (!uiState.ratingsEnabled) return
    val requests = items
      .asSequence()
      .filter { it.sourceAddonId != null && it.rating == null && !it.isLiveCatalogItem() }
      .distinctBy(::homeHeroMediaKey)
      .filter { homeHeroMediaKey(it) !in uiState.addonCatalogRatings }
      .filter { homeHeroMediaKey(it) !in addonRatingFailedKeys }
      .filter { pendingAddonRatingKeys.add(homeHeroMediaKey(it)) }
      .take(12)
      .toList()
    if (requests.isEmpty()) return
    viewModelScope.launch {
      try {
        val resolved = supervisorScope {
          requests.map { item ->
            async {
              val rating = apiClient.fetchDetails(item.type, item.id, item.title, item.year).getOrNull()
                ?.let { it.tmdbRating ?: it.rating }
                ?.takeIf { it > 0.0 }
              homeHeroMediaKey(item) to rating
            }
          }.awaitAll().toMap()
        }
        val succeeded = resolved.filterValues { it != null }.mapValues { it.value!! }
        if (succeeded.isNotEmpty()) uiState = uiState.copy(addonCatalogRatings = uiState.addonCatalogRatings + succeeded)
        resolved.keys.filter { it !in succeeded }.forEach { addonRatingFailedKeys.add(it) }
      } finally {
        requests.forEach { pendingAddonRatingKeys.remove(homeHeroMediaKey(it)) }
      }
    }
  }

  fun search(query: String) {
    val normalized = query.trim()
    if (normalized.length < 2) return
    val generation = ++searchRequestGeneration
    uiState = uiState.copy(searchLoading = true, errorMessage = null)
    viewModelScope.launch {
      apiClient.search(normalized)
        .onSuccess { page ->
          if (generation == searchRequestGeneration) {
            uiState = uiState.copy(searchLoading = false, searchResults = page.items, searchResultQuery = normalized)
            // Counts the catalogue search only. Add-on catalogues answer separately and later,
            // so folding them in here would report a number that was not true when it was
            // recorded. The query text is never sent.
            Telemetry.searchPerformed(page.items.size)
          }
        }
        .onFailure { error ->
          if (generation == searchRequestGeneration) {
            uiState = uiState.copy(searchLoading = false, searchResultQuery = normalized, errorMessage = error.message ?: "Search failed.")
          }
        }
    }
    searchInstalledAddons(normalized, generation)
  }

  /**
   * Asks every enabled add-on catalog that advertises search to answer the same query.
   *
   * Runs alongside the TMDB search rather than after it: the two answer different questions, and
   * an add-on's live channels exist in neither TMDB nor any list the app already holds. Failures
   * are silent per add-on — one unreachable add-on must not turn a search that found things into
   * an error.
   */
  private fun searchInstalledAddons(query: String, generation: Long) {
    val searchable = uiState.addons
      .filter { it.enabled }
      .flatMap { addon -> addon.manifest.catalogs.filter { it.supportsSearch }.map { addon to it } }
    if (searchable.isEmpty()) {
      uiState = uiState.copy(addonSearchResults = emptyList(), addonSearchLoading = false)
      return
    }
    uiState = uiState.copy(addonSearchLoading = true)
    viewModelScope.launch {
      val gate = Semaphore(5)
      val results = supervisorScope {
        searchable.map { (addon, catalog) ->
          async(Dispatchers.IO) {
            gate.withPermit {
              apiClient.searchAddonCatalog(addon, catalog, query)
                // Logged rather than swallowed silently: a catalog answering 404 for every query
                // is indistinguishable from one that simply has no matches, which is how a
                // malformed request URL went unnoticed until an add-on was tested by hand.
                .onFailure { Log.w("StreamDekAddonSearch", "${addon.manifest.name}/${catalog.id} search failed", it) }
                .getOrDefault(emptyList())
            }
          }
        }.awaitAll().flatten()
      }
      if (generation != searchRequestGeneration) return@launch
      // Add-ons answer their own way, and some ignore the query and return a default listing, so
      // the results are matched against the query here too rather than trusted wholesale.
      val relevant = withContext(Dispatchers.Default) {
        results.filter { it.playlistSearchRank(query) != null }.distinctBy { "${it.type}-${it.id}" }
      }
      uiState = uiState.copy(addonSearchResults = relevant, addonSearchLoading = false)
    }
  }

  /**
   * Pages in more items for a "View All" row. For add-on catalog rows, [anchorItem] carries
   * sourceAddonId/sourceCatalogType/sourceCatalogId/sourceCatalogGenre identifying which add-on
   * catalog to re-query, and [skip] is the number of items already shown for it (Stremio-style
   * item offset). Built-in TMDB rows (New Movies, Trending, ...) don't have an add-on source —
   * those items carry no sourceAddonId — so they're identified by [rowId] instead and paged by
   * TMDB page number (TMDB's default page size is 20, which is exactly why "View All" used to
   * cap at 20 items with no way to load more).
   * Returns an empty list (never throws) when the row has no re-queryable source at all (e.g.
   * Continue Watching, Watchlist, Trakt recommendations) or the add-on is no longer
   * installed/enabled.
   */
  suspend fun loadMoreRowItems(rowId: String, anchorItem: MediaItem?, skip: Int): List<MediaItem> {
    val addonId = anchorItem?.sourceAddonId
    val fetched = if (addonId != null) {
      val addon = uiState.addons.firstOrNull { it.id == addonId && it.enabled }
      if (addon == null) {
        android.util.Log.d("StreamDekPaging", "loadMoreRowItems row=$rowId: addon $addonId not found/enabled")
        emptyList()
      } else {
        val catalogType = anchorItem.sourceCatalogType
        val catalogId = anchorItem.sourceCatalogId
        if (catalogType == null || catalogId == null) {
          android.util.Log.d("StreamDekPaging", "loadMoreRowItems row=$rowId: missing catalogType/catalogId on anchor")
          emptyList()
        } else {
          val catalogName = anchorItem.sourceCatalogName ?: catalogType
          android.util.Log.d("StreamDekPaging", "loadMoreRowItems row=$rowId: addon-catalog path addon=$addonId type=$catalogType catalogId=$catalogId genre=${anchorItem.sourceCatalogGenre} skip=$skip")
          apiClient.fetchMoreCatalogItems(uiState.session, addon, catalogType, catalogId, catalogName, anchorItem.sourceCatalogGenre, skip, uiState.activeProfileId)
            .onFailure { android.util.Log.w("StreamDekPaging", "fetchMoreCatalogItems failed row=$rowId", it) }
            .onSuccess { android.util.Log.d("StreamDekPaging", "fetchMoreCatalogItems row=$rowId returned ${it.size}") }
            .getOrDefault(emptyList())
        }
      }
    } else {
      // Default catalog rows page by page number. The cursor comes from the backend rather than
      // from the item count: a home preview is not always exactly one page (a row short on titles
      // the viewer has not already seen reads further into its catalog), so dividing by the page
      // size would either re-request a page or skip one.
      val page = uiState.catalogNextPages[rowId] ?: ((skip / CATALOG_PAGE_SIZE) + 1)
      android.util.Log.d("StreamDekPaging", "loadMoreRowItems row=$rowId: default catalog path page=$page skip=$skip")
      apiClient.fetchCatalogPage(rowId, page)
        .onFailure { android.util.Log.w("StreamDekPaging", "fetchCatalogPage failed row=$rowId page=$page", it) }
        .onSuccess { result ->
          android.util.Log.d("StreamDekPaging", "fetchCatalogPage row=$rowId page=$page returned ${result.items.size}")
          // Only a page that produced something moves the cursor on; an empty answer means the
          // end of the catalog, and "View All" stops asking.
          if (result.items.isNotEmpty()) {
            uiState = uiState.copy(catalogNextPages = uiState.catalogNextPages + (rowId to page + 1))
          }
        }
        .map { it.items }
        .getOrDefault(emptyList())
    }
    if (uiState.browseRow?.id == rowId && fetched.isNotEmpty()) {
      uiState = uiState.copy(browseLoadedItems = (uiState.browseLoadedItems + fetched).distinctBy { "${it.type}-${it.id}" })
    }
    return fetched
  }
  fun resumeContinueWatching(item: MediaItem, onUnavailable: () -> Unit): Boolean {
    if (uiState.playerLaunching) return true
    // streamLoading is also used by an ordinary detail page. It can still be true after the
    // viewer has returned Home, and must not turn a Continue Watching tap into a silent no-op.
    // Likewise, retire an orphaned resume left by a failed/empty metadata response before starting
    // the newly requested title.
    if (pendingDirectContinueEntry != null) invalidatePendingPlaybackRequest()
    val ownerKey = activeOwnerKey() ?: GUEST_OWNER_KEY
    // Downloads saved before the media record existed are keyed by download id. Those play from
    // disk directly — sending that id through loadDetail is what opened an unrelated title.
    if (isDownloadMediaId(item.id) && playSavedDownload(item.id, ownerKey)) return true
    val candidates = playbackResumeStore.loadAll(ownerKey)
      .filter { it.mediaId == item.id && normalizedMediaType(it.mediaType) == normalizedMediaType(item.type) && !it.isLive }
    val entry = candidates.firstOrNull {
      item.resumeSeasonNumber != null && item.resumeEpisodeNumber != null &&
        it.seasonNumber == item.resumeSeasonNumber && it.episodeNumber == item.resumeEpisodeNumber
    } ?: candidates.maxByOrNull { it.updatedAt }
      ?: return false
    Log.i(
      "StreamDekPlayback",
      "[ContinueWatching] contentId=${entry.mediaId} contentType=${entry.mediaType} season=${entry.seasonNumber} episode=${entry.episodeNumber} originDevice=${entry.lastPlatform ?: "mobile"} destinationDevice=mobile resumePosition=${entry.positionSeconds ?: 0.0}",
    )
    pendingDirectContinueEntry = entry
    pendingDirectContinueFallback = onUnavailable
    pendingDirectContinueEpisode = continueFallbackEpisode(
      item.copy(
        // The stored entry is the authority on where the viewer actually got to; the card only
        // carries it when it was built from that same entry.
        resumeSeasonNumber = entry.seasonNumber ?: item.resumeSeasonNumber,
        resumeEpisodeNumber = entry.episodeNumber ?: item.resumeEpisodeNumber,
      ),
    )
    uiState = uiState.copy(
      playerLaunchSession = PlayerSession(
        url = "",
        title = sanitizeDisplayText(item.title).orEmpty(),
        subtitle = sanitizeDisplayText(item.cardSubtitle ?: item.year),
        sourceLabel = "Finding a source…",
        backdrop = item.backdrop ?: item.poster,
        poster = item.poster,
        synopsis = sanitizeDisplayText(item.description),
        mediaId = item.id,
        mediaType = item.type,
        seasonNumber = item.resumeSeasonNumber,
        episodeNumber = item.resumeEpisodeNumber,
      ),
      playerLaunching = true,
      playerLaunchingLabel = "Finding a source…",
      errorMessage = null,
    )
    loadDetail(item.type, item.id, item, preservePendingContinue = true)
    return true
  }

  private fun playPendingContinue(detail: MediaDetail, episode: EpisodeItem?): Boolean {
    // Never take the player away from something already on screen. A resume entry is queued when
    // a Continue Watching card is tapped and consumed when that title's detail finishes loading —
    // if the viewer has started watching something else in the meantime, that load arriving is no
    // reason to yank them into a different title mid-playback.
    uiState.playerSession?.let { active -> if (active.mediaId != detail.id) return false }
    val pending = pendingDirectContinueEntry ?: return false
    val matchesDetail =
      (pending.mediaId == detail.id || pending.mediaId == uiState.detailFallbackItem?.id) &&
        normalizedMediaType(pending.mediaType) == normalizedMediaType(detail.type)
    if (!matchesDetail) {
      // A metadata response that no longer belongs to the requested card must not leave the
      // full-screen launch state (and every later Continue Watching tap) locked indefinitely.
      invalidatePendingPlaybackRequest()
      uiState = uiState.copy(
        playerLaunchSession = null,
        playerLaunching = false,
        playerLaunchingLabel = null,
        streamLoading = false,
      )
      return false
    }
    val entry = pending
    pendingDirectContinueEntry = null
    val stream = entry.stream
    if (stream == null && progressCameFromAnotherPlatform(entry.lastPlatform, destination = "mobile")) {
      val showDetails = pendingDirectContinueFallback
      pendingDirectContinueFallback = null
      pendingDirectContinueEpisode = null
      uiState = uiState.copy(
        playerLaunchSession = null,
        playerLaunching = false,
        playerLaunchingLabel = null,
        streamLoading = false,
        infoMessage = crossDeviceContinueNotice(detail.type, episode?.seasonNumber, episode?.episodeNumber),
      )
      showDetails?.invoke()
      loadStreamsForCurrentDetail(episode)
      return true
    }
    if (stream != null && (!stream.url.isNullOrBlank() || !stream.infoHash.isNullOrBlank())) {
      playStream(stream, episode, entry.progressPercent)
    } else {
      // Cross-device SyncDek rows intentionally have no stream URL. Resolve through the same
      // device-local pipeline as Play; playStream will read this exact entry's resume position.
      uiState = uiState.copy(playerLaunching = true, playerLaunchingLabel = "Finding a source…")
      playBestStream(episode)
    }
    return true
  }

  private fun continueFallbackEpisode(item: MediaItem?): EpisodeItem? {
    val season = item?.resumeSeasonNumber ?: return null
    val episode = item.resumeEpisodeNumber ?: return null
    return EpisodeItem(
      id = "${item.id}:$season:$episode",
      episodeNumber = episode,
      seasonNumber = season,
      name = "Episode $episode",
      overview = "",
      still = null,
      runtime = null,
    )
  }
  /**
   * Plays a download by its download id, resuming where it was left off. Returns false when no
   * completed download matches, and reports it — the id cannot be looked up anywhere else.
   */
  private fun playSavedDownload(downloadId: String, ownerKey: String): Boolean {
    refreshDownloads()
    val download = uiState.downloads.firstOrNull { it.id == downloadId && it.state == DownloadState.COMPLETED }
    if (download == null) {
      uiState = uiState.copy(errorMessage = "That download is no longer on this device.")
      return true
    }
    val progress = playbackResumeStore.loadAll(ownerKey)
      .filter { it.mediaId == downloadId && !it.isLive }
      .maxByOrNull { it.updatedAt }
      ?.progressPercent
      ?: 0.0
    playDownload(download, progress)
    return true
  }

  fun loadDetail(type: String, id: String, fallbackItem: MediaItem? = null, preservePendingContinue: Boolean = false) {
    // A download id has no catalogue entry behind it. Looking one up returned whatever the id
    // happened to match, which is how tapping a downloaded title opened a different one.
    if (isDownloadMediaId(id)) {
      playSavedDownload(id, activeOwnerKey() ?: GUEST_OWNER_KEY)
      return
    }
    if (!preservePendingContinue) {
      // A resolver launched by the title the viewer just left can still complete at the network
      // layer. Retire its ownership before changing detail identity so its callback cannot open a
      // player or borrow metadata from this newly opened title.
      invalidatePendingPlaybackRequest()
    }
    // A fresh correlation id per title opened; every stage that follows carries it.
    detailCorrelationId = Telemetry.newCorrelationId()
    Telemetry.contentOpened(mediaId = id, mediaType = type, title = fallbackItem?.title)
    val detailIsLive = fallbackItem?.isLiveCatalogItem() == true
    detailSourceAddonId = fallbackItem?.sourceAddonId
    detailSourceCatalogType = fallbackItem?.sourceCatalogType
    val detailGeneration = ++detailRequestGeneration
    detailSettleJob?.cancel()
    detailLocalStreamId = null
    detailAddonMetaId = null
    detailLocalEpisodes = emptyList()
    detailDirectStream = fallbackItem?.directStreamUrl?.let { url ->
      val addon = uiState.addons.firstOrNull { it.id == fallbackItem.sourceAddonId }
      AddonStream(
        addonId = fallbackItem.sourceAddonId.orEmpty(),
        addonName = addon?.manifest?.name ?: "Sports source",
        name = fallbackItem.title,
        title = fallbackItem.title,
        description = fallbackItem.description.ifBlank { null },
        url = url,
        infoHash = null,
        fileIdx = null,
        filename = null,
        quality = null,
        size = null,
        cachedBy = emptyList(),
        requestHeaders = fallbackItem.requestHeaders,
        drmLicenseType = fallbackItem.drmLicenseType,
        drmClearKeys = fallbackItem.drmClearKeys,
      )
    }
    if (detailIsLive && fallbackItem != null) {
      loadPlayerLiveChannels(fallbackItem)
      val fallback = fallbackItem.toFallbackDetail()
      uiState = uiState.copy(
        detailLoading = false, detail = fallback, detailIsLive = true, detailFallbackItem = fallbackItem, selectedPerson = null, personLoading = false,
        selectedSeasonEpisodes = emptyList(), selectedSeasonNumber = null, selectedEpisode = null,
        detailSelectedTab = null, pendingStreamSources = 0, totalStreamSources = 0, searchingStreamSources = emptyList(), failedStreamSources = emptyList(), streamRefreshing = false, streamSearchStarted = false, availableStreams = emptyList(), errorMessage = null,
      )
      loadStreamsForCurrentDetail(null)
      return
    }
    // Ask the add-on that produced this card to describe it, whenever it publishes a `meta`
    // resource. That covers two cases with one path: a local bridge, whose catalog previews are
    // deliberately tiny and whose episode ids are opaque; and a metadata add-on, whose ids TMDB
    // cannot resolve at all. TMDB enrichment is still layered on top of whatever comes back.
    val metaAddon = fallbackItem?.sourceAddonId?.let { addonId ->
      uiState.addons.firstOrNull {
        it.id == addonId && (LocalAddonManager.isLocalAddonId(it.id) || it.manifest.providesMetaFor(type))
      }
    }
    if (metaAddon != null && fallbackItem != null) {
      val isLocalMetaAddon = LocalAddonManager.isLocalAddonId(metaAddon.id)
      val metaRequestType = addonMetaRequestType(type, fallbackItem.sourceCatalogType)
      launchWork(
        onStart = { uiState = uiState.copy(detailLoading = true, detail = null, detailIsLive = false, detailFallbackItem = fallbackItem, selectedPerson = null, personLoading = false, selectedSeasonEpisodes = emptyList(), selectedSeasonNumber = null, selectedEpisode = null, detailSelectedTab = null, pendingStreamSources = 0, totalStreamSources = 0, searchingStreamSources = emptyList(), failedStreamSources = emptyList(), streamRefreshing = false, streamSearchStarted = false, availableStreams = emptyList(), errorMessage = null) },
        block = {
          val addon = uiState.addons.firstOrNull { it.id == metaAddon.id }
            ?: return@launchWork Result.failure(IllegalStateException("That add-on is no longer installed."))
          val rawMeta = apiClient
            .fetchAddonMeta(uiState.session, uiState.activeProfileId, addon, metaRequestType, id)
            .getOrThrow()
          // An add-on that advertises `meta` but cannot describe this item is treated as though it
          // had not answered: the card's own id is what TMDB and the stream add-ons get.
          val bridgeMeta = rawMeta.takeIf { isUsableAddonMeta(it, id, isLocalMetaAddon) }
          val lookupId = bridgeMeta?.let { it.imdbId ?: it.id } ?: id
          val typeGuesses = when {
            bridgeMeta == null -> if (normalizedMediaType(type) == "tv") listOf("tv", "movie") else listOf("movie", "tv")
            bridgeMeta.episodes.isNotEmpty() || bridgeMeta.type in setOf("tv", "series", "show") -> listOf("tv", "movie")
            bridgeMeta.type == "movie" -> listOf("movie", "tv")
            else -> listOf("movie", "tv")
          }
          val enriched = coroutineScope {
            val guessResults = typeGuesses.map { guess ->
              async {
                apiClient.fetchDetails(
                  guess,
                  lookupId,
                  bridgeMeta?.title ?: fallbackItem.title,
                  bridgeMeta?.year ?: fallbackItem.year,
                ).getOrNull()
              }
            }.awaitAll()
            guessResults.firstNotNullOfOrNull { it }
          }
          Result.success(bridgeMeta to enriched)
        },
        onSuccess = { (bridgeMeta, enriched) ->
          if (detailGeneration != detailRequestGeneration) return@launchWork
          // A local bridge's id replaces the stream lookup outright — that is the only id its own
          // /stream endpoint answers to. A remote metadata add-on's id is only a fallback: stream
          // add-ons key on IMDb ids, which enrichment has just resolved. When the add-on could not
          // describe the item at all, the card's own id stands and nothing is overridden.
          if (isLocalMetaAddon) detailLocalStreamId = bridgeMeta?.id ?: id else detailAddonMetaId = bridgeMeta?.id
          detailLocalEpisodes = bridgeMeta?.episodes.orEmpty()
          val resolvedDetail = (
            enriched?.let { if (bridgeMeta != null) it.withLocalAddonMeta(bridgeMeta) else it }
              ?: bridgeMeta?.toFallbackDetail(fallbackItem)
              ?: fallbackItem.toFallbackDetail()
            ).withCatalogFallback(fallbackItem)
          val unreleasedMovie = resolvedDetail.type == "movie" && isFutureReleaseDate(resolvedDetail.releaseDate)
          uiState = uiState.copy(
            detailLoading = false,
            detail = resolvedDetail,
            detailIsLive = false,
            streamLoading = false,
            pendingStreamSources = 0, totalStreamSources = 0, searchingStreamSources = emptyList(), failedStreamSources = emptyList(), streamRefreshing = false, streamSearchStarted = false,
            errorMessage = null,
            availableStreams = if (unreleasedMovie) emptyList() else uiState.availableStreams,
          )
          if (enriched != null) {
            refreshExternalRatings(resolvedDetail)
            refreshTraktComments(resolvedDetail)
          }
          if (resolvedDetail.type == "tv" && resolvedDetail.seasons.isNotEmpty()) {
            loadResumeAwareSeries(
              resolvedDetail,
              fallbackItem.resumeSeasonNumber,
              fallbackItem.resumeEpisodeNumber,
              resumeKnownSource = pendingDirectContinueEntry != null,
            )
          } else if (!unreleasedMovie) {
            if (!playPendingContinue(resolvedDetail, continueFallbackEpisode(fallbackItem))) loadStreamsAfterDetailSettles(null)
          }
        },
        onFailure = {
          if (detailGeneration != detailRequestGeneration) return@launchWork
          if (isLocalMetaAddon) detailLocalStreamId = id else detailAddonMetaId = id
          detailLocalEpisodes = emptyList()
          val fallback = fallbackItem.toFallbackDetail()
          uiState = uiState.copy(detailLoading = false, detail = fallback, detailIsLive = false, errorMessage = null)
          if (!playPendingContinue(fallback, continueFallbackEpisode(fallbackItem))) loadStreamsAfterDetailSettles(null)
        },
      )
      return
    }
    launchWork(
      onStart = { uiState = uiState.copy(detailLoading = true, detail = null, detailIsLive = detailIsLive, detailFallbackItem = fallbackItem, selectedPerson = null, personLoading = false, selectedSeasonEpisodes = emptyList(), selectedSeasonNumber = null, selectedEpisode = null, detailSelectedTab = null, pendingStreamSources = 0, totalStreamSources = 0, searchingStreamSources = emptyList(), failedStreamSources = emptyList(), streamRefreshing = false, streamSearchStarted = false, availableStreams = emptyList(), errorMessage = null) },
      block = { apiClient.fetchDetails(type, id, fallbackItem?.title, fallbackItem?.year) },
      onSuccess = { detail ->
        if (detailGeneration != detailRequestGeneration) return@launchWork
        val resolvedDetail = detail.withCatalogFallback(fallbackItem)
        val unreleasedMovie = resolvedDetail.type == "movie" && isFutureReleaseDate(resolvedDetail.releaseDate)
        uiState = uiState.copy(
          detailLoading = false,
          detail = resolvedDetail,
          detailIsLive = detailIsLive,
          streamLoading = false,
          pendingStreamSources = 0, totalStreamSources = 0, searchingStreamSources = emptyList(), failedStreamSources = emptyList(), streamRefreshing = false, streamSearchStarted = false,
          availableStreams = if (unreleasedMovie) emptyList() else uiState.availableStreams,
        )
        refreshExternalRatings(resolvedDetail)
        refreshTraktComments(resolvedDetail)
        if (resolvedDetail.type == "tv" && resolvedDetail.seasons.isNotEmpty()) {
          loadResumeAwareSeries(
            resolvedDetail,
            fallbackItem?.resumeSeasonNumber,
            fallbackItem?.resumeEpisodeNumber,
            resumeKnownSource = pendingDirectContinueEntry != null,
          )
        } else if (!unreleasedMovie) {
          if (!playPendingContinue(resolvedDetail, continueFallbackEpisode(fallbackItem))) loadStreamsAfterDetailSettles(null)
        }
      },
      onFailure = { message ->
        if (detailGeneration != detailRequestGeneration) return@launchWork
        val fallback = fallbackItem?.toFallbackDetail()
        if (fallback != null) {
          uiState = uiState.copy(detailLoading = false, detail = fallback, detailIsLive = detailIsLive, errorMessage = null)
          if (!playPendingContinue(fallback, continueFallbackEpisode(fallbackItem))) loadStreamsAfterDetailSettles(null)
        } else {
          uiState = uiState.copy(detailLoading = false, errorMessage = message)
        }
      },
    )
  }

  fun openPerson(person: CastMember) {
    if (person.id.isBlank()) {
      uiState = uiState.copy(
        selectedPerson = PersonDetail(
          id = person.id,
          name = person.name,
          photo = person.photo,
          biography = null,
          birthday = null,
          placeOfBirth = null,
          knownFor = person.character,
        ),
      )
      return
    }
    launchWork(
      onStart = { uiState = uiState.copy(personLoading = true, errorMessage = null) },
      block = { apiClient.fetchPerson(person.id) },
      onSuccess = { detail -> uiState = uiState.copy(personLoading = false, selectedPerson = detail) },
      onFailure = {
        uiState = uiState.copy(
          personLoading = false,
          selectedPerson = PersonDetail(
            id = person.id,
            name = person.name,
            photo = person.photo,
            biography = null,
            birthday = null,
            placeOfBirth = null,
            knownFor = person.character,
          ),
        )
      },
    )
  }

  fun closePerson() { uiState = uiState.copy(selectedPerson = null, personLoading = false) }
  fun loadSeason(tvId: String, seasonNumber: Int, preferredEpisodeNumber: Int? = null, resumeKnownSource: Boolean = false) {
    if (detailLocalEpisodes.isNotEmpty()) {
      val episodes = detailLocalEpisodes.filter { it.seasonNumber == seasonNumber }.sortedBy(EpisodeItem::episodeNumber)
      uiState = uiState.copy(seasonLoading = false, selectedSeasonEpisodes = episodes, selectedSeasonNumber = seasonNumber, errorMessage = null)
      val episode = episodes.firstOrNull { it.episodeNumber == preferredEpisodeNumber }
        ?: episodes.firstOrNull()
        ?: pendingDirectContinueEpisode?.takeIf { it.seasonNumber == seasonNumber }
      episode?.let {
        if (!resumeKnownSource || !playPendingContinue(uiState.detail ?: return@let, it)) loadStreamsForCurrentDetail(it)
      }
      return
    }
    launchWork(
      onStart = { uiState = uiState.copy(seasonLoading = true, selectedSeasonNumber = seasonNumber, errorMessage = null) },
      block = { apiClient.fetchSeason(tvId, seasonNumber) },
      onSuccess = { episodes ->
        uiState = uiState.copy(seasonLoading = false, selectedSeasonEpisodes = episodes, selectedSeasonNumber = seasonNumber)
        val episode = episodes.firstOrNull { it.episodeNumber == preferredEpisodeNumber }
          ?: episodes.firstOrNull()
          ?: pendingDirectContinueEpisode?.takeIf { it.seasonNumber == seasonNumber }
        episode?.let {
          if (!resumeKnownSource || !playPendingContinue(uiState.detail ?: return@let, it)) loadStreamsForCurrentDetail(it)
        }
      },
      onFailure = { message ->
        val detail = uiState.detail
        val fallbackEpisode = pendingDirectContinueEpisode?.takeIf { it.seasonNumber == seasonNumber }
        if (resumeKnownSource && detail != null && fallbackEpisode != null && playPendingContinue(detail, fallbackEpisode)) {
          uiState = uiState.copy(seasonLoading = false, errorMessage = null)
        } else {
          invalidatePendingPlaybackRequest()
          uiState = uiState.copy(
            seasonLoading = false,
            playerLaunchSession = null,
            playerLaunching = false,
            playerLaunchingLabel = null,
            streamLoading = false,
            errorMessage = message,
          )
        }
      },
    )
  }

  private fun streamLookupIds(detail: MediaDetail): List<String> {
    // Local add-on items keep detail.id as the TMDB id (for season/rating/Trakt calls) once
    // enrichment succeeds, but the add-on's own /stream endpoint needs its own canonical id --
    // tracked separately since it can differ completely from whatever TMDB resolved to.
    detailLocalStreamId?.takeIf { it.isNotBlank() }?.let { return listOf(it) }
    val imdbId = detail.imdbId?.let { Regex("tt\\d+", RegexOption.IGNORE_CASE).find(it)?.value }
    return listOfNotNull(imdbId ?: detail.id.takeIf(String::isNotBlank)) +
      listOfNotNull(detailAddonMetaId?.takeIf { it.isNotBlank() })
  }

  /**
   * Starts the first stream search once the page it belongs to has had a chance to draw.
   *
   * Opening a detail used to kick off everything at once: TMDB detail, artwork, cast, ratings,
   * Trakt comments, the hero trailer, and a stream search that fans out across every add-on plus
   * one QuickJS engine per enabled plugin. All of it competed for the same CPU and network while
   * the page was still composing, so the content the viewer is actually looking at came in last.
   *
   * Only the automatic search on open is deferred. Reload, picking an episode and choosing a
   * season all still fire immediately — those are direct responses to a tap and any delay there
   * would read as lag.
   */
  private fun loadStreamsAfterDetailSettles(episode: EpisodeItem? = null) {
    detailSettleJob?.cancel()
    detailSettleJob = viewModelScope.launch {
      delay(DETAIL_SOURCES_DELAY_MS)
      loadStreamsForCurrentDetail(episode)
    }
  }

  fun loadStreamsForCurrentDetail(episode: EpisodeItem? = null) {
    val detail = uiState.detail ?: return
    if (detail.type == "movie" && isFutureReleaseDate(detail.releaseDate)) {
      pendingStreamLoad = null
      uiState = uiState.copy(streamLoading = false, pendingStreamSources = 0, totalStreamSources = 0, searchingStreamSources = emptyList(), failedStreamSources = emptyList(), streamRefreshing = false, streamSearchStarted = true, availableStreams = emptyList(), selectedEpisode = null, errorMessage = null)
      return
    }
    if (uiState.addonsLoading) {
      pendingStreamLoad = PendingStreamLoad(detail.id, episode)
      uiState = uiState.copy(streamLoading = true, pendingStreamSources = 0, totalStreamSources = 0, searchingStreamSources = emptyList(), failedStreamSources = emptyList(), streamRefreshing = false, streamSearchStarted = false, selectedEpisode = episode, errorMessage = null, streamsUnavailableReason = null)
      return
    }
    pendingStreamLoad = null
    detailDirectStream?.let { stream ->
      uiState = uiState.copy(streamLoading = false, pendingStreamSources = 0, totalStreamSources = 0, searchingStreamSources = emptyList(), failedStreamSources = emptyList(), streamRefreshing = false, streamSearchStarted = true, availableStreams = listOf(stream), selectedEpisode = episode, errorMessage = null)
      return
    }
    val type: String
    val ids: List<String>
    when {
      detail.type == "tv" && episode != null -> {
        val bridgeEpisodeId = episode.sourceStreamId?.takeIf { it.isNotBlank() }
        type = if (bridgeEpisodeId != null) detailSourceCatalogType ?: "series" else "series"
        ids = if (bridgeEpisodeId != null) {
          listOf(bridgeEpisodeId)
        } else {
          streamLookupIds(detail)
            .distinct()
            .map { "${it}:${episode.seasonNumber}:${episode.episodeNumber}" }
        }
      }
      detail.type == "tv" && !uiState.detailIsLive -> {
        uiState = uiState.copy(streamLoading = false, pendingStreamSources = 0, totalStreamSources = 0, searchingStreamSources = emptyList(), failedStreamSources = emptyList(), streamRefreshing = false, streamSearchStarted = true, errorMessage = "Choose an episode first.")
        return
      }
      else -> {
        val localBridgeType = detailSourceAddonId
          ?.takeIf(LocalAddonManager::isLocalAddonId)
          ?.let { detailSourceCatalogType }
        type = if (uiState.detailIsLive) detailSourceCatalogType ?: detail.type else localBridgeType ?: detail.type
        ids = streamLookupIds(detail).distinct()
      }
    }
    beginProgressiveStreamLoad(detail = detail, type = type, ids = ids, episode = episode)
  }

  private fun beginProgressiveStreamLoad(detail: MediaDetail, type: String, ids: List<String>, episode: EpisodeItem?) {
    val candidates = ids.filter { it.isNotBlank() }.distinct()
    if (candidates.isEmpty()) {
      uiState = uiState.copy(streamLoading = false, pendingStreamSources = 0, totalStreamSources = 0, searchingStreamSources = emptyList(), failedStreamSources = emptyList(), streamRefreshing = false, streamSearchStarted = true, availableStreams = emptyList(), selectedEpisode = episode, errorMessage = "No stream identifiers were available for this title.")
      return
    }

    val enabledAddons = uiState.addons
      .filter { addon ->
        if (!addon.enabled) return@filter false
        if (uiState.detailIsLive) {
          // Prefer the add-on the channel came from; otherwise only ask add-ons that
          // actually serve live TV. Movie/series add-ons are never queried here.
          if (detailSourceAddonId != null) addon.id == detailSourceAddonId else addonSupportsLiveStreams(addon)
        } else {
          addonSupportsStreamType(addon, type)
        }
      }
      .sortedWith(compareByDescending<InstalledAddon> { it.favourite }.thenBy { it.position })
    val pluginState = StreamDekPlugins.manager.state
    val enabledPluginRepos = pluginState.repos.filter { it.enabled }.mapTo(mutableSetOf()) { it.url }
    val pluginSourceCount = if (!uiState.detailIsLive && pluginState.enabled && pluginState.providers.any { it.enabled && it.repoUrl in enabledPluginRepos }) 1 else 0
    // CloudStream providers scrape by title, so they need a resolved one; and like the JS plugins
    // they are movie/series scrapers rather than a source for live channels.
    val cloudStreamTitle = sanitizeDisplayText(detail.title)?.takeIf { it.isNotBlank() && !uiState.detailIsLive }
    val cloudStreamProviders = if (cloudStreamTitle == null || !CloudStreamPlugins.isInitialized) {
      emptyList()
    } else {
      runCatching { CloudStreamPlugins.manager.activeProviders() }.getOrDefault(emptyList())
    }
    val cloudStreamSourceCount = if (cloudStreamProviders.isEmpty()) 0 else 1
    // SkyStream plugins scrape by title, like the CloudStream ones — an IMDb id is only useful to
    // the handful that proxy an id-keyed service, so it is passed along but not required.
    val skyStreamImdbId = detail.imdbId?.let { Regex("tt\\d+", RegexOption.IGNORE_CASE).find(it)?.value }
    val skyStreamSourceCount = if (
      cloudStreamTitle == null ||
      !SkyStreamPlugins.isInitialized ||
      runCatching { SkyStreamPlugins.manager.activeProviders() }.getOrDefault(emptyList()).isEmpty()
    ) 0 else 1
    val totalSources = candidates.size * enabledAddons.size + pluginSourceCount + cloudStreamSourceCount + skyStreamSourceCount
    val generation = ++streamRequestGeneration
    val merged = linkedMapOf<String, AddonStream>()
    val requestGate = Semaphore(4)
    var completedSources = 0
    var lastError: Throwable? = null
    // What is still being waited on, by name, so the page can say which sources have not answered
    // rather than only how many. Add-ons are named once however many ids they are asked about —
    // "PenguPlay" twice in a status line describes nothing.
    val pendingSourceNames = linkedMapOf<String, Int>()
    val failedSourceNames = linkedSetOf<String>()
    fun beginSource(label: String) {
      pendingSourceNames[label] = (pendingSourceNames[label] ?: 0) + 1
    }
    fun endSource(label: String, failed: Boolean) {
      val outstanding = (pendingSourceNames[label] ?: 0) - 1
      if (outstanding <= 0) pendingSourceNames.remove(label) else pendingSourceNames[label] = outstanding
      if (failed) failedSourceNames += label
      completedSources += 1
    }
    if (pluginSourceCount > 0) beginSource(PLUGIN_SOURCE_LABEL)
    if (skyStreamSourceCount > 0) beginSource(SKYSTREAM_SOURCE_LABEL)
    if (cloudStreamSourceCount > 0) beginSource(CLOUDSTREAM_SOURCE_LABEL)
    repeat(candidates.size) { enabledAddons.forEach { addon -> beginSource(addon.manifest.name.ifBlank { addon.id }) } }

    // A re-run over results that are already on screen is a refresh, not a fresh search, so the
    // list stays put until the new one has something to put in its place. Blanking it first threw
    // away what the viewer was reading and made every refresh look like a failure until it wasn't.
    val retained = if (uiState.availableStreams.isNotEmpty() && uiState.selectedEpisode?.id == episode?.id) {
      uiState.availableStreams
    } else {
      emptyList()
    }

    fun streamKey(stream: AddonStream): String = addonStreamPlaybackIdentity(stream)

    fun publish() {
      if (generation != streamRequestGeneration) return
      val ranked = rankedProfileStreams(mediaStreamsOnly(merged.values.toList(), detail))
      val remaining = (totalSources - completedSources).coerceAtLeast(0)
      val holding = ranked.isEmpty() && retained.isNotEmpty() && remaining > 0
      uiState = uiState.copy(
        streamLoading = remaining > 0,
        pendingStreamSources = remaining,
        totalStreamSources = totalSources,
        searchingStreamSources = pendingSourceNames.keys.toList(),
        failedStreamSources = failedSourceNames.toList(),
        streamRefreshing = holding,
        availableStreams = if (holding) retained else ranked,
        selectedEpisode = episode,
      )
    }

    uiState = uiState.copy(
      streamLoading = true,
      pendingStreamSources = totalSources,
      totalStreamSources = totalSources,
      searchingStreamSources = pendingSourceNames.keys.toList(),
      failedStreamSources = emptyList(),
      streamRefreshing = retained.isNotEmpty(),
      streamSearchStarted = true,
      availableStreams = retained,
      selectedEpisode = episode,
      errorMessage = null,
      streamsUnavailableReason = null,
    )

    viewModelScope.launch {
      if (pluginSourceCount > 0) {
        launch {
          // Wrapped like the other scrapers are: a plugin that throws is one source failing, and
          // it used to take the whole fan-out down with it because nothing caught it here.
          val outcome = runCatching {
            val pluginType = if (detail.type == "series") "tv" else detail.type
            val pluginId = apiClient.resolvePluginMediaId(pluginType, detail.id)
            StreamDekPlugins.manager.streams(pluginId, pluginType, episode?.seasonNumber, episode?.episodeNumber) { providerStreams ->
              withContext(Dispatchers.Main.immediate) {
                if (generation == streamRequestGeneration) {
                  providerStreams.forEach { stream -> merged.putIfAbsent(streamKey(stream), stream) }
                  publish()
                }
              }
            }.forEach { stream -> merged.putIfAbsent(streamKey(stream), stream) }
          }.onFailure { Log.w("StreamDekPlugins", "Plugin providers failed for ${detail.id}", it) }
          endSource(PLUGIN_SOURCE_LABEL, outcome.isFailure)
          publish()
        }
      }
      if (skyStreamSourceCount > 0 && cloudStreamTitle != null) {
        launch {
          val outcome = runCatching {
            SkyStreamPlugins.manager.streams(
              title = cloudStreamTitle,
              year = detail.year?.toIntOrNull(),
              imdbId = skyStreamImdbId,
              type = detail.type,
              season = episode?.seasonNumber,
              episode = episode?.episodeNumber,
            ) { providerStreams ->
              withContext(Dispatchers.Main.immediate) {
                if (generation == streamRequestGeneration) {
                  providerStreams.forEach { stream -> merged.putIfAbsent(streamKey(stream), stream) }
                  publish()
                }
              }
            }.forEach { stream -> merged.putIfAbsent(streamKey(stream), stream) }
          }.onFailure { Log.w("StreamDekSkyStream", "SkyStream providers failed for $skyStreamImdbId", it) }
          endSource(SKYSTREAM_SOURCE_LABEL, outcome.isFailure)
          publish()
        }
      }
      if (cloudStreamSourceCount > 0 && cloudStreamTitle != null) {
        launch {
          val request = CloudStreamProviderBridge.StreamRequest(
            title = cloudStreamTitle,
            year = detail.year?.toIntOrNull(),
            type = if (detail.type == "series") "tv" else detail.type,
            season = episode?.seasonNumber,
            episode = episode?.episodeNumber,
          )
          val outcome = runCatching {
            // Each provider publishes as it finishes rather than waiting for the slowest one,
            // matching how the add-on and JS plugin sources fill the list in.
            CloudStreamProviderBridge.streams(cloudStreamProviders, request) { providerStreams ->
              withContext(Dispatchers.Main.immediate) {
                if (generation == streamRequestGeneration) {
                  providerStreams.forEach { stream -> merged.putIfAbsent(streamKey(stream), stream) }
                  publish()
                }
              }
            }.forEach { stream -> merged.putIfAbsent(streamKey(stream), stream) }
          }.onFailure { Log.w("StreamDekCloudStream", "CloudStream providers failed for $cloudStreamTitle", it) }
          endSource(CLOUDSTREAM_SOURCE_LABEL, outcome.isFailure)
          publish()
        }
      }
      for (id in candidates) {
        for (addon in enabledAddons) {
          launch {
            val outcome = requestGate.withPermit { fetchAddonStreamsWithRetry(addon, type, id) }
              .onSuccess { streams -> streams.forEach { stream -> merged.putIfAbsent(streamKey(stream), stream) } }
              .onFailure { lastError = it }
            endSource(addon.manifest.name.ifBlank { addon.id }, outcome.isFailure)
            publish()
          }
        }

      }
    }.invokeOnCompletion {
      if (generation != streamRequestGeneration) return@invokeOnCompletion
      viewModelScope.launch {
        // The aggregate endpoint fans out across every installed add-on, so it is
        // skipped for live channels — those are served only by live-capable add-ons.
        if (merged.isEmpty() && !uiState.detailIsLive) {
          val fallback = mutableListOf<AddonStream>()
          for (id in candidates) {
            apiClient.fetchStreams(uiState.session, type, id, uiState.activeProfileId, detailCorrelationId)
              .onSuccess { fallback += it }
              .onFailure { lastError = it }
          }
          fallback.forEach { stream -> merged.putIfAbsent(streamKey(stream), stream) }
        }
        val ranked = rankedProfileStreams(mediaStreamsOnly(merged.values.toList(), detail))
        uiState = uiState.copy(
          streamLoading = false,
          pendingStreamSources = 0,
          searchingStreamSources = emptyList(),
          failedStreamSources = failedSourceNames.toList(),
          streamRefreshing = false,
          availableStreams = ranked,
          selectedEpisode = episode,
          errorMessage = lastError.let { error -> if (ranked.isEmpty() && error != null) error.message ?: "No playable streams were found." else uiState.errorMessage },
        )
        markDebridCachedStreams(generation)
      }
    }
  }

  /**
   * Fills in which streams the user's debrid providers already hold, once the whole list is in.
   *
   * Deliberately one request for the merged set rather than one per add-on: results arrive
   * add-on by add-on, and asking after each publish would put the same question to the provider
   * a dozen times for one title.
   *
   * Available to every account with a debrid provider - it describes that user's own
   * subscription, so there is nothing to gate.
   */
  private fun markDebridCachedStreams(generation: Long) {
    val session = uiState.session ?: return
    if (uiState.debridAccounts.none { it.enabled }) return
    // Streams fetched through StreamDek's servers already carry their markers.
    val hashes = uiState.availableStreams
      .filter { it.cachedBy.isEmpty() }
      .mapNotNull { it.infoHash?.trim()?.takeIf(String::isNotEmpty)?.lowercase() }
      .distinct()
    if (hashes.isEmpty()) return
    // Sent alongside the hashes for Deepbrid's benefit: it identifies nothing by hash, so a name
    // is the only thing it can match against what the account already holds. The filename is the
    // release name when an add-on supplies one; the stream's own title is the usable fallback.
    val releaseNames = uiState.availableStreams
      .mapNotNull { stream ->
        val hash = stream.infoHash?.trim()?.takeIf(String::isNotEmpty)?.lowercase() ?: return@mapNotNull null
        val name = stream.filename?.takeIf(String::isNotBlank) ?: stream.title?.takeIf(String::isNotBlank) ?: return@mapNotNull null
        hash to name
      }
      .toMap()
    viewModelScope.launch {
      // Same split as playback: a device that streams directly asks its own providers, so no list
      // of what this viewer is looking at goes anywhere it does not have to.
      val deviceDebrid = deviceDebrid()
      val answer = if (deviceDebrid != null) {
        runCatching { deviceDebrid.checkCacheAll(hashes, releaseNames) }
      } else if (uiState.serverSideStreamsEnabled) {
        apiClient.fetchDebridCachedHashes(session, hashes, releaseNames)
      } else {
        return@launch
      }
      answer.onSuccess { cached ->
        if (generation != streamRequestGeneration || cached.isEmpty()) return@onSuccess
        val decorated = uiState.availableStreams.map { stream ->
          val providers = stream.infoHash?.trim()?.lowercase()?.let(cached::get).orEmpty()
          if (providers.isEmpty() || stream.cachedBy.isNotEmpty()) stream else stream.copy(cachedBy = providers)
        }
        // Being cached is worth 400 points in rankedStreams, so the order the user is looking at
        // is wrong until it is applied - re-ranked here rather than left stale. Stream cards are
        // keyed by identity, so re-ordering moves cards instead of reassigning them.
        uiState = uiState.copy(
          availableStreams = rankedProfileStreams(decorated),
        )
      }
    }
  }

  /**
   * Ids already translated for add-on /stream calls, one in-flight resolution per title.
   *
   * The fan-out calls [fetchAddonStreamsWithRetry] once per add-on, and every one of them needs
   * the same translated id — without sharing the work here, opening a title would ask the
   * resolver as many times as the user has add-ons installed.
   */
  private val resolvedAddonVideoIds = mutableMapOf<String, kotlinx.coroutines.Deferred<String>>()

  private suspend fun addonVideoIdFor(type: String, id: String): String {
    if (type != "movie" && type != "series" && type != "tv") return id
    if (id.substringBefore(":").matches(IMDB_ID_PATTERN)) return id
    val key = "$type:$id"
    val pending = synchronized(resolvedAddonVideoIds) {
      resolvedAddonVideoIds.getOrPut(key) {
        viewModelScope.async(Dispatchers.IO) {
          apiClient.resolveAddonVideoId(uiState.session, type, id).getOrDefault(id)
        }
      }
    }
    return runCatching { pending.await() }.getOrDefault(id)
  }

  private suspend fun fetchAddonStreamsWithRetry(addon: InstalledAddon, type: String, id: String): Result<List<AddonStream>> {
    val requestedType = type.trim().lowercase()
    val declaredTypes = addon.manifest.types.map { it.trim().lowercase() }.filterTo(mutableSetOf()) { it.isNotBlank() }
    val typeCandidates = if (uiState.detailIsLive) {
      buildList {
        add(requestedType)
        detailSourceCatalogType?.trim()?.lowercase()?.takeIf { it.isNotBlank() }?.let(::add)
        addAll(declaredTypes)
        addAll(listOf("live", "channel", "tv", "sport", "sports", "other"))
      }.filter { it.isNotBlank() }.distinct()
        // The generic spellings above exist because live add-ons disagree about what to call a
        // channel, not because any one add-on serves all of them. Asking an add-on for a type it
        // never advertised is a guaranteed-empty round trip, and at six or more candidates
        // against two request paths that was most of the traffic a single channel generated.
        .filter { declaredTypes.isEmpty() || it == requestedType || it in declaredTypes }
    } else {
      listOf(requestedType)
    }
    var lastError: Throwable? = null
    val isLocalAddon = LocalAddonManager.isLocalAddonId(addon.id)
    // Asking StreamDek's servers to fetch streams is now an entitlement rather than the default.
    // An add-on that decides it dislikes the caller blocks that caller for everyone behind it, so
    // a single add-on's abuse detection used to remove sources for the whole user base. Fetching
    // from the device puts that risk on the one account it belongs to.
    val useServerSideStreams = !isLocalAddon && uiState.serverSideStreamsEnabled
    if (useServerSideStreams) {
      for (candidateType in typeCandidates) {
        apiClient.fetchStreamsFromAddon(uiState.session, addon.id, candidateType, id, uiState.activeProfileId)
          .onSuccess { if (it.isNotEmpty()) return Result.success(it) }
          .onFailure { lastError = it }
      }
    }
    val requiresImdbId = !uiState.detailIsLive && (requestedType == "movie" || requestedType == "series" || requestedType == "tv")
    // Without the server in front, an id an add-on cannot read has to be translated first or the
    // request below is a guaranteed miss - that translation needs a TMDB key only the server
    // holds. The resolver contacts no add-on, so no add-on learns a StreamDek address from it.
    val directId = if (isLocalAddon || !requiresImdbId) id else addonVideoIdFor(requestedType, id)
    val baseId = directId.substringBefore(":")
    // Local add-ons only ever fetch directly from the device (there's no backend copy to try
    // first), so they always go straight to the on-device fetch below.
    // Recorded rather than passed over: this is the one empty result that will still be empty
    // tomorrow, and the viewer is otherwise left refreshing a list that can never fill.
    if (requiresImdbId && !isLocalAddon && !baseId.matches(IMDB_ID_PATTERN)) {
      uiState = uiState.copy(
        streamsUnavailableReason = "No sources for this title. Add-ons look titles up by their IMDb id, and this one has none listed — refreshing will not change that.",
      )
    }
    if (isLocalAddon || !requiresImdbId || baseId.matches(IMDB_ID_PATTERN)) {
      if (useServerSideStreams) delay(180L)
      for (candidateType in typeCandidates.take(3)) {
        val answered = apiClient.fetchFreshStreamsFromAddon(addon, candidateType, directId)
          .onSuccess { if (it.isNotEmpty()) return Result.success(it) }
          .onFailure { lastError = it }
          .isSuccess
        // A direct fetch throws on any non-2xx, so reaching here having succeeded means the
        // add-on answered and genuinely has nothing for this title. Trying the remaining
        // spellings of the type would only ask the same question again.
        if (answered) break
      }
    }
    return lastError.let { error -> if (error == null) Result.success(emptyList()) else Result.failure(error) }
  }

  private suspend fun fetchStreamsForPlayback(
    type: String,
    ids: List<String>,
    live: Boolean = uiState.detailIsLive,
    // CloudStream providers search by title, so callers that are not the on-screen detail (the TV
    // handoff, for one) have to say which title they mean rather than inherit uiState.detail.
    detail: MediaDetail? = uiState.detail,
  ): Result<List<AddonStream>> {
    val merged = mutableListOf<AddonStream>()
    var lastError: Throwable? = null
    val candidates = ids.filter { it.isNotBlank() }.distinct()
    val enabledAddons = uiState.addons
      .filter { addon ->
        addon.enabled && if (live) addonSupportsLiveStreams(addon) else addonSupportsStreamType(addon, type)
      }
      .sortedWith(compareByDescending<InstalledAddon> { it.favourite }.thenBy { it.position })

    for (id in candidates) {
      for (addon in enabledAddons) {
        fetchAddonStreamsWithRetry(addon, type, id)
          .onSuccess { streams -> merged += streams }
          .onFailure { lastError = it }
      }

      // The aggregate endpoint spans every add-on, so live channels never use it.
      if (merged.isEmpty() && !live) {
        apiClient.fetchStreams(uiState.session, type, id, uiState.activeProfileId, detailCorrelationId)
          .onSuccess { streams -> merged += streams }
          .onFailure { lastError = it }
      }
    }

    // Plugin providers are movie/series scrapers — not a source for live channels.
    if (!live) {
      val pluginType = if (type == "series") "tv" else type
      val pluginCandidate = candidates.firstOrNull()?.substringBefore(":").orEmpty()
      val pluginId = apiClient.resolvePluginMediaId(pluginType, pluginCandidate)
      merged += StreamDekPlugins.manager.streams(pluginId, pluginType, null, null)
    }

    merged += cloudStreamStreams(type, candidates, live, detail)

    val unique = merged.distinctBy(::addonStreamPlaybackIdentity)
    return lastError.let { error -> if (unique.isNotEmpty() || error == null) Result.success(unique) else Result.failure(error) }
  }

  /**
   * Streams from installed CloudStream (.cs3) providers.
   *
   * Those providers are title scrapers rather than id lookups, so unlike the add-on/JS paths this
   * one is driven from the detail that is already on screen (title/year plus the season & episode
   * encoded in the "<id>:<season>:<episode>" candidate). Without a resolved title there is nothing
   * to search for, so it simply returns nothing.
   */
  private suspend fun cloudStreamStreams(type: String, candidates: List<String>, live: Boolean, requestedDetail: MediaDetail?): List<AddonStream> {
    if (!CloudStreamPlugins.isInitialized) return emptyList()
    val providers = CloudStreamPlugins.manager.activeProviders()
    if (providers.isEmpty()) return emptyList()
    val detail = requestedDetail ?: uiState.detailFallbackItem?.toFallbackDetail() ?: return emptyList()
    val title = sanitizeDisplayText(detail.title)?.takeIf { it.isNotBlank() } ?: return emptyList()
    val episodeRef = candidates.firstNotNullOfOrNull { candidate ->
      candidate.split(':').takeIf { it.size >= 3 }?.let { parts ->
        val season = parts[parts.size - 2].toIntOrNull()
        val episode = parts[parts.size - 1].toIntOrNull()
        if (season != null && episode != null) season to episode else null
      }
    } ?: uiState.selectedEpisode?.let { it.seasonNumber to it.episodeNumber }
    val requestType = when {
      live -> "live"
      type == "series" -> "tv"
      else -> type
    }
    return runCatching {
      CloudStreamProviderBridge.streams(
        providers = providers,
        request = CloudStreamProviderBridge.StreamRequest(
          title = title,
          year = detail.year?.toIntOrNull(),
          type = requestType,
          season = episodeRef?.first,
          episode = episodeRef?.second,
        ),
      )
    }.onFailure { Log.w("StreamDekCloudStream", "CloudStream providers failed for $title", it) }.getOrDefault(emptyList())
  }

  /**
   * Live channels must only ever be resolved by add-ons that actually serve live TV.
   * [addonSupportsStreamType] maps "tv" onto "series", which would otherwise match
   * every movie/series debrid add-on and waste a request per channel on sources that
   * can never answer.
   */
  private fun addonSupportsLiveStreams(addon: InstalledAddon): Boolean {
    val resources = addon.manifest.resources.map { it.trim().lowercase() }
    if (resources.isNotEmpty() && resources.none { it == "stream" || it == "streams" }) return false
    val types = addon.manifest.types.map { it.trim().lowercase() }
    // An add-on with no declared types is ambiguous — never assume it serves live TV.
    return types.any { it in liveAddonTypes }
  }

  private val IMDB_ID_PATTERN = Regex("^tt\\d+$", RegexOption.IGNORE_CASE)

  private fun addonSupportsStreamType(addon: InstalledAddon, type: String): Boolean {
    val resources = addon.manifest.resources.map { it.trim().lowercase() }
    if (resources.isNotEmpty() && resources.none { it == "stream" || it == "streams" }) return false
    val nativeType = if (type == "tv") "series" else type.trim().lowercase()
    val types = addon.manifest.types.map { it.trim().lowercase() }
    if (types.isEmpty()) return true
    return nativeType in types || (nativeType == "series" && "tv" in types)
  }

  private fun needsFreshPlaybackUrl(stream: AddonStream): Boolean {
    val url = stream.url ?: return false
    return runCatching {
      val uri = Uri.parse(url)
      uri.host.equals("pengu.uk", ignoreCase = true) && uri.path.orEmpty().startsWith("/direct/")
    }.getOrDefault(false)
  }

  private suspend fun refreshStreamForPlayback(stream: AddonStream, detail: MediaDetail, episode: EpisodeItem?): AddonStream {
    if (!needsFreshPlaybackUrl(stream)) return stream
    val addon = uiState.addons.firstOrNull { it.id == stream.addonId }
      ?: throw IllegalStateException("The addon needed to refresh this playback link is unavailable.")
    val streamType = if (detail.type == "tv") "series" else detail.type
    val mediaId = detail.imdbId?.takeIf { it.isNotBlank() } ?: detail.id
    val videoId = episode?.let { "$mediaId:${it.seasonNumber}:${it.episodeNumber}" } ?: mediaId
    val fresh = apiClient.fetchFreshStreamsFromAddon(addon, streamType, videoId, forceNetwork = true).getOrThrow()
    return fresh.firstOrNull { candidate ->
      !stream.bingeGroup.isNullOrBlank() && candidate.bingeGroup == stream.bingeGroup
    } ?: fresh.firstOrNull { candidate ->
      !stream.filename.isNullOrBlank() && candidate.filename == stream.filename && candidate.name == stream.name
    } ?: throw IllegalStateException("This addon could not refresh the selected playback link. Try another source.")
  }

  private suspend fun resolvePlayback(stream: AddonStream, detail: MediaDetail, episode: EpisodeItem?): Result<ResolvedPlayback> = runCatching {
    val playbackStream = refreshStreamForPlayback(stream, detail, episode)
    val directUrl = playbackStream.url?.takeIf { it.isNotBlank() && !it.startsWith("magnet:", ignoreCase = true) }
    if (directUrl != null) {
      val shouldPrepareBridgeHls = detailLocalStreamId != null && playbackStream.requestHeaders.isNotEmpty()
      val preparedUrl = if (shouldPrepareBridgeHls) {
        apiClient.prepareHlsForPlayback(directUrl, playbackStream.requestHeaders).getOrDefault(directUrl)
      } else {
        directUrl
      }
      return@runCatching ResolvedPlayback(preparedUrl, playbackStream)
    }

    // A usenet result is assembled here on the device: the NZB names the articles, the stream's
    // own `servers` list says where to pull them from, and the player is handed a loopback URL
    // into the local assembler. Nothing about it touches a StreamDek server.
    playbackStream.nzbUrl?.takeIf { it.isNotBlank() }?.let { nzbUrl ->
      val localUrl = withContext(Dispatchers.IO) {
        UsenetPlayback.open(getApplication(), nzbUrl, playbackStream.nntpServers)
      }
      return@runCatching ResolvedPlayback(localUrl, playbackStream)
    }

    val infoHash = playbackStream.infoHash?.takeIf { it.isNotBlank() }
      ?: throw IllegalStateException("This source does not contain a playable URL or peer hash.")
    var lastFailure: Throwable? = null
    // Kept apart from lastFailure: the torrent engine below reports its own errors on the way to
    // giving up, and overwriting "your debrid is fetching this" with one of those is how a source
    // that is simply not ready yet came to read as a dead one.
    var debridDownloading: DebridDownloadingException? = null

    val maxSizeBytes = uiState.maxFileSizeGb.takeIf { it > 0 }?.toLong()?.times(1024L * 1024L * 1024L)
    if (uiState.session != null && uiState.debridAccounts.any { it.enabled }) {
      // Streaming directly means this device talks to its own premium services, so the provider
      // sees the viewer's address rather than one StreamDek server address shared by everyone.
      // The server path exists only when this account explicitly enabled Server-Side Streaming.
      val deviceDebrid = deviceDebrid()

      if (deviceDebrid != null) {
        val magnet = buildPeerMagnet(playbackStream, infoHash)
        android.util.Log.d(
          "StreamDekDebrid",
          "resolving $infoHash on device via ${deviceDebrid.providerNames} with ${streamTrackers(playbackStream.sources).size} tracker(s)",
        )
        val resolution = deviceDebrid.resolve(infoHash, magnet, playbackStream.filename)
        // Said out loud rather than swallowed: a service refusing a source for its own reasons — a
        // dead subscription, a torrent limit, content it will not touch — is something the viewer
        // can act on, and it used to be visible only if every other route failed too.
        debridRejectionNotice(resolution.failures)?.let { notice ->
          uiState = uiState.copy(playbackNotice = notice)
        }
        resolution.stream?.link?.url?.takeIf { it.isNotBlank() }?.let { resolvedUrl ->
          return@runCatching ResolvedPlayback(resolvedUrl, playbackStream)
        }
        // "Downloading" outranks whatever else went wrong: if any provider took the magnet, the
        // useful thing to say is that it is on its way, not that some other service errored first.
        val downloading = resolution.failures.firstOrNull { it.code == DebridFailureCode.Downloading }
        if (downloading != null) {
          debridDownloading = DebridDownloadingException(downloading.message)
          lastFailure = debridDownloading
        } else {
          resolution.failures.firstOrNull()?.let { lastFailure = IllegalStateException(it.message) }
        }
      } else if (uiState.serverSideStreamsEnabled) {
        apiClient.resolveStream(uiState.session!!, playbackStream, maxSizeBytes)
          .onFailure { error ->
            lastFailure = error
            (error as? DebridDownloadingException)?.let { debridDownloading = it }
            error.message?.takeIf { it.isNotBlank() }?.let { message ->
              uiState = uiState.copy(playbackNotice = "Premium services: ${message.take(140)}")
            }
          }
          .getOrNull()?.url?.takeIf { it.isNotBlank() }?.let { resolvedUrl ->
            return@runCatching ResolvedPlayback(resolvedUrl, playbackStream)
          }
      }
    }

    val torrentSettings = uiState.peerStreamSettings
    android.util.Log.d(
      "StreamDekPeer",
      "debrid produced nothing for $infoHash; peer-to-peer mode=${torrentSettings.streamingMode} enabled=${torrentSettings.enabled}",
    )
    if (torrentSettings.streamingMode == "server") {
      ensurePeerEngineReady(torrentSettings.toServiceConfig())
        .onFailure {
          android.util.Log.w("StreamDekPeer", "engine did not come up: ${it.message}")
          lastFailure = it
        }
        .getOrNull()?.let { activeConfig ->
          // Warming the torrent up is allowed to fail without taking the whole attempt down with
          // it: the backend path below is a genuine second chance, and letting this throw straight
          // out of resolvePlayback meant a local engine that could not find peers also skipped it.
          runCatching {
            PeerStreamService.createPeerProxyUrl(
              activeConfig,
              infoHash,
              buildPeerMagnet(playbackStream, infoHash),
              playbackStream.filename,
              detail.title,
              episode?.seasonNumber,
              episode?.episodeNumber,
            )
          }
            .onFailure {
              android.util.Log.w("StreamDekPeer", "local engine could not prepare $infoHash: ${it.message}")
              lastFailure = it
            }
            .getOrNull()?.let { proxyUrl ->
              return@runCatching ResolvedPlayback(proxyUrl, playbackStream)
            }
        }

    }

    throw debridDownloading
      ?: IllegalStateException(lastFailure?.message ?: "This source could not be resolved. Enable the local peer server or try another source.")
  }

  fun playStream(
    stream: AddonStream,
    episode: EpisodeItem? = null,
    resumePercentOverride: Double? = null,
    returnToEpisodeStreams: Boolean = false,
    /** True when this call is the app rolling on to the next ranked source, not a new request. */
    continuingAttempt: Boolean = false,
  ) {
    val detail = uiState.detail ?: return
    val selectedEpisode = episode ?: uiState.selectedEpisode
    val requestGeneration = ++playbackRequestGeneration

    val attempt = playbackAttempt
      ?.takeIf { continuingAttempt }
      ?.also { it.sourcesTried += 1 }
      ?: PlaybackAttempt(
        correlationId = detailCorrelationId ?: Telemetry.newCorrelationId(),
        startedAt = System.currentTimeMillis(),
        mediaId = detail.id,
        mediaType = detail.type,
        seasonNumber = selectedEpisode?.seasonNumber,
        episodeNumber = selectedEpisode?.episodeNumber,
        sourcesTried = 1,
      ).also { playbackAttempt = it }
    // The journey the viewer measures as "the black screen": from the press to a picture. Its
    // phases are the only way to tell resolving a source apart from opening it, which look
    // identical from the outside and have completely different fixes.
    Perf.beginPlayback("addon=${stream.addonName};peer=${!stream.infoHash.isNullOrBlank()}")
    launchWork(
      onStart = {
        uiState = uiState.copy(
          streamLoading = true,
          errorMessage = null,
          returnToDetailAfterPlayer = true,
          playerLaunching = true,
          playerLaunchingLabel = buildSourceLabel(stream) ?: stream.addonName,
          // Enter the player route immediately with metadata only. NativePlayerScreen deliberately
          // does not create Media3/MPV until this is replaced by the URL-bearing real session.
          playerLaunchSession = buildPlayerLaunchSession(detail, selectedEpisode, stream),
          // Which row was chosen, so the sources list can mark that one as resolving. Read only
          // while playerLaunching is set, so no exit path has to remember to clear it.
          launchingStreamKey = addonStreamPlaybackIdentity(stream),
          // Only a source with no direct link of its own can end up in the torrent engine, so this
          // is what the player's loading backdrop watches through resolution and first frame.
          playerLaunchingPeerHash = stream.infoHash?.takeIf { hash ->
            hash.isNotBlank() && stream.url?.startsWith("magnet:", ignoreCase = true) != false
          },
          playbackNotice = null,
          playerReturnEpisodeId = if (returnToEpisodeStreams) selectedEpisode?.id else null,
        )
      },
      block = { resolvePlayback(stream, detail, selectedEpisode) },
      onSuccess = success@ { playback ->
        if (requestGeneration != playbackRequestGeneration || !attempt.owns(detail, selectedEpisode)) return@success
        // The loading scene stays in place here. Everything before this mark is source resolution;
        // everything after it is the player opening a URL it already has.
        Perf.playback?.mark("resolved", if (playback.url.startsWith("http://127.0.0.1")) "local" else "direct")
        val resumeEntry = loadPlaybackMemoryEntry(detail, selectedEpisode)
        val resumePercent = resumePercentOverride ?: resumeEntry?.progressPercent ?: 0.0
        val resumePositionSec = if (resumePercentOverride != null) 0.0 else resumeEntry?.positionSeconds ?: 0.0
        pendingDirectContinueFallback = null
        pendingDirectContinueEpisode = null
        val builtSession = buildPlayerSession(playback.url, detail, buildSourceLabel(playback.stream), selectedEpisode, playback.stream, resumePercent, resumePositionSec)
        if (resumePositionSec > 0.0 || resumePercent > 0.0) {
          Log.i(
            "StreamDekPlayback",
            "[ContinueWatching] sourceResolution=success provider=${playback.stream.addonName.take(48)} resumePosition=${resumePositionSec.takeIf { it > 0.0 } ?: resumePercent}",
          )
        }

        // Switching channels while one is already playing: swap the session straight over.
        // The old content stays visibly playing until the new source is actually ready -
        // ExoPlaybackView prepares the next source in the background and swaps in place
        // (see prepareSourceInBackground/promotePendingPlayer), and mpv's `loadfile ...
        // replace` does the same natively - so there's no need to pre-verify reachability
        // with a separate probe first. channelSwitchLoading stays true until the player
        // itself confirms the new channel is decoding (onChannelSwitchPlaybackStarted).
        uiState = uiState.copy(
          streamLoading = false,
          nextEpisodeLoading = false,
          nextEpisodeLoadingLabel = null,
          playerSession = builtSession,
          playerLaunchSession = null,
          playerLaunching = false,
          playerLaunchingLabel = null,
          liveChannelSwitching = liveChannelSwitchSnapshot != null,
          liveChannelSwitchingLabel = uiState.liveChannelSwitchingLabel,
        )

        Telemetry.playbackStarted(
          correlationId = attempt.correlationId,
          mediaId = detail.id,
          mediaType = detail.type,
          title = detail.title,
          addonKey = playback.stream.addonId.takeIf { it.isNotBlank() } ?: playback.stream.addonName,
          // Whichever debrid service actually served it, when one did.
          provider = playback.stream.cachedBy.firstOrNull(),
          durationMs = System.currentTimeMillis() - attempt.startedAt,
          sourcesTried = attempt.sourcesTried,
        )
        playbackAttempt = null
      },
      onFailure = failure@ { message ->
        if (requestGeneration != playbackRequestGeneration || !attempt.owns(detail, selectedEpisode)) return@failure
        // A failed resolver should not stop automatic playback at the first ranked source.
        // Preserve position for VOD and roll live channels on from zero.
        if (playNextStreamSource(stream, selectedEpisode, if (uiState.detailIsLive) 0.0 else resumePercentOverride)) return@failure

        // Past this point the app has stopped rolling on to other sources, so this is a failure
        // the viewer actually saw. Recording it any earlier would count a source that was
        // successfully replaced as a failed playback, and make the success rate meaningless.
        Telemetry.playbackFailed(
          correlationId = attempt.correlationId,
          mediaId = detail.id,
          mediaType = detail.type,
          title = detail.title,
          addonKey = stream.addonId.takeIf { it.isNotBlank() } ?: stream.addonName,
          provider = stream.cachedBy.firstOrNull(),
          errorCategory = classifyPlaybackFailure(message),
          errorCode = null,
          durationMs = System.currentTimeMillis() - attempt.startedAt,
          sourcesTried = attempt.sourcesTried,
        )
        playbackAttempt = null
        pendingDirectContinueFallback?.let { showDetails ->
          pendingDirectContinueFallback = null
          pendingDirectContinueEntry = null
          val resumedEpisode = pendingDirectContinueEpisode
          pendingDirectContinueEpisode = null
          uiState = uiState.copy(playerLaunchSession = null, playerLaunching = false, playerLaunchingLabel = null, playerLaunchingPeerHash = null, streamLoading = false, nextEpisodeLoading = false, nextEpisodeLoadingLabel = null, errorMessage = null)
          showDetails()
          // Straight to the sources for the episode that was being resumed, rather than the top of
          // the series page. The remembered source is gone; picking another one is the only thing
          // left to do, so put that in front of them.
          loadStreamsForCurrentDetail(resumedEpisode)
          return@failure
        }
        if (uiState.liveChannelSwitching) {
          val failedChannel = uiState.liveChannelSwitchingLabel
          cancelLiveChannelSwitch()
          uiState = uiState.copy(infoMessage = failedChannel?.let { "Could not load $it. Kept the current channel playing." } ?: message)
          return@failure
        }
        uiState = uiState.copy(playerLaunchSession = null, playerLaunching = false, playerLaunchingLabel = null, playerLaunchingPeerHash = null, streamLoading = false, nextEpisodeLoading = false, nextEpisodeLoadingLabel = null, errorMessage = message)
      },
    )
  }

  /**
   * Advances to the next ranked source after a resolver failure. For a remembered source
   * that is not in the current list, discard the stale memory and start a fresh ranked search.
   */
  private fun playNextStreamSource(failedStream: AddonStream, episode: EpisodeItem?, resumePercent: Double?): Boolean {
    val detail = uiState.detail ?: return false
    val streams = uiState.availableStreams
    val failedKey = streamIdentity(failedStream)
    val index = streams.indexOfFirst { streamIdentity(it) == failedKey }
    val next = streams.drop((index + 1).coerceAtLeast(0)).firstOrNull { streamIdentity(it) != failedKey }
    if (next != null) {
      uiState = uiState.copy(playerLaunchingLabel = buildSourceLabel(next) ?: next.addonName)
      playStream(next, episode, resumePercentOverride = resumePercent, continuingAttempt = true)
      return true
    }
    if (index < 0 && loadPlaybackMemoryEntry(detail, episode)?.stream != null) {
      val ownerKey = activeOwnerKey() ?: GUEST_OWNER_KEY
      loadPlaybackMemoryEntry(detail, episode)?.let { playbackResumeStore.save(ownerKey, it.copy(stream = null), touch = false) }
      uiState = uiState.copy(localResumeEntries = loadResumeEntries())
      playBestStream(episode)
      return true
    }
    return false
  }
  fun confirmLiveChannelSwitchStarted() {
    if (!uiState.liveChannelSwitching) return
    val detail = uiState.detail
    val stream = uiState.playerSession?.currentStream
    if (detail != null && stream != null && uiState.detailIsLive) rememberLiveSource(detail, stream)
    // Keep the previous working session snapshot available. If this new feed later
    // errors or stalls, Back can still restore it instead of leaving the player.
    uiState = uiState.copy(liveChannelSwitching = false, liveChannelSwitchingLabel = null)
  }
  private fun rememberLiveSource(detail: MediaDetail, stream: AddonStream) {
    if (!uiState.rememberLastSource) return
    val ownerKey = activeOwnerKey() ?: GUEST_OWNER_KEY
    playbackResumeStore.save(
      ownerKey,
      PlaybackMemoryEntry(
        mediaId = detail.id,
        mediaType = if (detail.type == "series") "tv" else detail.type,
        title = detail.title,
        year = detail.year,
        poster = detail.poster,
        backdrop = detail.backdrop,
        progressPercent = 0.0,
        isLive = true,
        stream = stream,
      ),
    )
    uiState = uiState.copy(localResumeEntries = loadResumeEntries())
  }

  fun playBestStream(episode: EpisodeItem? = null) {
    val detail = uiState.detail ?: return
    if (detail.type == "movie" && isFutureReleaseDate(detail.releaseDate)) {
      uiState = uiState.copy(streamLoading = false, pendingStreamSources = 0, totalStreamSources = 0, searchingStreamSources = emptyList(), failedStreamSources = emptyList(), streamRefreshing = false, streamSearchStarted = true, availableStreams = emptyList(), errorMessage = null)
      return
    }
    // With no explicit episode selection on a series, resume the episode the user
    // last watched so the "Continue S#-E#" CTA plays exactly where they left off.
    val selectedEpisode = episode ?: uiState.selectedEpisode ?: rememberedEpisodeFor(detail)
    val remembered = loadPlaybackMemoryEntry(detail, selectedEpisode)
    if (!uiState.detailIsLive && uiState.rememberLastSource && remembered?.stream != null && (remembered.progressPercent > 0.0 || !remembered.stream.url.isNullOrBlank() || !remembered.stream.infoHash.isNullOrBlank())) {
      playStream(remembered.stream, selectedEpisode, remembered.progressPercent)
      return
    }
    val cached = uiState.availableStreams.firstOrNull()
    if (cached != null && selectedEpisode == uiState.selectedEpisode) {
      playStream(cached, selectedEpisode)
      return
    }
    launchWork(
      onStart = {
        if (pendingDirectContinueFallback != null) Log.i("StreamDekPlayback", "[ContinueWatching] sourceResolution=started")
        uiState = uiState.copy(streamLoading = true, errorMessage = null)
      },
      block = {
        when {
          uiState.detailIsLive && detailSourceAddonId != null -> {
            val addon = uiState.addons.firstOrNull { it.id == detailSourceAddonId }
              ?: return@launchWork Result.failure(IllegalStateException("The live addon is no longer enabled."))
            val mediaId = detail.id.takeIf { it.isNotBlank() }
              ?: return@launchWork Result.failure(IllegalStateException("This channel has no stream identifier."))
            fetchAddonStreamsWithRetry(addon, detailSourceCatalogType ?: detail.type, mediaId)
          }
          detail.type == "tv" && !uiState.detailIsLive && selectedEpisode != null -> {
            val bridgeEpisodeId = selectedEpisode.sourceStreamId?.takeIf { it.isNotBlank() }
            if (bridgeEpisodeId != null) {
              fetchStreamsForPlayback(detailSourceCatalogType ?: "series", listOf(bridgeEpisodeId))
            } else {
              val ids = streamLookupIds(detail).distinct()
              fetchStreamsForPlayback("series", ids.map { "${it}:${selectedEpisode.seasonNumber}:${selectedEpisode.episodeNumber}" })
            }
          }
          detail.type == "tv" && !uiState.detailIsLive -> Result.failure(IllegalStateException("Choose an episode first."))
          uiState.detailIsLive -> {
            // Source add-on unknown — still restrict the search to live TV add-ons.
            fetchStreamsForPlayback(detailSourceCatalogType ?: detail.type, listOf(detail.id))
          }
          else -> {
            val ids = streamLookupIds(detail).distinct()
            val localBridgeType = detailSourceAddonId
              ?.takeIf(LocalAddonManager::isLocalAddonId)
              ?.let { detailSourceCatalogType }
            fetchStreamsForPlayback(localBridgeType ?: detail.type, ids)
          }
        }
      },
      onSuccess = { streams ->
        val ranked = rankedProfileStreams(mediaStreamsOnly(streams, detail))
        uiState = uiState.copy(streamLoading = false, availableStreams = ranked, selectedEpisode = selectedEpisode)
        val preferred = remembered?.stream?.takeIf { uiState.detailIsLive && uiState.rememberLastSource }?.let { saved ->
          ranked.firstOrNull { candidate ->
            streamIdentity(candidate) == streamIdentity(saved) ||
              addonStreamPlaybackIdentity(candidate) == addonStreamPlaybackIdentity(saved) ||
              (candidate.addonId == saved.addonId && listOf(candidate.source, candidate.name, candidate.title).any { label ->
                !label.isNullOrBlank() && listOf(saved.source, saved.name, saved.title).any { rememberedLabel -> label.equals(rememberedLabel, ignoreCase = true) }
              })
          }
        } ?: ranked.firstOrNull()
        preferred?.let { playStream(it, selectedEpisode) } ?: run {
          pendingDirectContinueFallback?.let { showDetails ->
            pendingDirectContinueFallback = null
            val resumeEpisode = pendingDirectContinueEpisode
            pendingDirectContinueEpisode = null
            showDetails()
            loadStreamsForCurrentDetail(resumeEpisode)
          }
          uiState = uiState.copy(playerLaunchSession = null, playerLaunching = false, playerLaunchingLabel = null, errorMessage = "No playable streams were found. Choose another source to keep your place.")
        }
      },
      onFailure = { message ->
        pendingDirectContinueFallback?.let { showDetails ->
          pendingDirectContinueFallback = null
          val resumeEpisode = pendingDirectContinueEpisode
          pendingDirectContinueEpisode = null
          showDetails()
          loadStreamsForCurrentDetail(resumeEpisode)
        }
        uiState = uiState.copy(playerLaunchSession = null, playerLaunching = false, playerLaunchingLabel = null, streamLoading = false, nextEpisodeLoading = false, nextEpisodeLoadingLabel = null, errorMessage = message)
      },
    )
  }
  fun refreshProfiles(showLoading: Boolean = true, refreshScopedData: Boolean = true) {
    val session = uiState.session ?: return
    launchWork(
      onStart = { if (showLoading) uiState = uiState.copy(profilesLoading = true, errorMessage = null) },
      block = { apiClient.fetchProfiles(session) },
      onSuccess = { profiles ->
        // The profile picker blocks on this and nothing else, so it is the launch milestone worth
        // timing: everything between `activity.firstComposition` and here is dark screen.
        Perf.startupMark("profiles.ready", "count=${profiles.size}")
        val selected = determineActiveProfile(session, profiles)
        val showPicker = if (routeAfterProfileRefresh) {
          profiles.size > 1 && !uiState.rememberLastProfileAtStartup
        } else uiState.showProfilePicker
        routeAfterProfileRefresh = false
        uiState = uiState.copy(profilesLoading = false, profiles = profiles, activeProfileId = selected?.id ?: uiState.activeProfileId, showProfilePicker = showPicker)
        selected?.id?.let { profileSelectionStore.save(session.user.uid, it) }
        if (refreshScopedData) refreshProfileScopedData()
      },
      onFailure = { message ->
        routeAfterProfileRefresh = false
        uiState = uiState.copy(profilesLoading = false, errorMessage = message)
      },
    )
  }

  fun selectProfile(profileId: String) {
    val profile = uiState.profiles.firstOrNull { it.id == profileId } ?: return
    val session = uiState.session
    if (session == null) {
      profileSelectionStore.save(GUEST_OWNER_KEY, profileId)
      uiState = uiState.copy(activeProfileId = profileId, showProfilePicker = false, availableStreams = emptyList(), profileTransitioning = true)
      refreshProfileScopedData()
      loadHome(force = true)
      return
    }
    if (profile.hasPinSet && (uiState.showProfilePicker || profile.id != uiState.activeProfileId)) {
      uiState = uiState.copy(pinPromptProfileId = profile.id, pinPromptProfileName = profile.name)
      return
    }
    profileSelectionStore.save(session.user.uid, profileId)
    uiState = uiState.copy(activeProfileId = profileId, showProfilePicker = false, pinPromptProfileId = null, pinPromptProfileName = null, availableStreams = emptyList(), profileTransitioning = true)
    refreshProfileScopedData()
    loadHome(force = true)
  }

  fun submitProfilePin(pin: String) {
    val session = uiState.session ?: return
    val profileId = uiState.pinPromptProfileId ?: return
    launchWork(
      onStart = { uiState = uiState.copy(profilesLoading = true, errorMessage = null) },
      block = { apiClient.verifyProfilePin(session, profileId, pin) },
      onSuccess = { valid ->
        if (valid) {
          profileSelectionStore.save(session.user.uid, profileId)
          uiState = uiState.copy(profilesLoading = false, activeProfileId = profileId, showProfilePicker = false, pinPromptProfileId = null, pinPromptProfileName = null, profileTransitioning = true)
          refreshProfileScopedData()
          loadHome(force = true)
        } else uiState = uiState.copy(profilesLoading = false, errorMessage = "Incorrect PIN. Try again.")
      },
      onFailure = { message -> uiState = uiState.copy(profilesLoading = false, errorMessage = message) },
    )
  }

  fun finishProfileTransition() { uiState = uiState.copy(profileTransitioning = false) }
  fun cancelProfilePinPrompt() { uiState = uiState.copy(pinPromptProfileId = null, pinPromptProfileName = null) }
  fun dismissProfilePicker() { uiState = uiState.copy(showProfilePicker = false) }

  fun showProfilePicker() {
    if (uiState.session == null) {
      if (uiState.profiles.isEmpty()) uiState = uiState.copy(infoMessage = "Create a local profile from Settings first.")
      else uiState = uiState.copy(showProfilePicker = true)
      return
    }
    uiState = uiState.copy(showProfilePicker = true)
    refreshProfiles(showLoading = uiState.profiles.isEmpty(), refreshScopedData = false)
  }

  fun createProfile(name: String, avatarIndex: Int = 0) {
    val normalized = name.trim().take(32)
    if (normalized.isBlank()) return
    val session = uiState.session
    if (session == null) {
      val profile = StreamProfile("guest-${UUID.randomUUID()}", GUEST_OWNER_KEY, normalized, avatarIndex.coerceIn(0, 11), false, uiState.profiles.isEmpty(), null, null)
      val profiles = uiState.profiles + profile
      guestProfileStore.save(profiles)
      profileSelectionStore.save(GUEST_OWNER_KEY, profile.id)
      uiState = uiState.copy(profiles = profiles, activeProfileId = profile.id, showProfilePicker = false, infoMessage = "Local profile created on this device.")
      refreshProfileScopedData()
      return
    }
    launchWork(
      onStart = { uiState = uiState.copy(profilesLoading = true, errorMessage = null) },
      block = { apiClient.createProfile(session, normalized, avatarIndex) },
      onSuccess = { profile ->
        val profiles = uiState.profiles + profile
        profileSelectionStore.save(session.user.uid, profile.id)
        uiState = uiState.copy(profilesLoading = false, profiles = profiles, activeProfileId = profile.id, showProfilePicker = false)
        refreshProfileScopedData()
      },
      onFailure = { message -> uiState = uiState.copy(profilesLoading = false, errorMessage = message) },
    )
  }

  fun deleteProfile(profileId: String) {
    val profile = uiState.profiles.firstOrNull { it.id == profileId } ?: return
    val fallback = uiState.profiles.firstOrNull { it.id != profileId }
    if (fallback == null) {
      uiState = uiState.copy(infoMessage = "At least one profile is required.")
      return
    }
    val session = uiState.session
    if (session == null) {
      val profiles = uiState.profiles.filterNot { it.id == profileId }.map { it.copy(isDefault = if (profile.isDefault) it.id == fallback.id else it.isDefault) }
      guestProfileStore.save(profiles)
      val selectedId = if (uiState.activeProfileId == profileId) fallback.id else uiState.activeProfileId
      profileSelectionStore.save(GUEST_OWNER_KEY, selectedId)
      uiState = uiState.copy(profiles = profiles, activeProfileId = selectedId)
      refreshProfileScopedData()
      return
    }
    launchWork(
      onStart = { uiState = uiState.copy(profilesLoading = true, errorMessage = null) },
      block = {
        if (profile.isDefault) apiClient.setDefaultProfile(session, fallback.id).getOrThrow()
        apiClient.deleteProfile(session, profileId)
      },
      onSuccess = {
        if (uiState.activeProfileId == profileId) {
          profileSelectionStore.save(session.user.uid, fallback.id)
          uiState = uiState.copy(activeProfileId = fallback.id)
        }
        refreshProfiles()
      },
      onFailure = { message -> uiState = uiState.copy(profilesLoading = false, errorMessage = message) },
    )
  }

  fun makeDefaultProfile(profileId: String) {
    val session = uiState.session
    if (session == null) {
      val profiles = uiState.profiles.map { it.copy(isDefault = it.id == profileId) }
      guestProfileStore.save(profiles)
      uiState = uiState.copy(profiles = profiles)
      return
    }
    launchWork(onStart = {}, block = { apiClient.setDefaultProfile(session, profileId) }, onSuccess = { refreshProfiles() })
  }

  fun updateProfile(profileId: String, name: String, avatarIndex: Int) {
    val normalized = name.trim().take(32)
    if (normalized.isBlank()) return
    val session = uiState.session
    if (session == null) {
      val profiles = uiState.profiles.map { if (it.id == profileId) it.copy(name = normalized, avatarIndex = avatarIndex.coerceIn(0, 11)) else it }
      guestProfileStore.save(profiles)
      uiState = uiState.copy(profiles = profiles)
      return
    }
    launchWork(onStart = { uiState = uiState.copy(profilesLoading = true) }, block = { apiClient.updateProfile(session, profileId, normalized, avatarIndex) }, onSuccess = { refreshProfiles() })
  }

  fun updateProfilePin(profileId: String, pin: String?) {
    val session = uiState.session ?: run {
      uiState = uiState.copy(infoMessage = "PINs are available for synced profiles after signing in.")
      return
    }
    launchWork(onStart = { uiState = uiState.copy(profilesLoading = true) }, block = { apiClient.setProfilePin(session, profileId, pin) }, onSuccess = { refreshProfiles() })
  }
  // Local add-ons (installed from a localhost/LAN manifest, see LocalAddonManager) live entirely
  // on-device and have no backend counterpart. They're appended after the backend-managed list
  // and renumbered into one continuous `position` sequence so the rest of the app (home rows,
  // stream fan-out ordering, up/down arrows) can keep treating `uiState.addons` as a single list.
  private fun mergeWithLocalAddons(backendAddons: List<InstalledAddon>): List<InstalledAddon> =
    (backendAddons.sortedBy { it.position } + LocalAddonManager.list()).mapIndexed { index, addon -> addon.copy(position = index) }

  fun refreshAddons() {
    launchWork(
      onStart = { uiState = uiState.copy(addonsLoading = true, errorMessage = null) },
      block = {
        // Local add-ons have no server keeping their manifest fresh, so "refresh" re-fetches
        // each one directly from the device before merging in the backend-managed list.
        LocalAddonManager.list().forEach { local -> runCatching { LocalAddonManager.refresh(local.id) } }
        apiClient.fetchAddons(uiState.session, uiState.activeProfileId)
      },
      onSuccess = { addons ->
        val merged = mergeWithLocalAddons(addons)
        val mergedRows = mergeHomeCatalogRows(uiState.homeCatalogRows, merged, uiState.catalogDefinitions)
        uiState = uiState.copy(
          addonsLoading = false,
          addons = merged,
          homeCatalogRows = mergedRows,
          homeSections = applyHomeCatalogLayout(uiState.allHomeSections, mergedRows, uiState.defaultAppCatalogsEnabled),
        )
        appSettingsStore.saveHomeCatalogRows(mergedRows)
        loadHome(force = true)
        pendingStreamLoad?.let { pending ->
          val currentDetail = uiState.detail
          if (currentDetail?.id == pending.detailId) loadStreamsForCurrentDetail(pending.episode)
          else pendingStreamLoad = null
        }
      },
      onFailure = { message ->
        // Even if the backend call fails (e.g. offline), keep showing whatever backend add-ons
        // we already had plus a freshly re-read local add-on list.
        val previousBackend = uiState.addons.filterNot { LocalAddonManager.isLocalAddonId(it.id) }
        uiState = uiState.copy(addonsLoading = false, errorMessage = message, addons = mergeWithLocalAddons(previousBackend))
        pendingStreamLoad?.let { pending ->
          if (uiState.detail?.id == pending.detailId) loadStreamsForCurrentDetail(pending.episode)
          else pendingStreamLoad = null
        }
      },
    )
  }

  fun installAddon(url: String) {
    val manifestUrl = normalizeAddonManifestUrl(url)
    if (manifestUrl == null) {
      uiState = uiState.copy(errorMessage = "Enter a valid Stremio add-on manifest URL.")
      return
    }
    // A manifest hosted on localhost/LAN can only ever be fetched by this device — the regular
    // backend-install flow would send the URL to StreamDek's server, where 127.0.0.1 means
    // something completely different. Install and serve those add-ons directly instead.
    if (isLocalNetworkUrl(manifestUrl)) {
      launchWork(
        onStart = { uiState = uiState.copy(addonsLoading = true, errorMessage = null) },
        block = { LocalAddonManager.install(manifestUrl) },
        onSuccess = {
          uiState = uiState.copy(infoMessage = "Add-on installed from your network.")
          refreshAddons()
        },
      )
      return
    }
    launchWork(
      onStart = { uiState = uiState.copy(addonsLoading = true, errorMessage = null) },
      block = { apiClient.installAddon(uiState.session, manifestUrl, uiState.activeProfileId) },
      onSuccess = {
        uiState = uiState.copy(infoMessage = "Add-on installed.")
        refreshAddons()
      },
    )
  }
  fun toggleAddon(addon: InstalledAddon, enabled: Boolean) {
    if (LocalAddonManager.isLocalAddonId(addon.id)) {
      LocalAddonManager.setEnabled(addon.id, enabled)
      refreshAddons()
      return
    }
    launchWork(onStart = {}, block = { apiClient.toggleAddon(uiState.session, addon.id, enabled, uiState.activeProfileId) }, onSuccess = { refreshAddons() })
  }
  fun toggleAddonFavourite(addon: InstalledAddon) {
    val favourite = !addon.favourite
    if (LocalAddonManager.isLocalAddonId(addon.id)) {
      LocalAddonManager.setFavourite(addon.id, favourite)
      refreshAddons()
      return
    }
    launchWork(onStart = {}, block = { apiClient.setAddonFavourite(uiState.session, addon.id, favourite, uiState.activeProfileId) }, onSuccess = { refreshAddons() })
  }
  fun uninstallAddon(addonId: String) {
    if (LocalAddonManager.isLocalAddonId(addonId)) {
      LocalAddonManager.remove(addonId)
      refreshAddons()
      return
    }
    launchWork(onStart = {}, block = { apiClient.uninstallAddon(uiState.session, addonId, uiState.activeProfileId) }, onSuccess = { refreshAddons() })
  }
  fun moveAddon(addonId: String, delta: Int) {
    val selected = uiState.addons.firstOrNull { it.id == addonId } ?: return
    val movingLocal = LocalAddonManager.isLocalAddonId(addonId)
    val current = uiState.addons
      .filter { LocalAddonManager.isLocalAddonId(it.id) == movingLocal && it.favourite == selected.favourite }
      .sortedBy { it.position }
    val index = current.indexOfFirst { it.id == addonId }
    if (index < 0) return
    val target = index + delta
    if (target < 0 || target >= current.size) return
    // Local/backend and favourite/standard add-ons are persisted as separate priority groups.
    if (movingLocal) {
      LocalAddonManager.move(addonId, delta)
      refreshAddons()
      return
    }
    val backendList = current.toMutableList()
    val backendIndex = backendList.indexOfFirst { it.id == addonId }
    val backendTarget = (backendIndex + delta).coerceIn(0, backendList.lastIndex)
    if (backendIndex < 0 || backendIndex == backendTarget) return
    val item = backendList.removeAt(backendIndex)
    backendList.add(backendTarget, item)
    val reorderedGroup = backendList.iterator()
    val reordered = uiState.addons.filterNot { LocalAddonManager.isLocalAddonId(it.id) }.sortedBy { it.position }.mapIndexed { position, addon ->
      (if (addon.favourite == selected.favourite) reorderedGroup.next() else addon).copy(position = position)
    }
    uiState = uiState.copy(addons = mergeWithLocalAddons(reordered))
    launchWork(onStart = {}, block = { apiClient.reorderAddons(uiState.session, reordered.map { it.id }, uiState.activeProfileId) }, onSuccess = { refreshAddons() })
  }

  private fun publishM3uProgress(generation: Long, progress: M3uLoadProgress, aggregateFraction: Float? = progress.fraction) {
    viewModelScope.launch(Dispatchers.Main.immediate) {
      if (generation != m3uLoadGeneration) return@launch
      uiState = uiState.copy(
        m3uProgress = aggregateFraction?.coerceIn(0f, 1f),
        m3uStatusMessage = progress.message,
        m3uErrorMessage = null,
      )
    }
  }

  /**
   * Publishes every enabled playlist's channels, from each one's stored copy where there is one.
   *
   * [forceRefresh] re-fetches from the provider instead, which is what the Refresh action does.
   */
  fun loadM3uPlaylists(forceRefresh: Boolean = false) = loadM3uPlaylists(forceRefresh, background = false)

  /**
   * @param background a refresh running behind channels that are already on screen. It shows no
   *   progress or error UI, and publishes nothing if it came back with nothing - a provider that
   *   is unreachable, or rejecting the token today, must not empty a Live TV list that was
   *   working a moment ago.
   */
  private fun loadM3uPlaylists(forceRefresh: Boolean, background: Boolean) {
    val sources = M3uPlaylistManager.list()
    val enabledSources = sources.filter { it.enabled }
    val generation = ++m3uLoadGeneration
    uiState = uiState.copy(m3uSources = sources)
    if (enabledSources.isEmpty()) {
      uiState = uiState.copy(
        m3uLoading = false,
        m3uProgress = null,
        m3uStatusMessage = null,
        m3uErrorMessage = null,
        m3uChannels = emptyList(),
        m3uVodItems = emptyList(),
      )
      return
    }
    if (!background) {
      uiState = uiState.copy(
        m3uLoading = true,
        m3uProgress = 0f,
        m3uStatusMessage = "Preparing ${enabledSources.size} playlist(s)…",
        m3uErrorMessage = null,
      )
    }
    viewModelScope.launch {
      val liveChannels = mutableListOf<MediaItem>()
      val vodItems = mutableListOf<MediaItem>()
      val failures = mutableListOf<String>()
      enabledSources.forEachIndexed { index, source ->
        M3uPlaylistManager.fetchItems(source, forceRefresh = forceRefresh) { progress ->
          if (background) return@fetchItems
          val aggregate = progress.fraction?.let { (index + it) / enabledSources.size.toFloat() }
          publishM3uProgress(
            generation,
            progress.copy(message = "Playlist ${index + 1} of ${enabledSources.size} • ${progress.message}"),
            aggregate,
          )
        }.onSuccess { content ->
          liveChannels += content.liveChannels
          vodItems += content.vodItems
          M3uPlaylistManager.updateContentSummary(source.id, content)
        }.onFailure { error ->
          failures += "${source.name}: ${error.message ?: "Unable to load"}"
        }
      }
      if (generation != m3uLoadGeneration) return@launch
      if (background && liveChannels.isEmpty() && vodItems.isEmpty()) return@launch
      uiState = uiState.copy(
        m3uLoading = false,
        m3uProgress = null,
        m3uStatusMessage = null,
        m3uErrorMessage = if (background) uiState.m3uErrorMessage else failures.takeIf { it.isNotEmpty() }?.joinToString("\n"),
        m3uSources = M3uPlaylistManager.list(),
        m3uChannels = liveChannels,
        m3uVodItems = vodItems,
      )
      // A stored copy is served however old it is, so this is the only thing that ever renews
      // one on its own. It runs after the channels are already listed, and cannot take them away.
      if (!forceRefresh && !background && enabledSources.any(M3uPlaylistManager::needsBackgroundRefresh)) {
        loadM3uPlaylists(forceRefresh = true, background = true)
      }
    }
  }

  fun addM3uPlaylist(url: String, name: String) {
    val generation = ++m3uLoadGeneration
    uiState = uiState.copy(
      m3uLoading = true,
      m3uProgress = 0f,
      m3uStatusMessage = "Connecting to playlist…",
      m3uErrorMessage = null,
      errorMessage = null,
    )
    viewModelScope.launch {
      M3uPlaylistManager.add(url, name) { progress -> publishM3uProgress(generation, progress) }
        .onSuccess { result ->
          if (generation != m3uLoadGeneration) return@onSuccess
          uiState = uiState.copy(
            m3uLoading = false,
            m3uProgress = null,
            m3uStatusMessage = null,
            m3uErrorMessage = null,
            m3uSources = M3uPlaylistManager.list(),
            m3uChannels = uiState.m3uChannels + result.content.liveChannels,
            m3uVodItems = uiState.m3uVodItems + result.content.vodItems,
          )
          // The playlist plays from the local copy either way; the account catches up behind it.
          val session = uiState.session
          val profileId = uiState.activeProfileId?.takeIf { it.isNotBlank() }
          if (session != null && profileId != null) {
            apiClient.addPlaylist(session, profileId, result.source.url, result.source.name)
              .onFailure { Log.w("StreamDekPlaylists", "could not save playlist to the account", it) }
          }
        }
        .onFailure { error ->
          if (generation != m3uLoadGeneration) return@onFailure
          uiState = uiState.copy(
            m3uLoading = false,
            m3uProgress = null,
            m3uStatusMessage = null,
            m3uErrorMessage = error.message ?: "Unable to add that playlist.",
          )
        }
    }
  }

  fun removeM3uPlaylist(id: String) {
    val removed = uiState.m3uSources.firstOrNull { it.id == id }
    M3uPlaylistManager.remove(id)
    loadM3uPlaylists()
    removed?.let { source -> mirrorPlaylistToAccount { session, profileId, remote ->
      remote.firstOrNull { it.url.equals(source.url, ignoreCase = true) }
        ?.let { apiClient.removePlaylist(session, profileId, it.id) }
    } }
  }

  fun setM3uPlaylistEnabled(id: String, enabled: Boolean) {
    val changed = uiState.m3uSources.firstOrNull { it.id == id }
    M3uPlaylistManager.setEnabled(id, enabled)
    loadM3uPlaylists()
    changed?.let { source -> mirrorPlaylistToAccount { session, profileId, remote ->
      remote.firstOrNull { it.url.equals(source.url, ignoreCase = true) }
        ?.let { apiClient.updatePlaylist(session, profileId, it.id, enabled = enabled) }
    } }
  }

  fun moveM3uPlaylist(id: String, delta: Int) {
    M3uPlaylistManager.move(id, delta)
    val reordered = M3uPlaylistManager.list()
    uiState = uiState.copy(m3uSources = reordered)
    mirrorPlaylistToAccount { session, profileId, remote ->
      reordered.forEach { source ->
        remote.firstOrNull { it.url.equals(source.url, ignoreCase = true) }
          ?.let { apiClient.updatePlaylist(session, profileId, it.id, position = source.position) }
      }
      null
    }
  }

  /**
   * Applies a playlist change to the account behind whatever already happened on the device.
   *
   * The device stays the source of truth for what is on screen: playlists are parsed and cached
   * locally, and a phone with no connection must still be able to add or turn one off. The account
   * copy is caught up on the next sync, so a failure here is logged rather than surfaced.
   */
  private fun mirrorPlaylistToAccount(
    block: suspend (AuthSession, String, List<RemotePlaylist>) -> Any?,
  ) {
    val session = uiState.session ?: return
    val profileId = uiState.activeProfileId?.takeIf { it.isNotBlank() } ?: return
    viewModelScope.launch {
      val remote = apiClient.fetchPlaylists(session, profileId).getOrElse {
        Log.w("StreamDekPlaylists", "could not read account playlists", it)
        return@launch
      }
      runCatching { block(session, profileId, remote) }
        .onFailure { Log.w("StreamDekPlaylists", "could not mirror playlist change", it) }
    }
  }

  /**
   * Reconciles this profile's playlists with the account.
   *
   * Playlists used to live only on the device, so the first run after signing in finds entries the
   * account has never seen and uploads them; from then on there is nothing local-only left and
   * this is just a pull. Matching is by URL, so a second device uploading the same playlist joins
   * the existing entry instead of adding a duplicate.
   */
  private fun syncPlaylistsWithAccount() {
    val session = uiState.session ?: return
    val profileId = uiState.activeProfileId?.takeIf { it.isNotBlank() } ?: return
    viewModelScope.launch {
      val remote = apiClient.fetchPlaylists(session, profileId).getOrElse {
        Log.w("StreamDekPlaylists", "playlist sync skipped", it)
        return@launch
      }
      val deviceOnly = M3uPlaylistManager.mergeRemote(remote.map(::toLocalPlaylistSource))
      if (deviceOnly.isNotEmpty()) {
        apiClient.importPlaylists(
          session,
          profileId,
          deviceOnly.map { RemotePlaylist(id = "", name = it.name, url = it.url, enabled = it.enabled, position = it.position) },
        ).onSuccess { uploaded -> M3uPlaylistManager.mergeRemote(uploaded.map(::toLocalPlaylistSource)) }
          .onFailure { Log.w("StreamDekPlaylists", "could not upload device playlists", it) }
      }
      val merged = M3uPlaylistManager.list()
      if (merged != uiState.m3uSources) loadM3uPlaylists()
    }
  }

  private fun toLocalPlaylistSource(remote: RemotePlaylist) = M3uPlaylistSource(
    id = M3uPlaylistManager.localIdFor(remote.url),
    name = remote.name,
    url = remote.url,
    enabled = remote.enabled,
    position = remote.position,
  )

  /**
   * Both write straight through [PlaybackCodecOptions], which owns the stored value and the copy
   * the player reads when it is built. Neither goes through syncCloudPreferences: these describe
   * the decoder in this device, not a preference the viewer holds.
   */
  /**
   * The series a reminder could be about: everything on the watchlist or part-way through.
   *
   * Both, because they are two different ways of saying "I am following this". Filtered to numeric
   * ids because the reminder is looked up against TMDB — an add-on catalogue item keyed by its own
   * identifier has nothing to ask about.
   */
  private fun followedSeriesTmdbIds(): List<Int> =
    (uiState.mergedWatchlist + mergedContinueWatchingItems())
      .filter { normalizedMediaType(it.type) == "tv" }
      .mapNotNull { it.id.toIntOrNull()?.takeIf { id -> id > 0 } }
      .distinct()

  /**
   * Re-arms the reminders from whatever is followed right now.
   *
   * Cheap enough to call on any change worth reacting to: it is one batched request, and it does
   * nothing at all when reminders are off. Failure is silent — a reminder that could not be
   * rescheduled is not something to interrupt a viewer about, and the next refresh will try again.
   */
  /** How far back the New Episodes row reaches. A week covers a weekly show plus a late look. */
  private val newEpisodeWindowDays = 8L

  /**
   * "S01E04 · Half Loop", or whatever of that is known.
   *
   * The same line the television shows, so a household with both does not see one describe an
   * episode differently from the other.
   */
  private fun newEpisodeSubtitle(episode: AiringEpisode): String {
    val code = when {
      episode.season != null && episode.episode != null -> "S%02dE%02d".format(episode.season, episode.episode)
      episode.episode != null -> "Episode ${episode.episode}"
      else -> null
    }
    val name = episode.name?.trim()?.takeIf { it.isNotEmpty() }
    return listOfNotNull(code, name).joinToString(" · ").ifBlank { "A new episode is out." }
  }

  /**
   * The line on a New Episodes card.
   *
   * It has to say three things in the width of a poster: that this is new, which episode it is,
   * and when it landed. "NEW" leads because that is the reason the row exists -- the same card
   * without it reads as just another entry in a catalogue.
   *
   * The date is relative for the first two days, which is when most of these are seen. "Today"
   * is worth more than a date someone has to work out is today.
   */
  private fun newEpisodeCardSubtitle(episode: AiringEpisode, airDate: java.time.LocalDate): String {
    val code = when {
      episode.season != null && episode.episode != null -> "S${episode.season} E${episode.episode}"
      episode.episode != null -> "Ep ${episode.episode}"
      else -> null
    }
    val today = java.time.LocalDate.now()
    val when_ = when (airDate) {
      today -> "Today"
      today.minusDays(1) -> "Yesterday"
      else -> airDate.format(java.time.format.DateTimeFormatter.ofPattern("d MMM"))
    }
    return listOfNotNull("NEW", code, when_).joinToString(" · ")
  }

  private fun buildNewEpisodeItems(statuses: List<SeriesEpisodeStatus>): List<MediaItem> {
    val today = java.time.LocalDate.now()
    return EpisodeReleasePolicy.releasedWithin(statuses, today, newEpisodeWindowDays).map { (entry, episode) ->
      val airDate = runCatching { java.time.LocalDate.parse(episode.airDate.trim()) }.getOrNull()
        ?: today
      MediaItem(
        id = entry.tmdbId.toString(),
        type = "tv",
        title = entry.title.orEmpty(),
        year = null,
        poster = entry.poster,
        // The episode's own still, falling back to the series backdrop and then to its poster --
        // a season that carries no still for an episode still gets a card rather than a hole.
        backdrop = episode.still ?: entry.backdrop ?: entry.poster,
        rating = null,
        description = newEpisodeSubtitle(episode),
        cardSubtitle = newEpisodeCardSubtitle(episode, airDate),
        cardHighlight = true,
        resumeSeasonNumber = episode.season,
        resumeEpisodeNumber = episode.episode,
      )
    }
  }

  fun refreshEpisodeReminders() {
    val context = getApplication<Application>()
    val owner = activeOwnerKey() ?: return
    val notificationSettings = EpisodeNotificationSystem.settings(context, owner)
    val permitted = EpisodeNotificationSystem.permitted(context)
    uiState = uiState.copy(
      episodeRemindersEnabled = notificationSettings.availableEnabled,
      upcomingEpisodeRemindersEnabled = notificationSettings.upcomingEnabled,
      upcomingEpisodeReminderDays = notificationSettings.upcomingDays,
      episodeRemindersPermitted = permitted,
    )
    val ids = followedSeriesTmdbIds()
    EpisodeNotificationSystem.cacheEligibleSeries(context, owner, ids)
    if (ids.isEmpty()) {
      uiState = uiState.copy(newEpisodeItems = emptyList())
      return
    }
    episodeReminderJob?.cancel()
    episodeReminderJob = viewModelScope.launch {
      apiClient.fetchSeriesEpisodeStatus(ids)
        .onSuccess { statuses ->
          // One request feeds both. The row is filled whatever the reminder setting says; only
          // the notifications are gated on it.
          uiState = uiState.copy(newEpisodeItems = buildNewEpisodeItems(statuses))
          EpisodeNotificationSystem.requestImmediateCheck(context)
        }
        .onFailure { Log.w("StreamDekEpisodes", "Could not refresh episode reminders", it) }
    }
  }

  fun setEpisodeRemindersEnabled(value: Boolean) {
    val context = getApplication<Application>()
    val owner = activeOwnerKey() ?: return
    val settings = EpisodeNotificationSystem.settings(context, owner).copy(availableEnabled = value)
    EpisodeNotificationSystem.saveSettings(context, owner, settings)
    uiState = uiState.copy(
      episodeRemindersEnabled = value,
      episodeRemindersPermitted = EpisodeNotificationSystem.permitted(context),
    )
    refreshEpisodeReminders()
  }

  fun setUpcomingEpisodeRemindersEnabled(value: Boolean) {
    val context = getApplication<Application>()
    val owner = activeOwnerKey() ?: return
    val settings = EpisodeNotificationSystem.settings(context, owner).copy(upcomingEnabled = value)
    EpisodeNotificationSystem.saveSettings(context, owner, settings)
    uiState = uiState.copy(
      upcomingEpisodeRemindersEnabled = value,
      episodeRemindersPermitted = EpisodeNotificationSystem.permitted(context),
    )
    refreshEpisodeReminders()
  }

  fun setUpcomingEpisodeReminderDays(value: Int) {
    if (value !in setOf(1, 2, 7)) return
    val context = getApplication<Application>()
    val owner = activeOwnerKey() ?: return
    val settings = EpisodeNotificationSystem.settings(context, owner).copy(upcomingDays = value)
    EpisodeNotificationSystem.saveSettings(context, owner, settings)
    uiState = uiState.copy(upcomingEpisodeReminderDays = value)
  }

  fun setDv7HevcFallback(value: Boolean) {
    PlaybackCodecOptions.setDv7HevcFallback(getApplication(), value)
    uiState = uiState.copy(dv7HevcFallback = value)
  }

  fun setTunneledPlayback(value: Boolean) {
    PlaybackCodecOptions.setTunneledPlayback(getApplication(), value)
    uiState = uiState.copy(tunneledPlayback = value)
  }

  fun setDownloadsEnabled(value: Boolean) {
    appSettingsStore.saveDownloadsEnabled(value)
    uiState = uiState.copy(downloadsEnabled = value)
    if (value) refreshDownloads()
  }

  /**
   * Asks which stream-fetching path this account is entitled to.
   *
   * A failure leaves it off rather than assuming the generous answer: falling back to the server
   * path would put StreamDek's shared IP in front of the add-ons again, which is the situation
   * being fixed, and direct fetching works for everyone regardless.
   */
  private fun refreshAddonEntitlements() {
    val session = uiState.session ?: run {
      uiState = uiState.copy(serverSideStreamsEnabled = false)
      return
    }
    viewModelScope.launch {
      apiClient.fetchAddonEntitlements(session)
        .onSuccess { uiState = uiState.copy(serverSideStreamsEnabled = it.serverSideStreams) }
        .onFailure { uiState = uiState.copy(serverSideStreamsEnabled = false) }
    }
  }

  fun refreshDownloads() {
    uiState = uiState.copy(downloads = StreamDekDownloads.currentDownloadEntries())
  }

  /** Only streams playable through Media3 with a plain HTTP(S) URL can be downloaded - no
   * torrent-only (`infoHash`) streams, and never live channels (there's no finite file). */
  fun isDownloadEligible(stream: AddonStream, isLive: Boolean): Boolean =
    uiState.downloadsEnabled && !isLive && stream.infoHash.isNullOrBlank() && !stream.url.isNullOrBlank() &&
      (stream.url.startsWith("http://", ignoreCase = true) || stream.url.startsWith("https://", ignoreCase = true))

  fun downloadStream(stream: AddonStream, title: String) {
    val url = stream.url ?: return
    if (!isDownloadEligible(stream, isLive = false)) return
    val id = downloadIdFor(stream)
    // Record which title this file is, not just its name. Played back later, this is the only
    // thing that lets the download resolve to a real detail page and carry its own artwork.
    val detail = uiState.detail
    val episode = uiState.selectedEpisode
    StreamDekDownloads.startDownload(
      id = id,
      url = url,
      media = DownloadMedia(
        mediaId = detail?.id.orEmpty(),
        mediaType = detail?.type ?: "movie",
        title = detail?.title?.takeIf { it.isNotBlank() } ?: title,
        year = detail?.year,
        poster = detail?.poster,
        backdrop = detail?.backdrop,
        titleLogo = detail?.titleLogo,
        seasonNumber = episode?.seasonNumber,
        episodeNumber = episode?.episodeNumber,
        episodeTitle = episode?.name,
        runtimeMinutes = episode?.runtime ?: detail?.runtimeMinutes,
      ),
      mimeType = null,
    )
    uiState = uiState.copy(infoMessage = "Downloading \"$title\"…")
    refreshDownloads()
  }

  fun removeDownload(id: String) {
    StreamDekDownloads.removeDownload(id)
    refreshDownloads()
  }

  /** Plays a completed download back through the regular player. Forces the Media3 engine
   * (not "Auto", which could fall back to mpv) since only Media3's data source chain knows how
   * to read from the shared download cache - mpv has no idea it exists. */
  fun playDownload(entry: DownloadEntry, resumePercent: Double = 0.0) {
    if (entry.state != DownloadState.COMPLETED) return
    val media = entry.media
    // The session carries the real media identity, so the resume entry this playback writes is
    // keyed on the title rather than the download hash. Without it Continue Watching had no
    // artwork to show and its card pointed at whatever the hash happened to resolve to.
    uiState = uiState.copy(
      returnToDetailAfterPlayer = false,
      playerSession = PlayerSession(
        holdToSpeedEnabled = uiState.holdToSpeedEnabled,
        holdToSpeedMultiplier = uiState.holdToSpeedMultiplier,
        swipeToSeekEnabled = uiState.swipeToSeekEnabled,
        doubleTapSeekEnabled = uiState.doubleTapSeekEnabled,
        doubleTapSeekSeconds = uiState.doubleTapSeekSeconds,
        doubleTapPlayPauseEnabled = uiState.doubleTapPlayPauseEnabled,
        showPlayerControlLabels = uiState.showPlayerControlLabels,
        playerControlLayout = uiState.playerControlLayout,
        fullscreenStatusBar = uiState.fullscreenStatusBar,
        playerTitleDisplay = uiState.playerTitleDisplay,
        favoriteSourceKeys = uiState.favoriteSourceKeys,
        levelGesturesEnabled = uiState.playerLevelGesturesEnabled,
        url = entry.url,
        title = media.title,
        subtitle = media.seasonNumber?.let { season -> media.episodeNumber?.let { "S$season E$it" } } ?: media.year,
        sourceLabel = "Downloaded",
        poster = media.poster,
        backdrop = media.backdrop,
        titleLogo = media.titleLogo,
        mediaId = media.mediaId.ifBlank { entry.id },
        mediaType = media.mediaType,
        year = media.year?.toIntOrNull(),
        seasonNumber = media.seasonNumber,
        episodeNumber = media.episodeNumber,
        episodeTitle = media.episodeTitle,
        runtimeMinutes = media.runtimeMinutes,
        isLive = false,
        pictureInPictureEnabled = uiState.pictureInPictureEnabled,
        decoderMode = uiState.decoderMode,
        renderSurface = uiState.renderSurface,
        playerEngine = "Media3",
        resumePercent = resumePercent,
        // Recorded as the resume source so Continue Watching can replay the saved file directly
        // instead of falling back to opening a detail page.
        currentStream = downloadStreamFor(entry),
      ),
    )
  }

  fun refreshDebridAccounts() {
    loadDebridAccounts("Premium services refreshed.")
  }

  /**
   * Re-reads the connected services from wherever they are kept.
   *
   * [problem] is carried through instead of a success message for the case where the list is worth
   * refreshing but something still went wrong — a key the server refused, say. Without it the
   * refresh landed after the explanation and wiped it off the screen.
   */
  private fun loadDebridAccounts(successMessage: String? = null, problem: String? = null) {
    // With the keys kept off StreamDek's servers there is nothing to fetch: this device holds the
    // only copy, so it is also the list.
    if (!uiState.debridCloudSync) {
      uiState = uiState.copy(
        debridLoading = false,
        debridAccounts = localDebridAccounts(),
        debridNoticeMessage = problem ?: successMessage,
        debridNoticeIsError = problem != null,
      )
      return
    }
    // Cloud sync is on but there is nobody signed in — an expired session, or a sign-out with the
    // preference still set. The device's own keys are what playback uses in that state, so they are
    // also what the list has to show; returning here left the previous account's cards on screen,
    // and every control on them did nothing.
    val session = uiState.session ?: run {
      uiState = uiState.copy(debridLoading = false, debridAccounts = localDebridAccounts())
      return
    }
    launchWork(
      onStart = { uiState = uiState.copy(debridLoading = true, debridNoticeMessage = null, debridNoticeIsError = false) },
      block = { apiClient.fetchDebridAccounts(session) },
      onSuccess = { accounts ->
        uiState = uiState.copy(
          debridLoading = false,
          debridAccounts = accounts.sortedBy { it.priority },
          debridNoticeMessage = problem ?: successMessage,
          debridNoticeIsError = problem != null,
        )
        syncDebridKeys()
      },
      onFailure = { message -> showDebridNotice(message, isError = true, loading = false) },
    )
  }

  private fun showDebridNotice(message: String?, isError: Boolean = false, loading: Boolean = uiState.debridLoading) {
    uiState = uiState.copy(debridLoading = loading, debridNoticeMessage = message, debridNoticeIsError = isError)
  }

  fun dismissDebridNotice() {
    uiState = uiState.copy(debridNoticeMessage = null, debridNoticeIsError = false)
  }

  /** The connected services as this device holds them, for when the keys are not in the cloud. */
  private fun localDebridAccounts(): List<DebridAccount> =
    DebridKeyStore.load(getApplication()).map { key ->
      DebridAccount(provider = key.provider, enabled = key.enabled, priority = key.priority, username = key.username)
    }

  private fun applyLocalDebridKeys(keys: List<DebridKeyStore.StoredKey>) {
    DebridKeyStore.save(getApplication(), keys.mapIndexed { index, key -> key.copy(priority = index) })
    deviceDebridManager = null
    uiState = uiState.copy(debridLoading = false, debridAccounts = localDebridAccounts())
  }

  /**
   * Moves the account's keys between StreamDek's database and this device alone.
   *
   * Turning it on uploads what the device holds, so the same services appear on a TV signed in to
   * the same account. Turning it off deletes the stored copies — but never before checking that
   * this device actually has each key, because until then the database holds the only copy and
   * removing it first would lose the credential outright with nothing to restore it from.
   */
  fun setDebridCloudSync(enabled: Boolean) {
    // Nothing to sync with while signed out, but the switch still has to move: leaving it stuck on
    // is what strands every other control on this screen. Saved, and the list falls back to the
    // device's own keys.
    val session = uiState.session ?: run {
      appSettingsStore.saveDebridCloudSync(enabled)
      uiState = uiState.copy(debridCloudSync = enabled, debridLoading = false, debridAccounts = localDebridAccounts())
      showDebridNotice(
        if (enabled) "Sign in to sync your premium-service keys with your account." else "Premium-service keys are kept on this device only.",
        loading = false,
      )
      return
    }
    appSettingsStore.saveDebridCloudSync(enabled)
    uiState = uiState.copy(debridCloudSync = enabled, debridNoticeMessage = null, debridNoticeIsError = false)

    viewModelScope.launch {
      uiState = uiState.copy(debridLoading = true)
      if (enabled) {
        val local = DebridKeyStore.load(getApplication())
        // Each key keeps the state this device holds for it. Uploading them as bare credentials let
        // the server default every one to "on", so switching cloud sync on switched services back
        // on that the account holder had switched off.
        val refused = local.mapIndexedNotNull { index, key ->
          apiClient
            .addDebridAccount(session, key.provider, key.apiKey, enabled = key.enabled, priority = index)
            .fold(onSuccess = { null }, onFailure = { debridProviderLabel(key.provider) to (it.message ?: "could not be saved") })
        }
        if (refused.isNotEmpty()) {
          // Reported rather than swallowed: a key the server would not take is a service that is
          // not on the account, and every control for it then fails with "account not found" —
          // which is what made this look random rather than like one refused upload.
          loadDebridAccounts(
            problem = refused.joinToString(" ") { (label, reason) -> "$label was not saved to your account: $reason." },
          )
          return@launch
        }
        loadDebridAccounts("Premium-service keys are now synced with your StreamDek account.")
        return@launch
      }

      // Make sure the device has its own copy of everything before anything is deleted.
      if (DebridKeyStore.load(getApplication()).isEmpty()) {
        apiClient.fetchDebridKeys(session)
          .onSuccess { keys ->
            DebridKeyStore.save(
              getApplication(),
              keys.map { DebridKeyStore.StoredKey(it.provider, it.apiKey, it.priority, it.enabled, it.username) },
            )
          }
      }
      val local = DebridKeyStore.load(getApplication())
      if (local.isEmpty() && uiState.debridAccounts.isNotEmpty()) {
        appSettingsStore.saveDebridCloudSync(true)
        uiState = uiState.copy(
          debridCloudSync = true,
          debridLoading = false,
          debridNoticeMessage = "Could not copy your keys to this device, so they were left in the cloud. Check your connection and try again.",
          debridNoticeIsError = true,
        )
        return@launch
      }

      local.forEach { key -> apiClient.removeDebridAccount(session, key.provider) }
      deviceDebridManager = null
      uiState = uiState.copy(
        debridLoading = false,
        debridAccounts = localDebridAccounts(),
        debridNoticeMessage = "Premium-service keys are now kept on this device only.",
        debridNoticeIsError = false,
      )
    }
  }

  /**
   * Brings this device's copy of the premium-service keys up to date.
   *
   * Only for accounts that stream directly: those are the ones whose device does the talking, and
   * a key is not worth holding on a device that will never use it. An account set to go through
   * StreamDek's servers has its device copy cleared instead, so switching modes does not leave a
   * working credential behind on the handset.
   *
   * Failure is deliberately quiet. The keys are a performance and privacy improvement over asking
   * the server, not a prerequisite for playback — [resolvePlayback] falls back to the server path
   * when the device has nothing stored, so a failed sync costs nothing a viewer would notice.
   */
  private fun syncDebridKeys() {
    val session = uiState.session ?: return
    // Nothing to sync when the keys are not in the cloud — and nothing to clear either. This
    // device holds the only copy, so fetching an empty server list and writing it over the store
    // would destroy the credentials outright.
    if (!uiState.debridCloudSync) return
    if (uiState.serverSideStreamsEnabled || uiState.debridAccounts.isEmpty()) {
      DebridKeyStore.clear(getApplication())
      deviceDebridManager = null
      return
    }
    viewModelScope.launch {
      apiClient.fetchDebridKeys(session)
        .onSuccess { keys ->
          // A credential this device signed in for itself outranks the account's copy of it.
          // Real-Debrid's device sign-in stores a token plus the material that renews it, and only
          // the token is ever posted to the account — so taking the server's version wholesale
          // would drop the renewal material and leave a credential dead within the hour.
          val selfRenewing = DebridKeyStore.load(getApplication()).filter { it.refreshToken != null }
          val fromAccount = keys
            .filterNot { key -> selfRenewing.any { it.provider == key.provider } }
            .map { DebridKeyStore.StoredKey(it.provider, it.apiKey, it.priority, it.enabled, it.username) }
          DebridKeyStore.save(getApplication(), selfRenewing + fromAccount)
          deviceDebridManager = null
        }
        .onFailure { android.util.Log.w("StreamDekDebrid", "Could not sync premium service keys: ${it.message}") }
    }
  }

  /**
   * The device's own premium services, held rather than rebuilt per call.
   *
   * Each provider memoises what its account holds — Real-Debrid pages through its whole library to
   * answer a cache check — and a manager built fresh for every stream list would throw that away
   * and pay for it again on the next publish. Dropped whenever the keys change, so a disconnected
   * service stops being asked immediately.
   */
  private var deviceDebridManager: DebridManager? = null

  private fun deviceDebrid(): DebridManager? {
    // Keys kept off the cloud mean the server has nothing to resolve with, so the device does the
    // work whatever the streaming mode says — otherwise turning off cloud sync would silently
    // break playback for an account set to go through the servers.
    if (uiState.serverSideStreamsEnabled && uiState.debridCloudSync) return null
    val existing = deviceDebridManager ?: DebridManager.fromStoredKeys(getApplication()).also { deviceDebridManager = it }
    return existing.takeIf { it.hasProviders }
  }

  fun addDebridAccount(provider: String, apiKey: String) {
    if (!uiState.debridCloudSync) { addDebridAccountOnDevice(provider, apiKey); return }
    val session = uiState.session ?: return
    launchWork(
      onStart = { uiState = uiState.copy(debridLoading = true, debridNoticeMessage = null, debridNoticeIsError = false) },
      block = { apiClient.addDebridAccount(session, provider, apiKey) },
      onSuccess = { message -> loadDebridAccounts(message?.takeIf { it.isNotBlank() } ?: "${debridProviderLabel(provider)} connected.") },
      onFailure = { message -> showDebridNotice(message, isError = true, loading = false) },
    )
  }

  /**
   * Connects a service without the key ever leaving the device.
   *
   * The key is checked against the provider from here rather than by StreamDek, which is the
   * whole point of the setting — and is possible at all because the device now has the same
   * provider clients the server has.
   */
  /** Whether this build can offer Premiumize sign-in; a blank client id hides the option. */
  fun premiumizeSignInAvailable(): Boolean =
    BuildConfig.PREMIUMIZE_CLIENT_ID.isNotBlank()

  /**
   * Signs in to Real-Debrid by code, reporting progress through [uiState].
   *
   * A code rather than a browser redirect, because Real-Debrid's flow is a device flow — and it
   * works the same on a phone, where the viewer simply opens the page in another tab.
   */
  fun startRealDebridSignIn() {
    viewModelScope.launch {
      uiState = uiState.copy(debridLoading = true, debridNoticeMessage = null, debridNoticeIsError = false, debridSignIn = null)
      val started = runCatching { RealDebridDeviceAuth.start() }.getOrElse {
        showDebridNotice(it.message ?: "Real-Debrid could not be reached.", isError = true, loading = false)
        return@launch
      }
      uiState = uiState.copy(
        debridLoading = false,
        debridSignIn = DebridSignInPrompt(
          providerLabel = "Real-Debrid",
          userCode = started.userCode,
          verificationUrl = started.verificationUrl,
        ),
      )

      val deadline = System.currentTimeMillis() + started.expiresInSeconds * 1000L
      while (System.currentTimeMillis() < deadline) {
        delay(started.intervalSeconds * 1000L)
        // Dismissed while waiting — stop polling rather than reviving a card the viewer closed.
        if (uiState.debridSignIn == null) return@launch
        when (val poll = RealDebridDeviceAuth.poll(started.deviceCode)) {
          is RealDebridDeviceAuth.Poll.Authorized -> {
            storeRealDebridCredentials(poll.credentials)
            return@launch
          }
          RealDebridDeviceAuth.Poll.Pending -> Unit
          is RealDebridDeviceAuth.Poll.Failed -> {
            uiState = uiState.copy(debridSignIn = uiState.debridSignIn?.copy(waiting = false, outcome = poll.message))
            return@launch
          }
        }
      }
      uiState = uiState.copy(
        debridSignIn = uiState.debridSignIn?.copy(
          waiting = false,
          outcome = "That code expired before it was approved. Start again for a new one.",
        ),
      )
    }
  }

  /** Closes the sign-in card, which also stops the polling loop watching it. */
  fun dismissDebridSignIn() { uiState = uiState.copy(debridSignIn = null) }

  /**
   * Stores a Real-Debrid sign-in.
   *
   * Always kept on the device, whatever the cloud setting says, because the renewal material has
   * nowhere else to live: the server's account record holds a single key, and a token without the
   * credentials that renew it stops working within the hour. The token is still posted to the
   * account when cloud sync is on, so the service shows up on other devices.
   */
  private suspend fun storeRealDebridCredentials(credentials: RealDebridDeviceAuth.Credentials) {
    val existing = DebridKeyStore.load(getApplication()).filterNot { it.provider == "real-debrid" }
    val username = runCatching { RealDebridClient(credentials.accessToken).validate() }.getOrNull()?.username
    DebridKeyStore.save(
      getApplication(),
      existing + DebridKeyStore.StoredKey(
        provider = "real-debrid",
        apiKey = credentials.accessToken,
        priority = existing.size,
        enabled = true,
        username = username,
        refreshToken = credentials.refreshToken,
        oauthClientId = credentials.clientId,
        oauthClientSecret = credentials.clientSecret,
      ),
    )
    deviceDebridManager = null
    if (uiState.debridCloudSync) {
      uiState.session?.let { session -> apiClient.addDebridAccount(session, "real-debrid", credentials.accessToken) }
      loadDebridAccounts()
    }
    uiState = uiState.copy(
      debridLoading = false,
      debridAccounts = if (uiState.debridCloudSync) uiState.debridAccounts else localDebridAccounts(),
      debridSignIn = uiState.debridSignIn?.copy(
        waiting = false,
        outcome = "Connected${username?.let { " as $it" }.orEmpty()}.",
      ),
    )
  }

  /** Starts Premiumize's documented browser-pairing flow, which never needs a client secret. */
  fun startPremiumizeSignIn() {
    viewModelScope.launch {
      uiState = uiState.copy(debridLoading = true, debridNoticeMessage = null, debridNoticeIsError = false, debridSignIn = null)
      val started = runCatching { PremiumizeDeviceAuth.start(BuildConfig.PREMIUMIZE_CLIENT_ID) }.getOrElse { error ->
        showDebridNotice(error.message ?: "Premiumize could not be reached.", isError = true, loading = false)
        return@launch
      }
      uiState = uiState.copy(
        debridLoading = false,
        debridSignIn = DebridSignInPrompt("Premiumize", started.userCode, started.verificationUrl),
      )

      val deadline = System.currentTimeMillis() + started.expiresInSeconds * 1000L
      var intervalSeconds = started.intervalSeconds
      while (System.currentTimeMillis() < deadline) {
        delay(intervalSeconds * 1000L)
        if (uiState.debridSignIn == null) return@launch
        when (val poll = PremiumizeDeviceAuth.poll(BuildConfig.PREMIUMIZE_CLIENT_ID, started.deviceCode)) {
          is PremiumizeDeviceAuth.Poll.Authorized -> {
            if (uiState.debridCloudSync) addDebridAccount("premiumize", poll.accessToken)
            else addDebridAccountOnDevice("premiumize", poll.accessToken)
            uiState = uiState.copy(
              debridSignIn = uiState.debridSignIn?.copy(waiting = false, outcome = "Connected."),
            )
            return@launch
          }
          PremiumizeDeviceAuth.Poll.Pending -> Unit
          PremiumizeDeviceAuth.Poll.SlowDown -> intervalSeconds = (intervalSeconds + 5).coerceAtMost(60)
          is PremiumizeDeviceAuth.Poll.Failed -> {
            uiState = uiState.copy(debridSignIn = uiState.debridSignIn?.copy(waiting = false, outcome = poll.message))
            return@launch
          }
        }
      }
      uiState = uiState.copy(
        debridSignIn = uiState.debridSignIn?.copy(
          waiting = false,
          outcome = "That code expired before it was approved. Start again for a new one.",
        ),
      )
    }
  }

  private fun addDebridAccountOnDevice(provider: String, apiKey: String) {
    val client = DebridManager.build(provider, apiKey) ?: return
    viewModelScope.launch {
      uiState = uiState.copy(debridLoading = true, debridNoticeMessage = null, debridNoticeIsError = false)
      val validation = runCatching { client.validate() }.getOrNull()
      if (validation?.valid != true) {
        showDebridNotice("Invalid access key — the service rejected it.", isError = true, loading = false)
        return@launch
      }
      val existing = DebridKeyStore.load(getApplication()).filterNot { it.provider == provider }
      applyLocalDebridKeys(
        existing + DebridKeyStore.StoredKey(provider, apiKey, existing.size, true, validation.username),
      )
      if (validation.premium == false) {
        showDebridNotice("Connected, but this account is not premium. Peer-to-peer downloads need a premium subscription with this service.", isError = true, loading = false)
      } else {
        showDebridNotice("${debridProviderLabel(provider)} connected.", loading = false)
      }
    }
  }

  /**
   * The session a premium-service change has to go through, or null to change this device's copy.
   *
   * Null covers two cases that behave the same way: cloud sync switched off, and cloud sync on with
   * nobody signed in — an expired session, or a sign-out with the preference left set. The second
   * used to return early and do nothing at all, so the switch flipped back and the ordering buttons
   * were dead, with no message to say why. The device's keys are what playback resolves through, so
   * the change is made there instead and the notice says it has not left this device.
   */
  private fun debridSyncSession(): AuthSession? = uiState.session.takeIf { uiState.debridCloudSync }

  /** Appended when a change could not be synced because the account is signed out. */
  private fun debridDeviceOnlySuffix(): String =
    if (uiState.debridCloudSync && uiState.session == null) " Sign in to sync it to your account." else ""

  fun removeDebridAccount(provider: String) {
    val session = debridSyncSession() ?: run {
      applyLocalDebridKeys(DebridKeyStore.load(getApplication()).filterNot { it.provider == provider })
      showDebridNotice("${debridProviderLabel(provider)} disconnected.${debridDeviceOnlySuffix()}", loading = false)
      return
    }
    launchWork(
      onStart = { dismissDebridNotice() },
      block = { apiClient.removeDebridAccount(session, provider) },
      onSuccess = { loadDebridAccounts("${debridProviderLabel(provider)} disconnected.") },
      onFailure = { message -> showDebridNotice(message, isError = true, loading = false) },
    )
  }

  fun setDebridAccountEnabled(provider: String, enabled: Boolean) {
    val session = debridSyncSession() ?: run {
      applyLocalDebridKeys(
        DebridKeyStore.load(getApplication()).map { key ->
          if (key.provider == provider) key.copy(enabled = enabled) else key
        },
      )
      showDebridNotice(
        "${debridProviderLabel(provider)} ${if (enabled) "enabled" else "disabled"}.${debridDeviceOnlySuffix()}",
        loading = false,
      )
      return
    }
    val previous = uiState.debridAccounts
    uiState = uiState.copy(
      debridAccounts = previous.map { account ->
        if (account.provider == provider) account.copy(enabled = enabled) else account
      },
      debridNoticeMessage = null,
      debridNoticeIsError = false,
    )
    launchWork(
      onStart = {},
      block = { apiClient.setDebridAccountEnabled(session, provider, enabled) },
      // No reload on success. The list already shows exactly what was just saved, and re-fetching it
      // put the whole page through a loading pass for every flick of a switch — which is what made
      // it flicker, and what let two quick toggles land their answers out of order.
      onSuccess = { showDebridNotice("${debridProviderLabel(provider)} ${if (enabled) "enabled" else "disabled"}.", loading = false) },
      onFailure = { message -> recoverDebridChange(provider, enabled, previous, message) },
    )
  }
  /**
   * Second attempt at a change the account refused because it has no such service.
   *
   * The account can be missing a service the device is still showing: turning cloud sync on uploads
   * each key, and one the provider would not validate never lands, leaving a card whose every
   * control answers "account not found". The device holds the credential either way, so it is
   * uploaded and the change repeated once. If that fails too, the reason is the provider's own and
   * worth reading — the switch goes back and says so.
   */
  private fun recoverDebridChange(provider: String, enabled: Boolean, previous: List<DebridAccount>, message: String) {
    val session = uiState.session
    val storedKey = DebridKeyStore.load(getApplication()).firstOrNull { it.provider == provider }
    if (session == null || storedKey == null || !message.contains("not found", ignoreCase = true)) {
      uiState = uiState.copy(debridAccounts = previous, debridNoticeMessage = message, debridNoticeIsError = true)
      return
    }
    viewModelScope.launch {
      val recovered = apiClient
        .addDebridAccount(session, provider, storedKey.apiKey, enabled = enabled, priority = storedKey.priority)
        .mapCatching { apiClient.setDebridAccountEnabled(session, provider, enabled).getOrThrow() }
      recovered.fold(
        onSuccess = {
          showDebridNotice("${debridProviderLabel(provider)} ${if (enabled) "enabled" else "disabled"}.", loading = false)
        },
        onFailure = { error ->
          uiState = uiState.copy(
            debridAccounts = previous,
            debridNoticeMessage = "${debridProviderLabel(provider)} is not saved to your StreamDek account: ${error.message ?: message}",
            debridNoticeIsError = true,
          )
        },
      )
    }
  }

  fun moveDebridAccount(provider: String, delta: Int) {
    val session = debridSyncSession() ?: run {
      val stored = DebridKeyStore.load(getApplication()).toMutableList()
      val index = stored.indexOfFirst { it.provider == provider }
      val target = (index + delta).coerceIn(0, (stored.size - 1).coerceAtLeast(0))
      if (index < 0 || index == target) return
      stored.add(target, stored.removeAt(index))
      applyLocalDebridKeys(stored)
      showDebridNotice("Premium service priority updated.${debridDeviceOnlySuffix()}", loading = false)
      return
    }
    val current = uiState.debridAccounts.sortedBy { it.priority }.toMutableList()
    val previous = current.toList()
    val index = current.indexOfFirst { it.provider == provider }
    val target = (index + delta).coerceIn(0, current.lastIndex)
    if (index < 0 || index == target) return
    val item = current.removeAt(index)
    current.add(target, item)
    val reordered = current.mapIndexed { priority, account -> account.copy(priority = priority) }
    uiState = uiState.copy(debridAccounts = reordered)
    launchWork(
      onStart = { dismissDebridNotice() },
      block = { apiClient.reorderDebridAccounts(session, reordered.map { it.provider }) },
      // Same as the switch above: the order on screen is the order that was sent.
      onSuccess = { showDebridNotice("Premium service priority updated.", loading = false) },
      onFailure = { message -> uiState = uiState.copy(debridAccounts = previous, debridNoticeMessage = message, debridNoticeIsError = true) },
    )
  }

  fun requestTraktDeviceCode() {
    launchWork(onStart = { uiState = uiState.copy(traktLoading = true) }, block = { apiClient.requestTraktDeviceCode() }, onSuccess = { code -> uiState = uiState.copy(traktLoading = false, pendingDeviceCode = code) })
  }
  fun pollTraktAuthorization() {
    val session = uiState.session ?: return
    val profileId = uiState.activeProfileId ?: return
    val code = uiState.pendingDeviceCode ?: return
    launchWork(onStart = { uiState = uiState.copy(traktLoading = true) }, block = { apiClient.pollTraktDeviceCode(session, profileId, code.deviceCode) }, onSuccess = { refreshTraktData() })
  }
  fun disconnectTrakt() { val session = uiState.session ?: return; val profileId = uiState.activeProfileId ?: return; launchWork(onStart = {}, block = { apiClient.disconnectTrakt(session, profileId) }, onSuccess = { refreshTraktData() }) }

  // --- Content services (TMDB, MDBList) --------------------------------------------------------
  //
  // The viewer's own enrichment keys. Everything below funnels through ServiceCredentialManager,
  // which owns the vault, the precedence and the prompting policy — nothing here decides on its
  // own which key is in play or whether it may be uploaded.

  private val credentials: ServiceCredentialManager? get() = apiClient.serviceCredentials

  /**
   * Re-reads what the account holds and folds it together with what this device holds.
   *
   * Called on sign-in, on resume and after any change made here — which is also how a key added
   * on the web portal or another phone reaches this one, without a restart and without a
   * long-lived cached copy of somebody's secret.
   */
  fun refreshContentServices() {
    val manager = credentials ?: return
    val session = uiState.session
    if (session == null) {
      // Signed out, the device vault is the whole story. Cards still work; only the account
      // column is unknown, and it is shown as absent rather than guessed at.
      uiState = uiState.copy(contentServices = mergeContentServices(manager, null, uiState.contentServices))
      return
    }
    launchWork(
      onStart = { uiState = uiState.copy(contentServices = uiState.contentServices.copy(loading = true)) },
      block = { apiClient.fetchContentServiceCredentials(session) },
      onSuccess = { account ->
        migrateLegacyMdblistKey(manager, account)
        uiState = uiState.copy(contentServices = mergeContentServices(manager, account, uiState.contentServices))
        maybeOfferContentServicesSetup()
      },
      // A failed read is not a reason to tell someone their keys have gone. The device half is
      // still true, so it is shown, and the account half is retried on the next refresh.
      onFailure = {
        uiState = uiState.copy(contentServices = mergeContentServices(manager, null, uiState.contentServices))
      },
    )
  }

  private fun mergeContentServices(
    manager: ServiceCredentialManager,
    account: AccountCredentials?,
    previous: ContentServicesState,
  ): ContentServicesState = previous.copy(
    tmdb = manager.merge(ContentService.Tmdb, account?.tmdb),
    mdblist = manager.merge(ContentService.Mdblist, account?.mdblist),
    sharedFallbackAvailable = account?.sharedFallbackAvailable ?: previous.sharedFallbackAvailable,
    loading = false,
    busy = null,
    loaded = true,
  )

  /**
   * Moves a pre-existing plaintext MDBList key off this device.
   *
   * The old key lived in ordinary preferences. The backend has already moved the account's copy
   * into encrypted storage, so in the common case there is simply nothing to keep and the
   * plaintext is deleted. Where the account has none — a viewer who was signed out, or whose key
   * only ever existed locally — it is moved into the keystore vault as a device key rather than
   * uploaded, because it was never the viewer's choice to share it.
   */
  private fun migrateLegacyMdblistKey(manager: ServiceCredentialManager, account: AccountCredentials?) {
    val legacy = appSettingsStore.legacyMdblistApiKey()
    if (legacy.isBlank()) return
    if (account?.mdblist?.configured != true && !manager.hasDeviceKey(ContentService.Mdblist)) {
      manager.saveDeviceKey(ContentService.Mdblist, legacy)
    }
    appSettingsStore.clearLegacyMdblistApiKey()
  }

  /**
   * Checks a key and puts it where the viewer asked.
   *
   * The check happens first in both cases, so "This device only" gets the same confirmation as
   * saving to the account. It is also the only path by which a key ever leaves this device: a
   * device-only key is checked and stored locally, and nothing is written to the account.
   */
  fun submitContentServiceKey(service: ContentService, apiKey: String, choice: StorageChoice) {
    val manager = credentials ?: return
    val trimmed = apiKey.trim()
    if (trimmed.length < 8) {
      uiState = uiState.copy(
        contentServices = uiState.contentServices.copy(
          notice = CredentialFailure.Malformed.message,
          noticeIsError = true,
          noticeService = service,
        ),
      )
      return
    }
    val session = uiState.session
    if (session == null) {
      // No account to check the key through, so the device asks the service directly. Storing it
      // unverified would mean the card claimed a working connection that nothing had established.
      launchWork(
        onStart = {
          uiState = uiState.copy(
            contentServices = uiState.contentServices.copy(busy = service, notice = null),
          )
        },
        block = { apiClient.validateContentServiceKeyDirect(service, trimmed) },
        onSuccess = { outcome ->
          when (outcome) {
            is CredentialCheck.Valid -> storeDeviceKey(manager, service, trimmed, verified = true)
            is CredentialCheck.Failed -> uiState = uiState.copy(
              contentServices = uiState.contentServices.copy(
                busy = null,
                notice = outcome.failure.message,
                noticeIsError = true,
                noticeService = service,
              ),
            )
          }
        },
        onFailure = { message ->
          uiState = uiState.copy(
            contentServices = uiState.contentServices.copy(
              busy = null,
              notice = message,
              noticeIsError = true,
              noticeService = service,
            ),
          )
        },
      )
      return
    }

    val savingToAccount = choice == StorageChoice.SaveToStreamDek
    launchWork(
      onStart = { uiState = uiState.copy(contentServices = uiState.contentServices.copy(busy = service, notice = null)) },
      block = {
        if (savingToAccount) {
          apiClient.saveContentServiceKey(session, service, trimmed).map { it as Any }
        } else {
          apiClient.validateContentServiceKey(session, service, trimmed).map { it as Any }
        }
      },
      onSuccess = { outcome ->
        when (outcome) {
          is AccountCredentialState -> {
            // Saved to the account, so this device deliberately keeps no copy of its own: one
            // key, one place, and removing it from the account removes it everywhere.
            manager.clearDeviceKey(service)
            noteContentServiceResult(
              service,
              "${service.label} connected and saved to your StreamDek account. Your TV will pick it up automatically.",
            )
          }
          is CredentialCheck.Valid -> storeDeviceKey(manager, service, trimmed, verified = true)
          is CredentialCheck.Failed -> uiState = uiState.copy(
            contentServices = uiState.contentServices.copy(
              busy = null,
              notice = outcome.failure.message,
              noticeIsError = true,
              noticeService = service,
            ),
          )
          else -> uiState = uiState.copy(contentServices = uiState.contentServices.copy(busy = null))
        }
      },
      onFailure = { message ->
        uiState = uiState.copy(
          contentServices = uiState.contentServices.copy(
            busy = null,
            notice = message,
            noticeIsError = true,
            noticeService = service,
          ),
        )
      },
    )
  }

  private fun storeDeviceKey(
    manager: ServiceCredentialManager,
    service: ContentService,
    apiKey: String,
    verified: Boolean,
  ) {
    if (!manager.saveDeviceKey(service, apiKey)) {
      uiState = uiState.copy(
        contentServices = uiState.contentServices.copy(
          busy = null,
          notice = "This device could not store the key securely, so it has not been saved. " +
            "Saving it to your StreamDek account instead will work.",
          noticeIsError = true,
          noticeService = service,
        ),
      )
      return
    }
    noteContentServiceResult(
      service,
      if (verified) {
        "${service.label} accepted your key. It is connected and kept on this device only."
      } else {
        "${service.label} key saved on this device. It will be checked the first time it is used."
      },
    )
  }

  /**
   * Copies a device key up to the account, at the viewer's request.
   *
   * The only route by which a device-only key ever reaches StreamDek, and it exists because
   * changing your mind should not mean finding the key again. The local copy is dropped once the
   * account has it, so there is one key in one place afterwards.
   */
  fun copyContentServiceKeyToAccount(service: ContentService) {
    val manager = credentials ?: return
    val session = uiState.session ?: return
    val key = manager.deviceKey(service) ?: return
    launchWork(
      onStart = { uiState = uiState.copy(contentServices = uiState.contentServices.copy(busy = service, notice = null)) },
      block = { apiClient.saveContentServiceKey(session, service, key) },
      onSuccess = {
        manager.clearDeviceKey(service)
        noteContentServiceResult(
          service,
          "${service.label} is now saved to your StreamDek account and available on your other devices.",
        )
      },
      onFailure = { message ->
        uiState = uiState.copy(
          contentServices = uiState.contentServices.copy(
            busy = null,
            notice = message,
            noticeIsError = true,
            noticeService = service,
          ),
        )
      },
    )
  }

  /**
   * Removes a key, from wherever the viewer said.
   *
   * The two scopes are never conflated. Removing the account copy is announced as affecting every
   * device, because it does; removing the device copy is local and leaves the account key — and
   * this device — working from that.
   */
  fun removeContentServiceKey(service: ContentService, scope: CredentialRemoval) {
    val manager = credentials ?: return
    if (scope == CredentialRemoval.Device) {
      manager.clearDeviceKey(service)
      noteContentServiceResult(service, "${service.label} key removed from this device.")
      return
    }
    val session = uiState.session ?: return
    launchWork(
      onStart = { uiState = uiState.copy(contentServices = uiState.contentServices.copy(busy = service, notice = null)) },
      block = { apiClient.removeContentServiceKey(session, service) },
      onSuccess = {
        noteContentServiceResult(
          service,
          "${service.label} key removed from your StreamDek account. Your other devices will stop using it.",
        )
      },
      onFailure = { message ->
        uiState = uiState.copy(
          contentServices = uiState.contentServices.copy(
            busy = null,
            notice = message,
            noticeIsError = true,
            noticeService = service,
          ),
        )
      },
    )
  }

  private fun noteContentServiceResult(service: ContentService, message: String) {
    val manager = credentials ?: return
    uiState = uiState.copy(
      contentServices = uiState.contentServices.copy(
        busy = null,
        notice = message,
        noticeIsError = false,
        noticeService = service,
      ),
    )
    refreshContentServices()
    // Whatever was blank because of a missing key is worth another go now that there is one.
    if (service == ContentService.Mdblist) uiState.detail?.let(::refreshExternalRatings)
  }

  fun dismissContentServiceNotice() {
    uiState = uiState.copy(
      contentServices = uiState.contentServices.copy(notice = null, noticeService = null),
    )
  }

  // --- Prompting ------------------------------------------------------------------------------

  /** Offers the setup card, if the manager's own policy says now is a reasonable moment. */
  private fun maybeOfferContentServicesSetup() {
    val manager = credentials ?: return
    if (uiState.contentServicesPromptVisible) return
    if (!manager.shouldOfferSetup(uiState.contentServices)) return
    uiState = uiState.copy(contentServicesPromptVisible = true)
  }

  fun showContentServicesSetup() {
    uiState = uiState.copy(contentServicesPromptVisible = true)
  }

  /**
   * "Do this later", honoured.
   *
   * The deferral is written down, so the next launch does not ask again — the reminder comes back
   * after the interval the viewer selected rather than on every refresh.
   */
  fun deferContentServicesSetup(deferral: SetupDeferral) {
    credentials?.deferSetup(deferral)
    uiState = uiState.copy(contentServicesPromptVisible = false)
  }

  fun dismissContentServicesSetup() {
    // "Done" or "Continue" closes an incomplete setup for at least a day as well. Without this,
    // the next resume refresh immediately recreated the prompt even though it had just been read.
    if (!uiState.contentServices.allConfigured) credentials?.deferSetup(SetupDeferral.Tomorrow)
    uiState = uiState.copy(contentServicesPromptVisible = false)
  }

  /** The small in-place nudge, shown at most once a day per service and never as a modal. */
  private fun offerContentServiceHint(service: ContentService) {
    val manager = credentials ?: return
    if (uiState.contentServiceHint != null || uiState.contentServicesPromptVisible) return
    if (!manager.shouldHintFor(service)) return
    manager.noteHintShown(service)
    uiState = uiState.copy(contentServiceHint = service)
  }

  fun dismissContentServiceHint() {
    uiState = uiState.copy(contentServiceHint = null)
  }

  // --- SIMKL / MDBList -------------------------------------------------------------------------
  // Connections are per profile, so every call carries the active profile and switching profiles
  // clears the cached statuses before refetching.

  fun refreshSyncServices() {
    val session = uiState.session
    val profileId = uiState.activeProfileId
    if (session == null || profileId == null) {
      uiState = uiState.copy(simklStatus = SyncServiceStatus(), mdblistStatus = SyncServiceStatus(), punchplayStatus = SyncServiceStatus())
      return
    }
    launchWork(
      onStart = { uiState = uiState.copy(syncSourcesRefreshing = true) },
      block = {
        coroutineScope {
          // A status call that never lands (older backend without these routes) is reported as
          // unavailable rather than "not connected", so the page can explain instead of offering
          // a Connect button that cannot succeed.
          val unreachable = SyncServiceStatus(available = false, checked = false)
          val simkl = async { apiClient.fetchSyncServiceStatus(session, profileId, SyncService.Simkl.id).getOrElse { unreachable } }
          val mdblist = async { apiClient.fetchSyncServiceStatus(session, profileId, SyncService.Mdblist.id).getOrElse { unreachable } }
          val punchplay = async { apiClient.fetchSyncServiceStatus(session, profileId, SyncService.Punchplay.id).getOrElse { unreachable } }
          Result.success(Triple(simkl.await(), mdblist.await(), punchplay.await()))
        }
      },
      onSuccess = { (simkl, mdblist, punchplay) ->
        uiState = uiState.copy(
          simklStatus = simkl,
          mdblistStatus = mdblist,
          punchplayStatus = punchplay,
          syncSourcesRefreshing = false,
          syncSourcesCheckedAt = System.currentTimeMillis(),
        )
      },
      // A tracking service being unreachable is not worth an error banner over the whole app.
      onFailure = { uiState = uiState.copy(syncSourcesRefreshing = false) },
    )
  }

  /** Chooses which connected service supplies Home rows and Continue Watching. */
  fun setPrimarySyncService(serviceId: String) {
    val normalized = normalizedPrimarySyncService(serviceId)
    if (normalized == uiState.primarySyncService) return
    appSettingsStore.savePrimarySyncService(normalized)
    uiState = uiState.copy(
      primarySyncService = normalized,
      // The previous service's rows belong to it, not the new one — clear them so nothing stale
      // lingers on Home while the new source loads.
      traktContinueWatching = emptyList(),
      traktWatchlist = emptyList(),
      mergedWatchlist = mergeWatchlistWithLocal(emptyList()),
      infoMessage = "${syncServiceLabel(normalized)} now feeds Home rows and Continue Watching.",
    )
    syncCloudPreferences()
    refreshTraktData()
  }

  fun requestSyncServiceDeviceCode(serviceId: String) {
    launchWork(
      onStart = { uiState = uiState.copy(syncServiceLoading = serviceId, pendingSyncService = serviceId, pendingSyncServiceCode = null) },
      block = { apiClient.requestSyncServiceDeviceCode(serviceId) },
      onSuccess = { code -> uiState = uiState.copy(syncServiceLoading = null, pendingSyncServiceCode = code) },
      onFailure = { message -> uiState = uiState.copy(syncServiceLoading = null, pendingSyncService = null, errorMessage = message) },
    )
  }

  fun pollSyncServiceAuthorization(serviceId: String) {
    // These used to return silently, which made a tap look like a dead button. A tracking
    // connection is stored against the account and profile, so both are genuinely required —
    // say so rather than doing nothing.
    val session = uiState.session ?: run {
      uiState = uiState.copy(errorMessage = "Sign in to connect ${syncServiceLabel(serviceId)}.")
      return
    }
    val profileId = uiState.activeProfileId ?: run {
      uiState = uiState.copy(errorMessage = "Choose a profile before connecting ${syncServiceLabel(serviceId)}.")
      return
    }
    val code = uiState.pendingSyncServiceCode?.takeIf { uiState.pendingSyncService == serviceId } ?: run {
      uiState = uiState.copy(errorMessage = "Start a new ${syncServiceLabel(serviceId)} pairing first.")
      return
    }
    launchWork(
      onStart = { uiState = uiState.copy(syncServiceLoading = serviceId) },
      block = { apiClient.pollSyncServiceDeviceCode(session, profileId, serviceId, code.deviceCode) },
      onSuccess = {
        uiState = uiState.copy(syncServiceLoading = null, pendingSyncService = null, pendingSyncServiceCode = null)
        refreshSyncServices()
      },
      onFailure = { message -> uiState = uiState.copy(syncServiceLoading = null, errorMessage = message) },
    )
  }

  fun connectSyncServiceApiKey(serviceId: String, apiKey: String) {
    val session = uiState.session ?: run {
      uiState = uiState.copy(errorMessage = "Sign in to connect a tracking service.")
      return
    }
    val profileId = uiState.activeProfileId ?: run {
      uiState = uiState.copy(errorMessage = "Choose a profile before connecting ${syncServiceLabel(serviceId)}.")
      return
    }
    val trimmed = apiKey.trim()
    if (trimmed.isBlank()) {
      uiState = uiState.copy(errorMessage = "Enter an access key first.")
      return
    }
    launchWork(
      onStart = { uiState = uiState.copy(syncServiceLoading = serviceId) },
      block = { apiClient.connectSyncServiceApiKey(session, profileId, serviceId, trimmed) },
      onSuccess = { status ->
        uiState = uiState.copy(syncServiceLoading = null, infoMessage = "Connected to ${syncServiceLabel(serviceId)}.")
        if (serviceId == SyncService.Mdblist.id) {
          // The same key answers for ratings, and the backend saves it as this account's
          // MDBList content-service credential in the same step — so rather than keeping a
          // second copy in step by hand, the credential state is simply re-read.
          uiState = uiState.copy(mdblistStatus = status)
          refreshContentServices()
          uiState.detail?.let(::refreshExternalRatings)
        }
        refreshSyncServices()
      },
      onFailure = { message -> uiState = uiState.copy(syncServiceLoading = null, errorMessage = message) },
    )
  }

  fun disconnectSyncService(serviceId: String) {
    val session = uiState.session ?: run {
      uiState = uiState.copy(errorMessage = "Sign in to manage ${syncServiceLabel(serviceId)}.")
      return
    }
    val profileId = uiState.activeProfileId ?: run {
      uiState = uiState.copy(errorMessage = "Choose a profile before managing ${syncServiceLabel(serviceId)}.")
      return
    }
    launchWork(
      onStart = { uiState = uiState.copy(syncServiceLoading = serviceId) },
      block = { apiClient.disconnectSyncService(session, profileId, serviceId) },
      onSuccess = {
        uiState = uiState.copy(syncServiceLoading = null, pendingSyncService = null, pendingSyncServiceCode = null)
        refreshSyncServices()
      },
      onFailure = { message -> uiState = uiState.copy(syncServiceLoading = null, errorMessage = message) },
    )
  }

  /** Pushes a watchlist add/remove to every connected service other than Trakt, which has its own. */
  private fun fanOutWatchlistToSyncServices(item: MediaItem, remove: Boolean) {
    val session = uiState.session ?: return
    val profileId = uiState.activeProfileId ?: return
    val connected = buildList {
      if (uiState.simklStatus.connected) add(SyncService.Simkl.id)
      if (uiState.mdblistStatus.connected) add(SyncService.Mdblist.id)
      if (uiState.punchplayStatus.connected) add(SyncService.Punchplay.id)
    }
    viewModelScope.launch {
      // StreamDek's own list is written every time, whatever the profile tracks with. It costs one
      // row and it is what lets someone switch to SyncDek and find their watchlist already there
      // instead of having to rebuild it.
      apiClient.syncDekWatchlist(session, profileId, item, remove)
      connected.forEach { serviceId ->
        apiClient.syncServiceWatchlist(session, profileId, serviceId, item, remove)
      }
    }
  }

  fun refreshConnectedServices() {
    val session = uiState.session ?: run {
      uiState = uiState.copy(infoMessage = "Sign in to refresh settings from cloud sync.")
      return
    }
    if (uiState.syncRefreshing) return
    if (!cloudSyncAllowed()) {
      uiState = uiState.copy(infoMessage = "Sync is paused on cellular. Enable Sync on Cellular to refresh account and addon data.")
      return
    }
    launchWork(
      onStart = { uiState = uiState.copy(syncRefreshing = true, errorMessage = null, infoMessage = null) },
      block = {
        coroutineScope {
          val preferences = async { apiClient.fetchCloudPlaybackPreferences(session, uiState.activeProfileId) }
          val minimumAnimation = async { delay(500) }
          minimumAnimation.await()
          preferences.await()
        }
      },
      onSuccess = { preferences ->
        applyCloudPlaybackPreferences(preferences)
        uiState = uiState.copy(syncRefreshing = false, infoMessage = "Cloud settings refreshed.")
        refreshProfiles(showLoading = false, refreshScopedData = false)
        refreshAddons()
        loadDebridAccounts()
        refreshTraktData()
        refreshSyncServices()
        loadHome(force = true)
      },
      onFailure = { message -> uiState = uiState.copy(syncRefreshing = false, errorMessage = message) },
    )
  }

  private fun applyCloudPlaybackPreferences(preferences: CloudPlaybackPreferences) {
    val appAppearance = preferences.appAppearance?.let { runCatching { AppAppearance.valueOf(it) }.getOrNull() }
    val themePreset = preferences.themePreset?.let { runCatching { AppThemePreset.valueOf(it) }.getOrNull() }
    val headerStyle = preferences.headerStyle?.let { runCatching { HeaderStyle.valueOf(it) }.getOrNull() }
    val detailPageStyle = preferences.detailPageStyle?.let { runCatching { DetailPageStyle.valueOf(it) }.getOrNull() }
    val continueWatchingStyle = preferences.continueWatchingStyle?.let { runCatching { ContinueWatchingStyle.valueOf(it) }.getOrNull() }
    val networkCardStyle = preferences.networkCardStyle?.let { runCatching { NetworkCardStyle.valueOf(it) }.getOrNull() }
    val seasonTabStyle = preferences.seasonTabStyle?.let { runCatching { SeasonTabStyle.valueOf(it) }.getOrNull() }
    val decoderMode = preferences.decoderMode?.let(::normalizeDecoderModeSetting)
    val renderSurface = preferences.renderSurface?.let(::normalizeRenderSurfaceSetting)
    val playerEngine = preferences.playerEngine?.let(::normalizePlayerEngineSetting)
    val preferredAudioLanguage = uiState.profiles.firstOrNull { it.id == uiState.activeProfileId }?.audioLanguage?.takeIf { it.isNotBlank() }?.let(::normalizePreferredAudioLanguage) ?: preferences.preferredAudioLanguage?.let(::normalizePreferredAudioLanguage)
    val ratingProviders = preferences.enabledRatingProviders?.map { it.trim().lowercase() }?.filter(String::isNotBlank)?.toSet()
    val fusionBadgeUrls = preferences.fusionBadgeUrls?.distinct()?.take(MAX_FUSION_BADGE_URLS)
    val activeFusionBadgeUrl = preferences.activeFusionBadgeUrl?.takeIf { it in (fusionBadgeUrls ?: uiState.fusionBadgeUrls) }
    val homeCatalogRows = preferences.homeCatalogRowsJson?.let(::parseHomeCatalogRows)

    appAppearance?.let {
      appSettingsStore.saveAppAppearance(it)
      // An appearance arriving from another device has to reach the platform too, or this phone's
      // splash keeps describing the choice the account no longer holds.
      applyAppNightMode(getApplication())
    }
    themePreset?.let(appSettingsStore::saveThemePreset)
    headerStyle?.let(appSettingsStore::saveHeaderStyle)
    preferences.showNavLabels?.let(appSettingsStore::saveShowNavLabels)
    preferences.collapsibleNavigationEnabled?.let(appSettingsStore::saveCollapsibleNavigationEnabled)
    preferences.navigationAutoCollapseSeconds?.let(appSettingsStore::saveNavigationAutoCollapseSeconds)
    preferences.syncOnCellular?.let(appSettingsStore::saveSyncOnCellular)
    detailPageStyle?.let(appSettingsStore::saveDetailPageStyle)
    continueWatchingStyle?.let(appSettingsStore::saveContinueWatchingStyle)
    networkCardStyle?.let(appSettingsStore::saveNetworkCardStyle)
    preferences.liveLandscapeCards?.let(appSettingsStore::saveLiveLandscapeCards)
    preferences.liveCategoriesEnabled?.let(appSettingsStore::saveLiveCategoriesEnabled)
    preferences.primarySyncService?.let { appSettingsStore.savePrimarySyncService(normalizedPrimarySyncService(it)) }
    preferences.liveFavouriteDrawerCards?.let(appSettingsStore::saveLiveFavouriteDrawerCards)
    preferences.showHeroSynopsis?.let(appSettingsStore::saveShowHeroSynopsis)
    preferences.vividAmbient?.let(appSettingsStore::saveVividAmbient)
    preferences.ambientTintPercent?.let(appSettingsStore::saveAmbientTintPercent)
    (preferences.detailAmbientTintPercent ?: preferences.ambientTintPercent)?.let(appSettingsStore::saveDetailAmbientTintPercent)
    preferences.defaultAppCatalogsEnabled?.let(appSettingsStore::saveDefaultAppCatalogsEnabled)
    homeCatalogRows?.let(appSettingsStore::saveHomeCatalogRows)
    seasonTabStyle?.let(appSettingsStore::saveSeasonTabStyle)
    preferences.heroTrailerAutoplay?.let(appSettingsStore::saveHeroTrailerAutoplay)
    preferences.heroTrailerResolution?.let(appSettingsStore::saveHeroTrailerResolution)
    preferences.heroTrailerDelaySeconds?.let(appSettingsStore::saveHeroTrailerDelaySeconds)
    preferences.trailerCacheClearHours?.let(appSettingsStore::saveTrailerCacheClearHours)
    preferences.detailBackgroundMode?.let { mode ->
      runCatching { BackgroundMode.valueOf(mode) }.getOrNull()?.let(appSettingsStore::saveDetailBackgroundMode)
    }
    preferences.homeBackgroundMode?.let { mode ->
      runCatching { BackgroundMode.valueOf(mode) }.getOrNull()?.takeIf { it in homeBackgroundModes }?.let(appSettingsStore::saveHomeBackgroundMode)
    }
    preferences.secondaryAudioLanguage?.let(appSettingsStore::saveSecondaryAudioLanguage)
    preferences.preferredSubtitleLanguage?.let(appSettingsStore::savePreferredSubtitleLanguage)
    preferences.secondarySubtitleLanguage?.let(appSettingsStore::saveSecondarySubtitleLanguage)
    preferences.useForcedSubtitles?.let(appSettingsStore::saveUseForcedSubtitles)
    preferences.showOnlyPreferredSubtitleLanguages?.let(appSettingsStore::saveShowOnlyPreferredSubtitleLanguages)
    preferences.addonSubtitleLoading?.let(appSettingsStore::saveAddonSubtitleLoading)
    preferences.subtitleDefaultSource?.let(appSettingsStore::saveSubtitleDefaultSource)
    preferences.ratingsEnabled?.let(appSettingsStore::saveRatingsEnabled)
    preferences.externalRatingsEnabled?.let(appSettingsStore::saveExternalRatingsEnabled)
    ratingProviders?.let(appSettingsStore::saveEnabledRatingProviders)
    // The MDBList key deliberately does not come from here any more. It was a secret riding
    // on an ordinary settings document, readable by anything that could read preferences;
    // the backend has moved any existing one into encrypted per-account storage and blanks
    // the field, so there is nothing left here to apply.
    preferences.pictureInPictureEnabled?.let(appSettingsStore::savePictureInPictureEnabled)
    decoderMode?.let(appSettingsStore::saveDecoderMode)
    renderSurface?.let(appSettingsStore::saveRenderSurface)
    playerEngine?.let(appSettingsStore::savePlayerEngine)
    preferredAudioLanguage?.let(appSettingsStore::savePreferredAudioLanguage)
    preferences.skipIntroEnabled?.let(appSettingsStore::saveSkipIntroEnabled)
    preferences.skipRecapEnabled?.let(appSettingsStore::saveSkipRecapEnabled)
    preferences.skipEndingEnabled?.let(appSettingsStore::saveSkipEndingEnabled)
    preferences.autoSkipIntroEnabled?.let(appSettingsStore::saveAutoSkipIntroEnabled)
    preferences.autoSkipRecapEnabled?.let(appSettingsStore::saveAutoSkipRecapEnabled)
    preferences.autoSkipEndingEnabled?.let(appSettingsStore::saveAutoSkipEndingEnabled)
    // Same account-level/profile-scoped split as the MDBList key above: the cloud copy only seeds
    // a profile that has none of its own.
    if (uiState.introdbApiKey.isBlank()) preferences.introdbApiKey?.takeIf { it.isNotBlank() }?.let(appSettingsStore::saveIntrodbApiKey)
    preferences.autoPlayNextEpisode?.let(appSettingsStore::saveAutoPlayNextEpisode)
    preferences.preferBingeGroup?.let(appSettingsStore::savePreferBingeGroup)
    preferences.autoLoadSubtitles?.let(appSettingsStore::saveAutoLoadSubtitles)
    preferences.nextEpisodeThresholdMode?.let(appSettingsStore::saveNextEpisodeThresholdMode)
    preferences.nextEpisodeThresholdPercent?.let(appSettingsStore::saveNextEpisodeThresholdPercent)
    preferences.nextEpisodeThresholdMinutes?.let(appSettingsStore::saveNextEpisodeThresholdMinutes)
    preferences.endOfPlaybackRecommendationsEnabled?.let(appSettingsStore::saveEndOfPlaybackRecommendationsEnabled)
    preferences.recommendationTiming?.let(appSettingsStore::saveRecommendationTiming)
    preferences.recommendationItemCount?.let(appSettingsStore::saveRecommendationItemCount)
    preferences.showStreamsList?.let(appSettingsStore::saveShowStreamsList)
    preferences.rememberLastSource?.let(appSettingsStore::saveRememberLastSource)
    preferences.favoriteSourceKeys?.map(String::trim)?.filter(String::isNotBlank)?.take(250)?.toSet()?.let(appSettingsStore::saveFavoriteSourceKeys)
    preferences.blurUnwatchedEpisodes?.let(appSettingsStore::saveBlurUnwatchedEpisodes)
    preferences.fusionBadgesEnabled?.let(appSettingsStore::saveFusionBadges)
    preferences.streamDekFormattingEnabled?.let(appSettingsStore::saveStreamDekFormatting)
    preferences.showSizeBadges?.let(appSettingsStore::saveShowSizeBadges)
    preferences.preferredQuality?.let(appSettingsStore::savePreferredQuality)
    preferences.maxFileSizeGb?.let(appSettingsStore::saveMaxFileSizeGb)
    preferences.badgePosition?.let(appSettingsStore::saveBadgePosition)
    fusionBadgeUrls?.let { appSettingsStore.saveFusionBadgeUrls(it, activeFusionBadgeUrl) }
    preferences.autoUpdateChecksEnabled?.let(appSettingsStore::saveAutoUpdateChecks)

    uiState = uiState.copy(
      appAppearance = appAppearance ?: uiState.appAppearance,
      themePreset = themePreset ?: uiState.themePreset,
      headerStyle = headerStyle ?: uiState.headerStyle,
      showNavLabels = preferences.showNavLabels ?: uiState.showNavLabels,
      collapsibleNavigationEnabled = preferences.collapsibleNavigationEnabled ?: uiState.collapsibleNavigationEnabled,
      navigationAutoCollapseSeconds = preferences.navigationAutoCollapseSeconds?.coerceIn(2, 15) ?: uiState.navigationAutoCollapseSeconds,
      syncOnCellular = preferences.syncOnCellular ?: uiState.syncOnCellular,
      detailPageStyle = detailPageStyle ?: uiState.detailPageStyle,
      continueWatchingStyle = continueWatchingStyle ?: uiState.continueWatchingStyle,
      networkCardStyle = networkCardStyle ?: uiState.networkCardStyle,
