      heroTrailerDelaySeconds = preferences.heroTrailerDelaySeconds?.coerceIn(0, MAX_TRAILER_DELAY_SECONDS)
        ?: uiState.heroTrailerDelaySeconds,
      ratingsEnabled = preferences.ratingsEnabled ?: uiState.ratingsEnabled,
      externalRatingsEnabled = preferences.externalRatingsEnabled ?: uiState.externalRatingsEnabled,
      enabledRatingProviders = ratingProviders ?: uiState.enabledRatingProviders,
      pictureInPictureEnabled = preferences.pictureInPictureEnabled ?: uiState.pictureInPictureEnabled,
      decoderMode = decoderMode ?: uiState.decoderMode,
      renderSurface = renderSurface ?: uiState.renderSurface,
      playerEngine = playerEngine ?: uiState.playerEngine,
      preferredAudioLanguage = preferredAudioLanguage ?: uiState.preferredAudioLanguage,
      skipIntroEnabled = preferences.skipIntroEnabled ?: uiState.skipIntroEnabled,
      skipRecapEnabled = preferences.skipRecapEnabled ?: uiState.skipRecapEnabled,
      skipEndingEnabled = preferences.skipEndingEnabled ?: uiState.skipEndingEnabled,
      autoSkipIntroEnabled = preferences.autoSkipIntroEnabled ?: uiState.autoSkipIntroEnabled,
      autoSkipRecapEnabled = preferences.autoSkipRecapEnabled ?: uiState.autoSkipRecapEnabled,
      autoSkipEndingEnabled = preferences.autoSkipEndingEnabled ?: uiState.autoSkipEndingEnabled,
      introdbApiKey = uiState.introdbApiKey.ifBlank { preferences.introdbApiKey?.trim().orEmpty() },
      autoPlayNextEpisode = preferences.autoPlayNextEpisode ?: uiState.autoPlayNextEpisode,
      preferBingeGroup = preferences.preferBingeGroup ?: uiState.preferBingeGroup,
      autoLoadSubtitles = preferences.autoLoadSubtitles ?: uiState.autoLoadSubtitles,
      nextEpisodeThresholdMode = preferences.nextEpisodeThresholdMode ?: uiState.nextEpisodeThresholdMode,
      nextEpisodeThresholdPercent = preferences.nextEpisodeThresholdPercent?.coerceIn(50, 99) ?: uiState.nextEpisodeThresholdPercent,
      nextEpisodeThresholdMinutes = preferences.nextEpisodeThresholdMinutes?.coerceIn(1, 15) ?: uiState.nextEpisodeThresholdMinutes,
      endOfPlaybackRecommendationsEnabled = preferences.endOfPlaybackRecommendationsEnabled ?: uiState.endOfPlaybackRecommendationsEnabled,
      recommendationTiming = preferences.recommendationTiming?.let { RecommendationTiming.fromKey(it).key } ?: uiState.recommendationTiming,
      recommendationItemCount = preferences.recommendationItemCount?.coerceIn(1, 2) ?: uiState.recommendationItemCount,
      showStreamsList = preferences.showStreamsList ?: uiState.showStreamsList,
      rememberLastSource = preferences.rememberLastSource ?: uiState.rememberLastSource,
      favoriteSourceKeys = preferences.favoriteSourceKeys?.map(String::trim)?.filter(String::isNotBlank)?.take(250)?.toSet() ?: uiState.favoriteSourceKeys,
      blurUnwatchedEpisodes = preferences.blurUnwatchedEpisodes ?: uiState.blurUnwatchedEpisodes,
      fusionBadgesEnabled = preferences.fusionBadgesEnabled ?: uiState.fusionBadgesEnabled,
      streamDekFormattingEnabled = preferences.streamDekFormattingEnabled ?: uiState.streamDekFormattingEnabled,
      showSizeBadges = preferences.showSizeBadges ?: uiState.showSizeBadges,
      preferredQuality = preferences.preferredQuality ?: uiState.preferredQuality,
      maxFileSizeGb = preferences.maxFileSizeGb ?: uiState.maxFileSizeGb,
      badgePosition = preferences.badgePosition ?: uiState.badgePosition,
      fusionBadgeUrls = fusionBadgeUrls ?: uiState.fusionBadgeUrls,
      activeFusionBadgeUrl = if (fusionBadgeUrls != null) activeFusionBadgeUrl else uiState.activeFusionBadgeUrl,
      autoUpdateChecksEnabled = preferences.autoUpdateChecksEnabled ?: uiState.autoUpdateChecksEnabled,
    )
    if (homeCatalogRows != null) uiState = uiState.copy(homeSections = applyHomeCatalogLayout(uiState.allHomeSections, homeCatalogRows, uiState.defaultAppCatalogsEnabled))
    // Another device may have switched rows on that this one never fetched.
    refreshHomeIfCatalogsMissing()
    if (fusionBadgeUrls != null) refreshFusionBadgeSources()
    uiState.detail?.let(::refreshExternalRatings)
  }
  fun refreshTraktData() {
    val session = uiState.session
    val profileId = uiState.activeProfileId
    launchWork(
      onStart = { uiState = uiState.copy(traktLoading = true, errorMessage = null) },
      block = {
        coroutineScope {
          val trendingDeferred = async { apiClient.fetchTraktTrending().getOrElse { emptyList() } }
          if (session == null || profileId == null) {
            Result.success(TraktDashboardState(TraktStatus(false, null), emptyList(), emptyList(), emptyList(), trendingDeferred.await()))
          } else {
            // These calls do not depend on one another. The old serial chain made Continue Watching
            // wait behind Trending, connection status, watchlist, and recommendations on launch.
            val primary = uiState.primarySyncService
            val primaryIsTrakt = primary == SyncService.Trakt.id
            // SyncDek needs no connection check: it is on whenever the viewer is signed in. Its
            // Continue Watching is the local resume store, which the home screen already reads
            // directly, so only the watchlist is fetched here.
            val primaryIsSyncDek = primary == SYNCDEK_ID
            val traktStatusDeferred = async { apiClient.fetchTraktStatus(session, profileId).getOrElse { TraktStatus(false, null) } }
            val primaryStatusDeferred = async {
              if (primaryIsTrakt || primaryIsSyncDek) SyncServiceStatus()
              else apiClient.fetchSyncServiceStatus(session, profileId, primary).getOrElse { SyncServiceStatus() }
            }
            // Connection status is the authority for provider-backed reads. Starting the list
            // requests alongside it caused a predictable 401 whenever an unconnected provider
            // happened to be selected as primary.
            val status = traktStatusDeferred.await()
            val primaryStatus = when {
              primaryIsSyncDek -> SyncServiceStatus(connected = true, supportsWatchlist = true, supportsPlayback = false)
              primaryIsTrakt -> SyncServiceStatus(connected = status.connected)
              else -> primaryStatusDeferred.await()
            }
            val primaryConnected = if (primaryIsTrakt) status.connected else primaryStatus.connected
            val continueWatchingDeferred = async {
              when {
                primaryIsSyncDek -> emptyList()
                !primaryConnected || !primaryStatus.supportsPlayback -> emptyList()
                primaryIsTrakt -> apiClient.fetchTraktContinueWatching(session, profileId).getOrElse { emptyList() }
                else -> apiClient.fetchSyncServicePlayback(session, profileId, primary).getOrElse { emptyList() }
              }
            }
            val watchlistDeferred = async {
              when {
                primaryIsSyncDek -> apiClient.fetchSyncDekWatchlist(session, profileId).getOrElse { emptyList() }
                !primaryConnected || !primaryStatus.supportsWatchlist -> emptyList()
                primaryIsTrakt -> apiClient.fetchTraktWatchlist(session, profileId).getOrElse { emptyList() }
                else -> apiClient.fetchSyncServiceWatchlist(session, profileId, primary).getOrElse { emptyList() }
              }
            }
            val recommendationsDeferred = async {
              if (status.connected) apiClient.fetchTraktRecommendations(session, profileId).getOrElse { emptyList() }
              else emptyList()
            }

            val cw = continueWatchingDeferred.await()
            val wl = watchlistDeferred.await()
            val recs = recommendationsDeferred.await()
            Result.success(TraktDashboardState(status, cw, wl, recs, trendingDeferred.await()))
          }
        }
      },
      onSuccess = { dashboard ->
        uiState = uiState.copy(
          traktLoading = false,
          traktStatus = dashboard.status,
          traktContinueWatching = dashboard.continueWatching,
          traktWatchlist = dashboard.watchlist,
          traktRecommendations = dashboard.recommendations,
          traktTrending = dashboard.trending,
          pendingDeviceCode = null,
          mergedWatchlist = mergeWatchlistWithLocal(dashboard.watchlist),
        )
        backfillTrackingArtwork()
      },
      onFailure = { message -> uiState = uiState.copy(traktLoading = false, errorMessage = message) },
    )
  }

  /**
   * Fill in artwork the tracking service did not send.
   *
   * Trakt's enriched endpoints carry TMDB posters inline; SIMKL and MDBList do not, so switching
   * the primary sync service left the watchlist grid drawing empty cards for titles that opened
   * fine on the detail page. The rows still carry a resolvable id (plus title/year), which is
   * exactly what the detail lookup needs, so the images can be recovered client-side.
   */
  private fun backfillTrackingArtwork() {
    val watchlistGaps = uiState.traktWatchlist.filter { it.poster.isNullOrBlank() }
    val continueGaps = uiState.traktContinueWatching.filter { it.poster.isNullOrBlank() }
    val gaps = (watchlistGaps + continueGaps).distinctBy { trackingArtworkKey(it) }
    if (gaps.isEmpty()) return
    trackingArtworkJob?.cancel()
    trackingArtworkJob = viewModelScope.launch {
      // Same bound the other per-item enrichment passes use: enough to fill a screen quickly
      // without firing one request per row at the backend all at once.
      val gate = Semaphore(4)
      val resolved = supervisorScope {
        gaps.map { item ->
          async {
            val key = trackingArtworkKey(item)
            if (trackingArtworkCache.containsKey(key)) return@async key to trackingArtworkCache[key]
            val detail = gate.withPermit {
              apiClient.fetchDetails(item.type, item.tmdbId?.toString() ?: item.id, item.title, item.year).getOrNull()
            }
            key to detail?.let { TrackingArtwork(it.poster, it.backdrop) }?.takeIf { !it.poster.isNullOrBlank() }
          }
        }.awaitAll()
      }
      resolved.forEach { (key, artwork) -> trackingArtworkCache[key] = artwork }
      if (resolved.none { (_, artwork) -> artwork != null }) return@launch
      val watchlist = uiState.traktWatchlist.map(::withCachedArtwork)
      uiState = uiState.copy(
        traktWatchlist = watchlist,
        traktContinueWatching = uiState.traktContinueWatching.map(::withCachedArtwork),
        mergedWatchlist = mergeWatchlistWithLocal(watchlist),
      )
    }
  }

  private fun trackingArtworkKey(item: TraktItem): String = mediaKey(item.type, item.tmdbId?.toString() ?: item.id)

  private fun withCachedArtwork(item: TraktItem): TraktItem {
    if (!item.poster.isNullOrBlank()) return item
    val artwork = trackingArtworkCache[trackingArtworkKey(item)] ?: return item
    return item.copy(poster = artwork.poster, backdrop = item.backdrop?.ifBlank { null } ?: artwork.backdrop)
  }

  fun toggleWatchlist(item: MediaItem) {
    val ownerKey = activeOwnerKey() ?: return
    val previousLocal = loadLocalWatchlist()
    val previousTrakt = uiState.traktWatchlist
    val previousMerged = uiState.mergedWatchlist
    val mutationGeneration = ++watchlistMutationGeneration
    val current = previousLocal.toMutableList()
    val localIndex = current.indexOfFirst { it.id == item.id && normalizedMediaType(it.type) == normalizedMediaType(item.type) }
    // The saved/unsaved state the UI shows comes from the merged list, so that is what a tap has
    // to toggle. A title that is only on the watchlist through Trakt has no local row, and keying
    // off the local store alone would re-add it instead of taking it off.
    val remove = localIndex >= 0 || uiState.mergedWatchlist.containsMedia(item)
    if (remove) {
      if (localIndex >= 0) current.removeAt(localIndex)
    } else {
      current.add(0, item.copy(addedAt = item.addedAt ?: System.currentTimeMillis()))
    }
    watchlistStore.save(ownerKey, current)
    // Drop the Trakt copy optimistically too, otherwise the merge puts the title straight back
    // until the next dashboard refresh lands.
    val traktWatchlist = if (remove) {
      uiState.traktWatchlist.filterNot {
        (it.tmdbId?.toString() ?: it.id) == item.id && normalizedMediaType(it.type) == normalizedMediaType(item.type)
      }
    } else {
      uiState.traktWatchlist
    }
    uiState = uiState.copy(
      traktWatchlist = traktWatchlist,
      mergedWatchlist = mergeWatchlistWithLocal(traktWatchlist, current),
    )
    val session = uiState.session
    val profileId = uiState.activeProfileId
    if (session != null && profileId != null && uiState.traktStatus.connected) {
      launchWork(
        onStart = {},
        block = { apiClient.syncWatchlist(session, profileId, item, remove) },
        onSuccess = { if (mutationGeneration == watchlistMutationGeneration) refreshTraktData() },
        onFailure = { message ->
          if (mutationGeneration != watchlistMutationGeneration) return@launchWork
          watchlistStore.save(ownerKey, previousLocal)
          uiState = uiState.copy(
            traktWatchlist = previousTrakt,
            mergedWatchlist = previousMerged,
            errorMessage = "Watchlist was not updated: $message",
          )
        },
      )
    }
    fanOutWatchlistToSyncServices(item, remove)
    // Adding or removing a series changes what there is to be reminded about. Called here rather
    // than at the top: uiState.mergedWatchlist above is what the reminder list is read from, so it
    // has to be the post-tap one.
    refreshEpisodeReminders()
  }

  fun clearWatchlist() {
    val ownerKey = activeOwnerKey() ?: return
    val itemsToRemove = uiState.mergedWatchlist
    val previousLocal = loadLocalWatchlist()
    val previousTrakt = uiState.traktWatchlist
    val mutationGeneration = ++watchlistMutationGeneration
    watchlistStore.clear(ownerKey)
    uiState = uiState.copy(mergedWatchlist = emptyList())
    val session = uiState.session
    val profileId = uiState.activeProfileId
    if (session != null && profileId != null && uiState.traktStatus.connected && itemsToRemove.isNotEmpty()) {
      launchWork(
        onStart = {},
        block = {
          itemsToRemove.forEach { item -> apiClient.syncWatchlist(session, profileId, item, remove = true) }
          Result.success(Unit)
        },
        onSuccess = { if (mutationGeneration == watchlistMutationGeneration) refreshTraktData() },
        onFailure = { message ->
          if (mutationGeneration != watchlistMutationGeneration) return@launchWork
          watchlistStore.save(ownerKey, previousLocal)
          uiState = uiState.copy(
            traktWatchlist = previousTrakt,
            mergedWatchlist = itemsToRemove,
            errorMessage = "Watchlist was not cleared: $message",
          )
        },
      )
    }
  }

  fun clearContinueWatching() {
    val ownerKey = activeOwnerKey() ?: GUEST_OWNER_KEY
    // Trakt's own progress list is re-fetched on every dashboard refresh, so simply emptying the
    // in-memory copy would let the cleared rows come straight back. The watched-title store is the
    // same local filter markWatched already uses (see loadLocalContinueWatching / refreshTraktData),
    // so recording the cleared titles there is what makes the clear stick.
    val traktItems = uiState.traktContinueWatching.map { MediaItem(it.tmdbId?.toString() ?: it.id, it.type, it.title, it.year, it.poster, it.backdrop, it.rating, it.description.orEmpty()) }
    watchedTitleStore.addAll(ownerKey, uiState.localContinueWatching + traktItems)
    playbackResumeStore.clearResumable(ownerKey)
    // And on the account, or the rows come back: the television still lists them, and this
    // device's own store refills from the server the next time the app comes forward. Scoped to
    // this profile, so it does not empty anyone else's list.
    clearRemoteContinueWatching()
    uiState = uiState.copy(
      localContinueWatching = loadLocalContinueWatching(),
      localResumeEntries = loadResumeEntries(),
      traktContinueWatching = emptyList(),
      infoMessage = "Continue Watching cleared.",
    )
  }

  private fun applyFavouriteChannels(updated: List<MediaItem>) {
    val favouritesOpen = uiState.browseRow?.id == "favourites"
    uiState = uiState.copy(
      favouriteChannels = updated,
      browseRow = if (favouritesOpen) uiState.browseRow?.copy(items = updated) else uiState.browseRow,
      browseLoadedItems = if (favouritesOpen) updated else uiState.browseLoadedItems,
    )
  }

  fun toggleFavouriteChannel(item: MediaItem) {
    val ownerKey = activeOwnerKey() ?: GUEST_OWNER_KEY
    val stored = loadLocalFavouriteChannels()
    // Removal must work off the same loose match the UI uses to draw the filled star, otherwise an
    // already-favourited channel reached from somewhere with different source metadata silently
    // adds a duplicate instead of removing — which reads as the button doing nothing.
    val updated = if (stored.hasFavouriteChannel(item)) {
      stored.withoutFavouriteChannel(item)
    } else {
      // Only ever *add* something that really is a live channel.
      if (!item.isLiveCatalogItem()) return
      listOf(item.copy(addedAt = item.addedAt ?: System.currentTimeMillis())) + stored
    }
    favouriteChannelStore.save(ownerKey, updated)
    applyFavouriteChannels(updated)
    syncLiveFavouriteChannels(updated)
  }

  /**
   * Favourite toggle for the channel currently open on the detail page.
   *
   * The detail page does not always have the original catalog item (deep links and restored state
   * only carry an id), and a [MediaItem] rebuilt from [MediaDetail] alone carries none of the
   * source fields [isLiveCatalogItem] looks at. Since the star is only shown when the detail is
   * live, that context is supplied here rather than inferred from a lossy item.
   */
  fun toggleFavouriteChannelForCurrentDetail() {
    val detail = uiState.detail ?: return
    if (!uiState.detailIsLive) return
    val item = uiState.detailFallbackItem?.takeIf { it.id == detail.id }?.copy(
      title = detail.title,
      poster = detail.poster ?: uiState.detailFallbackItem?.poster,
      backdrop = detail.backdrop ?: uiState.detailFallbackItem?.backdrop,
    ) ?: MediaItem(
      id = detail.id,
      type = "live",
      title = detail.title,
      year = detail.year,
      poster = detail.poster,
      backdrop = detail.backdrop,
      rating = detail.rating,
      description = detail.description,
      sourceAddonId = detailSourceAddonId,
      sourceCatalogType = detailSourceCatalogType ?: "live",
    )
    toggleFavouriteChannel(item)
  }

  fun clearFavouriteChannels() {
    val ownerKey = activeOwnerKey() ?: return
    favouriteChannelStore.clear(ownerKey)
    applyFavouriteChannels(emptyList())
    syncLiveFavouriteChannels(emptyList())
  }

  private fun syncLiveFavouriteChannels(items: List<MediaItem>) {
    val session = uiState.session ?: return
    val profileId = uiState.activeProfileId ?: return
    viewModelScope.launch {
      apiClient.saveLiveFavouriteChannels(session, profileId, items).onFailure { failure ->
        Log.w("StreamDekFavourites", "Live favourites will retry on the next profile refresh", failure)
      }
    }
  }

  private fun refreshLiveFavouriteChannels() {
    val session = uiState.session ?: return
    val profileId = uiState.activeProfileId ?: return
    val ownerKey = activeOwnerKey() ?: return
    val local = favouriteChannelStore.load(ownerKey)
    viewModelScope.launch {
      apiClient.fetchLiveFavouriteChannels(session, profileId).onSuccess { cloud ->
        if (uiState.activeProfileId != profileId || activeOwnerKey() != ownerKey) return@onSuccess
        if (cloud.updatedAt > 0L) {
          // Read back through the store so a cloud copy written by an older build cannot
          // reintroduce duplicates the local list has already been cleaned of.
          favouriteChannelStore.save(ownerKey, cloud.items)
          applyFavouriteChannels(favouriteChannelStore.load(ownerKey))
        } else if (local.isNotEmpty()) {
          apiClient.saveLiveFavouriteChannels(session, profileId, local)
        }
      }.onFailure { failure ->
        Log.w("StreamDekFavourites", "Using locally cached live favourites", failure)
      }
    }
  }

  fun toggleFavouriteChannelForCurrentSession() {
    val session = uiState.playerSession ?: return
    if (!session.isLive) return
    val item = uiState.detailFallbackItem?.takeIf { it.id == session.mediaId } ?: MediaItem(
      id = session.mediaId,
      type = session.mediaType,
      title = session.title,
      year = session.year?.toString(),
      poster = session.poster,
      backdrop = session.backdrop,
      rating = null,
      description = session.synopsis.orEmpty(),
      sourceAddonId = session.currentStream?.addonId,
      sourceAddonName = session.currentStream?.addonName,
    )
    toggleFavouriteChannel(item)
  }

  fun markWatched(item: MediaItem) {
    val ownerKey = activeOwnerKey() ?: return
    watchedTitleStore.add(ownerKey, item)
    val seasonNumber = item.resumeSeasonNumber
    val episodeNumber = item.resumeEpisodeNumber
    if (normalizedMediaType(item.type) == "tv" && seasonNumber != null && episodeNumber != null) {
      playbackResumeStore.remove(ownerKey, item.id, item.type, seasonNumber, episodeNumber)
      val watchedKey = watchedEpisodeKey(item.id, seasonNumber, episodeNumber)
      watchedEpisodeStore.save(
        ownerKey,
        item.id,
        (watchedEpisodeStore.load(ownerKey, item.id) + watchedKey).distinct(),
      )
    } else {
      playbackResumeStore.removeTitle(ownerKey, item.id, item.type)
    }
    if (item.type == "movie") {
      watchedMovieStore.save(ownerKey, (watchedMovieStore.load(ownerKey) + item.id).distinct())
    }

    pushWatchedProgress(item, seasonNumber, episodeNumber)
    val localWatchlist = loadLocalWatchlist().filterNot { it.id == item.id && normalizedMediaType(it.type) == normalizedMediaType(item.type) }
    watchlistStore.save(ownerKey, localWatchlist)
    uiState = uiState.copy(
      mergedWatchlist = uiState.mergedWatchlist.filterNot { it.id == item.id && normalizedMediaType(it.type) == normalizedMediaType(item.type) },
      localContinueWatching = loadLocalContinueWatching(), localResumeEntries = loadResumeEntries(),
      traktContinueWatching = uiState.traktContinueWatching.filterNot {
        (it.tmdbId?.toString() ?: it.id) == item.id && normalizedMediaType(it.type) == normalizedMediaType(item.type) &&
          (seasonNumber == null || episodeNumber == null || (it.seasonNumber == seasonNumber && it.episodeNumber == episodeNumber))
      },
      infoMessage = "${item.title} marked as watched.",
    )

    val session = uiState.session
    val profileId = uiState.activeProfileId
    // Every connected provider hears about the watchlist removal, whether or not Trakt is one of
    // them. This used to sit inside the Trakt branch below, so a profile tracking with SIMKL or
    // MDBList alone kept the title on its watchlist after marking it watched -- the fan-out was
    // written to be provider-agnostic and was then gated on one provider being present.
    fanOutWatchlistToSyncServices(item, remove = true)
    if (session != null && profileId != null && uiState.traktStatus.connected) {
      viewModelScope.launch {
        apiClient.syncWatchlist(session, profileId, item, remove = true)
        if (item.type == "movie") {
          apiClient.fetchDetails(item.type, item.id, item.title, item.year)
            .onSuccess { detail -> apiClient.syncWatchedMovie(session, profileId, detail) }
        } else if (seasonNumber != null && episodeNumber != null) {
          apiClient.fetchDetails("tv", item.id, item.title, item.year).onSuccess { detail ->
            apiClient.fetchSeason(detail.id, seasonNumber).onSuccess { episodes ->
              episodes.firstOrNull { it.episodeNumber == episodeNumber }?.let { episode ->
                apiClient.syncWatchedEpisode(session, profileId, detail, episode, true)
              }
            }
          }
        }
        refreshTraktData()
      }
    }
  }

  fun toggleEpisodeWatched(detail: MediaDetail, episode: EpisodeItem, currentlyWatched: Boolean) {
    val ownerKey = activeOwnerKey() ?: return
    val targetWatched = !currentlyWatched
    val key = watchedEpisodeKey(detail.id, episode.seasonNumber, episode.episodeNumber)
    val existing = watchedEpisodeStore.load(ownerKey, detail.id)
    watchedEpisodeStore.save(
      ownerKey,
      detail.id,
      if (targetWatched) (existing + key).distinct() else existing.filterNot { it == key },
    )
    playbackResumeStore.remove(ownerKey, detail.id, "tv", episode.seasonNumber, episode.episodeNumber)
    val now = System.currentTimeMillis()
    val optimistic = PlaybackProgressRecord(
      entityType = "tv",
      entityId = detail.id,
      episodeKey = playbackEpisodeKey(episode.seasonNumber, episode.episodeNumber),
      seasonNumber = episode.seasonNumber,
      episodeNumber = episode.episodeNumber,
      title = detail.title,
      poster = detail.poster,
      backdrop = detail.backdrop,
      year = detail.year,
      positionSec = 0.0,
      durationSec = 0.0,
      progress = 0.0,
      completed = targetWatched,
      unwatched = !targetWatched,
      updatedAt = now,
      lastDevice = "StreamDek Mobile",
      lastPlatform = "mobile",
    )
    uiState = uiState.copy(
      playbackProgressRecords = uiState.playbackProgressRecords.filterNot {
        it.entityType.equals("tv", true) && it.entityId == detail.id &&
          it.seasonNumber == episode.seasonNumber && it.episodeNumber == episode.episodeNumber
      } + optimistic,
      localContinueWatching = loadLocalContinueWatching(),
      localResumeEntries = loadResumeEntries(),
      watchedEpisodeRevision = uiState.watchedEpisodeRevision + 1,
      infoMessage = if (targetWatched) "Episode marked as watched." else "Episode marked as unwatched.",
    )
    // Reuse the same series policy as initial detail loading. Marking the current episode watched
    // advances to the next unwatched slot; reversing it makes that exact episode the continuation.
    seriesResumeState(detail).target?.let { target ->
      loadSeason(detail.id, target.seasonNumber, target.episodeNumber)
    }

    val session = uiState.session ?: return
    val profileId = uiState.activeProfileId ?: return
    viewModelScope.launch {
      apiClient.putPlaybackProgress(
        session = session,
        profileId = profileId,
        entityType = "tv",
        entityId = detail.id,
        episodeKey = playbackEpisodeKey(episode.seasonNumber, episode.episodeNumber),
        positionSec = 0.0,
        durationSec = 0.0,
        title = detail.title,
        poster = detail.poster,
        backdrop = detail.backdrop,
        year = detail.year,
        seasonNumber = episode.seasonNumber,
        episodeNumber = episode.episodeNumber,
        completed = targetWatched,
        unwatched = !targetWatched,
      )
      if (uiState.traktStatus.connected) {
        apiClient.syncWatchedEpisode(session, profileId, detail, episode, targetWatched)
      }
      pullPlaybackProgress()
    }
  }

  fun setSeasonWatched(detail: MediaDetail, episodes: List<EpisodeItem>, watched: Boolean) {
    val ownerKey = activeOwnerKey() ?: return
    if (episodes.isEmpty()) return
    val seasonKeys = episodes.map { watchedEpisodeKey(detail.id, it.seasonNumber, it.episodeNumber) }.toSet()
    val existing = watchedEpisodeStore.load(ownerKey, detail.id)
    watchedEpisodeStore.save(
      ownerKey,
      detail.id,
      if (watched) (existing + seasonKeys).distinct() else existing.filterNot { it in seasonKeys },
    )
    episodes.forEach { episode ->
      playbackResumeStore.remove(ownerKey, detail.id, "tv", episode.seasonNumber, episode.episodeNumber)
    }
    val now = System.currentTimeMillis()
    val records = episodes.map { episode ->
      PlaybackProgressRecord(
        entityType = "tv",
        entityId = detail.id,
        episodeKey = playbackEpisodeKey(episode.seasonNumber, episode.episodeNumber),
        seasonNumber = episode.seasonNumber,
        episodeNumber = episode.episodeNumber,
        title = detail.title,
        poster = detail.poster,
        backdrop = detail.backdrop,
        year = detail.year,
        positionSec = 0.0,
        durationSec = 0.0,
        progress = 0.0,
        completed = watched,
        unwatched = !watched,
        updatedAt = now,
        lastDevice = "StreamDek Mobile",
        lastPlatform = "mobile",
      )
    }
    uiState = uiState.copy(
      playbackProgressRecords = uiState.playbackProgressRecords.filterNot { record ->
        record.entityType.equals("tv", true) && record.entityId == detail.id &&
          episodes.any { it.seasonNumber == record.seasonNumber && it.episodeNumber == record.episodeNumber }
      } + records,
      localContinueWatching = loadLocalContinueWatching(),
      localResumeEntries = loadResumeEntries(),
      watchedEpisodeRevision = uiState.watchedEpisodeRevision + 1,
      infoMessage = if (watched) "Season marked as watched." else "Season marked as unwatched.",
    )
    // A bulk watched-state action must not navigate. The series resume policy may now point at
    // the next season, but that target belongs to a later Play/Continue Watching action; while
    // managing this season the viewer should remain on the episodes they just changed.

    val session = uiState.session ?: return
    val profileId = uiState.activeProfileId ?: return
    viewModelScope.launch {
      var synced = false
      repeat(3) { attempt ->
        if (!synced) {
          synced = apiClient.putPlaybackProgressBatch(session, profileId, records).isSuccess
          if (!synced && attempt < 2) delay(500L * (attempt + 1))
        }
      }
      if (!synced) {
        uiState = uiState.copy(
          infoMessage = "Season updated on this device, but SyncDek could not sync it yet. Please retry.",
        )
      }
      pullPlaybackProgress()
    }
  }

  fun markPreviousEpisodesWatched(detail: MediaDetail, selected: EpisodeItem) {
    val ownerKey = activeOwnerKey() ?: return
    viewModelScope.launch {
      val seasonNumbers = detail.seasons.map { it.seasonNumber }
        .filter { it > 0 && it <= selected.seasonNumber }
        .distinct()
      val previous = coroutineScope {
        seasonNumbers.map { number -> async { apiClient.fetchSeason(detail.id, number).getOrDefault(emptyList()) } }
          .awaitAll()
          .flatten()
      }.filter { episode ->
        !isEpisodeUnreleased(episode) &&
          (episode.seasonNumber < selected.seasonNumber ||
            (episode.seasonNumber == selected.seasonNumber && episode.episodeNumber < selected.episodeNumber))
      }
      if (previous.isEmpty()) {
        uiState = uiState.copy(infoMessage = "There are no previous released episodes to update.")
        return@launch
      }
      val keys = previous.map { watchedEpisodeKey(detail.id, it.seasonNumber, it.episodeNumber) }
      watchedEpisodeStore.save(ownerKey, detail.id, (watchedEpisodeStore.load(ownerKey, detail.id) + keys).distinct())
      previous.forEach { playbackResumeStore.remove(ownerKey, detail.id, "tv", it.seasonNumber, it.episodeNumber) }
      val now = System.currentTimeMillis()
      val records = previous.map { episode ->
        PlaybackProgressRecord(
          entityType = "tv",
          entityId = detail.id,
          episodeKey = playbackEpisodeKey(episode.seasonNumber, episode.episodeNumber),
          seasonNumber = episode.seasonNumber,
          episodeNumber = episode.episodeNumber,
          title = detail.title,
          poster = detail.poster,
          backdrop = detail.backdrop,
          year = detail.year,
          positionSec = 0.0,
          durationSec = 0.0,
          progress = 0.0,
          completed = true,
          updatedAt = now,
          lastDevice = "StreamDek Mobile",
          lastPlatform = "mobile",
        )
      }
      uiState = uiState.copy(
        playbackProgressRecords = uiState.playbackProgressRecords.filterNot { existing ->
          existing.entityId == detail.id && records.any { it.episodeKey == existing.episodeKey }
        } + records,
        localContinueWatching = loadLocalContinueWatching(),
        localResumeEntries = loadResumeEntries(),
        watchedEpisodeRevision = uiState.watchedEpisodeRevision + 1,
        infoMessage = "Previous episodes marked as watched.",
      )
      val session = uiState.session ?: return@launch
      val profileId = uiState.activeProfileId ?: return@launch
      if (apiClient.putPlaybackProgressBatch(session, profileId, records).isFailure) {
        uiState = uiState.copy(infoMessage = "Updated on this device, but SyncDek could not sync it yet. Please retry.")
      } else {
        pullPlaybackProgress()
      }
    }
  }

  fun markEarlierEpisodesWatched(item: MediaItem) {
    val seasonNumber = item.resumeSeasonNumber
    val episodeNumber = item.resumeEpisodeNumber
    if (seasonNumber == null || episodeNumber == null || (seasonNumber == 1 && episodeNumber == 1)) {
      uiState = uiState.copy(infoMessage = "This Continue Watching item does not identify any earlier episodes.")
      return
    }
    viewModelScope.launch {
      val detail = apiClient.fetchDetails(
        type = normalizedMediaType(item.type),
        id = item.id,
        fallbackTitle = item.title,
        fallbackYear = item.year,
      ).getOrElse {
        uiState = uiState.copy(errorMessage = "Could not load the episode list. Please try again.")
        return@launch
      }
      markPreviousEpisodesWatched(
        detail,
        EpisodeItem(
          id = "${detail.id}:$seasonNumber:$episodeNumber",
          episodeNumber = episodeNumber,
          seasonNumber = seasonNumber,
          name = "Episode $episodeNumber",
          overview = "",
          still = null,
          runtime = null,
        ),
      )
    }
  }

  /**
   * Takes one title off Continue Watching without claiming it was watched.
   *
   * The account stores a distinct dismissed tombstone. It suppresses a stale provider playback
   * row on every device without being interpreted as completed or watched, and new playback
   * replaces it with an in-progress event.
   */
  fun removeFromContinueWatching(item: MediaItem) {
    val ownerKey = activeOwnerKey() ?: GUEST_OWNER_KEY
    val seasonNumber = item.resumeSeasonNumber
    val episodeNumber = item.resumeEpisodeNumber
    val episodeKey = playbackEpisodeKey(seasonNumber, episodeNumber)
    if (episodeKey != null) {
      playbackResumeStore.remove(ownerKey, item.id, item.type, seasonNumber, episodeNumber)
    } else {
      playbackResumeStore.removeTitle(ownerKey, item.id, item.type)
    }
    val now = System.currentTimeMillis()
    val removedIdentity = mediaIdentityOf(item.type, item.id)
    val dismissal = PlaybackProgressRecord(
      entityType = normalizedMediaType(item.type),
      entityId = item.id,
      tmdbId = removedIdentity.tmdbId,
      imdbId = removedIdentity.imdbId,
      episodeKey = episodeKey,
      seasonNumber = seasonNumber,
      episodeNumber = episodeNumber,
      title = item.title,
      poster = item.poster,
      backdrop = item.backdrop,
      year = item.year,
      positionSec = 0.0,
      durationSec = 0.0,
      progress = 0.0,
      completed = false,
      dismissed = true,
      updatedAt = now,
      lastDevice = "StreamDek Mobile",
      lastPlatform = "mobile",
    )
    uiState = uiState.copy(
      playbackProgressRecords = uiState.playbackProgressRecords.filterNot { record ->
        sameMediaIdentity(
          mediaIdentityOf(record.entityType, record.entityId, record.tmdbId, record.imdbId),
          removedIdentity,
        ) && (episodeKey == null || record.episodeKey.equals(episodeKey, ignoreCase = true))
      } + dismissal,
      localContinueWatching = loadLocalContinueWatching(),
      localResumeEntries = loadResumeEntries(),
      // Same identity rule as everywhere else. This filter used to compare the provider row's id
      // against the card's directly, so the card vanished only when the two sources happened to
      // agree on a spelling -- and where they did not, the row the viewer had just removed was
      // still on screen underneath it.
      traktContinueWatching = uiState.traktContinueWatching.filterNot { provider ->
        sameMediaIdentity(
          mediaIdentityOf(provider.type, provider.id, provider.tmdbId),
          removedIdentity,
        ) && removalCoversEpisode(seasonNumber, episodeNumber, provider.seasonNumber, provider.episodeNumber)
      },
      infoMessage = "${item.title} removed from Continue Watching.",
    )
    val session = uiState.session ?: return
    viewModelScope.launch {
      var synced = false
      repeat(3) { attempt ->
        if (!synced) {
          synced = apiClient.removeFromContinueWatching(
            session = session,
            profileId = uiState.activeProfileId,
            entityType = item.type,
            entityId = item.id,
            episodeKey = episodeKey,
            seasonNumber = seasonNumber,
            episodeNumber = episodeNumber,
            // Sent so the removal can be recognised later against a provider row that spells this
            // title a different way -- the reason removed films used to come back.
            tmdbId = removedIdentity.tmdbId,
            imdbId = removedIdentity.imdbId,
            title = item.title,
            poster = item.poster,
            backdrop = item.backdrop,
            year = item.year,
          ).isSuccess
          if (!synced) {
            // An account still on a SyncDek without the canonical route gets the tombstone written
            // the way this app wrote it before. The removal is weaker -- the server cannot suppress
            // the provider row on the other devices -- but far better than removal not working at
            // all until the backend is deployed.
            synced = apiClient.putPlaybackProgress(
              session = session,
              profileId = uiState.activeProfileId,
              entityType = item.type,
              entityId = item.id,
              episodeKey = episodeKey,
              positionSec = 0.0,
              durationSec = 0.0,
              title = item.title,
              poster = item.poster,
              backdrop = item.backdrop,
              year = item.year,
              seasonNumber = seasonNumber,
              episodeNumber = episodeNumber,
              dismissed = true,
            ).isSuccess
          }
          if (!synced && attempt < 2) delay(500L * (attempt + 1))
        }
      }
      if (!synced) {
        uiState = uiState.copy(errorMessage = "Removed on this device, but SyncDek could not save the change yet. Please retry when connected.")
      }
    }
  }

  fun restartFromBeginning(item: MediaItem) {
    val ownerKey = activeOwnerKey() ?: GUEST_OWNER_KEY
    playbackResumeStore.removeTitle(ownerKey, item.id, item.type)
    clearRemotePlaybackProgress(item.id, item.type)
    uiState = uiState.copy(
      localContinueWatching = loadLocalContinueWatching(),
      localResumeEntries = loadResumeEntries(),
      traktContinueWatching = uiState.traktContinueWatching.filterNot {
        (it.tmdbId?.toString() ?: it.id) == item.id && normalizedMediaType(it.type) == normalizedMediaType(item.type)
      },
      infoMessage = "${item.title} will start from the beginning.",
    )
  }
  fun setAutoUpdateChecks(enabled: Boolean) {
    appSettingsStore.saveAutoUpdateChecks(enabled)
    uiState = uiState.copy(autoUpdateChecksEnabled = enabled)
    syncCloudPreferences()
    if (enabled) checkForUpdates(manual = false)
  }

  fun checkForUpdates(manual: Boolean = true) {
    if (uiState.updateChecking) return
    launchWork(
      onStart = { uiState = uiState.copy(updateChecking = true, updateErrorMessage = null, updateStatusMessage = if (manual) "Checking for updates..." else null) },
      block = { apiClient.fetchLatestMobileUpdate() },
      onSuccess = { release ->
        val available = release.versionCode > BuildConfig.VERSION_CODE
        val mandatory = release.required || (release.minSupportedVersionCode?.let { BuildConfig.VERSION_CODE < it } == true)
        uiState = uiState.copy(updateChecking = false, availableUpdate = release.takeIf { available }, updatePromptVisible = available && (manual || uiState.autoUpdateChecksEnabled || mandatory), updateStatusMessage = if (available) "Version ${release.versionName} is available." else if (manual) "You are already on the latest version." else null, updateErrorMessage = null)
      },
      onFailure = { message -> uiState = uiState.copy(updateChecking = false, updateStatusMessage = null, updateErrorMessage = message) },
    )
  }

  fun dismissUpdatePrompt() {
    val release = uiState.availableUpdate
    val mandatory = release?.required == true || (release?.minSupportedVersionCode?.let { BuildConfig.VERSION_CODE < it } == true)
    if (!mandatory && !uiState.updateDownloading) uiState = uiState.copy(updatePromptVisible = false)
  }

  fun startUpdate() {
    val release = uiState.availableUpdate ?: return
    if (uiState.updateDownloading) return
    val context = getApplication<Application>()
    if (Build.VERSION.SDK_INT >= Build.VERSION_CODES.O && !context.packageManager.canRequestPackageInstalls()) {
      context.startActivity(Intent(Settings.ACTION_MANAGE_UNKNOWN_APP_SOURCES, Uri.parse("package:${BuildConfig.APPLICATION_ID}")).addFlags(Intent.FLAG_ACTIVITY_NEW_TASK))
      uiState = uiState.copy(updatePromptVisible = true, updateStatusMessage = "Allow installs from StreamDek, then tap Update Now again.")
      return
    }
    val safeName = release.assetName?.replace(Regex("[^a-zA-Z0-9._-]"), "-") ?: "streamdek-${release.versionCode}.apk"
    val destination = java.io.File(context.cacheDir, "updates/$safeName")
    launchWork(
      onStart = { uiState = uiState.copy(updateDownloading = true, updateProgress = 0f, updatePromptVisible = false, updateErrorMessage = null, updateStatusMessage = "Downloading version ${release.versionName}...") },
      block = { apiClient.downloadUpdate(release, destination) { downloaded, total ->
        val progress = total?.takeIf { it > 0L }?.let { (downloaded.toDouble() / it.toDouble()).toFloat().coerceIn(0f, 1f) }
        viewModelScope.launch(Dispatchers.Main) { uiState = uiState.copy(updateProgress = progress) }
      } },
      onSuccess = { apk ->
        val uri = FileProvider.getUriForFile(context, "${BuildConfig.APPLICATION_ID}.fileprovider", apk)
        val intent = Intent(Intent.ACTION_VIEW).setDataAndType(uri, "application/vnd.android.package-archive").addFlags(Intent.FLAG_ACTIVITY_NEW_TASK or Intent.FLAG_GRANT_READ_URI_PERMISSION)
        uiState = uiState.copy(updateDownloading = false, updateProgress = null, updateStatusMessage = "Download complete. Opening the installer...")
        context.startActivity(intent)
      },
      onFailure = { message -> uiState = uiState.copy(updateDownloading = false, updateProgress = null, updateErrorMessage = message, updateStatusMessage = null, updatePromptVisible = true) },
    )
  }

  fun apiBaseUrl(): String = apiClient.apiBaseUrl

  private fun cloudSyncAllowed(): Boolean {
    if (uiState.syncOnCellular) return true
    val manager = getApplication<Application>().getSystemService(android.content.Context.CONNECTIVITY_SERVICE) as? android.net.ConnectivityManager ?: return true
    val network = manager.activeNetwork ?: return false
    val capabilities = manager.getNetworkCapabilities(network) ?: return true
    return !capabilities.hasTransport(android.net.NetworkCapabilities.TRANSPORT_CELLULAR)
  }
private fun watchedOwnerKey(session: AuthSession?, activeProfileId: String?): String {
  val userId = session?.user?.uid
  return when {
    userId.isNullOrBlank() -> activeProfileId?.let { "guest:$it" } ?: GUEST_OWNER_KEY
    activeProfileId.isNullOrBlank() -> userId
    else -> "$userId:$activeProfileId"
  }
}

  private fun syncCloudPreferences(force: Boolean = false) {
    val session = uiState.session ?: return
    if (!force && !cloudSyncAllowed()) return
    val preferences = CloudPlaybackPreferences(
      appAppearance = uiState.appAppearance.name,
      themePreset = uiState.themePreset.name,
      headerStyle = uiState.headerStyle.name,
      showNavLabels = uiState.showNavLabels,
      collapsibleNavigationEnabled = uiState.collapsibleNavigationEnabled,
      navigationAutoCollapseSeconds = uiState.navigationAutoCollapseSeconds,
      syncOnCellular = uiState.syncOnCellular,
      detailPageStyle = uiState.detailPageStyle.name,
      continueWatchingStyle = uiState.continueWatchingStyle.name,
      networkCardStyle = uiState.networkCardStyle.name,
      liveLandscapeCards = uiState.liveLandscapeCards,
      liveCategoriesEnabled = uiState.liveCategoriesEnabled,
      primarySyncService = uiState.primarySyncService,
      liveFavouriteDrawerCards = uiState.liveFavouriteDrawerCards,
      showHeroSynopsis = uiState.showHeroSynopsis,
      vividAmbient = uiState.vividAmbient,
      ambientTintPercent = uiState.ambientTintPercent,
      detailAmbientTintPercent = uiState.detailAmbientTintPercent,
      defaultAppCatalogsEnabled = uiState.defaultAppCatalogsEnabled,
      homeCatalogRowsJson = serializeHomeCatalogRows(uiState.homeCatalogRows),
      seasonTabStyle = uiState.seasonTabStyle.name,
      heroTrailerAutoplay = uiState.heroTrailerAutoplay,
      heroTrailerResolution = uiState.heroTrailerResolution,
      heroTrailerDelaySeconds = uiState.heroTrailerDelaySeconds,
      trailerCacheClearHours = uiState.trailerCacheClearHours,
      detailBackgroundMode = uiState.detailBackgroundMode.name,
      homeBackgroundMode = uiState.homeBackgroundMode.name,
      secondaryAudioLanguage = uiState.secondaryAudioLanguage,
      preferredSubtitleLanguage = uiState.preferredSubtitleLanguage,
      secondarySubtitleLanguage = uiState.secondarySubtitleLanguage,
      useForcedSubtitles = uiState.useForcedSubtitles,
      showOnlyPreferredSubtitleLanguages = uiState.showOnlyPreferredSubtitleLanguages,
      addonSubtitleLoading = uiState.addonSubtitleLoading,
      subtitleDefaultSource = uiState.subtitleDefaultSource,
      ratingsEnabled = uiState.ratingsEnabled,
      externalRatingsEnabled = uiState.externalRatingsEnabled,
      enabledRatingProviders = uiState.enabledRatingProviders.sorted(),
      // Deliberately null rather than "": an API key does not belong in a settings document,
      // and a blank would overwrite a legacy value the backend has not yet migrated out of
      // one. Null means "not sent", which leaves whatever is there for the migration to move.
      mdblistApiKey = null,
      pictureInPictureEnabled = uiState.pictureInPictureEnabled,
      decoderMode = uiState.decoderMode,
      renderSurface = uiState.renderSurface,
      playerEngine = uiState.playerEngine,
      preferredAudioLanguage = uiState.preferredAudioLanguage,
      skipIntroEnabled = uiState.skipIntroEnabled,
      skipRecapEnabled = uiState.skipRecapEnabled,
      skipEndingEnabled = uiState.skipEndingEnabled,
      autoSkipIntroEnabled = uiState.autoSkipIntroEnabled,
      autoSkipRecapEnabled = uiState.autoSkipRecapEnabled,
      autoSkipEndingEnabled = uiState.autoSkipEndingEnabled,
      introdbApiKey = uiState.introdbApiKey,
      autoPlayNextEpisode = uiState.autoPlayNextEpisode,
      preferBingeGroup = uiState.preferBingeGroup,
      autoLoadSubtitles = uiState.autoLoadSubtitles,
      nextEpisodeThresholdMode = uiState.nextEpisodeThresholdMode,
      nextEpisodeThresholdPercent = uiState.nextEpisodeThresholdPercent,
      nextEpisodeThresholdMinutes = uiState.nextEpisodeThresholdMinutes,
      endOfPlaybackRecommendationsEnabled = uiState.endOfPlaybackRecommendationsEnabled,
      recommendationTiming = uiState.recommendationTiming,
      recommendationItemCount = uiState.recommendationItemCount,
      showStreamsList = uiState.showStreamsList,
      rememberLastSource = uiState.rememberLastSource,
      favoriteSourceKeys = uiState.favoriteSourceKeys.sorted(),
      blurUnwatchedEpisodes = uiState.blurUnwatchedEpisodes,
      fusionBadgesEnabled = uiState.fusionBadgesEnabled,
      streamDekFormattingEnabled = uiState.streamDekFormattingEnabled,
      showSizeBadges = uiState.showSizeBadges,
      preferredQuality = uiState.preferredQuality,
      maxFileSizeGb = uiState.maxFileSizeGb,
      badgePosition = uiState.badgePosition,
      fusionBadgeUrls = uiState.fusionBadgeUrls,
      activeFusionBadgeUrl = uiState.activeFusionBadgeUrl,
      autoUpdateChecksEnabled = uiState.autoUpdateChecksEnabled,
    )
    viewModelScope.launch { apiClient.patchCloudPreferences(session, preferences, uiState.activeProfileId) }
  }
  fun setAppAppearance(value: AppAppearance) {
    appSettingsStore.saveAppAppearance(value)
    uiState = uiState.copy(appAppearance = value)
    // Told to the platform as well as saved, so the splash on the next launch is the one this
    // choice describes rather than the one the phone happens to be in.
    applyAppNightMode(getApplication())
    syncCloudPreferences()
  }
  /**
   * Deliberately without a [syncCloudPreferences] call, unlike every other appearance setting.
   *
   * The selection belongs to this installation - see [AnimationSpeed] - so it is saved locally and
   * that is the end of it. Applying it is nothing more than the state change: the theme reads the
   * new value on the next composition and every animation in the tree is already sourcing its
   * duration from there, so the difference is visible immediately with no restart.
   */
  fun setAnimationSpeed(value: AnimationSpeed) {
    appSettingsStore.saveAnimationSpeed(value)
    uiState = uiState.copy(animationSpeed = value)
  }
