  fun addFusionBadgeUrl(url: String) {
    val normalized = url.trim()
    if (normalized.isBlank()) return
    if (uiState.fusionBadgeUrls.size >= MAX_FUSION_BADGE_URLS && normalized !in uiState.fusionBadgeUrls) {
      uiState = uiState.copy(errorMessage = "You can add up to $MAX_FUSION_BADGE_URLS badge collections.")
      return
    }
    val urls = (uiState.fusionBadgeUrls + normalized).distinct().take(MAX_FUSION_BADGE_URLS)
    val active = uiState.activeFusionBadgeUrl ?: urls.firstOrNull()
    appSettingsStore.saveFusionBadgeUrls(urls, active)
    uiState = uiState.copy(fusionBadgeUrls = urls, activeFusionBadgeUrl = active)
    syncCloudPreferences()
    refreshFusionBadgeUrl(normalized, refresh = true)
  }

  fun removeFusionBadgeUrl(url: String) {
    val urls = uiState.fusionBadgeUrls.filterNot { it == url }.ifEmpty { listOf(DEFAULT_FUSION_BADGE_URL) }
    val active = uiState.activeFusionBadgeUrl?.takeIf { it in urls } ?: urls.firstOrNull()
    appSettingsStore.saveFusionBadgeUrls(urls, active)
    uiState = uiState.copy(
      fusionBadgeUrls = urls,
      activeFusionBadgeUrl = active,
      fusionBadgeSources = uiState.fusionBadgeSources - url,
    )
    syncCloudPreferences()
    urls.forEach { if (uiState.fusionBadgeSources[it]?.source == null) refreshFusionBadgeUrl(it) }
  }

  fun setActiveFusionBadgeUrl(url: String) {
    if (url !in uiState.fusionBadgeUrls) return
    appSettingsStore.saveFusionBadgeUrls(uiState.fusionBadgeUrls, url)
    uiState = uiState.copy(activeFusionBadgeUrl = url)
    syncCloudPreferences()
  }

  fun refreshFusionBadgeUrl(url: String, refresh: Boolean = true) {
    val normalized = url.trim()
    if (normalized.isBlank()) return
    launchWork(
      onStart = {
        uiState = uiState.copy(
          fusionBadgeSources = uiState.fusionBadgeSources + (normalized to FusionBadgeSourceState(normalized, uiState.fusionBadgeSources[normalized]?.source, loading = true)),
        )
      },
      block = { apiClient.fetchFusionBadgeSource(normalized).map { normalizeFusionBadgeSource(it, normalized) } },
      onSuccess = { source ->
        val active = uiState.activeFusionBadgeUrl ?: normalized
        if (uiState.activeFusionBadgeUrl == null) appSettingsStore.saveFusionBadgeUrls(uiState.fusionBadgeUrls, active)
        uiState = uiState.copy(
          activeFusionBadgeUrl = active,
          fusionBadgeSources = uiState.fusionBadgeSources + (normalized to FusionBadgeSourceState(normalized, source, loading = false)),
        )
      },
      onFailure = { message ->
        uiState = uiState.copy(
          fusionBadgeSources = uiState.fusionBadgeSources + (normalized to FusionBadgeSourceState(normalized, uiState.fusionBadgeSources[normalized]?.source, loading = false, error = message)),
          errorMessage = message,
        )
      },
    )
  }

  private fun refreshFusionBadgeSources() {
    uiState.fusionBadgeUrls.forEach { url ->
      if (uiState.fusionBadgeSources[url]?.source == null) refreshFusionBadgeUrl(url, refresh = false)
    }
  }


  private fun syncPeerEngine() {
    val app = getApplication<Application>()
    val config = uiState.peerStreamSettings.toServiceConfig()
    val shouldRun = config.enabled && config.streamingMode == "server" &&
      (config.runAsForegroundService || (uiState.playerSession != null && PeerStreamService.isOnline))
    if (shouldRun) {
      val intent = PeerStreamService.createIntent(app, config)
      val notificationsAllowed = if (Build.VERSION.SDK_INT >= Build.VERSION_CODES.TIRAMISU) {
        ContextCompat.checkSelfPermission(app, android.Manifest.permission.POST_NOTIFICATIONS) == android.content.pm.PackageManager.PERMISSION_GRANTED
      } else {
        true
      }
      if (config.runAsForegroundService && notificationsAllowed && Build.VERSION.SDK_INT >= Build.VERSION_CODES.O) {
        ContextCompat.startForegroundService(app, intent)
      } else {
        app.startService(intent)
      }
      scheduleTorrentStatusRefresh()
    } else {
      runCatching { app.stopService(PeerStreamService.createIntent(app, config)) }
      PeerStreamService.markStopped()
    }
    refreshPeerStreamStatus()
  }

  private fun stopOnDemandPeerEngine() {
    val config = uiState.peerStreamSettings.toServiceConfig()
    if (config.runAsForegroundService) return
    torrentStatusRefreshJob?.cancel()
    val app = getApplication<Application>()
    runCatching { app.stopService(PeerStreamService.createIntent(app, config)) }
    PeerStreamService.markStopped()
    refreshPeerStreamStatus()
  }

  private fun scheduleTorrentStatusRefresh() {
    torrentStatusRefreshJob?.cancel()
    torrentStatusRefreshJob = viewModelScope.launch {
      repeat(6) { attempt ->
        delay(if (attempt == 0) 250L else 500L)
        refreshPeerStreamStatus()
      }
    }
  }

  private suspend fun ensurePeerEngineReady(config: PeerStreamConfig): Result<PeerStreamConfig> {
    val app = getApplication<Application>()
    val intent = PeerStreamService.createIntent(app, config)
    runCatching {
      val notificationsAllowed = if (Build.VERSION.SDK_INT >= Build.VERSION_CODES.TIRAMISU) {
        ContextCompat.checkSelfPermission(app, android.Manifest.permission.POST_NOTIFICATIONS) == android.content.pm.PackageManager.PERMISSION_GRANTED
      } else {
        true
      }
      if (config.runAsForegroundService && notificationsAllowed && Build.VERSION.SDK_INT >= Build.VERSION_CODES.O) {
        ContextCompat.startForegroundService(app, intent)
      } else {
        app.startService(intent)
      }
    }.onFailure {
      refreshPeerStreamStatus()
      return Result.failure(it)
    }
    // Starting a libtorrent session, measuring the cache and binding a socket is now done off the
    // service's main thread, which means it takes as long as it takes: the old three-second window
    // was shorter than a cold start and reported a working engine as one that never came up.
    repeat(TORRENT_SERVER_READY_ATTEMPTS) {
      delay(TORRENT_SERVER_READY_POLL_MS)
      if (PeerStreamService.isOnline) {
        refreshPeerStreamStatus()
        return Result.success(config.copy(port = PeerStreamService.activePort))
      }
    }
    refreshPeerStreamStatus()
    return Result.failure(IllegalStateException(PeerStreamService.lastStartupError?.ifBlank { null } ?: "Local peer server did not come online in time."))
  }

  /**
   * Throws away the temporary data peer-to-peer playback has accumulated.
   *
   * Off the main thread: this walks and deletes directories that may hold gigabytes. Anything the
   * engine is currently playing from survives, so pressing this during playback tidies up around
   * it rather than ending it.
   */
  fun clearPeerStorage() {
    if (uiState.peerStorageClearing) return
    // Read here, on the main thread, rather than inside the worker: what is playing is a fact about
    // the state as the button was pressed.
    val activeSessionId = activePeerPlaybackSessionId()
    launchWork(
      onStart = { uiState = uiState.copy(peerStorageClearing = true) },
      block = { runCatching { PeerStreamService.clearStoredData(activeSessionId) } },
      onSuccess = { result ->
        uiState = uiState.copy(peerStorageClearing = false)
        refreshPeerStreamStatus()
        // infoMessage, not playbackNotice. That channel means one thing — a premium service turned
        // a source down — and the banner hardcodes "Premium service declined this source" as its
        // heading and a warning colour to match. Answering a settings button through it put that
        // heading over a plain confirmation, so clearing storage successfully reported itself as a
        // refusal. This is the same neutral channel [clearTrailerCacheNow] answers its own row on.
        //
        // Four outcomes, not two. The old message worked from the freed total alone, so a clear
        // that removed nothing *because there was nothing* and one that removed nothing *because
        // it could not* said the same untrue thing.
        val freedLabel = formatBytesLabel(result.freedBytes).removeSuffix(" used")
        val remainingLabel = formatBytesLabel(result.remainingBytes).removeSuffix(" used")
        uiState = when {
          result.freedBytes <= 0L && result.isEmpty ->
            uiState.copy(infoMessage = "There was no peer-to-peer storage to clear.")
          result.isEmpty ->
            uiState.copy(infoMessage = "Cleared $freedLabel of peer-to-peer storage.")
          result.freedBytes > 0L ->
            uiState.copy(infoMessage = "Cleared $freedLabel. $remainingLabel is still in use by what is playing.")
          // Nothing went, and something is still there. Said as a failure, because it is one.
          else ->
            uiState.copy(errorMessage = "Could not clear $remainingLabel of peer-to-peer storage. Stop playback and try again.")
        }
      },
      onFailure = { message ->
        uiState = uiState.copy(peerStorageClearing = false, errorMessage = message)
      },
    )
  }

  /**
   * The peer playback the viewer is watching right now, if any, as the engine's own session id.
   *
   * Read out of the local URL the player was handed — `http://127.0.0.1:PORT/torrent/<sessionId>`
   * — rather than tracked as another piece of state that could fall out of step with it. Null for
   * a web stream, a download or no player at all, and null is the answer whenever the settings
   * screen asks, because the player owns the whole scene while it is up.
   */
  private fun activePeerPlaybackSessionId(): String? =
    uiState.playerSession?.url
      ?.substringBefore('?')
      ?.substringAfterLast("/torrent/", "")
      ?.takeIf { it.isNotBlank() }

  /**
   * Measures both stores now and adopts the figure, so the settings screen opens on what is
   * actually on disk.
   *
   * Nothing else re-read it while that screen was up: the status was last written when the engine
   * started or stopped, so on a launch where nothing had been played the screen showed "None" over
   * gigabytes — and the Clear button, which was enabled only above zero, could not be pressed at
   * all. That is the "sometimes I tap it and nothing happens".
   */
  fun refreshPeerStorageUsage() {
    viewModelScope.launch {
      runCatching { PeerStreamService.primeStoragePaths(getApplication<Application>()) }
      // The walk is the slow part on a full cache, so it happens here rather than on the main
      // thread; refreshPeerStreamStatus then reads the figure it just warmed.
      withContext(Dispatchers.IO) { runCatching { PeerStreamService.measureStoredBytes() } }
      refreshPeerStreamStatus()
    }
  }

  private fun refreshPeerStreamStatus() {
    // Cheap, idempotent, and the difference between the settings screen reporting the storage that
    // is actually there and reporting none of it when nothing has been played yet this launch.
    runCatching { PeerStreamService.primeStoragePaths(getApplication<Application>()) }
    uiState = uiState.copy(
      peerStreamStatus = peerStreamStatusFromSnapshot(
        PeerStreamService.snapshot(uiState.peerStreamSettings.toServiceConfig()),
        uiState.peerStreamSettings,
      ),
    )
  }

  /**
   * MDBList ratings for the open title.
   *
   * No key is read here any more. Whether one exists, where it is kept and which one wins
   * are all answered further down — by the request interceptor for a device key, and by the
   * backend for an account key. This only has to know whether the viewer has one at all,
   * so it can offer to set one up instead of quietly showing nothing.
   */
  private fun refreshExternalRatings(detail: MediaDetail) {
    if (!uiState.externalRatingsEnabled || uiState.enabledRatingProviders.isEmpty()) return
    // Only skipped once the credential state is actually known. Before the first read has
    // landed, the request is made anyway: the backend resolves the key and answers with an
    // empty list if there is none, which costs one call and beats suppressing ratings on a
    // device that has a perfectly good account key we simply have not read yet.
    if (uiState.contentServices.loaded && !uiState.contentServices.mdblist.configured) {
      offerContentServiceHint(ContentService.Mdblist)
      return
    }
    launchWork(
      onStart = {},
      block = { apiClient.fetchMdblistRatings(uiState.session, detail.type, detail.id, detail.imdbId, uiState.enabledRatingProviders.toList()) },
      onSuccess = { ratings ->
        if (ratings.isEmpty()) return@launchWork
        val current = uiState.detail ?: return@launchWork
        if (current.id == detail.id && current.type == detail.type) {
          uiState = uiState.copy(detail = current.copy(externalRatings = ratings))
        }
      },
      onFailure = {},
    )
  }

  private fun refreshTraktComments(detail: MediaDetail) {
    launchWork(
      onStart = {},
      block = { apiClient.fetchTraktComments(uiState.session, detail.type, detail.id, detail.imdbId) },
      onSuccess = { comments ->
        if (comments.isEmpty()) return@launchWork
        val current = uiState.detail ?: return@launchWork
        if (current.id == detail.id && current.type == detail.type) {
          uiState = uiState.copy(detail = current.copy(traktComments = comments))
        }
      },
      onFailure = {},
    )
  }

  private fun restore() {
    launchWork(
      onStart = { uiState = uiState.copy(errorMessage = null) },
      block = { Result.success(sessionStore.load()) },
      onSuccess = { session ->
        if (session == null) {
          val profiles = guestProfileStore.load()
          val selected = profiles.firstOrNull { it.id == profileSelectionStore.load(GUEST_OWNER_KEY) } ?: profiles.firstOrNull { it.isDefault } ?: profiles.firstOrNull()
          uiState = appSettingsStore.applyTo(uiState.copy(booting = false, session = null, profilesLoading = false, profiles = profiles, activeProfileId = selected?.id, showProfilePicker = profiles.size > 1, mergedWatchlist = watchlistStore.load(selected?.id?.let { "guest:$it" } ?: GUEST_OWNER_KEY), favouriteChannels = favouriteChannelStore.load(selected?.id?.let { "guest:$it" } ?: GUEST_OWNER_KEY)))
        } else {
          routeAfterProfileRefresh = true
          uiState = appSettingsStore.applyTo(uiState.copy(booting = false, session = session, profilesLoading = true, showProfilePicker = true, mergedWatchlist = watchlistStore.load(activeOwnerKey() ?: GUEST_OWNER_KEY), favouriteChannels = favouriteChannelStore.load(activeOwnerKey() ?: GUEST_OWNER_KEY)))
        }
        bootstrapAfterAuth()
      },
      onFailure = {
        val profiles = guestProfileStore.load()
        val selected = profiles.firstOrNull { it.id == profileSelectionStore.load(GUEST_OWNER_KEY) } ?: profiles.firstOrNull { it.isDefault } ?: profiles.firstOrNull()
        uiState = appSettingsStore.applyTo(uiState.copy(booting = false, session = null, profilesLoading = false, profiles = profiles, activeProfileId = selected?.id, showProfilePicker = profiles.size > 1, errorMessage = null, mergedWatchlist = watchlistStore.load(selected?.id?.let { "guest:$it" } ?: GUEST_OWNER_KEY), favouriteChannels = favouriteChannelStore.load(selected?.id?.let { "guest:$it" } ?: GUEST_OWNER_KEY)))
        bootstrapAfterAuth()
      },
    )
  }

  private fun submitAuth(guestDataOwnerKey: String? = null, block: suspend () -> Result<AuthSession>) {
    launchWork(
      onStart = { uiState = uiState.copy(booting = true, errorMessage = null, infoMessage = null) },
      block = block,
      onSuccess = { session ->
        sessionStore.save(session)
        routeAfterProfileRefresh = true
        uiState = appSettingsStore.applyTo(uiState.copy(booting = false, session = session, profilesLoading = true, showProfilePicker = true, pendingGuestMerge = guestDataOwnerKey))
        bootstrapAfterAuth(forceHome = true)
      },
      onFailure = { message -> uiState = uiState.copy(booting = false, errorMessage = message) },
    )
  }

  fun dismissGuestMergePrompt() {
    uiState = uiState.copy(pendingGuestMerge = null)
  }

  /** Moves a just-left-behind guest identity's watchlist, favourites, continue-watching
   * progress, and locally-added add-ons into the profile the user just registered/landed
   * on. General app settings need no migration - most of them already live in a single
   * shared preferences file rather than being keyed per owner. */
  fun mergeGuestDataIntoAccount() {
    val sourceKey = uiState.pendingGuestMerge ?: return
    uiState = uiState.copy(pendingGuestMerge = null)
    val targetKey = activeOwnerKey() ?: return
    if (targetKey == sourceKey) return
    val mergedWatchlist = (watchlistStore.load(targetKey) + watchlistStore.load(sourceKey)).distinctBy { "${it.type}:${it.id}" }
    watchlistStore.save(targetKey, mergedWatchlist)
    // Channel id alone, matching how favourites are identified everywhere else — the same channel
    // is stored as "tv" or "live" depending on which catalog it came through.
    val mergedFavourites = (favouriteChannelStore.load(targetKey) + favouriteChannelStore.load(sourceKey)).distinctBy { it.id }
    favouriteChannelStore.save(targetKey, mergedFavourites)
    playbackResumeStore.loadAll(sourceKey).forEach { entry -> playbackResumeStore.save(targetKey, entry) }
    LocalAddonManager.copyProfileStorageTo(sourceKey, targetKey)
    refreshProfileScopedData()
    uiState = uiState.copy(infoMessage = "Your favourites, watchlist, and add-ons were moved into your new account.")
  }

  private fun bootstrapAfterAuth(forceHome: Boolean = false) {
    // First, ahead of everything below it, because it is the only one of these the viewer is
    // actually waiting on: the profile picker is the screen on top, and it stays dark until the
    // profiles land. It used to be issued last, behind eight other calls to the same host, and
    // measured 1.9s from process start on a warm network — nearly all of it spent queued rather
    // than in flight. The rest of this fan-out fills in screens that are not on top yet.
    if (uiState.session != null) refreshProfiles()
    syncPeerEngine()
    uiState.session?.let { session ->
      viewModelScope.launch {
        apiClient.fetchCloudPlaybackPreferences(session, uiState.activeProfileId).onSuccess { preferences ->
          val before = homeLayoutSignature()
          applyCloudPlaybackPreferences(preferences)
          // Only when the account actually asks for different rows. Reloading unconditionally
          // spent a second full home request on every launch to arrive at what was already there.
          if (homeLayoutSignature() != before) loadHome(force = true, silent = true)
        }
      }
    }
    refreshFusionBadgeSources()
    refreshAddonEntitlements()
    loadHome(force = forceHome)
    refreshAddons()
    refreshProfilePlugins()
    loadM3uPlaylists()
    syncPlaylistsWithAccount()
    refreshTraktData()
    refreshSyncServices()
    refreshContentServices()
    uiState = uiState.copy(mergedWatchlist = loadLocalWatchlist(), favouriteChannels = loadLocalFavouriteChannels(), localContinueWatching = loadLocalContinueWatching(), localResumeEntries = loadResumeEntries())
    if (uiState.session != null) loadDebridAccounts()
    if (uiState.autoUpdateChecksEnabled && uiState.availableUpdate == null) checkForUpdates(manual = false)
  }

  private fun refreshProfileScopedData() {
    val ownerKey = activeOwnerKey() ?: GUEST_OWNER_KEY
    // Sorted catalogues belong to the profile that owns the playlists and favourites behind them.
    BrowseCategoryCache.clear()
    appSettingsStore.selectProfileStorage(ownerKey)
    LocalAddonManager.selectProfileStorage(ownerKey)
    M3uPlaylistManager.selectProfileStorage(ownerKey)
    loadM3uPlaylists()
    syncPlaylistsWithAccount()
    val activeProfile = uiState.profiles.firstOrNull { it.id == uiState.activeProfileId }
    // Tracking connections belong to the profile: clear the previous profile's statuses so a
    // stale "Connected" never shows against the profile that was just switched to.
    uiState = uiState.copy(simklStatus = SyncServiceStatus(), mdblistStatus = SyncServiceStatus(), punchplayStatus = SyncServiceStatus(), pendingSyncService = null, pendingSyncServiceCode = null)
    refreshTraktData()
    refreshSyncServices()
    refreshProfilePlugins()
    refreshProfileCloudStreamPlugins()
    refreshLiveFavouriteChannels()
    uiState = appSettingsStore.applyTo(uiState.copy(
      mergedWatchlist = loadLocalWatchlist(),
      favouriteChannels = loadLocalFavouriteChannels(),
      localContinueWatching = loadLocalContinueWatching(),
      localResumeEntries = loadResumeEntries(),
      preferredAudioLanguage = normalizePreferredAudioLanguage(activeProfile?.audioLanguage?.takeIf { it.isNotBlank() } ?: "en"),
    ))
    refreshAddons()
    val session = uiState.session
    val profileId = uiState.activeProfileId
    if (session != null && profileId != null) {
      viewModelScope.launch {
        apiClient.fetchCloudPlaybackPreferences(session, profileId).onSuccess { preferences ->
          if (uiState.activeProfileId == profileId) {
            val before = homeLayoutSignature()
            applyCloudPlaybackPreferences(preferences)
            syncCloudPreferences(force = true)
            // Switching profile already reloads home; this only has to catch the case where the
            // profile's synced preferences turn out to want a different set of rows.
            if (homeLayoutSignature() != before) loadHome(force = true, silent = true)
          }
        }
      }
    }
  }

  /**
   * Pulls the profile's plugin document and takes it on unless the device holds newer edits.
   *
   * Add-on state is read back from the server by every refreshAddons(), of which there is one on
   * practically every screen change, so a change made in the portal turns up almost at once.
   * Plugins are client state synced through a single document, and this used to run only on a
   * profile switch -- which meant a portal edit did not appear until the app was killed and
   * reopened. It is now called on the same beats: sign-in, foreground, and opening the screen.
   */
  /** Brings the platform's content policy up to date. Safe to call at any time. */
  fun refreshContentPolicy() {
    viewModelScope.launch { apiClient.refreshContentPolicy() }
  }

  /**
   * Watches the account for a plugin change made somewhere else.
   *
   * Polls a stamp, not the document: the document carries every source and every settings schema
   * and is far too large to ask for on a timer, while the stamp is one number. Only when it moves
   * past what this device last wrote or read is the document actually fetched — so the steady
   * state is a few bytes every fifteen seconds, and a collection added on the web portal lands
   * here within that without anyone pressing refresh.
   *
   * Runs only while the app is in front. A background poll would cost battery to answer a question
   * nobody is looking at, and the foreground pull already covers coming back.
   */
  fun startWatchingProfilePlugins() {
    val session = uiState.session ?: return
    val profileId = uiState.activeProfileId ?: return
    pluginWatchJob?.cancel()
    pluginWatchJob = viewModelScope.launch {
      while (isActive) {
        delay(PLUGIN_WATCH_INTERVAL_MS)
        if (uiState.session?.user?.uid != session.user.uid || uiState.activeProfileId != profileId) return@launch
        val remote = apiClient.fetchProfilePluginsVersion(session, profileId).getOrNull() ?: continue
        if (remote > lastKnownPluginVersion) {
          lastKnownPluginVersion = remote
          refreshProfilePlugins()
        }
      }
    }
  }

  fun stopWatchingProfilePlugins() {
    pluginWatchJob?.cancel()
    pluginWatchJob = null
  }

  fun refreshProfilePlugins(manual: Boolean = false) {
    val ownerKey = activeOwnerKey() ?: GUEST_OWNER_KEY
    StreamDekPlugins.manager.selectProfileStorage(ownerKey)
    val session = uiState.session
    val profileId = uiState.activeProfileId
    if (session == null || profileId == null) {
      // Pressing refresh while signed out should say why rather than appear to do nothing.
      if (manual) uiState = uiState.copy(pluginsLoading = false, infoMessage = "Sign in to sync plugin collections.")
      return
    }
    pluginRefreshJob?.cancel()
    uiState = uiState.copy(pluginsLoading = true)
    pluginRefreshJob = viewModelScope.launch {
      apiClient.fetchProfilePlugins(session, profileId).onFailure {
        if (manual) uiState = uiState.copy(errorMessage = "Could not reach your account to refresh plugin collections.")
      }.onSuccess { cloudJson ->
        if (uiState.activeProfileId != profileId || activeOwnerKey() != ownerKey) return@onSuccess
        lastKnownPluginVersion = runCatching {
          JSONObject(cloudJson).let { root ->
            maxOf(root.optLong("updatedAt", 0L), root.optJSONObject("cloudstream")?.optLong("updatedAt", 0L) ?: 0L)
          }
        }.getOrDefault(lastKnownPluginVersion)
        val cloudHasState = runCatching {
          JSONObject(cloudJson).let { root -> root.has("enabled") || root.has("repos") || root.has("providers") }
        }.getOrDefault(false)
        val localSnapshot = StreamDekPlugins.manager.snapshotJson(includeCode = false)
        val localIsNewer = StreamDekPlugins.manager.state.updatedAt > StreamDekPlugins.manager.snapshotUpdatedAt(cloudJson)
        // Both sides stamp updatedAt from their own clock, so a phone running even slightly
        // ahead of the machine the portal was used on would keep deciding it was the newer of
        // the two and push over the change instead of taking it. That is fine to arbitrate on a
        // background sync, but not when someone has pressed refresh and is watching: there the
        // account wins outright. Nothing local is lost by it -- edits made here are pushed as
        // they happen, so the copy being taken back already contains them.
        // The CloudStream half is arbitrated on its own stamp. It is written by a different
        // engine on a different schedule, so tying it to the JS half's clock would let an edit to
        // one hold back an edit to the other.
        applyCloudStreamDocument(cloudJson, manual)
        if (cloudHasState && (manual || !localIsNewer)) {
          StreamDekPlugins.manager.restoreCloudState(cloudJson)
          StreamDekPlugins.manager.state.repos
            .filter { repo -> StreamDekPlugins.manager.state.providers.none { provider -> provider.repoUrl == repo.url } || StreamDekPlugins.manager.state.providers.any { provider -> provider.repoUrl == repo.url && provider.code.isBlank() } }
            .forEach { repo -> StreamDekPlugins.manager.refresh(repo.url) }
        } else if (StreamDekPlugins.manager.state.repos.isNotEmpty() || StreamDekPlugins.manager.state.updatedAt > 0L) {
          apiClient.putProfilePlugins(session, profileId, localSnapshot)
        }
        if (manual) uiState = uiState.copy(infoMessage = "Plugin collections up to date.")
      }
      uiState = uiState.copy(pluginsLoading = false)
    }
  }

  /**
   * Takes the `cloudstream` section of a profile document, and brings up anything it switched on.
   *
   * Reloading is what makes a source added from the web portal actually answer here: the record
   * arriving is only a pointer, and the `.cs3` behind it is downloaded the first time it is asked
   * for. Done off the main thread because that download is the expensive part.
   */
  private fun applyCloudStreamDocument(cloudJson: String, manual: Boolean) {
    if (!CloudStreamPlugins.isInitialized) return
    val section = runCatching { JSONObject(cloudJson).optJSONObject("cloudstream") }.getOrNull() ?: return
    val incomingAt = section.optLong("updatedAt", 0L)
    val localAt = CloudStreamPlugins.manager.state.updatedAt
    // Same arbitration the JS half uses: the account wins outright on a deliberate refresh, and
    // only when it is genuinely newer on a background one.
    if (!manual && incomingAt <= localAt) return
    if (!CloudStreamPlugins.manager.restoreCloudState(section.toString())) return
    cloudStreamLoadJob?.cancel()
    cloudStreamLoadJob = viewModelScope.launch(Dispatchers.IO) {
      runCatching { CloudStreamPlugins.manager.loadEnabledProviders() }
        .onFailure { Log.w("StreamDekCloudStream", "Could not bring up synced CloudStream sources", it) }
    }
  }

  /**
   * Points the CloudStream collections at the active profile and brings its enabled sources up.
   * Unlike the JS plugin collections there is no cloud copy to reconcile against — a `.cs3` is a
   * binary the device downloads itself — so this is purely local.
   */
  private fun refreshProfileCloudStreamPlugins() {
    val ownerKey = activeOwnerKey() ?: GUEST_OWNER_KEY
    // SkyStream collections are profile-scoped for the same reason: one household member's
    // sources should not answer stream requests under another's profile. Nothing to load ahead
    // of time — a .sky is read from disk when it is asked for a stream, not held in the process.
    if (SkyStreamPlugins.isInitialized) SkyStreamPlugins.manager.selectProfileStorage(ownerKey)
    if (!CloudStreamPlugins.isInitialized) return
    CloudStreamPlugins.manager.selectProfileStorage(ownerKey)
    cloudStreamLoadJob?.cancel()
    cloudStreamLoadJob = viewModelScope.launch(Dispatchers.IO) {
      runCatching { CloudStreamPlugins.manager.loadEnabledProviders() }
        .onFailure { Log.w("StreamDekCloudStream", "Could not restore enabled CloudStream sources", it) }
    }
  }

  /**
   * The whole plugin document: StreamDek's own collections, and the CloudStream ones beside them.
   *
   * Composed from both managers every time rather than remembered, so a push triggered by one of
   * them always carries the other's current state. `cloudstream` is only written once there is
   * something to write -- a profile that has never had one should not start carrying an empty
   * section around.
   */
  private fun profilePluginDocument(): String {
    val root = runCatching { JSONObject(StreamDekPlugins.manager.snapshotJson(includeCode = false)) }
      .getOrDefault(JSONObject())
    if (CloudStreamPlugins.isInitialized) {
      val cloudStream = CloudStreamPlugins.manager.state
      if (cloudStream.repos.isNotEmpty() || cloudStream.providers.isNotEmpty()) {
        runCatching { root.put("cloudstream", JSONObject(CloudStreamPlugins.manager.snapshotJson())) }
      }
    }
    return root.toString()
  }

  private fun syncActiveProfilePlugins() {
    val session = uiState.session ?: return
    val profileId = uiState.activeProfileId ?: return
    pluginSyncJob?.cancel()
    pluginSyncJob = viewModelScope.launch {
      delay(350)
      // Read after the debounce, not before: several edits in quick succession should send the
      // state they settled on rather than the first of them.
      val document = profilePluginDocument()
      repeat(3) { attempt ->
        if (apiClient.putProfilePlugins(session, profileId, document).isSuccess) {
          lastKnownPluginVersion = runCatching { JSONObject(document).optLong("updatedAt", 0L) }.getOrDefault(0L)
          return@launch
        }
        delay(500L * (attempt + 1))
      }
    }
  }

  private fun determineActiveProfile(session: AuthSession, profiles: List<StreamProfile>): StreamProfile? {
    val stored = profileSelectionStore.load(session.user.uid)
    return profiles.firstOrNull { it.id == stored } ?: profiles.firstOrNull { it.isDefault } ?: profiles.firstOrNull()
  }

  private fun seriesResumeState(detail: MediaDetail, extraWatched: Set<String> = emptySet()): SeriesResumeState {
    val ownerKey = activeOwnerKey() ?: GUEST_OWNER_KEY
    val watched = watchedEpisodeStore.load(ownerKey, detail.id).toSet() + extraWatched
    val remoteEvents = uiState.playbackProgressRecords.filter {
      it.entityType.equals("tv", true) && it.entityId == detail.id && it.seasonNumber != null && it.episodeNumber != null
    }.map {
      SeriesProgressEvent(
        seasonNumber = it.seasonNumber!!,
        episodeNumber = it.episodeNumber!!,
        positionSec = it.positionSec,
        status = when { it.unwatched -> "unwatched"; it.completed -> "completed"; else -> "in-progress" },
        updatedAtMillis = it.updatedAt,
      )
    }
    val localEvents = uiState.localResumeEntries.filter {
      it.mediaId == detail.id && normalizedMediaType(it.mediaType) == "tv" && it.seasonNumber != null && it.episodeNumber != null
    }.map {
      SeriesProgressEvent(it.seasonNumber!!, it.episodeNumber!!, it.positionSeconds ?: 0.0, "in-progress", it.updatedAt ?: 0L)
    }
    val providerEvents = uiState.traktContinueWatching.filter {
      (it.tmdbId?.toString() ?: it.id) == detail.id && it.seasonNumber != null && it.episodeNumber != null &&
        uiState.playbackProgressRecords.none { record -> progressRecordSuppressesProviderItem(record, it.toMediaItem()) }
    }.map {
      SeriesProgressEvent(
        it.seasonNumber!!,
        it.episodeNumber!!,
        it.positionSec ?: (it.durationSec?.times((it.progress ?: 0.0) / 100.0) ?: 0.0),
        "in-progress",
        it.updatedAt ?: 0L,
      )
    }
    return getSeriesResumeState(detail.id, seriesEpisodeSlots(detail.seasons), remoteEvents + localEvents + providerEvents, watched)
  }

  private fun loadResumeAwareSeries(
    detail: MediaDetail,
    preferredSeasonNumber: Int? = null,
    preferredEpisodeNumber: Int? = null,
    resumeKnownSource: Boolean = false,
  ) {
    uiState = uiState.copy(seasonLoading = true)
    // A direct Continue Watching request already names the exact episode. Loading watched-history
    // and migration state first only delays playback and lets an unrelated sync failure strand the
    // launch. Fetch the requested season immediately; the normal detail refresh can reconcile
    // watched state independently.
    if (resumeKnownSource && preferredSeasonNumber != null && preferredEpisodeNumber != null) {
      loadSeason(detail.id, preferredSeasonNumber, preferredEpisodeNumber, resumeKnownSource = true)
      return
    }
    viewModelScope.launch {
      val session = uiState.session
      val profileId = uiState.activeProfileId
      val traktWatched = if (session != null && profileId != null && uiState.traktStatus.connected) {
        apiClient.fetchTraktWatchedEpisodeKeys(session, profileId, detail.id).getOrDefault(emptySet())
      } else emptySet()
      if (traktWatched.isNotEmpty()) {
        val ownerKey = activeOwnerKey() ?: GUEST_OWNER_KEY
        watchedEpisodeStore.save(ownerKey, detail.id, (watchedEpisodeStore.load(ownerKey, detail.id) + traktWatched).distinct())
        uiState = uiState.copy(watchedEpisodeRevision = uiState.watchedEpisodeRevision + 1)
      }
      // Older builds treated the season button as a local-only shortcut. Migrate those genuine
      // local episode ticks into SyncDek, but only when the account has no event for that exact
      // episode. An explicit remote unwatched event therefore remains authoritative.
      if (session != null && profileId != null) {
        val remoteForSeries = apiClient.fetchPlaybackProgress(
          session = session,
          profileId = profileId,
          limit = 100,
          entityId = detail.id,
        ).getOrNull()
        if (remoteForSeries != null) {
          val knownEpisodes = remoteForSeries.filter { it.entityType.equals("tv", true) }.mapNotNull { record ->
            val season = record.seasonNumber ?: return@mapNotNull null
            val episode = record.episodeNumber ?: return@mapNotNull null
            season to episode
          }.toSet()
          val prefix = "episode:${detail.id}:"
          val localWatched = watchedEpisodeStore.load(activeOwnerKey() ?: GUEST_OWNER_KEY, detail.id)
            .mapNotNull { key ->
              if (!key.startsWith(prefix)) return@mapNotNull null
              val parts = key.removePrefix(prefix).split(':')
              val season = parts.getOrNull(0)?.toIntOrNull() ?: return@mapNotNull null
              val episode = parts.getOrNull(1)?.toIntOrNull() ?: return@mapNotNull null
              season to episode
            }
          val missingRemoteEpisodes = localWatched.filterNot { it in knownEpisodes }
          if (missingRemoteEpisodes.isNotEmpty()) {
            val migrationTime = System.currentTimeMillis()
            val migrationRecords = missingRemoteEpisodes.map { (season, episode) ->
              PlaybackProgressRecord(
                entityType = "tv",
                entityId = detail.id,
                episodeKey = playbackEpisodeKey(season, episode),
                seasonNumber = season,
                episodeNumber = episode,
                title = detail.title,
                poster = detail.poster,
                backdrop = detail.backdrop,
                year = detail.year,
                positionSec = 0.0,
                durationSec = 0.0,
                progress = 0.0,
                completed = true,
                updatedAt = migrationTime,
                lastDevice = "StreamDek Mobile",
                lastPlatform = "mobile",
              )
            }
            apiClient.putPlaybackProgressBatch(session, profileId, migrationRecords)
          }
        }
      }
      if (uiState.detail?.id != detail.id) return@launch
      val state = seriesResumeState(detail, traktWatched)
      val target = if (preferredSeasonNumber != null && preferredEpisodeNumber != null) {
        SeriesEpisodeSlot(preferredSeasonNumber, preferredEpisodeNumber)
      } else state.target ?: SeriesEpisodeSlot(detail.seasons.first().seasonNumber, 1)
      loadSeason(detail.id, target.seasonNumber, target.episodeNumber, resumeKnownSource)
    }
  }

  private fun activeOwnerKey(): String? {
    val userId = uiState.session?.user?.uid
    if (userId == null) return uiState.activeProfileId?.let { "guest:$it" } ?: GUEST_OWNER_KEY
    val profileId = uiState.activeProfileId ?: return userId
    return "$userId:$profileId"
  }

  private fun loadLocalWatchlist(): List<MediaItem> = watchlistStore.load(activeOwnerKey() ?: GUEST_OWNER_KEY)

  private fun loadLocalFavouriteChannels(): List<MediaItem> = favouriteChannelStore.load(activeOwnerKey() ?: GUEST_OWNER_KEY)

  /**
   * Tells the account where this title was left.
   *
   * Fire and forget, deliberately: the local save has already happened by the time this runs, so a
   * failed call costs the other devices a stale position and costs this one nothing. Live channels
   * are skipped -- there is no position to return to -- and so is anything with no duration, which
   * the server would otherwise have to guess a completion percentage from.
   */
  private fun pushPlaybackProgress(player: PlayerSession, progressPercent: Double) {
    if (player.isLive) return
    val session = uiState.session ?: return
    val duration = lastPlaybackDurationSec
    if (duration <= 0.0) return
    val position = if (progressPercent >= 95.0) duration else lastPlaybackPositionSec
    viewModelScope.launch {
      apiClient.putPlaybackProgress(
        session = session,
        profileId = uiState.activeProfileId,
        entityType = player.mediaType,
        entityId = player.mediaId,
        episodeKey = playbackEpisodeKey(player.seasonNumber, player.episodeNumber),
        positionSec = position,
        durationSec = duration,
        title = player.title,
        poster = player.poster,
        backdrop = player.backdrop,
        year = player.year?.toString(),
        seasonNumber = player.seasonNumber,
        episodeNumber = player.episodeNumber,
      ).onSuccess {
        activeOwnerKey()?.let { ownerKey ->
          playbackResumeStore.markSynced(
            ownerKey, player.mediaId, player.mediaType, player.seasonNumber, player.episodeNumber,
            System.currentTimeMillis(),
          )
        }
      }
    }
  }

  /**
   * Records a title as finished on the account.
   *
   * Written rather than deleted, which is what "mark as watched" used to do. A deletion cannot
   * travel through a list of records, so the other devices learnt nothing; a completed row goes
   * down the same path that watching something to the end already uses, and arrives as a tick and
   * a removal from Continue Watching without Trakt being involved at all.
   *
   * A whole series carries no episode key, so its in-progress episodes are dropped first --
   * otherwise the marker and the half-watched episode it is meant to retire would both come back
   * in the same pull.
   */
  private fun pushWatchedProgress(item: MediaItem, seasonNumber: Int? = null, episodeNumber: Int? = null) {
    val session = uiState.session ?: return
    val profileId = uiState.activeProfileId
    val type = if (item.type.equals("movie", true)) "movie" else "tv"
    val episodeKey = playbackEpisodeKey(seasonNumber, episodeNumber)
    viewModelScope.launch {
      if (type == "tv" && episodeKey == null) {
        apiClient.deletePlaybackProgress(session, profileId, type, item.id)
      }
      apiClient.putPlaybackProgress(
        session = session,
        profileId = profileId,
        entityType = type,
        entityId = item.id,
        episodeKey = episodeKey,
        positionSec = 0.0,
        durationSec = 0.0,
        title = item.title,
        poster = item.poster,
        backdrop = item.backdrop,
        year = item.year,
        seasonNumber = seasonNumber,
        episodeNumber = episodeNumber,
        completed = true,
      )
    }
  }

  /** Empties this profile's Continue Watching on the account as well as on this device. */
  private fun clearRemoteContinueWatching() {
    val session = uiState.session ?: return
    val profileId = uiState.activeProfileId
    viewModelScope.launch { apiClient.clearPlaybackProgress(session, profileId) }
  }

  /** Forgets a title's place on the account as well as on this device. */
  private fun clearRemotePlaybackProgress(mediaId: String, mediaType: String, seasonNumber: Int? = null, episodeNumber: Int? = null) {
    val session = uiState.session ?: return
    viewModelScope.launch {
      apiClient.deletePlaybackProgress(session, uiState.activeProfileId, mediaType, mediaId, playbackEpisodeKey(seasonNumber, episodeNumber))
    }
  }

  /**
   * Takes the account's copy of where things were left and folds it into this device's.
   *
   * Newest wins, per title and per episode: both sides stamp their own writes, so a film finished
   * on the television beats a stale local position and a position set here a moment ago is not
   * overwritten by an older one from the server. A completed title is recorded the same way
   * [markWatched] records one, which is what takes it out of Continue Watching rather than leaving
   * it sitting at 99%.
   */
  /** One page of the account's positions. The local store keeps 80, so this always covers it. */
  private val PROGRESS_PULL_LIMIT = 100

  fun pullPlaybackProgress() {
    val session = uiState.session ?: return
    // Nothing to pull into until a profile is chosen. Positions are the profile's, and a request
    // that names none is answered with the account's default profile -- so pulling early filed one
    // viewer's positions under the pre-profile owner key, which is a different set of rows again.
    // The effect that calls this is keyed on the active profile, so choosing one runs it properly.
    val profileId = uiState.activeProfileId ?: return
    val ownerKey = activeOwnerKey() ?: return
    viewModelScope.launch {
      val remote = apiClient.fetchPlaybackProgress(session, profileId, PROGRESS_PULL_LIMIT)
        .getOrNull() ?: return@launch
      if (uiState.session?.user?.uid != session.user.uid || activeOwnerKey() != ownerKey) return@launch
      val local = playbackResumeStore.loadAll(ownerKey).associateBy { entry ->
        listOf(normalizedMediaType(entry.mediaType), entry.mediaId, entry.seasonNumber?.toString().orEmpty(), entry.episodeNumber?.toString().orEmpty()).joinToString(":")
      }
      var changed = false
      val seen = hashSetOf<String>()
      remote.forEach { record ->
        val type = if (record.entityType.equals("movie", true)) "movie" else "tv"
        val key = listOf(normalizedMediaType(type), record.entityId, record.seasonNumber?.toString().orEmpty(), record.episodeNumber?.toString().orEmpty()).joinToString(":")
        seen += key
        val existing = local[key]
        if (existing != null && (existing.updatedAt ?: 0L) >= record.updatedAt) return@forEach
        changed = true
        if (record.unwatched) {
          if (record.seasonNumber != null && record.episodeNumber != null) {
            val watchedKey = watchedEpisodeKey(record.entityId, record.seasonNumber, record.episodeNumber)
            watchedEpisodeStore.save(
              ownerKey,
              record.entityId,
              watchedEpisodeStore.load(ownerKey, record.entityId).filterNot { it == watchedKey },
            )
          }
          playbackResumeStore.remove(ownerKey, record.entityId, type, record.seasonNumber, record.episodeNumber)
        } else if (record.dismissed) {
          playbackResumeStore.removeTitle(ownerKey, record.entityId, type)
        } else if (record.completed) {
          // Finished elsewhere -- either played out, or marked watched, which now writes the same
          // kind of row rather than deleting one. The same two moves markWatched makes locally.
          if (record.seasonNumber != null && record.episodeNumber != null) {
            val watchedKey = watchedEpisodeKey(record.entityId, record.seasonNumber, record.episodeNumber)
            watchedEpisodeStore.save(
              ownerKey,
              record.entityId,
              completedEpisodeWatchedIds(watchedEpisodeStore.load(ownerKey, record.entityId), watchedKey),
            )
            // One episode finished, not the series. Dropping the whole title here would take the
            // next episode's position with it, which is the one the viewer is about to want.
            playbackResumeStore.remove(ownerKey, record.entityId, type, record.seasonNumber, record.episodeNumber)
          } else {
            watchedTitleStore.add(ownerKey, MediaItem(record.entityId, type, record.title.orEmpty(), record.year, record.poster, record.backdrop, null, ""))
            playbackResumeStore.removeTitle(ownerKey, record.entityId, type)
          }
        } else {
          playbackResumeStore.save(
            ownerKey,
            PlaybackMemoryEntry(
              mediaId = record.entityId,
              mediaType = type,
              title = record.title.orEmpty().ifBlank { existing?.title.orEmpty() },
              year = record.year ?: existing?.year,
              // A record with no artwork is missing information, not an instruction to forget what
              // this device already knew. Taking it literally is how a card that had a poster this
              // morning went blank: the position was newer, so the whole entry was replaced, art
              // and all.
              poster = record.poster ?: existing?.poster,
              backdrop = record.backdrop ?: existing?.backdrop,
              seasonNumber = record.seasonNumber,
              episodeNumber = record.episodeNumber,
              progressPercent = record.progress,
              positionSeconds = record.positionSec.takeIf { it >= 0.0 },
              durationSeconds = record.durationSec.takeIf { it > 0.0 }?.toInt() ?: existing?.durationSeconds,
              // The same reasoning as the artwork above, and the reason Remember Last Source read
              // as broken: the account stores a position, not a source, so every pull replaced the
              // entry with one that had forgotten which stream had played. Continue Watching then
              // had nothing to resume from and fell back to opening the detail page. The server
              // does not know this, so it cannot be asked -- what this device already knew is the
              // only copy there is.
              stream = existing?.stream,
              isLive = existing?.isLive ?: false,
              updatedAt = record.updatedAt,
              lastDevice = record.lastDevice,
              lastPlatform = record.lastPlatform,
              syncedAt = record.updatedAt,
            ),
            touch = false,
          )
        }
      }

      // Anything the account no longer holds was removed on another device: "remove from Continue
      // Watching", "start over", or a clear. Only entries known to have reached the account are
      // eligible, because one that never made it up there is a position recorded offline rather
      // than a deletion. Skipped when the page came back full, since the absentees may then be
      // nothing more than the rows past the end of it.
      if (remote.size < PROGRESS_PULL_LIMIT) {
        local.forEach { (key, entry) ->
          if (key in seen || entry.isLive || entry.syncedAt == null) return@forEach
          changed = true
          playbackResumeStore.remove(ownerKey, entry.mediaId, entry.mediaType, entry.seasonNumber, entry.episodeNumber)
        }
      }

      uiState = uiState.copy(playbackProgressRecords = remote)
      if (changed) {
        uiState = uiState.copy(
          localContinueWatching = loadLocalContinueWatching(),
          localResumeEntries = loadResumeEntries(),
          watchedEpisodeRevision = uiState.watchedEpisodeRevision + 1,
        )
      }
    }
  }

  /** "S1 E3", or nothing at all for a film. */
  private fun episodeLabel(seasonNumber: Int?, episodeNumber: Int?): String? =
    if (seasonNumber != null && episodeNumber != null) "S$seasonNumber E$episodeNumber" else null

  private fun loadLocalContinueWatching(): List<MediaItem> {
    val ownerKey = activeOwnerKey() ?: GUEST_OWNER_KEY
    val watchedMovies = watchedMovieStore.load(ownerKey).toSet()
    return playbackResumeStore.loadAll(ownerKey)
      .filter { entry -> !entry.isLive && entry.mediaType.lowercase() !in setOf("live", "channel", "sports", "sport") }
      // A viewer can genuinely have more than one episode in progress. Collapse duplicate writes
      // for the same episode, not the whole series, so each started episode keeps its own card.
      .groupBy { entry ->
        buildString {
          append("${normalizedMediaType(entry.mediaType)}:${entry.mediaId}")
          if (normalizedMediaType(entry.mediaType) == "tv" && entry.seasonNumber != null && entry.episodeNumber != null) {
            append(":s${entry.seasonNumber}:e${entry.episodeNumber}")
          }
        }
      }
      .mapNotNull { (_, entries) -> entries.maxByOrNull { it.updatedAt } }
      .sortedByDescending { it.updatedAt }
      .map { entry ->
        val isSeries = normalizedMediaType(entry.mediaType) == "tv"
        MediaItem(
          id = entry.mediaId,
          type = entry.mediaType,
          title = entry.title,
          year = entry.year,
          poster = entry.poster,
          backdrop = entry.backdrop,
          rating = null,
          description = "",
          progress = entry.progressPercent,
          updatedAt = entry.updatedAt,
          resumeSeasonNumber = entry.seasonNumber.takeIf { isSeries },
          resumeEpisodeNumber = entry.episodeNumber.takeIf { isSeries },
          historicallyWatched = if (normalizedMediaType(entry.mediaType) == "movie") {
            entry.mediaId in watchedMovies
          } else if (entry.seasonNumber != null && entry.episodeNumber != null) {
            watchedEpisodeKey(entry.mediaId, entry.seasonNumber, entry.episodeNumber) in
              watchedEpisodeStore.load(ownerKey, entry.mediaId)
          } else false,
          // Which episode you are part-way through, rather than the year the series began. The
          // card is an invitation to carry on, and "2026" answers a question nobody asked.
          cardSubtitle = episodeLabel(entry.seasonNumber, entry.episodeNumber).takeIf { isSeries },
        )
      }
  }

  /**
   * How an episode is named on the account: `s01e04`, or nothing at all for a film.
   *
   * Has to match what the television writes, or the two would file the same episode twice and
   * neither would ever see the other's position.
   */
  private fun playbackEpisodeKey(seasonNumber: Int?, episodeNumber: Int?): String? {
    if (seasonNumber == null || episodeNumber == null) return null
    return "s%02de%02d".format(seasonNumber, episodeNumber)
  }

  private fun loadResumeEntries(): List<PlaybackMemoryEntry> =
    playbackResumeStore.loadAll(activeOwnerKey() ?: GUEST_OWNER_KEY)

  private fun rememberedEpisodeFor(detail: MediaDetail): EpisodeItem? {
    if (detail.type != "tv" || uiState.detailIsLive) return null
    val entry = playbackResumeStore.loadAll(activeOwnerKey() ?: GUEST_OWNER_KEY)
      .filter { it.mediaId == detail.id && it.mediaType == "tv" && it.progressPercent in 1.0..94.9 }
      .maxByOrNull { it.updatedAt } ?: return null
    val seasonNumber = entry.seasonNumber ?: return null
    val episodeNumber = entry.episodeNumber ?: return null
    return EpisodeItem(
      id = "${detail.id}:$seasonNumber:$episodeNumber",
      episodeNumber = episodeNumber,
      seasonNumber = seasonNumber,
      name = "Episode $episodeNumber",
      overview = "",
      still = null,
      runtime = entry.durationSeconds?.div(60),
    )
  }

  private fun loadPlaybackMemoryEntry(detail: MediaDetail, episode: EpisodeItem?): PlaybackMemoryEntry? {
    val ownerKey = activeOwnerKey() ?: GUEST_OWNER_KEY
    val mediaType = if (detail.type == "series") "tv" else detail.type
    return playbackResumeStore.loadAll(ownerKey).firstOrNull {
      it.mediaId == detail.id &&
        it.mediaType == mediaType &&
        it.seasonNumber == episode?.seasonNumber &&
        it.episodeNumber == episode?.episodeNumber
    }
  }

  /** The last position the player reported, so a snapshot taken elsewhere still has seconds. */
  private var lastPlaybackPositionSec: Double = 0.0
  private var lastPlaybackDurationSec: Double = 0.0

  private fun saveCurrentPlaybackSnapshot(progressPercent: Double) {
    val ownerKey = activeOwnerKey() ?: GUEST_OWNER_KEY
    val player = uiState.playerSession ?: return
    val normalizedProgress = progressPercent.coerceIn(0.0, 100.0)
    if (player.isLive) {
      // Live has no meaningful resume position, but the entry is still worth keeping
      // as a record of the source that worked. Continue Watching filters live entries
      // out on load, so this never shows up there.
      if (uiState.rememberLastSource) {
        playbackResumeStore.save(
          ownerKey,
          PlaybackMemoryEntry(
            mediaId = player.mediaId,
            mediaType = player.mediaType,
            title = player.title,
            year = player.year?.toString(),
            poster = player.poster,
            backdrop = player.backdrop,
            progressPercent = 0.0,
            isLive = true,
            stream = if (uiState.rememberLastSource) player.currentStream else null,
          ),
        )
      } else {
        playbackResumeStore.remove(ownerKey, player.mediaId, player.mediaType, player.seasonNumber, player.episodeNumber)
      }
      uiState = uiState.copy(localContinueWatching = loadLocalContinueWatching(), localResumeEntries = loadResumeEntries())
      return
    }
    pushPlaybackProgress(player, normalizedProgress)
    if (normalizedProgress >= 95.0 || normalizedProgress <= 1.0) {
      playbackResumeStore.remove(ownerKey, player.mediaId, player.mediaType, player.seasonNumber, player.episodeNumber)
    } else {
      playbackResumeStore.save(
        ownerKey,
        PlaybackMemoryEntry(
          mediaId = player.mediaId,
          mediaType = player.mediaType,
          title = player.title,
          year = player.year?.toString(),
          poster = player.poster,
          backdrop = player.backdrop,
          seasonNumber = player.seasonNumber,
          episodeNumber = player.episodeNumber,
          progressPercent = normalizedProgress,
          positionSeconds = lastPlaybackPositionSec.takeIf { it >= 0.0 },
          durationSeconds = lastPlaybackDurationSec.takeIf { it > 0.0 }?.toInt() ?: player.runtimeMinutes?.times(60),
          isLive = player.isLive,
          stream = if (uiState.rememberLastSource) player.currentStream else null,
        ),
      )
    }
    uiState = uiState.copy(localContinueWatching = loadLocalContinueWatching(), localResumeEntries = loadResumeEntries())
  }

  private fun mergedContinueWatchingItems(): List<MediaItem> {
    val providerItems = uiState.traktContinueWatching.filterNot { provider ->
      uiState.playbackProgressRecords.any { record -> progressRecordSuppressesProviderItem(record, provider.toMediaItem()) }
    }.map(TraktItem::toMediaItem)
    return mergeContinueWatchingItems(providerItems, uiState.localContinueWatching)
  }

  private fun mergeWatchlistWithLocal(traktItems: List<TraktItem>, localOverride: List<MediaItem>? = null): List<MediaItem> {
    val merged = linkedMapOf<String, MediaItem>()
    traktItems.forEach { item ->
      val media = item.toMediaItem()
      merged[mediaKey(media.type, media.id)] = media
    }
    (localOverride ?: loadLocalWatchlist()).forEach { item ->
      val key = mediaKey(item.type, item.id)
      val traktItem = merged[key]
      merged[key] = if (traktItem == null) item else item.copy(
        addedAt = item.addedAt ?: traktItem.addedAt,
        updatedAt = item.updatedAt ?: traktItem.updatedAt,
      )
    }
    return merged.values.sortedWith(
      compareByDescending<MediaItem> { it.addedAt ?: Long.MIN_VALUE }
        .thenByDescending { it.updatedAt ?: Long.MIN_VALUE },
    )
  }

  private fun scrobbleCurrentPlayer(action: String, progressPercent: Double) {
    // Pausing settles the position, whoever is or is not connected. This used to sit below the
    // Trakt check, so an account without Trakt only ever persisted on the periodic checkpoint --
    // survivable at ten seconds, and a visible loss now that the checkpoint is every thirty.
    if (action == "pause" || action == "stop") saveCurrentPlaybackSnapshot(progressPercent)
    val session = uiState.session ?: return
    val profileId = uiState.activeProfileId ?: return
    val player = uiState.playerSession ?: return
    if (!uiState.traktStatus.connected) return
    launchWork(
      onStart = {},
      block = {
        apiClient.scrobbleTrakt(
          session = session,
          profileId = profileId,
          action = action,
          payload = TraktScrobblePayload(
            mediaId = uiState.detail?.id ?: player.mediaId,
            mediaType = uiState.detail?.type ?: player.mediaType,
            title = uiState.detail?.title ?: player.title,
            year = uiState.detail?.year?.toIntOrNull() ?: player.year,
            progress = progressPercent,
            seasonNumber = uiState.selectedEpisode?.seasonNumber ?: player.seasonNumber,
            episodeNumber = uiState.selectedEpisode?.episodeNumber ?: player.episodeNumber,
            episodeTitle = uiState.selectedEpisode?.name ?: player.episodeTitle,
          ),
        )
      },
      onSuccess = {
        if (action == "pause" || action == "stop") refreshTraktData()
      },
      onFailure = {},
    )
  }

  private fun <T> launchWork(onStart: () -> Unit, block: suspend () -> Result<T>, onSuccess: (T) -> Unit, onFailure: (String) -> Unit = { message -> uiState = uiState.copy(errorMessage = message) }) {
    onStart()
    viewModelScope.launch {
      val result = runCatching { withContext(Dispatchers.IO) { block() } }.getOrElse { Result.failure(it) }
      result.onSuccess(onSuccess).onFailure { throwable -> onFailure(throwable.message ?: "Network error. Check your connection.") }
    }
  }

  private fun traktItemId(item: TraktItem): String = item.tmdbId?.toString() ?: item.id

  private fun buildPlayerSession(url: String, detail: MediaDetail, sourceLabel: String?, episode: EpisodeItem?, stream: AddonStream, resumePercent: Double = 0.0, resumePositionSec: Double = 0.0): PlayerSession = PlayerSession(
    holdToSpeedEnabled = uiState.holdToSpeedEnabled,
    holdToSpeedMultiplier = uiState.holdToSpeedMultiplier,
    swipeToSeekEnabled = uiState.swipeToSeekEnabled,
    doubleTapSeekEnabled = uiState.doubleTapSeekEnabled,
    doubleTapSeekSeconds = uiState.doubleTapSeekSeconds,
    doubleTapPlayPauseEnabled = uiState.doubleTapPlayPauseEnabled,
    showPlayerControlLabels = uiState.showPlayerControlLabels,
    playerControlLayout = uiState.playerControlLayout,
    fullscreenStatusBar = uiState.fullscreenStatusBar,
    playerTitleDisplay = uiState.playerTitleDisplay,
    favoriteSourceKeys = uiState.favoriteSourceKeys,
    levelGesturesEnabled = uiState.playerLevelGesturesEnabled,
    url = url,
    title = sanitizeDisplayText(detail.title).orEmpty(),
    subtitle = sanitizeDisplayText(episode?.let { "S${it.seasonNumber} E${it.episodeNumber}" } ?: detail.year),
    sourceLabel = sanitizeDisplayText(sourceLabel),
    qualityLabel = stream.quality,
    sizeLabel = stream.size,
    backdrop = episode?.still ?: detail.backdrop ?: detail.poster,
    poster = detail.poster,
    titleLogo = detail.titleLogo,
    // Live channels have no synopsis — keep it null so the player omits the block.
    synopsis = sanitizeDisplayText(if (uiState.detailIsLive) null else episode?.overview?.ifBlank { detail.description } ?: detail.description),
    mediaId = detail.id,
    mediaType = detail.type,
    year = detail.year?.toIntOrNull(),
    seasonNumber = episode?.seasonNumber,
    episodeNumber = episode?.episodeNumber,
    episodeTitle = sanitizeDisplayText(episode?.name),
    pictureInPictureEnabled = uiState.pictureInPictureEnabled,
    decoderMode = uiState.decoderMode,
    renderSurface = uiState.renderSurface,
    // A saved download can only be read back through Media3's cache-aware data source chain, so
    // resuming one overrides the engine preference rather than failing to open under mpv.
    playerEngine = if (stream.source == DOWNLOAD_STREAM_SOURCE) "Media3" else uiState.playerEngine,
    preferredAudioLanguage = uiState.preferredAudioLanguage,
    resumePercent = resumePercent,
    resumePositionSec = resumePositionSec,
    currentStream = stream,
    imdbId = detail.imdbId ?: detail.id.takeIf { it.startsWith("tt") },
    tmdbId = detail.id.toIntOrNull()?.takeIf { it > 0 },
    // This is the explicit subtitle setting shown to the viewer. A general profile-language field
    // must not silently replace it or "Show only preferred" filters the list using another value.
    subtitleLanguage = uiState.preferredSubtitleLanguage,
    secondarySubtitleLanguage = uiState.secondarySubtitleLanguage,
    secondaryAudioLanguage = uiState.secondaryAudioLanguage,
    useForcedSubtitles = uiState.useForcedSubtitles,
    showOnlyPreferredSubtitleLanguages = uiState.showOnlyPreferredSubtitleLanguages,
    addonSubtitleLoading = uiState.addonSubtitleLoading,
    autoLoadSubtitles = uiState.autoLoadSubtitles,
    subtitleTextSize = uiState.subtitleTextSize,
    subtitleVerticalOffset = uiState.subtitleVerticalOffset,
    subtitleBold = uiState.subtitleBold,
    subtitleTextColor = uiState.subtitleTextColor,
    subtitleBackgroundColor = uiState.subtitleBackgroundColor,
    subtitleOutline = uiState.subtitleOutline,
    subtitleOutlineColor = uiState.subtitleOutlineColor,
    subtitleDefaultSource = uiState.subtitleDefaultSource,
    skipIntroEnabled = uiState.skipIntroEnabled,
    skipRecapEnabled = uiState.skipRecapEnabled,
    skipEndingEnabled = uiState.skipEndingEnabled,
    autoSkipIntroEnabled = uiState.autoSkipIntroEnabled,
    autoSkipRecapEnabled = uiState.autoSkipRecapEnabled,
    autoSkipEndingEnabled = uiState.autoSkipEndingEnabled,
    introdbApiKey = uiState.introdbApiKey,
    autoPlayNextEpisode = uiState.autoPlayNextEpisode,
    preferBingeGroup = uiState.preferBingeGroup,
    nextEpisodeThresholdMode = uiState.nextEpisodeThresholdMode,
    nextEpisodeThresholdPercent = uiState.nextEpisodeThresholdPercent,
    nextEpisodeThresholdMinutes = uiState.nextEpisodeThresholdMinutes,
    recommendations = detail.similarTitles.filter { it.id != detail.id }.take(uiState.recommendationItemCount),
    endOfPlaybackRecommendationsEnabled = uiState.endOfPlaybackRecommendationsEnabled,
    recommendationTiming = uiState.recommendationTiming,
    recommendationItemCount = uiState.recommendationItemCount,
    requestHeaders = stream.requestHeaders,
    drmLicenseType = stream.drmLicenseType,
    drmClearKeys = stream.drmClearKeys,
    isLive = uiState.detailIsLive,
    isVod = uiState.detailIsLive && detailSourceCatalogType.equals("movie", ignoreCase = true),
    showLiveProgressBar = uiState.liveProgressBarEnabled,
    runtimeMinutes = episode?.runtime ?: detail.runtimeMinutes,
    addonSubtitleSources = addonSubtitleSources(),
    userSubtitleSources = UserSubtitleSourceStore.load(getApplication<Application>().applicationContext, activeOwnerKey() ?: GUEST_OWNER_KEY),
    isProxied = stream.isLikelyProxied(uiState.addons.firstOrNull { it.id == stream.addonId }),
  )

  /** Metadata-only session for the unified player loading scene; no playback engine sees this. */
  private fun buildPlayerLaunchSession(detail: MediaDetail, episode: EpisodeItem?, stream: AddonStream): PlayerSession = PlayerSession(
    url = "",
    title = sanitizeDisplayText(detail.title).orEmpty(),
    subtitle = sanitizeDisplayText(episode?.let { "S${it.seasonNumber} E${it.episodeNumber}" } ?: detail.year),
    sourceLabel = sanitizeDisplayText(buildSourceLabel(stream) ?: stream.addonName),
    qualityLabel = stream.quality,
    sizeLabel = stream.size,
    backdrop = episode?.still ?: detail.backdrop ?: detail.poster,
    poster = detail.poster,
    titleLogo = detail.titleLogo,
    synopsis = sanitizeDisplayText(if (uiState.detailIsLive) null else episode?.overview?.ifBlank { detail.description } ?: detail.description),
    mediaId = detail.id,
    mediaType = detail.type,
    year = detail.year?.toIntOrNull(),
    seasonNumber = episode?.seasonNumber,
    episodeNumber = episode?.episodeNumber,
    episodeTitle = sanitizeDisplayText(episode?.name),
    currentStream = stream,
    isLive = uiState.detailIsLive,
  )

  // Installed, enabled addons that advertise the Stremio "subtitles" resource are
  // queried alongside the user's manual subtitle sources.
  private fun addonSubtitleSources(): List<UserSubtitleSource> = uiState.addons
    .filter { addon ->
      addon.enabled && addon.manifest.resources.any { it.trim().equals("subtitles", ignoreCase = true) }
    }
    .mapNotNull { addon ->
      val manifestUrl = addon.transportUrl ?: addon.manifestUrl ?: addon.url ?: addon.baseUrl ?: return@mapNotNull null
      val baseUrl = manifestUrl.substringBeforeLast("/manifest.json", missingDelimiterValue = manifestUrl).trimEnd('/')
      if (baseUrl.isBlank()) return@mapNotNull null
      UserSubtitleSource(
        id = "addon:${addon.id}",
        name = addon.manifest.name.ifBlank { addon.id },
        baseUrl = baseUrl,
      )
    }

  private fun buildSourceLabel(stream: AddonStream): String? = listOfNotNull(stream.addonName.takeIf { it.isNotBlank() }, stream.source?.takeIf { it.isNotBlank() }, stream.quality, stream.size?.takeIf { it.isNotBlank() }?.let { "[$it]" }).distinct().joinToString(" \u2022 ").ifBlank { stream.name }
}
private class NativeAppViewModelFactory(
  private val application: Application,
) : ViewModelProvider.Factory {
  override fun <T : ViewModel> create(modelClass: Class<T>): T {
    @Suppress("UNCHECKED_CAST")
    return NativeAppViewModel(application) as T
  }
}

@OptIn(androidx.compose.foundation.layout.ExperimentalLayoutApi::class)
@Composable
fun StreamDekNativeApp(
  pendingAddonManifestUrl: String? = null,
  onAddonManifestConsumed: () -> Unit = {},
  pendingEpisodeNotification: EpisodeNotificationTarget? = null,
  onEpisodeNotificationConsumed: () -> Unit = {},
) {
  val context = androidx.compose.ui.platform.LocalContext.current.applicationContext as Application
  val viewModel = viewModel<NativeAppViewModel>(factory = NativeAppViewModelFactory(context))
  val uiState = viewModel.uiState
  LaunchedEffect(uiState.playerSession?.url, uiState.session?.user?.uid) {
    if (uiState.playerSession != null) viewModel.refreshHandoffDevices()
  }
  // Someone making a change in the portal and switching straight back to the app is the whole
  // reason plugin sync felt broken, so the plugin document is re-read whenever the app is
  // brought forward rather than only when a profile is chosen.
  val lifecycleOwner = androidx.lifecycle.compose.LocalLifecycleOwner.current
  DisposableEffect(lifecycleOwner, uiState.session?.user?.uid, uiState.activeProfileId) {
    val observer = LifecycleEventObserver { _, event ->
      if (event == Lifecycle.Event.ON_START) {
        viewModel.refreshContentPolicy()
        viewModel.pullPlaybackProgress()
        viewModel.refreshProfilePlugins()
        // Air dates get revised and a reminder that has already fired leaves nothing behind, so
        // the next one is worked out each time the app comes forward rather than only on a change.
        viewModel.refreshEpisodeReminders()
        // Then keep watching while the app is in front, so an edit made in the portal lands here
        // without the viewer having to leave and come back for it.
        viewModel.startWatchingProfilePlugins()
      }
      if (event == Lifecycle.Event.ON_STOP) viewModel.stopWatchingProfilePlugins()
    }
    lifecycleOwner.lifecycle.addObserver(observer)
    onDispose { lifecycleOwner.lifecycle.removeObserver(observer) }
  }
  // deviceInDarkTheme(), not isSystemInDarkTheme(): the latter reads the activity's configuration,
  // whose night bits this app pins in attachBaseContext, so it answers with whichever appearance the
  // process started under rather than with the phone's. See [deviceInDarkTheme].
  val systemDarkMode = deviceInDarkTheme()
  val darkMode = when (uiState.appAppearance) {
    AppAppearance.Dark -> true
    AppAppearance.Light -> false
    AppAppearance.System -> systemDarkMode
  }
  val colorScheme = remember(uiState.themePreset, darkMode) { appColorScheme(uiState.themePreset, darkMode) }
  // The same theme in its dark form, for the surfaces that are dark in every appearance because
  // they are pictures rather than pages. Only the player uses it today; see [LocalDarkColorScheme].
  val darkColorScheme = remember(uiState.themePreset) { appColorScheme(uiState.themePreset, darkMode = true) }
  val activity = LocalContext.current as? Activity
  DisposableEffect(activity, darkMode) {
    activity?.window?.let { window ->
      // Deprecated in API 35+ edge-to-edge, but still the correct way to tint the
      // navigation bar on the API levels this app supports.
      @Suppress("DEPRECATION")
      window.navigationBarColor = if (darkMode) android.graphics.Color.BLACK else android.graphics.Color.WHITE
      WindowInsetsControllerCompat(window, window.decorView).apply {
        isAppearanceLightStatusBars = !darkMode
        isAppearanceLightNavigationBars = !darkMode
      }
    }
    onDispose {}
  }

  // Transient messages all withdraw on their own; the banner's close button does it sooner. An
  // error is given longer than a confirmation, since it usually asks the viewer to do something.
  LaunchedEffect(uiState.errorMessage, uiState.infoMessage) {
    val message = uiState.errorMessage ?: uiState.infoMessage
    if (message.isNullOrBlank()) return@LaunchedEffect
    delay(if (uiState.errorMessage != null) APP_NOTICE_ERROR_DURATION_MS else appInfoNoticeDuration(message))
    viewModel.clearTransientMessage()
  }

  // Withdraws on its own after twelve seconds; the banner's own close button does it sooner.
  LaunchedEffect(uiState.playbackNotice) {
    if (uiState.playbackNotice.isNullOrBlank()) return@LaunchedEffect
    delay(PLAYBACK_NOTICE_DURATION_MS)
    viewModel.clearPlaybackNotice()
  }

  LaunchedEffect(uiState.debridNoticeMessage) {
    if (!uiState.debridNoticeMessage.isNullOrBlank()) {
      delay(30_000)
      viewModel.dismissDebridNotice()
    }
  }

  LaunchedEffect(uiState.debridSignIn?.outcome) {
    if (!uiState.debridSignIn?.outcome.isNullOrBlank()) {
      delay(30_000)
      viewModel.dismissDebridSignIn()
    }
  }

  // Measured from the window rather than the device, and re-read on every configuration change, so
  // folding, rotating or dragging the app into a split-screen pane all land in the right layout.
  val configuration = LocalConfiguration.current
  val windowSize = remember(configuration.screenWidthDp, configuration.screenHeightDp) {
    WindowSize(widthDp = configuration.screenWidthDp.dp, heightDp = configuration.screenHeightDp.dp)
  }
  val spacing = remember(windowSize.widthClass) { StreamDekSpacing.forWidth(windowSize.widthClass) }

  MaterialTheme(
    colorScheme = colorScheme,
    shapes = Shapes(
      extraSmall = StreamDekRadius.controlShape,
      small = StreamDekRadius.thumbShape,
      medium = StreamDekRadius.cardShape,
      large = StreamDekRadius.panelShape,
      extraLarge = StreamDekRadius.sheetShape,
    ),
  ) {
   ProvideStreamDekMotion(rememberMotionSettings(uiState.animationSpeed)) {
   CompositionLocalProvider(
     LocalWindowSize provides windowSize,
     LocalStreamDekSpacing provides spacing,
     LocalDarkColorScheme provides darkColorScheme,
     LocalCardRatingsEnabled provides uiState.ratingsEnabled,
   ) {
    Surface(modifier = Modifier.fillMaxSize(), color = MaterialTheme.colorScheme.background) {
      Box(modifier = Modifier.fillMaxSize().background(MaterialTheme.colorScheme.background)) {
        Scaffold(
          containerColor = Color.Transparent,
        ) { padding ->
          // The player replaces the whole main scene, so hold the main scene's
          // saveable state (scroll positions, browse page state) while it is away.
          val rootStateHolder = rememberSaveableStateHolder()
          // Do not animate two root scenes at once. A fast Back while the detail scene was still
          // AnimatedContent's outgoing child mounted a second SaveableStateProvider("main_scene")
          // before the first was disposed, which Compose correctly rejects as a duplicate key.
          // The player owns its loading visuals, so a direct switch is also the intended handoff.
          val rootPlayerSession = uiState.playerSession ?: uiState.playerLaunchSession
          when {
              uiState.booting -> SplashScene()
              rootPlayerSession != null -> {
                // Stable across the provisional-to-real session handoff. NativePlayerScreen's
                // richer handler wins while composed; this catches a system-back gesture during
                // the branch swap so it can never fall through to the Activity and exit the app.
                BackHandler {
                  if (uiState.playerSession != null) viewModel.dismissPlayer() else viewModel.cancelPlayerLaunch()
                }
                NativePlayerScreen(
                session = rootPlayerSession,
                resolving = uiState.playerSession == null,
                resolvingSourceLabel = uiState.playerLaunchingLabel,
                resolvingPeerHash = uiState.playerLaunchingPeerHash,
                onCancelResolving = viewModel::cancelPlayerLaunch,
                availableStreams = uiState.availableStreams,
                handoffDevices = uiState.handoffDevices,
                onHandoff = viewModel::handoffCurrentPlayback,
                onSubtitleTextSizeChange = viewModel::setSubtitleTextSize,
                onSubtitleVerticalOffsetChange = viewModel::setSubtitleVerticalOffset,
                onSubtitleSourceChange = viewModel::setSubtitleDefaultSource,
                onToggleSourceFavourite = viewModel::toggleFavoriteSource,
                onBack = viewModel::dismissPlayer,
                onScrobble = viewModel::scrobblePlayer,
                onProgressCheckpoint = viewModel::savePlayerProgressCheckpoint,
                onSelectStream = { stream, resumePercent -> viewModel.playStream(stream, resumePercentOverride = resumePercent) },
                onReloadStreams = { viewModel.loadStreamsForCurrentDetail(uiState.selectedEpisode) },
                onPlaybackEnded = viewModel::onPlayerPlaybackEnded,
                onRecommendedPlaybackEnded = viewModel::playRecommendedFromEnding,
                nextEpisodeLoading = uiState.nextEpisodeLoading,
                nextEpisodeLoadingLabel = uiState.nextEpisodeLoadingLabel,
                onPreviousEpisode = { viewModel.playAdjacentEpisode(-1) },
                onNextEpisode = { viewModel.playAdjacentEpisode(1) },
                onNextEpisodeAtEnding = viewModel::playNextEpisodeFromEnding,
                isFavourite = uiState.favouriteChannels.any { it.id == (uiState.playerSession ?: uiState.playerLaunchSession)?.mediaId },
                onToggleFavourite = viewModel::toggleFavouriteChannelForCurrentSession,
                liveChannels = uiState.playerLiveChannels,
                liveChannelsLoading = uiState.playerLiveChannelsLoading,
                channelSwitchLoading = uiState.liveChannelSwitching,
                channelSwitchLoadingLabel = uiState.liveChannelSwitchingLabel,
                onCancelChannelSwitch = viewModel::cancelLiveChannelSwitch,
                onChannelSwitchPlaybackStarted = viewModel::confirmLiveChannelSwitchStarted,
                channelSwitchFallbackAvailable = uiState.playerSession?.isLive == true && viewModel.hasLiveChannelFallback(),
                favouriteChannels = uiState.favouriteChannels,
                favouriteDrawerCards = uiState.liveFavouriteDrawerCards,
                onSelectLiveChannel = viewModel::playLiveChannel,
                onToggleFavouriteDrawerCards = viewModel::setLiveFavouriteDrawerCards,
                onClearFavourites = viewModel::clearFavouriteChannels,
                downloadsEnabled = uiState.downloadsEnabled,
                onDownloadStream = { stream -> viewModel.downloadStream(stream, uiState.detail?.title ?: uiState.playerSession?.title ?: "Download") },
              )
              }
              else -> rootStateHolder.SaveableStateProvider("main_scene") {
                MainScene(viewModel, pendingAddonManifestUrl, onAddonManifestConsumed, pendingEpisodeNotification, onEpisodeNotificationConsumed)
              }
          }
          // Sits above the scene rather than inside it so it reads the same over the launch screen,
          // the player and the home grid — the three places a premium service can refuse a source.
          AppNoticeStack(
            notices = buildList {
              uiState.playbackNotice?.takeIf { it.isNotBlank() }?.let {
                add(AppNotice("playback", "Premium service declined this source", it, AppNoticeTone.Warning, viewModel::clearPlaybackNotice))
              }
              uiState.errorMessage?.takeIf { it.isNotBlank() }?.let {
                add(AppNotice("error", "Something went wrong", it, AppNoticeTone.Error, viewModel::clearTransientMessage))
              }
              uiState.infoMessage?.takeIf { it.isNotBlank() }?.let {
                add(AppNotice("info", null, it, AppNoticeTone.Info, viewModel::clearTransientMessage))
              }
            },
            modifier = Modifier.align(Alignment.TopCenter),
          )
        }
      }
    }
   }
   }
  }
}

/** What a notice is about, which decides its colour. */
internal enum class AppNoticeTone { Info, Warning, Error }

/** One transient message: who it is from, what it says, and how to make it go away. */
internal data class AppNotice(
  val id: String,
  val title: String?,
  val message: String,
  val tone: AppNoticeTone,
  val onDismiss: () -> Unit,
)

/**
 * Every transient message in the app, at the top of the screen.
 *
 * One presentation for all of them. They used to arrive as a snackbar at the bottom, under the
 * navigation bar and the player controls, styled by Material rather than by StreamDek — and the
 * premium-service notice had its own separate look on top. Coming down from the top puts them where
 * the viewer is already looking during playback, and keeps them clear of the controls at the bottom.
 *
 * Stacked rather than queued: a playback attempt can produce a provider refusal and an error at the
 * same moment, and showing them one after the other hides the first behind a wait.
 */
@Composable
private fun AppNoticeStack(notices: List<AppNotice>, modifier: Modifier = Modifier) {
  Column(
    modifier = modifier.statusBarsPadding().padding(horizontal = 14.dp, vertical = 10.dp).widthIn(max = 560.dp),
    verticalArrangement = Arrangement.spacedBy(8.dp),
  ) {
    notices.forEach { notice ->
      key(notice.id) {
        AppNoticeBanner(notice = notice)
      }
    }
  }
}

@Composable
private fun AppNoticeBanner(notice: AppNotice) {
  // Held so the text does not blank out while the banner is sliding away.
  var shown by remember { mutableStateOf(notice) }
  LaunchedEffect(notice.message) { shown = notice }
  var visible by remember { mutableStateOf(false) }
  LaunchedEffect(Unit) { visible = true }
  AnimatedVisibility(
    visible = visible,
    enter = fadeIn() + slideInVertically { -it },
    exit = fadeOut() + slideOutVertically { -it },
  ) {
    val container = when (shown.tone) {
      AppNoticeTone.Error -> MaterialTheme.colorScheme.errorContainer
      AppNoticeTone.Warning -> MaterialTheme.colorScheme.errorContainer
      AppNoticeTone.Info -> MaterialTheme.colorScheme.surfaceVariant
    }
    val content = when (shown.tone) {
      AppNoticeTone.Error, AppNoticeTone.Warning -> MaterialTheme.colorScheme.onErrorContainer
      AppNoticeTone.Info -> MaterialTheme.colorScheme.onSurfaceVariant
    }
    Surface(
      modifier = Modifier.fillMaxWidth(),
      shape = StreamDekRadius.cardShape,
      color = container,
      contentColor = content,
      tonalElevation = 6.dp,
      shadowElevation = 10.dp,
    ) {
      Row(
        modifier = Modifier.padding(start = 16.dp, end = 6.dp, top = 12.dp, bottom = 12.dp),
        verticalAlignment = Alignment.CenterVertically,
        horizontalArrangement = Arrangement.spacedBy(10.dp),
      ) {
        Icon(
          if (shown.tone == AppNoticeTone.Info) Icons.Rounded.Info else Icons.Rounded.Warning,
          contentDescription = null,
          modifier = Modifier.size(20.dp),
        )
        Column(modifier = Modifier.weight(1f)) {
          shown.title?.let {
            Text(it, style = MaterialTheme.typography.labelLarge, fontWeight = FontWeight.Black)
          }
          Text(shown.message, style = MaterialTheme.typography.bodySmall, maxLines = 4, overflow = TextOverflow.Ellipsis)
        }
        IconButton(onClick = notice.onDismiss) {
          Icon(Icons.Rounded.Close, contentDescription = "Dismiss", modifier = Modifier.size(20.dp))
        }
      }
    }
  }
}

@Composable
private fun GradientBackdrop(content: @Composable () -> Unit) {
  Box(
    modifier = Modifier
      .fillMaxSize()
      .background(
        brush = Brush.verticalGradient(
          colors = listOf(Color(0xFF040B14), Color(0xFF0B1830), Color(0xFF07111C)),
        ),
      ),
  ) {
    Box(
      modifier = Modifier
        .fillMaxWidth()
        .height(340.dp)
        .background(
          brush = Brush.radialGradient(
            colors = listOf(Color(0xFF123B55), Color.Transparent),
            radius = 900f,
          ),
        ),
    )
    content()
  }
}

