@Composable
private fun UpdatePromptDialog(uiState: AppUiState, onUpdate: () -> Unit, onDismiss: () -> Unit) {
  val release = uiState.availableUpdate ?: return
  val mandatory = release.required || (release.minSupportedVersionCode?.let { BuildConfig.VERSION_CODE < it } == true)
  AlertDialog(
    onDismissRequest = { if (!mandatory && !uiState.updateDownloading) onDismiss() },
    title = {
      Column(verticalArrangement = Arrangement.spacedBy(10.dp)) {
        Box(modifier = Modifier.clip(StreamDekRadius.pill).background(MaterialTheme.colorScheme.primary.copy(alpha = 0.14f)).padding(horizontal = 12.dp, vertical = 7.dp)) {
          Text(if (mandatory) "Required update" else "Update available", color = MaterialTheme.colorScheme.primary, style = MaterialTheme.typography.labelLarge, fontWeight = FontWeight.Black)
        }
        Text("StreamDek ${release.versionName}", fontWeight = FontWeight.Black)
      }
    },
    text = {
      Column(modifier = Modifier.heightIn(max = 420.dp).verticalScroll(rememberScrollState()), verticalArrangement = Arrangement.spacedBy(14.dp)) {
        release.requiredReason?.let { Text(it, color = MaterialTheme.colorScheme.error, fontWeight = FontWeight.Bold) }
        if (release.releaseNotes.isNotBlank()) {
          Text("What is new", fontWeight = FontWeight.Black)
          // Authored as Markdown, so shown as Markdown -- see MarkdownText. Handed to a plain Text
          // the notes arrived as their own punctuation: "## What's New" hashes and all.
          MarkdownText(release.releaseNotes, bodyAlpha = 0.78f)
        }
        uiState.updateProgress?.let { progress ->
          Column(verticalArrangement = Arrangement.spacedBy(8.dp)) {
            Text("${(progress.coerceIn(0f, 1f) * 100).toInt()}% downloaded", color = MaterialTheme.colorScheme.primary, fontWeight = FontWeight.Bold)
            LinearProgressIndicator(
              progress = { progress },
              modifier = Modifier.fillMaxWidth().height(7.dp).clip(StreamDekRadius.pill),
              color = MaterialTheme.colorScheme.primary,
              trackColor = MaterialTheme.colorScheme.primary.copy(alpha = 0.16f),
            )
          }
        }
        uiState.updateStatusMessage?.let { Text(it, color = MaterialTheme.colorScheme.primary) }
        uiState.updateErrorMessage?.let { Text(it, color = MaterialTheme.colorScheme.error) }
      }
    },
    confirmButton = {
      Button(onClick = onUpdate, enabled = !uiState.updateDownloading, colors = ButtonDefaults.buttonColors(containerColor = MaterialTheme.colorScheme.primary, contentColor = MaterialTheme.colorScheme.onPrimary)) {
        if (uiState.updateDownloading) CircularProgressIndicator(modifier = Modifier.size(20.dp), strokeWidth = 2.dp, color = MaterialTheme.colorScheme.onPrimary)
        else Text("Update Now", fontWeight = FontWeight.Black)
      }
    },
    dismissButton = {
      if (!mandatory) TextButton(onClick = onDismiss, enabled = !uiState.updateDownloading) { Text("Later") }
    },
    containerColor = MaterialTheme.colorScheme.surface,
  )
}

private fun TraktItem.toMediaItem(): MediaItem {
  val isSeries = normalizedMediaType(type) == "tv"
  return MediaItem(
  id = tmdbId?.toString() ?: id,
  type = type,
  title = title,
  year = year,
  poster = poster,
  backdrop = backdrop,
  rating = rating,
  description = description.orEmpty(),
  progress = progress,
  cardSubtitle = if (isSeries && seasonNumber != null && episodeNumber != null) "S$seasonNumber E$episodeNumber" else null,
  resumeSeasonNumber = seasonNumber.takeIf { isSeries },
  resumeEpisodeNumber = episodeNumber.takeIf { isSeries },
  addedAt = addedAt,
  updatedAt = updatedAt,
  )
}

private fun combinedContinueWatching(uiState: AppUiState): List<MediaItem> {
  val providerItems = uiState.traktContinueWatching.filterNot { provider ->
    uiState.playbackProgressRecords.any { record -> progressRecordSuppressesProviderItem(record, provider.toMediaItem()) }
  }.map(TraktItem::toMediaItem)
  return mergeContinueWatchingItems(providerItems, uiState.localContinueWatching)
}

private fun continueWatchingTitleKey(item: MediaItem): String =
  "${normalizedMediaType(item.type)}:${item.id}"

private fun continueWatchingItemKey(item: MediaItem): String = buildString {
  append(continueWatchingTitleKey(item))
  if (normalizedMediaType(item.type) == "tv" && item.resumeSeasonNumber != null && item.resumeEpisodeNumber != null) {
    append(":s${item.resumeSeasonNumber}:e${item.resumeEpisodeNumber}")
  }
}

/**
 * Combines provider and device resume rows without inventing a second, title-only series card.
 * Episode identity is deliberately part of the key: two episodes can both be in progress, while
 * `tv`, `series`, and `show` are aliases for the same canonical title.
 */
internal fun mergeContinueWatchingItems(providerItems: List<MediaItem>, localItems: List<MediaItem>): List<MediaItem> {
  val merged = linkedMapOf<String, MediaItem>()
  providerItems.forEach { item -> merged[continueWatchingItemKey(item)] = item }
  localItems.forEach { item ->
    val key = continueWatchingItemKey(item)
    val existing = merged[key]
    merged[key] = if (existing == null) item else item.copy(
      title = item.title.ifBlank { existing.title },
      year = item.year ?: existing.year,
      poster = item.poster ?: existing.poster,
      backdrop = item.backdrop ?: existing.backdrop,
      rating = item.rating ?: existing.rating,
      description = item.description.ifBlank { existing.description },
      progress = item.progress ?: existing.progress,
      cardSubtitle = item.cardSubtitle ?: existing.cardSubtitle,
      updatedAt = item.updatedAt ?: existing.updatedAt,
    )
  }
  val episodeSpecificTitles = merged.values.asSequence()
    .filter { normalizedMediaType(it.type) == "tv" && it.resumeSeasonNumber != null && it.resumeEpisodeNumber != null }
    .map(::continueWatchingTitleKey)
    .toSet()
  return merged.values
    .filterNot { item ->
      normalizedMediaType(item.type) == "tv" &&
        item.resumeSeasonNumber == null && item.resumeEpisodeNumber == null &&
        continueWatchingTitleKey(item) in episodeSpecificTitles
    }
    .sortedWith(compareByDescending<MediaItem> { it.updatedAt ?: 0L }.thenByDescending { it.progress ?: 0.0 })
}

/**
 * A provider resume row cannot override an explicit completion or dismissal from SyncDek.
 *
 * The identity comparison used to be `record.entityId != item.id` — raw string equality between two
 * sources that spell the same title differently. A removal recorded against `tt1160419` therefore
 * did not suppress the provider row that came back as `438631`, and the title reappeared on the
 * next refresh. `mediaIdentityOf` is the same rule the server applies before it answers, so this
 * only has to hold the line between an optimistic removal and the next fetch.
 */
internal fun progressRecordSuppressesProviderItem(record: PlaybackProgressRecord, item: MediaItem): Boolean {
  if (!record.completed && !record.dismissed) return false
  val recordIdentity = mediaIdentityOf(record.entityType, record.entityId, record.tmdbId, record.imdbId)
  if (!sameMediaIdentity(recordIdentity, mediaIdentityOf(item.type, item.id))) return false
  return removalCoversEpisode(
    record.seasonNumber,
    record.episodeNumber,
    item.resumeSeasonNumber,
    item.resumeEpisodeNumber,
  )
}

internal fun isSeriesType(type: String): Boolean = type == "tv" || type == "series" || type == "show"
private fun homeHeroMediaKey(item: MediaItem): String = "${if (isSeriesType(item.type)) "tv" else item.type}:${item.id}"

/**
 * Stable identity for cards that can represent a specific episode of a series.
 *
 * Most catalogue cards identify a title, so type + id is sufficient. New Episodes deliberately
 * allows more than one card for the same series, however, and those cards must remain distinct in
 * lazy lists and in the View All page.
 */
internal fun mediaCollectionKey(item: MediaItem): String = buildString {
  append(item.type)
  append('-')
  append(item.id)
  if (item.resumeSeasonNumber != null || item.resumeEpisodeNumber != null) {
    append("-s")
    append(item.resumeSeasonNumber ?: "unknown")
    append("-e")
    append(item.resumeEpisodeNumber ?: "unknown")
  }
}

/**
 * The TMDB ratings resolved for add-on catalog cards, folded back into the items they belong to.
 *
 * Ratings arrive after the row does — they are looked up per card once the row is on screen — so
 * they are stitched on at the point of display rather than stored on the section.
 */
private fun List<MediaItem>.withAddonRatings(uiState: AppUiState): List<MediaItem> {
  if (!uiState.ratingsEnabled || uiState.addonCatalogRatings.isEmpty()) return this
  return map { item ->
    if (item.rating != null) item else uiState.addonCatalogRatings[homeHeroMediaKey(item)]?.let { item.copy(rating = it) } ?: item
  }
}

/**
 * What a Home row shows of a section.
 *
 * Only add-on sections are trimmed, and only because they are now held complete: a built-in row
 * arrives from the backend already the length it is meant to be, and shortening one here would
 * change a row that has never been wrong.
 */
private fun MediaSection.homePreviewItems(): List<MediaItem> =
  if (isBuiltinHomeCatalog(id)) items else items.take(HOME_ROW_PREVIEW_LIMIT)

/**
 * Everything the add-on catalog behind a Home row returned, not just the row's preview.
 *
 * Home rows carry [HOME_ROW_PREVIEW_LIMIT] items; the section they came from holds the full
 * response. Opening "View All" on the preview alone left the rest recoverable only by asking the
 * add-on again with a `skip` offset, which an add-on that answers with its whole catalog every
 * time (TvVoo and live TV add-ons generally) simply ignores — so the page stayed at twenty.
 */
private fun fullSectionRow(uiState: AppUiState, row: HomeRow): HomeRow {
  val section = uiState.homeSections.firstOrNull { it.id == row.id } ?: return row
  if (section.items.size <= row.items.size) return row
  return row.copy(items = section.items.withAddonRatings(uiState))
}

private fun mixedHeroItems(sections: List<MediaSection>, continueWatching: List<MediaItem>, watchlist: List<MediaItem>): List<MediaItem> {
  fun eligibleItems(items: List<MediaItem>): List<MediaItem> = items.filter { item ->
    (item.type.equals("movie", true) || isSeriesType(item.type)) && !item.isLiveCatalogItem()
  }
  fun eligibleSection(section: MediaSection): Boolean {
    val identity = "${section.id} ${section.title}".lowercase()
    return listOf("streaming_network", "streaming network", "live tv", "live_tv", "live-tv", "iptv", "channel").none { it in identity }
  }
  fun section(id: String): List<MediaItem> = sections.firstOrNull { it.id == id && eligibleSection(it) }
    ?.items
    ?.let(::eligibleItems)
    .orEmpty()
  val preferredIds = listOf(
    section("new_movies"),
    section("new_series"),
    section("trending_movies"),
    section("trending_series"),
    // What is in cinemas right now is the most current thing the catalog knows about, and it is
    // the one bucket here that is not already the opening rows of the home screen.
    section("in_theatres"),
    eligibleItems(continueWatching),
    eligibleItems(watchlist),
  )
  val preferredSectionIds = setOf("new_movies", "new_series", "trending_movies", "trending_series", "in_theatres")
  // Providers do not share one fixed catalog vocabulary. Once the familiar categories have been
  // tried, every other non-empty provider section is a valid graceful fallback.
  val buckets = preferredIds + sections
    .filter { it.id !in preferredSectionIds && eligibleSection(it) }
    .map { eligibleItems(it.items) }
  val selected = mutableListOf<MediaItem>()
  val seen = mutableSetOf<String>()
  var position = 0
  while (selected.size < 12 && buckets.any { position < it.size }) {
    buckets.forEach { bucket ->
      val item = bucket.getOrNull(position) ?: return@forEach
      if (seen.add("${item.type}-${item.id}")) selected += item
      if (selected.size == 12) return selected
    }
    position += 1
  }
  return selected
}

@OptIn(ExperimentalMaterial3Api::class)
@Composable
private fun HomeTab(uiState: AppUiState, scrollToTopSignal: Int, onReload: () -> Unit, onOpen: (MediaItem) -> Unit, onPlayContinueWatching: (MediaItem) -> Unit, onViewAll: (HomeRow) -> Unit, onToggleWatchlist: (MediaItem) -> Unit, onMarkWatched: (MediaItem) -> Unit, onMarkEarlierEpisodesWatched: (MediaItem) -> Unit, onRestartFromBeginning: (MediaItem) -> Unit, onRemoveFromContinueWatching: (MediaItem) -> Unit = {}, onResolveHeroTitleLogos: (List<MediaItem>) -> Unit, onResolveAddonRatings: (List<MediaItem>) -> Unit = {}, onToggleFavourite: (MediaItem) -> Unit = {}, onEnableAddon: (InstalledAddon) -> Unit = {}, handoffDevices: List<LinkedTvDevice> = emptyList(), onRefreshHandoffDevices: () -> Unit = {}, onHandoffLive: suspend (MediaItem, LinkedTvDevice) -> Result<PlaybackHandoffReceipt> = { _, _ -> Result.failure(IllegalStateException("Handoff is unavailable.")) }, onHandoffContinueWatching: suspend (MediaItem, LinkedTvDevice) -> Result<PlaybackHandoffReceipt> = { _, _ -> Result.failure(IllegalStateException("Handoff is unavailable.")) }) {
  if (uiState.homeLoading && uiState.homeSections.isEmpty()) {
    SplashScene()
    return
  }

  val continueWatching = remember(uiState.traktContinueWatching, uiState.localContinueWatching) { combinedContinueWatching(uiState) }
  val rawHeroItems = remember(uiState.allHomeSections, uiState.homeSections, continueWatching, uiState.mergedWatchlist) {
    mixedHeroItems(uiState.allHomeSections.ifEmpty { uiState.homeSections }, continueWatching, uiState.mergedWatchlist)
  }
  LaunchedEffect(rawHeroItems) { onResolveHeroTitleLogos(rawHeroItems) }
  LaunchedEffect(uiState.homeSections, uiState.ratingsEnabled, uiState.addonCatalogRatings.size) {
    // Only what a Home row actually shows: a section now holds an add-on's whole catalog, and
    // looking up a TMDB rating for every one of several hundred cards nobody has scrolled to
    // would be a lot of requests for nothing.
    if (uiState.ratingsEnabled) onResolveAddonRatings(uiState.homeSections.flatMap { it.homePreviewItems() })
  }
  val heroItems = remember(rawHeroItems, uiState.homeHeroTitleLogos) {
    rawHeroItems.map { item ->
      val resolvedLogo = uiState.homeHeroTitleLogos[homeHeroMediaKey(item)]
      if (item.titleLogo.isNullOrBlank() && !resolvedLogo.isNullOrBlank()) item.copy(titleLogo = resolvedLogo) else item
    }
  }
  val pagerState = rememberPagerState(pageCount = { heroItems.size })
  val listState = rememberLazyListState()
  val heroAtTop by remember(listState) {
    derivedStateOf {
      listState.firstVisibleItemIndex == 0 && listState.firstVisibleItemScrollOffset == 0
    }
  }

  LaunchedEffect(heroItems.size, pagerState.settledPage, heroAtTop) {
    if (heroItems.size <= 1) return@LaunchedEffect
    if (!heroAtTop) {
      // LazyColumn can dispose the HorizontalPager while an automatic or dot-selected animation is
      // between pages. PagerState survives that disposal, including its fractional offset, which
      // used to restore as two half-width backdrops when the viewer returned to the top. Queue a
      // synchronous snap for the pager's next measure so an off-screen interruption can never be
      // preserved as a visual state.
      pagerState.requestScrollToPage(pagerState.currentPage.coerceIn(heroItems.indices))
      return@LaunchedEffect
    }
    delay(5500)
    if (!heroAtTop) return@LaunchedEffect
    val nextPage = (pagerState.settledPage + 1) % heroItems.size
    pagerState.animateScrollToPage(nextPage)
  }

  val recommendations = remember(uiState.traktRecommendations) {
    uiState.traktRecommendations.map {
      MediaItem(
        id = it.tmdbId?.toString() ?: it.id,
        type = it.type,
        title = it.title,
        year = it.year,
        poster = it.poster,
        backdrop = it.backdrop,
        rating = it.rating,
        description = it.description.orEmpty(),
        progress = it.progress,
      )
    }
  }
  val trending = remember(uiState.traktTrending) {
    uiState.traktTrending.map {
      MediaItem(
        id = it.tmdbId?.toString() ?: it.id,
        type = it.type,
        title = it.title,
        year = it.year,
        poster = it.poster,
        backdrop = it.backdrop,
        rating = it.rating,
        description = it.description.orEmpty(),
        progress = it.progress,
      )
    }
  }
  val rows = remember(uiState.homeSections, continueWatching, recommendations, trending, uiState.mergedWatchlist, uiState.favouriteChannels, uiState.m3uChannels, uiState.m3uVodItems, uiState.addonCatalogRatings, uiState.ratingsEnabled, uiState.newEpisodeItems, uiState.defaultAppCatalogsEnabled, uiState.homeCatalogRows) {
    buildList {
      if (continueWatching.isNotEmpty()) add(HomeRow("continue", "Continue Watching", continueWatching))
      // Straight after Continue Watching, as on the television: both answer "what should I put on
      // now", and a feed of what has just aired is worth less further down the page.
      if (uiState.newEpisodeItems.isNotEmpty()) add(HomeRow("new-episodes", "New Episodes", uiState.newEpisodeItems))
      if (uiState.favouriteChannels.isNotEmpty()) add(HomeRow("favourites", "Live Favourites", uiState.favouriteChannels))
      // Home only needs a small preview. View All receives the complete list separately, which
      // keeps composition and card clicks bounded even for very large IPTV playlists.
      if (uiState.m3uChannels.isNotEmpty()) add(HomeRow("m3u_playlists_live", "Playlist Live TV", uiState.m3uChannels.take(30)))
      if (uiState.m3uVodItems.isNotEmpty()) add(HomeRow("m3u_playlists_vod", "Playlist VOD", uiState.m3uVodItems.take(30)))
      // Catalogue rows and StreamDek's own assembled rows, in the one order the viewer arranged.
      //
      // Both come out of the saved layout, so the walk is over that rather than over the fetched
      // sections: Recommended, Trending On Trakt and Watchlist have no section behind them -- Home
      // builds their contents itself -- and appending them afterwards, as this used to, meant the
      // drag handles in settings moved them somewhere the screen ignored.
      //
      // Continue Watching, New Episodes, the live favourites and the playlist rows above are not
      // in the layout at all: they are the viewer's own content and their own configured sources,
      // so they are neither ordered here nor gated by StreamDek Home Rows.
      val sectionsById = uiState.homeSections.associateBy { it.id }
      val assembled = mapOf(
        "recommended" to { HomeRow("recommended", "Recommended For You", recommendations) },
        "trending" to { HomeRow("trending", "Trending On Trakt", trending) },
        "watchlist" to { HomeRow("watchlist", "Watchlist", uiState.mergedWatchlist) },
      )
      // Before the first merge the layout is empty, and falling through to it would leave Home
      // blank; the fetched order is the right answer until the viewer has arranged one.
      val layout = uiState.homeCatalogRows.ifEmpty {
        uiState.homeSections.map { HomeCatalogRow(it.id, it.title, "", builtin = true) }
      }
      layout.forEach { row ->
        if (!row.enabled) return@forEach
        if (row.builtin && !uiState.defaultAppCatalogsEnabled) return@forEach
        val built = assembled[row.id]?.invoke()
          ?: sectionsById[row.id]?.let { section ->
            // An add-on catalog is held complete rather than trimmed to the preview length, so the
            // trim happens here: Home shows the opening titles, and "View All" is handed the whole
            // section (see onViewAll).
            HomeRow(section.id, section.title, section.homePreviewItems().withAddonRatings(uiState))
          }
          ?: return@forEach
        if (built.items.isNotEmpty()) add(built)
      }
    }.map { row -> row.copy(items = row.items.distinctBy(::mediaCollectionKey)) }
  }
  val heroBackdrop = heroItems.getOrNull(pagerState.currentPage.coerceIn(0, (heroItems.size - 1).coerceAtLeast(0)))
  // Hoisted out of the background layer below so it is remembered for as long as Home is, rather
  // than for as long as the spotlight happens to be on screen. Scrolling down past the hero and
  // back up again must not re-sample the palette or replay its fade.
  val heroAmbient = rememberHomeHeroAmbientColor(
    artworkUrl = heroBackdrop?.backdrop ?: heroBackdrop?.poster,
    enabled = heroBackdrop != null,
  )

  // Track the last handled signal so re-entering composition (e.g. returning from a
  // detail page with restored scroll state) doesn't replay an old scroll-to-top.
  var handledScrollToTopSignal by rememberSaveable { mutableIntStateOf(scrollToTopSignal) }
  LaunchedEffect(scrollToTopSignal) {
    if (scrollToTopSignal > handledScrollToTopSignal) {
      handledScrollToTopSignal = scrollToTopSignal
      listState.animateScrollToItem(0)
    }
  }

  // Home is the only screen that changes with the density, so the metrics are provided here rather
  // than at the root: the media cards below are shared with Browse, Search and the View All pages,
  // and those keep the Relaxed default whatever Home is set to.
  val homeLayout = remember(uiState.homeDensity) { HomeLayoutMetrics.forDensity(uiState.homeDensity) }
  CompositionLocalProvider(LocalHomeLayout provides homeLayout) {
  PullToRefreshBox(isRefreshing = uiState.homeLoading, onRefresh = onReload, modifier = Modifier.fillMaxSize()) {
    Box(modifier = Modifier.fillMaxSize().background(MaterialTheme.colorScheme.background)) {
    val lightMode = MaterialTheme.colorScheme.background.luminance() > 0.5f
    if (uiState.homeBackgroundMode == BackgroundMode.Cinematic && heroBackdrop != null) {
      // Crossfaded rather than swapped. A bare AsyncImage restarts when its model changes, so
      // turning the carousel replaced the whole page's backdrop in a single frame — the abrupt
      // background change that made the join below the hero so obvious. Both copies are composed
      // through the turn, and the incoming one is almost always a memory-cache hit because the
      // spotlight above is drawing the same artwork at the same size.
      //
      // The duration is the one the palette and the ambient wash use, so the image, the colour and
      // the gradient are a single transition rather than three that happen to overlap.
      Crossfade(
        targetState = heroBackdrop.backdrop ?: heroBackdrop.poster,
        animationSpec = StreamDekMotion.crossfadeSpec(MotionDuration.crossfade * 3),
        modifier = Modifier.fillMaxSize(),
        label = "home_ambient_backdrop",
      ) { backdropUrl ->
        AsyncImage(
          model = backdropUrl,
          contentDescription = null,
          modifier = Modifier
            .fillMaxSize()
            .blur(38.dp)
            .graphicsLayer { alpha = if (lightMode) 0.38f else 0.30f },
          contentScale = ContentScale.Crop,
        )
      }
      val tint = uiState.ambientTintPercent
      Box(modifier = Modifier.fillMaxSize().background(if (lightMode) MaterialTheme.colorScheme.background.copy(alpha = ambientTintAlpha(0.48f, tint)) else Color.Black.copy(alpha = ambientTintAlpha(0.36f, tint))))
      Box(
        modifier = Modifier.fillMaxSize().background(
          Brush.verticalGradient(
            colorStops = arrayOf(
              0.00f to Color.Transparent,
              0.42f to (if (lightMode) MaterialTheme.colorScheme.background.copy(alpha = ambientTintAlpha(0.10f, tint)) else Color.Black.copy(alpha = ambientTintAlpha(0.36f, tint))),
              0.72f to MaterialTheme.colorScheme.background.copy(alpha = ambientTintAlpha(if (lightMode) 0.55f else 0.54f, tint)),
              1.00f to MaterialTheme.colorScheme.background.copy(alpha = ambientTintAlpha(1f, tint).coerceAtLeast(0.62f)),
            ),
          ),
        ),
      )
    }

    // The join between the spotlight and the rows, in both background modes. In Cinematic it tints
    // a blurred backdrop that already spans the whole page; in Normal it is the entire mechanism,
    // since there is otherwise nothing but flat page colour under the rows. Either way it is drawn
    // here — behind the list, in the page's own coordinate space — because the thing it has to
    // cross is the edge of the list's first item.
    if (heroItems.isNotEmpty()) {
      HomeHeroAmbientBleed(
        ambient = heroAmbient,
        heroHeight = homeHeroHeight(),
        lightMode = lightMode,
        tintPercent = uiState.ambientTintPercent,
        // The spotlight item's own offset, not the raw scroll position: it already accounts for
        // content padding and for the item having left the viewport, so the wash tracks the edge it
        // is blending exactly and needs no arithmetic of its own. Read in the draw phase, so a
        // scroll moves it without recomposing anything.
        heroTopOffset = {
          listState.layoutInfo.visibleItemsInfo.firstOrNull { it.index == 0 }?.offset
            ?: HomeHeroBleedParkedOffset
        },
      )
    }

    LazyColumn(
      state = listState,
      modifier = Modifier.fillMaxSize(),
      contentPadding = PaddingValues(bottom = 104.dp),
      // The list's own spacing is the hero-to-first-row gap when there is a spotlight, and the
      // full row gap when there is not; the spacer below makes up the difference between rows. Two
      // numbers rather than one because the spotlight sits closer to what follows it than two rows
      // of cards do to each other.
      verticalArrangement = Arrangement.spacedBy(if (heroItems.isNotEmpty()) homeLayout.heroToRowGap else homeLayout.rowGap),
    ) {
      if (heroItems.isNotEmpty()) {
        item {
          HomeHeroCarousel(
            items = heroItems,
            pagerState = pagerState,
            onOpen = onOpen,
            showSynopsis = uiState.showHeroSynopsis,
            scrollOffset = { if (listState.firstVisibleItemIndex == 0) listState.firstVisibleItemScrollOffset else 0 },
            modifier = Modifier.fillMaxWidth(),
          )
        }
      }
      itemsIndexed(rows, key = { _, row -> row.id }) { index, row ->
        Column {
          if (heroItems.isNotEmpty() && index > 0) Spacer(modifier = Modifier.height(homeLayout.rowGap - homeLayout.heroToRowGap))
          HomeStrip(rowId = row.id, title = row.title, items = row.items, continueWatchingStyle = uiState.continueWatchingStyle, networkCardStyle = uiState.networkCardStyle, liveLandscapeCards = uiState.liveLandscapeCards, newEpisodesLandscape = uiState.newEpisodesLandscape, watchlistItems = uiState.mergedWatchlist, favouriteItems = uiState.favouriteChannels, addons = uiState.addons, handoffDevices = handoffDevices, onRefreshHandoffDevices = onRefreshHandoffDevices, onHandoffLive = onHandoffLive, onHandoffContinueWatching = onHandoffContinueWatching, onOpen = onOpen, onViewAll = { onViewAll(row) }, onToggleWatchlist = onToggleWatchlist, onToggleFavourite = onToggleFavourite, onEnableAddon = onEnableAddon, onMarkWatched = onMarkWatched, onMarkEarlierEpisodesWatched = onMarkEarlierEpisodesWatched, onRestartFromBeginning = onRestartFromBeginning, onRemoveFromContinueWatching = onRemoveFromContinueWatching, onPlayContinueWatching = onPlayContinueWatching)
        }
      }
    }
  }
  }
  }
}

/**
 * How tall the spotlight is.
 *
 * A fixed 640dp is most of a phone's screen and all of a landscape tablet's, which leaves the
 * spotlight filling the window with nothing beneath it — the rows that make Home worth opening end
 * up entirely below the fold. Capping it against the window's own height keeps the next row
 * showing, which is what invites a scroll.
 *
 * Shared with [HomeHeroAmbientBleed], which has to know exactly where the hero stops in order to
 * carry its colour across that line.
 */
@Composable
private fun homeHeroHeight(): Dp = minOf(640.dp, LocalWindowSize.current.heightDp * 0.72f)

/** The strip the carousel dots sit in, below the artwork and inside the same list item. */
private val HomeHeroDotsLaneHeight = 26.dp

/**
 * Where the ambient wash sits when the spotlight is not on screen at all.
 *
 * Far enough above the viewport that nothing of it is drawn. Parking it rather than removing it
 * from composition means scrolling back to the top brings it straight back, with no re-sample and
 * no second fade-in.
 */
private const val HomeHeroBleedParkedOffset = -100_000

/**
 * The hero's own colour, carried across the line where the hero stops.
 *
 * # The seam this exists to remove
 *
 * The spotlight is the first item of a `LazyColumn`, so it has a hard bottom edge at a known pixel
 * row, and everything below it is drawn on the page background. The hero used to end by painting a
 * gradient *to* that background - opaque by its last pixel - which meant the bottom of the hero was
 * flat page colour while the strip immediately beneath it showed the Cinematic ambient wash. Two
 * different colours meeting at a straight horizontal line: the page read as two stacked panels.
 *
 * The fix is in two halves and neither of them is a rectangle laid over the join:
 *
 * 1. The artwork is **alpha-masked** out over the bottom of the hero rather than covered up (see
 *    the mask in [HomeHeroCarousel]), so whatever is behind it - page background, or the blurred
 *    Cinematic backdrop - is the same surface above the line and below it. A boundary between two
 *    parts of one continuous painted surface cannot be seen.
 * 2. This layer adds the hero's own colour on top of that surface, as one gradient whose peak
 *    straddles the boundary and which is still changing gently as it crosses. It is drawn *behind*
 *    the list, in the page's coordinate space rather than the item's, so it does not care where the
 *    item ends.
 *
 * Multi-stop on purpose: a two-colour ramp of this length puts a visible Mach band across the
 * middle of it, which would simply move the seam rather than remove it.
 *
 * Decorative only - no background, no pointer input, nothing measured against it - so it cannot
 * intercept a touch or change how the list scrolls. The translation is read in the draw phase, so
 * scrolling moves it without recomposing anything.
 */
@Composable
private fun HomeHeroAmbientBleed(
  ambient: Color?,
  heroHeight: Dp,
  lightMode: Boolean,
  tintPercent: Int,
  /** Where the spotlight item's top edge currently is, so the wash stays glued to it. */
  heroTopOffset: () -> Int,
  modifier: Modifier = Modifier,
) {
  if (ambient == null) return
  val laneHeight = HomeHeroDotsLaneHeight
  // How far past the dots lane the colour keeps going before it is gone. Long enough that the top
  // of the first row is still standing on it, which is what stops the row reading as a new panel.
  val tailHeight = 260.dp
  // Light themes take the wash at roughly two-thirds strength: the same alpha over a pale page is
  // a much larger perceptual change than it is over a dark one, and it turns readable text grey.
  val strength = if (lightMode) 0.62f else 1f
  Box(
    modifier = modifier
      .fillMaxSize()
      .graphicsLayer { translationY = heroTopOffset().toFloat() }
      .drawBehind {
        val hero = heroHeight.toPx()
        val lane = laneHeight.toPx()
        val end = hero + lane + tailHeight.toPx()
        if (end <= 0f) return@drawBehind
        fun at(y: Float) = (y / end).coerceIn(0f, 1f)
        fun wash(alpha: Float) = ambient.copy(alpha = ambientTintAlpha(alpha * strength, tintPercent))
        drawRect(
          brush = Brush.verticalGradient(
            colorStops = arrayOf(
              // Nothing at all for the top half: that is artwork at full opacity, and tinting it
              // would be colouring the image rather than blending away from it.
              0f to Color.Transparent,
              at(hero * 0.52f) to Color.Transparent,
              at(hero * 0.72f) to wash(0.20f),
              at(hero * 0.88f) to wash(0.32f),
              // The peak sits *on* the boundary and is barely moving as it crosses it, which is
              // the whole trick: there is no rate of change for the eye to catch.
              at(hero) to wash(0.34f),
              at(hero + lane) to wash(0.29f),
              at(hero + lane + tailHeight.toPx() * 0.4f) to wash(0.16f),
              1f to Color.Transparent,
            ),
            startY = 0f,
            endY = end,
          ),
        )
      },
  )
}

/**
 * The spotlight's palette, held across a carousel turn.
 *
 * Unlike [rememberDominantBackgroundColor], which forgets its answer the moment the artwork changes,
 * this keeps the outgoing hero's colour until the incoming one has actually been sampled. On a page
 * whose whole background is derived from that colour, dropping to the theme default for the second
 * or two the sample takes is a flash of grey between two palettes - which is exactly what the
 * carousel must not do. `DominantColor` caches per image, so a hero that has been shown before
 * resolves without any work at all.
 */
@Composable
private fun rememberHomeHeroAmbientColor(artworkUrl: String?, enabled: Boolean): Color? {
  val context = LocalContext.current
  val themeBackground = MaterialTheme.colorScheme.background
  val lightTheme = themeBackground.luminance() > 0.5f
  // Not keyed on the artwork: that is the point.
  var settled by remember { mutableStateOf<Color?>(null) }
  LaunchedEffect(artworkUrl, enabled, lightTheme) {
    if (!enabled) {
      settled = null
      return@LaunchedEffect
    }
    DominantColor.forArtwork(context, artworkUrl, lightTheme)?.let { settled = it }
  }
  val motion = LocalMotionSettings.current
  val animated by animateColorAsState(
    targetValue = settled ?: themeBackground,
    // The artwork, the palette and this wash all move together on one duration, so a carousel turn
    // is one transition rather than three that happen to overlap.
    animationSpec = tween(durationMillis = motion.crossfade(MotionDuration.crossfade * 3), easing = FastOutSlowInEasing),
    label = "home_hero_ambient",
  )
  return if (settled == null) null else animated
}

private fun homeHeroPageOffset(
  pagerState: androidx.compose.foundation.pager.PagerState,
  page: Int,
): Float {
  val fraction = pagerState.currentPageOffsetFraction
  // A freshly measured pager can briefly report a stale/NaN fraction. The hero layer
  // multiplies this by 22x the hero width, so even a tiny residual would push the
  // image clean off screen — treat anything near zero as settled.
  val safeFraction = if (fraction.isNaN() || kotlin.math.abs(fraction) < 0.001f) 0f else fraction
  return (pagerState.currentPage - page) + safeFraction
}

private fun homeHeroPageVisibility(
  pagerState: androidx.compose.foundation.pager.PagerState,
  page: Int,
): Float = (1f - kotlin.math.abs(homeHeroPageOffset(pagerState, page))).coerceIn(0f, 1f)

@Composable
private fun HeroTitleArtwork(
  url: String,
  title: String,
  modifier: Modifier,
  alignment: Alignment = Alignment.Center,
  onError: (() -> Unit)? = null,
) {
  val lightMode = MaterialTheme.colorScheme.background.luminance() > 0.5f
  Box(modifier = modifier, contentAlignment = alignment) {
    if (lightMode) {
      AsyncImage(
        model = url,
        contentDescription = null,
        modifier = Modifier.fillMaxSize().offset(y = 1.dp).blur(3.dp).graphicsLayer { alpha = 0.58f },
        contentScale = ContentScale.Fit,
        alignment = alignment,
        colorFilter = ColorFilter.tint(Color.Black),
      )
    }
    AsyncImage(
      model = url,
      contentDescription = title,
      modifier = Modifier.fillMaxSize(),
      contentScale = ContentScale.Fit,
      alignment = alignment,
      onError = { onError?.invoke() },
    )
  }
}

@Composable
private fun HomeHeroTitle(item: MediaItem, lightMode: Boolean) {
  var logoFailed by remember(item.id, item.titleLogo) { mutableStateOf(false) }
  val titleLogo = item.titleLogo
  if (!titleLogo.isNullOrBlank() && !logoFailed) {
    HeroTitleArtwork(
      url = titleLogo,
      title = item.title,
      modifier = Modifier.fillMaxWidth(0.74f).height(92.dp),
      onError = { logoFailed = true },
    )
  } else {
    Text(
      item.title,
      style = MaterialTheme.typography.displayMedium.copy(shadow = if (lightMode) Shadow(Color.Black.copy(alpha = 0.72f), Offset(0f, 2f), 5f) else null),
      fontWeight = FontWeight.Black,
      maxLines = 2,
      overflow = TextOverflow.Ellipsis,
      color = Color.White,
      textAlign = androidx.compose.ui.text.style.TextAlign.Center,
    )
  }
}

/**
 * The page indicator, kept in its own composable on purpose.
 *
 * Each dot's width tracks the swipe, and width is a *layout* property — so this reads the pager's
 * offset every frame and re-lays-out on every one of them. That is fine for a row of small boxes,
 * but inlined in the carousel the read belonged to the carousel's composition scope, which meant
 * the backdrops, the title block and the whole hero were recomposed and re-measured 60+ times a
 * second while dragging. Scoping the read here confines that work to the dots.
 */
@Composable
private fun HomeHeroPageDots(
  pageCount: Int,
  pagerState: androidx.compose.foundation.pager.PagerState,
  onSelect: (Int) -> Unit,
) {
  Row(horizontalArrangement = Arrangement.spacedBy(8.dp), verticalAlignment = Alignment.CenterVertically) {
    repeat(pageCount) { index ->
      val activeFraction = homeHeroPageVisibility(pagerState, index)
      Box(
        modifier = Modifier
          .clickable { onSelect(index) }
          .clip(CircleShape)
          .background(MaterialTheme.colorScheme.onBackground)
          .graphicsLayer { alpha = 0.30f + (0.62f * activeFraction) }
          .width((8f + (18f * activeFraction)).dp)
          .height(8.dp),
      )
    }
  }
}

@Composable
private fun HomeHeroCarousel(
  items: List<MediaItem>,
  pagerState: androidx.compose.foundation.pager.PagerState,
  onOpen: (MediaItem) -> Unit,
  showSynopsis: Boolean,
  scrollOffset: () -> Int,
  modifier: Modifier = Modifier,
) {
  if (items.isEmpty()) return
  val lightMode = MaterialTheme.colorScheme.background.luminance() > 0.5f
  val pagerScope = rememberCoroutineScope()
  BoxWithConstraints(
    modifier = modifier.fillMaxWidth(),
  ) {
    val currentPage = pagerState.currentPage.coerceIn(items.indices)
    val currentItem = items[currentPage]
    val heroHeight = homeHeroHeight()
    val heroDotsLaneHeight = HomeHeroDotsLaneHeight
    val heroItemSpacing = if (maxWidth < 390.dp) 4.dp else if (showSynopsis) 8.dp else 6.dp
    val heroCtaSpacing = if (maxWidth < 390.dp || !showSynopsis) 4.dp else 7.dp
    // Which pages can be on screen at all.
    //
    // This used to be rebuilt in composition from `currentPageOffsetFraction`, which changes on
    // every frame of a swipe — so the entire hero recomposed 60+ times a second while dragging.
    // Deriving the window from the settled page instead means the list, and the composition that
    // depends on it, changes once per page turn. Each layer's actual offset is read inside its
    // graphicsLayer below, which runs in the draw phase and needs no recomposition at all.
    //
    // Order is by page index and never changes. The previous version sorted by visibility, so the
    // two layers swapped slots halfway through every swipe; with no `key`, Compose reused each
    // slot's AsyncImage for a different page and Coil restarted the request — the flicker that
    // came across as jitter.
    val heroPages by remember(pagerState, items.size) {
      derivedStateOf {
        val settled = pagerState.currentPage.coerceIn(items.indices)
        listOf(settled - 1, settled, settled + 1).filter { it in items.indices }
      }
    }

    Box(modifier = Modifier.fillMaxWidth().height(heroHeight + heroDotsLaneHeight)) {
      HorizontalPager(
        state = pagerState,
        modifier = Modifier.align(Alignment.TopCenter).fillMaxWidth().height(heroHeight).graphicsLayer { alpha = 0.01f },
      ) { Box(modifier = Modifier.fillMaxSize()) }

      Box(modifier = Modifier.align(Alignment.TopCenter).fillMaxWidth().height(heroHeight).clip(RectangleShape)) {
        // The artwork stack, dissolved rather than covered.
        //
        // What used to be here was a gradient painted *over* the bottom of the hero, ending at the
        // page background at full opacity — which is what made the hero's last pixel row a
        // different colour from the first row beneath it, and hid the Cinematic ambient wash that
        // was visible on the other side of the line. Alpha-masking the stack instead means the
        // artwork thins out into whatever is already behind it, so both sides of the boundary are
        // literally the same surface and there is no edge to find. HomeHeroAmbientBleed then
        // carries the hero's colour across that surface.
        //
        // The mask carrier is deliberately a separate, *static* box: put the mask on the parallax
        // layer below and the feather would slide down the hero as the page scrolled, taking the
        // artwork's edge with it.
        Box(
          modifier = Modifier
            .fillMaxSize()
            // Required for DstIn: the mask has to be composited against this layer's own alpha
            // rather than against whatever has already been drawn underneath it.
            .graphicsLayer { compositingStrategy = CompositingStrategy.Offscreen }
            .drawWithContent {
              drawContent()
              drawRect(
                brush = Brush.verticalGradient(
                  colorStops = arrayOf(
                    // Six stops, not two. A straight ramp over this distance shows a Mach band
                    // across its middle, which would only move the seam rather than remove it.
                    0.00f to Color.Black,
                    0.56f to Color.Black,
                    0.74f to Color.Black.copy(alpha = 0.88f),
                    0.86f to Color.Black.copy(alpha = 0.54f),
                    0.95f to Color.Black.copy(alpha = 0.18f),
                    1.00f to Color.Transparent,
                  ),
                ),
                blendMode = BlendMode.DstIn,
              )
            },
        ) {
        Box(modifier = Modifier.fillMaxSize().graphicsLayer { translationY = scrollOffset().toFloat() * 0.46f }) {
          heroPages.forEach { page ->
            key(page) {
              AsyncImage(
                model = items[page].backdrop ?: items[page].poster,
                contentDescription = items[page].title,
                // One page of offset moves exactly one hero width, so the next backdrop sits flush
                // against the current one and tracks the finger. `size.width` is the layer's width
                // in pixels — the previous multiplier was built on `maxWidth.value`, which is the
                // width in *dp*, so the neighbouring image was parked roughly seven screens away
                // and only slid into view over the last tenth of the swipe. For the rest of the
                // gesture there was nothing but backdrop between the two images.
                //
                // Backdrops stay fully opaque: cross-fading two adjacent images means both are
                // semi-transparent mid-swipe, which shows the background through the seam.
                // The window always holds three pages so composition stays stable, but a page that
                // is a full width away must not be rasterised — `alpha = 0f` still draws the layer
                // and composites it, which measured as ~7ms of extra frame time from the third
                // full-screen backdrop. drawWithContent skips the draw outright, and like the
                // transform above it reads the offset in the draw phase, so nothing recomposes.
                modifier = Modifier
                  .fillMaxSize()
                  .graphicsLayer {
                    translationX = -homeHeroPageOffset(pagerState, page) * size.width
                    scaleX = 1.08f
                    scaleY = 1.08f
                  }
                  .drawWithContent {
                    if (kotlin.math.abs(homeHeroPageOffset(pagerState, page)) < 1f) drawContent()
                  },
                contentScale = ContentScale.Crop,
                alignment = Alignment.Center,
              )
            }
          }

          // What the hero's white title and metadata sit on. Inside the mask, so it thins out with
          // the artwork it is darkening instead of surviving as a band of its own — which is what
          // lets it be this strong without producing an edge.
          //
          // The light theme gets one too now, where it previously had none: white text over pale
          // artwork was already marginal, and the dissolve below leaves less image behind it.
          Box(
            modifier = Modifier
              .align(Alignment.BottomCenter)
              .fillMaxWidth()
              .height(240.dp)
              .background(
                Brush.verticalGradient(
                  colors = if (lightMode) {
                    listOf(Color.Transparent, Color.Black.copy(alpha = 0.30f), Color.Black.copy(alpha = 0.72f))
                  } else {
                    listOf(Color.Transparent, Color.Black.copy(alpha = 0.42f), Color.Black)
                  },
                ),
              ),
          )

        }
        }

        Column(
          modifier = Modifier.align(Alignment.BottomCenter).fillMaxWidth().padding(horizontal = 24.dp).padding(top = 42.dp, bottom = 8.dp),
          horizontalAlignment = Alignment.CenterHorizontally,
          verticalArrangement = Arrangement.spacedBy(heroCtaSpacing),
        ) {
          Box(modifier = Modifier.fillMaxWidth(), contentAlignment = Alignment.BottomCenter) {
            heroPages.forEach { page ->
              key(page) {
              // Same one-page-per-hero-width travel as the backdrop so the title stays locked to
              // its image, and the same draw-phase offset read so dragging never recomposes this.
              // Text keeps its cross-fade — sliding two opaque copies of the overlay past each
              // other reads as a collision rather than a transition. Only the title block lives
              // here; the shared View Details button below always follows the settled page, so an
              // off-screen neighbour never becomes a stray touch target.
              Box(
                modifier = Modifier
                  .graphicsLayer {
                    val offset = homeHeroPageOffset(pagerState, page)
                    alpha = (1f - kotlin.math.abs(offset)).coerceIn(0f, 1f)
                    translationX = -offset * size.width
                  }
                  .drawWithContent {
                    if (kotlin.math.abs(homeHeroPageOffset(pagerState, page)) < 1f) drawContent()
                  },
              ) {
              Column(
                modifier = Modifier.fillMaxWidth(),
                horizontalAlignment = Alignment.CenterHorizontally,
                verticalArrangement = Arrangement.spacedBy(heroItemSpacing),
              ) {
                HomeHeroTitle(items[page], lightMode)
                Text(
                  (listOf(if (items[page].type == "tv" || items[page].type == "series") "Series" else "Movie") + items[page].genres.take(3)).joinToString(" \u00B7 "),
                  style = MaterialTheme.typography.bodyMedium,
                  color = Color.White.copy(alpha = 0.72f),
                  fontWeight = FontWeight.Bold,
                  maxLines = 1,
                  overflow = TextOverflow.Ellipsis,
                )
                if (showSynopsis && items[page].description.isNotBlank()) {
                  Text(
                    items[page].description,
                    style = MaterialTheme.typography.bodyMedium,
                    color = Color.White.copy(alpha = 0.82f),
                    maxLines = 2,
                    overflow = TextOverflow.Ellipsis,
                    textAlign = androidx.compose.ui.text.style.TextAlign.Center,
                    modifier = Modifier.fillMaxWidth(0.88f),
                  )
                }
              }
              }
              }
            }
          }

          Button(
            onClick = { onOpen(currentItem) },
            colors = ButtonDefaults.buttonColors(containerColor = Color.White, contentColor = Color.Black),
            shape = StreamDekRadius.pill,
            modifier = Modifier.fillMaxWidth(0.68f),
          ) {
            Text("View Details", fontWeight = FontWeight.ExtraBold)
          }
        }
      }

      if (items.size > 1) {
        Box(
          modifier = Modifier
            .align(Alignment.BottomCenter)
            .fillMaxWidth()
            .height(heroDotsLaneHeight),
          contentAlignment = Alignment.BottomCenter,
        ) {
          HomeHeroPageDots(
            pageCount = items.size,
            pagerState = pagerState,
            onSelect = { index -> pagerScope.launch { pagerState.animateScrollToPage(index) } },
          )
        }
      }
    }
  }
}

@Composable
private fun NetworkBrowseScreen(network: MediaItem, headerStyle: HeaderStyle, onBack: () -> Unit, onOpen: (MediaItem) -> Unit) {
  val api = remember { StreamDekApiClient() }
  BackHandler(onBack = onBack)
  var query by rememberSaveable(network.id) { mutableStateOf("") }
  var type by rememberSaveable(network.id) { mutableStateOf("all") }
  var sort by rememberSaveable(network.id) { mutableStateOf("trending") }
  var genreId by rememberSaveable(network.id) { mutableStateOf<Int?>(null) }
  var year by rememberSaveable(network.id) { mutableStateOf<String?>(null) }
  var selectionSheet by rememberSaveable(network.id) { mutableStateOf<String?>(null) }
  var columns by rememberSaveable(network.id) { mutableStateOf(3) }
  var genres by remember(network.id) { mutableStateOf<List<DiscoverGenre>>(emptyList()) }
  var catalogItems by remember(network.id) { mutableStateOf<List<MediaItem>>(emptyList()) }
  var loading by remember(network.id) { mutableStateOf(true) }
  var page by remember(network.id) { mutableStateOf(1) }
  var totalPages by remember(network.id) { mutableStateOf(1) }
  var activeRequestToken by remember(network.id) { mutableStateOf("") }
  val listState = rememberLazyGridState()
  val years: List<String> = remember { (java.time.Year.now().value downTo 1980).map(Int::toString) }
  val scope = rememberCoroutineScope()
  val modernHeader = headerStyle == HeaderStyle.Modern
  val headerHazeState = rememberHazeState()

  fun load(targetPage: Int, append: Boolean) {
    val requestedQuery = query.trim()
    val requestToken = listOf(network.id, targetPage, type, genreId, year, sort, requestedQuery, System.nanoTime()).joinToString(":")
    activeRequestToken = requestToken
    loading = true
    scope.launch {
      val firstPage = api.fetchNetworkCatalog(network.id, targetPage, type, genreId, year, sort, "")
        .getOrElse {
          if (activeRequestToken == requestToken) {
            if (!append) catalogItems = emptyList()
            loading = false
          }
          return@launch
        }
      if (activeRequestToken != requestToken) return@launch

      if (requestedQuery.isNotBlank() && !append) {
        val collected = firstPage.items.toMutableList()
        val lastSearchPage = minOf(firstPage.totalPages, 20)
        if (lastSearchPage > 1) {
          (2..lastSearchPage).chunked(4).forEach { pageChunk ->
            val chunkItems = coroutineScope {
              pageChunk.map { searchPage ->
                async { api.fetchNetworkCatalog(network.id, searchPage, type, genreId, year, sort, "").getOrNull()?.items.orEmpty() }
              }.awaitAll()
            }
            if (activeRequestToken != requestToken) return@launch
            chunkItems.forEach(collected::addAll)
          }
        }
        val queryTokens = requestedQuery.lowercase().split(Regex("\\s+")).filter(String::isNotBlank)
        catalogItems = collected
          .distinctBy { item -> "${item.type}:${item.id}" }
          .filter { item ->
            val searchText = listOf(item.title, item.year, item.description).joinToString(" ").lowercase()
            queryTokens.all(searchText::contains)
          }
        page = 1
        totalPages = 1
      } else {
        catalogItems = if (append) (catalogItems + firstPage.items).distinctBy { item -> "${item.type}:${item.id}" } else firstPage.items
        page = firstPage.page
        totalPages = firstPage.totalPages
      }
      if (activeRequestToken != requestToken) return@launch
      loading = false
    }
  }

  LaunchedEffect(type) {
    val genreType = if (type == "tv") "tv" else "movie"
    api.fetchDiscoverGenres(genreType).onSuccess { genres = it }
  }
  LaunchedEffect(network.id, type, sort, genreId, year, query) {
    delay(if (query.isBlank()) 0 else 350)
    load(1, false)
  }
  LaunchedEffect(listState, page, totalPages, loading, query) {
    snapshotFlow { listState.canScrollForward }.collect { canScrollForward ->
      if (query.isBlank() && !canScrollForward && !loading && page < totalPages) load(page + 1, true)
    }
  }

  val selectionOptions = remember(selectionSheet, type, sort, genreId, year, genres) {
    when (selectionSheet) {
      "type" -> listOf(
        SearchSelectionOption("All", type == "all") { type = "all"; selectionSheet = null },
        SearchSelectionOption("Movies", type == "movie") { type = "movie"; selectionSheet = null },
        SearchSelectionOption("Series", type == "tv") { type = "tv"; selectionSheet = null },
      )
      "genre" -> buildList {
        add(SearchSelectionOption("All Genres", genreId == null) { genreId = null; selectionSheet = null })
        genres.forEach { genre ->
          add(SearchSelectionOption(genre.name, genreId == genre.id) { genreId = genre.id; selectionSheet = null })
        }
      }
      "year" -> buildList {
        add(SearchSelectionOption("Any Year", year == null) { year = null; selectionSheet = null })
        years.forEach { option ->
          add(SearchSelectionOption(option, year == option) { year = option; selectionSheet = null })
        }
      }
      else -> emptyList()
    }
  }

  Box(modifier = Modifier.fillMaxSize().background(MaterialTheme.colorScheme.background)) {
    LazyVerticalGrid(
      columns = GridCells.Fixed(adaptiveMediaColumns(columns)),
      state = listState,
      modifier = Modifier.fillMaxSize().then(if (modernHeader) Modifier.hazeSource(headerHazeState) else Modifier),
      contentPadding = PaddingValues(start = 16.dp, end = 16.dp, top = if (modernHeader) 272.dp else 274.dp, bottom = 126.dp),
      horizontalArrangement = Arrangement.spacedBy(12.dp),
      verticalArrangement = Arrangement.spacedBy(18.dp),
    ) {
      when {
        loading && catalogItems.isEmpty() -> item(span = { GridItemSpan(maxLineSpan) }) {
          Box(Modifier.fillMaxWidth().height(220.dp), contentAlignment = Alignment.Center) { CircularProgressIndicator() }
        }
        catalogItems.isEmpty() -> item(span = { GridItemSpan(maxLineSpan) }) {
          LibraryEmptyState(
            icon = { Icon(Icons.Rounded.Search, null, modifier = Modifier.size(48.dp)) },
            title = "No matching titles",
            subtitle = "Try changing the search or filters.",
          )
        }
        else -> gridItems(catalogItems, key = { item -> "${item.type}:${item.id}" }) { item ->
          LibraryPosterTile(item = item, modifier = Modifier.fillMaxWidth(), showMeta = false, onClick = { onOpen(item) })
        }
      }
      if (loading && catalogItems.isNotEmpty()) {
        item(span = { GridItemSpan(maxLineSpan) }) {
          Box(Modifier.fillMaxWidth().padding(16.dp), contentAlignment = Alignment.Center) { CircularProgressIndicator(modifier = Modifier.size(24.dp)) }
        }
      }
    }

    if (modernHeader) {
      val lightHeader = MaterialTheme.colorScheme.background.luminance() > 0.5f
      Box(modifier = Modifier.align(Alignment.TopCenter).zIndex(2f).fillMaxWidth().statusBarsPadding().padding(start = 16.dp, end = 16.dp, top = 12.dp)) {
        FrostedGlassSurface(
          modifier = Modifier.fillMaxWidth().height(204.dp),
          shape = StreamDekRadius.sheetShape,
          hazeStateOverride = headerHazeState,
          blurRadius = 68f,
          contentPadding = PaddingValues(horizontal = 16.dp, vertical = 12.dp),
          tintAlpha = if (lightHeader) 0.14f else 0.06f,
          borderAlpha = if (lightHeader) 0.10f else 0f,
          baseAlpha = if (lightHeader) 0.28f else 0.08f,
          fillColorOverride = if (lightHeader) null else Color.White,
          showEdgeGradient = false,
        ) {
          NetworkCatalogHeaderContent(
            network = network,
            query = query,
            onQueryChange = { query = it },
            columns = columns,
            onToggleColumns = { columns = if (columns == 3) 2 else 3 },
            type = type,
            genres = genres,
            genreId = genreId,
            year = year,
            onOpenFilter = { selectionSheet = it },
          )
        }
      }
    } else {
      NetworkCatalogHeaderContent(
        network = network,
        query = query,
        onQueryChange = { query = it },
        columns = columns,
        onToggleColumns = { columns = if (columns == 3) 2 else 3 },
        type = type,
        genres = genres,
        genreId = genreId,
        year = year,
        onOpenFilter = { selectionSheet = it },
        modifier = Modifier.align(Alignment.TopCenter).zIndex(2f).fillMaxWidth().background(MaterialTheme.colorScheme.background.copy(alpha = 0.98f)).statusBarsPadding().padding(horizontal = 16.dp, vertical = 12.dp),
      )
    }
  }
  if (selectionSheet != null && selectionOptions.isNotEmpty()) {
    SearchSelectionDialog(
      title = when (selectionSheet) {
        "type" -> "Choose Type"
        "genre" -> "Choose Genre"
        "year" -> "Choose Year"
        else -> "Choose Filter"
      },
      options = selectionOptions,
      onDismiss = { selectionSheet = null },
    )
  }
}

@Composable
private fun NetworkCatalogHeaderContent(
  network: MediaItem,
  query: String,
  onQueryChange: (String) -> Unit,
  columns: Int,
  onToggleColumns: () -> Unit,
  type: String,
  genres: List<DiscoverGenre>,
  genreId: Int?,
  year: String?,
  onOpenFilter: (String) -> Unit,
  modifier: Modifier = Modifier,
) {
  Column(modifier = modifier.fillMaxWidth(), verticalArrangement = Arrangement.spacedBy(12.dp)) {
    Row(modifier = Modifier.fillMaxWidth(), verticalAlignment = Alignment.CenterVertically, horizontalArrangement = Arrangement.spacedBy(12.dp)) {
      Column(modifier = Modifier.weight(1f), verticalArrangement = Arrangement.spacedBy(2.dp)) {
        AdaptivePageTitle(title = networkCatalogDisplayName(network.title), maxLines = 2)
        Text("Network catalog", color = MaterialTheme.colorScheme.onBackground.copy(alpha = 0.64f), style = MaterialTheme.typography.bodyMedium, fontWeight = FontWeight.SemiBold)
      }
      GlassCircleButton(onClick = onToggleColumns) {
        Icon(if (columns == 3) Icons.Rounded.ViewAgenda else Icons.Rounded.ViewModule, contentDescription = "Change grid size", tint = MaterialTheme.colorScheme.onBackground)
      }
    }
    OutlinedTextField(
      value = query,
      onValueChange = onQueryChange,
      modifier = Modifier.fillMaxWidth(),
      placeholder = { InputGuideText("Search within this network") },
      leadingIcon = { Icon(Icons.Rounded.Search, null) },
      trailingIcon = if (query.isNotBlank()) ({ IconButton(onClick = { onQueryChange("") }) { Icon(Icons.Rounded.Close, "Clear") } }) else null,
      singleLine = true,
      shape = StreamDekRadius.cardShape,
    )
    Row(modifier = Modifier.fillMaxWidth(), horizontalArrangement = Arrangement.spacedBy(4.dp)) {
      SearchDiscoverField("Type", when (type) { "movie" -> "Movies"; "tv" -> "Series"; else -> "Type" }, Modifier.weight(1f)) { onOpenFilter("type") }
      SearchDiscoverField("Genre", genres.firstOrNull { it.id == genreId }?.name ?: "Genre", Modifier.weight(1f), enabled = genres.isNotEmpty()) { onOpenFilter("genre") }
      SearchDiscoverField("Year", year ?: "Year", Modifier.weight(1f)) { onOpenFilter("year") }
    }
  }
}
@Composable
private fun NetworkCatalogLandscapeGrid(items: List<MediaItem>, onOpen: (MediaItem) -> Unit) {
  Column(modifier = Modifier.fillMaxWidth(), verticalArrangement = Arrangement.spacedBy(12.dp)) {
    items.chunked(2).forEach { rowItems ->
      Row(modifier = Modifier.fillMaxWidth(), horizontalArrangement = Arrangement.spacedBy(12.dp)) {
        rowItems.forEach { item ->
          NetworkCatalogLandscapeCard(item = item, modifier = Modifier.weight(1f), onClick = { onOpen(item) })
        }
        if (rowItems.size == 1) Spacer(modifier = Modifier.weight(1f))
      }
    }
  }
}

@Composable
private fun NetworkCatalogLandscapeCard(item: MediaItem, modifier: Modifier = Modifier, onClick: () -> Unit) {
  Box(
    modifier = modifier
      .aspectRatio(16f / 10f)
      .clip(StreamDekRadius.cardShape)
      .background(MaterialTheme.colorScheme.surface)
      .border(1.dp, MaterialTheme.colorScheme.onBackground.copy(alpha = 0.10f), StreamDekRadius.cardShape)
      .clickable(onClick = onClick),
  ) {
    AsyncImage(
      model = item.backdrop ?: item.poster,
      contentDescription = item.title,
      modifier = Modifier.fillMaxSize(),
      contentScale = ContentScale.Crop,
    )
    Box(
      modifier = Modifier.fillMaxSize().background(
        Brush.verticalGradient(
          colorStops = arrayOf(
            0.00f to Color.Black.copy(alpha = 0.04f),
            0.48f to Color.Black.copy(alpha = 0.16f),
            1.00f to Color.Black.copy(alpha = 0.88f),
          ),
        ),
      ),
    )
    CardImdbRatingBadge(rating = item.rating, topPadding = 5.dp)
    Column(
      modifier = Modifier.align(Alignment.BottomStart).fillMaxWidth().padding(horizontal = 11.dp, vertical = 10.dp),
      verticalArrangement = Arrangement.spacedBy(2.dp),
    ) {
      Text(item.title, color = Color.White, fontSize = 12.sp, lineHeight = 15.sp, fontWeight = FontWeight.Black, maxLines = 2, overflow = TextOverflow.Ellipsis)
      Text(item.year ?: item.type.replaceFirstChar(Char::uppercase), color = Color.White.copy(alpha = 0.72f), fontSize = 10.sp, maxLines = 1)
    }
  }
}
private fun networkCatalogDisplayName(title: String): String =
  if (title.contains("Amazon", ignoreCase = true) && title.contains("Prime", ignoreCase = true)) "Amazon Prime" else title

@Composable
private fun AdaptivePageTitle(
  title: String,
  modifier: Modifier = Modifier,
  maxLines: Int = 2,
  color: Color = MaterialTheme.colorScheme.onBackground,
) {
  val adaptiveSize = when {
    title.length >= 38 -> 22.sp
    title.length >= 30 -> 24.sp
    title.length >= 22 -> 27.sp
    else -> PageTitleSize
  }
  Text(
    text = title,
    modifier = modifier,
    fontSize = adaptiveSize,
    lineHeight = (adaptiveSize.value + 4f).sp,
    fontWeight = FontWeight.ExtraBold,
    color = color,
    maxLines = maxLines,
    overflow = TextOverflow.Ellipsis,
  )
}

/**
 * Default catalog rows "View All" can page through, taken from the backend registry: everything
 * except the streaming-networks tiles, which are a fixed list of services rather than a catalog.
 */
internal fun pageableCatalogRowIds(definitions: List<CatalogDefinition>): Set<String> =
  definitions.filter { it.paginated }.mapTo(mutableSetOf()) { it.id }

// ---------------------------------------------------------------------------------------------
// Live TV / playlist categories
//
// IPTV playlists and live add-on catalogs are far too long to browse as one flat list, so the
// "View All" page groups them the way an IPTV app does: categories first, channels inside.
// Category data is used when the source publishes it (an M3U `group-title`, an add-on's meta
// genres or catalog genre), and is inferred from the channel name when it does not.
// ---------------------------------------------------------------------------------------------

/** One group on the category screen. [items] is kept so drilling in costs no extra filtering. */
internal data class BrowseCategory(val name: String, val items: List<MediaItem>)

/** Categories that are a bucket for "everything else" and so always sort last. */
private val trailingCategoryNames = setOf("General", "Other", "Uncategorized", "Undefined")

/**
 * Cleans a raw `group-title` for display. Providers write these as `US| ENTERTAINMENT`,
 * `|IN| MOVIES`, `SPORTS »`, so the leading/trailing punctuation goes, inner pipes become a
 * bullet, and shouty ALL-CAPS words are cased down. Words of three characters or fewer are left
 * alone — they are nearly always initialisms (US, UK, TV, HD, PPV) that must not become "Us".
 */
internal fun tidyCategoryLabel(raw: String): String {
  val trimmed = raw.trim().trim('|', '»', '>', '~', '-', '–', '—', '•', ':', '.', ' ')
  if (trimmed.isBlank()) return ""
  return trimmed
    .replace(Regex("\\s+"), " ")
    .replace(Regex("\\s*[|»>~]\\s*"), " • ")
    .split(' ')
    .joinToString(" ") { word ->
      if (word.length <= 3 || word.any(Char::isLowerCase)) word
      else word.lowercase().replaceFirstChar(Char::uppercaseChar)
    }
}

/**
 * The category the source itself published for this item, if any. `sourceCatalogName` only
 * counts when it differs from the add-on/playlist name — otherwise every item in a single-catalog
 * source would land in one category named after the source, which groups nothing.
 */
internal fun MediaItem.declaredCategory(): String? = listOfNotNull(
  genres.firstOrNull()?.takeIf { it.isNotBlank() },
  sourceCatalogGenre?.takeIf { it.isNotBlank() },
  sourceCatalogName?.takeIf { it.isNotBlank() && !it.equals(sourceAddonName, ignoreCase = true) },
).firstOrNull()?.let(::tidyCategoryLabel)?.takeIf { it.isNotBlank() }

// Matched against the channel name in order, so the first entry wins. Adult is deliberately
// first: those channels routinely carry "movie"/"tv" words that would otherwise capture them.
private val inferredCategoryRules: List<Pair<String, List<String>>> = listOf(
  "Adult" to listOf("xxx", "adult", "playboy", "brazzers", "18+", "erotic", "hustler", "penthouse", "porn"),
  "Sports" to listOf(
    "sport", "espn", "bein", "dazn", "nba", "nfl", "nhl", "mlb", "ufc", "wwe", "footbal", "soccer",
    "rugby", "cricket", "tennis", "golf", "motogp", "formula 1", "f1 tv", "racing", "boxing",
    "eurosport", "supersport", "premier league", "la liga", "laliga", "serie a", "bundesliga",
    "ligue 1", "sportsnet", "willow", "match tv", "fight", "wrestling", "olympic",
  ),
  "News" to listOf(
    "news", "cnn", "msnbc", "cnbc", "bloomberg", "al jazeera", "aljazeera", "euronews",
    "france 24", "newsmax", "aaj tak", "ndtv", "wion", "i24", "gb ne", "sky ne",
  ),
  "Kids" to listOf(
    "kids", "cartoon", "nick", "disney", "junior", "baby", "boomerang", "cbeebies", "toon",
    "pokemon", "peppa", "boing", "duck tv", "anime",
  ),
  "Documentary" to listOf(
    "documentar", "docu", "discovery", "history", "nat geo", "national geographic",
    "animal planet", "smithsonian", "science", "curiosity", "investigation", "crime", "viasat",
  ),
  "Movies" to listOf(
