// Country prefixes as IPTV playlists write them: "UK | BBC One", "US: ESPN", "[IN] Star Plus".
private val channelRegionNames: Map<String, String> = mapOf(
  "uk" to "United Kingdom", "gb" to "United Kingdom", "eng" to "United Kingdom",
  "us" to "United States", "usa" to "United States",
  "ca" to "Canada", "au" to "Australia", "nz" to "New Zealand", "ie" to "Ireland",
  "in" to "India", "pk" to "Pakistan", "bd" to "Bangladesh", "lk" to "Sri Lanka", "np" to "Nepal",
  "de" to "Germany", "fr" to "France", "es" to "Spain", "it" to "Italy", "pt" to "Portugal",
  "nl" to "Netherlands", "be" to "Belgium", "ch" to "Switzerland", "at" to "Austria",
  "se" to "Sweden", "no" to "Norway", "dk" to "Denmark", "fi" to "Finland", "is" to "Iceland",
  "pl" to "Poland", "cz" to "Czechia", "sk" to "Slovakia", "hu" to "Hungary", "ro" to "Romania",
  "bg" to "Bulgaria", "gr" to "Greece", "tr" to "Turkey", "ru" to "Russia", "ua" to "Ukraine",
  "rs" to "Serbia", "hr" to "Croatia", "si" to "Slovenia", "al" to "Albania", "mk" to "Macedonia",
  "br" to "Brazil", "mx" to "Mexico", "ar" to "Argentina", "cl" to "Chile", "co" to "Colombia",
  "pe" to "Peru", "latino" to "Latino",
  "ae" to "United Arab Emirates", "sa" to "Saudi Arabia", "eg" to "Egypt", "ma" to "Morocco",
  "dz" to "Algeria", "tn" to "Tunisia", "iq" to "Iraq", "ir" to "Iran", "il" to "Israel",
  "lb" to "Lebanon", "sy" to "Syria", "jo" to "Jordan", "kw" to "Kuwait", "qa" to "Qatar",
  "arab" to "Arabic",
  "ng" to "Nigeria", "gh" to "Ghana", "ke" to "Kenya", "za" to "South Africa",
  "ph" to "Philippines", "id" to "Indonesia", "my" to "Malaysia", "sg" to "Singapore",
  "th" to "Thailand", "vn" to "Vietnam",
  "jp" to "Japan", "kr" to "South Korea", "cn" to "China", "hk" to "Hong Kong", "tw" to "Taiwan",
)

// Either a bracketed prefix ("[IN] Star Plus") or one closed by a separator ("UK | BBC One").
private val channelRegionPrefixRegexes = listOf(
  Regex("^\\s*[\\[(]\\s*([\\p{L}]{2,6})\\s*[\\])]\\s*\\S"),
  Regex("^\\s*([\\p{L}]{2,6})\\s*[|:›»\\-–—]\\s*\\S"),
)

/**
 * Best guess at a category from the channel name alone, for sources that publish none. Genre
 * keywords come first because they are what a viewer is actually browsing by; a country prefix
 * is the next-best grouping and is what most raw playlists are sorted by anyway.
 */
internal fun MediaItem.inferredCategory(): String {
  val haystack = (title + " " + genres.joinToString(" ")).lowercase()
  inferredCategoryRules.firstOrNull { (_, keywords) -> keywords.any { it in haystack } }
    ?.let { return it.first }
  channelRegionPrefixRegexes
    .firstNotNullOfOrNull { regex -> regex.find(title)?.let { channelRegionNames[it.groupValues[1].lowercase()] } }
    ?.let { return it }
  return "General"
}

/**
 * Groups a live/playlist catalog into categories. Published categories are preferred, but only
 * when they actually organise the list — a playlist where only a handful of entries carry a
 * `group-title` is better served by inferring throughout than by a couple of real groups next to
 * a huge "General" pile.
 */
internal fun buildBrowseCategories(items: List<MediaItem>): List<BrowseCategory> {
  if (items.isEmpty()) return emptyList()
  // Live lists reach this from sources the playlist parser never sees, and an adult section is
  // usually labelled as one, so the group name is worth checking as well as the entries.
  @Suppress("NAME_SHADOWING") val items = items.filterNot { item ->
    AdultContentFilter.isBlockedItem(title = item.title, genres = item.genres) ||
      AdultContentFilter.isBlocked(item.sourceCatalogName) ||
      AdultContentFilter.isBlockedCategory(item.declaredCategory())
  }
  if (items.isEmpty()) return emptyList()
  val declared = items.groupBy { it.declaredCategory() }
  val declaredNames = declared.keys.filterNotNull()
  val declaredCoverage = items.size - (declared[null]?.size ?: 0)
  val useDeclared = declaredNames.size >= 2 && declaredCoverage * 5 >= items.size * 3
  val grouped = if (useDeclared) {
    items.groupBy { it.declaredCategory() ?: it.inferredCategory() }
  } else {
    items.groupBy { it.inferredCategory() }
  }
  return grouped
    .map { (name, group) -> BrowseCategory(name, group) }
    .sortedWith(
      // Alphabetical, not biggest-first. Size order reads as arbitrary to anyone scanning for a
      // known category name - the position of "Sports" moves with whatever the provider happened
      // to publish - and the category picker is used to find a named section, not to discover the
      // largest one. The catch-all groups stay pinned to the end, where they are a fallback rather
      // than a destination.
      compareBy<BrowseCategory> { it.name in trailingCategoryNames }
        .thenBy { it.name.lowercase() },
    )
}

/** Everything the browse screen derives from a catalogue in one pass, so it can be cached whole. */
private class BrowseCategoryResult(
  val sourceNames: List<String>,
  val scopedItems: List<MediaItem>,
  val categories: List<BrowseCategory>,
)

/**
 * Sorted catalogues, kept for the session.
 *
 * The screen's state is dropped when the page is left, so re-entering a "View All" page used to
 * sort the same channels from scratch and show the progress notice again every time. Entries hold
 * references to the MediaItems already in ui state, so a cached catalogue costs a pointer array
 * rather than a second copy of the list.
 *
 * The key carries a fingerprint of the list, so a catalogue that has since gained items — the next
 * page of an add-on catalogue, a newly added favourite — misses the cache and re-sorts.
 */
private object BrowseCategoryCache {
  private const val MAX_ENTRIES = 8
  // accessOrder = true makes this an LRU, so the least recently opened page is evicted first.
  private val entries = object : LinkedHashMap<String, BrowseCategoryResult>(0, 0.75f, true) {
    override fun removeEldestEntry(eldest: Map.Entry<String, BrowseCategoryResult>): Boolean = size > MAX_ENTRIES
  }

  fun key(rowId: String, sourceName: String?, items: List<MediaItem>): String =
    "$rowId|${sourceName.orEmpty()}|${items.size}|${items.firstOrNull()?.id.orEmpty()}|${items.lastOrNull()?.id.orEmpty()}"

  @Synchronized fun get(key: String): BrowseCategoryResult? = entries[key]

  @Synchronized fun put(key: String, result: BrowseCategoryResult) { entries[key] = result }

  /** Called when the active profile changes: a new profile has its own playlists and favourites. */
  @Synchronized fun clear() = entries.clear()
}

/** How many entries the browse screen inspects when deciding what kind of catalogue a row holds. */
private const val BROWSE_ROW_KIND_SAMPLE = 200

private fun browseCategoryIcon(name: String): ImageVector = when (name) {
  "Sports" -> Icons.Rounded.SportsSoccer
  "News" -> Icons.Rounded.Newspaper
  "Movies" -> Icons.Rounded.Movie
  "Series & Shows", "Entertainment" -> Icons.Rounded.Theaters
  "Kids" -> Icons.Rounded.ChildCare
  "Music" -> Icons.Rounded.MusicNote
  "Documentary" -> Icons.Rounded.Public
  "Religion" -> Icons.Rounded.Church
  "Lifestyle" -> Icons.Rounded.Restaurant
  "Adult" -> Icons.Rounded.Lock
  else -> if (name in channelRegionNames.values) Icons.Rounded.Language else Icons.Rounded.LiveTv
}

private val browseCategoryPalette = listOf(
  Color(0xFF38BDF8), Color(0xFFF472B6), Color(0xFFFBBF24), Color(0xFF4ADE80),
  Color(0xFFA78BFA), Color(0xFFFB923C), Color(0xFF2DD4BF), Color(0xFFF87171),
)

private fun browseCategoryAccent(name: String): Color = when (name) {
  "Sports" -> Color(0xFF4ADE80)
  "News" -> Color(0xFF38BDF8)
  "Movies" -> Color(0xFFA78BFA)
  "Kids" -> Color(0xFFFBBF24)
  "Music" -> Color(0xFFF472B6)
  "Documentary" -> Color(0xFF2DD4BF)
  "Adult" -> Color(0xFFF87171)
  else -> browseCategoryPalette[(name.hashCode().toLong().let { kotlin.math.abs(it) } % browseCategoryPalette.size).toInt()]
}

/**
 * The Live TV "View All" page.
 *
 * A channel list rather than a grid of category tiles, which is what this used to be. Tens of
 * thousands of channels genuinely cannot be shown at once, but a wall of categories in front of
 * them answers that by hiding the thing the viewer came for: on a channel list the first move is
 * almost always to search or to resume, and neither of those is a category. So the channels are on
 * screen from the first frame, and the category becomes a filter sitting beside "All" and
 * "Favourites" rather than a gate in front of them.
 *
 * Used for the Favourites page too. It is the same content with a smaller scope, and giving it a
 * different layout was only ever an accident of where the two pages were written.
 */
/**
 * The live channel the viewer left most recently.
 *
 * Read off the same resume store Continue Watching uses. Live entries are recorded there like
 * everything else and then filtered *out* of that row, because a channel has no position to
 * return to — but "which channel was I on" is exactly the question a Live TV page should answer,
 * so here it is the useful half of the same record.
 */
private fun AppUiState.lastWatchedLiveChannel(): MediaItem? =
  localResumeEntries
    .filter { it.isLive || it.mediaType.lowercase() in setOf("live", "channel") }
    .maxByOrNull { it.updatedAt }
    ?.let { entry ->
      MediaItem(
        id = entry.mediaId,
        type = entry.mediaType,
        title = entry.title,
        year = entry.year,
        poster = entry.poster,
        backdrop = entry.backdrop,
        rating = null,
        description = "",
      )
    }

@Composable
private fun LiveChannelsBrowseScreen(
  title: String,
  items: List<MediaItem>,
  favouriteItems: List<MediaItem>,
  categoriesEnabled: Boolean,
  isFavouritesRow: Boolean,
  lastWatched: MediaItem?,
  onBack: () -> Unit,
  onOpen: (MediaItem) -> Unit,
  onToggleFavourite: (MediaItem) -> Unit,
  onClearFavourites: (() -> Unit)?,
) {
  val lightPage = MaterialTheme.colorScheme.background.luminance() > 0.5f
  var query by rememberSaveable(title) { mutableStateOf("") }
  var scope by rememberSaveable(title) { mutableStateOf(LiveChannelScope.All) }
  var selectedCategory by rememberSaveable(title) { mutableStateOf<String?>(null) }
  var showCategorySheet by remember { mutableStateOf(false) }
  var showClearConfirm by remember { mutableStateOf(false) }

  // Grouping a fifty-thousand-channel playlist is far too much work for the main thread, so it is
  // done on Default and only when the page is actually offering categories.
  var categories by remember(title, items) { mutableStateOf<List<BrowseCategory>>(emptyList()) }
  LaunchedEffect(items, categoriesEnabled) {
    categories = if (!categoriesEnabled) emptyList() else withContext(Dispatchers.Default) { buildBrowseCategories(items) }
    if (selectedCategory != null && categories.none { it.name == selectedCategory }) {
      selectedCategory = null
      if (scope == LiveChannelScope.Category) scope = LiveChannelScope.All
    }
  }

  val favouriteIds = remember(favouriteItems) { favouriteItems.mapTo(hashSetOf()) { it.id } }
  val scoped = when {
    scope == LiveChannelScope.Favourites -> items.filter { it.id in favouriteIds }
    scope == LiveChannelScope.Category && selectedCategory != null ->
      categories.firstOrNull { it.name == selectedCategory }?.items.orEmpty()
    else -> items
  }
  // Searching runs off the main thread for the same reason grouping does: an IPTV list is long
  // enough that filtering it per keystroke on the UI thread is felt.
  var visible by remember(title) { mutableStateOf<List<MediaItem>>(emptyList()) }
  LaunchedEffect(scoped, query) {
    val trimmed = query.trim()
    visible = if (trimmed.isEmpty()) scoped else withContext(Dispatchers.Default) {
      scoped.filter { it.title.contains(trimmed, ignoreCase = true) || it.sourceCatalogName.orEmpty().contains(trimmed, ignoreCase = true) }
    }
  }

  BackHandler(onBack = onBack)

  if (showClearConfirm && onClearFavourites != null) {
    AlertDialog(
      onDismissRequest = { showClearConfirm = false },
      title = { Text("Clear Live Favourites?") },
      text = { Text("This removes all ${favouriteItems.size} favourite channels. This can't be undone.") },
      confirmButton = { Button(onClick = { showClearConfirm = false; onClearFavourites() }) { Text("Clear all") } },
      dismissButton = { TextButton(onClick = { showClearConfirm = false }) { Text("Cancel") } },
    )
  }

  if (showCategorySheet) {
    LiveCategorySheet(
      categories = categories,
      selected = if (scope == LiveChannelScope.Category) selectedCategory else null,
      scope = scope,
      showFavourites = !isFavouritesRow,
      onDismiss = { showCategorySheet = false },
      onPick = { picked ->
        when (picked) {
          null -> { scope = LiveChannelScope.All; selectedCategory = null }
          LIVE_SCOPE_FAVOURITES -> { scope = LiveChannelScope.Favourites; selectedCategory = null }
          else -> { scope = LiveChannelScope.Category; selectedCategory = picked }
        }
        showCategorySheet = false
      },
    )
  }

  Box(modifier = Modifier.fillMaxSize().background(MaterialTheme.colorScheme.background)) {
    LazyColumn(
      // The page draws edge to edge, so the list has to be told where the status bar ends. Without
      // this the header scrolls up underneath the clock instead of starting below it.
      modifier = Modifier.fillMaxSize().statusBarsPadding(),
      // No horizontal padding here: the pinned block needs to paint edge to edge, so the 20dp
      // margin is applied per item instead.
      contentPadding = PaddingValues(top = 20.dp, bottom = 126.dp),
      verticalArrangement = Arrangement.spacedBy(12.dp),
    ) {
      // Everything above the channel list is pinned: back/title/count, the search box, the
      // scope chips and the section count. An IPTV list runs to tens of thousands of rows, so
      // with these scrolling away the only way back to search or the category picker was to
      // fling all the way to the top. The list scrolls underneath instead.
      stickyHeader(key = "controls") {
        Column(
          modifier = Modifier
            .fillMaxWidth()
            // Opaque, and drawn outside the list padding, so channels passing underneath do
            // not show through at the margins.
            .background(MaterialTheme.colorScheme.background)
            .padding(horizontal = 20.dp)
            .padding(bottom = 12.dp),
          verticalArrangement = Arrangement.spacedBy(12.dp),
        ) {
          Row(modifier = Modifier.fillMaxWidth(), verticalAlignment = Alignment.CenterVertically, horizontalArrangement = Arrangement.spacedBy(12.dp)) {
            GlassCircleButton(onClick = onBack) {
              Icon(Icons.AutoMirrored.Rounded.ArrowBack, contentDescription = "Back", tint = MaterialTheme.colorScheme.onBackground)
            }
            Column(modifier = Modifier.weight(1f), verticalArrangement = Arrangement.spacedBy(3.dp)) {
              AdaptivePageTitle(title = title, maxLines = 2)
              Text(
                "${items.size.formattedItemCount()} channel${if (items.size == 1) "" else "s"}",
                color = MaterialTheme.colorScheme.onBackground.copy(alpha = 0.60f),
                style = MaterialTheme.typography.bodyMedium,
                fontWeight = FontWeight.Bold,
              )
            }
            if (onClearFavourites != null && favouriteItems.isNotEmpty()) {
              GlassCircleButton(onClick = { showClearConfirm = true }) {
                Icon(Icons.Rounded.DeleteSweep, contentDescription = "Clear favourites", tint = MaterialTheme.colorScheme.onBackground)
              }
            }
          }
          OutlinedTextField(
            value = query,
            onValueChange = { query = it },
            modifier = Modifier.fillMaxWidth(),
            placeholder = { InputGuideText("Search channels") },
            leadingIcon = { Icon(Icons.Rounded.Search, contentDescription = null) },
            trailingIcon = if (query.isNotBlank()) ({ IconButton(onClick = { query = "" }) { Icon(Icons.Rounded.Close, "Clear") } }) else null,
            singleLine = true,
            shape = StreamDekRadius.cardShape,
          )
          Row(
            modifier = Modifier.fillMaxWidth().horizontalScroll(rememberScrollState()),
            horizontalArrangement = Arrangement.spacedBy(10.dp),
          ) {
            FilterChip(
              selected = scope == LiveChannelScope.All,
              onClick = { scope = LiveChannelScope.All; selectedCategory = null },
              label = { Text("All channels") },
            )
            if (!isFavouritesRow) {
              FilterChip(
                selected = scope == LiveChannelScope.Favourites,
                onClick = { scope = LiveChannelScope.Favourites; selectedCategory = null },
                label = { Text("Favourites") },
              )
            }
            if (categories.size >= 2) {
              FilterChip(
                selected = scope == LiveChannelScope.Category,
                onClick = { showCategorySheet = true },
                label = { Text(selectedCategory?.takeIf { scope == LiveChannelScope.Category } ?: "Choose category") },
                trailingIcon = { Icon(Icons.Rounded.KeyboardArrowDown, contentDescription = null, modifier = Modifier.size(18.dp)) },
              )
            }
          }
          Row(modifier = Modifier.fillMaxWidth(), verticalAlignment = Alignment.CenterVertically) {
            Text(
              when {
                scope == LiveChannelScope.Favourites -> "Favourites"
                scope == LiveChannelScope.Category -> selectedCategory.orEmpty()
                else -> "Channels"
              },
              modifier = Modifier.weight(1f),
              color = MaterialTheme.colorScheme.onBackground,
              style = MaterialTheme.typography.titleSmall,
              fontWeight = FontWeight.Black,
              maxLines = 1,
              overflow = TextOverflow.Ellipsis,
            )
            Text(
              "${visible.size.formattedItemCount()} channel${if (visible.size == 1) "" else "s"}",
              color = MaterialTheme.colorScheme.onBackground.copy(alpha = 0.55f),
              style = MaterialTheme.typography.labelLarge,
              fontWeight = FontWeight.Bold,
            )
          }
        }
      }

      // Content rather than a control, so it scrolls with the channels it sits above.
      lastWatched?.takeIf { candidate -> items.any { it.id == candidate.id } }?.let { channel ->
        item(key = "resume") {
          Box(modifier = Modifier.padding(horizontal = 20.dp)) {
            LiveResumeCard(channel = channel, lightPage = lightPage, onPlay = { onOpen(channel) })
          }
        }
      }

      if (visible.isEmpty()) {
        item(key = "empty") {
          Text(
            when {
              query.isNotBlank() -> "No channels match \"${query.trim()}\"."
              scope == LiveChannelScope.Favourites -> "No favourite channels yet. Tap the star on a channel to keep it here."
              else -> "No channels here yet."
            },
            color = MaterialTheme.colorScheme.onBackground.copy(alpha = 0.68f),
            style = MaterialTheme.typography.bodyMedium,
            modifier = Modifier.padding(horizontal = 20.dp, vertical = 24.dp),
          )
        }
      }

      items(visible, key = { "${it.type}-${it.id}" }) { channel ->
        Box(modifier = Modifier.padding(horizontal = 20.dp)) {
          LiveChannelRow(
            channel = channel,
            favourite = channel.id in favouriteIds,
            lightPage = lightPage,
            onPlay = { onOpen(channel) },
            onToggleFavourite = { onToggleFavourite(channel) },
          )
        }
      }
    }
  }
}

private enum class LiveChannelScope { All, Favourites, Category }

/** Sentinel for the Favourites entry in the category sheet, which is not a category. */
private const val LIVE_SCOPE_FAVOURITES = "␀favourites"

/** The channel left part-way, with one press to go back to it. */
@Composable
private fun LiveResumeCard(channel: MediaItem, lightPage: Boolean, onPlay: () -> Unit) {
  Card(
    modifier = Modifier.fillMaxWidth().clickable(onClick = onPlay),
    colors = CardDefaults.cardColors(
      containerColor = MaterialTheme.colorScheme.onSurface.copy(alpha = if (lightPage) 0.08f else 0.06f),
    ),
    shape = StreamDekRadius.panelShape,
  ) {
    Row(
      modifier = Modifier.fillMaxWidth().padding(14.dp),
      horizontalArrangement = Arrangement.spacedBy(14.dp),
      verticalAlignment = Alignment.CenterVertically,
    ) {
      LiveChannelArtwork(channel = channel, size = 62.dp, lightPage = lightPage)
      Column(modifier = Modifier.weight(1f), verticalArrangement = Arrangement.spacedBy(2.dp)) {
        Text(
          "Last watched channel",
          color = MaterialTheme.colorScheme.onBackground.copy(alpha = 0.58f),
          style = MaterialTheme.typography.labelMedium,
          fontWeight = FontWeight.Bold,
        )
        Text(
          channel.title,
          color = MaterialTheme.colorScheme.onBackground,
          style = MaterialTheme.typography.titleMedium,
          fontWeight = FontWeight.Black,
          maxLines = 1,
          overflow = TextOverflow.Ellipsis,
        )
        channel.sourceCatalogName?.takeIf { it.isNotBlank() }?.let {
          Text(
            it,
            color = MaterialTheme.colorScheme.onBackground.copy(alpha = 0.50f),
            style = MaterialTheme.typography.bodySmall,
            maxLines = 1,
            overflow = TextOverflow.Ellipsis,
          )
        }
      }
      Row(
        modifier = Modifier
          .clip(StreamDekRadius.pill)
          .background(MaterialTheme.colorScheme.primary)
          .clickable(onClick = onPlay)
          .padding(horizontal = 16.dp, vertical = 10.dp),
        horizontalArrangement = Arrangement.spacedBy(6.dp),
        verticalAlignment = Alignment.CenterVertically,
      ) {
        Icon(Icons.Rounded.PlayArrow, contentDescription = null, tint = MaterialTheme.colorScheme.onPrimary, modifier = Modifier.size(20.dp))
        Text("Continue", color = MaterialTheme.colorScheme.onPrimary, style = MaterialTheme.typography.labelLarge, fontWeight = FontWeight.Black, maxLines = 1)
      }
    }
  }
}

/** One channel: its mark, what it is, whether it is kept, and one press to watch it. */
@Composable
private fun LiveChannelRow(
  channel: MediaItem,
  favourite: Boolean,
  lightPage: Boolean,
  onPlay: () -> Unit,
  onToggleFavourite: () -> Unit,
) {
  Card(
    modifier = Modifier.fillMaxWidth().clickable(onClick = onPlay),
    colors = CardDefaults.cardColors(
      containerColor = MaterialTheme.colorScheme.onSurface.copy(alpha = if (lightPage) 0.07f else 0.05f),
    ),
    shape = StreamDekRadius.cardShape,
  ) {
    Row(
      modifier = Modifier.fillMaxWidth().padding(horizontal = 12.dp, vertical = 11.dp),
      horizontalArrangement = Arrangement.spacedBy(12.dp),
      verticalAlignment = Alignment.CenterVertically,
    ) {
      LiveChannelArtwork(channel = channel, size = 54.dp, lightPage = lightPage)
      Column(modifier = Modifier.weight(1f), verticalArrangement = Arrangement.spacedBy(2.dp)) {
        Text(
          channel.title,
          color = MaterialTheme.colorScheme.onBackground,
          style = MaterialTheme.typography.titleSmall,
          fontWeight = FontWeight.Black,
          maxLines = 2,
          overflow = TextOverflow.Ellipsis,
        )
        channel.sourceCatalogName?.takeIf { it.isNotBlank() }?.let {
          Text(
            it,
            color = MaterialTheme.colorScheme.onBackground.copy(alpha = 0.50f),
            style = MaterialTheme.typography.bodySmall,
            maxLines = 1,
            overflow = TextOverflow.Ellipsis,
          )
        }
      }
      IconButton(onClick = onToggleFavourite, modifier = Modifier.size(40.dp)) {
        Icon(
          if (favourite) Icons.Rounded.Star else Icons.Rounded.StarBorder,
          contentDescription = if (favourite) "Remove ${channel.title} from favourites" else "Add ${channel.title} to favourites",
          tint = if (favourite) Color(0xFFFACC15) else MaterialTheme.colorScheme.onBackground.copy(alpha = 0.42f),
        )
      }
      Box(
        modifier = Modifier
          .size(44.dp)
          .clip(StreamDekRadius.pill)
          .background(MaterialTheme.colorScheme.onSurface.copy(alpha = if (lightPage) 0.10f else 0.12f))
          .clickable(onClick = onPlay),
        contentAlignment = Alignment.Center,
      ) {
        Icon(Icons.Rounded.PlayArrow, contentDescription = "Play ${channel.title}", tint = MaterialTheme.colorScheme.onBackground, modifier = Modifier.size(22.dp))
      }
    }
  }
}

/**
 * A channel's logo, or a mark standing in for one.
 *
 * Most IPTV entries carry no artwork at all, so the placeholder is the common case rather than the
 * error case and is drawn to look deliberate.
 */
@Composable
private fun LiveChannelArtwork(channel: MediaItem, size: Dp, lightPage: Boolean) {
  Box(
    modifier = Modifier
      .size(size)
      .clip(StreamDekRadius.thumbShape)
      .background(MaterialTheme.colorScheme.onSurface.copy(alpha = if (lightPage) 0.08f else 0.10f)),
    contentAlignment = Alignment.Center,
  ) {
    val artwork = channel.poster ?: channel.backdrop ?: channel.titleLogo
    if (artwork.isNullOrBlank()) {
      Icon(
        Icons.Rounded.Tv,
        contentDescription = null,
        tint = MaterialTheme.colorScheme.onBackground.copy(alpha = 0.45f),
        modifier = Modifier.size(size * 0.46f),
      )
    } else {
      AsyncImage(
        model = artwork,
        contentDescription = channel.title,
        modifier = Modifier.fillMaxSize().padding(6.dp),
        contentScale = ContentScale.Fit,
      )
    }
  }
}

/** The category picker, as a sheet rather than a page in front of the channels. */
@Composable
private fun LiveCategorySheet(
  categories: List<BrowseCategory>,
  selected: String?,
  scope: LiveChannelScope,
  showFavourites: Boolean,
  onDismiss: () -> Unit,
  onPick: (String?) -> Unit,
) {
  Dialog(onDismissRequest = onDismiss, properties = DialogProperties(usePlatformDefaultWidth = false)) {
    Box(
      modifier = Modifier.fillMaxSize().background(Color.Black.copy(alpha = 0.66f)).clickable(onClick = onDismiss),
      contentAlignment = Alignment.BottomCenter,
    ) {
      Surface(
        modifier = Modifier.fillMaxWidth().widthIn(max = 640.dp).heightIn(max = 680.dp).clickable(enabled = false, onClick = {}),
        color = MaterialTheme.colorScheme.surface,
        shape = RoundedCornerShape(topStart = 30.dp, topEnd = 30.dp),
        border = BorderStroke(1.dp, MaterialTheme.colorScheme.onSurface.copy(alpha = 0.12f)),
      ) {
        Column(modifier = Modifier.padding(top = 12.dp)) {
          Box(
            modifier = Modifier
              .align(Alignment.CenterHorizontally)
              .width(44.dp)
              .height(4.dp)
              .clip(StreamDekRadius.pill)
              .background(MaterialTheme.colorScheme.onSurface.copy(alpha = 0.22f)),
          )
          Text(
            "Choose category",
            modifier = Modifier.padding(horizontal = 24.dp, vertical = 18.dp),
            color = MaterialTheme.colorScheme.onSurface,
            style = MaterialTheme.typography.titleLarge,
            fontWeight = FontWeight.Black,
          )
          LazyColumn(contentPadding = PaddingValues(bottom = 28.dp)) {
            item(key = "all") {
              LiveCategorySheetRow(
                label = "All channels",
                icon = Icons.Rounded.Tv,
                selected = scope == LiveChannelScope.All,
                onClick = { onPick(null) },
              )
            }
            if (showFavourites) {
              item(key = "favourites") {
                LiveCategorySheetRow(
                  label = "Favourites",
                  icon = Icons.Rounded.Star,
                  selected = scope == LiveChannelScope.Favourites,
                  onClick = { onPick(LIVE_SCOPE_FAVOURITES) },
                )
              }
            }
            item(key = "heading") {
              Text(
                "Categories",
                modifier = Modifier.padding(start = 24.dp, end = 24.dp, top = 18.dp, bottom = 8.dp),
                color = MaterialTheme.colorScheme.onSurface.copy(alpha = 0.55f),
                style = MaterialTheme.typography.labelLarge,
                fontWeight = FontWeight.Bold,
              )
            }
            items(categories, key = { it.name }) { category ->
              LiveCategorySheetRow(
                label = category.name,
                icon = null,
                trailing = "${category.items.size.formattedItemCount()}",
                selected = selected == category.name,
                onClick = { onPick(category.name) },
              )
            }
          }
        }
      }
    }
  }
}

@Composable
private fun LiveCategorySheetRow(
  label: String,
  icon: androidx.compose.ui.graphics.vector.ImageVector?,
  selected: Boolean,
  onClick: () -> Unit,
  trailing: String? = null,
) {
  Row(
    modifier = Modifier
      .fillMaxWidth()
      .clickable(onClick = onClick)
      .padding(horizontal = 24.dp, vertical = 16.dp),
    horizontalArrangement = Arrangement.spacedBy(14.dp),
    verticalAlignment = Alignment.CenterVertically,
  ) {
    if (icon != null) {
      Icon(icon, contentDescription = null, tint = if (selected) MaterialTheme.colorScheme.primary else MaterialTheme.colorScheme.onSurface.copy(alpha = 0.72f))
    }
    Text(
      label,
      modifier = Modifier.weight(1f),
      color = if (selected) MaterialTheme.colorScheme.primary else MaterialTheme.colorScheme.onSurface,
      style = MaterialTheme.typography.titleSmall,
      fontWeight = if (selected) FontWeight.Black else FontWeight.SemiBold,
      maxLines = 2,
      overflow = TextOverflow.Ellipsis,
    )
    trailing?.let {
      Text(it, color = MaterialTheme.colorScheme.onSurface.copy(alpha = 0.45f), style = MaterialTheme.typography.labelMedium, fontWeight = FontWeight.Bold)
    }
    if (selected) {
      Icon(Icons.Rounded.CheckCircle, contentDescription = null, tint = MaterialTheme.colorScheme.primary, modifier = Modifier.size(20.dp))
    }
  }
}

@Composable
private fun BrowseSectionScreen(row: HomeRow, loadedItems: List<MediaItem>, returnItemId: String?, headerStyle: HeaderStyle, lastWatchedChannel: MediaItem? = null, networkCardStyle: NetworkCardStyle = NetworkCardStyle.Branded, liveLandscapeCards: Boolean, categoriesEnabled: Boolean = true, watchlistItems: List<MediaItem>, favouriteItems: List<MediaItem> = emptyList(), addons: List<InstalledAddon> = emptyList(), handoffDevices: List<LinkedTvDevice> = emptyList(), onRefreshHandoffDevices: () -> Unit = {}, onHandoffLive: suspend (MediaItem, LinkedTvDevice) -> Result<PlaybackHandoffReceipt> = { _, _ -> Result.failure(IllegalStateException("Handoff is unavailable.")) }, onBack: () -> Unit, onOpen: (MediaItem) -> Unit, onToggleWatchlist: (MediaItem) -> Unit, onToggleFavourite: (MediaItem) -> Unit = {}, onClearFavourites: () -> Unit = {}, onEnableAddon: (InstalledAddon) -> Unit = {}, onMarkWatched: (MediaItem) -> Unit, pageableRowIds: Set<String> = emptySet(), onLoadMore: (suspend (String, MediaItem?, Int) -> List<MediaItem>)? = null) {
  fun isFavourite(item: MediaItem): Boolean = favouriteItems.hasFavouriteChannel(item)
  var filter by rememberSaveable(row.id) { mutableStateOf(MediaFilter.All) }
  var layout by rememberSaveable(row.id) { mutableStateOf(BrowseLayout.Cards3) }
  var actionItem by remember { mutableStateOf<MediaItem?>(null) }
  var disabledAddonPrompt by remember { mutableStateOf<InstalledAddon?>(null) }
  var showClearFavouritesConfirm by rememberSaveable(row.id) { mutableStateOf(false) }
  val isFavouritesRow = row.id == "favourites"
  fun addonFor(item: MediaItem): InstalledAddon? = item.sourceAddonId?.let { id -> addons.firstOrNull { it.id == id } }
  fun handleOpen(item: MediaItem) {
    val addon = if (isFavouritesRow) addonFor(item) else null
    if (addon != null && !addon.enabled) disabledAddonPrompt = addon else onOpen(item)
  }
  val browseHazeState = rememberHazeState()
  val modernHeader = headerStyle == HeaderStyle.Modern
  val isM3uRow = row.id.startsWith("m3u_playlists_")
  // Both of these decide what kind of row this is, and both used to scan the entire catalogue on
  // every recomposition — isLiveCatalogItem() compiles regexes, so on a 200k-channel playlist VOD
  // row (where the id and title checks do not short-circuit) that was enough to stall composition
  // on its own. The answer cannot change for a given row, and for a catalogue that is homogeneous
  // by construction a sample off the front is as good an answer as the full sweep.
  val isLiveRow = remember(row.id, row.title, row.items.size) {
    row.id == "m3u_playlists_live" || row.title.contains("live", true) || row.title.contains("sport", true) ||
      row.items.asSequence().take(BROWSE_ROW_KIND_SAMPLE).any(MediaItem::isLiveCatalogItem)
  }
  val isNetworkRow = remember(row.id, row.items.size) {
    row.id == "streaming_networks" ||
      (!isM3uRow && row.items.asSequence().take(BROWSE_ROW_KIND_SAMPLE).any { it.type == "network" })
  }
  // Live channels get their own page. A grid of posters is the wrong shape for a channel list --
  // most carry no artwork, and what a viewer does here is search, resume or star rather than
  // browse pictures. See LiveChannelsBrowseScreen.
  if (isLiveRow || isM3uRow || isFavouritesRow) {
    LiveChannelsBrowseScreen(
      title = row.title,
      items = loadedItems,
      favouriteItems = favouriteItems,
      categoriesEnabled = categoriesEnabled,
      isFavouritesRow = isFavouritesRow,
      lastWatched = lastWatchedChannel,
      onBack = onBack,
      onOpen = ::handleOpen,
      onToggleFavourite = onToggleFavourite,
      onClearFavourites = if (isFavouritesRow) onClearFavourites else null,
    )
    return
  }
  val landscapeArtwork = (isLiveRow && liveLandscapeCards) || isNetworkRow
  val showsList = layout == BrowseLayout.List
  // Landscape artwork is unreadable three across, so those rows toggle straight between their
  // card grid and the text list.
  fun nextLayout(): BrowseLayout = when {
    showsList -> BrowseLayout.Cards3
    landscapeArtwork -> BrowseLayout.List
    layout == BrowseLayout.Cards3 -> BrowseLayout.Cards2
    else -> BrowseLayout.List
  }
  // The chosen density, before the window has its say.
  val compactColumns = when {
    showsList -> 1
    landscapeArtwork -> 2
    layout == BrowseLayout.Cards2 -> 2
    else -> 3
  }
  // A text list stays one column at any width — its rows are full-width by nature, and the
  // container's maximum readable width is what keeps them from stretching.
  val adaptiveColumns = if (showsList) 1 else adaptiveMediaColumns(compactColumns, landscapeArtwork)
  fun contentColumns(): Int = adaptiveColumns
  var query by rememberSaveable(row.id) { mutableStateOf("") }
  var browseSort by rememberSaveable(row.id) { mutableStateOf(BrowseSort.Original) }
  // Live TV and playlist catalogs browse as categories first, channels second — a flat list of
  // tens of thousands of channels is unusable on a phone. Everything else keeps the flat grid.
  val supportsCategories = categoriesEnabled && (isM3uRow || isLiveRow)
  var selectedCategory by rememberSaveable(row.id) { mutableStateOf<String?>(null) }
  var selectedSource by rememberSaveable(row.id) { mutableStateOf<String?>(null) }
  var categories by remember(row.id) { mutableStateOf<List<BrowseCategory>>(emptyList()) }
  var sourceNames by remember(row.id) { mutableStateOf<List<String>>(emptyList()) }
  var scopedItems by remember(row.id) { mutableStateOf(loadedItems) }
  var categorizing by remember(row.id) { mutableStateOf(false) }
  // "View All" starts from whatever the home row already fetched, then pages in more from the
  // same add-on catalog as the user scrolls — most add-on catalogs only return a handful of
  // items per request so large add-on catalogs are fetched incrementally.
  var isLoadingMore by remember(row.id) { mutableStateOf(false) }
  var canLoadMore by remember(row.id) {
    mutableStateOf(
      onLoadMore != null && !isM3uRow && row.items.isNotEmpty() &&
        (
          row.items.last().let { it.sourceAddonId != null && it.sourceCatalogType != null && it.sourceCatalogId != null } ||
            row.id in pageableRowIds
        ),
    )
  }
  // M3U parser IDs are already unique; do not allocate another full list just to deduplicate a
  // potentially huge playlist. Other rows keep their existing defensive de-duplication.
  val uniqueItems = remember(row.id, loadedItems) { if (isM3uRow) loadedItems else loadedItems.distinctBy(::mediaCollectionKey) }
  val hasMovies = remember(uniqueItems, isM3uRow) { !isM3uRow && uniqueItems.any { it.type.equals("movie", true) } }
  val hasSeries = remember(uniqueItems, isM3uRow) { !isM3uRow && uniqueItems.any { it.type.equals("tv", true) || it.type.equals("series", true) } }
  val showsTypeFilters = hasMovies && hasSeries
  // Live TV / sports rows hold long channel lists, so they get local search. Filtering and
  // sorting run on Default rather than the UI thread so very large IPTV lists remain responsive.
  val showSearch = isLiveRow || uniqueItems.size >= 24
  var filteredItems by remember(row.id) { mutableStateOf<List<MediaItem>>(emptyList()) }
  // Grouping a 50k-channel playlist is far too much work for the main thread, so categories are
  // built on Default alongside the search/sort pass below.
  LaunchedEffect(uniqueItems, supportsCategories, selectedSource) {
    if (!supportsCategories) {
      categories = emptyList()
      sourceNames = emptyList()
      scopedItems = uniqueItems
      categorizing = false
      return@LaunchedEffect
    }
    // Sorting the same catalogue again on every visit is wasted work the user has to watch, so a
    // page that has already been sorted comes straight back from the cache without the notice.
    val cacheKey = BrowseCategoryCache.key(row.id, selectedSource, uniqueItems)
    val computed = BrowseCategoryCache.get(cacheKey) ?: run {
      categorizing = true
      withContext(Dispatchers.Default) {
        val sources = uniqueItems.mapNotNull { it.sourceAddonName?.takeIf(String::isNotBlank) }.distinct()
        val scoped = selectedSource
          ?.takeIf { name -> sources.any { it == name } }
          ?.let { name -> uniqueItems.filter { it.sourceAddonName == name } }
          ?: uniqueItems
        BrowseCategoryResult(sources, scoped, buildBrowseCategories(scoped))
      }.also { BrowseCategoryCache.put(cacheKey, it) }
    }
    sourceNames = computed.sourceNames
    scopedItems = computed.scopedItems
    categories = computed.categories
    // A playlist can be removed while its "View All" page is open; don't leave the picker
    // pointing at a source that is no longer there.
    if (selectedSource != null && sourceNames.none { it == selectedSource }) selectedSource = null
    categorizing = false
  }
  // What the search/sort pass runs over: one category's channels once the user has drilled in,
  // otherwise everything currently in scope.
  val baseItems = when {
    !supportsCategories -> uniqueItems
    selectedCategory != null -> categories.firstOrNull { it.name == selectedCategory }?.items.orEmpty()
    else -> scopedItems
  }
  LaunchedEffect(baseItems, filter, showsTypeFilters, query, browseSort) {
    filteredItems = withContext(Dispatchers.Default) {
      val typeFiltered = if (showsTypeFilters) baseItems.filteredBy(filter) else baseItems
      val normalizedQuery = query.trim()
      val searched = if (normalizedQuery.isBlank()) typeFiltered else typeFiltered.filter {
        it.title.contains(normalizedQuery, ignoreCase = true) || it.description.contains(normalizedQuery, ignoreCase = true)
      }
      when (browseSort) {
        BrowseSort.Original -> searched
        BrowseSort.TitleAscending -> searched.sortedWith(compareBy<MediaItem> { it.title.lowercase() })
        BrowseSort.TitleDescending -> searched.sortedWith(compareByDescending<MediaItem> { it.title.lowercase() })
      }
    }
  }
  // Typing in the search box drops straight to matching channels across the whole catalog, which
  // is how an IPTV app behaves — categories are a browsing aid, not a wall in front of search.
  val showCategoryGrid = supportsCategories && selectedCategory == null && query.isBlank() && categories.size >= 2
  // Held back briefly so a playlist small enough to group instantly doesn't flash a progress
  // notice for two frames. Only the category level shows it; drilling in has nothing to wait for.
  var showCategorizingNotice by remember(row.id) { mutableStateOf(false) }
  LaunchedEffect(categorizing, selectedCategory, query) {
    if (!categorizing || selectedCategory != null || query.isNotBlank()) {
      showCategorizingNotice = false
      return@LaunchedEffect
    }
    delay(180)
    showCategorizingNotice = true
  }
  val showHeaderFilters = !isNetworkRow && showsTypeFilters && !showCategoryGrid
  val searchExtra = if (showSearch) 72.dp else 0.dp
  val modernHeaderHeight = (if (showHeaderFilters) 164.dp else 124.dp) + searchExtra
  val modernContentTop = (if (showHeaderFilters) 234.dp else 194.dp) + searchExtra
  val classicContentTop = (if (showHeaderFilters) 202.dp else 152.dp) + searchExtra
  val clearFavouritesAction: (() -> Unit)? =
    if (isFavouritesRow && uniqueItems.isNotEmpty()) ({ showClearFavouritesConfirm = true }) else null
  if (showClearFavouritesConfirm) {
    AlertDialog(
      onDismissRequest = { showClearFavouritesConfirm = false },
      title = { Text("Clear Live Favourites?") },
      text = { Text("This removes all ${uniqueItems.size} favourite channels. This can't be undone.") },
      confirmButton = { Button(onClick = { showClearFavouritesConfirm = false; onClearFavourites() }) { Text("Clear all") } },
      dismissButton = { TextButton(onClick = { showClearFavouritesConfirm = false }) { Text("Cancel") } },
    )
  }
  // Inside a category, back steps up to the category list rather than leaving the page.
  BackHandler(onBack = { if (selectedCategory != null) selectedCategory = null else onBack() })

  val gridState = rememberLazyGridState()
  LaunchedEffect(returnItemId, filteredItems.size, query, browseSort) {
    val targetId = returnItemId ?: return@LaunchedEffect
    val targetIndex = withContext(Dispatchers.Default) { filteredItems.indexOfFirst { it.id == targetId } }
    if (targetIndex >= 0) gridState.scrollToItem(targetIndex)
  }
  // Changing level resets the scroll, but only on a real change: the initial value matches the
  // restored selection so returning from a channel keeps the position the grid state saved.
  var lastLevelKey by remember(row.id) { mutableStateOf(selectedCategory to selectedSource) }
  LaunchedEffect(selectedCategory, selectedSource) {
    val levelKey = selectedCategory to selectedSource
    if (levelKey != lastLevelKey) {
      lastLevelKey = levelKey
      gridState.scrollToItem(0)
    }
  }
  // Only auto-page while the user is looking at the unfiltered list: once "skip" no longer
  // lines up with what's on screen (a search/type filter is active), fetching more would just
  // silently re-request items already loaded.
  // The category screen shows categories, not channels, so "scrolled near the last channel"
  // means nothing there — it offers an explicit "Load more channels" footer instead.
  val canAutoPage = canLoadMore && filter == MediaFilter.All && query.isBlank() &&
    browseSort == BrowseSort.Original && !showCategoryGrid
  // Deliberately NOT info.totalItemsCount: the loading-spinner row below is itself one more
  // grid item while isLoadingMore is true, so totalItemsCount ticks up the instant a fetch
  // starts. That shifted this threshold just enough to flip nearEnd back to false one frame
  // later, restarting this effect's LaunchedEffect (nearEnd is one of its keys) and cancelling
  // the fetch coroutine mid-flight — logs showed the backend request succeeding with a full
  // page of items that then got thrown away as a cancellation. filteredItems.size is the count
  // of actual content tiles, unaffected by the spinner, so it doesn't move under the request.
  // Keyed on filteredItems.size so the derivedStateOf's closure picks up the current count —
  // remember with no keys would otherwise freeze this on the very first composition's count.
  val nearEnd by remember(filteredItems.size) {
    derivedStateOf {
      val info = gridState.layoutInfo
      val lastVisible = info.visibleItemsInfo.lastOrNull()?.index ?: -1
      filteredItems.isNotEmpty() && lastVisible >= filteredItems.size - 6
    }
  }
  // Shared by the scroll-driven auto-page below and the category screen's explicit footer button.
  suspend fun fetchNextPage() {
    if (isLoadingMore || !canLoadMore) return
    val anchor = row.items.lastOrNull() ?: return
    val loader = onLoadMore ?: return
    isLoadingMore = true
    val skip = uniqueItems.size
    android.util.Log.d("StreamDekPaging", "fetching more row=${row.id} skip=$skip anchorAddon=${anchor.sourceAddonId} anchorCatalog=${anchor.sourceCatalogType}/${anchor.sourceCatalogId}")
    // runCatching catches EVERYTHING, including CancellationException — and this effect gets
    // legitimately cancelled-and-relaunched whenever nearEnd flips (that's the whole point of
    // listing it as a key). Swallowing that cancellation instead of rethrowing it made an
    // in-flight fetch that was cancelled right as it succeeded look identical to "the add-on
    // returned nothing", which is what was permanently disabling further loading after exactly
    // one page. Cancellation must propagate, not be treated as a normal failure.
    val fetched = try {
      loader(row.id, anchor, skip)
    } catch (e: kotlinx.coroutines.CancellationException) {
      isLoadingMore = false
      throw e
    } catch (e: Throwable) {
      android.util.Log.w("StreamDekPaging", "loadMore threw for row=${row.id}", e)
      emptyList()
    }
    val existingKeys = uniqueItems.mapTo(mutableSetOf()) { "${it.type}-${it.id}" }
    val newOnes = fetched.filter { "${it.type}-${it.id}" !in existingKeys }
    android.util.Log.d("StreamDekPaging", "result row=${row.id} fetched=${fetched.size} new=${newOnes.size}")
    if (newOnes.isEmpty()) canLoadMore = false
    isLoadingMore = false
  }
  // isLoadingMore is intentionally NOT a key here: it's mutated inside fetchNextPage, and a
  // LaunchedEffect cancels-and-relaunches itself the instant one of its own keys changes. With
  // it listed as a key, setting it to true immediately restarted this effect, which cancelled
  // the in-flight fetch before it could ever finish and left loading stuck forever — the exact
  // "never loads more" bug. It only needs to be checked (as a re-entrancy guard), not restarted on.
  LaunchedEffect(row.id, nearEnd, canAutoPage) {
    android.util.Log.d("StreamDekPaging", "effect check row=${row.id} nearEnd=$nearEnd canAutoPage=$canAutoPage isLoadingMore=$isLoadingMore canLoadMore=$canLoadMore items=${uniqueItems.size}")
    if (!nearEnd || !canAutoPage) return@LaunchedEffect
    fetchNextPage()
  }
  val pagingScope = rememberCoroutineScope()
  val gridColumns = if (showCategoryGrid) 2 else contentColumns()
  // Playlist VOD entries carry a direct stream URL, which makes isLiveRow true for them as well —
  // they are still titles, not channels.
  val itemNoun = when {
    row.id == "new-episodes" -> "episodes"
    isLiveRow && row.id != "m3u_playlists_vod" -> "channels"
    else -> "titles"
  }
  val headerTitle = selectedCategory ?: row.title
  val headerCount = when {
    showCategoryGrid -> "${categories.size} categories • ${scopedItems.size.formattedItemCount()} $itemNoun"
    isNetworkRow -> "${filteredItems.size.formattedItemCount()} networks"
    else -> "${filteredItems.size.formattedItemCount()} $itemNoun"
  }
  val headerUpAction: (() -> Unit)? = if (selectedCategory != null) ({ selectedCategory = null }) else null

  // Landscape on a tablet has width to spare and very little height, so the header stops being a
  // band across the top and becomes a column down the side: the title, filters and search sit
  // beside the results instead of eating the first third of a short window. Portrait keeps the
  // banner exactly as it is, and no phone reaches this.
  // Only the frosted header has been moved into a column so far; the classic header still draws as
  // a band across the top, and shifting the grid across for it would leave an empty gutter beside a
  // full-width header.
  val sideHeader = LocalWindowSize.current.supportsTwoPanes && modernHeader
  Box(modifier = Modifier.fillMaxSize().background(MaterialTheme.colorScheme.background)) {
    LazyVerticalGrid(
      state = gridState,
      columns = GridCells.Fixed(gridColumns),
      modifier = Modifier
        .fillMaxSize()
        .background(MaterialTheme.colorScheme.background)
        .then(if (modernHeader) Modifier.hazeSource(browseHazeState) else Modifier),
      contentPadding = if (sideHeader) {
        PaddingValues(start = BrowseSideHeaderWidth + 20.dp, end = 20.dp, top = 20.dp, bottom = 126.dp)
      } else {
        PaddingValues(start = 20.dp, end = 20.dp, top = if (modernHeader) modernContentTop else classicContentTop, bottom = 126.dp)
      },
      horizontalArrangement = Arrangement.spacedBy(12.dp),
      verticalArrangement = Arrangement.spacedBy(if (showsList) 6.dp else 18.dp),
    ) {
      if (showCategorizingNotice) {
        item(span = { GridItemSpan(maxLineSpan) }) {
          BrowseCategorizingNotice(itemCount = uniqueItems.size, itemNoun = itemNoun)
        }
      }
      if (showCategoryGrid) {
        if (sourceNames.size > 1) {
          item(span = { GridItemSpan(maxLineSpan) }) {
            BrowseSourceChips(sources = sourceNames, selected = selectedSource, onSelect = { selectedSource = it })
          }
        }
        gridItems(categories, key = { "category-${it.name}" }) { category ->
          BrowseCategoryTile(category = category, itemNoun = itemNoun, onClick = { selectedCategory = category.name })
        }
        if (canLoadMore) {
          item(span = { GridItemSpan(maxLineSpan) }) {
            Box(modifier = Modifier.fillMaxWidth().padding(vertical = 18.dp), contentAlignment = Alignment.Center) {
              if (isLoadingMore) {
                CircularProgressIndicator(modifier = Modifier.size(28.dp), color = MaterialTheme.colorScheme.onBackground.copy(alpha = 0.7f), strokeWidth = 2.5.dp)
              } else {
                TextButton(onClick = { pagingScope.launch { fetchNextPage() } }) {
                  Text("Load more $itemNoun", fontWeight = FontWeight.Bold)
                }
              }
            }
          }
        }
      } else if (filteredItems.isEmpty()) {
        // "Nothing here" would be wrong while the grouping pass is still running.
        if (!showCategorizingNotice) {
          item(span = { GridItemSpan(maxLineSpan) }) {
            LibraryEmptyState(icon = { Icon(Icons.Rounded.Search, null, tint = MaterialTheme.colorScheme.onBackground.copy(alpha = 0.70f), modifier = Modifier.size(54.dp)) }, title = "No titles here", subtitle = "This section does not have matching items for the selected filter.")
          }
        }
      } else {
        gridItems(filteredItems, key = ::mediaCollectionKey) { item ->
          val disabled = isFavouritesRow && addonFor(item)?.enabled == false
          // Long-pressing anywhere on a live row opens the channel menu, so the TV list has to be
          // refreshed for every layout — not just the landscape-card one.
          val openActions: () -> Unit = { actionItem = item; if (isLiveRow) onRefreshHandoffDevices() }
          when {
            showsList -> BrowseListRow(item = item, favourite = isFavourite(item), dimmed = disabled, onClick = { handleOpen(item) }, onLongPress = openActions, networkStyle = if (isNetworkRow) networkCardStyle else null)
            isLiveRow && liveLandscapeCards -> NetworkHomeCard(item = item, sports = true, modifier = Modifier.fillMaxWidth(), dimmed = disabled, favourite = isFavourite(item), onClick = { handleOpen(item) }, onLongPress = openActions)
            isNetworkRow -> NetworkHomeCard(item = item, sports = false, branded = networkCardStyle == NetworkCardStyle.Branded, modifier = Modifier.fillMaxWidth(), dimmed = disabled, favourite = isFavourite(item), onClick = { handleOpen(item) })
            else -> LibraryPosterTile(item = item, modifier = Modifier.alpha(if (disabled) 0.4f else 1f), showMeta = row.id == "new-episodes", favourite = isLiveRow && isFavourite(item), onClick = { handleOpen(item) }, onLongPress = openActions)
          }
        }
        if (isLoadingMore) {
          item(span = { GridItemSpan(maxLineSpan) }) {
            Box(modifier = Modifier.fillMaxWidth().padding(vertical = 20.dp), contentAlignment = Alignment.Center) {
              CircularProgressIndicator(modifier = Modifier.size(28.dp), color = MaterialTheme.colorScheme.onBackground.copy(alpha = 0.7f), strokeWidth = 2.5.dp)
            }
          }
        }
      }
    }

    if (modernHeader) {
      val lightHeader = MaterialTheme.colorScheme.background.luminance() > 0.5f
      Box(
        modifier = Modifier
          .align(if (sideHeader) Alignment.TopStart else Alignment.TopCenter)
          .zIndex(4f)
          .then(if (sideHeader) Modifier.width(BrowseSideHeaderWidth) else Modifier.fillMaxWidth())
          .statusBarsPadding()
          .padding(start = 20.dp, end = 20.dp, top = 12.dp, bottom = 6.dp),
      ) {
        FrostedGlassSurface(
          // As a side column it takes the height its own content needs, rather than the fixed band
          // height that only makes sense across the top.
          modifier = Modifier.fillMaxWidth().then(if (sideHeader) Modifier else Modifier.height(modernHeaderHeight)),
          shape = StreamDekRadius.sheetShape,
          hazeStateOverride = browseHazeState,
          blurRadius = 68f,
          contentPadding = PaddingValues(horizontal = 18.dp, vertical = 14.dp),
          tintAlpha = if (lightHeader) 0.14f else 0.06f,
          borderAlpha = if (lightHeader) 0.10f else 0f,
          baseAlpha = if (lightHeader) 0.28f else 0.08f,
          fillColorOverride = if (lightHeader) null else Color.White,
          showEdgeGradient = false,
        ) {
          BrowseSectionHeaderContent(
            title = headerTitle,
            countLabel = headerCount,
            onUpNavigate = headerUpAction,
            showLayoutToggle = !showCategoryGrid,
            layout = layout,
            onCycleLayout = { layout = nextLayout() },
            selectedFilter = filter,
            showFilters = showHeaderFilters,
            onFilterChange = { filter = it },
            query = query,
            showSearch = showSearch,
            onQueryChange = { query = it },
            showSort = isM3uRow && !showCategoryGrid,
            sortLabel = when (browseSort) {
              BrowseSort.Original -> "Playlist order"
              BrowseSort.TitleAscending -> "A-Z"
              BrowseSort.TitleDescending -> "Z-A"
            },
            onToggleSort = {
              browseSort = when (browseSort) {
                BrowseSort.Original -> BrowseSort.TitleAscending
                BrowseSort.TitleAscending -> BrowseSort.TitleDescending
                BrowseSort.TitleDescending -> BrowseSort.Original
              }
            },
            onClearAll = clearFavouritesAction,
            clearAllDescription = "Clear Live Favourites",
          )
        }
      }
    } else {
      Box(
        modifier = Modifier
          .align(Alignment.TopCenter)
          .zIndex(4f)
          .fillMaxWidth()
          .background(MaterialTheme.colorScheme.background.copy(alpha = 0.98f))
          .statusBarsPadding()
          .padding(horizontal = 20.dp, vertical = 12.dp),
      ) {
        BrowseSectionHeaderContent(
          title = headerTitle,
          countLabel = headerCount,
          onUpNavigate = headerUpAction,
          showLayoutToggle = !showCategoryGrid,
          layout = layout,
          onCycleLayout = { layout = nextLayout() },
          selectedFilter = filter,
          showFilters = showHeaderFilters,
          onFilterChange = { filter = it },
          query = query,
          showSearch = showSearch,
          onQueryChange = { query = it },
          showSort = isM3uRow && !showCategoryGrid,
          sortLabel = when (browseSort) {
            BrowseSort.Original -> "Playlist order"
            BrowseSort.TitleAscending -> "A-Z"
            BrowseSort.TitleDescending -> "Z-A"
          },
          onToggleSort = {
            browseSort = when (browseSort) {
              BrowseSort.Original -> BrowseSort.TitleAscending
              BrowseSort.TitleAscending -> BrowseSort.TitleDescending
              BrowseSort.TitleDescending -> BrowseSort.Original
            }
          },
          onClearAll = clearFavouritesAction,
          clearAllDescription = "Clear Live Favourites",
        )
      }
    }
  }
  actionItem?.let { item ->
    if (isLiveRow) {
      LiveChannelActionsDialog(
        item = item,
        isFavourite = isFavourite(item),
        devices = handoffDevices,
        onToggleFavourite = { onToggleFavourite(item) },
        onRefreshDevices = onRefreshHandoffDevices,
        onHandoff = { device -> onHandoffLive(item, device) },
        onDismiss = { actionItem = null },
      )
    } else {
      MediaCardActionsDialog(
        item = item,
        inWatchlist = watchlistItems.containsMedia(item),
        includeRemoveAction = true,
        onAddToWatchlist = { onToggleWatchlist(item) },
        onRemoveFromWatchlist = { onToggleWatchlist(item) },
        onMarkWatched = { onMarkWatched(item) },
        onDismiss = { actionItem = null },
      )
    }
  }
  disabledAddonPrompt?.let { addon ->
    AlertDialog(
      onDismissRequest = { disabledAddonPrompt = null },
      title = { Text("Add-on disabled") },
      text = { Text("${addon.manifest.name} is currently turned off. Enable it to watch this channel?") },
      confirmButton = {
        Button(onClick = { onEnableAddon(addon); disabledAddonPrompt = null }) { Text("Enable") }
      },
      dismissButton = { TextButton(onClick = { disabledAddonPrompt = null }) { Text("Cancel") } },
    )
  }
}

@Composable
private fun BrowseSectionHeaderContent(
  title: String,
  countLabel: String,
  layout: BrowseLayout,
  onCycleLayout: () -> Unit,
  selectedFilter: MediaFilter,
  showFilters: Boolean,
  onFilterChange: (MediaFilter) -> Unit,
  query: String = "",
  showSearch: Boolean = false,
  onQueryChange: (String) -> Unit = {},
  showSort: Boolean = false,
  sortLabel: String = "",
  onToggleSort: () -> Unit = {},
  onClearAll: (() -> Unit)? = null,
  clearAllDescription: String = "Clear all",
  onUpNavigate: (() -> Unit)? = null,
  showLayoutToggle: Boolean = true,
) {
  Column(modifier = Modifier.fillMaxWidth(), verticalArrangement = Arrangement.spacedBy(10.dp)) {
    Row(modifier = Modifier.fillMaxWidth(), verticalAlignment = Alignment.CenterVertically, horizontalArrangement = Arrangement.spacedBy(12.dp)) {
      // Only shown one level deep (inside a category), where back means "up", not "leave".
      if (onUpNavigate != null) {
        GlassCircleButton(onClick = onUpNavigate) {
          Icon(Icons.AutoMirrored.Rounded.ArrowBack, contentDescription = "All categories", tint = MaterialTheme.colorScheme.onBackground)
        }
      }
      Column(modifier = Modifier.weight(1f), verticalArrangement = Arrangement.spacedBy(3.dp)) {
        AdaptivePageTitle(title = title, maxLines = 2)
        Text(countLabel, color = MaterialTheme.colorScheme.onBackground.copy(alpha = 0.60f), style = MaterialTheme.typography.bodyMedium, fontWeight = FontWeight.Bold)
      }
      if (showSort) {
        TextButton(onClick = onToggleSort) {
          Text(sortLabel, fontWeight = FontWeight.Bold)
        }
      }
      if (onClearAll != null) {
        GlassCircleButton(onClick = onClearAll) {
          Icon(Icons.Rounded.DeleteSweep, contentDescription = clearAllDescription, tint = MaterialTheme.colorScheme.onBackground)
        }
      }
      if (showLayoutToggle) {
        GlassCircleButton(onClick = onCycleLayout) {
          Icon(
            when (layout) {
              BrowseLayout.Cards3 -> Icons.Rounded.ViewAgenda
              BrowseLayout.Cards2 -> Icons.Rounded.ViewModule
              BrowseLayout.List -> Icons.AutoMirrored.Rounded.ViewList
            },
            contentDescription = "Change layout",
            tint = MaterialTheme.colorScheme.onBackground,
          )
        }
      }
    }
    if (showSearch) {
      OutlinedTextField(
        value = query,
        onValueChange = onQueryChange,
        modifier = Modifier.fillMaxWidth(),
        placeholder = { InputGuideText("Search this list") },
        leadingIcon = { Icon(Icons.Rounded.Search, null) },
        trailingIcon = if (query.isNotBlank()) ({ IconButton(onClick = { onQueryChange("") }) { Icon(Icons.Rounded.Close, "Clear") } }) else null,
        singleLine = true,
        shape = StreamDekRadius.cardShape,
      )
    }
    if (showFilters) {
      Row(horizontalArrangement = Arrangement.spacedBy(10.dp)) {
        MediaFilter.values().forEach { option ->
          FilterChip(selected = selectedFilter == option, onClick = { onFilterChange(option) }, label = { Text(if (option == MediaFilter.All) "All" else option.name) })
        }
      }
    }
  }
}
/**
 * Shown while a catalog is being grouped. Sorting a large IPTV playlist takes a visible moment,
 * and an empty screen in that gap reads as "there is nothing here" rather than "working on it".
 * The sweeping bar and cycling dots are what make it read as progress rather than a frozen frame.
 */
@Composable
private fun BrowseCategorizingNotice(itemCount: Int, itemNoun: String) {
  val transition = rememberInfiniteTransition(label = "categorizing")
  val sweep by transition.animateFloat(
    initialValue = 0f,
    targetValue = 1f,
    animationSpec = infiniteRepeatable(tween(1400, easing = LinearEasing), RepeatMode.Restart),
    label = "sweep",
  )
  val dots by transition.animateFloat(
    initialValue = 0f,
    targetValue = 3.99f,
    animationSpec = infiniteRepeatable(tween(1600, easing = LinearEasing), RepeatMode.Restart),
    label = "dots",
  )
  val accent = MaterialTheme.colorScheme.onBackground
  Column(
    modifier = Modifier
      .fillMaxWidth()
      .clip(StreamDekRadius.cardShape)
      .background(accent.copy(alpha = 0.05f))
      .padding(horizontal = 18.dp, vertical = 20.dp),
    verticalArrangement = Arrangement.spacedBy(12.dp),
  ) {
    Row(horizontalArrangement = Arrangement.spacedBy(12.dp), verticalAlignment = Alignment.CenterVertically) {
      CircularProgressIndicator(modifier = Modifier.size(20.dp), color = accent.copy(alpha = 0.75f), strokeWidth = 2.dp)
      Column(verticalArrangement = Arrangement.spacedBy(2.dp)) {
        Text(
          "Sorting into categories" + ".".repeat(dots.toInt()),
          color = accent,
          fontSize = 15.sp,
          fontWeight = FontWeight.Bold,
        )
        Text(
          if (itemCount > 0) "Reading ${itemCount.formattedItemCount()} $itemNoun" else "Reading $itemNoun",
          color = accent.copy(alpha = 0.55f),
          fontSize = 12.sp,
        )
      }
    }
    // Indeterminate sweep: the grouping pass reports no percentage, so a bar that travels is
    // honest about "still working" without inventing progress it does not know.
    Box(modifier = Modifier.fillMaxWidth().height(4.dp).clip(StreamDekRadius.pill).background(accent.copy(alpha = 0.10f))) {
      BoxWithConstraints(modifier = Modifier.fillMaxSize()) {
        val trackWidth = maxWidth
        val barWidth = trackWidth * 0.34f
        Box(
          modifier = Modifier
            .offset(x = (trackWidth + barWidth) * sweep - barWidth)
            .width(barWidth)
            .fillMaxHeight()
            .clip(StreamDekRadius.pill)
            .background(accent.copy(alpha = 0.55f)),
        )
      }
    }
  }
}

/**
 * A category on the Live TV / playlist browse screen. Fixed height so a row of tiles stays even
 * whether the category name wraps to one line or two.
 */
@Composable
private fun BrowseCategoryTile(category: BrowseCategory, itemNoun: String, onClick: () -> Unit) {
  val accent = browseCategoryAccent(category.name)
  Column(
    modifier = Modifier
      .fillMaxWidth()
      .height(132.dp)
      .clip(StreamDekRadius.cardShape)
      .background(MaterialTheme.colorScheme.onBackground.copy(alpha = 0.05f))
      .clickable(onClick = onClick)
      .padding(14.dp),
    verticalArrangement = Arrangement.SpaceBetween,
  ) {
    Box(
      modifier = Modifier.size(40.dp).clip(StreamDekRadius.controlShape).background(accent.copy(alpha = 0.18f)),
      contentAlignment = Alignment.Center,
    ) {
      Icon(browseCategoryIcon(category.name), contentDescription = null, tint = accent, modifier = Modifier.size(21.dp))
    }
    Column(verticalArrangement = Arrangement.spacedBy(2.dp)) {
      Text(
        category.name,
        color = MaterialTheme.colorScheme.onBackground,
        fontSize = 15.sp,
        lineHeight = 18.sp,
        fontWeight = FontWeight.Bold,
        maxLines = 2,
        overflow = TextOverflow.Ellipsis,
      )
      Text(
        "${category.items.size.formattedItemCount()} $itemNoun",
        color = MaterialTheme.colorScheme.onBackground.copy(alpha = 0.55f),
        fontSize = 12.sp,
        maxLines = 1,
      )
    }
  }
}

/** Playlist/add-on picker shown above the categories when the row draws on more than one source. */
@Composable
private fun BrowseSourceChips(sources: List<String>, selected: String?, onSelect: (String?) -> Unit) {
  Row(
    modifier = Modifier.fillMaxWidth().horizontalScroll(rememberScrollState()).padding(bottom = 2.dp),
    horizontalArrangement = Arrangement.spacedBy(8.dp),
  ) {
    FilterChip(selected = selected == null, onClick = { onSelect(null) }, label = { Text("All sources") })
    sources.forEach { name ->
      FilterChip(
        selected = selected == name,
        onClick = { onSelect(if (selected == name) null else name) },
        label = { Text(name, maxLines = 1, overflow = TextOverflow.Ellipsis) },
      )
    }
  }
}

@Composable
private fun NetworkHomeCard(item: MediaItem, sports: Boolean = false, branded: Boolean = false, modifier: Modifier = Modifier.width(LocalHomeLayout.current.card(176.dp)), dimmed: Boolean = false, favourite: Boolean = false, onClick: () -> Unit, onLongPress: () -> Unit = {}) {
  // Relaxed everywhere except inside Home, so the Browse grid — which passes its own width and
  // shares this card — is untouched by the density setting.
  val home = LocalHomeLayout.current
  // Live channels borrow this card for their landscape artwork and are not services, so the
  // branded treatment is a networks-row decision only.
  val brandedNetwork = branded && !sports
  val tile = if (brandedNetwork) networkTileArt(item) else null
  // The bundled logo beats the one the row supplied: that one is a provider-list thumbnail from
  // TMDB, and its softness shows at card size. Null for a service none ships for, which is when
  // the fetched logo is still the best picture available.
  val logo = if (sports) null else networkLogoArt(item)
  // Artwork fills the tile; a bare logo is fitted inside it with room to breathe. A branded row
  // with no bundled tile for one service keeps that service on the white logo card rather than
  // dropping a logo drawn for white -- dark ink on transparency -- onto a dark surface.
  val fullBleed = tile != null || sports
  Column(
    modifier = modifier.alpha(if (dimmed) 0.4f else 1f),
    horizontalAlignment = Alignment.CenterHorizontally,
    verticalArrangement = Arrangement.spacedBy(home.card(9.dp)),
  ) {
    Box(
      modifier = Modifier
        .fillMaxWidth()
        .height(home.card(104.dp))
        .clip(StreamDekRadius.panelShape)
        .background(if (tile != null) Color(0xFF0E0E0E) else if (sports) Color(0xFF171717) else Color.White)
        .border(1.dp, if (tile != null) Color.White.copy(alpha = 0.10f) else Color.Black.copy(alpha = 0.08f), StreamDekRadius.panelShape)
        .pressable(item.id, item.type, onClick = onClick, onLongPress = onLongPress)
        // A fitted logo needs its breathing room scaled with the tile, or a Compact card would sit
        // a full-size margin around a four-fifths wordmark and read as a mistake.
        .padding(horizontal = if (fullBleed) 0.dp else home.card(22.dp), vertical = if (fullBleed) 0.dp else home.card(12.dp)),
      contentAlignment = Alignment.Center,
    ) {
      AsyncImage(
        model = tile ?: logo ?: if (sports) item.backdrop ?: item.poster else item.poster,
        contentDescription = item.title,
        modifier = Modifier.fillMaxSize(),
        contentScale = if (fullBleed) ContentScale.Crop else ContentScale.Fit,
      )
      if (favourite) FavouriteChannelBadge(modifier = Modifier.align(Alignment.TopEnd))
    }
    // The tile artwork is the service's own wordmark, so a caption under it only repeats it. The
    // caption is dropped for every card in a branded row, not only the ones that found a tile,
    // because a row of cards at two different heights reads as a mistake.
    if (!brandedNetwork) {
      Text(
        item.title,
        color = MaterialTheme.colorScheme.onBackground,
        style = home.text(MaterialTheme.typography.bodyMedium),
        fontWeight = FontWeight.SemiBold,
        maxLines = 1,
        overflow = TextOverflow.Ellipsis,
        textAlign = androidx.compose.ui.text.style.TextAlign.Center,
        modifier = Modifier.fillMaxWidth(),
      )
    }
  }
}

@Composable
private fun HomeStrip(rowId: String, title: String, items: List<MediaItem>, continueWatchingStyle: ContinueWatchingStyle, networkCardStyle: NetworkCardStyle = NetworkCardStyle.Branded, liveLandscapeCards: Boolean, newEpisodesLandscape: Boolean = true, watchlistItems: List<MediaItem>, favouriteItems: List<MediaItem> = emptyList(), addons: List<InstalledAddon> = emptyList(), handoffDevices: List<LinkedTvDevice> = emptyList(), onRefreshHandoffDevices: () -> Unit = {}, onHandoffLive: suspend (MediaItem, LinkedTvDevice) -> Result<PlaybackHandoffReceipt> = { _, _ -> Result.failure(IllegalStateException("Handoff is unavailable.")) }, onHandoffContinueWatching: suspend (MediaItem, LinkedTvDevice) -> Result<PlaybackHandoffReceipt> = { _, _ -> Result.failure(IllegalStateException("Handoff is unavailable.")) }, onOpen: (MediaItem) -> Unit, onViewAll: () -> Unit, onToggleWatchlist: (MediaItem) -> Unit, onToggleFavourite: (MediaItem) -> Unit = {}, onEnableAddon: (InstalledAddon) -> Unit = {}, onMarkWatched: (MediaItem) -> Unit, onMarkEarlierEpisodesWatched: (MediaItem) -> Unit, onRestartFromBeginning: (MediaItem) -> Unit, onRemoveFromContinueWatching: (MediaItem) -> Unit = {}, onPlayContinueWatching: (MediaItem) -> Unit) {
  fun isFavourite(item: MediaItem): Boolean = favouriteItems.hasFavouriteChannel(item)
  val isAddonRow = rowId.startsWith("addon:")
  val isFavouritesRow = rowId == "favourites"
  val isSportsRow = title.contains("sport", ignoreCase = true) || title.contains("live", ignoreCase = true) || items.any(MediaItem::isLiveCatalogItem)
  var actionItem by remember { mutableStateOf<MediaItem?>(null) }
  var disabledAddonPrompt by remember { mutableStateOf<InstalledAddon?>(null) }
  fun addonFor(item: MediaItem): InstalledAddon? = item.sourceAddonId?.let { id -> addons.firstOrNull { it.id == id } }
  fun handleOpen(item: MediaItem) {
    val addon = if (isFavouritesRow) addonFor(item) else null
    if (addon != null && !addon.enabled) {
      disabledAddonPrompt = addon
    } else {
      onOpen(item)
    }
  }
  val home = LocalHomeLayout.current
  Column(verticalArrangement = Arrangement.spacedBy(home.rowHeaderGap)) {
    Column(
      modifier = Modifier.padding(horizontal = home.rowSideInset),
      verticalArrangement = Arrangement.spacedBy(home.rowHeaderTitleGap),
    ) {
      Row(modifier = Modifier.fillMaxWidth(), horizontalArrangement = Arrangement.SpaceBetween, verticalAlignment = Alignment.CenterVertically) {
        Text(title, fontSize = if (isAddonRow) home.addonRowTitleSize else home.rowTitleSize, fontWeight = if (isAddonRow) FontWeight.Bold else FontWeight.ExtraBold, color = MaterialTheme.colorScheme.onBackground, modifier = Modifier.weight(1f), maxLines = 1, overflow = TextOverflow.Ellipsis)
        TextButton(onClick = onViewAll) { Text("View All", color = MaterialTheme.colorScheme.onBackground.copy(alpha = 0.78f), fontWeight = FontWeight.Bold) }
      }
      if (home.showRowAccentBar) {
        Box(
          modifier = Modifier
            .width(if (rowId == "continue") 102.dp else if (isAddonRow) 56.dp else 68.dp)
            .height(7.dp)
            .clip(StreamDekRadius.pill)
            .background(MaterialTheme.colorScheme.onBackground.copy(alpha = if (rowId == "continue") 0.96f else if (isAddonRow) 0.24f else 0.32f)),
        )
      }
    }
    LazyRow(
      contentPadding = PaddingValues(horizontal = home.rowSideInset),
      horizontalArrangement = Arrangement.spacedBy(home.cardGap),
    ) {
      items(items, key = ::mediaCollectionKey) { item ->
        val disabled = isFavouritesRow && addonFor(item)?.enabled == false
        if (rowId == "continue") {
          ContinueWatchingCard(item = item, style = continueWatchingStyle, onClick = { onPlayContinueWatching(item) }, onLongPress = { actionItem = item; onRefreshHandoffDevices() })
        } else if (rowId == "streaming_networks" || (isSportsRow && liveLandscapeCards)) {
          NetworkHomeCard(item = item, sports = isSportsRow, branded = networkCardStyle == NetworkCardStyle.Branded, dimmed = disabled, favourite = isFavourite(item), onClick = { handleOpen(item) }, onLongPress = { if (isSportsRow) { actionItem = item; onRefreshHandoffDevices() } })
        } else {
          PosterCard(item = item, dimmed = disabled, landscape = rowId == "new-episodes" && newEpisodesLandscape, onClick = { handleOpen(item) }, onLongPress = { actionItem = item; if (isSportsRow) onRefreshHandoffDevices() })
        }
      }
    }
  }
  actionItem?.let { item ->
    if (isSportsRow) {
      LiveChannelActionsDialog(
        item = item,
        isFavourite = isFavourite(item),
        devices = handoffDevices,
        onToggleFavourite = { onToggleFavourite(item) },
        onRefreshDevices = onRefreshHandoffDevices,
        onHandoff = { device -> onHandoffLive(item, device) },
        onDismiss = { actionItem = null },
      )
    } else if (rowId == "continue") {
      ContinueWatchingActionsDialog(
        item = item,
        inWatchlist = watchlistItems.containsMedia(item),
        onRestartFromBeginning = { onRestartFromBeginning(item) },
        onOpenDetails = { onOpen(item) },
        onAddToWatchlist = { onToggleWatchlist(item) },
        onMarkWatched = { onMarkWatched(item) },
        onMarkEarlierEpisodesWatched = { onMarkEarlierEpisodesWatched(item) },
        onRemoveFromContinueWatching = { onRemoveFromContinueWatching(item) },
        onDismiss = { actionItem = null },
        handoffDevices = handoffDevices,
        onRefreshHandoffDevices = onRefreshHandoffDevices,
        onHandoffToTv = { device -> onHandoffContinueWatching(item, device) },
      )
    } else {
      MediaCardActionsDialog(
        item = item,
        inWatchlist = watchlistItems.containsMedia(item),
        includeRemoveAction = false,
        onAddToWatchlist = { onToggleWatchlist(item) },
        onRemoveFromWatchlist = { onToggleWatchlist(item) },
        onMarkWatched = { onMarkWatched(item) },
        onDismiss = { actionItem = null },
      )
    }
  }
  disabledAddonPrompt?.let { addon ->
    AlertDialog(
      onDismissRequest = { disabledAddonPrompt = null },
      title = { Text("Add-on disabled") },
      text = { Text("${addon.manifest.name} is currently turned off. Enable it to watch this channel?") },
      confirmButton = {
        Button(onClick = { onEnableAddon(addon); disabledAddonPrompt = null }) { Text("Enable") }
      },
      dismissButton = { TextButton(onClick = { disabledAddonPrompt = null }) { Text("Cancel") } },
    )
  }
}

@Composable
private fun LibraryHeaderPanel(

  title: String,
  count: Int? = null,
  note: String? = null,
  selectedFilter: MediaFilter,
  onFilterChange: (MediaFilter) -> Unit,
  actionIcon: ImageVector,
  actionLabel: String,
  onAction: () -> Unit,
  searchQuery: String? = null,
  onSearchQueryChange: ((String) -> Unit)? = null,
  modifier: Modifier = Modifier,
) {
  FrostedGlassSurface(
    modifier = modifier.fillMaxWidth(),
    shape = StreamDekRadius.sheetShape,
    blurRadius = 48f,
    contentPadding = PaddingValues(18.dp),
    tintAlpha = 0.17f,
    borderAlpha = 0.22f,
  ) {
    Column(modifier = Modifier.fillMaxWidth(), verticalArrangement = Arrangement.spacedBy(18.dp)) {
    Row(modifier = Modifier.fillMaxWidth(), horizontalArrangement = Arrangement.SpaceBetween, verticalAlignment = Alignment.CenterVertically) {
      Text(title, style = MaterialTheme.typography.headlineMedium, fontWeight = FontWeight.Black, color = MaterialTheme.colorScheme.onBackground)
      Row(horizontalArrangement = Arrangement.spacedBy(10.dp), verticalAlignment = Alignment.CenterVertically) {
        count?.let { GlassPill("$it titles") }
        GlassCircleButton(modifier = Modifier.size(52.dp), onClick = onAction) {
          Icon(actionIcon, contentDescription = actionLabel, tint = MaterialTheme.colorScheme.onBackground, modifier = Modifier.size(22.dp))
        }
      }
    }
    if (searchQuery != null && onSearchQueryChange != null) {
      OutlinedTextField(
        value = searchQuery,
        onValueChange = onSearchQueryChange,
        modifier = Modifier.fillMaxWidth(),
        placeholder = { InputGuideText("Search movies & TV series...") },
        leadingIcon = { Icon(Icons.Rounded.Search, contentDescription = null) },
        singleLine = true,
        shape = StreamDekRadius.panelShape,
        colors = androidx.compose.material3.TextFieldDefaults.colors(
          focusedContainerColor = MaterialTheme.colorScheme.onBackground.copy(alpha = 0.08f),
          unfocusedContainerColor = MaterialTheme.colorScheme.onBackground.copy(alpha = 0.06f),
          focusedIndicatorColor = Color.Transparent,
          unfocusedIndicatorColor = Color.Transparent,
          cursorColor = MaterialTheme.colorScheme.onBackground,
          focusedTextColor = MaterialTheme.colorScheme.onBackground,
          unfocusedTextColor = MaterialTheme.colorScheme.onBackground,
          focusedLeadingIconColor = MaterialTheme.colorScheme.onBackground.copy(alpha = 0.92f),
          unfocusedLeadingIconColor = MaterialTheme.colorScheme.onBackground.copy(alpha = 0.72f),
          focusedPlaceholderColor = MaterialTheme.colorScheme.onBackground.copy(alpha = 0.46f),
          unfocusedPlaceholderColor = MaterialTheme.colorScheme.onBackground.copy(alpha = 0.46f),
        ),
      )
    }
    Row(horizontalArrangement = Arrangement.spacedBy(10.dp)) {
      MediaFilter.values().forEach { filter ->
        FilterChip(
          selected = selectedFilter == filter,
          onClick = { onFilterChange(filter) },
          label = { Text(if (filter == MediaFilter.All) "All" else filter.name) },
        )
      }
    }
    note?.let { Text(it, color = MaterialTheme.colorScheme.onBackground.copy(alpha = 0.58f), style = MaterialTheme.typography.bodyLarge) }
    }
  }
}

/**
 * One catalog an installed add-on offers, presented as a Discover source.
 *
 * Holds the add-on rather than just its id because paging a catalog needs the whole record (a
 * local add-on is fetched straight from the device, a hosted one through its transport URL).
 */
private data class AddonDiscoverSource(
  val key: String,
  val addon: InstalledAddon,
  val catalog: AddonCatalog,
  /** "Add-on · Catalog", for the picker where there is room to disambiguate two add-ons that
   * both call a catalog something generic like "Search". */
  val label: String,
  /** Just the catalog name, for the filter row. The full label is far too long there - it
   * ellipsised to "Xperience · To…", which told the user nothing about what was selected. */
  val shortLabel: String,
)

/** Section heading for playlist results, with a count so a capped list does not look like the
 * whole answer. */
@Composable
private fun PlaylistResultsHeader(title: String, count: Int) {
  Column(
    modifier = Modifier.fillMaxWidth().padding(horizontal = 16.dp, vertical = 6.dp),
    verticalArrangement = Arrangement.spacedBy(2.dp),
  ) {
    Text(title, style = MaterialTheme.typography.titleMedium, fontWeight = FontWeight.Bold, color = MaterialTheme.colorScheme.onBackground)
    Text(
      if (count >= PLAYLIST_SEARCH_LIMIT) "Top $count matches" else "$count ${if (count == 1) "match" else "matches"}",
      style = MaterialTheme.typography.bodySmall,
      color = MaterialTheme.colorScheme.onBackground.copy(alpha = 0.58f),
    )
  }
}

/** How many playlist matches one section will show. A provider list can match thousands of
 * entries for a short query, and past a screenful the rest is noise. */
internal const val PLAYLIST_SEARCH_LIMIT = 60

/**
 * True when [needle] starts a word in this string.
 *
 * Uses case-insensitive indexOf rather than lowercasing, because this runs once per playlist entry
 * per keystroke and a 200k-entry list would otherwise allocate 200k throwaway strings each time.
 */
internal fun String.containsWordStart(needle: String): Boolean {
  var index = indexOf(needle, ignoreCase = true)
  while (index >= 0) {
    if (index == 0 || !this[index - 1].isLetterOrDigit()) return true
    index = indexOf(needle, index + 1, ignoreCase = true)
  }
  return false
}

/**
 * How well a playlist entry answers [needle], lower being better, or null when it does not.
 *
 * Ranked by *how* the match was made rather than by position alone, so searching "bbc" puts the
 * channel called "BBC One" above a film whose category merely happens to mention it.
 */
internal fun MediaItem.playlistSearchRank(needle: String): Int? = when {
  title.equals(needle, ignoreCase = true) -> 0
  title.startsWith(needle, ignoreCase = true) -> 1
  title.containsWordStart(needle) -> 2
  title.contains(needle, ignoreCase = true) -> 3
  sourceCatalogName?.contains(needle, ignoreCase = true) == true -> 4
  else -> null
}

/**
 * The best [limit] entries for [query], already ordered.
 *
 * Deliberately searches the title and category only. Playlist descriptions are built from the
 * group and source name, so matching them too would make almost every entry in a category match
 * any word from its name.
 */
internal fun List<MediaItem>.matchingPlaylistItems(query: String, limit: Int = PLAYLIST_SEARCH_LIMIT): List<MediaItem> {
  val needle = query.trim()
  if (needle.length < 2) return emptyList()
  val ranked = ArrayList<Pair<Int, MediaItem>>()
  for (item in this) {
    val rank = item.playlistSearchRank(needle) ?: continue
    ranked.add(rank to item)
  }
  return ranked
    .sortedWith(compareBy({ it.first }, { it.second.title.lowercase() }))
    .take(limit)
    .map { it.second }
}

private fun List<MediaItem>.filteredBy(filter: MediaFilter): List<MediaItem> = when (filter) {
  MediaFilter.All -> this
  MediaFilter.Movies -> filter { it.type == "movie" }
  MediaFilter.Series -> filter { it.type == "tv" || it.type == "series" }
}

