    CardActionsAmbientScaffold(item = item, onDismiss = onDismiss) {
      if (!choosingTv) {
        AmbientActionRow(if (isFavourite) "Remove from Favourites" else "Add to Favourites", icon = if (isFavourite) Icons.Rounded.Close else Icons.Rounded.Star) {
          onToggleFavourite()
          onDismiss()
