      .clickable(onClick = onClick)
      .padding(vertical = 14.dp, horizontal = 12.dp),
    horizontalArrangement = Arrangement.SpaceBetween,
    verticalAlignment = Alignment.CenterVertically,
  ) {
    Text(label, color = Color.White, style = MaterialTheme.typography.bodyLarge, fontWeight = FontWeight.Medium)
    Icon(icon, contentDescription = null, tint = Color.White.copy(alpha = 0.85f))
  }
}

@Composable
private fun MediaGrid(
  items: List<MediaItem>,
  onOpen: (MediaItem) -> Unit,
  columns: Int = 3,
  showMeta: Boolean = true,
  onToggleWatchlist: ((MediaItem) -> Unit)? = null,
  watchlistItems: List<MediaItem> = emptyList(),
  includeRemoveAction: Boolean = false,
  onMarkWatched: ((MediaItem) -> Unit)? = null,
  onMarkEarlierEpisodesWatched: ((MediaItem) -> Unit)? = null,
  continueWatchingActions: Boolean = false,
  onRestartFromBeginning: ((MediaItem) -> Unit)? = null,
  onRemoveFromContinueWatching: ((MediaItem) -> Unit)? = null,
  onOpenDetails: ((MediaItem) -> Unit)? = null,
  handoffDevices: List<LinkedTvDevice> = emptyList(),
  onRefreshHandoffDevices: () -> Unit = {},
  onHandoffToTv: (suspend (MediaItem, LinkedTvDevice) -> Result<PlaybackHandoffReceipt>)? = null,
) {
  var actionItem by remember { mutableStateOf<MediaItem?>(null) }
  // `columns` is the density the viewer picked with the grid toggle. On a phone it is used as-is;
  // on anything wider it is read as a card size and turned into however many of those fit, so extra
  // width shows more artwork instead of inflating each poster.
  val gridColumns = adaptiveMediaColumns(columns)
  val gridGap = LocalStreamDekSpacing.current.gridGap
  Column(modifier = Modifier.fillMaxWidth().padding(horizontal = 8.dp), verticalArrangement = Arrangement.spacedBy(18.dp)) {
    items.chunked(gridColumns).forEach { row ->
      Row(horizontalArrangement = Arrangement.spacedBy(gridGap), modifier = Modifier.fillMaxWidth()) {
        row.forEach { item ->
          LibraryPosterTile(item = item, modifier = Modifier.weight(1f), showMeta = showMeta, onClick = { onOpen(item) }, onLongPress = { actionItem = item; if (continueWatchingActions) onRefreshHandoffDevices() })
        }
        repeat(gridColumns - row.size) { Spacer(modifier = Modifier.weight(1f)) }
      }
    }
  }
  actionItem?.let { item ->
    if (continueWatchingActions && onRestartFromBeginning != null) {
      val handoffForItem: (suspend (LinkedTvDevice) -> Result<PlaybackHandoffReceipt>)? =
        if (onHandoffToTv == null) null else { device -> onHandoffToTv(item, device) }
      ContinueWatchingActionsDialog(
        item = item,
        inWatchlist = watchlistItems.containsMedia(item),
        onRestartFromBeginning = { onRestartFromBeginning(item) },
        onOpenDetails = { (onOpenDetails ?: onOpen)(item) },
        onAddToWatchlist = { onToggleWatchlist?.invoke(item) },
        onMarkWatched = { onMarkWatched?.invoke(item) },
        onMarkEarlierEpisodesWatched = onMarkEarlierEpisodesWatched?.let { markEarlier -> { markEarlier(item) } },
        onRemoveFromContinueWatching = onRemoveFromContinueWatching?.let { remove -> { remove(item) } },
        onDismiss = { actionItem = null },
        handoffDevices = handoffDevices,
        onRefreshHandoffDevices = onRefreshHandoffDevices,
        onHandoffToTv = handoffForItem,
      )
    } else {
      MediaCardActionsDialog(
        item = item,
        inWatchlist = watchlistItems.containsMedia(item),
        includeRemoveAction = includeRemoveAction,
        onAddToWatchlist = { onToggleWatchlist?.invoke(item) },
        onRemoveFromWatchlist = { onToggleWatchlist?.invoke(item) },
        onMarkWatched = { onMarkWatched?.invoke(item) },
        onDismiss = { actionItem = null },
      )
    }
  }
}

@Composable
private fun SearchGridSkeleton(columns: Int, rows: Int = 3) {
  // Mirrors the MediaGrid poster layout so the loading state matches the results.
  Column(modifier = Modifier.fillMaxWidth().padding(horizontal = 8.dp), verticalArrangement = Arrangement.spacedBy(18.dp)) {
    repeat(rows) {
      Row(horizontalArrangement = Arrangement.spacedBy(12.dp), modifier = Modifier.fillMaxWidth()) {
        repeat(columns) {
          SkeletonBlock(modifier = Modifier.weight(1f).aspectRatio(0.68f), radius = 16.dp)
        }
      }
    }
  }
}

@Composable
private fun LibraryPosterTile(item: MediaItem, modifier: Modifier = Modifier, showMeta: Boolean = true, favourite: Boolean = false, onClick: () -> Unit, onLongPress: () -> Unit = {}) {
  Column(
    modifier = modifier.fillMaxWidth().clip(StreamDekRadius.thumbShape).background(MaterialTheme.colorScheme.surface).border(1.dp, MaterialTheme.colorScheme.onBackground.copy(alpha = 0.10f), StreamDekRadius.thumbShape).pressable(item.id, item.type, onClick = onClick, onLongPress = onLongPress),
  ) {
    Box(modifier = Modifier.fillMaxWidth().aspectRatio(0.68f)) {
      AsyncImage(model = item.poster ?: item.backdrop, contentDescription = item.title, modifier = Modifier.fillMaxSize(), contentScale = ContentScale.Crop)
      CardImdbRatingBadge(rating = item.rating)
      if (favourite) FavouriteChannelBadge(modifier = Modifier.align(Alignment.TopEnd))
      Box(modifier = Modifier.align(Alignment.BottomStart).fillMaxWidth().height(4.dp).background(MaterialTheme.colorScheme.onBackground.copy(alpha = 0.055f))) {
        Box(modifier = Modifier.fillMaxWidth(((item.progress ?: 0.0) / 100.0).toFloat().coerceIn(0f, 1f)).height(4.dp).background(Color(0xFF22C55E)))
      }
    }
    if (showMeta) {
      Column(modifier = Modifier.fillMaxWidth().height(72.dp).padding(10.dp), verticalArrangement = Arrangement.spacedBy(5.dp)) {
        Text(item.title, maxLines = 2, overflow = TextOverflow.Ellipsis, fontWeight = FontWeight.SemiBold, fontSize = 12.sp, lineHeight = 16.sp)
        Row(modifier = Modifier.fillMaxWidth(), horizontalArrangement = Arrangement.SpaceBetween) {
          Text(
            item.cardSubtitle ?: item.year ?: item.type.replaceFirstChar(Char::uppercase),
            color = if (item.cardHighlight) MaterialTheme.colorScheme.primary else MaterialTheme.colorScheme.onBackground.copy(alpha = 0.54f),
            fontWeight = if (item.cardHighlight) FontWeight.Bold else FontWeight.Normal,
            maxLines = 1,
            overflow = TextOverflow.Ellipsis,
            fontSize = 11.sp,
          )
          item.progress?.takeIf { it > 0.0 }?.let { Text("${it.toInt()}%", color = Color(0xFF22C55E), fontWeight = FontWeight.Bold, fontSize = 10.sp) }
        }
      }
    }
  }
}

/** The star that marks a channel as favourited, shared by every card and list layout. */
@Composable
private fun FavouriteChannelBadge(modifier: Modifier = Modifier, size: Dp = 23.dp) {
  Box(
    modifier = modifier.padding(7.dp).size(size).clip(CircleShape).background(Color.Black.copy(alpha = 0.55f)),
    contentAlignment = Alignment.Center,
  ) {
    Icon(Icons.Rounded.Star, contentDescription = "Favourite channel", tint = Color(0xFFFACC15), modifier = Modifier.size(size * 0.6f))
  }
}

/**
 * Compact text row for the "View All" list layout. IPTV catalogs run to thousands of channels
 * whose logos are near-identical, so this keeps the name readable and the row height small while
 * still carrying the favourite star and the same long-press menu as the card layouts.
 */
@Composable
private fun BrowseListRow(
  item: MediaItem,
  favourite: Boolean,
  dimmed: Boolean,
  onClick: () -> Unit,
  onLongPress: () -> Unit,
  /**
   * Set for a streaming-networks row, and null everywhere else.
   *
   * A network is recognised by its wordmark, not by its name, and the square 44dp thumbnail below
   * was cropping a landscape card down to a centre square - which for most services cuts the
   * wordmark in half. When this is set the row leads with a miniature of the same card the grid
   * draws, in whichever style is currently selected, so switching Classic/Branded changes the list
   * and the grid together instead of only the grid.
   */
  networkStyle: NetworkCardStyle? = null,
) {
  val subtitle = listOfNotNull(
    item.cardSubtitle?.takeIf { it.isNotBlank() },
    item.sourceCatalogGenre?.takeIf { it.isNotBlank() },
    item.sourceCatalogName?.takeIf { it.isNotBlank() },
    item.year?.takeIf { it.isNotBlank() },
  ).firstOrNull()
  Row(
    modifier = Modifier
      .fillMaxWidth()
      .alpha(if (dimmed) 0.4f else 1f)
      .clip(StreamDekRadius.thumbShape)
      .background(MaterialTheme.colorScheme.onBackground.copy(alpha = 0.045f))
      .pressable(item.id, item.type, onClick = onClick, onLongPress = onLongPress)
      .padding(horizontal = 12.dp, vertical = 10.dp),
    horizontalArrangement = Arrangement.spacedBy(12.dp),
    verticalAlignment = Alignment.CenterVertically,
  ) {
    if (networkStyle != null) {
      // Same decisions as NetworkHomeCard, at list scale: the bundled tile is a full-bleed
      // wordmark on its own dark ground, while a bare logo is drawn for white and has to be fitted
      // with padding rather than cropped. Branded falls back to the logo card for any service that
      // ships no tile, exactly as the grid does.
      val tile = if (networkStyle == NetworkCardStyle.Branded) networkTileArt(item) else null
      val logo = networkLogoArt(item)
      val fullBleed = tile != null
      Box(
        modifier = Modifier
          .width(76.dp)
          .height(44.dp)
          .clip(StreamDekRadius.controlShape)
          .background(if (fullBleed) Color(0xFF0E0E0E) else Color.White)
          .border(1.dp, if (fullBleed) Color.White.copy(alpha = 0.10f) else Color.Black.copy(alpha = 0.08f), StreamDekRadius.controlShape)
          .padding(horizontal = if (fullBleed) 0.dp else 8.dp, vertical = if (fullBleed) 0.dp else 6.dp),
        contentAlignment = Alignment.Center,
      ) {
        AsyncImage(
          model = tile ?: logo ?: item.poster,
          contentDescription = item.title,
          modifier = Modifier.fillMaxSize(),
          contentScale = if (fullBleed) ContentScale.Crop else ContentScale.Fit,
        )
      }
    } else {
      Box(
        modifier = Modifier.size(44.dp).clip(StreamDekRadius.controlShape).background(MaterialTheme.colorScheme.onBackground.copy(alpha = 0.08f)),
        contentAlignment = Alignment.Center,
      ) {
        val artwork = item.poster ?: item.backdrop
        if (artwork != null) {
          AsyncImage(model = artwork, contentDescription = null, modifier = Modifier.fillMaxSize(), contentScale = ContentScale.Crop)
        } else {
          Icon(Icons.Rounded.LiveTv, contentDescription = null, tint = MaterialTheme.colorScheme.onBackground.copy(alpha = 0.5f), modifier = Modifier.size(20.dp))
        }
      }
    }
    Column(modifier = Modifier.weight(1f), verticalArrangement = Arrangement.spacedBy(2.dp)) {
      Text(
        item.title,
        color = MaterialTheme.colorScheme.onBackground,
        fontWeight = FontWeight.SemiBold,
        fontSize = 14.sp,
        maxLines = 1,
        overflow = TextOverflow.Ellipsis,
      )
      subtitle?.let {
        Text(it, color = MaterialTheme.colorScheme.onBackground.copy(alpha = 0.56f), fontSize = 11.sp, maxLines = 1, overflow = TextOverflow.Ellipsis)
      }
    }
    if (favourite) {
      Icon(Icons.Rounded.Star, contentDescription = "Favourite channel", tint = Color(0xFFFACC15), modifier = Modifier.size(18.dp))
    }
  }
}

@Composable
private fun LibraryStreamDekHeader(
  title: String,
  subtitle: String,
  count: Int,
  selectedFilter: MediaFilter,
  onFilterChange: (MediaFilter) -> Unit,
  columns: Int,
  onToggleColumns: () -> Unit,
  style: HeaderStyle,
  hazeState: HazeState,
  modifier: Modifier = Modifier,
  trailingAction: (@Composable () -> Unit)? = null,
) {
  val content: @Composable BoxScope.() -> Unit = {
    Column(modifier = Modifier.fillMaxWidth(), verticalArrangement = Arrangement.spacedBy(8.dp)) {
      Row(modifier = Modifier.fillMaxWidth(), horizontalArrangement = Arrangement.SpaceBetween, verticalAlignment = Alignment.CenterVertically) {
        Column(verticalArrangement = Arrangement.spacedBy(4.dp)) {
          AdaptivePageTitle(title = title, maxLines = 2)
          if (subtitle.isNotBlank()) Text(subtitle, style = MaterialTheme.typography.bodyMedium, color = MaterialTheme.colorScheme.onBackground.copy(alpha = 0.64f))
        }
        Row(horizontalArrangement = Arrangement.spacedBy(10.dp), verticalAlignment = Alignment.CenterVertically) {
          Box(modifier = Modifier.clip(StreamDekRadius.pill).background(MaterialTheme.colorScheme.surfaceVariant.copy(alpha = 0.72f)).padding(horizontal = 12.dp, vertical = 7.dp)) {
            Text("$count titles", color = MaterialTheme.colorScheme.onBackground.copy(alpha = 0.82f), fontSize = 12.sp, fontWeight = FontWeight.Bold)
          }
          trailingAction?.invoke()
          GlassCircleButton(onClick = onToggleColumns) {
            Icon(if (columns == 3) Icons.Rounded.ViewAgenda else Icons.Rounded.ViewModule, contentDescription = null, tint = MaterialTheme.colorScheme.onBackground)
          }
        }
      }
      Row(horizontalArrangement = Arrangement.spacedBy(10.dp)) {
        MediaFilter.values().forEach { value ->
          FilterChip(selected = selectedFilter == value, onClick = { onFilterChange(value) }, label = { Text(if (value == MediaFilter.All) "All" else value.name) })
        }
      }
    }
  }
  if (style == HeaderStyle.Modern) {
    val lightHeader = MaterialTheme.colorScheme.background.luminance() > 0.5f
    Box(modifier = modifier.fillMaxWidth().statusBarsPadding().padding(start = 8.dp, end = 8.dp, top = 12.dp, bottom = 6.dp)) {
      FrostedGlassSurface(
        modifier = Modifier.fillMaxWidth().height(152.dp),
        shape = StreamDekRadius.sheetShape,
        hazeStateOverride = hazeState,
        blurRadius = 68f,
        contentPadding = PaddingValues(horizontal = 18.dp, vertical = 16.dp),
        tintAlpha = if (lightHeader) 0.14f else 0.06f,
        borderAlpha = if (lightHeader) 0.10f else 0f,
        baseAlpha = if (lightHeader) 0.28f else 0.08f,
        fillColorOverride = if (lightHeader) null else Color.White,
        showEdgeGradient = false,
        content = content,
      )
    }
  } else {
    Box(modifier = modifier.fillMaxWidth().background(MaterialTheme.colorScheme.background.copy(alpha = 0.94f)).statusBarsPadding().padding(horizontal = 16.dp, vertical = 12.dp), content = content)
  }
}

@Composable
private fun ContinueTab(
  uiState: AppUiState,
  onOpen: (MediaItem) -> Unit,
  onOpenDetails: (MediaItem) -> Unit,
  onToggleWatchlist: (MediaItem) -> Unit,
  onMarkWatched: (MediaItem) -> Unit,
  onMarkEarlierEpisodesWatched: (MediaItem) -> Unit,
  onRestartFromBeginning: (MediaItem) -> Unit,
  onRemoveFromContinueWatching: (MediaItem) -> Unit,
  onClearContinueWatching: () -> Unit,
  onRefreshHandoffDevices: () -> Unit = {},
  onHandoffContinueWatching: suspend (MediaItem, LinkedTvDevice) -> Result<PlaybackHandoffReceipt> = { _, _ -> Result.failure(IllegalStateException("Handoff is unavailable.")) },
) {
  var filter by rememberSaveable { mutableStateOf(MediaFilter.All) }
  var columns by rememberSaveable { mutableStateOf(3) }
  var showClearConfirm by rememberSaveable { mutableStateOf(false) }
  val allItems = remember(uiState.traktContinueWatching, uiState.localContinueWatching) { combinedContinueWatching(uiState) }
  val items = remember(allItems, filter) { allItems.filteredBy(filter) }
  val modernHeader = uiState.headerStyle == HeaderStyle.Modern
  val headerHazeState = rememberHazeState()
  val clearAction: (@Composable () -> Unit)? = if (allItems.isEmpty()) null else {
    {
      GlassCircleButton(onClick = { showClearConfirm = true }) {
        Icon(Icons.Rounded.DeleteSweep, contentDescription = "Clear Continue Watching", tint = MaterialTheme.colorScheme.onBackground)
      }
    }
  }
  if (showClearConfirm) {
    AlertDialog(
      onDismissRequest = { showClearConfirm = false },
      title = { Text("Clear Continue Watching?") },
      text = { Text("This removes all ${allItems.size} in-progress titles. This can't be undone.") },
      confirmButton = { Button(onClick = { showClearConfirm = false; onClearContinueWatching() }) { Text("Clear all") } },
      dismissButton = { TextButton(onClick = { showClearConfirm = false }) { Text("Cancel") } },
    )
  }
  Box(modifier = Modifier.fillMaxSize()) {
    LazyColumn(
      modifier = Modifier.fillMaxSize().background(MaterialTheme.colorScheme.background).then(if (modernHeader) Modifier.hazeSource(headerHazeState) else Modifier),
      contentPadding = PaddingValues(top = if (modernHeader) 222.dp else 0.dp, bottom = 126.dp),
      verticalArrangement = Arrangement.spacedBy(20.dp),
    ) {
      if (!modernHeader) {
        stickyHeader {
          LibraryStreamDekHeader(
            title = "Continue",
            subtitle = "",
            count = items.size,
            selectedFilter = filter,
            onFilterChange = { filter = it },
            columns = columns,
            onToggleColumns = { columns = if (columns == 3) 2 else 3 },
            style = HeaderStyle.Classic,
            hazeState = headerHazeState,
            trailingAction = clearAction,
          )
        }
      }
      if (items.isEmpty()) {
        item { LibraryEmptyState(icon = { Icon(Icons.Rounded.PlayCircleOutline, null, tint = MaterialTheme.colorScheme.onBackground.copy(alpha = 0.76f), modifier = Modifier.size(54.dp)) }, title = "Nothing here yet", subtitle = "Start watching something - your in-progress titles will appear here automatically.") }
      } else {
        item {
          MediaGrid(
            items,
            onOpen,
            columns = columns,
            onToggleWatchlist = onToggleWatchlist,
            watchlistItems = uiState.mergedWatchlist,
            onMarkWatched = onMarkWatched,
            onMarkEarlierEpisodesWatched = onMarkEarlierEpisodesWatched,
            continueWatchingActions = true,
            onRestartFromBeginning = onRestartFromBeginning,
            onRemoveFromContinueWatching = onRemoveFromContinueWatching,
            onOpenDetails = onOpenDetails,
            handoffDevices = uiState.handoffDevices,
            onRefreshHandoffDevices = onRefreshHandoffDevices,
            onHandoffToTv = onHandoffContinueWatching,
          )
        }
      }
    }
    if (modernHeader) {
      LibraryStreamDekHeader(
        title = "Continue",
        subtitle = "",
        count = items.size,
        selectedFilter = filter,
        onFilterChange = { filter = it },
        columns = columns,
        onToggleColumns = { columns = if (columns == 3) 2 else 3 },
        style = HeaderStyle.Modern,
        hazeState = headerHazeState,
        modifier = Modifier.align(Alignment.TopCenter).zIndex(4f),
        trailingAction = clearAction,
      )
    }
  }
}

@Composable
private fun WatchlistTab(uiState: AppUiState, onOpen: (MediaItem) -> Unit, onToggleWatchlist: (MediaItem) -> Unit, onMarkWatched: (MediaItem) -> Unit, onClearWatchlist: () -> Unit) {
  var filter by rememberSaveable { mutableStateOf(MediaFilter.All) }
  var columns by rememberSaveable { mutableStateOf(3) }
  var showClearConfirm by rememberSaveable { mutableStateOf(false) }
  val items = remember(uiState.mergedWatchlist, filter) {
    uiState.mergedWatchlist
      .filteredBy(filter)
      .sortedWith(compareByDescending<MediaItem> { it.addedAt ?: Long.MIN_VALUE }.thenByDescending { it.updatedAt ?: Long.MIN_VALUE })
  }
  val modernHeader = uiState.headerStyle == HeaderStyle.Modern
  val headerHazeState = rememberHazeState()
  val clearAction: (@Composable () -> Unit)? = if (uiState.mergedWatchlist.isEmpty()) null else {
    {
      GlassCircleButton(onClick = { showClearConfirm = true }) {
        Icon(Icons.Rounded.DeleteSweep, contentDescription = "Clear watchlist", tint = MaterialTheme.colorScheme.onBackground)
      }
    }
  }
  if (showClearConfirm) {
    AlertDialog(
      onDismissRequest = { showClearConfirm = false },
      title = { Text("Clear watchlist?") },
      text = { Text("This removes all ${uiState.mergedWatchlist.size} titles from your watchlist. This can't be undone.") },
      confirmButton = { Button(onClick = { showClearConfirm = false; onClearWatchlist() }) { Text("Clear all") } },
      dismissButton = { TextButton(onClick = { showClearConfirm = false }) { Text("Cancel") } },
    )
  }
  Box(modifier = Modifier.fillMaxSize()) {
    LazyColumn(
      modifier = Modifier.fillMaxSize().background(MaterialTheme.colorScheme.background).then(if (modernHeader) Modifier.hazeSource(headerHazeState) else Modifier),
      contentPadding = PaddingValues(top = if (modernHeader) 222.dp else 0.dp, bottom = 126.dp),
      verticalArrangement = Arrangement.spacedBy(20.dp),
    ) {
      if (!modernHeader) {
        stickyHeader {
          LibraryStreamDekHeader(
            title = "Watchlist",
            subtitle = "",
            count = items.size,
            selectedFilter = filter,
            onFilterChange = { filter = it },
            columns = columns,
            onToggleColumns = { columns = if (columns == 3) 2 else 3 },
            style = HeaderStyle.Classic,
            hazeState = headerHazeState,
            trailingAction = clearAction,
          )
        }
      }
      if (items.isEmpty()) {
        item { LibraryEmptyState(icon = { Icon(Icons.Rounded.Bookmark, null, tint = MaterialTheme.colorScheme.onBackground.copy(alpha = 0.62f), modifier = Modifier.size(54.dp)) }, title = "Your watchlist is empty", subtitle = "Add movies and TV series from the detail page to watch them later.") }
      } else {
        item { MediaGrid(items, onOpen, columns = columns, showMeta = false, onToggleWatchlist = onToggleWatchlist, watchlistItems = uiState.mergedWatchlist, includeRemoveAction = true, onMarkWatched = onMarkWatched) }
      }
    }
    if (modernHeader) {
      LibraryStreamDekHeader(
        title = "Watchlist",
        subtitle = "",
        count = items.size,
        selectedFilter = filter,
        onFilterChange = { filter = it },
        columns = columns,
        onToggleColumns = { columns = if (columns == 3) 2 else 3 },
        style = HeaderStyle.Modern,
        hazeState = headerHazeState,
        modifier = Modifier.align(Alignment.TopCenter).zIndex(4f),
        trailingAction = clearAction,
      )
    }
  }
}

@Composable
private fun SearchTab(uiState: AppUiState, ownerKey: String, onSearch: (String) -> Unit, onOpen: (MediaItem) -> Unit, onToggleWatchlist: (MediaItem) -> Unit, onMarkWatched: (MediaItem) -> Unit) {

  val listState = rememberLazyListState()
  var query by rememberSaveable { mutableStateOf("") }
  var filter by rememberSaveable { mutableStateOf(MediaFilter.All) }
  var columns by rememberSaveable { mutableStateOf(3) }
  val searchContext = LocalContext.current
  val searchPrefs = remember(searchContext) { searchContext.getSharedPreferences("streamdek_native_search", Context.MODE_PRIVATE) }
  val recentSearchesKey = remember(ownerKey) { "recent_searches:$ownerKey" }
  var recentSearches by rememberSaveable(ownerKey) {
    mutableStateOf<List<String>>(runCatching {
      val stored = JSONArray(searchPrefs.getString(recentSearchesKey, "[]"))
      List(stored.length()) { index -> stored.optString(index) }.filter { it.isNotBlank() }.take(3)
    }.getOrDefault(emptyList()))
  }
  var discoverType by rememberSaveable { mutableStateOf("movie") }
  var selectedGenreId by rememberSaveable { mutableStateOf<Int?>(null) }
  var selectedYear by rememberSaveable { mutableStateOf<String?>(null) }
  // Which catalogue Discover is reading from: null is StreamDek's own (TMDB), anything else is
  // one catalog belonging to an installed add-on. Saved as a key rather than the catalog object
  // so it survives the add-on list being refreshed underneath it.
  var selectedCatalogKey by rememberSaveable { mutableStateOf<String?>(null) }
  var selectedCatalogGenre by rememberSaveable { mutableStateOf<String?>(null) }
  // The add-on and catalog name behind that key, kept so switching Movies <-> Series can stay on
  // the same add-on. A movie catalog genuinely cannot serve series, but the add-on that owns it
  // almost always has a series catalog too, and dropping the user back to StreamDek every time
  // they changed type made the source control feel broken.
  var selectedAddonId by rememberSaveable { mutableStateOf<String?>(null) }
  var selectedCatalogLabel by rememberSaveable { mutableStateOf<String?>(null) }
  var discoverGenres by remember { mutableStateOf<List<DiscoverGenre>>(emptyList()) }
  var discoverItems by remember { mutableStateOf<List<MediaItem>>(emptyList()) }
  var discoverPage by remember { mutableStateOf(1) }
  var discoverTotalPages by remember { mutableStateOf(1) }
  var discoverLoading by remember { mutableStateOf(true) }
  var discoverLoadingMore by remember { mutableStateOf(false) }
  var discoverSheet by remember { mutableStateOf<String?>(null) }
  var discoverRequestedPage by remember { mutableStateOf<Int?>(null) }

  val apiClient = remember { StreamDekApiClient() }
  val scope = rememberCoroutineScope()
  val yearOptions = remember {
    val currentYear = java.time.LocalDate.now().year
    buildList {
      add(SearchYearOption("Any Year", null))
      for (year in currentYear downTo (currentYear - 19)) {
        add(SearchYearOption(year.toString(), year.toString()))
      }
      add(SearchYearOption("Before 2000", "before:1999"))
    }
  }

  fun discoverTypeLabel(value: String): String = when (value) {
    "tv" -> "Series"
    "documentary" -> "Documentaries"
    else -> "Movies"
  }

  // Every catalog an enabled add-on offers for the type currently being browsed. This is what
  // widens Discover past TMDB: an add-on's own lists (a debrid cloud, a curated "Top 10", an
  // anime catalogue) become selectable sources rather than only ever appearing on Home.
  val addonSources = remember(uiState.addons, discoverType) {
    val wanted = if (discoverType == "documentary") "movie" else discoverType
    uiState.addons
      .filter { it.enabled }
      .flatMap { addon ->
        addon.manifest.catalogs.mapNotNull { catalog ->
          if (mapHomeCatalogType(catalog.type) != wanted) return@mapNotNull null
          val catalogName = cleanAddonCatalogLabel(catalog.name, addon.manifest.name).ifBlank { catalog.name }
          AddonDiscoverSource(
            key = "${addon.id}|${catalog.type}|${catalog.id}",
            addon = addon,
            catalog = catalog,
            label = "${addon.manifest.name} · $catalogName",
            shortLabel = catalogName,
          )
        }
      }
  }
  val selectedCatalog = remember(addonSources, selectedCatalogKey) {
    addonSources.firstOrNull { it.key == selectedCatalogKey }
  }
  // An add-on catalog answers with whatever its own genre options say, so those replace TMDB's
  // genre list while one is selected. A catalog with none simply has no genre control.
  val catalogGenreOptions = selectedCatalog?.catalog?.genreOptions.orEmpty()

  fun selectedSourceLabel(): String = selectedCatalog?.shortLabel ?: "StreamDek"
  // With nothing chosen these read as the name of the filter rather than as a value. "All Genres"
  // and "Any Year" describe the unfiltered result, which is what the option inside the sheet still
  // says - but on the collapsed control it looks like a selection has been made. The sheet keeps
  // the longer wording, because there it genuinely is one of the choices.
  fun selectedGenreLabel(): String = when {
    selectedCatalog != null -> selectedCatalogGenre ?: if (selectedCatalog.catalog.requiresGenre) "Choose" else "Genre"
    else -> discoverGenres.firstOrNull { it.id == selectedGenreId }?.name ?: "Genre"
  }
  fun selectedYearLabel(): String =
    if (selectedYear == null) "Year" else yearOptions.firstOrNull { it.value == selectedYear }?.label ?: "Year"

  fun loadDiscover(page: Int, append: Boolean) {
    if (discoverRequestedPage == page) return
    val source = selectedCatalog
    scope.launch {
      discoverRequestedPage = page
      if (page <= 1) discoverLoading = true else discoverLoadingMore = true
      if (source == null) {
        apiClient.fetchDiscover(discoverType, page, selectedGenreId, selectedYear)
          .onSuccess { payload ->
            discoverPage = payload.page
            discoverTotalPages = payload.totalPages
            discoverItems = if (append) {
              (discoverItems + payload.items).distinctBy { "${it.type}-${it.id}" }
            } else {
              payload.items.distinctBy { "${it.type}-${it.id}" }
            }
          }
          .onFailure {
            if (!append) discoverItems = emptyList()
          }
      } else {
        // Add-on catalogs page by how many items have already been taken, not by page number,
        // and never say how many there are in total. Paging therefore stops when a request comes
        // back with nothing new rather than on a page count.
        val skip = if (append) discoverItems.size else 0
        val genre = selectedCatalogGenre
          ?: source.catalog.genreOptions.firstOrNull()?.takeIf { source.catalog.requiresGenre }
        apiClient.fetchMoreCatalogItems(
          session = uiState.session,
          addon = source.addon,
          catalogType = source.catalog.type,
          catalogId = source.catalog.id,
          catalogName = source.catalog.name,
          genre = genre,
          skip = skip,
          profileId = uiState.activeProfileId,
        )
          .onSuccess { items ->
            discoverPage = page
            val merged = if (append) {
              (discoverItems + items).distinctBy { "${it.type}-${it.id}" }
            } else {
              items.distinctBy { "${it.type}-${it.id}" }
            }
            // Nothing new came back, so this catalog has no more to give.
            discoverTotalPages = if (merged.size > discoverItems.size || !append) page + 1 else page
            discoverItems = merged
          }
          .onFailure {
            if (!append) discoverItems = emptyList()
            discoverTotalPages = page
          }
      }
      discoverLoading = false
      discoverLoadingMore = false
      discoverRequestedPage = null
    }
  }

  LaunchedEffect(query) {
    val normalized = query.trim()
    if (normalized.isBlank()) return@LaunchedEffect
    delay(500)
    if (normalized.length > 1) onSearch(normalized)
  }

  LaunchedEffect(query, uiState.searchLoading, uiState.searchResults) {
    val normalized = query.trim()
    if (normalized.length > 1 && uiState.searchResultQuery == normalized && !uiState.searchLoading && uiState.searchResults.isNotEmpty()) {
      recentSearches = listOf(normalized, *recentSearches.filterNot { it.equals(normalized, ignoreCase = true) }.toTypedArray()).take(3)
      searchPrefs.edit().putString(recentSearchesKey, JSONArray(recentSearches).toString()).apply()
    }
  }

  LaunchedEffect(discoverType) {
    selectedGenreId = null
    if (discoverType == "documentary") {
      discoverGenres = emptyList()
    } else {
      apiClient.fetchDiscoverGenres(discoverType)
        .onSuccess { discoverGenres = it }
        .onFailure { discoverGenres = emptyList() }
    }
  }

  LaunchedEffect(discoverType, selectedGenreId, selectedYear, selectedCatalogKey, selectedCatalogGenre) {
    // Changing type invalidates the selected catalog for one frame, until the effect below finds
    // that add-on's catalog for the new type. Loading now would fetch and show StreamDek's
    // results in the meantime, which is the flicker the user would see mid-switch.
    if (selectedAddonId != null && selectedCatalog == null) return@LaunchedEffect
    discoverPage = 1
    discoverTotalPages = 1
    discoverRequestedPage = null
    discoverItems = emptyList()
    loadDiscover(page = 1, append = false)
  }

  /**
   * Keeps the chosen source pointing at something that can actually answer.
   *
   * The catalog list is rebuilt for whichever type is being browsed, so changing Movies <->
   * Series always invalidates the current key. Rather than giving up and reverting to StreamDek,
   * the same add-on is looked up again for the new type — preferring a catalog with the same name
   * ("Blumhouse" movies -> "Blumhouse" series) and otherwise taking that add-on's first. Only an
   * add-on with nothing for this type, or one that has been disabled or uninstalled, falls back.
   */
  LaunchedEffect(addonSources, selectedCatalogKey, selectedAddonId) {
    val addonId = selectedAddonId ?: return@LaunchedEffect
    if (addonSources.any { it.key == selectedCatalogKey }) return@LaunchedEffect
    val sameAddon = addonSources.filter { it.addon.id == addonId }
    val replacement = sameAddon.firstOrNull { it.shortLabel.equals(selectedCatalogLabel, ignoreCase = true) }
      ?: sameAddon.firstOrNull()
    if (replacement != null) {
      selectedCatalogKey = replacement.key
      selectedCatalogLabel = replacement.shortLabel
      // Genre options belong to the catalog, so one chosen for the old catalog cannot carry over.
      selectedCatalogGenre = null
    } else {
      selectedCatalogKey = null
      selectedAddonId = null
      selectedCatalogLabel = null
      selectedCatalogGenre = null
    }
  }

  LaunchedEffect(listState, query, discoverPage, discoverTotalPages, discoverLoading, discoverLoadingMore, discoverItems.size, discoverRequestedPage) {
    snapshotFlow { listState.canScrollForward }
      .collect { canScrollForward ->
        if (canScrollForward) return@collect
        if (query.isNotBlank() || discoverLoading || discoverLoadingMore || discoverPage >= discoverTotalPages || discoverItems.isEmpty()) return@collect
        val nextPage = discoverPage + 1
        if (discoverRequestedPage == nextPage) return@collect
        loadDiscover(nextPage, append = true)
      }
  }

  val searchResults = remember(uiState.searchResults, filter) {
    uiState.searchResults.distinctBy { "${it.type}-${it.id}" }.filteredBy(filter)
  }

  // Installed playlists are already parsed in memory, so matching them is a local pass rather
  // than another round trip - results appear without waiting on the network. It runs off the main
  // thread because a provider list can hold hundreds of thousands of entries, and behind the same
  // debounce the remote search uses so typing does not re-scan the list on every character.
  var playlistLive by remember { mutableStateOf<List<MediaItem>>(emptyList()) }
  var playlistVod by remember { mutableStateOf<List<MediaItem>>(emptyList()) }
  var playlistGroup by remember { mutableStateOf<String?>(null) }

  LaunchedEffect(query, uiState.m3uChannels, uiState.m3uVodItems) {
    val normalized = query.trim()
    if (normalized.length < 2) {
      playlistLive = emptyList()
      playlistVod = emptyList()
      playlistGroup = null
      return@LaunchedEffect
    }
    delay(500)
    val live = withContext(Dispatchers.Default) { uiState.m3uChannels.matchingPlaylistItems(normalized) }
    val vod = withContext(Dispatchers.Default) { uiState.m3uVodItems.matchingPlaylistItems(normalized) }
    playlistLive = live
    playlistVod = vod
    // A category chosen for the previous query rarely exists in the new one's matches.
    playlistGroup = null
  }

  // Categories are taken from what actually matched rather than from the whole playlist, so every
  // chip offered leads somewhere. Playlist group-titles are already parsed into sourceCatalogName.
  val playlistGroups = remember(playlistLive, playlistVod) {
    (playlistLive + playlistVod)
      .mapNotNull { it.sourceCatalogName?.takeIf(String::isNotBlank) }
      .groupingBy { it }
      .eachCount()
      .entries
      .sortedWith(compareByDescending<Map.Entry<String, Int>> { it.value }.thenBy { it.key })
      .take(12)
      .map { it.key }
  }
  val visiblePlaylistLive = remember(playlistLive, playlistGroup) {
    playlistGroup?.let { group -> playlistLive.filter { it.sourceCatalogName == group } } ?: playlistLive
  }
  val visiblePlaylistVod = remember(playlistVod, playlistGroup) {
    playlistGroup?.let { group -> playlistVod.filter { it.sourceCatalogName == group } } ?: playlistVod
  }
  val hasPlaylistMatches = visiblePlaylistLive.isNotEmpty() || visiblePlaylistVod.isNotEmpty()
  val addonMatches = remember(uiState.addonSearchResults) {
    uiState.addonSearchResults.distinctBy { "${it.type}-${it.id}" }
  }

  val discoverOptions = remember(discoverSheet, discoverType, discoverGenres, selectedGenreId, selectedYear) {
    when (discoverSheet) {
      "type" -> listOf("movie", "tv", "documentary").map { value ->
        SearchSelectionOption(
          label = discoverTypeLabel(value),
          selected = discoverType == value,
          onSelect = {
            discoverType = value
            discoverSheet = null
          },
        )
      }
      "source" -> buildList {
        add(
          SearchSelectionOption(
            label = "StreamDek",
            selected = selectedCatalogKey == null,
            onSelect = {
              selectedCatalogKey = null
              selectedAddonId = null
              selectedCatalogLabel = null
              selectedCatalogGenre = null
              discoverSheet = null
            },
          )
        )
        addonSources.forEach { source ->
          add(
            SearchSelectionOption(
              label = source.label,
              selected = source.key == selectedCatalogKey,
              onSelect = {
                selectedCatalogKey = source.key
                selectedAddonId = source.addon.id
                selectedCatalogLabel = source.shortLabel
                // TMDB's genre and year mean nothing to an add-on catalog, and a stale one left
                // showing in the field would claim a filter that is not being applied.
                selectedCatalogGenre = null
                selectedGenreId = null
                selectedYear = null
                discoverSheet = null
              },
            )
          )
        }
      }
      "genre" -> buildList {
        if (selectedCatalog != null) {
          if (!selectedCatalog.catalog.requiresGenre) {
            add(
              SearchSelectionOption(
                label = "All Genres",
                selected = selectedCatalogGenre == null,
                onSelect = {
                  selectedCatalogGenre = null
                  discoverSheet = null
                },
              )
            )
          }
          catalogGenreOptions.forEach { option ->
            add(
              SearchSelectionOption(
                label = option,
                selected = option == selectedCatalogGenre,
                onSelect = {
                  selectedCatalogGenre = option
                  discoverSheet = null
                },
              )
            )
          }
          return@buildList
        }
        add(
          SearchSelectionOption(
            label = "All Genres",
            selected = selectedGenreId == null,
            onSelect = {
              selectedGenreId = null
              discoverSheet = null
            },
          )
        )
        discoverGenres.forEach { genre ->
          add(
            SearchSelectionOption(
              label = genre.name,
              selected = genre.id == selectedGenreId,
              onSelect = {
                selectedGenreId = genre.id
                discoverSheet = null
              },
            )
          )
        }
      }
      "year" -> yearOptions.map { option ->
        SearchSelectionOption(
          label = option.label,
          selected = option.value == selectedYear,
          onSelect = {
            selectedYear = option.value
            discoverSheet = null
          },
        )
      }
      else -> emptyList()
    }
  }

  val modernHeader = uiState.headerStyle == HeaderStyle.Modern
  val headerHazeState = rememberHazeState()
  Box(modifier = Modifier.fillMaxSize()) {
  LazyColumn(
    state = listState,
    modifier = Modifier.fillMaxSize().background(MaterialTheme.colorScheme.background).then(if (modernHeader) Modifier.hazeSource(headerHazeState) else Modifier),
    contentPadding = PaddingValues(top = if (modernHeader) 236.dp else 0.dp, bottom = 126.dp),
    verticalArrangement = Arrangement.spacedBy(20.dp),
  ) {
    if (!modernHeader) {
      stickyHeader {
        Box(modifier = Modifier.fillMaxWidth().background(MaterialTheme.colorScheme.background.copy(alpha = 0.94f)).statusBarsPadding().padding(horizontal = 16.dp, vertical = 10.dp)) {
          SearchHeader(
            query = query,
            columns = columns,
            showResultsState = query.isNotBlank() && searchResults.isNotEmpty(),
            onQueryChange = { query = it },
            onClear = { query = "" },
            onToggleColumns = { columns = if (columns == 3) 2 else 3 },
            modifier = Modifier.fillMaxWidth(),
          )
        }
      }
    }

    if (query.isBlank()) {
      if (recentSearches.isNotEmpty()) {
        item {
          SearchRecentSection(
            recentSearches = recentSearches,
            onSearchPress = { query = it },
            onRemoveSearch = { recent ->
              recentSearches = recentSearches.filterNot { it == recent }
              searchPrefs.edit().putString(recentSearchesKey, JSONArray(recentSearches).toString()).apply()
            },
          )
        }
      }
      item {
        Column(
          modifier = Modifier.fillMaxWidth().padding(horizontal = 16.dp),
          verticalArrangement = Arrangement.spacedBy(14.dp),
        ) {
          SearchSectionLabel(
            title = "Discover",
            subtitle = "",
            horizontalPadding = 0.dp,
          )
          // Sized to their contents and wrapped rather than forced into equal columns. Add-on
          // catalog names vary from "A24" to "Right Now Movies", and an even split either wasted
          // half the row on "Movies" or cut the selected source down to something unreadable.
          androidx.compose.foundation.layout.FlowRow(
            modifier = Modifier.fillMaxWidth(),
            horizontalArrangement = Arrangement.spacedBy(18.dp),
            verticalArrangement = Arrangement.spacedBy(2.dp),
          ) {
            // Ordered the way the choices actually depend on each other: Source decides which
            // catalogue is being asked, and both Genre and Year are dropped or replaced depending
            // on what that source supports - so it belongs first, before the controls it governs.
            // Type narrows what Source returns, then Genre and Year narrow that, ending on the
            // two that disappear most often so the row does not reshuffle around a stable control.
            if (addonSources.isNotEmpty()) {
              SearchDiscoverField(
                label = "Source",
                value = selectedSourceLabel(),
                onClick = { discoverSheet = "source" },
              )
            }
            SearchDiscoverField(
              label = "Type",
              value = discoverTypeLabel(discoverType),
              onClick = { discoverSheet = "type" },
            )
            // With an add-on catalog selected the control offers that catalog's own options, so
            // it is dropped entirely when that catalog declares none - a permanently greyed-out
            // "All Genres" only looks broken.
            val showGenre = if (selectedCatalog != null) {
              catalogGenreOptions.isNotEmpty()
            } else {
              discoverType != "documentary" && discoverGenres.isNotEmpty()
            }
            if (showGenre) {
              SearchDiscoverField(
                label = "Genre",
                value = selectedGenreLabel(),
                onClick = { discoverSheet = "genre" },
              )
            }
            // An add-on catalog answers with its own ordering and has no year parameter, so the
            // control is dropped rather than left showing a filter that would be ignored.
            if (selectedCatalog == null) {
              SearchDiscoverField(
                label = "Year",
                value = selectedYearLabel(),
                onClick = { discoverSheet = "year" },
              )
            }
          }
        }
      }
      when {
        discoverLoading && discoverItems.isEmpty() -> {
          item { SearchGridSkeleton(columns = columns) }
        }
        discoverItems.isEmpty() -> {
          item {
            LibraryEmptyState(
              icon = { Icon(Icons.Rounded.Search, null, tint = MaterialTheme.colorScheme.onBackground.copy(alpha = 0.70f), modifier = Modifier.size(54.dp)) },
              title = "Nothing matched these filters",
              subtitle = "Try a different type, genre, or year.",
            )
          }
        }
        else -> {
          item { MediaGrid(discoverItems, onOpen, columns = columns, showMeta = true, onToggleWatchlist = onToggleWatchlist, watchlistItems = uiState.mergedWatchlist, onMarkWatched = onMarkWatched) }
          if (discoverPage < discoverTotalPages) {
            item {
              Box(modifier = Modifier.fillMaxWidth().padding(horizontal = 16.dp, vertical = 12.dp), contentAlignment = Alignment.Center) {
                if (discoverLoadingMore) {
                  CircularProgressIndicator(color = MaterialTheme.colorScheme.onBackground, modifier = Modifier.size(22.dp), strokeWidth = 2.dp)
                }
              }
            }
          }
        }
      }
    } else {
      item {
        Column(
          modifier = Modifier
            .fillMaxWidth()
            .padding(horizontal = 16.dp),
          verticalArrangement = Arrangement.spacedBy(14.dp),
        ) {
          Row(modifier = Modifier.fillMaxWidth(), horizontalArrangement = Arrangement.spacedBy(10.dp)) {
            MediaFilter.values().forEach { value ->
              FilterChip(selected = filter == value, onClick = { filter = value }, label = { Text(if (value == MediaFilter.All) "All" else value.name) })
            }
          }
          Text(
            text = "Results",
            style = MaterialTheme.typography.titleLarge,
            fontWeight = FontWeight.Bold,
            color = MaterialTheme.colorScheme.onBackground,
          )
        }
      }
      when {
        uiState.searchLoading && searchResults.isEmpty() && !hasPlaylistMatches && addonMatches.isEmpty() -> {
          item { SearchGridSkeleton(columns = columns) }
        }
        searchResults.isEmpty() && !hasPlaylistMatches && addonMatches.isEmpty() && !uiState.addonSearchLoading -> {
          item {
            LibraryEmptyState(
              icon = { Icon(Icons.Rounded.Search, null, tint = MaterialTheme.colorScheme.onBackground.copy(alpha = 0.70f), modifier = Modifier.size(54.dp)) },
              title = "No results",
              subtitle = "Try another title or clear the search to return to Discover.",
            )
          }
        }
        else -> {
          if (searchResults.isNotEmpty()) {
            item { MediaGrid(searchResults.take(60), onOpen, columns = columns, showMeta = true, onToggleWatchlist = onToggleWatchlist, watchlistItems = uiState.mergedWatchlist, onMarkWatched = onMarkWatched) }
          }
        }
      }

      // Add-on results sit between the catalogue and the playlists: they are the only place an
      // add-on's own titles - live channels above all - can appear, since TMDB does not carry
      // them and the app never holds a whole catalog to filter.
      if (addonMatches.isNotEmpty()) {
        item { PlaylistResultsHeader("From your add-ons", addonMatches.size) }
        item {
          MediaGrid(addonMatches.take(60), onOpen, columns = columns, showMeta = true, onToggleWatchlist = onToggleWatchlist, watchlistItems = uiState.mergedWatchlist, onMarkWatched = onMarkWatched)
        }
      }

      // Playlist matches keep their own sections rather than joining the grid above. A provider
      // list can answer a short query with thousands of channels, and merged in they would bury
      // the handful of catalogue results the user was most likely looking for.
      if (hasPlaylistMatches) {
        if (playlistGroups.size > 1) {
          item {
            Column(
              modifier = Modifier.fillMaxWidth().padding(horizontal = 16.dp, vertical = 4.dp),
              verticalArrangement = Arrangement.spacedBy(10.dp),
            ) {
              Text(
                "From your playlists",
                style = MaterialTheme.typography.titleLarge,
                fontWeight = FontWeight.Bold,
                color = MaterialTheme.colorScheme.onBackground,
              )
              androidx.compose.foundation.layout.FlowRow(
                horizontalArrangement = Arrangement.spacedBy(8.dp),
                verticalArrangement = Arrangement.spacedBy(8.dp),
              ) {
                FilterChip(
                  selected = playlistGroup == null,
                  onClick = { playlistGroup = null },
                  label = { Text("All") },
                )
                playlistGroups.forEach { group ->
                  FilterChip(
                    selected = playlistGroup == group,
                    onClick = { playlistGroup = if (playlistGroup == group) null else group },
                    label = { Text(group, maxLines = 1, overflow = TextOverflow.Ellipsis) },
                  )
                }
              }
            }
          }
        }
        if (visiblePlaylistLive.isNotEmpty()) {
          item { PlaylistResultsHeader("Playlist Live TV", visiblePlaylistLive.size) }
          item {
            MediaGrid(visiblePlaylistLive, onOpen, columns = columns, showMeta = false, onToggleWatchlist = onToggleWatchlist, watchlistItems = uiState.mergedWatchlist, onMarkWatched = onMarkWatched)
          }
        }
        if (visiblePlaylistVod.isNotEmpty()) {
          item { PlaylistResultsHeader("Playlist VOD", visiblePlaylistVod.size) }
          item {
            MediaGrid(visiblePlaylistVod, onOpen, columns = columns, showMeta = false, onToggleWatchlist = onToggleWatchlist, watchlistItems = uiState.mergedWatchlist, onMarkWatched = onMarkWatched)
          }
        }
      }
    }
  }
  if (modernHeader) {
    val lightHeader = MaterialTheme.colorScheme.background.luminance() > 0.5f
    Box(modifier = Modifier.align(Alignment.TopCenter).zIndex(4f).fillMaxWidth().statusBarsPadding().padding(start = 8.dp, end = 8.dp, top = 12.dp, bottom = 6.dp)) {
      FrostedGlassSurface(
        modifier = Modifier.fillMaxWidth().height(166.dp),
        shape = StreamDekRadius.sheetShape,
        hazeStateOverride = headerHazeState,
        blurRadius = 68f,
        contentPadding = PaddingValues(horizontal = 16.dp, vertical = 12.dp),
        tintAlpha = if (lightHeader) 0.14f else 0.06f,
        borderAlpha = if (lightHeader) 0.10f else 0f,
        baseAlpha = if (lightHeader) 0.28f else 0.08f,
        fillColorOverride = if (lightHeader) null else Color.White,
        showEdgeGradient = false,
      ) {
        SearchHeader(
          query = query,
          columns = columns,
          showResultsState = query.isNotBlank() && searchResults.isNotEmpty(),
          onQueryChange = { query = it },
          onClear = { query = "" },
          onToggleColumns = { columns = if (columns == 3) 2 else 3 },
          modifier = Modifier.fillMaxWidth(),
        )
      }
    }
  }
  }

  if (discoverSheet != null && discoverOptions.isNotEmpty()) {
    SearchSelectionDialog(
      title = when (discoverSheet) {
        "type" -> "Choose Type"
        "genre" -> "Choose Genre"
        "source" -> "Choose Source"
        else -> "Choose Year"
      },
      options = discoverOptions,
      onDismiss = { discoverSheet = null },
    )
  }
}

@Composable
private fun SearchDiscoverField(
  label: String,
  value: String,
  modifier: Modifier = Modifier,
  enabled: Boolean = true,
  onClick: () -> Unit,
) {
  Row(
    modifier = modifier
      .heightIn(min = 28.dp)
      .clip(StreamDekRadius.controlShape)
      .clickable(enabled = enabled, onClick = onClick)
      .padding(vertical = 2.dp),
    horizontalArrangement = Arrangement.spacedBy(4.dp),
    verticalAlignment = Alignment.CenterVertically,
  ) {
    Text(
      value,
      color = if (label == "Type") MaterialTheme.colorScheme.onBackground else MaterialTheme.colorScheme.onBackground.copy(alpha = 0.76f),
      fontSize = 15.sp,
      fontWeight = if (label == "Type") FontWeight.SemiBold else FontWeight.Medium,
      maxLines = 1,
      overflow = TextOverflow.Ellipsis,
    )
    Icon(
      Icons.Rounded.KeyboardArrowDown,
      contentDescription = null,
      tint = if (enabled) MaterialTheme.colorScheme.onBackground.copy(alpha = 0.58f) else MaterialTheme.colorScheme.onBackground.copy(alpha = 0.28f),
      modifier = Modifier.size(16.dp),
    )
  }
}

@Composable
private fun SearchSelectionDialog(
  title: String,
  options: List<SearchSelectionOption>,
  onDismiss: () -> Unit,
) {
  Dialog(onDismissRequest = onDismiss, properties = DialogProperties(usePlatformDefaultWidth = false)) {
    Box(
      modifier = Modifier
        .fillMaxSize()
        .background(Color.Black.copy(alpha = 0.58f))
        .clickable(onClick = onDismiss),
      contentAlignment = Alignment.BottomCenter,
    ) {
      Card(
        modifier = Modifier
          .fillMaxWidth()
          .padding(horizontal = 16.dp, vertical = 18.dp)
          .clickable(enabled = false, onClick = {}),
        shape = StreamDekRadius.sheetShape,
        colors = CardDefaults.cardColors(containerColor = MaterialTheme.colorScheme.surface),
      ) {
        Column(
          modifier = Modifier
            .fillMaxWidth()
            .padding(horizontal = 18.dp, vertical = 18.dp),
          verticalArrangement = Arrangement.spacedBy(12.dp),
        ) {
          Text(title, color = MaterialTheme.colorScheme.onBackground, style = MaterialTheme.typography.titleLarge, fontWeight = FontWeight.Black)
          LazyColumn(
            modifier = Modifier
              .fillMaxWidth()
              .heightIn(max = 420.dp),
            verticalArrangement = Arrangement.spacedBy(8.dp),
          ) {
            items(options.size) { index ->
              val option = options[index]
              OutlinedButton(
                onClick = option.onSelect,
                modifier = Modifier.fillMaxWidth(),
                shape = StreamDekRadius.cardShape,
                border = BorderStroke(1.dp, MaterialTheme.colorScheme.onBackground.copy(alpha = if (option.selected) 0.26f else 0.10f)),
                colors = ButtonDefaults.outlinedButtonColors(
                  containerColor = if (option.selected) MaterialTheme.colorScheme.onBackground.copy(alpha = 0.12f) else MaterialTheme.colorScheme.onBackground.copy(alpha = 0.04f),
                  contentColor = MaterialTheme.colorScheme.onBackground,
                ),
                contentPadding = PaddingValues(horizontal = 14.dp, vertical = 14.dp),
              ) {
                Row(modifier = Modifier.fillMaxWidth(), horizontalArrangement = Arrangement.SpaceBetween, verticalAlignment = Alignment.CenterVertically) {
                  Text(option.label, fontWeight = if (option.selected) FontWeight.Bold else FontWeight.Medium)
                  if (option.selected) {
                    Icon(Icons.Rounded.CheckCircle, contentDescription = null, tint = MaterialTheme.colorScheme.onBackground, modifier = Modifier.size(18.dp))
                  }
                }
              }
            }
          }
        }
      }
    }
  }
}

@Composable
private fun SearchHeader(
  query: String,
  columns: Int,
  showResultsState: Boolean,
  onQueryChange: (String) -> Unit,
  onClear: () -> Unit,
  onToggleColumns: () -> Unit,
  modifier: Modifier = Modifier,
) {
  Column(
    modifier = modifier.fillMaxWidth().padding(start = 2.dp, end = 2.dp, top = 10.dp, bottom = 8.dp),
    verticalArrangement = Arrangement.spacedBy(12.dp),
  ) {
    Row(modifier = Modifier.fillMaxWidth(), horizontalArrangement = Arrangement.SpaceBetween, verticalAlignment = Alignment.CenterVertically) {
      Column(verticalArrangement = Arrangement.spacedBy(4.dp)) {
        AdaptivePageTitle(title = "Search", maxLines = 1)
      }
      GlassCircleButton(onClick = onToggleColumns) {
        Icon(if (columns == 3) Icons.Rounded.ViewAgenda else Icons.Rounded.ViewModule, contentDescription = null, tint = MaterialTheme.colorScheme.onBackground)
      }
    }
    OutlinedTextField(
      value = query,
      onValueChange = onQueryChange,
      modifier = Modifier.fillMaxWidth(),
      singleLine = true,
      placeholder = { InputGuideText("Search movies, TV and catalogs") },
      leadingIcon = { Icon(Icons.Rounded.Search, contentDescription = null) },
      trailingIcon = if (query.isNotBlank()) ({ IconButton(onClick = onClear) { Icon(Icons.Rounded.Close, contentDescription = "Clear") } }) else null,
      shape = StreamDekRadius.cardShape,
      colors = androidx.compose.material3.TextFieldDefaults.colors(
        focusedContainerColor = MaterialTheme.colorScheme.onBackground.copy(alpha = 0.07f),
        unfocusedContainerColor = MaterialTheme.colorScheme.onBackground.copy(alpha = 0.05f),
        focusedIndicatorColor = Color.Transparent,
        unfocusedIndicatorColor = Color.Transparent,
        cursorColor = MaterialTheme.colorScheme.onBackground,
        focusedTextColor = MaterialTheme.colorScheme.onBackground,
        unfocusedTextColor = MaterialTheme.colorScheme.onBackground,
        focusedLeadingIconColor = MaterialTheme.colorScheme.onBackground.copy(alpha = 0.92f),
        unfocusedLeadingIconColor = MaterialTheme.colorScheme.onBackground.copy(alpha = 0.72f),
        focusedPlaceholderColor = MaterialTheme.colorScheme.onBackground.copy(alpha = 0.46f),
        unfocusedPlaceholderColor = MaterialTheme.colorScheme.onBackground.copy(alpha = 0.46f),
      ),
    )
    if (showResultsState) {
      Text(if (columns == 3) "Three-column layout" else "Two-column layout", color = MaterialTheme.colorScheme.onBackground.copy(alpha = 0.62f), style = MaterialTheme.typography.bodySmall)
    }
  }
}

@Composable
private fun SearchRecentSection(recentSearches: List<String>, onSearchPress: (String) -> Unit, onRemoveSearch: (String) -> Unit) {
  Column(modifier = Modifier.fillMaxWidth().padding(horizontal = 16.dp), verticalArrangement = Arrangement.spacedBy(10.dp)) {
    SearchSectionLabel(
      title = "Recent Searches",
      subtitle = "Jump back into titles you looked up earlier.",
      horizontalPadding = 0.dp,
    )
    recentSearches.forEach { recentQuery ->
      SearchRecentRow(query = recentQuery, onSearchPress = { onSearchPress(recentQuery) }, onRemovePress = { onRemoveSearch(recentQuery) })
    }
  }
}

@Composable
private fun SearchSectionLabel(title: String, subtitle: String, horizontalPadding: Dp = 16.dp) {
  Column(
    modifier = Modifier
      .fillMaxWidth()
      .padding(horizontal = horizontalPadding),
    verticalArrangement = Arrangement.spacedBy(4.dp),
  ) {
    Text(title, fontSize = if (title == "Discover") 24.3.sp else 18.sp, lineHeight = if (title == "Discover") 29.7.sp else 22.sp, fontWeight = FontWeight.Bold, color = MaterialTheme.colorScheme.onBackground)
    if (subtitle.isNotBlank()) {
      Text(subtitle, style = MaterialTheme.typography.bodyMedium, color = MaterialTheme.colorScheme.onBackground.copy(alpha = 0.62f))
    }
  }
}

@Composable
private fun SearchRecentRow(query: String, onSearchPress: () -> Unit, onRemovePress: () -> Unit) {
  Row(
    modifier = Modifier
      .fillMaxWidth()
      .clip(StreamDekRadius.cardShape)
      .background(MaterialTheme.colorScheme.onBackground.copy(alpha = 0.035f))
      .border(1.dp, MaterialTheme.colorScheme.onBackground.copy(alpha = 0.06f), StreamDekRadius.cardShape)
      .clickable(onClick = onSearchPress)
      .padding(horizontal = 14.dp, vertical = 12.dp),
    horizontalArrangement = Arrangement.spacedBy(12.dp),
    verticalAlignment = Alignment.CenterVertically,
  ) {
    Box(modifier = Modifier.background(MaterialTheme.colorScheme.onBackground.copy(alpha = 0.06f), StreamDekRadius.pill).padding(9.dp), contentAlignment = Alignment.Center) {
      Icon(Icons.Rounded.History, contentDescription = null, tint = MaterialTheme.colorScheme.onBackground.copy(alpha = 0.68f), modifier = Modifier.size(18.dp))
    }
    Text(query, modifier = Modifier.weight(1f), style = MaterialTheme.typography.bodyLarge, color = MaterialTheme.colorScheme.onBackground, maxLines = 1, overflow = TextOverflow.Ellipsis)
    IconButton(onClick = onRemovePress) {
      Icon(Icons.Rounded.Close, contentDescription = "Remove recent search", tint = MaterialTheme.colorScheme.onBackground.copy(alpha = 0.68f))
    }
  }
}

@Composable
private fun LibraryTabScreen(viewModel: NativeAppViewModel) {
  val uiState = viewModel.uiState
  var selected by rememberSaveable { mutableStateOf(LibraryTab.Continue) }
  var addonUrl by rememberSaveable { mutableStateOf("") }
  var profileName by rememberSaveable { mutableStateOf("") }
  var selectedProvider by rememberSaveable { mutableStateOf("real-debrid") }
  var providerApiKey by rememberSaveable { mutableStateOf("") }
  var pinPrompt by rememberSaveable(uiState.pinPromptProfileId) { mutableStateOf("") }
  var editingPinProfileId by rememberSaveable { mutableStateOf<String?>(null) }
  var newPin by rememberSaveable(editingPinProfileId) { mutableStateOf("") }
  var confirmPin by rememberSaveable(editingPinProfileId) { mutableStateOf("") }

  LazyColumn(
    modifier = Modifier.fillMaxSize(),
    contentPadding = PaddingValues(16.dp),
    verticalArrangement = Arrangement.spacedBy(14.dp),
  ) {
    item {
      LazyRow(horizontalArrangement = Arrangement.spacedBy(8.dp)) {
        items(LibraryTab.values().toList(), key = { it.name }) { tab ->
          FilterChip(selected = selected == tab, onClick = { selected = tab }, label = { Text(tab.name) })
        }
      }
    }

    when (selected) {
      LibraryTab.Continue -> {
        items(combinedContinueWatching(uiState), key = { "continue-${it.type}-${it.id}" }) { item ->
          Box(modifier = animatedItem()) { LibraryMediaCard(item = item) }
        }
      }
      LibraryTab.Watchlist -> {
        items(uiState.mergedWatchlist, key = { "watchlist-${it.type}-${it.id}" }) { item ->
          Box(modifier = animatedItem()) { SearchResultRow(item = item, onClick = { viewModel.toggleWatchlist(item) }) }
        }
      }
      LibraryTab.Profiles -> {
        item {
          GlassCard {
            Column(verticalArrangement = Arrangement.spacedBy(12.dp)) {
              OutlinedTextField(value = profileName, onValueChange = { profileName = it }, modifier = Modifier.fillMaxWidth(), label = { Text("New profile name") }, singleLine = true)
              Button(onClick = {
                if (profileName.isNotBlank()) {
                  viewModel.createProfile(profileName.trim())
                  profileName = ""
                }
              }, modifier = Modifier.fillMaxWidth()) { Text("Create profile") }
            }
          }
        }
        if (uiState.pinPromptProfileId != null) {
          item {
            GlassCard {
              Column(verticalArrangement = Arrangement.spacedBy(12.dp)) {
                Text("PIN required", fontWeight = FontWeight.Bold)
                Text("Enter the 4-digit PIN for ${uiState.pinPromptProfileName ?: "this profile"}.", color = MaterialTheme.colorScheme.onSurface.copy(alpha = 0.72f))
                OutlinedTextField(
                  value = pinPrompt,
                  onValueChange = { pinPrompt = it.filter(Char::isDigit).take(4) },
                  modifier = Modifier.fillMaxWidth(),
                  label = { Text("PIN") },
                  singleLine = true,
                  keyboardOptions = KeyboardOptions(keyboardType = KeyboardType.NumberPassword),
                  visualTransformation = PasswordVisualTransformation(),
                )
                Row(horizontalArrangement = Arrangement.spacedBy(8.dp)) {
                  Button(
                    onClick = {
                      viewModel.submitProfilePin(pinPrompt)
                      pinPrompt = ""
                    },
                    enabled = pinPrompt.length == 4,
                  ) { Text("Unlock") }
                  TextButton(
                    onClick = {
                      pinPrompt = ""
                      viewModel.cancelProfilePinPrompt()
                    },
                  ) { Text("Cancel") }
                }
              }
            }
          }
        }
        items(uiState.profiles, key = { "profile-${it.id}" }) { profile ->
          GlassCard {
            Row(modifier = Modifier.fillMaxWidth(), horizontalArrangement = Arrangement.SpaceBetween, verticalAlignment = Alignment.CenterVertically) {
              Column(modifier = Modifier.weight(1f), verticalArrangement = Arrangement.spacedBy(4.dp)) {
                Text(profile.name, fontWeight = FontWeight.Bold)
                Text(buildString {
                  append(if (profile.id == uiState.activeProfileId) "Active" else "Tap to switch")
                  if (profile.isDefault) append(" \u2022 Default")
                  if (profile.hasPinSet) append(" \u2022 PIN set")
                }, color = MaterialTheme.colorScheme.onSurface.copy(alpha = 0.72f))
              }
              Row(horizontalArrangement = Arrangement.spacedBy(6.dp)) {
                TextButton(onClick = { viewModel.selectProfile(profile.id) }) { Text("Use") }
                TextButton(onClick = { viewModel.makeDefaultProfile(profile.id) }) { Text("Default") }
                if (!profile.isDefault) {
                  TextButton(onClick = { viewModel.deleteProfile(profile.id) }) { Text("Delete") }
                }
              }
            }
            Spacer(modifier = Modifier.height(5.dp))
          if (editingPinProfileId == profile.id) {
              Column(verticalArrangement = Arrangement.spacedBy(8.dp)) {
                OutlinedTextField(
                  value = newPin,
                  onValueChange = { newPin = it.filter(Char::isDigit).take(4) },
                  modifier = Modifier.fillMaxWidth(),
                  label = { Text(if (profile.hasPinSet) "New PIN" else "PIN") },
                  singleLine = true,
                  keyboardOptions = KeyboardOptions(keyboardType = KeyboardType.NumberPassword),
                  visualTransformation = PasswordVisualTransformation(),
                )
                OutlinedTextField(
                  value = confirmPin,
                  onValueChange = { confirmPin = it.filter(Char::isDigit).take(4) },
                  modifier = Modifier.fillMaxWidth(),
                  label = { Text("Confirm PIN") },
                  singleLine = true,
                  keyboardOptions = KeyboardOptions(keyboardType = KeyboardType.NumberPassword),
                  visualTransformation = PasswordVisualTransformation(),
                )
                Row(horizontalArrangement = Arrangement.spacedBy(8.dp)) {
                  Button(
                    onClick = {
                      viewModel.updateProfilePin(profile.id, newPin)
                      editingPinProfileId = null
                      newPin = ""
                      confirmPin = ""
                    },
                    enabled = newPin.length == 4 && confirmPin == newPin,
                  ) { Text(if (profile.hasPinSet) "Change PIN" else "Set PIN") }
                  if (profile.hasPinSet) {
                    TextButton(
                      onClick = {
                        viewModel.updateProfilePin(profile.id, null)
                        editingPinProfileId = null
                        newPin = ""
                        confirmPin = ""
                      },
                    ) { Text("Remove PIN") }
                  }
                  TextButton(
                    onClick = {
                      editingPinProfileId = null
                      newPin = ""
                      confirmPin = ""
                    },
                  ) { Text("Cancel") }
                }
              }
            } else {
              TextButton(onClick = { editingPinProfileId = profile.id }) {
                Text(if (profile.hasPinSet) "Manage PIN" else "Set PIN")
              }
            }
          }
        }
      }
      LibraryTab.Addons -> {
        item {
          GlassCard {
            Column(verticalArrangement = Arrangement.spacedBy(12.dp)) {
              OutlinedTextField(value = addonUrl, onValueChange = { addonUrl = it }, modifier = Modifier.fillMaxWidth(), label = { Text("Add-on link") }, singleLine = true)
              Button(onClick = {
                if (addonUrl.isNotBlank()) {
                  viewModel.installAddon(addonUrl.trim())
                  addonUrl = ""
                }
              }, modifier = Modifier.fillMaxWidth()) { Text("Install add-on") }
            }
          }
        }
        items(uiState.addons, key = { "addon-${it.id}" }) { addon ->
          GlassCard(modifier = animatedItem()) {
            Row(modifier = Modifier.fillMaxWidth(), horizontalArrangement = Arrangement.SpaceBetween, verticalAlignment = Alignment.CenterVertically) {
              Column(modifier = Modifier.weight(1f), verticalArrangement = Arrangement.spacedBy(4.dp)) {
                Text(addon.manifest.name, fontWeight = FontWeight.Bold)
                Text("${addon.manifest.version} - ${addon.id}", color = MaterialTheme.colorScheme.onSurface.copy(alpha = 0.72f))
                addon.manifest.description?.takeIf { it.isNotBlank() }?.let {
                  Text(it, color = MaterialTheme.colorScheme.onSurface.copy(alpha = 0.72f), maxLines = 2, overflow = TextOverflow.Ellipsis)
                }
              }
              Column(horizontalAlignment = Alignment.End, verticalArrangement = Arrangement.spacedBy(8.dp)) {
                Row(horizontalArrangement = Arrangement.spacedBy(4.dp)) {
                  TextButton(onClick = { viewModel.moveAddon(addon.id, -1) }) { Text("Up") }
                  TextButton(onClick = { viewModel.moveAddon(addon.id, 1) }) { Text("Down") }
                }
                Switch(checked = addon.enabled, onCheckedChange = { viewModel.toggleAddon(addon, it) })
                TextButton(onClick = { viewModel.uninstallAddon(addon.id) }) { Text("Remove") }
              }
            }
          }
        }
      }
      LibraryTab.Debrid -> {
        item {
          GlassCard {
            Column(verticalArrangement = Arrangement.spacedBy(12.dp)) {
              Row(horizontalArrangement = Arrangement.spacedBy(8.dp)) {
                DebridProviderOptions.forEach { (provider, label) ->
                  FilterChip(selected = selectedProvider == provider, onClick = { selectedProvider = provider }, label = { Text(label) })
                }
              }
              OutlinedTextField(value = providerApiKey, onValueChange = { providerApiKey = it }, modifier = Modifier.fillMaxWidth(), label = { Text("Service access key") }, singleLine = true)
              Button(onClick = {
                if (providerApiKey.isNotBlank()) {
                  viewModel.addDebridAccount(selectedProvider, providerApiKey.trim())
                  providerApiKey = ""
                }
              }, modifier = Modifier.fillMaxWidth()) { Text("Connect service") }
            }
          }
        }
        items(uiState.debridAccounts, key = { "debrid-${it.provider}" }) { account ->
          GlassCard(modifier = animatedItem()) {
            Row(modifier = Modifier.fillMaxWidth(), horizontalArrangement = Arrangement.SpaceBetween, verticalAlignment = Alignment.CenterVertically) {
              Column(verticalArrangement = Arrangement.spacedBy(4.dp)) {
                Text(debridProviderLabel(account.provider), fontWeight = FontWeight.Bold)
                Text(account.username ?: "Configured", color = MaterialTheme.colorScheme.onSurface.copy(alpha = 0.72f))
              }
              Column(horizontalAlignment = Alignment.End) {
                Row(horizontalArrangement = Arrangement.spacedBy(4.dp)) {
                  TextButton(onClick = { viewModel.moveDebridAccount(account.provider, -1) }) { Text("Up") }
                  TextButton(onClick = { viewModel.moveDebridAccount(account.provider, 1) }) { Text("Down") }
                }
                Switch(checked = account.enabled, onCheckedChange = { viewModel.setDebridAccountEnabled(account.provider, it) })
                TextButton(onClick = { viewModel.removeDebridAccount(account.provider) }) { Text("Remove") }
              }
            }
          }
        }
      }
      LibraryTab.Trakt -> {
        item {
          GlassCard {
            Column(verticalArrangement = Arrangement.spacedBy(12.dp)) {
              Text(if (uiState.traktStatus.connected) "Connected as ${uiState.traktStatus.username ?: "unknown"}" else "Trakt is not connected", fontWeight = FontWeight.Bold)
              uiState.pendingDeviceCode?.let { code ->
                Text("Go to ${code.verificationUrl} and enter ${code.userCode}", color = MaterialTheme.colorScheme.secondary)
              }
              Row(horizontalArrangement = Arrangement.spacedBy(8.dp)) {
                Button(onClick = viewModel::requestTraktDeviceCode) { Text("Start device auth") }
                if (uiState.pendingDeviceCode != null) {
                  Button(onClick = viewModel::pollTraktAuthorization) { Text("Check status") }
                }
                if (uiState.traktStatus.connected) {
                  TextButton(onClick = viewModel::disconnectTrakt) { Text("Disconnect") }
                }
              }
            }
          }
        }
        item {
          GlassCard {
            Column(verticalArrangement = Arrangement.spacedBy(6.dp)) {
              Text("Recommendations", fontWeight = FontWeight.Bold)
              uiState.traktRecommendations.take(5).forEach { item ->
        Text("${item.title}${item.year?.let { " ($it)" } ?: ""}")
              }
            }
          }
        }
        item {
          GlassCard {
            Column(verticalArrangement = Arrangement.spacedBy(6.dp)) {
              Text("Trending", fontWeight = FontWeight.Bold)
              uiState.traktTrending.take(5).forEach { item ->
        Text("${item.title}${item.year?.let { " ($it)" } ?: ""}")
              }
            }
          }
        }
      }
    }
  }
}

@Composable
private fun SettingsSection(title: String, content: @Composable ColumnScope.() -> Unit) {
  Column(verticalArrangement = Arrangement.spacedBy(12.dp)) {
    Text(title, style = MaterialTheme.typography.titleMedium, fontWeight = FontWeight.Bold, color = MaterialTheme.colorScheme.onSurface)
    Card(
      colors = CardDefaults.cardColors(containerColor = MaterialTheme.colorScheme.surface),
      shape = StreamDekRadius.panelShape,
    ) {
      Column(modifier = Modifier.padding(horizontal = 18.dp, vertical = 16.dp), content = content)
    }
  }
}

@Composable
private fun SettingsRow(icon: String, iconColor: Color, title: String, subtitle: String, trailing: @Composable (() -> Unit)? = null) {
  Row(modifier = Modifier.fillMaxWidth().padding(vertical = 6.dp), horizontalArrangement = Arrangement.spacedBy(14.dp), verticalAlignment = Alignment.CenterVertically) {
    Box(modifier = Modifier.size(46.dp).clip(StreamDekRadius.controlShape).background(iconColor.copy(alpha = 0.16f)), contentAlignment = Alignment.Center) {
      Text(icon, color = iconColor, fontWeight = FontWeight.Black)
    }
    Column(modifier = Modifier.weight(1f), verticalArrangement = Arrangement.spacedBy(2.dp)) {
      Text(title, style = MaterialTheme.typography.titleMedium, fontWeight = FontWeight.Black, color = MaterialTheme.colorScheme.onSurface)
      Text(subtitle, style = MaterialTheme.typography.bodyMedium, color = MaterialTheme.colorScheme.onSurface.copy(alpha = 0.68f))
    }
    if (trailing != null) trailing() else Text(">", color = MaterialTheme.colorScheme.onSurface.copy(alpha = 0.34f), style = MaterialTheme.typography.headlineSmall)
  }
}

@Composable
private fun SettingsDivider() {
  Box(modifier = Modifier.fillMaxWidth().padding(start = 66.dp).height(1.dp).background(MaterialTheme.colorScheme.onSurface.copy(alpha = 0.09f)))
}
@Composable
private fun AmbientTintSlider(percent: Int, enabled: Boolean, surface: String, onPercentChange: (Int) -> Unit) {
  Column(
    modifier = Modifier.fillMaxWidth().padding(vertical = 8.dp),
    verticalArrangement = Arrangement.spacedBy(6.dp),
  ) {
    Row(modifier = Modifier.fillMaxWidth(), horizontalArrangement = Arrangement.SpaceBetween, verticalAlignment = Alignment.CenterVertically) {
      Column(modifier = Modifier.weight(1f), verticalArrangement = Arrangement.spacedBy(2.dp)) {
        Text("Ambient Tint", style = MaterialTheme.typography.titleMedium, fontWeight = FontWeight.Black, color = MaterialTheme.colorScheme.onSurface)
        Text(
          if (enabled) "Lower values make the page tint more transparent, so more of the blurred artwork shows through on $surface."
          // Says what to do about it. The slider only has anything to act on while this page is
          // drawing artwork behind itself, and greying it out without saying why is how it looked
          // broken rather than inapplicable.
          else "Available when this page's Background Mode is Cinematic.",
          style = MaterialTheme.typography.bodyMedium,
          color = MaterialTheme.colorScheme.onSurface.copy(alpha = if (enabled) 0.68f else 0.42f),
        )
      }
      Text(
        "$percent%",
        color = if (enabled) MaterialTheme.colorScheme.primary else MaterialTheme.colorScheme.onSurface.copy(alpha = 0.42f),
        style = MaterialTheme.typography.labelLarge,
        fontWeight = FontWeight.Black,
      )
    }
    androidx.compose.material3.Slider(
      value = percent.toFloat(),
      onValueChange = { onPercentChange((it + 0.5f).toInt().coerceIn(20, 100)) },
      valueRange = 20f..100f,
      steps = 15,
      enabled = enabled,
      colors = androidx.compose.material3.SliderDefaults.colors(
        thumbColor = MaterialTheme.colorScheme.primary,
        activeTrackColor = MaterialTheme.colorScheme.primary,
        inactiveTrackColor = MaterialTheme.colorScheme.onSurface.copy(alpha = 0.18f),
        disabledThumbColor = MaterialTheme.colorScheme.onSurface.copy(alpha = 0.34f),
        disabledActiveTrackColor = MaterialTheme.colorScheme.onSurface.copy(alpha = 0.20f),
        disabledInactiveTrackColor = MaterialTheme.colorScheme.onSurface.copy(alpha = 0.10f),
      ),
    )
  }
}

@Composable
private fun HoldToSpeedMultiplierPicker(multiplier: Float, onMultiplierChange: (Float) -> Unit) {
  Column(
    modifier = Modifier.fillMaxWidth().padding(vertical = 8.dp),
    verticalArrangement = Arrangement.spacedBy(8.dp),
  ) {
    Column(verticalArrangement = Arrangement.spacedBy(2.dp)) {
      Text("Hold speed", style = MaterialTheme.typography.titleMedium, fontWeight = FontWeight.Black, color = MaterialTheme.colorScheme.onSurface)
      Text(
        "How fast to play while your finger is down. This multiplies whatever speed is already set.",
        style = MaterialTheme.typography.bodyMedium,
        color = MaterialTheme.colorScheme.onSurface.copy(alpha = 0.68f),
      )
    }
    Row(horizontalArrangement = Arrangement.spacedBy(10.dp)) {
      listOf(1.5f, 2f, 2.5f, 3f, 4f).forEach { option ->
        FilterChip(
          selected = multiplier == option,
          onClick = { onMultiplierChange(option) },
          label = { Text("${formatPlaybackSpeed(option)}x") },
        )
      }
    }
  }
}

@Composable
private fun NavigationAutoCollapseDelaySlider(seconds: Int, enabled: Boolean, onSecondsChange: (Int) -> Unit) {
