/**
 * Streaming sources currently on, across both plugin systems: JS plugin collections and the
 * compiled CloudStream (.cs3) providers. The Settings row counted only the former, so anyone
 * running CloudStream sources exclusively was told they had none.
 *
 * A provider only counts when its own collection is enabled too — disabling a collection leaves
 * its providers' individual flags untouched, so counting those alone would overstate it.
 */
private fun enabledStreamingSourceCount(): Int {
  val pluginState = StreamDekPlugins.manager.state
  val enabledPluginRepos = pluginState.repos.filter { it.enabled }.mapTo(mutableSetOf()) { it.url }
  val pluginSources = pluginState.providers.count { it.enabled && it.repoUrl in enabledPluginRepos }

  val skyStreamSources = if (!SkyStreamPlugins.isInitialized) 0 else SkyStreamPlugins.manager.activeProviders().size
  if (!CloudStreamPlugins.isInitialized) return pluginSources + skyStreamSources
  val cloudStreamState = CloudStreamPlugins.manager.state
  val enabledCloudStreamRepos = cloudStreamState.repos.filter { it.enabled }.mapTo(mutableSetOf()) { it.url }
  return pluginSources + skyStreamSources +
    cloudStreamState.providers.count { it.enabled && it.repoUrl in enabledCloudStreamRepos }
}

/**
 * Words that should find a settings page, beyond its own title and description.
 *
 * Exhaustive `when` rather than a hand-maintained list on purpose: a new settings page now fails
 * to compile until it has been given search terms. The list this replaced had drifted three pages
 * behind the enum — Catalog & Home Layout, M3U Playlists and Downloads were entirely unfindable,
 * so searching "iptv", "m3u" or "offline" led nowhere.
 */
/**
 * Settings pages matching [rawQuery], best first, or empty for a blank query.
 *
 * A match in the page's own name counts for far more than one in its description or keywords.
 * Without that weighting every page scored the same for a whole-query hit and ties fell back to
 * enum order, so typing "trakt" opened Sync Services — which merely mentions Trakt — instead of
 * the Trakt page itself.
 */
internal fun searchSettingsRoutes(rawQuery: String): List<SettingsRoute> {
  val stopWords = setOf("a", "an", "and", "can", "do", "for", "how", "i", "in", "is", "my", "of", "the", "to", "want", "where")
  val query = rawQuery.trim().lowercase()
  if (query.isBlank()) return emptyList()
  val tokens = query.split(Regex("[^a-z0-9]+"), limit = 0).filter { it.length > 1 && it !in stopWords }
  return SettingsRoute.values()
    .map { route ->
      val title = settingsRouteTitle(route).lowercase()
      val body = "${settingsRouteSubtitle(route)} ${settingsRouteKeywords(route)}".lowercase()
      var score = 0
      if (title == query) score += 100
      if (title.contains(query)) score += 60
      if (body.contains(query)) score += 20
      score += tokens.count(title::contains) * 5
      score += tokens.count(body::contains)
      route to score
    }
    .filter { it.second > 0 }
    // Title breaks ties rather than enum order, so the list cannot silently reorder when a new
    // page is added to the middle of the enum.
    .sortedWith(compareByDescending<Pair<SettingsRoute, Int>> { it.second }.thenBy { settingsRouteTitle(it.first) })
    .map { it.first }
}

internal fun settingsRouteKeywords(route: SettingsRoute): String = when (route) {
  SettingsRoute.Player -> "player engine mpv media3 exoplayer pip picture in picture floating " +
    "gesture gestures hold speed swipe seek scrub brightness volume level dim loudness " +
    "decoder hardware software compatibility display surface video will not play"
  SettingsRoute.SkipAndAutoplay -> "autoplay auto play skip intro recap ending credits next episode binge threshold introdb intro db api key"
  SettingsRoute.Subtitles -> "subtitle subtitles caption captions language languages audio preferred secondary forced show only addon loading source position style"
  SettingsRoute.Streams -> "streams stream results source quality resolution 4k 1080p size limit filter badges labels " +
    "formatting remember last source list"
  SettingsRoute.Downloads -> "download downloads offline saved save storage remove delete watch offline"
