/**
 * The animation-speed control.
 *
 * Its own composable rather than a bare [SettingsChoiceRow] because of the second line: when the
 * device's own reduce-motion setting is on it overrules whatever is selected here, and a row that
 * kept reporting "Cinematic" while the app animated nothing would be lying. The selection is left
 * alone and editable - turning the system setting off should restore the choice that was already
 * made - and the override is stated instead.
 */
@Composable
private fun AnimationSpeedRow(selected: AnimationSpeed, onSelected: (AnimationSpeed) -> Unit) {
  val motion = LocalMotionSettings.current
  Column(verticalArrangement = Arrangement.spacedBy(2.dp)) {
    SettingsChoiceRow(
      icon = "AN",
      iconColor = Color(0xFF34D399),
      title = "Animation Speed",
      subtitle = "How long transitions take across the app. Saved on this device only.",
      options = AnimationSpeed.entries.map { it.name },
      selected = selected.name,
      optionDescriptions = AnimationSpeed.entries.associate { it.name to it.description },
      onSelected = { name -> onSelected(AnimationSpeed.valueOf(name)) },
    )
    if (motion.overriddenBySystem) {
      Text(
        "This device's Reduce Motion setting is on, so animations are currently off regardless of "
          + "this choice. Your selection is kept and returns when you turn Reduce Motion off.",
        style = MaterialTheme.typography.bodySmall,
        color = MaterialTheme.colorScheme.onSurface.copy(alpha = 0.68f),
        modifier = Modifier.padding(start = 46.dp, end = 4.dp, bottom = 8.dp),
      )
    }
  }
}

/**
 * Relaxed or Compact, shown rather than described.
 *
 * A density is a hard thing to put into a sentence — Compact means smaller cards *and* tighter rows
 * *and* no bar under each header, and a one-line summary of that reads as jargon. So each option
 * carries a skeleton of the home screen it produces instead, and the skeleton is drawn from
 * [HomeLayoutMetrics] rather than by hand: the card proportions, the gaps and the header bar are the
 * screen's own numbers, so the preview cannot come to claim something Home does not do.
 */
@Composable
private fun HomeDensityPicker(selected: HomeDensity, onSelected: (HomeDensity) -> Unit) {
  Column(verticalArrangement = Arrangement.spacedBy(10.dp), modifier = Modifier.padding(vertical = 10.dp)) {
    Row(horizontalArrangement = Arrangement.spacedBy(14.dp), verticalAlignment = Alignment.CenterVertically) {
      SettingsIcon("DEN", Color(0xFF8B5CF6))
      Column(verticalArrangement = Arrangement.spacedBy(2.dp)) {
        Text("Home Layout", style = MaterialTheme.typography.titleMedium, fontWeight = FontWeight.SemiBold, color = MaterialTheme.colorScheme.onSurface)
        Text("Choose how much of Home fits on screen at once. Saved on this device only.", style = MaterialTheme.typography.bodySmall, color = MaterialTheme.colorScheme.onSurface.copy(alpha = 0.68f))
      }
    }
    Row(horizontalArrangement = Arrangement.spacedBy(10.dp)) {
      HomeDensity.entries.forEach { density ->
        val chosen = density == selected
        Column(
          modifier = Modifier
            .weight(1f)
            .clip(StreamDekRadius.cardShape)
            .background(if (chosen) MaterialTheme.colorScheme.primary.copy(alpha = 0.16f) else MaterialTheme.colorScheme.onSurface.copy(alpha = 0.04f))
            .border(1.dp, if (chosen) MaterialTheme.colorScheme.primary.copy(alpha = 0.64f) else MaterialTheme.colorScheme.onSurface.copy(alpha = 0.08f), StreamDekRadius.cardShape)
            .clickable { onSelected(density) }
            .padding(12.dp),
          verticalArrangement = Arrangement.spacedBy(8.dp),
        ) {
          HomeDensitySkeleton(HomeLayoutMetrics.forDensity(density))
          Text(density.label, color = MaterialTheme.colorScheme.onSurface, style = MaterialTheme.typography.labelLarge, fontWeight = FontWeight.Bold, maxLines = 1)
        }
      }
    }
    // The description belongs to the selection rather than to each card. Inside them it would wrap
    // to a different number of lines per option, and two cards of different heights side by side is
    // exactly the raggedness the skeletons are meant to avoid.
    Text(selected.description, color = MaterialTheme.colorScheme.onSurface.copy(alpha = 0.68f), style = MaterialTheme.typography.bodySmall)
  }
}

/**
 * A miniature of the home screen at one density: row headings, and a scrolling row of cards under
 * each.
 *
 * A drawing rather than a scale model — the numbers below are chosen for a panel a phone's width
 * across, not divided down from a phone. What comes from [HomeLayoutMetrics] is everything that
 * distinguishes the two answers: the card size goes through [HomeLayoutMetrics.card], so a Compact
 * card here is a fifth smaller exactly as it is on Home; the gaps keep the real ratio between the
 * modes; and the bar under each heading appears only where the screen draws one.
 *
 * The frame is a fixed height with the contents clipped, so the denser option genuinely fits more
 * rows into it. That is the whole claim the setting is making, made by the preview itself rather
 * than asserted in a caption.
 */
@Composable
private fun HomeDensitySkeleton(metrics: HomeLayoutMetrics) {
  val cardWidth = metrics.card(30.dp)
  val cardHeight = metrics.card(42.dp)
  Box(
    modifier = Modifier
      .fillMaxWidth()
      .height(HomeDensitySkeletonHeight)
      .clip(StreamDekRadius.badgeShape),
  ) {
    Column(verticalArrangement = Arrangement.spacedBy(metrics.rowGap * HomeDensitySkeletonSpacingScale)) {
      repeat(HomeDensitySkeletonRows) {
        Column(verticalArrangement = Arrangement.spacedBy(metrics.rowHeaderTitleGap * HomeDensitySkeletonSpacingScale)) {
          SkeletonBlock(modifier = Modifier.width(metrics.card(44.dp)).height(metrics.card(7.dp)), radius = 3.dp)
          if (metrics.showRowAccentBar) {
            SkeletonBlock(modifier = Modifier.width(metrics.card(20.dp)).height(4.dp), radius = 2.dp)
          }
        }
        Spacer(modifier = Modifier.height(metrics.rowHeaderGap * HomeDensitySkeletonSpacingScale))
        Row(horizontalArrangement = Arrangement.spacedBy(metrics.cardGap * HomeDensitySkeletonSpacingScale)) {
          repeat(HomeDensitySkeletonCardsPerRow) {
            SkeletonBlock(modifier = Modifier.width(cardWidth).height(cardHeight), radius = 4.dp)
          }
        }
      }
    }
  }
}

/** Tall enough to hold two Relaxed rows and the start of a third, which is where the two differ. */
private val HomeDensitySkeletonHeight = 132.dp

/** Enough rows and cards to overflow the frame in both directions, so both edges read as scrolling. */
private const val HomeDensitySkeletonRows = 4
private const val HomeDensitySkeletonCardsPerRow = 5

/**
 * Gaps in the preview are half the screen's own, so the *ratio* between the two modes survives
 * while the absolute numbers suit a panel this size. Card dimensions are not scaled this way — they
 * go through [HomeLayoutMetrics.card] so the 20% difference is shown exactly.
 */
private const val HomeDensitySkeletonSpacingScale = 0.5f

@Composable
private fun ThemePresetPicker(selected: AppThemePreset, onSelected: (AppThemePreset) -> Unit) {
  Column(verticalArrangement = Arrangement.spacedBy(10.dp), modifier = Modifier.padding(vertical = 10.dp)) {
    Row(horizontalArrangement = Arrangement.spacedBy(14.dp), verticalAlignment = Alignment.CenterVertically) {
      SettingsIcon("TH", Color(0xFFF59E0B))
      Column(verticalArrangement = Arrangement.spacedBy(2.dp)) {
        Text("Theme", style = MaterialTheme.typography.titleMedium, fontWeight = FontWeight.SemiBold, color = MaterialTheme.colorScheme.onSurface)
        Text("Choose the colour theme used across the app.", style = MaterialTheme.typography.bodySmall, color = MaterialTheme.colorScheme.onSurface.copy(alpha = 0.68f))
      }
    }
    androidx.compose.foundation.layout.FlowRow(horizontalArrangement = Arrangement.spacedBy(10.dp), verticalArrangement = Arrangement.spacedBy(10.dp)) {
      AppThemePreset.values().forEach { preset ->
        val palette = themeAccentPalette(preset, darkMode = MaterialTheme.colorScheme.background.luminance() <= 0.5f)
        Column(
          modifier = Modifier
            .width(104.dp)
            .clip(StreamDekRadius.cardShape)
            .background(if (selected == preset) MaterialTheme.colorScheme.primary.copy(alpha = 0.16f) else MaterialTheme.colorScheme.onSurface.copy(alpha = 0.04f))
            .border(1.dp, if (selected == preset) MaterialTheme.colorScheme.primary.copy(alpha = 0.64f) else MaterialTheme.colorScheme.onSurface.copy(alpha = 0.08f), StreamDekRadius.cardShape)
            .clickable { onSelected(preset) }
            .padding(12.dp),
          verticalArrangement = Arrangement.spacedBy(8.dp),
        ) {
          Row(horizontalArrangement = Arrangement.spacedBy(6.dp), verticalAlignment = Alignment.CenterVertically) {
            Box(modifier = Modifier.weight(1f).height(28.dp).clip(StreamDekRadius.controlShape).background(palette.accent))
            Box(modifier = Modifier.weight(1f).height(28.dp).clip(StreamDekRadius.controlShape).background(palette.tertiary))
          }
          Text(preset.name, color = MaterialTheme.colorScheme.onSurface, style = MaterialTheme.typography.labelLarge, fontWeight = FontWeight.Bold, maxLines = 1)
        }
      }
    }
  }
}

@Composable
private fun SettingsSwitchRow(icon: String, iconColor: Color, title: String, subtitle: String, checked: Boolean, onCheckedChange: (Boolean) -> Unit, logoProvider: String? = null, enabled: Boolean = true) {
  Row(modifier = Modifier.fillMaxWidth().padding(vertical = 10.dp), horizontalArrangement = Arrangement.spacedBy(14.dp), verticalAlignment = Alignment.CenterVertically) {
    if (logoProvider != null) {
      Image(
        painter = painterResource(ratingProviderLogoRes(logoProvider)),
        contentDescription = title,
        modifier = Modifier.size(22.dp),
        contentScale = ContentScale.Fit,
      )
    } else {
      SettingsIcon(icon, iconColor)
    }
    Column(modifier = Modifier.weight(1f), verticalArrangement = Arrangement.spacedBy(2.dp)) {
      Text(title, style = MaterialTheme.typography.titleMedium, fontWeight = FontWeight.SemiBold, color = MaterialTheme.colorScheme.onSurface)
      SettingsSubtitle(subtitle)
    }
    Switch(
      checked = checked,
      onCheckedChange = onCheckedChange,
      enabled = enabled,
      colors = SwitchDefaults.colors(
        checkedThumbColor = MaterialTheme.colorScheme.onPrimary,
        checkedTrackColor = MaterialTheme.colorScheme.primary,
        checkedBorderColor = MaterialTheme.colorScheme.primary,
        uncheckedThumbColor = MaterialTheme.colorScheme.onSurfaceVariant,
        uncheckedTrackColor = MaterialTheme.colorScheme.surfaceVariant,
        uncheckedBorderColor = MaterialTheme.colorScheme.outline,
      ),
    )
  }
}

@Composable
private fun SettingsChoiceRow(
  icon: String,
  iconColor: Color,
  title: String,
  subtitle: String,
  options: List<String>,
  selected: String,
  optionDescriptions: Map<String, String> = emptyMap(),
  onSelected: (String) -> Unit,
) {
  var showSheet by rememberSaveable(title) { mutableStateOf(false) }
  SettingsNavRow(icon = icon, iconColor = iconColor, title = title, subtitle = subtitle, value = settingsOptionLabel(title, selected), onClick = { showSheet = true })
  if (showSheet) {
    SettingsChoiceSheet(
      title = title,
      options = options,
      selected = selected,
      optionDescriptions = optionDescriptions,
      onDismiss = { showSheet = false },
      onSelected = {
        onSelected(it)
        showSheet = false
      },
    )
  }
}

/**
 * A language picker.
 *
 * Its own composable rather than a [SettingsChoiceRow] because the option list is every ISO
 * language: a sheet of 180-odd rows is only usable with a search field, and the row itself has to
 * show the language's name while storing its code.
 */
@Composable
private fun LanguageChoiceRow(
  icon: String,
  iconColor: Color,
  title: String,
  subtitle: String,
  options: List<String>,
  selected: String,
  onSelected: (String) -> Unit,
) {
  var showSheet by rememberSaveable(title) { mutableStateOf(false) }
  SettingsNavRow(
    icon = icon,
    iconColor = iconColor,
    title = title,
    subtitle = subtitle,
    value = Languages.label(selected),
    onClick = { showSheet = true },
  )
  if (showSheet) {
    LanguageChoiceSheet(
      title = title,
      options = options,
      selected = Languages.normalize(selected),
      onDismiss = { showSheet = false },
      onSelected = {
        onSelected(it)
        showSheet = false
      },
    )
  }
}

@Composable
private fun LanguageChoiceSheet(
  title: String,
  options: List<String>,
  selected: String,
  onDismiss: () -> Unit,
  onSelected: (String) -> Unit,
) {
  var query by rememberSaveable(title) { mutableStateOf("") }
  // Matched on the name rather than the code, since that is what the viewer is reading — but a
  // typed "de" or "ger" still finds German, because some people know the codes.
  val matches = remember(options, query) {
    val trimmed = query.trim()
    if (trimmed.isEmpty()) options else options.filter { code ->
      Languages.label(code).contains(trimmed, ignoreCase = true) || code.startsWith(trimmed, ignoreCase = true) ||
        Languages.tags(code).any { it.equals(trimmed, ignoreCase = true) }
    }
  }
  Dialog(onDismissRequest = onDismiss, properties = DialogProperties(usePlatformDefaultWidth = false)) {
    Box(
      modifier = Modifier.fillMaxSize().background(Color.Black.copy(alpha = 0.66f)).imePadding().clickable(onClick = onDismiss),
      contentAlignment = Alignment.BottomCenter,
    ) {
      Surface(
        // Capped rather than edge to edge. A phone is narrower than this so nothing changes there,
        // but on a tablet a full-width sheet stretches every language row across the window and
        // leaves its code stranded at the far edge, yards from the name it belongs to.
        modifier = Modifier.fillMaxWidth().widthIn(max = 640.dp).heightIn(max = 680.dp).clickable(enabled = false, onClick = {}),
        color = MaterialTheme.colorScheme.surface,
        shape = RoundedCornerShape(topStart = 30.dp, topEnd = 30.dp),
        border = BorderStroke(1.dp, MaterialTheme.colorScheme.onSurface.copy(alpha = 0.12f)),
      ) {
        Column(modifier = Modifier.padding(horizontal = 24.dp, vertical = 28.dp), verticalArrangement = Arrangement.spacedBy(14.dp)) {
          Text(title, color = MaterialTheme.colorScheme.onSurface, style = MaterialTheme.typography.titleLarge, fontWeight = FontWeight.SemiBold)
          OutlinedTextField(
            value = query,
            onValueChange = { query = it },
            modifier = Modifier.fillMaxWidth(),
            singleLine = true,
            placeholder = { Text("Search languages") },
            leadingIcon = { Icon(Icons.Rounded.Search, contentDescription = null) },
            shape = StreamDekRadius.thumbShape,
          )
          if (matches.isEmpty()) {
            Text(
              "No language matches \"${query.trim()}\".",
              color = MaterialTheme.colorScheme.onSurface.copy(alpha = 0.68f),
              style = MaterialTheme.typography.bodyMedium,
            )
          }
          LazyColumn(verticalArrangement = Arrangement.spacedBy(10.dp)) {
            items(matches, key = { it }) { option ->
              val isSelected = selected == Languages.normalize(option)
              Row(
                modifier = Modifier
                  .fillMaxWidth()
                  .clip(StreamDekRadius.cardShape)
                  .background(if (isSelected) MaterialTheme.colorScheme.primary.copy(alpha = 0.14f) else MaterialTheme.colorScheme.onSurface.copy(alpha = 0.04f))
                  .border(1.dp, if (isSelected) MaterialTheme.colorScheme.primary.copy(alpha = 0.86f) else MaterialTheme.colorScheme.onSurface.copy(alpha = 0.12f), StreamDekRadius.cardShape)
                  .clickable { onSelected(option) }
                  .padding(horizontal = 18.dp, vertical = 16.dp),
                verticalAlignment = Alignment.CenterVertically,
                horizontalArrangement = Arrangement.spacedBy(12.dp),
              ) {
                Text(
                  Languages.label(option),
                  modifier = Modifier.weight(1f),
                  color = MaterialTheme.colorScheme.onSurface,
                  style = MaterialTheme.typography.titleMedium,
                  fontWeight = if (isSelected) FontWeight.SemiBold else FontWeight.Normal,
                )
                if (option != Languages.ORIGINAL && option != Languages.NONE) {
                  Text(
                    option.uppercase(),
                    color = MaterialTheme.colorScheme.onSurface.copy(alpha = 0.5f),
                    style = MaterialTheme.typography.labelMedium,
                  )
                }
              }
            }
          }
        }
      }
    }
  }
}

@Composable
private fun SettingsChoiceSheet(
  title: String,
  options: List<String>,
  selected: String,
  optionDescriptions: Map<String, String> = emptyMap(),
  onDismiss: () -> Unit,
  onSelected: (String) -> Unit,
) {
  Dialog(onDismissRequest = onDismiss, properties = DialogProperties(usePlatformDefaultWidth = false)) {
    Box(
      modifier = Modifier
        .fillMaxSize()
        .background(Color.Black.copy(alpha = 0.66f))
        .clickable(onClick = onDismiss),
      contentAlignment = Alignment.BottomCenter,
    ) {
      Surface(
        // Same cap as the language sheet: the style previews inside are laid out two to a row, and
        // across a tablet's full width each one stretches into a band rather than a card.
        modifier = Modifier.fillMaxWidth().widthIn(max = 640.dp).heightIn(max = 680.dp).clickable(enabled = false, onClick = {}),
        color = MaterialTheme.colorScheme.surface,
        shape = RoundedCornerShape(topStart = 30.dp, topEnd = 30.dp),
        border = BorderStroke(1.dp, MaterialTheme.colorScheme.onSurface.copy(alpha = 0.12f)),
      ) {
        Column(modifier = Modifier.verticalScroll(rememberScrollState()).padding(horizontal = 24.dp, vertical = 28.dp), verticalArrangement = Arrangement.spacedBy(14.dp)) {
          Text(title, color = MaterialTheme.colorScheme.onSurface, style = MaterialTheme.typography.titleLarge, fontWeight = FontWeight.SemiBold)
          if (title == "Continue Watching Style" || title == "Title Page Style" || title == "Streaming Network Cards") {
            options.chunked(2).forEach { rowOptions ->
              Row(modifier = Modifier.fillMaxWidth(), horizontalArrangement = Arrangement.spacedBy(12.dp)) {
                rowOptions.forEach { option ->
                  val isSelected = selected == option
                  Column(
                    modifier = Modifier
                      .weight(1f)
                      .clip(StreamDekRadius.cardShape)
                      .background(if (isSelected) MaterialTheme.colorScheme.primary.copy(alpha = 0.14f) else MaterialTheme.colorScheme.onSurface.copy(alpha = 0.04f))
                      .border(1.dp, if (isSelected) MaterialTheme.colorScheme.primary.copy(alpha = 0.86f) else MaterialTheme.colorScheme.onSurface.copy(alpha = 0.12f), StreamDekRadius.cardShape)
                      .clickable { onSelected(option) }
                      .padding(horizontal = 14.dp, vertical = 14.dp),
                    verticalArrangement = Arrangement.spacedBy(12.dp),
                  ) {
                    if (title == "Continue Watching Style") {
                      ContinueWatchingStyleSkeletonPreview(
                        style = runCatching { ContinueWatchingStyle.valueOf(option) }.getOrDefault(ContinueWatchingStyle.Glass),
                        selected = isSelected,
                      )
                    } else if (title == "Streaming Network Cards") {
                      NetworkCardStyleSkeletonPreview(
                        style = runCatching { NetworkCardStyle.valueOf(option) }.getOrDefault(NetworkCardStyle.Branded),
                        selected = isSelected,
                      )
                    } else {
                      PageStyleSkeletonPreview(
                        style = runCatching { DetailPageStyle.valueOf(option) }.getOrDefault(DetailPageStyle.Classic),
                        selected = isSelected,
                      )
                    }
                    Text(settingsOptionLabel(title, option), color = MaterialTheme.colorScheme.onSurface, style = MaterialTheme.typography.titleMedium, fontWeight = FontWeight.SemiBold)
                    (optionDescriptions[option] ?: settingsOptionDescription(title, option))?.let { Text(it, color = MaterialTheme.colorScheme.onSurface.copy(alpha = 0.68f), style = MaterialTheme.typography.bodySmall) }
                  }
                }
                if (rowOptions.size == 1) Spacer(modifier = Modifier.weight(1f))
              }
            }
          } else {
            options.forEach { option ->
              val isSelected = selected == option
              Row(
                modifier = Modifier.fillMaxWidth().clip(StreamDekRadius.cardShape).background(if (isSelected) MaterialTheme.colorScheme.primary.copy(alpha = 0.14f) else MaterialTheme.colorScheme.onSurface.copy(alpha = 0.04f)).border(1.dp, if (isSelected) MaterialTheme.colorScheme.primary.copy(alpha = 0.86f) else MaterialTheme.colorScheme.onSurface.copy(alpha = 0.12f), StreamDekRadius.cardShape).clickable { onSelected(option) }.padding(horizontal = 18.dp, vertical = 16.dp),
                verticalAlignment = Alignment.CenterVertically,
                horizontalArrangement = Arrangement.spacedBy(12.dp),
              ) {
                Column(modifier = Modifier.weight(1f), verticalArrangement = Arrangement.spacedBy(4.dp)) {
                  Text(settingsOptionLabel(title, option), color = MaterialTheme.colorScheme.onSurface, style = MaterialTheme.typography.titleMedium, fontWeight = FontWeight.SemiBold)
                  (optionDescriptions[option] ?: settingsOptionDescription(title, option))?.let { Text(it, color = MaterialTheme.colorScheme.onSurface.copy(alpha = 0.68f), style = MaterialTheme.typography.bodySmall) }
                }
                if (isSelected) Icon(Icons.Rounded.CheckCircle, contentDescription = null, tint = MaterialTheme.colorScheme.primary) else Box(modifier = Modifier.size(22.dp).clip(CircleShape).border(2.dp, MaterialTheme.colorScheme.onSurface.copy(alpha = 0.34f), CircleShape))
              }
            }
          }
        }
      }
    }
  }
}

/**
 * The Streaming Networks row in miniature, so the choice is made by looking rather than by reading.
 *
 * Both options paint real artwork — the same two services either way, so what changes between the
 * previews is only the treatment, which is the thing being chosen.
 */
@Composable
private fun NetworkCardStyleSkeletonPreview(style: NetworkCardStyle, selected: Boolean) {
  val border = if (selected) MaterialTheme.colorScheme.onSurface.copy(alpha = 0.24f) else MaterialTheme.colorScheme.onSurface.copy(alpha = 0.12f)
  val branded = style == NetworkCardStyle.Branded
  Row(
    // Fixed so both options are the same height in the sheet, even though only one has captions.
    modifier = Modifier.fillMaxWidth().height(60.dp),
    horizontalArrangement = Arrangement.spacedBy(8.dp),
  ) {
    val previews = listOf(
      R.drawable.network_tile_netflix to R.drawable.network_logo_netflix,
      R.drawable.network_tile_prime_video to R.drawable.network_logo_prime_video,
    )
    previews.forEach { (tile, logo) ->
      Column(
        modifier = Modifier.weight(1f),
        horizontalAlignment = Alignment.CenterHorizontally,
        verticalArrangement = Arrangement.spacedBy(6.dp),
      ) {
        Box(
          modifier = Modifier
            .fillMaxWidth()
            .height(42.dp)
            .clip(StreamDekRadius.controlShape)
            .background(if (branded) Color(0xFF0E0E0E) else Color.White)
            .border(1.dp, border, StreamDekRadius.controlShape),
          contentAlignment = Alignment.Center,
        ) {
          AsyncImage(
            model = if (branded) tile else logo,
            contentDescription = null,
            modifier = if (branded) Modifier.fillMaxSize() else Modifier.fillMaxSize().padding(horizontal = 10.dp, vertical = 5.dp),
            contentScale = if (branded) ContentScale.Crop else ContentScale.Fit,
          )
        }
        if (!branded) SkeletonBlock(modifier = Modifier.fillMaxWidth(0.72f).height(6.dp), radius = 999.dp)
      }
    }
  }
}

@Composable
private fun ContinueWatchingStyleSkeletonPreview(style: ContinueWatchingStyle, selected: Boolean) {
  val border = if (selected) MaterialTheme.colorScheme.onSurface.copy(alpha = 0.24f) else MaterialTheme.colorScheme.onSurface.copy(alpha = 0.12f)
  val fill = if (selected) MaterialTheme.colorScheme.onSurface.copy(alpha = 0.10f) else MaterialTheme.colorScheme.onSurface.copy(alpha = 0.06f)
  when (style) {
    ContinueWatchingStyle.Cinematic -> {
      Box(
        modifier = Modifier
          .fillMaxWidth()
          .height(88.dp)
          .clip(StreamDekRadius.thumbShape)
          .background(fill)
          .border(1.dp, border, StreamDekRadius.thumbShape),
      ) {
        Column(modifier = Modifier.align(Alignment.BottomStart).fillMaxWidth().padding(10.dp), verticalArrangement = Arrangement.spacedBy(6.dp)) {
          SkeletonBlock(modifier = Modifier.fillMaxWidth(0.58f).height(12.dp), radius = 8.dp)
          SkeletonBlock(modifier = Modifier.fillMaxWidth(0.32f).height(8.dp), radius = 8.dp)
          SkeletonBlock(modifier = Modifier.fillMaxWidth().height(4.dp), radius = 999.dp)
        }
      }
    }
    ContinueWatchingStyle.Glass -> {
      Box(
        modifier = Modifier
          .fillMaxWidth()
          .height(88.dp)
          .clip(StreamDekRadius.thumbShape)
          .background(fill)
          .border(1.dp, border, StreamDekRadius.thumbShape),
      ) {
        SkeletonBlock(modifier = Modifier.fillMaxSize(), radius = 16.dp)
        Box(
          modifier = Modifier
            .align(Alignment.BottomCenter)
            .fillMaxWidth()
            .height(34.dp)
            .background(MaterialTheme.colorScheme.surface.copy(alpha = 0.72f))
            .border(
              width = 1.dp,
              color = MaterialTheme.colorScheme.onSurface.copy(alpha = 0.10f),
              shape = RectangleShape,
            ),
        )
        Column(
          modifier = Modifier.align(Alignment.BottomStart).fillMaxWidth().padding(horizontal = 10.dp, vertical = 6.dp),
          verticalArrangement = Arrangement.spacedBy(4.dp),
        ) {
          SkeletonBlock(modifier = Modifier.fillMaxWidth(0.58f).height(7.dp), radius = 8.dp)
          SkeletonBlock(modifier = Modifier.fillMaxWidth(0.32f).height(5.dp), radius = 8.dp)
          SkeletonBlock(modifier = Modifier.fillMaxWidth().height(3.dp), radius = 999.dp)
        }
      }
    }
    ContinueWatchingStyle.Ticket -> {
      Row(
        modifier = Modifier
          .fillMaxWidth()
          .height(64.dp)
          .clip(StreamDekRadius.thumbShape)
          .background(fill)
          .border(1.dp, border, StreamDekRadius.thumbShape)
          .padding(10.dp),
        horizontalArrangement = Arrangement.spacedBy(10.dp),
        verticalAlignment = Alignment.CenterVertically,
      ) {
        SkeletonBlock(modifier = Modifier.weight(1f).height(40.dp), radius = 10.dp)
        SkeletonBlock(modifier = Modifier.width(32.dp).height(12.dp), radius = 8.dp)
      }
    }
    ContinueWatchingStyle.Mini -> {
      Row(
        modifier = Modifier
          .fillMaxWidth()
          .height(58.dp)
          .clip(StreamDekRadius.thumbShape)
          .background(fill)
          .border(1.dp, border, StreamDekRadius.thumbShape)
          .padding(8.dp),
        horizontalArrangement = Arrangement.spacedBy(8.dp),
      ) {
        SkeletonBlock(modifier = Modifier.width(52.dp).fillMaxSize(), radius = 10.dp)
        Column(modifier = Modifier.weight(1f), verticalArrangement = Arrangement.spacedBy(6.dp)) {
          SkeletonBlock(modifier = Modifier.fillMaxWidth(0.64f).height(10.dp), radius = 8.dp)
          SkeletonBlock(modifier = Modifier.fillMaxWidth(0.36f).height(8.dp), radius = 8.dp)
          SkeletonBlock(modifier = Modifier.fillMaxWidth().height(4.dp), radius = 999.dp)
        }
      }
    }
    ContinueWatchingStyle.Stacked -> {
      Column(
        modifier = Modifier
          .fillMaxWidth()
          .clip(StreamDekRadius.thumbShape)
          .background(fill)
          .border(1.dp, border, StreamDekRadius.thumbShape)
          .padding(8.dp),
        verticalArrangement = Arrangement.spacedBy(8.dp),
      ) {
        SkeletonBlock(modifier = Modifier.fillMaxWidth().height(44.dp), radius = 10.dp)
        SkeletonBlock(modifier = Modifier.fillMaxWidth(0.62f).height(10.dp), radius = 8.dp)
        SkeletonBlock(modifier = Modifier.fillMaxWidth(0.40f).height(8.dp), radius = 8.dp)
      }
    }
  }
}

@Composable
private fun PageStyleSkeletonPreview(style: DetailPageStyle, selected: Boolean) {
  val border = if (selected) MaterialTheme.colorScheme.onSurface.copy(alpha = 0.24f) else MaterialTheme.colorScheme.onSurface.copy(alpha = 0.12f)
  val fill = if (selected) MaterialTheme.colorScheme.onSurface.copy(alpha = 0.10f) else MaterialTheme.colorScheme.onSurface.copy(alpha = 0.06f)
  Box(
    modifier = Modifier
      .fillMaxWidth()
      .height(128.dp)
      .clip(StreamDekRadius.thumbShape)
      .background(fill)
      .border(1.dp, border, StreamDekRadius.thumbShape)
      .padding(10.dp),
  ) {
    Column(modifier = Modifier.fillMaxSize(), verticalArrangement = Arrangement.spacedBy(8.dp)) {
      SkeletonBlock(modifier = Modifier.fillMaxWidth().weight(1f), radius = 12.dp)
      if (style == DetailPageStyle.Centered) {
        Column(modifier = Modifier.fillMaxWidth(), horizontalAlignment = Alignment.CenterHorizontally, verticalArrangement = Arrangement.spacedBy(6.dp)) {
          SkeletonBlock(modifier = Modifier.fillMaxWidth(0.54f).height(11.dp), radius = 8.dp)
          SkeletonBlock(modifier = Modifier.fillMaxWidth(0.72f).height(8.dp), radius = 8.dp)
        }
      } else {
        SkeletonBlock(modifier = Modifier.fillMaxWidth(0.62f).height(11.dp), radius = 8.dp)
        SkeletonBlock(modifier = Modifier.fillMaxWidth(0.78f).height(8.dp), radius = 8.dp)
      }
      Row(horizontalArrangement = Arrangement.spacedBy(6.dp), modifier = Modifier.fillMaxWidth()) {
        SkeletonBlock(modifier = Modifier.weight(1f).height(8.dp), radius = 999.dp)
        SkeletonBlock(modifier = Modifier.weight(1f).height(8.dp), radius = 999.dp)
        SkeletonBlock(modifier = Modifier.weight(1f).height(8.dp), radius = 999.dp)
      }
    }
  }
}

private fun settingsOptionLabel(title: String, option: String): String = when {
  title == "Background Mode" -> runCatching { backgroundModeLabel(BackgroundMode.valueOf(option)) }.getOrDefault(option)
  title == "Language" -> supportedAppLanguages[normalizeAppLanguage(option)] ?: "English"
  title == "Default Player" -> when (option) {
    "Auto" -> "Auto"
    "Media3" -> "ExoPlayer"
    "MPV" -> "libmpv"
    else -> option
  }
  title == "Max File Size" && option == "0" -> "Unlimited"
  title == "Max File Size" -> "$option GB"
  title == "Temporary Storage Limit" -> "$option GB"
  title == "Preferred Stream Quality" && option == "2160p" -> "4K"
  title == "Trailer resolution" && option == "2160p" -> "4K"
  title == "Preferred Stream Quality" && option == "Auto" -> "Best Available"
  title == "mpv Video Compatibility" -> when (option) {
    "HW+" -> "Recommended"
    "HW" -> "Device"
    "SW" -> "Safe mode"
    else -> option
  }
  title == "Playback Method" -> when (option) {
    "Local Server" -> "On this device"
    "Direct HTTP" -> "Direct links only"
    else -> option
  }
  title == "Startup Speed" -> when (option) {
    "default" -> "Balanced"
    "soft" -> "Gentler"
    "fast" -> "Faster"
    "ultra_fast" -> "Fastest"
    else -> option
  }
  title == "Animation Speed" -> runCatching { AnimationSpeed.valueOf(option).label }.getOrDefault(option)
  title == "Appearance" -> when (option) {
    AppAppearance.System.name -> "Follow system"
    AppAppearance.Dark.name -> "Dark"
    AppAppearance.Light.name -> "Light"
    else -> option
  }
  title == "Theme" -> when (option) {
    AppThemePreset.Monochrome.name -> "Monochrome"
    AppThemePreset.Ocean.name -> "Ocean"
    AppThemePreset.Emerald.name -> "Emerald"
    AppThemePreset.Amber.name -> "Amber"
    AppThemePreset.Crimson.name -> "Crimson"
    AppThemePreset.Rose.name -> "Rose"
    AppThemePreset.Violet.name -> "Violet"
    AppThemePreset.White.name -> "White"
    else -> option
  }
  title == "Continue Watching Style" -> when (option) {
    ContinueWatchingStyle.Cinematic.name -> "Cinematic"
    ContinueWatchingStyle.Glass.name -> "Glass"
    ContinueWatchingStyle.Ticket.name -> "Card"
    ContinueWatchingStyle.Mini.name -> "Wide"
    ContinueWatchingStyle.Stacked.name -> "Poster"
    else -> option
  }
  title == "Title Page Style" -> when (option) {
    DetailPageStyle.Classic.name -> "Classic"
    DetailPageStyle.Centered.name -> "Centered"
    else -> option
  }
  title == "Streaming Network Cards" -> when (option) {
    NetworkCardStyle.Classic.name -> "Logo tile"
    NetworkCardStyle.Branded.name -> "Branded"
    else -> option
  }
  else -> option
}

private fun settingsOptionDescription(title: String, option: String): String? = when (title) {
  "DoH Provider" -> StreamDekDoHProviders.firstOrNull { it.label == option }?.let { provider ->
    provider.endpoint ?: "Not configured"
  }
  "Background Mode" -> runCatching { backgroundModeDescription(BackgroundMode.valueOf(option)) }.getOrNull()
  "Language" -> when (normalizeAppLanguage(option)) {
    "en" -> "English"
    "es" -> "Español · Spanish"
    "fr" -> "Français · French"
    "it" -> "Italiano · Italian"
    "nl" -> "Nederlands · Dutch"
    else -> null
  }
  "Preferred Stream Quality" -> when (option) {
    "2160p" -> "Prefer 4K streams first."
    "1080p" -> "Prefer Full HD streams first."
    "720p" -> "Prefer HD streams first."
    else -> "Use StreamDek ranking without a fixed resolution target."
  }
  "Trailer resolution" -> when (option) {
    "2160p" -> "Use up to 4K when the trailer provides it."
    "1080p" -> "Use up to Full HD."
    "720p" -> "Use up to HD."
    else -> "Use up to 360p to reduce data use."
  }
  "Appearance" -> when (option) {
    AppAppearance.System.name -> "Follow the current device appearance."
    AppAppearance.Dark.name -> "Always use the dark app theme."
    AppAppearance.Light.name -> "Always use the light app theme."
    else -> null
  }
  "Theme" -> "Change the accent color used across supported controls and surfaces."
  "Max File Size" -> if (option == "0") "Do not filter streams by file size." else "Exclude streams larger than ${option} GB."
  "Badge Position" -> "Place Fusion badges at the ${option.lowercase()} of each stream card."
  "Continue Watching Style" -> when (option) {
    ContinueWatchingStyle.Cinematic.name -> "Large cinematic hero card."
    ContinueWatchingStyle.Glass.name -> "Backdrop card with a frosted information panel."
    ContinueWatchingStyle.Ticket.name -> "TV-style landscape card."
    ContinueWatchingStyle.Mini.name -> "Compact wide card."
    ContinueWatchingStyle.Stacked.name -> "Artwork-first poster card."
    else -> null
  }
  "Streaming Network Cards" -> when (option) {
    NetworkCardStyle.Classic.name -> "Each service's logo on a white tile and named"
    NetworkCardStyle.Branded.name -> "The service's own artwork, edge to edge."
    else -> null
  }
  "Title Page Style" -> "Use the $option layout on media pages."
  "Season Tabs" -> if (option == SeasonTabStyle.Posters.name) "Show image tabs for seasons." else "Use compact regular season tabs."
  else -> null
}

