private fun addonConfigureUrl(addon: InstalledAddon): String? {
  if (!addon.manifest.behaviorConfigurable) return null
  val rawBase = addon.manifest.baseUrl
    ?: addon.baseUrl
    ?: addon.manifest.transportUrl
    ?: addon.transportUrl
    ?: addon.manifest.manifestUrl
    ?: addon.manifest.url
    ?: addon.manifestUrl
    ?: addon.url
  val normalized = rawBase?.trim().orEmpty().trimEnd('/')
  if (normalized.isBlank()) return null
  return if (normalized.endsWith("/manifest.json", ignoreCase = true)) {
    normalized.removeSuffix("/manifest.json") + "/configure"
  } else {
    "$normalized/configure"
  }
}

@Composable
private fun AddonServiceCard(
  addon: InstalledAddon,
  index: Int,
  total: Int,
  onRefreshAddons: () -> Unit,
  onToggleAddon: (InstalledAddon, Boolean) -> Unit,
  onToggleFavourite: (InstalledAddon) -> Unit,
  onUninstallAddon: (String) -> Unit,
  onMoveAddon: (String, Int) -> Unit,
  dragScrollBy: suspend (Float) -> Float = { 0f },
) {
  val context = LocalContext.current
  val configureUrl = remember(addon.id, addon.manifest.behaviorConfigurable, addon.manifest.baseUrl, addon.baseUrl, addon.manifest.manifestUrl, addon.manifest.url, addon.url, addon.manifest.transportUrl, addon.transportUrl) { addonConfigureUrl(addon) }
  var expanded by rememberSaveable(addon.id) { mutableStateOf(false) }
  var showDetails by remember { mutableStateOf(false) }
  var displayNameVersion by remember { mutableStateOf(0) }
  val displayName = remember(addon.id, addon.manifest.name, displayNameVersion) { DisplayNameOverrides.resolve(addon.id, addon.manifest.name) }
  if (showDetails) AddonDetailsDialog(addon, displayName, { displayNameVersion++ }, { showDetails = false })

  val latestOnMove by rememberUpdatedState { delta: Int -> onMoveAddon(addon.id, delta) }
  var dragging by remember(addon.id) { mutableStateOf(false) }
  var dragOffsetY by remember(addon.id) { mutableFloatStateOf(0f) }
  var itemTopInRoot by remember(addon.id) { mutableFloatStateOf(0f) }
  var autoScrollStep by remember(addon.id) { mutableFloatStateOf(0f) }
  val density = LocalDensity.current
  val configuration = LocalConfiguration.current
  val screenHeightPx = with(density) { configuration.screenHeightDp.dp.toPx() }
  val topEdgePx = with(density) { 172.dp.toPx() }
  val bottomEdgePx = screenHeightPx - with(density) { 132.dp.toPx() }
  val maxAutoScrollStepPx = with(density) { 9.dp.toPx() }
  val reorderThresholdPx = with(density) { 74.dp.toPx() }

  fun applyDragDelta(delta: Float) {
    dragOffsetY += delta
    while (dragOffsetY > reorderThresholdPx) {
      dragOffsetY -= reorderThresholdPx
      latestOnMove(1)
    }
    while (dragOffsetY < -reorderThresholdPx) {
      dragOffsetY += reorderThresholdPx
      latestOnMove(-1)
    }
  }

  LaunchedEffect(dragging) {
    while (dragging) {
      val step = autoScrollStep
      if (step != 0f) {
        val consumed = dragScrollBy(step)
        if (consumed != 0f) applyDragDelta(consumed)
      }
      delay(16)
    }
  }

  Surface(
    modifier = Modifier
      .onGloballyPositioned { itemTopInRoot = it.positionInRoot().y }
      .zIndex(if (dragging) 2f else 0f)
      .graphicsLayer {
        translationY = dragOffsetY
        scaleX = if (dragging) 1.02f else 1f
        scaleY = if (dragging) 1.02f else 1f
        shadowElevation = if (dragging) 18f else 0f
      },
    color = MaterialTheme.colorScheme.surface,
    shape = StreamDekRadius.cardShape,
    border = BorderStroke(1.dp, MaterialTheme.colorScheme.onSurface.copy(alpha = 0.075f)),
  ) {
    Column(modifier = Modifier.fillMaxWidth().animateContentSize()) {
      Row(
        modifier = Modifier.fillMaxWidth().clickable { expanded = !expanded }.padding(14.dp),
        horizontalArrangement = Arrangement.spacedBy(12.dp),
        verticalAlignment = Alignment.CenterVertically,
      ) {
        Box(
          modifier = Modifier.pointerInput(addon.id) {
            detectDragGesturesAfterLongPress(
              onDragStart = {
                dragging = true
                dragOffsetY = 0f
                autoScrollStep = 0f
              },
              onDragEnd = {
                dragging = false
                dragOffsetY = 0f
                autoScrollStep = 0f
              },
              onDragCancel = {
                dragging = false
                dragOffsetY = 0f
                autoScrollStep = 0f
              },
              onDrag = { change, dragAmount ->
                change.consume()
                applyDragDelta(dragAmount.y)
                val pointerRootY = itemTopInRoot + dragOffsetY + change.position.y
                autoScrollStep = when {
                  pointerRootY < topEdgePx -> -((topEdgePx - pointerRootY) / 6f).coerceIn(0f, maxAutoScrollStepPx)
                  pointerRootY > bottomEdgePx -> ((pointerRootY - bottomEdgePx) / 6f).coerceIn(0f, maxAutoScrollStepPx)
                  else -> 0f
                }
              },
            )
          },
        ) {
          AddonLogo(addon)
        }
        Column(modifier = Modifier.weight(1f), verticalArrangement = Arrangement.spacedBy(3.dp)) {
          Text(displayName, style = MaterialTheme.typography.titleMedium, fontWeight = FontWeight.Bold, maxLines = 1, overflow = TextOverflow.Ellipsis)
          Text(
            buildString {
              append(if (addon.enabled) "Active" else "Off")
              append("  •  ${addon.manifest.catalogs.size} Home rows")
              if (addon.manifest.behaviorConfigurable) append("  •  Configurable")
            },
            color = MaterialTheme.colorScheme.onSurface.copy(alpha = 0.58f),
            style = MaterialTheme.typography.bodySmall,
            maxLines = 1,
            overflow = TextOverflow.Ellipsis,
          )
        }
        IconButton(onClick = { onToggleFavourite(addon) }) {
          Icon(
            if (addon.favourite) Icons.Rounded.Star else Icons.Rounded.StarBorder,
            contentDescription = if (addon.favourite) "Remove $displayName from favourites" else "Add $displayName to favourites",
            tint = if (addon.favourite) Color(0xFFFACC15) else MaterialTheme.colorScheme.onSurface.copy(alpha = 0.72f),
          )
        }
        Switch(checked = addon.enabled, onCheckedChange = { onToggleAddon(addon, it) })
        Icon(
          if (expanded) Icons.Rounded.KeyboardArrowUp else Icons.Rounded.KeyboardArrowDown,
          contentDescription = if (expanded) "Hide actions" else "Show actions",
          tint = MaterialTheme.colorScheme.onSurface.copy(alpha = 0.58f),
        )
      }
      AnimatedVisibility(visible = expanded) {
        Column(modifier = Modifier.fillMaxWidth().padding(start = 14.dp, end = 14.dp, bottom = 12.dp), verticalArrangement = Arrangement.spacedBy(8.dp)) {
          SettingsDivider()
          addon.manifest.description?.takeIf { it.isNotBlank() }?.let {
            Text(it, color = MaterialTheme.colorScheme.onSurface.copy(alpha = 0.62f), style = MaterialTheme.typography.bodySmall, maxLines = 2, overflow = TextOverflow.Ellipsis)
          }
          Row(modifier = Modifier.fillMaxWidth(), horizontalArrangement = Arrangement.spacedBy(2.dp), verticalAlignment = Alignment.CenterVertically) {
            IconButton(onClick = { showDetails = true }) { Icon(Icons.Rounded.Info, contentDescription = "Add-on details") }
            if (configureUrl != null) IconButton(onClick = {
              runCatching { context.startActivity(Intent(Intent.ACTION_VIEW, Uri.parse(configureUrl)).addFlags(Intent.FLAG_ACTIVITY_NEW_TASK)) }
            }) { Icon(Icons.Rounded.Settings, contentDescription = "Configure add-on") }
            Spacer(Modifier.weight(1f))
            IconButton(onClick = { onMoveAddon(addon.id, -1) }, enabled = index > 0) { Icon(Icons.Rounded.KeyboardArrowUp, "Move up") }
            IconButton(onClick = { onMoveAddon(addon.id, 1) }, enabled = index < total - 1) { Icon(Icons.Rounded.KeyboardArrowDown, "Move down") }
            IconButton(onClick = onRefreshAddons) { Icon(Icons.Rounded.Refresh, "Refresh") }
            IconButton(onClick = { onUninstallAddon(addon.id) }) { Icon(Icons.Rounded.Delete, "Remove", tint = Color(0xFFEF476F)) }
          }
        }
      }
    }
  }
}

@Composable
private fun DetailRow(label: String, value: String) {
  Column(verticalArrangement = Arrangement.spacedBy(2.dp)) {
    Text(label, style = MaterialTheme.typography.labelMedium, color = MaterialTheme.colorScheme.onSurface.copy(alpha = 0.56f))
    Text(value, style = MaterialTheme.typography.bodyMedium, color = MaterialTheme.colorScheme.onSurface)
  }
}

/**
 * A URL worth having rather than just reading: the address is shown in full, and can be taken.
 *
 * An add-on is identified by where it came from — two installs with the same name are told apart by
 * their address and nothing else — but an address is only useful somewhere: pasted into another
 * device's install box, or opened to see what is actually there. Printing it and leaving the viewer
 * to copy it off the screen by hand is what makes a long signed manifest URL unusable.
 *
 * The text wraps rather than ellipsising for the same reason. The distinguishing part of these is
 * often the very end.
 */
@Composable
private fun DetailUrlRow(label: String, url: String) {
  val clipboard = LocalClipboardManager.current
  val context = LocalContext.current
  Column(verticalArrangement = Arrangement.spacedBy(6.dp)) {
    Text(label, style = MaterialTheme.typography.labelMedium, color = MaterialTheme.colorScheme.onSurface.copy(alpha = 0.56f))
    Text(url, style = MaterialTheme.typography.bodySmall, color = MaterialTheme.colorScheme.onSurface.copy(alpha = 0.86f))
    Row(horizontalArrangement = Arrangement.spacedBy(8.dp)) {
      OutlinedButton(
        onClick = {
          clipboard.setText(AnnotatedString(url))
          android.widget.Toast.makeText(context, "Address copied", android.widget.Toast.LENGTH_SHORT).show()
        },
        shape = StreamDekRadius.pill,
      ) { Text("Copy") }
      OutlinedButton(
        onClick = { openExternalUrl(context, url) },
        shape = StreamDekRadius.pill,
      ) { Text("Open") }
    }
  }
}

@Composable
private fun AddonDetailsDialog(addon: InstalledAddon, displayName: String, onRenamed: () -> Unit, onDismiss: () -> Unit) {
  var nameField by remember(addon.id) { mutableStateOf(displayName) }
  Dialog(onDismissRequest = onDismiss) {
    Surface(shape = StreamDekRadius.panelShape, color = MaterialTheme.colorScheme.surface, border = BorderStroke(1.dp, MaterialTheme.colorScheme.onSurface.copy(alpha = 0.10f))) {
      Column(modifier = Modifier.fillMaxWidth().heightIn(max = 560.dp).verticalScroll(rememberScrollState()).padding(20.dp), verticalArrangement = Arrangement.spacedBy(14.dp)) {
        Row(verticalAlignment = Alignment.CenterVertically, horizontalArrangement = Arrangement.spacedBy(12.dp)) {
          AddonLogo(addon)
          Column(modifier = Modifier.weight(1f)) {
            Text("Add-on details", style = MaterialTheme.typography.labelMedium, color = MaterialTheme.colorScheme.onSurface.copy(alpha = 0.56f))
            Text(addon.manifest.name, style = MaterialTheme.typography.titleMedium, fontWeight = FontWeight.Black, maxLines = 2, overflow = TextOverflow.Ellipsis)
          }
        }
        if (LocalAddonManager.isLocalAddonId(addon.id)) {
          Text(
            "This add-on is available while your phone is connected to the same network as the device providing it.",
            color = MaterialTheme.colorScheme.onSurface.copy(alpha = 0.62f),
            style = MaterialTheme.typography.bodySmall,
          )
        }
        SettingsDivider()
        OutlinedTextField(
          value = nameField,
          onValueChange = { nameField = it },
          label = { Text("Display name") },
          singleLine = true,
          modifier = Modifier.fillMaxWidth(),
        )
        Row(horizontalArrangement = Arrangement.spacedBy(10.dp)) {
          Button(onClick = {
            DisplayNameOverrides.set(addon.id, nameField.takeIf { it.isNotBlank() && it != addon.manifest.name })
            onRenamed()
          }, enabled = nameField.isNotBlank()) { Text("Save name") }
          if (DisplayNameOverrides.get(addon.id) != null) {
            TextButton(onClick = {
              DisplayNameOverrides.clear(addon.id)
              nameField = addon.manifest.name
              onRenamed()
            }) { Text("Reset to default") }
          }
        }
        SettingsDivider()
        DetailRow("Version", addon.manifest.version)
        addon.manifest.description?.takeIf { it.isNotBlank() }?.let { DetailRow("About", it) }
        // Where this one came from. The manifest address is the install itself — it is what was
        // added, what identifies it against another copy of the same add-on, and what has to be
        // typed into the next device — so it is the address shown, with the others standing in only
        // if an install recorded no manifest URL.
        listOfNotNull(addon.manifestUrl, addon.transportUrl, addon.url, addon.baseUrl)
          .firstOrNull { it.isNotBlank() }
          ?.let { DetailUrlRow("Address", it) }
        DetailRow(
          "Setup",
          when {
            addon.manifest.configurationRequired -> "Finish setup before using"
            addon.manifest.behaviorConfigurable -> "Optional settings available"
            else -> "Ready to use"
          },
        )
        if (addon.manifest.catalogs.isNotEmpty()) {
          Text("Home rows (${addon.manifest.catalogs.size})", style = MaterialTheme.typography.labelLarge, fontWeight = FontWeight.Bold, color = MaterialTheme.colorScheme.onSurface)
          addon.manifest.catalogs.forEach { catalog ->
            Text("• ${catalog.name.ifBlank { "Untitled row" }}", style = MaterialTheme.typography.bodySmall, color = MaterialTheme.colorScheme.onSurface.copy(alpha = 0.70f))
          }
        }
        TextButton(onClick = onDismiss, modifier = Modifier.align(Alignment.End)) { Text("Close") }
      }
    }
  }
}

/**
 * How subtitles look, shown against a sample of what they will look like.
 *
 * The preview earns its place: size, colour and outline are all judged against video rather than
 * read as numbers, and a viewer changing them here is not sitting in front of a playing film.
 */
@Composable
private fun SubtitleAppearanceSettings(
  uiState: AppUiState,
  onTextSizeChange: (Int) -> Unit,
  onVerticalOffsetChange: (Int) -> Unit,
  onBoldChange: (Boolean) -> Unit,
  onTextColorChange: (String) -> Unit,
  onBackgroundColorChange: (String) -> Unit,
  onOutlineChange: (Boolean) -> Unit,
  onOutlineColorChange: (String) -> Unit,
) {
  Column(verticalArrangement = Arrangement.spacedBy(12.dp)) {
    Text("Appearance", style = MaterialTheme.typography.titleMedium, fontWeight = FontWeight.Bold, color = MaterialTheme.colorScheme.onSurface)
    SubtitlePreviewCard(uiState)
    Card(
      colors = CardDefaults.cardColors(containerColor = MaterialTheme.colorScheme.surface),
      shape = StreamDekRadius.panelShape,
    ) {
      Column(modifier = Modifier.padding(horizontal = 18.dp, vertical = 16.dp)) {
        SettingsSliderRow(
          icon = "SIZE",
          iconColor = Color(0xFFA78BFA),
          title = "Text Size",
          subtitle = "How large subtitle text is drawn over the picture.",
          value = uiState.subtitleTextSize,
          range = SUBTITLE_TEXT_SIZE_RANGE,
          valueLabel = "${uiState.subtitleTextSize}",
          onValueChange = onTextSizeChange,
        )
        SettingsDivider()
        SettingsSliderRow(
          icon = "POS",
          iconColor = Color(0xFF38BDF8),
          title = "Vertical Position",
          subtitle = "Move subtitles up away from the bottom edge, clear of on-screen controls.",
          value = uiState.subtitleVerticalOffset,
          range = SUBTITLE_OFFSET_RANGE,
          valueLabel = "${uiState.subtitleVerticalOffset}",
          onValueChange = onVerticalOffsetChange,
        )
        SettingsDivider()
        SettingsSwitchRow("BOLD", Color(0xFFF97316), "Bold Text", "Use a heavier weight so subtitles hold up against bright scenes.", uiState.subtitleBold, onBoldChange)
        SettingsDivider()
        SubtitleColorRow("TEXT", Color(0xFF22C55E), "Text Colour", "The colour of the subtitle text itself.", SUBTITLE_COLOR_CHOICES, uiState.subtitleTextColor, onTextColorChange)
        SettingsDivider()
        SubtitleColorRow("FILL", Color(0xFF94A3B8), "Background", "A panel drawn behind the text. Transparent leaves the picture untouched.", SUBTITLE_FILL_CHOICES, uiState.subtitleBackgroundColor, onBackgroundColorChange)
        SettingsDivider()
        SettingsSwitchRow("EDGE", Color(0xFFFACC15), "Outline", "Trace subtitle text so it stays readable over pale scenes.", uiState.subtitleOutline, onOutlineChange)
        if (uiState.subtitleOutline) {
          SettingsDivider()
          SubtitleColorRow("LINE", Color(0xFFEC4899), "Outline Colour", "The colour traced around each character.", SUBTITLE_COLOR_CHOICES, uiState.subtitleOutlineColor, onOutlineColorChange)
        }
      }
    }
  }
}

/** A sample line of subtitle, drawn exactly as the player will draw it. */
@Composable
private fun SubtitlePreviewCard(uiState: AppUiState) {
  val textColor = Color(parseSubtitleColor(uiState.subtitleTextColor))
  val backgroundColor = Color(parseSubtitleColor(uiState.subtitleBackgroundColor))
  val outlineColor = Color(parseSubtitleColor(uiState.subtitleOutlineColor))
  // mpv sizes subtitles against the video height, where 55 is its default; the preview mirrors that
  // ratio so the slider reads the same here as it does in the player.
  val previewSize = (uiState.subtitleTextSize / 55f * 15f).sp
  // The preview frame stands in for the video frame, so the position slider can be read the way
  // the player reads it: the number is how far down the picture the line sits, 100 being the very
  // bottom edge. Past that the line runs off the frame here exactly as it would off the video.
  val frameHeight = 168.dp
  val density = LocalDensity.current
  var lineHeight by remember { mutableStateOf(0.dp) }
  val lineTop = (frameHeight * (uiState.subtitleVerticalOffset / 100f)) - lineHeight
  Box(
    modifier = Modifier
      .fillMaxWidth()
      .height(frameHeight)
      .clip(StreamDekRadius.panelShape)
      .background(
        Brush.verticalGradient(
          listOf(Color(0xFF1E2536), Color(0xFF0B0F1A)),
        ),
      ),
  ) {
    Text(
      "Preview",
      modifier = Modifier.align(Alignment.TopStart).padding(horizontal = 18.dp, vertical = 14.dp),
      style = MaterialTheme.typography.labelSmall,
      fontWeight = FontWeight.Black,
      letterSpacing = 1.2.sp,
      color = Color.White.copy(alpha = 0.34f),
    )
    Box(
      modifier = Modifier
        .align(Alignment.TopCenter)
        .offset(y = lineTop)
        .padding(horizontal = 18.dp)
        .onSizeChanged { lineHeight = with(density) { it.height.toDp() } }
        .clip(StreamDekRadius.badgeShape)
        .background(backgroundColor)
        .padding(horizontal = 10.dp, vertical = 4.dp),
    ) {
      if (uiState.subtitleOutline) {
        // Compose has no text stroke, so the outline is four offset copies behind the glyphs —
        // enough to read as a traced edge at subtitle sizes.
        listOf(-1f to 0f, 1f to 0f, 0f to -1f, 0f to 1f).forEach { (dx, dy) ->
          Text(
            SUBTITLE_PREVIEW_LINE,
            modifier = Modifier.graphicsLayer { translationX = dx * 2.4f; translationY = dy * 2.4f },
            color = outlineColor,
            fontSize = previewSize,
            fontWeight = if (uiState.subtitleBold) FontWeight.Bold else FontWeight.Medium,
            textAlign = androidx.compose.ui.text.style.TextAlign.Center,
          )
        }
      }
      Text(
        SUBTITLE_PREVIEW_LINE,
        color = textColor,
        fontSize = previewSize,
        fontWeight = if (uiState.subtitleBold) FontWeight.Bold else FontWeight.Medium,
        textAlign = androidx.compose.ui.text.style.TextAlign.Center,
      )
    }
  }
}

private const val SUBTITLE_PREVIEW_LINE = "The quick brown fox jumps over the lazy dog."

internal fun parseSubtitleColor(value: String): Int =
  runCatching { android.graphics.Color.parseColor(value.trim()) }.getOrDefault(android.graphics.Color.WHITE)

/** A choice row that shows the chosen colour rather than only naming it. */
@Composable
private fun SubtitleColorRow(
  icon: String,
  iconColor: Color,
  title: String,
  subtitle: String,
  choices: List<Pair<String, String>>,
  selected: String,
  onSelected: (String) -> Unit,
) {
  var showSheet by rememberSaveable(title) { mutableStateOf(false) }
  Row(
    modifier = Modifier.fillMaxWidth().clip(StreamDekRadius.cardShape).clickable { showSheet = true }.padding(vertical = 10.dp),
    horizontalArrangement = Arrangement.spacedBy(14.dp),
    verticalAlignment = Alignment.CenterVertically,
  ) {
    SettingsIcon(icon, iconColor)
    Column(modifier = Modifier.weight(1f), verticalArrangement = Arrangement.spacedBy(2.dp)) {
      Text(title, style = MaterialTheme.typography.titleMedium, fontWeight = FontWeight.SemiBold, color = MaterialTheme.colorScheme.onSurface)
      Text(subtitle, style = MaterialTheme.typography.bodySmall, color = MaterialTheme.colorScheme.onSurface.copy(alpha = 0.68f), maxLines = 3, overflow = TextOverflow.Ellipsis)
    }
    SubtitleColorSwatch(selected)
    Text(subtitleColorLabel(selected), color = MaterialTheme.colorScheme.onSurface.copy(alpha = 0.68f), style = MaterialTheme.typography.bodyMedium, maxLines = 1)
    Icon(Icons.AutoMirrored.Rounded.KeyboardArrowRight, contentDescription = null, tint = MaterialTheme.colorScheme.onSurface.copy(alpha = 0.34f))
  }
  if (showSheet) {
    SettingsChoiceSheet(
      title = title,
      options = choices.map { it.first },
      selected = subtitleColorLabel(selected),
      onDismiss = { showSheet = false },
      onSelected = { label ->
        choices.firstOrNull { it.first == label }?.let { onSelected(it.second) }
        showSheet = false
      },
    )
  }
}

@Composable
private fun SubtitleColorSwatch(value: String) {
  Box(
    modifier = Modifier
      .size(22.dp)
      .clip(StreamDekRadius.badgeShape)
      .background(MaterialTheme.colorScheme.onSurface.copy(alpha = 0.10f))
      .padding(2.dp)
      .clip(StreamDekRadius.badgeShape)
      .background(Color(parseSubtitleColor(value))),
  )
}

/** A labelled slider that sits in a settings card alongside the switch and choice rows. */
@Composable
private fun SettingsSliderRow(
  icon: String,
  iconColor: Color,
  title: String,
  subtitle: String,
  value: Int,
  range: IntRange,
  valueLabel: String,
  onValueChange: (Int) -> Unit,
) {
  Column(modifier = Modifier.fillMaxWidth().padding(vertical = 10.dp), verticalArrangement = Arrangement.spacedBy(4.dp)) {
    Row(horizontalArrangement = Arrangement.spacedBy(14.dp), verticalAlignment = Alignment.CenterVertically) {
      SettingsIcon(icon, iconColor)
      Column(modifier = Modifier.weight(1f), verticalArrangement = Arrangement.spacedBy(2.dp)) {
        Text(title, style = MaterialTheme.typography.titleMedium, fontWeight = FontWeight.SemiBold, color = MaterialTheme.colorScheme.onSurface)
        Text(subtitle, style = MaterialTheme.typography.bodySmall, color = MaterialTheme.colorScheme.onSurface.copy(alpha = 0.68f), maxLines = 3, overflow = TextOverflow.Ellipsis)
      }
      Text(valueLabel, color = MaterialTheme.colorScheme.primary, style = MaterialTheme.typography.labelLarge, fontWeight = FontWeight.Black)
    }
    androidx.compose.material3.Slider(
      value = value.toFloat(),
      onValueChange = { onValueChange((it + 0.5f).toInt().coerceIn(range)) },
      valueRange = range.first.toFloat()..range.last.toFloat(),
      colors = androidx.compose.material3.SliderDefaults.colors(
        thumbColor = MaterialTheme.colorScheme.primary,
        activeTrackColor = MaterialTheme.colorScheme.primary,
        inactiveTrackColor = MaterialTheme.colorScheme.onSurface.copy(alpha = 0.18f),
      ),
    )
  }
}

@Composable
private fun SubtitleSourcesSettings(ownerKey: String) {
  val context = LocalContext.current
  var sourceUrl by rememberSaveable { mutableStateOf("") }
  var sources by remember(ownerKey) { mutableStateOf(UserSubtitleSourceStore.load(context, ownerKey)) }
  var message by remember { mutableStateOf<String?>(null) }

  fun refreshSources() {
    sources = UserSubtitleSourceStore.load(context, ownerKey)
  }

  SettingsSection("Subtitle Sources") {
    SettingsStaticRow("SUB", Color(0xFFA78BFA), "OpenSubtitles", "Built in and always available.")
    if (sources.isNotEmpty()) SettingsDivider()
    sources.forEachIndexed { index, source ->
      if (index > 0) SettingsDivider()
      Row(modifier = Modifier.fillMaxWidth().padding(vertical = 10.dp), horizontalArrangement = Arrangement.spacedBy(12.dp), verticalAlignment = Alignment.CenterVertically) {
        Column(modifier = Modifier.weight(1f), verticalArrangement = Arrangement.spacedBy(3.dp)) {
          Text(source.name, color = MaterialTheme.colorScheme.onSurface, fontWeight = FontWeight.Bold)
          Text("Included in subtitle searches", color = MaterialTheme.colorScheme.onSurface.copy(alpha = 0.58f), style = MaterialTheme.typography.bodySmall)
        }
        Switch(
          checked = source.enabled,
          onCheckedChange = { enabled ->
            UserSubtitleSourceStore.setEnabled(context, ownerKey, source.id, enabled)
            refreshSources()
          },
        )
        IconButton(onClick = {
          UserSubtitleSourceStore.remove(context, ownerKey, source.id)
          refreshSources()
          message = "Subtitle source removed."
        }) {
          Icon(Icons.Rounded.Delete, contentDescription = "Remove subtitle source", tint = MaterialTheme.colorScheme.error)
        }
      }
    }
    Spacer(modifier = Modifier.height(12.dp))
    Text("Add your own", color = MaterialTheme.colorScheme.onSurface, style = MaterialTheme.typography.titleMedium, fontWeight = FontWeight.Black)
    Text("Paste the link supplied by your subtitle provider. StreamDek will search it alongside the built-in source.", color = MaterialTheme.colorScheme.onSurface.copy(alpha = 0.66f), style = MaterialTheme.typography.bodySmall)
    Spacer(modifier = Modifier.height(10.dp))
    OutlinedTextField(
      value = sourceUrl,
      onValueChange = { sourceUrl = it; message = null },
      modifier = Modifier.fillMaxWidth(),
      placeholder = { InputGuideText("Paste subtitle add-on link") },
      leadingIcon = { Icon(Icons.Rounded.Link, contentDescription = null) },
      singleLine = true,
    )
    Spacer(modifier = Modifier.height(10.dp))
    Button(
      onClick = {
        UserSubtitleSourceStore.add(context, ownerKey, sourceUrl)
          .onSuccess {
            sourceUrl = ""
            message = "Subtitle source added."
            refreshSources()
          }
          .onFailure { message = it.message ?: "Could not add that subtitle source." }
      },
      enabled = sourceUrl.isNotBlank(),
      modifier = Modifier.fillMaxWidth(),
    ) { Text("Add Subtitle Source", fontWeight = FontWeight.Bold) }
    message?.let { Text(it, color = MaterialTheme.colorScheme.onSurface.copy(alpha = 0.72f), style = MaterialTheme.typography.bodySmall) }
  }
}

private data class PluginSourceTestState(
  val providerName: String,
  val testLabel: String,
  val loading: Boolean = true,
  val streams: List<AddonStream> = emptyList(),
  val error: String? = null,
)

@Composable
private fun PluginSourceTestDialog(state: PluginSourceTestState, onDismiss: () -> Unit) {
  AlertDialog(
    onDismissRequest = onDismiss,
    title = { Text("Test ${state.providerName}", fontWeight = FontWeight.Black) },
    text = {
      Column(verticalArrangement = Arrangement.spacedBy(10.dp)) {
        Text(state.testLabel, color = MaterialTheme.colorScheme.onSurface.copy(alpha = 0.68f), style = MaterialTheme.typography.bodySmall)
        when {
          state.loading -> Row(horizontalArrangement = Arrangement.spacedBy(10.dp), verticalAlignment = Alignment.CenterVertically) {
            CircularProgressIndicator(modifier = Modifier.size(22.dp), strokeWidth = 2.dp)
            Text("Checking this source...")
          }
          state.error != null -> Text(state.error, color = MaterialTheme.colorScheme.error)
          state.streams.isEmpty() -> Text("The source completed its ${state.testLabel.substringBefore(" •")} check but returned no playable results. It may be offline, region-blocked, or not carry this title.")
          else -> {
            Text("${state.streams.size} sample ${if (state.streams.size == 1) "result" else "results"}", fontWeight = FontWeight.Bold)
            state.streams.forEach { stream ->
              Surface(shape = StreamDekRadius.controlShape, color = MaterialTheme.colorScheme.onSurface.copy(alpha = 0.055f)) {
                Column(Modifier.fillMaxWidth().padding(10.dp), verticalArrangement = Arrangement.spacedBy(2.dp)) {
                  Text(streamSingleLine(stream.title) ?: stream.name ?: state.providerName, maxLines = 2, overflow = TextOverflow.Ellipsis)
                  // Some sources pack a whole formatted card — title, size, codec, source — into
                  // every one of these fields, so flatten them and drop the blanks rather than
                  // printing four lines of it under a two-line title.
                  listOfNotNull(streamSingleLine(stream.quality), streamSizeLabel(stream)).joinToString("  •  ").takeIf { it.isNotBlank() }?.let {
                    Text(it, color = MaterialTheme.colorScheme.onSurface.copy(alpha = 0.62f), style = MaterialTheme.typography.bodySmall)
                  }
                }
              }
            }
          }
        }
      }
    },
    confirmButton = { TextButton(onClick = onDismiss) { Text("Close") } },
  )
}

@Composable
private fun PluginProviderSettingsDialog(provider: PluginProvider, onDismiss: () -> Unit) {
  ProviderSettingsDialog(
    providerKey = provider.id,
    providerName = provider.name,
    loadSchema = { StreamDekPlugins.manager.settingsSchema(provider.id) },
    initialValues = { StreamDekPlugins.manager.providerSettings(provider.id) },
    onSave = { values -> StreamDekPlugins.manager.saveProviderSettings(provider.id, values) },
    onDismiss = onDismiss,
  )
}

/** The same dialog for a SkyStream source — its `getSettings()` answers the same field model. */
@Composable
private fun SkyProviderSettingsDialog(provider: SkyProvider, onDismiss: () -> Unit) {
  ProviderSettingsDialog(
    providerKey = provider.packageName,
    providerName = provider.name,
    loadSchema = { SkyStreamPlugins.manager.settingsSchema(provider) },
    initialValues = { SkyStreamPlugins.manager.providerSettings(provider.packageName) },
    onSave = { values -> SkyStreamPlugins.manager.saveProviderSettings(provider.packageName, values) },
    onDismiss = onDismiss,
  )
}

/**
 * Renders whatever settings a source declares at runtime.
 *
 * Both plugin systems describe their options the same way — a list of typed fields — so the
 * rendering, defaulting and saving is shared and each system only supplies how to fetch the
 * schema and where to put the answers.
 */
@Composable
private fun ProviderSettingsDialog(
  providerKey: String,
  providerName: String,
  loadSchema: suspend () -> Result<List<PluginSettingField>>,
  initialValues: () -> Map<String, Any>,
  onSave: suspend (Map<String, Any>) -> Unit,
  onDismiss: () -> Unit,
) {
  val scope = rememberCoroutineScope()
  var loading by remember(providerKey) { mutableStateOf(true) }
  var saving by remember(providerKey) { mutableStateOf(false) }
  var fields by remember(providerKey) { mutableStateOf<List<PluginSettingField>>(emptyList()) }
  var values by remember(providerKey) { mutableStateOf(initialValues()) }
  var error by remember(providerKey) { mutableStateOf<String?>(null) }

  LaunchedEffect(providerKey) {
    loadSchema()
      .onSuccess { loaded ->
        fields = loaded
        val withDefaults = values.toMutableMap()
        loaded.forEach { field -> field.key?.let { key -> if (key !in withDefaults && field.defaultValue != null) withDefaults[key] = field.defaultValue } }
        values = withDefaults
      }
      .onFailure { error = humanReadablePluginError(it) }
    loading = false
  }

  Dialog(onDismissRequest = { if (!saving) onDismiss() }) {
    Surface(shape = StreamDekRadius.panelShape, color = MaterialTheme.colorScheme.surface, border = BorderStroke(1.dp, MaterialTheme.colorScheme.onSurface.copy(alpha = 0.10f))) {
      Column(Modifier.fillMaxWidth().heightIn(max = 620.dp).verticalScroll(rememberScrollState()).padding(20.dp), verticalArrangement = Arrangement.spacedBy(14.dp)) {
        Text("Source settings", style = MaterialTheme.typography.labelMedium, color = MaterialTheme.colorScheme.onSurface.copy(alpha = 0.56f))
        Text(providerName, style = MaterialTheme.typography.titleLarge, fontWeight = FontWeight.Black)
        when {
          loading -> CircularProgressIndicator(modifier = Modifier.align(Alignment.CenterHorizontally))
          error != null -> Text(error.orEmpty(), color = MaterialTheme.colorScheme.error)
          fields.isEmpty() -> Text(
            "This source says it takes settings but did not describe any fields. Add the ones it " +
              "expects below -- the name has to match what the source reads, and its collection " +
              "or author is the only place that says what that is.",
            color = MaterialTheme.colorScheme.onSurface.copy(alpha = 0.68f),
            style = MaterialTheme.typography.bodySmall,
          )
          else -> fields.forEach { field ->
            when (field.type) {
              "header" -> Text(field.label, style = MaterialTheme.typography.titleMedium, fontWeight = FontWeight.Bold)
              "toggle" -> field.key?.let { key ->
                Row(Modifier.fillMaxWidth(), horizontalArrangement = Arrangement.spacedBy(12.dp), verticalAlignment = Alignment.CenterVertically) {
                  Column(Modifier.weight(1f)) {
                    Text(field.label, fontWeight = FontWeight.SemiBold)
                    field.description?.let { Text(it, color = MaterialTheme.colorScheme.onSurface.copy(alpha = 0.62f), style = MaterialTheme.typography.bodySmall) }
                  }
                  Switch(checked = values[key] as? Boolean ?: (field.defaultValue as? Boolean ?: false), onCheckedChange = { values = values + (key to it) })
                }
              }
              "select" -> field.key?.let { key ->
                Column(verticalArrangement = Arrangement.spacedBy(8.dp)) {
                  Text(field.label, fontWeight = FontWeight.SemiBold)
                  field.description?.let { Text(it, color = MaterialTheme.colorScheme.onSurface.copy(alpha = 0.62f), style = MaterialTheme.typography.bodySmall) }
                  androidx.compose.foundation.layout.FlowRow(horizontalArrangement = Arrangement.spacedBy(8.dp), verticalArrangement = Arrangement.spacedBy(8.dp)) {
                    field.options.forEach { option ->
                      FilterChip(selected = values[key]?.toString() == option.value, onClick = { values = values + (key to option.value) }, label = { Text(option.label) })
                    }
                  }
                }
              }
              "text" -> field.key?.let { key ->
                // A source token — a FebBox `ui=` cookie, an API key — is pasted in from somewhere
                // else and then checked by eye, so masking it hides the one thing worth looking at.
                // These show their contents, with an eye to hide them rather than to reveal them.
                var hidden by remember(providerKey, key) { mutableStateOf(false) }
                OutlinedTextField(
                  value = values[key]?.toString().orEmpty(),
                  onValueChange = { values = values + (key to it) },
                  label = { Text(field.label) },
                  placeholder = field.placeholder?.let { placeholder -> { Text(placeholder) } },
                  supportingText = field.description?.let { description -> { Text(description) } },
                  visualTransformation = if (field.isPassword && hidden) PasswordVisualTransformation() else VisualTransformation.None,
                  trailingIcon = if (!field.isPassword) null else {
                    {
                      IconButton(onClick = { hidden = !hidden }) {
                        Icon(
                          if (hidden) Icons.Rounded.Visibility else Icons.Rounded.VisibilityOff,
                          contentDescription = if (hidden) "Show value" else "Hide value",
                        )
                      }
                    }
                  },
                  singleLine = true,
                  modifier = Modifier.fillMaxWidth(),
                )
              }
            }
          }
        }
        // Anything already stored that the schema has no field for, so a value entered here or
        // arriving from another device is visible and editable rather than silently held.
        if (!loading) {
          val describedKeys = fields.mapNotNull { it.key }.toSet()
          values.keys.filterNot { it in describedKeys }.sorted().forEach { key ->
            OutlinedTextField(
              value = values[key]?.toString().orEmpty(),
              onValueChange = { values = values + (key to it) },
              label = { Text(key) },
              trailingIcon = {
                IconButton(onClick = { values = values - key }) {
                  Icon(Icons.Rounded.Delete, contentDescription = "Remove $key")
                }
              },
              singleLine = true,
              modifier = Modifier.fillMaxWidth(),
            )
          }
          // Offered when the source described nothing, and once something has been added by hand,
          // so a source needing two tokens can be given both. A source that describes its own
          // fields properly does not get an invitation to invent more.
          if (fields.isEmpty() || values.keys.any { it !in describedKeys }) {
            var newKey by remember(providerKey) { mutableStateOf("") }
            var newValue by remember(providerKey) { mutableStateOf("") }
            SettingsDivider()
            Text("Add a setting", style = MaterialTheme.typography.labelLarge, fontWeight = FontWeight.Bold)
            OutlinedTextField(
              value = newKey,
              onValueChange = { newKey = it },
              label = { Text("Name") },
              placeholder = { InputGuideText("token1") },
              singleLine = true,
              modifier = Modifier.fillMaxWidth(),
            )
            OutlinedTextField(
              value = newValue,
              onValueChange = { newValue = it },
              label = { Text("Value") },
              singleLine = true,
              modifier = Modifier.fillMaxWidth(),
            )
            TextButton(
              onClick = {
                values = values + (newKey.trim() to newValue.trim())
                newKey = ""
                newValue = ""
              },
              enabled = newKey.isNotBlank() && newValue.isNotBlank(),
              modifier = Modifier.align(Alignment.End),
            ) { Text("Add") }
          }
        }
        Row(Modifier.align(Alignment.End), horizontalArrangement = Arrangement.spacedBy(8.dp)) {
          TextButton(onClick = onDismiss, enabled = !saving) { Text("Cancel") }
          Button(onClick = {
            saving = true
            scope.launch {
              onSave(values)
              saving = false
              onDismiss()
            }
          }, enabled = !loading && error == null && !saving) { Text(if (saving) "Saving..." else "Save") }
        }
      }
    }
  }
}

/** The two kinds of source collection the Plugins page can install. */
private enum class CollectionKind(val label: String, val hint: String, val placeholder: String) {
  Plugin(
    "Plugin",
    "StreamDek's own JavaScript sources.",
    "Paste the plugin collection link",
  ),
  CloudStream(
    "CloudStream",
    "CloudStream .cs3 and SkyStream .sky extensions — the link is read to work out which. A repo.json or a mega repo that bundles several. Sources start off — turn on the ones you want.",
    "Paste the repo.json or mega repo link",
  ),
}

/**
 * One installed collection — JS plugin or CloudStream — with its sources folded away underneath.
 *
 * Both collection types get the same card so the two settings sections behave identically: the
 * header toggles the whole collection, the icon row carries the collection-level actions, and the
 * sources expand in place rather than living in a second list further down the page.
 */
@Composable
private fun CollectionCard(
  title: String,
  subtitle: String,
  enabled: Boolean,
  expanded: Boolean,
  busy: Boolean,
  onToggleEnabled: (Boolean) -> Unit,
  onToggleExpanded: () -> Unit,
  onRefresh: () -> Unit,
  onRemove: () -> Unit,
  favourite: Boolean = false,
  onToggleFavourite: (() -> Unit)? = null,
  onDetails: (() -> Unit)? = null,
  sources: @Composable ColumnScope.() -> Unit,
) {
  val lightSurface = MaterialTheme.colorScheme.surface.luminance() > 0.5f
  Column(
    modifier = Modifier
      .fillMaxWidth()
      .clip(StreamDekRadius.cardShape)
      // 4% of near-black on a white card is not a card, it is a smudge — the collections on the
      // Plugins page had no edge at all in light mode. A light surface needs both a deeper fill
      // and a drawn border to separate from the white section behind it; a dark one does not.
      .background(MaterialTheme.colorScheme.onSurface.copy(alpha = if (lightSurface) 0.055f else 0.04f))
      .border(1.dp, MaterialTheme.colorScheme.onSurface.copy(alpha = if (lightSurface) 0.10f else 0.06f), StreamDekRadius.cardShape)
      .padding(14.dp),
    verticalArrangement = Arrangement.spacedBy(6.dp),
  ) {
    Row(modifier = Modifier.fillMaxWidth(), horizontalArrangement = Arrangement.spacedBy(12.dp), verticalAlignment = Alignment.CenterVertically) {
      Column(
        modifier = Modifier.weight(1f).clip(StreamDekRadius.controlShape).clickable(onClick = onToggleExpanded).padding(vertical = 4.dp),
        verticalArrangement = Arrangement.spacedBy(2.dp),
      ) {
        Text(title, fontWeight = FontWeight.Bold, color = MaterialTheme.colorScheme.onSurface)
        Text(subtitle, color = MaterialTheme.colorScheme.onSurface.copy(alpha = 0.62f), style = MaterialTheme.typography.bodySmall)
      }
      Switch(checked = enabled, onCheckedChange = onToggleEnabled)
    }
    Row(horizontalArrangement = Arrangement.spacedBy(2.dp), verticalAlignment = Alignment.CenterVertically) {
      onToggleFavourite?.let { toggleFavourite ->
        IconButton(onClick = toggleFavourite) {
          Icon(
            if (favourite) Icons.Rounded.Star else Icons.Rounded.StarBorder,
            contentDescription = if (favourite) "Remove $title from favourites" else "Add $title to favourites",
            tint = if (favourite) Color(0xFFFACC15) else MaterialTheme.colorScheme.onSurface.copy(alpha = 0.78f),
          )
        }
      }
      onDetails?.let { details ->
        IconButton(onClick = details) { Icon(Icons.Rounded.Info, contentDescription = "$title details", tint = MaterialTheme.colorScheme.onSurface.copy(alpha = 0.78f)) }
      }
      IconButton(onClick = onRefresh, enabled = !busy) {
        Icon(Icons.Rounded.Refresh, contentDescription = "Refresh $title", tint = MaterialTheme.colorScheme.onSurface.copy(alpha = 0.78f))
      }
      IconButton(onClick = onRemove, enabled = !busy) {
        Icon(Icons.Rounded.Delete, contentDescription = "Remove $title", tint = MaterialTheme.colorScheme.onSurface.copy(alpha = 0.78f))
      }
      Spacer(modifier = Modifier.weight(1f))
      IconButton(onClick = onToggleExpanded) {
        Icon(
          if (expanded) Icons.Rounded.KeyboardArrowUp else Icons.Rounded.KeyboardArrowDown,
          contentDescription = if (expanded) "Hide $title sources" else "Show $title sources",
          tint = MaterialTheme.colorScheme.onSurface.copy(alpha = 0.78f),
        )
      }
    }
    AnimatedVisibility(visible = expanded) {
      Column(modifier = Modifier.fillMaxWidth(), verticalArrangement = Arrangement.spacedBy(2.dp), content = sources)
    }
  }
}

@Composable
private fun PluginsSettingsSummary(refreshing: Boolean, onRefresh: () -> Unit) {
  val scope = rememberCoroutineScope()
  val context = LocalContext.current
  var addKind by rememberSaveable { mutableStateOf(CollectionKind.Plugin) }
  var repositoryUrl by rememberSaveable { mutableStateOf("") }
  // Bumped after a CloudStream collection is added here so its own section re-reads the manager.
  var cloudStreamVersion by remember { mutableIntStateOf(0) }
  var pluginState by remember { mutableStateOf(StreamDekPlugins.manager.state) }
  // syncState() below covers edits made on this screen. This covers the ones that are not:
  // a portal change arriving on the next foreground, which otherwise left the page stale.
  LaunchedEffect(Unit) {
    StreamDekPlugins.manager.stateChanged.collect { pluginState = it }
  }
  var busy by remember { mutableStateOf(false) }
  var message by remember { mutableStateOf<String?>(null) }
  var expandedPluginUrl by rememberSaveable { mutableStateOf<String?>(null) }
  var detailsRepoUrl by rememberSaveable { mutableStateOf<String?>(null) }
  var displayNameVersion by remember { mutableStateOf(0) }
  var settingsProviderId by remember { mutableStateOf<String?>(null) }
  var sourceTest by remember { mutableStateOf<PluginSourceTestState?>(null) }

  fun syncState() {
    pluginState = StreamDekPlugins.manager.state
  }

  detailsRepoUrl?.let { url ->
    pluginState.repos.firstOrNull { it.url == url }?.let { repository ->
      PluginRepoDetailsDialog(
        repository = repository,
        providers = pluginState.providers.filter { it.repoUrl == url },
        onRenamed = { displayNameVersion++ },
        onDismiss = { detailsRepoUrl = null },
      )
    }
  }
  settingsProviderId?.let { id ->
    pluginState.providers.firstOrNull { it.id == id }?.let { provider ->
      PluginProviderSettingsDialog(provider = provider, onDismiss = { settingsProviderId = null })
    }
  }
  sourceTest?.let { test -> PluginSourceTestDialog(test, onDismiss = { sourceTest = null }) }

  Column(verticalArrangement = Arrangement.spacedBy(18.dp)) {
    SettingsSection("Add a Collection") {
      // One field in one place for both collection types: the chips swap what the field means
      // rather than the page carrying two near-identical add forms.
      Row(horizontalArrangement = Arrangement.spacedBy(8.dp), modifier = Modifier.padding(bottom = 12.dp)) {
        CollectionKind.entries.forEach { kind ->
          FilterChip(
            selected = addKind == kind,
            onClick = { addKind = kind; message = null },
            label = { Text(kind.label) },
          )
        }
      }
      OutlinedTextField(
        value = repositoryUrl,
        onValueChange = { repositoryUrl = it },
        modifier = Modifier.fillMaxWidth(),
        placeholder = { InputGuideText(addKind.placeholder) },
        leadingIcon = { Icon(Icons.Rounded.Link, contentDescription = null) },
        singleLine = true,
        enabled = !busy,
      )
      Text(
        addKind.hint,
        color = MaterialTheme.colorScheme.onSurface.copy(alpha = 0.62f),
        style = MaterialTheme.typography.bodySmall,
        modifier = Modifier.padding(top = 8.dp),
      )
      Button(
        onClick = {
          busy = true
          message = null
          val url = repositoryUrl
          scope.launch {
            when (addKind) {
              CollectionKind.Plugin ->
                StreamDekPlugins.manager.add(url)
                  .onSuccess {
                    repositoryUrl = ""
                    message = StreamDekPlugins.manager.consumeOperationNotice() ?: "Plugin collection added."
                  }
                  .onFailure { message = humanReadablePluginError(it) }
              CollectionKind.CloudStream -> {
                // One field serves both formats. A SkyStream repo and a CloudStream repo are
                // advertised with the identical manifest shape — only the file extension on the
                // plugin entries tells them apart — so asking the user to pick would be asking
                // them something the URL already answers. SkyStream is tried first because the
                // CloudStream reader does not check extensions and would otherwise install .sky
                // bundles it has no way to run, which is exactly how they failed before.
                SkyStreamPlugins.initialize(context.applicationContext)
                CloudStreamPlugins.initialize(context.applicationContext)
                // Both engines are offered the URL. Each takes only the entries whose extension it
                // can run, so an aggregate carrying both formats installs into both, and one
                // carrying a single format simply gets "no providers" from the other.
                val skyResult = SkyStreamPlugins.manager.addRepo(url)
                val cloudResult = CloudStreamPlugins.manager.addRepo(url)
                when {
                  skyResult.isSuccess || cloudResult.isSuccess -> {
                    repositoryUrl = ""
                    message = when {
                      skyResult.isSuccess && cloudResult.isSuccess -> "Collection added — SkyStream and CloudStream sources."
                      skyResult.isSuccess -> "SkyStream collection added."
                      else -> "CloudStream collection added."
                    }
                    cloudStreamVersion += 1
                  }
                  // Neither could use it. "These aren't .sky files" is the least informative
                  // reason, so prefer whatever the other engine said went wrong.
                  else -> {
                    val skyFailure = skyResult.exceptionOrNull()
                    val reason = if (skyFailure is NotASkyStreamRepo) cloudResult.exceptionOrNull() else skyFailure
                    message = reason?.message
                      ?: cloudResult.exceptionOrNull()?.message
                      ?: "That collection could not be added."
                  }
                }
              }
            }
            syncState()
            busy = false
          }
        },
        enabled = repositoryUrl.isNotBlank() && !busy,
        modifier = Modifier.fillMaxWidth().padding(top = 12.dp),
      ) {
        Text(if (busy) "Working..." else "Add Collection")
      }
      message?.let {
        Text(it, color = MaterialTheme.colorScheme.onSurface.copy(alpha = 0.76f), style = MaterialTheme.typography.bodySmall, modifier = Modifier.padding(top = 8.dp))
      }
    }

    SettingsSection("Plugin Collections") {
      // The master switch lives with the collections it governs rather than in a section of its
      // own — on a page that now offers two kinds of collection, "Enable Plugins" floating above
      // both was ambiguous about which it applied to.
      SettingsSwitchRow(
        "JS",
        Color(0xFFF59E0B),
        "Enable Plugins",
        "Let installed plugins add more places to find streams.",
        pluginState.enabled,
        onCheckedChange = {
          StreamDekPlugins.manager.enable(it)
          syncState()
        },
      )

      // The same control the add-ons page carries, and for the same reason: this list is one
      // document synced per profile, so a collection added or a source switched off in the web
      // portal only lands when something asks the account for it.
      Row(
        modifier = Modifier.fillMaxWidth().padding(top = 6.dp),
        verticalAlignment = Alignment.CenterVertically,
        horizontalArrangement = Arrangement.spacedBy(8.dp),
      ) {
        Text(
          "Synced with your account",
          color = MaterialTheme.colorScheme.onSurface.copy(alpha = 0.62f),
          style = MaterialTheme.typography.bodySmall,
          modifier = Modifier.weight(1f),
        )
        if (refreshing) {
          CircularProgressIndicator(modifier = Modifier.size(18.dp), strokeWidth = 2.dp)
        } else {
          IconButton(onClick = onRefresh) {
            Icon(
              Icons.Rounded.Refresh,
              contentDescription = "Refresh plugin collections",
              tint = MaterialTheme.colorScheme.onSurface.copy(alpha = 0.78f),
            )
          }
        }
      }

      if (pluginState.repos.isEmpty()) {
        Text(
          "No plugin collections added yet.",
          color = MaterialTheme.colorScheme.onSurface.copy(alpha = 0.68f),
          modifier = Modifier.padding(top = 10.dp),
        )
      }
      if (pluginState.repos.isNotEmpty()) Spacer(modifier = Modifier.height(12.dp))
      pluginState.repos.sortedWith(compareByDescending<PluginRepo> { it.favourite }.thenBy { it.name.lowercase() }).forEachIndexed { index, repository ->
        if (index > 0) Spacer(modifier = Modifier.height(10.dp))
        val repoDisplayName = remember(repository.url, repository.name, displayNameVersion) { DisplayNameOverrides.resolve("plugin:" + repository.url, repository.name) }
        val pluginSources = pluginState.providers.filter { it.repoUrl == repository.url }.sortedBy { it.name.lowercase() }
        val enabledCount = pluginSources.count { it.enabled }
        CollectionCard(
          title = repoDisplayName,
          subtitle = "$enabledCount of ${pluginSources.size} ${if (pluginSources.size == 1) "source" else "sources"} on",
          enabled = repository.enabled,
          expanded = expandedPluginUrl == repository.url,
          busy = busy,
          favourite = repository.favourite,
          onToggleFavourite = { StreamDekPlugins.manager.toggleRepoFavourite(repository.url); syncState() },
          onToggleEnabled = { enabled ->
            StreamDekPlugins.manager.enableRepo(repository.url, enabled)
            syncState()
          },
          onToggleExpanded = { expandedPluginUrl = if (expandedPluginUrl == repository.url) null else repository.url },
          onDetails = { detailsRepoUrl = repository.url },
          onRefresh = {
            busy = true
            scope.launch {
              StreamDekPlugins.manager.refresh(repository.url)
                .onSuccess { message = StreamDekPlugins.manager.consumeOperationNotice() ?: "Plugin collection updated." }
                .onFailure { message = humanReadablePluginError(it) }
              syncState()
              busy = false
            }
          },
          onRemove = { StreamDekPlugins.manager.remove(repository.url); syncState() },
        ) {
          if (pluginSources.isEmpty()) {
            Text(
              "This plugin does not provide any compatible stream sources.",
              modifier = Modifier.padding(vertical = 10.dp),
              color = MaterialTheme.colorScheme.onSurface.copy(alpha = 0.62f),
              style = MaterialTheme.typography.bodySmall,
            )
          }
          pluginSources.forEachIndexed { sourceIndex, provider ->
            if (sourceIndex > 0) SettingsDivider()
            val supportedTypes = provider.types.map { type ->
              if (type.equals("movie", true)) "Movies"
              else if (type.equals("tv", true) || type.equals("series", true)) "Series"
              else "Streams"
            }.distinct().joinToString(" / ")
            Row(
              modifier = Modifier.fillMaxWidth().padding(vertical = 8.dp),
              horizontalArrangement = Arrangement.spacedBy(8.dp),
              verticalAlignment = Alignment.CenterVertically,
            ) {
              Column(modifier = Modifier.weight(1f), verticalArrangement = Arrangement.spacedBy(2.dp)) {
                Text(provider.name, color = MaterialTheme.colorScheme.onSurface, fontWeight = FontWeight.Bold)
                Text(
                  listOfNotNull(supportedTypes.takeIf { it.isNotBlank() }, if (provider.hasSettings) "Settings available" else null).joinToString(" - "),
                  color = MaterialTheme.colorScheme.onSurface.copy(alpha = 0.62f),
                  style = MaterialTheme.typography.bodySmall,
                )
              }
              IconButton(
                onClick = {
                  val testMedia = StreamDekPlugins.manager.testMediaForProvider(provider.id)
                  sourceTest = PluginSourceTestState(provider.name, testMedia.label)
                  scope.launch {
                    StreamDekPlugins.manager.testProvider(provider.id)
                      .onSuccess { streams -> sourceTest = PluginSourceTestState(provider.name, testMedia.label, loading = false, streams = streams) }
                      .onFailure { failure -> sourceTest = PluginSourceTestState(provider.name, testMedia.label, loading = false, error = humanReadablePluginError(failure)) }
                  }
                },
                enabled = repository.enabled && provider.enabled && provider.types.any { it.equals("movie", true) || it.equals("tv", true) || it.equals("series", true) },
              ) { Icon(Icons.Rounded.PlayCircleOutline, contentDescription = "Test ${provider.name}") }
              if (provider.hasSettings) {
                IconButton(onClick = { settingsProviderId = provider.id }, enabled = repository.enabled) {
                  Icon(Icons.Rounded.Settings, contentDescription = "Configure ${provider.name}")
                }
              }
              Switch(
                checked = provider.enabled && repository.enabled,
                onCheckedChange = {
                  StreamDekPlugins.manager.enableProvider(provider.id, it)
                  syncState()
                },
                enabled = repository.enabled,
              )
            }
          }
        }
      }
    }

    CloudStreamCollectionsSection(refreshSignal = cloudStreamVersion)
    SkyStreamCollectionsSection(refreshSignal = cloudStreamVersion)
  }
}

/**
 * CloudStream (.cs3) extension collections, kept separate from StreamDek's own JS plugin
 * collections above because they are a different runtime: a `.cs3` is compiled Kotlin running
 * against the bundled `com.lagradost.cloudstream3` API rather than a JS `getStreams()` script.
 *
 * Sources default to off. A single repo can list 80+ extensions, each a separate multi-megabyte
 * download that only gets fetched when it is switched on.
 */
/**
 * Installed SkyStream collections and their sources.
 *
 * Deliberately a sibling of [CloudStreamCollectionsSection] rather than a merged list: the two
 * run on completely different engines, and keeping them apart means it is obvious which kind a
 * collection is when one of them misbehaves. No per-source test button here — the CloudStream one
 * probes a known title through a loaded provider, which has no equivalent while these plugins are
 * only wired up for streams.
 */
@Composable
private fun SkyStreamCollectionsSection(refreshSignal: Int) {
  val context = LocalContext.current
  val scope = rememberCoroutineScope()
  LaunchedEffect(Unit) { SkyStreamPlugins.initialize(context.applicationContext) }
  if (!SkyStreamPlugins.isInitialized) return
  val manager = SkyStreamPlugins.manager

  var state by remember(refreshSignal) { mutableStateOf(manager.state) }
  var busy by remember { mutableStateOf(false) }
  var message by remember { mutableStateOf<String?>(null) }
  var expandedRepoUrl by rememberSaveable { mutableStateOf<String?>(null) }
  var query by rememberSaveable { mutableStateOf("") }
  var pendingProvider by remember { mutableStateOf<String?>(null) }
  var settingsProvider by remember { mutableStateOf<SkyProvider?>(null) }

  fun syncState() { state = manager.state }

  settingsProvider?.let { provider ->
    SkyProviderSettingsDialog(provider = provider, onDismiss = { settingsProvider = null })
  }

  if (state.repos.isEmpty()) return

  Column(verticalArrangement = Arrangement.spacedBy(18.dp)) {
    SettingsSection("SkyStream Collections") {
      state.repos.sortedWith(compareByDescending<SkyRepo> { it.favourite }.thenBy { it.name.lowercase() }).forEachIndexed { index, repo ->
        if (index > 0) Spacer(modifier = Modifier.height(10.dp))
        val allSources = remember(state, repo.url) { state.providers.filter { it.repoUrl == repo.url } }
        val sources = remember(allSources, query) {
          allSources.filter { query.isBlank() || it.name.contains(query, ignoreCase = true) }.sortedBy { it.name.lowercase() }
        }
        val enabledCount = allSources.count { it.enabled }
        CollectionCard(
          title = repo.name,
          subtitle = "$enabledCount of ${allSources.size} ${if (allSources.size == 1) "source" else "sources"} on",
          enabled = repo.enabled,
          expanded = expandedRepoUrl == repo.url,
          busy = busy,
          favourite = repo.favourite,
          onToggleFavourite = { manager.toggleRepoFavourite(repo.url); syncState() },
          onToggleEnabled = { enabled -> manager.enableRepo(repo.url, enabled); syncState() },
          onToggleExpanded = { expandedRepoUrl = if (expandedRepoUrl == repo.url) null else repo.url },
          onRefresh = {
            busy = true
            scope.launch {
              manager.refreshRepo(repo.url)
                .onSuccess { message = "${repo.name} updated." }
                .onFailure { message = it.message ?: "That collection could not be refreshed." }
              syncState()
              busy = false
            }
          },
          onRemove = { manager.removeRepo(repo.url); syncState() },
        ) {
          OutlinedTextField(
            value = query,
            onValueChange = { query = it },
            modifier = Modifier.fillMaxWidth().padding(vertical = 8.dp),
            placeholder = { InputGuideText("Search sources") },
            leadingIcon = { Icon(Icons.Rounded.Search, contentDescription = null) },
            singleLine = true,
          )
          sources.forEachIndexed { sourceIndex, provider ->
            if (sourceIndex > 0) SettingsDivider()
            val key = provider.repoUrl + "|" + provider.packageName
            Row(
              modifier = Modifier.fillMaxWidth().padding(vertical = 8.dp),
              horizontalArrangement = Arrangement.spacedBy(8.dp),
              verticalAlignment = Alignment.CenterVertically,
            ) {
              Column(modifier = Modifier.weight(1f), verticalArrangement = Arrangement.spacedBy(2.dp)) {
                Text(provider.name, color = MaterialTheme.colorScheme.onSurface, fontWeight = FontWeight.Bold)
                Text(
                  listOfNotNull(
                    provider.categories.takeIf { it.isNotEmpty() }?.joinToString(" / "),
                    "v${provider.version}",
                  ).joinToString(" - "),
                  color = MaterialTheme.colorScheme.onSurface.copy(alpha = 0.62f),
                  style = MaterialTheme.typography.bodySmall,
                )
              }
              // Settings are declared at runtime, so the only way to know whether a source has
              // any is to load it and ask. The button is offered whenever the source is on, and
              // the dialog says so plainly when the plugin declares none.
              IconButton(
                onClick = { settingsProvider = provider },
                enabled = repo.enabled && provider.enabled,
              ) { Icon(Icons.Rounded.Tune, contentDescription = "${provider.name} settings") }
              if (pendingProvider == key) {
                CircularProgressIndicator(modifier = Modifier.size(20.dp), strokeWidth = 2.dp)
              } else {
                Switch(
                  checked = provider.enabled && repo.enabled,
                  enabled = repo.enabled,
                  onCheckedChange = { enabled ->
                    pendingProvider = key
                    message = null
                    scope.launch {
                      manager.setProviderEnabled(provider.repoUrl, provider.packageName, enabled)
                        .onFailure { message = it.message ?: "${provider.name} could not be turned on." }
                      syncState()
                      pendingProvider = null
                    }
                  },
                )
              }
            }
          }
        }
      }
      message?.let {
        Text(it, color = MaterialTheme.colorScheme.onSurface.copy(alpha = 0.76f), style = MaterialTheme.typography.bodySmall, modifier = Modifier.padding(top = 10.dp))
      }
    }
  }
}

@Composable
private fun CloudStreamCollectionsSection(refreshSignal: Int) {
  val context = LocalContext.current
  val scope = rememberCoroutineScope()
  LaunchedEffect(Unit) { CloudStreamPlugins.initialize(context.applicationContext) }
  if (!CloudStreamPlugins.isInitialized) return
  val manager = CloudStreamPlugins.manager

  // Adding happens in the shared form above; refreshSignal is how that reaches this list.
  var state by remember(refreshSignal) { mutableStateOf(manager.state) }
  var busy by remember { mutableStateOf(false) }
  var message by remember { mutableStateOf<String?>(null) }
  var expandedRepoUrl by rememberSaveable { mutableStateOf<String?>(null) }
  var query by rememberSaveable { mutableStateOf("") }
  var pendingProvider by remember { mutableStateOf<String?>(null) }
  var sourceTest by remember { mutableStateOf<PluginSourceTestState?>(null) }

  fun syncState() { state = manager.state }

  sourceTest?.let { test -> PluginSourceTestDialog(test, onDismiss = { sourceTest = null }) }

  Column(verticalArrangement = Arrangement.spacedBy(18.dp)) {
    SettingsSection("CloudStream Collections") {
      if (state.repos.isEmpty()) {
        Text("No CloudStream collections added yet.", color = MaterialTheme.colorScheme.onSurface.copy(alpha = 0.68f))
      }
      state.repos.sortedWith(compareByDescending<CsRepo> { it.favourite }.thenBy { it.name.lowercase() }).forEachIndexed { index, repo ->
        if (index > 0) Spacer(modifier = Modifier.height(10.dp))
        val allSources = remember(state, repo.url) { state.providers.filter { it.repoUrl == repo.url } }
        val sources = remember(allSources, query) {
          allSources.filter { query.isBlank() || it.name.contains(query, ignoreCase = true) }.sortedBy { it.name.lowercase() }
        }
        val enabledCount = allSources.count { it.enabled }
        CollectionCard(
          title = repo.name,
          subtitle = "$enabledCount of ${allSources.size} ${if (allSources.size == 1) "source" else "sources"} on",
          enabled = repo.enabled,
          expanded = expandedRepoUrl == repo.url,
          busy = busy,
          favourite = repo.favourite,
          onToggleFavourite = { manager.toggleRepoFavourite(repo.url); syncState() },
          onToggleEnabled = { enabled ->
            manager.enableRepo(repo.url, enabled)
            syncState()
            if (enabled) scope.launch { runCatching { manager.loadEnabledProviders() } }
          },
          onToggleExpanded = { expandedRepoUrl = if (expandedRepoUrl == repo.url) null else repo.url },
          onRefresh = {
            busy = true
            scope.launch {
              manager.refreshRepo(repo.url)
                .onSuccess { message = "${repo.name} updated." }
                .onFailure { message = it.message ?: "That collection could not be refreshed." }
              runCatching { manager.loadEnabledProviders() }
              syncState()
              busy = false
            }
          },
          onRemove = { manager.removeRepo(repo.url); syncState() },
        ) {
          OutlinedTextField(
            value = query,
            onValueChange = { query = it },
            modifier = Modifier.fillMaxWidth().padding(vertical = 8.dp),
            placeholder = { InputGuideText("Search sources") },
            leadingIcon = { Icon(Icons.Rounded.Search, contentDescription = null) },
            singleLine = true,
          )
          sources.forEachIndexed { sourceIndex, provider ->
            if (sourceIndex > 0) SettingsDivider()
            val key = provider.repoUrl + "|" + provider.internalName
            val testMedia = remember(key) { manager.testMediaForProvider(provider.repoUrl, provider.internalName) }
            Row(
              modifier = Modifier.fillMaxWidth().padding(vertical = 8.dp),
              horizontalArrangement = Arrangement.spacedBy(8.dp),
              verticalAlignment = Alignment.CenterVertically,
            ) {
              Column(modifier = Modifier.weight(1f), verticalArrangement = Arrangement.spacedBy(2.dp)) {
                Text(provider.name, color = MaterialTheme.colorScheme.onSurface, fontWeight = FontWeight.Bold)
                Text(
                  listOfNotNull(
                    provider.tvTypes.takeIf { it.isNotEmpty() }?.joinToString(" / "),
                    provider.language?.uppercase(),
                    "v${provider.version}",
                  ).joinToString(" - "),
                  color = MaterialTheme.colorScheme.onSurface.copy(alpha = 0.62f),
                  style = MaterialTheme.typography.bodySmall,
                )
              }
              IconButton(
                onClick = {
                  val media = testMedia ?: return@IconButton
                  sourceTest = PluginSourceTestState(provider.name, media.label)
                  scope.launch {
                    manager.testProvider(provider.repoUrl, provider.internalName)
                      .onSuccess { streams -> sourceTest = PluginSourceTestState(provider.name, media.label, loading = false, streams = streams) }
                      .onFailure { failure -> sourceTest = PluginSourceTestState(provider.name, media.label, loading = false, error = humanReadablePluginError(failure)) }
                  }
                },
                // Testing scrapes a known title through the loaded plugin, so the source has to be
                // on; live-only sources have no meaningful title to probe with.
                enabled = repo.enabled && provider.enabled && testMedia != null,
              ) { Icon(Icons.Rounded.PlayCircleOutline, contentDescription = "Test ${provider.name}") }
              if (pendingProvider == key) {
                CircularProgressIndicator(modifier = Modifier.size(20.dp), strokeWidth = 2.dp)
              } else {
                Switch(
                  checked = provider.enabled && repo.enabled,
                  enabled = repo.enabled,
                  onCheckedChange = { enabled ->
                    pendingProvider = key
                    message = null
                    scope.launch {
                      manager.setProviderEnabled(provider.repoUrl, provider.internalName, enabled)
                        .onFailure { message = it.message ?: "${provider.name} could not be turned on." }
                      syncState()
                      pendingProvider = null
                    }
                  },
                )
              }
            }
          }
        }
      }
      message?.let {
        Text(it, color = MaterialTheme.colorScheme.onSurface.copy(alpha = 0.76f), style = MaterialTheme.typography.bodySmall, modifier = Modifier.padding(top = 10.dp))
      }
    }
  }
}

@Composable
private fun PluginRepoDetailsDialog(repository: PluginRepo, providers: List<PluginProvider>, onRenamed: () -> Unit, onDismiss: () -> Unit) {
  val overrideKey = "plugin:" + repository.url
  var nameField by remember(repository.url) { mutableStateOf(DisplayNameOverrides.resolve(overrideKey, repository.name)) }
  Dialog(onDismissRequest = onDismiss) {
    Surface(shape = StreamDekRadius.panelShape, color = MaterialTheme.colorScheme.surface, border = BorderStroke(1.dp, MaterialTheme.colorScheme.onSurface.copy(alpha = 0.10f))) {
      Column(modifier = Modifier.fillMaxWidth().heightIn(max = 560.dp).verticalScroll(rememberScrollState()).padding(20.dp), verticalArrangement = Arrangement.spacedBy(14.dp)) {
        Text("Plugin collection details", style = MaterialTheme.typography.labelMedium, color = MaterialTheme.colorScheme.onSurface.copy(alpha = 0.56f))
        Text(repository.name, style = MaterialTheme.typography.titleMedium, fontWeight = FontWeight.Black)
        SettingsDivider()
        OutlinedTextField(
          value = nameField,
          onValueChange = { nameField = it },
          label = { Text("Display name") },
          singleLine = true,
          modifier = Modifier.fillMaxWidth(),
        )
        Row(horizontalArrangement = Arrangement.spacedBy(10.dp)) {
          Button(onClick = {
            DisplayNameOverrides.set(overrideKey, nameField.takeIf { it.isNotBlank() && it != repository.name })
            onRenamed()
          }, enabled = nameField.isNotBlank()) { Text("Save name") }
          if (DisplayNameOverrides.get(overrideKey) != null) {
            TextButton(onClick = {
              DisplayNameOverrides.clear(overrideKey)
              nameField = repository.name
              onRenamed()
            }) { Text("Reset to default") }
          }
        }
        SettingsDivider()

        DetailRow("Version", repository.version)
        repository.description?.takeIf { it.isNotBlank() }?.let { DetailRow("Description", it) }
        // The collection's address, which is the collection: it is what was added, what the app
        // refreshes against, and what somebody has to be given to install the same plugins
        // elsewhere. The dialog knew it all along — it keys the rename override on it — and was the
        // one place a viewer could not read it back out.
        DetailUrlRow("Address", repository.url)
        DetailRow("Status", if (repository.enabled) "On" else "Off")
        if (providers.isNotEmpty()) {
          Text("Sources (${providers.size})", style = MaterialTheme.typography.labelLarge, fontWeight = FontWeight.Bold, color = MaterialTheme.colorScheme.onSurface)
          providers.forEach { provider ->
            Text(
              "• ${provider.name} — ${provider.types.joinToString("/")}${if (!provider.enabled) " (off)" else ""}",
              style = MaterialTheme.typography.bodySmall,
              color = MaterialTheme.colorScheme.onSurface.copy(alpha = 0.70f),
            )
          }
        }
        TextButton(onClick = onDismiss, modifier = Modifier.align(Alignment.End)) { Text("Close") }
      }
    }
  }
}

private fun Int.formattedItemCount(): String = String.format("%,d", this)

@Composable
private fun M3uPlaylistsSettingsSummary(
  uiState: AppUiState,
  onAddM3uPlaylist: (String, String) -> Unit,
  onRemoveM3uPlaylist: (String) -> Unit,
  onSetM3uPlaylistEnabled: (String, Boolean) -> Unit,
  onMoveM3uPlaylist: (String, Int) -> Unit,
  onRefreshM3uPlaylists: () -> Unit,
) {
  var playlistUrl by rememberSaveable { mutableStateOf("") }
  var playlistName by rememberSaveable { mutableStateOf("") }
  var showAddField by rememberSaveable { mutableStateOf(false) }
  var addingFromSourceCount by rememberSaveable { mutableIntStateOf(-1) }
  val sources = uiState.m3uSources.sortedBy { it.position }
  LaunchedEffect(sources.size, uiState.m3uLoading, addingFromSourceCount) {
    if (!uiState.m3uLoading && addingFromSourceCount >= 0 && sources.size > addingFromSourceCount) {
      playlistUrl = ""
      playlistName = ""
      showAddField = false
      addingFromSourceCount = -1
    }
  }
  Column(verticalArrangement = Arrangement.spacedBy(14.dp)) {
    Surface(
      color = MaterialTheme.colorScheme.primary.copy(alpha = 0.08f),
      shape = StreamDekRadius.panelShape,
      border = BorderStroke(1.dp, MaterialTheme.colorScheme.primary.copy(alpha = 0.15f)),
    ) {
      Row(modifier = Modifier.fillMaxWidth().padding(16.dp), verticalAlignment = Alignment.CenterVertically, horizontalArrangement = Arrangement.spacedBy(12.dp)) {
        Box(modifier = Modifier.size(42.dp).clip(StreamDekRadius.controlShape).background(MaterialTheme.colorScheme.primary.copy(alpha = 0.14f)), contentAlignment = Alignment.Center) {
          Text("+", color = MaterialTheme.colorScheme.primary, fontSize = 24.sp, fontWeight = FontWeight.Light)
        }
        Column(modifier = Modifier.weight(1f), verticalArrangement = Arrangement.spacedBy(2.dp)) {
          Text("M3U playlists", style = MaterialTheme.typography.titleMedium, fontWeight = FontWeight.Bold)
          Text("${(uiState.m3uChannels.size + uiState.m3uVodItems.size).formattedItemCount()} items (${uiState.m3uChannels.size.formattedItemCount()} live, ${uiState.m3uVodItems.size.formattedItemCount()} VOD) from ${sources.count { it.enabled }} playlist(s)", color = MaterialTheme.colorScheme.onSurface.copy(alpha = 0.60f), style = MaterialTheme.typography.bodySmall)
        }
        IconButton(onClick = onRefreshM3uPlaylists, enabled = !uiState.m3uLoading) { Icon(Icons.Rounded.Refresh, "Refresh playlists") }
      }
    }

    if (uiState.m3uLoading || uiState.m3uStatusMessage != null || uiState.m3uErrorMessage != null) {
      Surface(
        color = MaterialTheme.colorScheme.primary.copy(alpha = 0.07f),
        shape = StreamDekRadius.cardShape,
        border = BorderStroke(1.dp, MaterialTheme.colorScheme.primary.copy(alpha = 0.14f)),
      ) {
        Column(modifier = Modifier.fillMaxWidth().padding(14.dp), verticalArrangement = Arrangement.spacedBy(8.dp)) {
          Row(verticalAlignment = Alignment.CenterVertically, horizontalArrangement = Arrangement.spacedBy(10.dp)) {
            if (uiState.m3uLoading) CircularProgressIndicator(modifier = Modifier.size(18.dp), strokeWidth = 2.dp)
            Text(
              uiState.m3uStatusMessage ?: if (uiState.m3uLoading) "Loading playlist…" else "Playlist loading finished",
              modifier = Modifier.weight(1f),
              color = MaterialTheme.colorScheme.onSurface,
              fontWeight = FontWeight.SemiBold,
            )
          }
          uiState.m3uProgress?.let { progress ->
            LinearProgressIndicator(
              progress = { progress.coerceIn(0f, 1f) },
              modifier = Modifier.fillMaxWidth().height(6.dp).clip(StreamDekRadius.pill),
              color = MaterialTheme.colorScheme.primary,
              trackColor = MaterialTheme.colorScheme.primary.copy(alpha = 0.14f),
            )
            Text("${(progress.coerceIn(0f, 1f) * 100).toInt()}%", color = MaterialTheme.colorScheme.primary, style = MaterialTheme.typography.labelMedium, fontWeight = FontWeight.Bold)
          }
          uiState.m3uErrorMessage?.let { Text(it, color = MaterialTheme.colorScheme.error, style = MaterialTheme.typography.bodySmall) }
        }
      }
    }

    AnimatedVisibility(visible = showAddField) {
      Surface(color = MaterialTheme.colorScheme.surface, shape = StreamDekRadius.cardShape, border = BorderStroke(1.dp, MaterialTheme.colorScheme.onSurface.copy(alpha = 0.08f))) {
        Column(modifier = Modifier.fillMaxWidth().padding(14.dp), verticalArrangement = Arrangement.spacedBy(10.dp)) {
          OutlinedTextField(
            value = playlistName, onValueChange = { playlistName = it }, modifier = Modifier.fillMaxWidth(),
            placeholder = { InputGuideText("Playlist name (optional)") }, singleLine = true, shape = StreamDekRadius.thumbShape,
          )
          OutlinedTextField(
            value = playlistUrl, onValueChange = { playlistUrl = it }, modifier = Modifier.fillMaxWidth(),
            placeholder = { InputGuideText("Paste an M3U or M3U8 playlist link") }, leadingIcon = { Icon(Icons.Rounded.Link, null) },
            singleLine = true, shape = StreamDekRadius.thumbShape,
          )
          Row(modifier = Modifier.fillMaxWidth(), horizontalArrangement = Arrangement.End) {
            TextButton(onClick = { showAddField = false; playlistUrl = ""; playlistName = ""; addingFromSourceCount = -1 }) { Text("Cancel") }
            Button(onClick = {
              playlistUrl.trim().takeIf { it.isNotEmpty() }?.let { addingFromSourceCount = sources.size; onAddM3uPlaylist(it, playlistName) }
            }, enabled = playlistUrl.isNotBlank() && !uiState.m3uLoading, shape = StreamDekRadius.thumbShape) {
              Text(if (uiState.m3uLoading) "Adding…" else "Add")
            }
          }
        }
      }
    }
    if (!showAddField) {
      OutlinedButton(onClick = { showAddField = true }, modifier = Modifier.fillMaxWidth().height(48.dp), shape = StreamDekRadius.thumbShape) {
        Icon(Icons.Rounded.Add, contentDescription = null)
        Spacer(Modifier.width(8.dp))
        Text("Add a playlist", fontWeight = FontWeight.SemiBold)
      }
    }

    Row(modifier = Modifier.fillMaxWidth(), horizontalArrangement = Arrangement.SpaceBetween, verticalAlignment = Alignment.CenterVertically) {
      Text("Playlists", style = MaterialTheme.typography.titleMedium, fontWeight = FontWeight.Bold)
      Text("${sources.size}", color = MaterialTheme.colorScheme.onSurface.copy(alpha = 0.48f), style = MaterialTheme.typography.labelLarge)
    }
    if (sources.isEmpty()) {
      Surface(color = MaterialTheme.colorScheme.surface, shape = StreamDekRadius.cardShape) {
        Text("No M3U playlists added yet.", modifier = Modifier.fillMaxWidth().padding(18.dp), color = MaterialTheme.colorScheme.onSurface.copy(alpha = 0.68f), textAlign = TextAlign.Center)
      }
    } else {
      sources.forEachIndexed { index, source ->
        key(source.id) {
          Surface(color = MaterialTheme.colorScheme.surface, shape = StreamDekRadius.cardShape, border = BorderStroke(1.dp, MaterialTheme.colorScheme.onSurface.copy(alpha = 0.075f))) {
            Column(modifier = Modifier.fillMaxWidth().padding(14.dp), verticalArrangement = Arrangement.spacedBy(8.dp)) {
              Row(verticalAlignment = Alignment.CenterVertically, horizontalArrangement = Arrangement.spacedBy(12.dp)) {
                Column(modifier = Modifier.weight(1f), verticalArrangement = Arrangement.spacedBy(3.dp)) {
                  Text(source.name, style = MaterialTheme.typography.titleMedium, fontWeight = FontWeight.Bold, maxLines = 1, overflow = TextOverflow.Ellipsis)
                  Text(source.url, color = MaterialTheme.colorScheme.onSurface.copy(alpha = 0.58f), style = MaterialTheme.typography.bodySmall, maxLines = 1, overflow = TextOverflow.Ellipsis)
                  val liveCount = source.liveItemCount
                  val vodCount = source.vodItemCount
                  if (liveCount != null || vodCount != null) {
                    val live = liveCount ?: 0
                    val vod = vodCount ?: 0
                    val contentType = when {
                      live > 0 && vod > 0 -> "Live + VOD"
                      vod > 0 -> "VOD"
                      else -> "Live"
                    }
                    Text(
                      "${(live + vod).formattedItemCount()} items • $contentType",
                      color = MaterialTheme.colorScheme.primary,
                      style = MaterialTheme.typography.labelMedium,
                      fontWeight = FontWeight.SemiBold,
                    )
                  }
                }
                Switch(checked = source.enabled, onCheckedChange = { onSetM3uPlaylistEnabled(source.id, it) })
              }
              Row(modifier = Modifier.fillMaxWidth(), horizontalArrangement = Arrangement.spacedBy(2.dp), verticalAlignment = Alignment.CenterVertically) {
                Spacer(Modifier.weight(1f))
                IconButton(onClick = { onMoveM3uPlaylist(source.id, -1) }, enabled = index > 0) { Icon(Icons.Rounded.KeyboardArrowUp, "Move up") }
                IconButton(onClick = { onMoveM3uPlaylist(source.id, 1) }, enabled = index < sources.size - 1) { Icon(Icons.Rounded.KeyboardArrowDown, "Move down") }
                IconButton(onClick = { onRemoveM3uPlaylist(source.id) }) { Icon(Icons.Rounded.Delete, "Remove", tint = Color(0xFFEF476F)) }
              }
            }
          }
        }
      }
    }
  }
}

/** The download's media record as a [MediaItem], so it can reuse the card action scaffold. */
private fun DownloadEntry.toMediaItem(): MediaItem = MediaItem(
  id = media.mediaId.ifBlank { id },
  type = media.mediaType,
  title = media.title,
  year = media.year,
  poster = media.poster,
  backdrop = media.backdrop,
  rating = null,
  description = "",
  titleLogo = media.titleLogo,
  resumeSeasonNumber = media.seasonNumber,
  resumeEpisodeNumber = media.episodeNumber,
)

/**
 * Long-press menu for a download, using the same ambient scaffold as the Home cards so the
 * gesture behaves the same wherever a title appears.
 */
@Composable
private fun DownloadActionsDialog(
  download: DownloadEntry,
  onPlay: () -> Unit,
  onOpenDetails: () -> Unit,
  onRemove: () -> Unit,
  onDismiss: () -> Unit,
) {
  Dialog(onDismissRequest = onDismiss, properties = DialogProperties(usePlatformDefaultWidth = false, decorFitsSystemWindows = false)) {
    CardActionsAmbientScaffold(item = download.toMediaItem(), onDismiss = onDismiss) {
      if (download.state == DownloadState.COMPLETED) {
        AmbientActionRow("Play", icon = Icons.Rounded.PlayArrow) {
          onPlay()
          onDismiss()
        }
      }
      // Downloads saved before the media record existed have no catalogue id, so there is no
      // page to open — offering it would land on an unrelated title.
      if (download.media.isResolvable) {
        AmbientActionRow("Open Details", icon = Icons.Rounded.Info) {
          onOpenDetails()
          onDismiss()
        }
      }
      AmbientActionRow("Remove Download", icon = Icons.Rounded.Delete) {
        onRemove()
        onDismiss()
      }
    }
  }
}

@Composable
private fun DownloadsSettingsSummary(
  uiState: AppUiState,
  onRefresh: () -> Unit,
  onRemove: (String) -> Unit,
  onPlay: (DownloadEntry) -> Unit,
  onOpenDetails: (DownloadEntry) -> Unit,
) {
  LaunchedEffect(Unit) {
    while (true) {
      onRefresh()
      delay(2_000)
    }
  }
  val downloads = uiState.downloads.sortedByDescending { it.startTimeMs }
  val context = LocalContext.current
  // Dismissal sticks, matching the add-on reorder hint: a one-off discovery aid, not a banner
  // to re-read on every visit.
  val hintPrefs = remember { context.getSharedPreferences(APP_SETTINGS_PREFERENCES, Context.MODE_PRIVATE) }
  var showLongPressHint by remember { mutableStateOf(!hintPrefs.getBoolean("downloads_long_press_hint_dismissed", false)) }
  var actionDownload by remember { mutableStateOf<DownloadEntry?>(null) }
  // Re-read from the live list so the menu reflects a download that finished while it was open.
  actionDownload?.let { pending ->
    downloads.firstOrNull { it.id == pending.id }?.let { download ->
      DownloadActionsDialog(
        download = download,
        onPlay = { onPlay(download) },
        onOpenDetails = { onOpenDetails(download) },
        onRemove = { onRemove(download.id) },
        onDismiss = { actionDownload = null },
      )
    } ?: run { actionDownload = null }
  }
  Column(verticalArrangement = Arrangement.spacedBy(14.dp)) {
    if (downloads.isEmpty()) {
      Surface(color = MaterialTheme.colorScheme.surface, shape = StreamDekRadius.cardShape) {
        Text("No downloads yet. Downloads started from the player's Sources list appear here.", modifier = Modifier.fillMaxWidth().padding(18.dp), color = MaterialTheme.colorScheme.onSurface.copy(alpha = 0.68f), textAlign = TextAlign.Center)
      }
    } else {
      AnimatedVisibility(visible = showLongPressHint) {
        Surface(color = MaterialTheme.colorScheme.primary.copy(alpha = 0.08f), shape = StreamDekRadius.thumbShape) {
          Row(modifier = Modifier.fillMaxWidth().padding(horizontal = 14.dp, vertical = 10.dp), verticalAlignment = Alignment.CenterVertically, horizontalArrangement = Arrangement.spacedBy(10.dp)) {
            Icon(Icons.Rounded.TouchApp, contentDescription = null, tint = MaterialTheme.colorScheme.primary, modifier = Modifier.size(18.dp))
            Text(
              "Long-press a download for more actions, or tap it to play.",
              modifier = Modifier.weight(1f),
              style = MaterialTheme.typography.bodySmall,
              color = MaterialTheme.colorScheme.onSurface.copy(alpha = 0.78f),
            )
            IconButton(
              onClick = {
                showLongPressHint = false
                hintPrefs.edit().putBoolean("downloads_long_press_hint_dismissed", true).apply()
              },
              modifier = Modifier.size(24.dp),
            ) { Icon(Icons.Rounded.Close, contentDescription = "Dismiss hint", modifier = Modifier.size(16.dp)) }
          }
        }
      }
      downloads.forEach { download ->
        key(download.id) {
          Surface(color = MaterialTheme.colorScheme.surface, shape = StreamDekRadius.cardShape, border = BorderStroke(1.dp, MaterialTheme.colorScheme.onSurface.copy(alpha = 0.075f))) {
            Column(
              modifier = Modifier
                .fillMaxWidth()
                // Same gesture as a Home card: tap plays, long-press opens the menu.
                .pointerInput(download.id, download.state) {
                  detectTapGestures(
                    onTap = { if (download.state == DownloadState.COMPLETED) onPlay(download) },
                    onLongPress = { actionDownload = download },
                  )
                }
                .padding(14.dp),
              verticalArrangement = Arrangement.spacedBy(8.dp),
            ) {
              Row(verticalAlignment = Alignment.CenterVertically, horizontalArrangement = Arrangement.spacedBy(12.dp)) {
                Column(modifier = Modifier.weight(1f), verticalArrangement = Arrangement.spacedBy(3.dp)) {
                  Text(download.title, style = MaterialTheme.typography.titleMedium, fontWeight = FontWeight.Bold, maxLines = 1, overflow = TextOverflow.Ellipsis)
                  Text(
                    when (download.state) {
                      DownloadState.COMPLETED -> "Downloaded"
                      DownloadState.FAILED -> "Failed"
                      DownloadState.REMOVING -> "Removing…"
                      DownloadState.QUEUED -> "Queued"
                      DownloadState.PAUSED -> "Paused"
                      DownloadState.DOWNLOADING -> "Downloading ${download.percentDownloaded.toInt()}%"
                    },
                    color = MaterialTheme.colorScheme.onSurface.copy(alpha = 0.60f),
                    style = MaterialTheme.typography.bodySmall,
                  )
                }
                if (download.state == DownloadState.COMPLETED) {
                  IconButton(onClick = { onPlay(download) }) { Icon(Icons.Rounded.PlayArrow, "Play download", tint = MaterialTheme.colorScheme.primary) }
                }
                IconButton(onClick = { onRemove(download.id) }) { Icon(Icons.Rounded.Delete, "Remove download", tint = Color(0xFFEF476F)) }
              }
              if (download.state == DownloadState.DOWNLOADING) {
                LinearProgressIndicator(
                  progress = { (download.percentDownloaded / 100f).coerceIn(0f, 1f) },
                  modifier = Modifier.fillMaxWidth().height(4.dp).clip(StreamDekRadius.pill),
                )
              }
            }
          }
        }
      }
    }
  }
}

@Composable
private fun AddonsSettingsSummary(uiState: AppUiState, onRefreshAddons: () -> Unit, onInstallAddon: (String) -> Unit, onToggleAddon: (InstalledAddon, Boolean) -> Unit, onToggleAddonFavourite: (InstalledAddon) -> Unit, onUninstallAddon: (String) -> Unit, onMoveAddon: (String, Int) -> Unit, dragScrollBy: suspend (Float) -> Float = { 0f }) {
  var addonUrl by rememberSaveable { mutableStateOf("") }
  var showAddField by rememberSaveable { mutableStateOf(false) }
  val addons = uiState.addons.sortedWith(compareByDescending<InstalledAddon> { it.favourite }.thenBy { it.position })
  val activeCount = addons.count { it.enabled }
  val catalogCount = addons.sumOf { supportedHomeCatalogCount(it) }
  val context = LocalContext.current
  val reorderHintPrefs = remember { context.getSharedPreferences(APP_SETTINGS_PREFERENCES, Context.MODE_PRIVATE) }
  var showReorderHint by remember { mutableStateOf(!reorderHintPrefs.getBoolean("addon_reorder_hint_dismissed", false)) }
  Column(verticalArrangement = Arrangement.spacedBy(14.dp)) {
    Surface(
      color = MaterialTheme.colorScheme.primary.copy(alpha = 0.08f),
      shape = StreamDekRadius.panelShape,
      border = BorderStroke(1.dp, MaterialTheme.colorScheme.primary.copy(alpha = 0.15f)),
    ) {
      Row(modifier = Modifier.fillMaxWidth().padding(16.dp), verticalAlignment = Alignment.CenterVertically, horizontalArrangement = Arrangement.spacedBy(12.dp)) {
        Box(modifier = Modifier.size(42.dp).clip(StreamDekRadius.controlShape).background(MaterialTheme.colorScheme.primary.copy(alpha = 0.14f)), contentAlignment = Alignment.Center) {
          Text("+", color = MaterialTheme.colorScheme.primary, fontSize = 24.sp, fontWeight = FontWeight.Light)
        }
        Column(modifier = Modifier.weight(1f), verticalArrangement = Arrangement.spacedBy(2.dp)) {
          Text("Your add-ons", style = MaterialTheme.typography.titleMedium, fontWeight = FontWeight.Bold)
          Text("$activeCount of ${addons.size} active  •  $catalogCount Home rows", color = MaterialTheme.colorScheme.onSurface.copy(alpha = 0.60f), style = MaterialTheme.typography.bodySmall)
        }
        IconButton(onClick = onRefreshAddons, enabled = !uiState.addonsLoading) { Icon(Icons.Rounded.Refresh, "Refresh add-ons") }
      }
    }

    AnimatedVisibility(visible = showAddField) {
      Surface(color = MaterialTheme.colorScheme.surface, shape = StreamDekRadius.cardShape, border = BorderStroke(1.dp, MaterialTheme.colorScheme.onSurface.copy(alpha = 0.08f))) {
        Column(modifier = Modifier.fillMaxWidth().padding(14.dp), verticalArrangement = Arrangement.spacedBy(10.dp)) {
          OutlinedTextField(
            value = addonUrl, onValueChange = { addonUrl = it }, modifier = Modifier.fillMaxWidth(),
            placeholder = { InputGuideText("Paste add-on manifest link") }, leadingIcon = { Icon(Icons.Rounded.Link, null) },
            singleLine = true, shape = StreamDekRadius.thumbShape,
          )
          Row(modifier = Modifier.fillMaxWidth(), horizontalArrangement = Arrangement.End) {
            TextButton(onClick = { showAddField = false; addonUrl = "" }) { Text("Cancel") }
            Button(onClick = {
              addonUrl.trim().takeIf { it.isNotEmpty() }?.let { onInstallAddon(it); addonUrl = ""; showAddField = false }
            }, enabled = addonUrl.isNotBlank() && !uiState.addonsLoading, shape = StreamDekRadius.thumbShape) {
              Text(if (uiState.addonsLoading) "Adding…" else "Add")
            }
          }
        }
      }
    }
    if (!showAddField) {
      OutlinedButton(onClick = { showAddField = true }, modifier = Modifier.fillMaxWidth().height(48.dp), shape = StreamDekRadius.thumbShape) {
        Icon(Icons.Rounded.Add, contentDescription = null)
        Spacer(Modifier.width(8.dp))
        Text("Add an add-on", fontWeight = FontWeight.SemiBold)
      }
    }

    Row(modifier = Modifier.fillMaxWidth(), horizontalArrangement = Arrangement.SpaceBetween, verticalAlignment = Alignment.CenterVertically) {
      Text("Installed", style = MaterialTheme.typography.titleMedium, fontWeight = FontWeight.Bold)
      Text("${addons.size}", color = MaterialTheme.colorScheme.onSurface.copy(alpha = 0.48f), style = MaterialTheme.typography.labelLarge)
    }
    if (addons.isEmpty()) {
      Surface(color = MaterialTheme.colorScheme.surface, shape = StreamDekRadius.cardShape) {
        Text("No add-ons installed yet.", modifier = Modifier.fillMaxWidth().padding(18.dp), color = MaterialTheme.colorScheme.onSurface.copy(alpha = 0.68f), textAlign = TextAlign.Center)
      }
    } else {
      AnimatedVisibility(visible = showReorderHint) {
        Surface(color = MaterialTheme.colorScheme.primary.copy(alpha = 0.08f), shape = StreamDekRadius.thumbShape) {
          Row(modifier = Modifier.fillMaxWidth().padding(horizontal = 14.dp, vertical = 10.dp), verticalAlignment = Alignment.CenterVertically, horizontalArrangement = Arrangement.spacedBy(10.dp)) {
            Icon(Icons.Rounded.DragHandle, contentDescription = null, tint = MaterialTheme.colorScheme.primary, modifier = Modifier.size(18.dp))
            Text(
              "Long-press and drag a logo to reorder your add-ons.",
              modifier = Modifier.weight(1f),
              style = MaterialTheme.typography.bodySmall,
              color = MaterialTheme.colorScheme.onSurface.copy(alpha = 0.78f),
            )
            IconButton(
              onClick = {
                showReorderHint = false
                reorderHintPrefs.edit().putBoolean("addon_reorder_hint_dismissed", true).apply()
              },
              modifier = Modifier.size(24.dp),
            ) { Icon(Icons.Rounded.Close, contentDescription = "Dismiss hint", modifier = Modifier.size(16.dp)) }
          }
        }
      }
      addons.forEach { addon ->
        val reorderGroup = addons.filter {
          it.favourite == addon.favourite && LocalAddonManager.isLocalAddonId(it.id) == LocalAddonManager.isLocalAddonId(addon.id)
        }
        val index = reorderGroup.indexOfFirst { it.id == addon.id }
        key(addon.id) {
          AddonServiceCard(addon, index, reorderGroup.size, onRefreshAddons, onToggleAddon, onToggleAddonFavourite, onUninstallAddon, onMoveAddon, dragScrollBy)
        }
      }
    }
  }
}

@Composable
private fun DebridServiceCard(providerLabel: String, account: DebridAccount, index: Int, total: Int, isActive: Boolean, onRemoveDebrid: (String) -> Unit, onSetDebridEnabled: (String, Boolean) -> Unit, onMoveDebrid: (String, Int) -> Unit) {
  Card(colors = CardDefaults.cardColors(containerColor = MaterialTheme.colorScheme.surface), shape = StreamDekRadius.panelShape, border = BorderStroke(1.dp, MaterialTheme.colorScheme.onSurface.copy(alpha = 0.13f))) {
    Column(modifier = Modifier.padding(18.dp), verticalArrangement = Arrangement.spacedBy(14.dp)) {
      Row(horizontalArrangement = Arrangement.spacedBy(14.dp), verticalAlignment = Alignment.CenterVertically) {
        Box(modifier = Modifier.size(12.dp).clip(CircleShape).background(if (account.enabled) Color(0xFF00E676) else MaterialTheme.colorScheme.onSurface.copy(alpha = 0.28f)))
        Column(modifier = Modifier.weight(1f), verticalArrangement = Arrangement.spacedBy(2.dp)) {
          Text(providerLabel, color = MaterialTheme.colorScheme.onSurface, style = MaterialTheme.typography.titleMedium, fontWeight = FontWeight.Bold)
          val resolverStatus = when {
            !account.enabled -> "Disabled"
            isActive -> "Used first"
            else -> "Backup"
          }
          val accountLabel = account.username?.let { "Signed in as $it" } ?: "Connected"
          Text("$resolverStatus | Order ${index + 1} | $accountLabel", color = MaterialTheme.colorScheme.onSurface.copy(alpha = 0.68f), style = MaterialTheme.typography.bodySmall)
        }
        Switch(
          checked = account.enabled,
          onCheckedChange = { onSetDebridEnabled(account.provider, it) },
        )
      }
      Row(horizontalArrangement = Arrangement.spacedBy(10.dp), verticalAlignment = Alignment.CenterVertically) {
        OutlinedButton(onClick = { onMoveDebrid(account.provider, -1) }, enabled = index > 0, shape = StreamDekRadius.pill) { Text("Up") }
        OutlinedButton(onClick = { onMoveDebrid(account.provider, 1) }, enabled = index < total - 1, shape = StreamDekRadius.pill) { Text("Down") }
        TextButton(onClick = { onRemoveDebrid(account.provider) }) { Text("Disconnect", color = Color(0xFFEF4444), fontWeight = FontWeight.SemiBold) }
      }
    }
  }
}

/**
 * Every premium service the backend will accept, paired with its display name, in the order the
 * chips are shown. Must stay in step with SUPPORTED_DEBRID_PROVIDERS on the backend — the id is
 * what gets posted, and the backend rejects anything not on its own list. Kept here as the single
 * source of truth so adding a provider is one edit rather than three scattered literals.
 */
private val DebridProviderOptions = listOf(
  "real-debrid" to "Real-Debrid",
  "alldebrid" to "AllDebrid",
  "premiumize" to "Premiumize",
  "torbox" to "TorBox",
  "debrid-link" to "Debrid-Link",
  "deepbrid" to "Deepbrid",
)

/** Display name for a stored provider id, falling back to the id for anything unrecognised. */
private fun debridProviderLabel(provider: String): String =
  DebridProviderOptions.firstOrNull { it.first == provider }?.second ?: provider

/**
 * The two steps of a device sign-in, kept on screen until they are done.
 *
 * Laid out as instructions rather than as a status line, because the viewer has to act on it: open
 * a page on something else, and type a code they are still reading from here. Both halves are
 * therefore doing rather than telling — the address is a button that opens it, and the code is a
 * button that copies it — since a code read off a phone screen and typed by hand is exactly where
 * this goes wrong.
 */
@Composable
private fun DebridSignInCard(prompt: DebridSignInPrompt, onDismiss: () -> Unit) {
  val context = LocalContext.current
  val clipboard = LocalClipboardManager.current
  var copied by remember(prompt.userCode) { mutableStateOf(false) }
  val finished = !prompt.waiting

  Surface(
    modifier = Modifier.fillMaxWidth(),
    color = MaterialTheme.colorScheme.surfaceVariant.copy(alpha = 0.55f),
    shape = StreamDekRadius.cardShape,
    border = BorderStroke(1.dp, MaterialTheme.colorScheme.primary.copy(alpha = 0.35f)),
  ) {
    Column(modifier = Modifier.padding(16.dp), verticalArrangement = Arrangement.spacedBy(14.dp)) {
      Text(
        "Finish signing in to ${prompt.providerLabel}",
        style = MaterialTheme.typography.titleMedium,
        fontWeight = FontWeight.Black,
        color = MaterialTheme.colorScheme.onSurface,
      )

      if (!finished) {
        Column(verticalArrangement = Arrangement.spacedBy(6.dp)) {
          Text("1. Open this page", style = MaterialTheme.typography.labelLarge, color = MaterialTheme.colorScheme.onSurface.copy(alpha = 0.72f))
          OutlinedButton(
            onClick = {
              runCatching {
                context.startActivity(
                  Intent(Intent.ACTION_VIEW, Uri.parse(prompt.verificationUrl)).addFlags(Intent.FLAG_ACTIVITY_NEW_TASK),
                )
              }
            },
            modifier = Modifier.fillMaxWidth(),
            shape = StreamDekRadius.pill,
          ) {
            Text(prompt.verificationUrl.removePrefix("https://").removePrefix("http://"), fontWeight = FontWeight.SemiBold)
          }
        }

        Column(verticalArrangement = Arrangement.spacedBy(6.dp)) {
          Text("2. Enter this code", style = MaterialTheme.typography.labelLarge, color = MaterialTheme.colorScheme.onSurface.copy(alpha = 0.72f))
          Surface(
            modifier = Modifier.fillMaxWidth(),
            color = MaterialTheme.colorScheme.surface,
            shape = StreamDekRadius.thumbShape,
          ) {
            Row(
              modifier = Modifier.fillMaxWidth().padding(horizontal = 14.dp, vertical = 12.dp),
              horizontalArrangement = Arrangement.spacedBy(10.dp),
              verticalAlignment = Alignment.CenterVertically,
            ) {
              Text(
                prompt.userCode,
                modifier = Modifier.weight(1f),
                style = MaterialTheme.typography.headlineSmall,
                fontWeight = FontWeight.Black,
                // Spaced out because this is read off a screen and typed on another device, where
                // a mistaken character costs the whole attempt.
                letterSpacing = 3.sp,
                color = MaterialTheme.colorScheme.primary,
              )
              TextButton(onClick = {
                clipboard.setText(androidx.compose.ui.text.AnnotatedString(prompt.userCode))
                copied = true
              }) {
                Text(if (copied) "Copied" else "Copy", fontWeight = FontWeight.Bold)
              }
            }
          }
        }

        Row(horizontalArrangement = Arrangement.spacedBy(10.dp), verticalAlignment = Alignment.CenterVertically) {
          CircularProgressIndicator(modifier = Modifier.size(16.dp), strokeWidth = 2.dp)
          Text(
            "Waiting for you to approve it…",
            style = MaterialTheme.typography.bodySmall,
            color = MaterialTheme.colorScheme.onSurface.copy(alpha = 0.72f),
          )
        }
      } else {
        Text(
          prompt.outcome.orEmpty(),
          style = MaterialTheme.typography.bodyMedium,
          color = MaterialTheme.colorScheme.onSurface,
        )
      }

      TextButton(onClick = onDismiss, modifier = Modifier.align(Alignment.End)) {
        Text(if (finished) "Done" else "Cancel", fontWeight = FontWeight.SemiBold)
      }
    }
  }
}

@Composable
private fun DebridSettingsSummary(uiState: AppUiState, onRefreshDebrid: () -> Unit, onAddDebrid: (String, String) -> Unit, onRemoveDebrid: (String) -> Unit, onSetDebridEnabled: (String, Boolean) -> Unit, onMoveDebrid: (String, Int) -> Unit, onSetDebridCloudSync: (Boolean) -> Unit, onPremiumizeSignIn: (() -> Unit)? = null, onRealDebridSignIn: (() -> Unit)? = null, onDismissDebridSignIn: (() -> Unit)? = null, onDismissDebridNotice: () -> Unit) {
  val providerOptions = DebridProviderOptions
  var selectedProvider by rememberSaveable { mutableStateOf(providerOptions.first().first) }
  var apiKey by rememberSaveable(selectedProvider) { mutableStateOf("") }
  /** Whether the chosen service has a sign-in of its own, making the key field redundant. */
  val signsInWithoutKey = (selectedProvider == "real-debrid" && onRealDebridSignIn != null) ||
    (selectedProvider == "premiumize" && onPremiumizeSignIn != null)
  val accounts = uiState.debridAccounts.sortedBy { it.priority }
  Column(verticalArrangement = Arrangement.spacedBy(20.dp)) {
    uiState.debridNoticeMessage?.let { message ->
      val noticeColor = if (uiState.debridNoticeIsError) MaterialTheme.colorScheme.error else MaterialTheme.colorScheme.primary
      Surface(
        modifier = Modifier.fillMaxWidth(),
        color = noticeColor.copy(alpha = 0.10f),
        shape = StreamDekRadius.cardShape,
        border = BorderStroke(1.dp, noticeColor.copy(alpha = 0.28f)),
      ) {
        Row(
          modifier = Modifier.fillMaxWidth().padding(start = 16.dp, top = 12.dp, bottom = 12.dp, end = 8.dp),
          verticalAlignment = Alignment.CenterVertically,
          horizontalArrangement = Arrangement.spacedBy(10.dp),
        ) {
          Icon(
            if (uiState.debridNoticeIsError) Icons.Rounded.Warning else Icons.Rounded.Info,
            contentDescription = null,
            tint = noticeColor,
            modifier = Modifier.size(20.dp),
          )
          Text(message, modifier = Modifier.weight(1f), color = MaterialTheme.colorScheme.onSurface, style = MaterialTheme.typography.bodyMedium)
          IconButton(onClick = onDismissDebridNotice, modifier = Modifier.size(36.dp)) {
            Icon(Icons.Rounded.Close, contentDescription = "Dismiss notification", tint = MaterialTheme.colorScheme.onSurface.copy(alpha = 0.70f), modifier = Modifier.size(18.dp))
          }
        }
      }
    }
    SettingsSection("Connect a Service") {
      Text("Service", color = MaterialTheme.colorScheme.onSurface, style = MaterialTheme.typography.titleMedium, fontWeight = FontWeight.SemiBold)
      LazyRow(horizontalArrangement = Arrangement.spacedBy(8.dp)) {
        items(providerOptions) { provider ->
          FilterChip(selected = provider.first == selectedProvider, onClick = { selectedProvider = provider.first }, label = { Text(provider.second) })
        }
      }
      if (selectedProvider == "real-debrid" && onRealDebridSignIn != null) {
        Text(
          "Real-Debrid can sign you in with a short code instead of an access key.",
          color = MaterialTheme.colorScheme.onSurface.copy(alpha = 0.68f),
          style = MaterialTheme.typography.bodySmall,
        )
        Button(onClick = onRealDebridSignIn, enabled = !uiState.debridLoading, shape = StreamDekRadius.pill) {
          Text("Sign in with Real-Debrid", fontWeight = FontWeight.SemiBold)
        }
      }
      uiState.debridSignIn?.let { prompt ->
        // Spaced by hand: SettingsSection stacks its children flush, so without this the card sits
        // hard against whatever follows it.
        Box(modifier = Modifier.padding(top = 14.dp, bottom = 4.dp)) {
          DebridSignInCard(prompt = prompt, onDismiss = onDismissDebridSignIn ?: {})
        }
      }
      if (selectedProvider == "premiumize" && onPremiumizeSignIn != null) {
        Text(
          "Premiumize can sign you in without an access key: open its secure page and approve the short pairing code.",
          color = MaterialTheme.colorScheme.onSurface.copy(alpha = 0.68f),
          style = MaterialTheme.typography.bodySmall,
        )
        Button(onClick = onPremiumizeSignIn, enabled = !uiState.debridLoading, shape = StreamDekRadius.pill) {
          Text("Sign in with Premiumize", fontWeight = FontWeight.SemiBold)
        }
      }
      // Hidden for a service that signs in instead. Offering a key field beside a sign-in button
      // asks the viewer to choose between two ways of doing the same thing, and for these two the
      // key is the worse one — there is nothing to paste unless they went and found it themselves.
      if (!signsInWithoutKey) {
        OutlinedTextField(value = apiKey, onValueChange = { apiKey = it }, modifier = Modifier.fillMaxWidth(), singleLine = true, placeholder = { InputGuideText("Access key") })
      }
      Row(horizontalArrangement = Arrangement.spacedBy(10.dp)) {
        if (!signsInWithoutKey) {
          Button(onClick = { val trimmed = apiKey.trim(); if (trimmed.isNotEmpty()) { onAddDebrid(selectedProvider, trimmed); apiKey = "" } }, enabled = apiKey.isNotBlank() && !uiState.debridLoading, shape = StreamDekRadius.pill) { Text("Connect") }
        }
        OutlinedButton(onClick = onRefreshDebrid, shape = StreamDekRadius.pill) { Text("Refresh") }
      }
    }
    SettingsSection("Where Your Keys Are Kept") {
      SettingsSwitchRow(
        "KEY",
        Color(0xFF8B5CF6),
        "Save Keys to Your StreamDek Account",
        "On: your keys are stored, encrypted, in your StreamDek account — sign in on your TV or " +
          "another phone and your services are already there, so you only enter each key once. " +
          "Off: they stay on this device alone and StreamDek keeps no copy of them, but every other " +
          "device needs its own keys entered separately. Switching off copies your keys to this " +
          "device before removing them from your account, so nothing is lost either way.",
        uiState.debridCloudSync,
        onSetDebridCloudSync,
        enabled = !uiState.debridLoading,
      )
      if (!uiState.debridCloudSync) {
        Text(
          "Kept on this device only. Your services are reached from this device directly, whichever " +
            "streaming mode your account is set to — StreamDek's servers have no key to use on your behalf.",
          color = MaterialTheme.colorScheme.onSurface.copy(alpha = 0.62f),
          style = MaterialTheme.typography.bodySmall,
        )
      }
    }
    if (accounts.isEmpty()) {
      SettingsSection("Connected Services") { Text("No premium services connected.", color = MaterialTheme.colorScheme.onSurface.copy(alpha = 0.74f), style = MaterialTheme.typography.bodyMedium) }
    } else {
      val activeProvider = accounts.firstOrNull { it.enabled }?.provider
      accounts.forEachIndexed { index, account ->
        val label = debridProviderLabel(account.provider)
        DebridServiceCard(providerLabel = label, account = account, index = index, total = accounts.size, isActive = account.provider == activeProvider, onRemoveDebrid = onRemoveDebrid, onSetDebridEnabled = onSetDebridEnabled, onMoveDebrid = onMoveDebrid)
      }
    }
  }
}

private fun openExternalUrl(context: Context, url: String) {
  runCatching { context.startActivity(Intent(Intent.ACTION_VIEW, Uri.parse(url)).addFlags(Intent.FLAG_ACTIVITY_NEW_TASK)) }
}

private fun syncServicesSubtitle(uiState: AppUiState): String {
  val connected = SyncService.values().filter { syncServiceStatus(uiState, it).connected }
  return when {
    connected.isEmpty() -> "Connect Trakt, SIMKL, or MDBList to this profile"
    connected.size == SyncService.values().size -> "All ${connected.size} services connected"
    else -> "${connected.joinToString(", ") { it.label }} connected"
  }
}

/** Width of the logo plus its gap, so content below a service row can line up with its text. */
private val SyncServiceTextInset = 40.dp

/**
 * Brand logos supplied as flat silhouettes have to be tinted to the current foreground colour or
 * they vanish against a surface of the same shade. Full-colour marks are drawn untouched.
 */
@Composable
private fun SyncServiceLogo(service: SyncService, size: Dp = 26.dp) {
  Image(
    painter = painterResource(service.logoRes),
    contentDescription = service.label,
    modifier = Modifier.size(size),
    contentScale = ContentScale.Fit,
    colorFilter = if (service.monochromeLogo) ColorFilter.tint(MaterialTheme.colorScheme.onSurface) else null,
  )
}

/** Logo + name + connection state, the row shared by the hub list and each service's own page. */
@Composable
private fun SyncServiceIdentityRow(service: SyncService, status: SyncServiceStatus, trailing: @Composable (() -> Unit)? = null) {
  Row(modifier = Modifier.fillMaxWidth().padding(vertical = 10.dp), horizontalArrangement = Arrangement.spacedBy(14.dp), verticalAlignment = Alignment.CenterVertically) {
    SyncServiceLogo(service)
    Column(modifier = Modifier.weight(1f), verticalArrangement = Arrangement.spacedBy(2.dp)) {
      Text(service.label, style = MaterialTheme.typography.titleMedium, fontWeight = FontWeight.SemiBold, color = MaterialTheme.colorScheme.onSurface)
      Text(
        if (status.connected) "Connected${status.username?.let { " as $it" } ?: ""}" else service.blurb,
        style = MaterialTheme.typography.bodySmall,
        color = if (status.connected) service.accent else MaterialTheme.colorScheme.onSurface.copy(alpha = 0.68f),
        maxLines = 3,
        overflow = TextOverflow.Ellipsis,
      )
    }
    trailing?.invoke()
  }
}

/**
 * Actions under a service's identity row. Indented to the text above rather than the logo, and
 * with no rule between them — the buttons act on the service named directly above, so a divider
 * would read as separating them from it.
 */
@Composable
private fun SyncServiceActionRow(content: @Composable RowScope.() -> Unit) {
  Row(
    modifier = Modifier.fillMaxWidth().padding(start = SyncServiceTextInset, bottom = 4.dp),
    horizontalArrangement = Arrangement.spacedBy(10.dp),
    verticalAlignment = Alignment.CenterVertically,
    content = content,
  )
}

/** Copies a pairing code and confirms it, so the user never has to transcribe it by hand. */
@Composable
private fun CopyCodeButton(code: String) {
  val clipboard = LocalClipboardManager.current
  val context = LocalContext.current
  OutlinedButton(
    onClick = {
      clipboard.setText(AnnotatedString(code))
      android.widget.Toast.makeText(context, "Code copied", android.widget.Toast.LENGTH_SHORT).show()
    },
    shape = StreamDekRadius.pill,
  ) {
    Icon(Icons.Rounded.ContentCopy, contentDescription = null, modifier = Modifier.size(17.dp))
    Spacer(modifier = Modifier.width(7.dp))
    Text("Copy code")
  }
}

/**
 * StreamDek's own sync, as a choice on this page.
 *
 * It is not a [SyncService] -- there is no account to link, no device code and no status to
 * fetch -- so its identity lives here rather than in that enum.
 */
private val SyncDekAccent = Color(0xFFA78BFA)

/** One option in "where your sync lives": SyncDek, or a tracking service. */
private data class SyncSourceOption(
  val id: String,
  val label: String,
  val accent: Color,
  val logoRes: Int,
  val monochromeLogo: Boolean,
  /** What it does for the viewer, in one line and without jargon. */
  val capability: String,
  /** Null for SyncDek, which has no account behind it. */
  val service: SyncService?,
)

/**
 * Said plainly, because this is the line someone reads before making the choice.
 *
 * All four hold a real position. MDBList was twice described here as unable to -- first as having
 * no playback API, then as having one that could not be read -- and both turned out to be wrong,
 * so this says what each actually does and nothing more.
 */
private fun syncSourceCapability(service: SyncService): String = when (service) {
  SyncService.Trakt -> "Resume positions, watchlist, ratings and watched history."
  SyncService.Simkl -> "Resume positions and watchlist."
  SyncService.Punchplay -> "Resume positions and watchlist."
  SyncService.Mdblist -> "Watchlist, plus it is sent your progress as you watch. StreamDek cannot read positions back from it yet, so pick something else if you want Continue Watching here."
}

private fun syncSourceOptions(): List<SyncSourceOption> = buildList {
  add(
    SyncSourceOption(
      id = SYNCDEK_ID,
      label = "SyncDek",
      accent = SyncDekAccent,
      logoRes = R.drawable.streamdek_logo_transparent,
      monochromeLogo = false,
      capability = "Keeps your place and your watchlist on every device. Nothing to connect.",
      service = null,
    ),
  )
  SyncService.values().forEach { service ->
    add(
      SyncSourceOption(
        id = service.id,
        label = service.label,
        accent = service.accent,
        logoRes = service.logoRes,
        monochromeLogo = service.monochromeLogo,
        capability = syncSourceCapability(service),
        service = service,
      ),
    )
  }
}

/** "2 minutes ago", for the line beside Sync now. */
private fun lastCheckedLabel(checkedAt: Long?): String {
  if (checkedAt == null) return "Not checked yet"
  val elapsed = System.currentTimeMillis() - checkedAt
  return when {
    elapsed < 60_000 -> "Checked just now"
    elapsed < 3_600_000 -> "Checked ${elapsed / 60_000} min ago"
    elapsed < 86_400_000 -> "Checked ${elapsed / 3_600_000} h ago"
    else -> "Checked ${elapsed / 86_400_000} d ago"
  }
}

/**
 * One tappable option.
 *
 * A card rather than a radio row: the choice carries a logo, a state and a sentence of
 * explanation, and a bare radio beside a name gave none of that room. The whole card is the
 * target, and a service that has not been connected says so instead of being silently inert.
 */
@Composable
private fun SyncSourceCard(
  option: SyncSourceOption,
  selected: Boolean,
  status: SyncServiceStatus,
  onSelect: () -> Unit,
  onOpen: (() -> Unit)?,
) {
  val builtIn = option.service == null
  val selectable = builtIn || status.connected
  val badge = when {
    builtIn -> "Built in"
    status.connected -> status.username?.let { "Connected as $it" } ?: "Connected"
    !status.available -> "Unavailable on this server"
    else -> "Not connected"
  }
  val badgeColor = when {
    builtIn || status.connected -> option.accent
    !status.available -> Color(0xFFF59E0B)
    else -> MaterialTheme.colorScheme.onSurface.copy(alpha = 0.55f)
  }

  Surface(
    modifier = Modifier.fillMaxWidth(),
    shape = StreamDekRadius.cardShape,
    color = if (selected) option.accent.copy(alpha = 0.12f) else MaterialTheme.colorScheme.surfaceVariant.copy(alpha = 0.35f),
    border = BorderStroke(if (selected) 1.5.dp else 1.dp, if (selected) option.accent else MaterialTheme.colorScheme.outlineVariant),
  ) {
    Column(
      modifier = Modifier
        .fillMaxWidth()
        // Tapping an unconnected service opens its page rather than doing nothing: wanting to
        // pick it is exactly the moment someone is willing to connect it.
        .clickable { if (selectable) onSelect() else onOpen?.invoke() }
        .padding(horizontal = 16.dp, vertical = 14.dp),
      verticalArrangement = Arrangement.spacedBy(8.dp),
    ) {
      Row(horizontalArrangement = Arrangement.spacedBy(14.dp), verticalAlignment = Alignment.CenterVertically) {
        Image(
          painter = painterResource(option.logoRes),
          contentDescription = null,
          modifier = Modifier.size(28.dp),
          contentScale = ContentScale.Fit,
          colorFilter = if (option.monochromeLogo) ColorFilter.tint(MaterialTheme.colorScheme.onSurface) else null,
        )
        Column(modifier = Modifier.weight(1f), verticalArrangement = Arrangement.spacedBy(2.dp)) {
          Text(
            option.label,
            style = MaterialTheme.typography.titleMedium,
            fontWeight = FontWeight.Bold,
            color = MaterialTheme.colorScheme.onSurface,
          )
          Text(badge, style = MaterialTheme.typography.labelMedium, fontWeight = FontWeight.SemiBold, color = badgeColor)
        }
        if (selected) {
          Icon(Icons.Rounded.CheckCircle, contentDescription = "In use", tint = option.accent, modifier = Modifier.size(24.dp))
        } else if (!selectable) {
          Icon(
            Icons.AutoMirrored.Rounded.KeyboardArrowRight,
            contentDescription = null,
            tint = MaterialTheme.colorScheme.onSurface.copy(alpha = 0.34f),
          )
        }
      }
      Text(
        option.capability,
        style = MaterialTheme.typography.bodySmall,
        color = MaterialTheme.colorScheme.onSurface.copy(alpha = 0.70f),
      )
      if (!selectable && status.available) {
        Text(
          "Tap to connect ${option.label} first.",
          style = MaterialTheme.typography.bodySmall,
          fontWeight = FontWeight.SemiBold,
          color = option.accent,
        )
      }
    }
  }
}

@Composable
private fun SyncServicesSettingsSummary(
  uiState: AppUiState,
  onRouteChange: (SettingsRoute) -> Unit,
  onRefreshSyncServices: () -> Unit,
  onPrimarySyncServiceChange: (String) -> Unit,
) {
  val options = remember { syncSourceOptions() }
  val activeId = uiState.primarySyncService
  val active = options.firstOrNull { it.id == activeId } ?: options.first()

  Column(verticalArrangement = Arrangement.spacedBy(24.dp)) {
    // The page opens by answering the question it exists to answer: what is doing this right now,
    // and is it up to date. Refresh used to be the last control on the page, under a heading that
    // did not mention it.
    Surface(
      modifier = Modifier.fillMaxWidth(),
      shape = StreamDekRadius.panelShape,
      color = active.accent.copy(alpha = 0.14f),
      border = BorderStroke(1.dp, active.accent.copy(alpha = 0.45f)),
    ) {
      Column(modifier = Modifier.padding(18.dp), verticalArrangement = Arrangement.spacedBy(12.dp)) {
        Text(
          "YOUR SYNC",
          style = MaterialTheme.typography.labelSmall,
          fontWeight = FontWeight.Bold,
          color = active.accent,
        )
        Row(horizontalArrangement = Arrangement.spacedBy(14.dp), verticalAlignment = Alignment.CenterVertically) {
          Image(
            painter = painterResource(active.logoRes),
            contentDescription = null,
            modifier = Modifier.size(34.dp),
            contentScale = ContentScale.Fit,
            colorFilter = if (active.monochromeLogo) ColorFilter.tint(MaterialTheme.colorScheme.onSurface) else null,
          )
          Column(modifier = Modifier.weight(1f), verticalArrangement = Arrangement.spacedBy(2.dp)) {
            Text(active.label, style = MaterialTheme.typography.headlineSmall, fontWeight = FontWeight.Bold)
            Text(
              "Keeps Continue Watching and your watchlist in step across your devices.",
              style = MaterialTheme.typography.bodySmall,
              color = MaterialTheme.colorScheme.onSurface.copy(alpha = 0.72f),
            )
          }
        }
        Row(horizontalArrangement = Arrangement.spacedBy(12.dp), verticalAlignment = Alignment.CenterVertically) {
          Button(
            onClick = onRefreshSyncServices,
            enabled = !uiState.syncSourcesRefreshing,
            shape = StreamDekRadius.pill,
          ) { Text(if (uiState.syncSourcesRefreshing) "Syncing…" else "Sync now") }
          Text(
            if (uiState.syncSourcesRefreshing) "Checking your connections…" else lastCheckedLabel(uiState.syncSourcesCheckedAt),
            style = MaterialTheme.typography.bodySmall,
            color = MaterialTheme.colorScheme.onSurface.copy(alpha = 0.60f),
          )
        }
      }
    }

    SettingsSection("Where your sync lives") {
      Text(
        "Pick one. It supplies your Continue Watching row and your watchlist. Anything else you connect keeps receiving your watchlist changes, so nothing goes quiet.",
        color = MaterialTheme.colorScheme.onSurface.copy(alpha = 0.68f),
        style = MaterialTheme.typography.bodySmall,
      )
      Column(
        modifier = Modifier.padding(top = 6.dp),
        verticalArrangement = Arrangement.spacedBy(10.dp),
      ) {
        options.forEach { option ->
          SyncSourceCard(
            option = option,
            selected = option.id == activeId,
            status = option.service?.let { syncServiceStatus(uiState, it) } ?: SyncServiceStatus(connected = true),
            onSelect = { onPrimarySyncServiceChange(option.id) },
            onOpen = option.service?.let { service -> { onRouteChange(syncServiceRoute(service)) } },
          )
        }
      }
    }

    SettingsSection("Accounts") {
      Text(
        "Connect as many as you like. Every one of them receives your watchlist changes, whichever you chose above.",
        color = MaterialTheme.colorScheme.onSurface.copy(alpha = 0.68f),
        style = MaterialTheme.typography.bodySmall,
      )
      SyncService.values().forEachIndexed { index, service ->
        if (index > 0) SettingsDivider()
        Box(modifier = Modifier.fillMaxWidth().clickable { onRouteChange(syncServiceRoute(service)) }) {
          SyncServiceIdentityRow(service, syncServiceStatus(uiState, service)) {
            Icon(Icons.AutoMirrored.Rounded.KeyboardArrowRight, contentDescription = null, tint = MaterialTheme.colorScheme.onSurface.copy(alpha = 0.34f))
          }
        }
      }
      SettingsStaticRow("PRO", Color(0xFFE5E7EB), "Kept per profile", "Each viewing profile keeps its own connections and its own watch history, so switching profiles switches whose activity is updated.")
    }
  }
}

/** Device-code connect page, used by SIMKL. Mirrors the Trakt page's flow exactly. */
@Composable
private fun DeviceCodeSyncServiceSummary(
  service: SyncService,
  uiState: AppUiState,
  onRequestSyncServiceDeviceCode: (String) -> Unit,
  onPollSyncServiceAuthorization: (String) -> Unit,
  onDisconnectSyncService: (String) -> Unit,
  onRefreshSyncServices: () -> Unit,
) {
  val context = LocalContext.current
  val status = syncServiceStatus(uiState, service)
  val busy = uiState.syncServiceLoading == service.id
  // Statuses are fetched on profile change; refresh again on entry so this page never shows a
  // stale "not connected" for a service that was connected elsewhere.
  LaunchedEffect(service.id) { onRefreshSyncServices() }
  Column(verticalArrangement = Arrangement.spacedBy(24.dp)) {
    SettingsSection("Status") {
      SyncServiceIdentityRow(service, status)
      // A server without credentials for this service can never complete a pairing. Saying so
      // beats a Connect button that looks live and quietly fails.
      if (!status.available) {
        Text(
          if (status.checked) {
            "${service.label} is not enabled on this server. The backend needs SIMKL_CLIENT_ID configured."
          } else {
            "StreamDek could not reach the ${service.label} service on this server. Make sure the backend is up to date."
          },
          modifier = Modifier.padding(start = SyncServiceTextInset, bottom = 8.dp),
          color = Color(0xFFF59E0B),
          style = MaterialTheme.typography.bodySmall,
        )
      }
      SyncServiceActionRow {
        OutlinedButton(onClick = onRefreshSyncServices, shape = StreamDekRadius.pill) { Text("Refresh") }
        if (status.connected) {
          TextButton(onClick = { onDisconnectSyncService(service.id) }) { Text("Disconnect", color = Color(0xFFEF4444), fontWeight = FontWeight.SemiBold) }
        } else {
          Button(
            onClick = { onRequestSyncServiceDeviceCode(service.id) },
            enabled = !busy && status.available,
            shape = StreamDekRadius.pill,
          ) { Text(if (busy) "Starting…" else "Connect ${service.label}") }
        }
      }
    }
    uiState.pendingSyncServiceCode?.takeIf { uiState.pendingSyncService == service.id }?.let { code ->
      SettingsSection("Device Code") {
        SettingsStaticRow("KEY", service.accent, code.userCode, code.verificationUrl)
        Text("Open the ${service.label} verification page, enter the code above, then come back here and confirm.", color = MaterialTheme.colorScheme.onSurface.copy(alpha = 0.70f), style = MaterialTheme.typography.bodySmall)
        Row(horizontalArrangement = Arrangement.spacedBy(10.dp), verticalAlignment = Alignment.CenterVertically) {
          CopyCodeButton(code.userCode)
          OutlinedButton(onClick = { openExternalUrl(context, code.verificationUrl.ifBlank { service.siteUrl }) }, shape = StreamDekRadius.pill) { Text("Open ${service.label}") }
        }
        Button(onClick = { onPollSyncServiceAuthorization(service.id) }, enabled = !busy, shape = StreamDekRadius.pill) { Text("I Connected It") }
      }
    }
    SettingsSection("What Stays Up to Date") {
      SettingsStaticRow("TV", Color(0xFFE5E7EB), "Your ${service.label} activity", "${service.blurb} This connection belongs to the profile you are using.")
    }
  }
}

/** Access-key connect page, used by MDBList. */
@Composable
private fun ApiKeySyncServiceSummary(
  service: SyncService,
  uiState: AppUiState,
  storedKey: String,
  onConnectSyncServiceApiKey: (String, String) -> Unit,
  onDisconnectSyncService: (String) -> Unit,
  onRefreshSyncServices: () -> Unit,
) {
  val context = LocalContext.current
  val status = syncServiceStatus(uiState, service)
  val busy = uiState.syncServiceLoading == service.id
  var key by rememberSaveable(storedKey) { mutableStateOf(storedKey) }
  LaunchedEffect(service.id) { onRefreshSyncServices() }
  Column(verticalArrangement = Arrangement.spacedBy(24.dp)) {
    SettingsSection("Status") {
      SyncServiceIdentityRow(service, status)
      if (!status.available && !status.checked) {
        Text(
          "StreamDek could not reach the ${service.label} service on this server. Make sure the backend is up to date.",
          modifier = Modifier.padding(start = SyncServiceTextInset, bottom = 8.dp),
          color = Color(0xFFF59E0B),
          style = MaterialTheme.typography.bodySmall,
        )
      }
      SyncServiceActionRow {
        OutlinedButton(onClick = onRefreshSyncServices, shape = StreamDekRadius.pill) { Text("Refresh") }
        if (status.connected) {
          TextButton(onClick = { onDisconnectSyncService(service.id) }) { Text("Disconnect", color = Color(0xFFEF4444), fontWeight = FontWeight.SemiBold) }
        }
      }
    }
    SettingsSection("Access Key") {
      Text("${service.label} Access Key", color = MaterialTheme.colorScheme.onSurface, style = MaterialTheme.typography.titleLarge, fontWeight = FontWeight.Black)
      Text("Get an access key from mdblist.com/preferences. The key is stored against the profile you are using.", color = MaterialTheme.colorScheme.onSurface.copy(alpha = 0.68f), style = MaterialTheme.typography.titleSmall)
      OutlinedTextField(value = key, onValueChange = { key = it }, modifier = Modifier.fillMaxWidth(), singleLine = true, placeholder = { InputGuideText("Paste access key") })
      Spacer(modifier = Modifier.height(10.dp))
      Button(
        onClick = { onConnectSyncServiceApiKey(service.id, key) },
        enabled = !busy && key.isNotBlank() && status.available,
        modifier = Modifier.fillMaxWidth().height(54.dp),
        colors = ButtonDefaults.buttonColors(containerColor = MaterialTheme.colorScheme.onSurface, contentColor = MaterialTheme.colorScheme.surface),
        shape = StreamDekRadius.pill,
      ) {
        Text(if (status.connected) "Update key" else "Connect ${service.label}", fontWeight = FontWeight.Black)
      }
      Spacer(modifier = Modifier.height(4.dp))
      TextButton(onClick = { openExternalUrl(context, service.siteUrl) }) { Text("Open ${service.label}") }
    }
  }
}

