@Composable
private fun RatingsSettingsSummary(
  uiState: AppUiState,
  onExternalRatingsEnabledChange: (Boolean) -> Unit,
  onRatingProviderEnabledChange: (String, Boolean) -> Unit,
  onRouteChange: (SettingsRoute) -> Unit,
) {
