@Composable
private fun AppUpdatesSettingsSummary(uiState: AppUiState, onAutoCheckChange: (Boolean) -> Unit, onCheckNow: () -> Unit, onStartUpdate: () -> Unit) {
  val release = uiState.availableUpdate
  Column(verticalArrangement = Arrangement.spacedBy(24.dp)) {
    SettingsSection("App Updates") {
      SettingsSwitchRow("UP", Color(0xFF22C55E), "Check Automatically", "Let StreamDek notify you when a new version is available.", uiState.autoUpdateChecksEnabled, onAutoCheckChange)
      SettingsDivider()
      SettingsNavRow(
        "DL",
        Color(0xFF38BDF8),
        "Check for Updates",
        uiState.updateErrorMessage ?: uiState.updateStatusMessage ?: "Check the StreamDek update service now.",
        value = when { uiState.updateChecking -> "Checking"; release != null -> "Available"; else -> "Current" },
        onClick = onCheckNow,
      )
      SettingsDivider()
      SettingsStaticRow("APP", Color(0xFF94A3B8), "Current Version", BuildConfig.VERSION_NAME)
    }
    if (release != null) {
      Card(colors = CardDefaults.cardColors(containerColor = MaterialTheme.colorScheme.surface), shape = StreamDekRadius.sheetShape, border = BorderStroke(1.dp, MaterialTheme.colorScheme.onSurface.copy(alpha = 0.12f))) {
        Column(modifier = Modifier.padding(24.dp), verticalArrangement = Arrangement.spacedBy(16.dp)) {
          Box(modifier = Modifier.clip(StreamDekRadius.pill).background(MaterialTheme.colorScheme.primary.copy(alpha = 0.14f)).border(1.dp, MaterialTheme.colorScheme.primary.copy(alpha = 0.38f), StreamDekRadius.pill).padding(horizontal = 14.dp, vertical = 8.dp)) {
            Text(if (release.required) "Required update" else "Update available", color = MaterialTheme.colorScheme.onSurface, fontWeight = FontWeight.Black)
          }
          Text("StreamDek ${release.versionName}", color = MaterialTheme.colorScheme.onSurface, style = MaterialTheme.typography.headlineSmall, fontWeight = FontWeight.Black)
          release.fileSizeBytes?.let { Text("Download size ${formatBytesLabel(it).removeSuffix(" used")}", color = MaterialTheme.colorScheme.onSurface.copy(alpha = 0.72f), fontWeight = FontWeight.Bold) }
          if (release.releaseNotes.isNotBlank()) {
            Text("What is new", color = MaterialTheme.colorScheme.onSurface.copy(alpha = 0.78f), fontWeight = FontWeight.Black)
            MarkdownText(release.releaseNotes)
          }
          uiState.updateProgress?.let { progress ->
            Column(verticalArrangement = Arrangement.spacedBy(8.dp)) {
              Text("${(progress.coerceIn(0f, 1f) * 100).toInt()}% downloaded", color = MaterialTheme.colorScheme.primary, fontWeight = FontWeight.Bold)
              LinearProgressIndicator(
                progress = { progress },
                modifier = Modifier.fillMaxWidth().height(8.dp).clip(StreamDekRadius.pill),
                color = MaterialTheme.colorScheme.primary,
                trackColor = MaterialTheme.colorScheme.primary.copy(alpha = 0.16f),
              )
            }
          }
          uiState.updateStatusMessage?.let { Text(it, color = MaterialTheme.colorScheme.primary) }
          uiState.updateErrorMessage?.let { Text(it, color = MaterialTheme.colorScheme.error) }
          Button(onClick = onStartUpdate, enabled = !uiState.updateDownloading, modifier = Modifier.fillMaxWidth().height(56.dp), colors = ButtonDefaults.buttonColors(containerColor = MaterialTheme.colorScheme.primary, contentColor = MaterialTheme.colorScheme.onPrimary), shape = StreamDekRadius.pill) {
            if (uiState.updateDownloading) CircularProgressIndicator(modifier = Modifier.size(22.dp), strokeWidth = 2.dp, color = MaterialTheme.colorScheme.onPrimary)
            else Text("Update Now", fontWeight = FontWeight.Black)
          }
        }
      }
    }
  }
}
@OptIn(ExperimentalMaterial3Api::class)
@Composable
private fun DetailScreen(
  uiState: AppUiState,
  onBack: () -> Unit,
  onLoadStreams: (EpisodeItem?) -> Unit,
  onDetailTabChange: (String) -> Unit,
  onPlayStream: (AddonStream, EpisodeItem?) -> Unit,
  onPlayEpisodeStream: (AddonStream, EpisodeItem?) -> Unit,
  onClearPlayerReturnTarget: () -> Unit,
  onPlayBestStream: (EpisodeItem?) -> Unit,
  onLoadSeason: (String, Int) -> Unit,
  onToggleWatchlist: (MediaItem) -> Unit,
  onToggleEpisodeWatched: (MediaDetail, EpisodeItem, Boolean) -> Unit,
  onMarkPreviousEpisodesWatched: (MediaDetail, EpisodeItem) -> Unit,
  onSetSeasonWatched: (MediaDetail, List<EpisodeItem>, Boolean) -> Unit,
  onRefreshPlaybackProgress: () -> Unit,
  onToggleFavourite: () -> Unit,
  onOpenPerson: (CastMember) -> Unit,
  onClosePerson: () -> Unit,
  onOpenRelated: (MediaItem) -> Unit,
  onDownloadStream: (AddonStream, String) -> Unit = { _, _ -> },
  isStreamDownloadEligible: (AddonStream) -> Boolean = { false },
  onTrailerMutedChange: (Boolean) -> Unit = {},
  /**
   * Sends the viewer to the add-on and plugin settings.
   *
   * Only the sources page uses it, and only when it has nothing to show: an empty results list is
   * a dead end without a way to go and fix what caused it.
   */
  onManageSources: (() -> Unit)? = null,
  /** Autoplay is on but its start delay has not elapsed yet. */
  trailerAutoplayPending: Boolean = false,
) {
  val detail = uiState.detail
  if (uiState.detailLoading || detail == null) {
    DetailSkeletonScene(style = uiState.detailPageStyle)
    return
  }
  // Live channels have no synopsis worth reading — open straight on the sources list.
  val defaultTab = when {
    uiState.detailIsLive && uiState.showStreamsList -> DetailTab.Streams.name
    detail.type == "tv" && detail.seasons.isNotEmpty() -> DetailTab.Episodes.name
    else -> DetailTab.About.name
  }
  var selectedTab by rememberSaveable(detail.id) { mutableStateOf(uiState.detailSelectedTab ?: defaultTab) }
  LaunchedEffect(detail.id) {
    val restoredTab = uiState.detailSelectedTab ?: defaultTab
    selectedTab = restoredTab
    onDetailTabChange(restoredTab)
  }
  val selectedEpisode = uiState.selectedEpisode
  var episodePageId by rememberSaveable(detail.id, "episodePage") { mutableStateOf(uiState.playerReturnEpisodeId) }
  val context = LocalContext.current
  val watchedEpisodeStore = remember(context) { WatchedEpisodeStore(context.applicationContext) }
  val watchedMovieStore = remember(context) { WatchedMovieStore(context.applicationContext) }
  val watchedOwnerKey = remember(uiState.session?.user?.uid, uiState.activeProfileId) { watchedOwnerKey(uiState.session, uiState.activeProfileId) }
  var watchedEpisodeIds by rememberSaveable(detail.id, watchedOwnerKey) { mutableStateOf(watchedEpisodeStore.load(watchedOwnerKey, detail.id)) }
  LaunchedEffect(detail.id, watchedOwnerKey, uiState.watchedEpisodeRevision) {
    watchedEpisodeIds = watchedEpisodeStore.load(watchedOwnerKey, detail.id)
  }
  LaunchedEffect(detail.id, watchedOwnerKey) {
    while (true) {
      delay(4_000L)
      onRefreshPlaybackProgress()
    }
  }
  val detailScope = rememberCoroutineScope()
  var watchedMovieIds by rememberSaveable(watchedOwnerKey) { mutableStateOf(watchedMovieStore.load(watchedOwnerKey)) }
  val movieWatched = detail.type == "movie" && detail.id in watchedMovieIds
  fun persistMovieWatched(watched: Boolean) {
    val updated = if (watched) (watchedMovieIds + detail.id).distinct() else watchedMovieIds.filterNot { it == detail.id }
    watchedMovieIds = updated
    watchedMovieStore.save(watchedOwnerKey, updated)
    if (watched) {
      val session = uiState.session
      val profileId = uiState.activeProfileId
      if (session != null && profileId != null && uiState.traktStatus.connected) {
        val apiClient = StreamDekApiClient()
        detailScope.launch { apiClient.syncWatchedMovie(session, profileId, detail) }
      }
    }
  }
  val episodePage = episodePageId?.let { id -> uiState.selectedSeasonEpisodes.firstOrNull { it.id == id } ?: selectedEpisode?.takeIf { it.id == id } }
  val watchlistItem = MediaItem(
    id = detail.id,
    type = detail.type,
    title = detail.title,
    year = detail.year,
    poster = detail.poster,
    backdrop = detail.backdrop,
    rating = detail.rating,
    description = detail.description,
  )
  val favouriteItem = uiState.detailFallbackItem?.takeIf { it.id == detail.id }?.copy(
    title = detail.title,
    poster = detail.poster ?: uiState.detailFallbackItem.poster,
    backdrop = detail.backdrop ?: uiState.detailFallbackItem.backdrop,
  ) ?: watchlistItem
  val inWatchlist = uiState.mergedWatchlist.containsMedia(watchlistItem)
  val isFavouriteChannel = uiState.favouriteChannels.hasFavouriteChannel(favouriteItem)
  val proxyStatus = if (uiState.detailIsLive) {
    uiState.availableStreams.firstOrNull()?.let { stream ->
      stream.isLikelyProxied(uiState.addons.firstOrNull { it.id == stream.addonId })
    }
  } else {
    null
  }
  val metadataLine = detail.genres
    .takeIf { it.isNotEmpty() }
    ?.take(4)
    ?.joinToString(" \u00B7 ")
    ?: listOfNotNull(
      detail.type.replaceFirstChar(Char::uppercase),
      detail.year,
      detail.runtimeMinutes?.let { "${it}m" },
      detail.seasonsCount?.takeIf { detail.type == "tv" }?.let { "$it seasons" },
    ).joinToString(" \u00B7 ")
  val backdrop = detail.backdrop ?: detail.poster
  val streamCount = uiState.availableStreams.size
  val isUnreleasedMovie = detail.type == "movie" && isFutureReleaseDate(detail.releaseDate)
  val resumeMemory = remember(detail.id, detail.type, uiState.localResumeEntries) {
    val mediaType = if (detail.type == "series") "tv" else detail.type
    uiState.localResumeEntries
      .filter { it.mediaId == detail.id && it.mediaType == mediaType && !it.isLive && it.progressPercent in 3.0..94.9 }
      .maxByOrNull { it.updatedAt }
  }
  val primaryPlayLabel = when {
    isUnreleasedMovie -> "Unreleased"
    // Resume state comes from the local store, so surface it instantly — stream
    // discovery keeps running in the background and never blocks this label.
    resumeMemory != null -> buildString {
      append("Continue")
      val seasonNumber = resumeMemory.seasonNumber
      val episodeNumber = resumeMemory.episodeNumber
      if (seasonNumber != null && episodeNumber != null) append(" S$seasonNumber-E$episodeNumber")
      resumePositionLabel(resumeMemory)?.let { append(" from $it") }
    }
    // Streams publish progressively — the button is ready as soon as the first
    // source lands, while remaining sources keep loading in the background.
    uiState.streamLoading && uiState.availableStreams.isEmpty() -> "Loading..."
    else -> "Play"
  }
  // Live channels carry no synopsis — leave it blank so the hero omits the block
  // entirely rather than showing a placeholder.
  val overview = if (uiState.detailIsLive) "" else detail.description.ifBlank { "No synopsis available." }
  var overviewExpanded by rememberSaveable(detail.id, "overview") { mutableStateOf(false) }
  var trailerPopupUrl by rememberSaveable(detail.id, "trailer") { mutableStateOf<String?>(null) }
  LaunchedEffect(episodePageId) {
    if (episodePageId != null) trailerPopupUrl = null
  }
  // Held back until the page has actually drawn its content, so the trailer's video pipeline is
  // the last thing to start rather than something the page competes with while coming up.
  //
  // The wait is measured from content being on screen, not from navigation: a bare timer started
  // at navigation can elapse while the page is still empty on a slow detail fetch, which puts the
  // trailer right back into contention with everything else. It deliberately does not wait on
  // sources — those can take many seconds, and the trailer is what makes the page feel alive.
  //
  // How long the wait is belongs to the viewer now, and to the account rather than to this device.
  // Measuring it from content still matters at every setting: at zero the trailer starts as soon as
  // there is a page, which is the earliest that is not simply competing with the page being built.
  var trailerReleased by remember(detail.id) { mutableStateOf(false) }
  LaunchedEffect(detail.id, uiState.detailLoading) {
    if (uiState.detailLoading) {
      trailerReleased = false
      return@LaunchedEffect
    }
    delay(uiState.heroTrailerDelaySeconds.coerceIn(0, MAX_TRAILER_DELAY_SECONDS) * 1_000L)
    trailerReleased = true
  }
  val listState = rememberLazyListState()
  val detailHazeState = rememberHazeState()
  LaunchedEffect(selectedTab) {
    if (selectedTab == DetailTab.Streams.name && uiState.showStreamsList) {
      delay(16)
      listState.animateScrollToItem(1)
    }
  }
  val lightMode = MaterialTheme.colorScheme.background.luminance() > 0.5f
  // Read from the artwork rather than the theme when the viewer has asked for it. Null until the
  // image has been sampled, and null forever if it cannot be — the page then simply keeps the theme
  // background, which looks deliberate where an arbitrary colour would look broken.
  val dominant = rememberDominantBackgroundColor(
    artworkUrl = backdrop,
    enabled = uiState.detailBackgroundMode == BackgroundMode.Dominant,
  )
  val pageBackground = dominant ?: MaterialTheme.colorScheme.background
  // The Streams tab's palette, worked out exactly as the episode sources page works out its own,
  // from this page's own ambient colour. Shared components take these rather than reading the
  // theme directly, which is what lets one set of controls sit correctly on either page.
  val streamsThemeForeground = MaterialTheme.colorScheme.onSurface
  val streamsForeground = when {
    contrastRatio(streamsThemeForeground, pageBackground) >= 4.5f -> streamsThemeForeground
    pageBackground.luminance() > 0.5f -> Color(0xFF101114)
    else -> Color(0xFFF5F6F8)
  }
  val streamsAccent = ambientAccentColor(pageBackground, MaterialTheme.colorScheme.primary)
  val onStreamsAccent = readableOn(streamsAccent)
  // Hoisted out of the tab's list item: the item is removed from composition the moment another
  // tab is chosen, and a filter that reset itself every time somebody glanced at Episodes is not a
  // filter. Keyed on the title so a different one starts clean.
  var streamProviderFilter by rememberSaveable(detail.id) { mutableStateOf("All") }
  // Likewise the chips' own scroll offset, so results arriving mid-search cannot pull the row back
  // to the start under the viewer's finger.
  val streamsFilterRowState = rememberLazyListState()
  // Holds everything else the tab remembers - which provider groups are open, which quality bands
  // have been expanded in full - across a trip to another tab and back.
  val streamsStateHolder = rememberSaveableStateHolder()
  val streamProviderCounts = remember(uiState.availableStreams) { streamProviderCounts(uiState.availableStreams) }
  val streamProviders = remember(streamProviderCounts) { streamProviderCounts.keys.toList() }
  LaunchedEffect(streamProviders, streamProviderFilter) {
    if (streamProviderFilter != "All" && streamProviderFilter !in streamProviders) streamProviderFilter = "All"
  }
  Box(modifier = Modifier.fillMaxSize().background(pageBackground)) {
    if (uiState.detailBackgroundMode == BackgroundMode.Cinematic) {
      AsyncImage(
        model = backdrop,
        contentDescription = null,
        modifier = Modifier
          .fillMaxSize()
          .blur(34.dp)
          .graphicsLayer { alpha = if (lightMode) 0.42f else 0.32f },
        contentScale = ContentScale.Crop,
      )
      val tint = uiState.detailAmbientTintPercent
      Box(
        modifier = Modifier.fillMaxSize().background(
          MaterialTheme.colorScheme.background.copy(alpha = ambientTintAlpha(if (lightMode) 0.46f else 0.36f, tint)),
        ),
      )
      Box(
        modifier = Modifier.fillMaxSize().background(
          Brush.verticalGradient(
            colorStops = arrayOf(
              0.00f to MaterialTheme.colorScheme.background.copy(alpha = ambientTintAlpha(if (lightMode) 0.10f else 0.11f, tint)),
              0.34f to MaterialTheme.colorScheme.background.copy(alpha = ambientTintAlpha(if (lightMode) 0.28f else 0.44f, tint)),
              0.68f to MaterialTheme.colorScheme.background.copy(alpha = ambientTintAlpha(if (lightMode) 0.58f else 0.552f, tint)),
              1.00f to MaterialTheme.colorScheme.background.copy(alpha = ambientTintAlpha(1f, tint).coerceAtLeast(0.62f)),
            ),
          ),
        ),
      )
    }

    // A landscape tablet is wide and short, which is the wrong shape for the phone's single
    // column: the artwork fills the window and the episodes are pushed off the bottom. Split in
    // two, the artwork, title and actions stay on the left where they can be seen and used at
    // any time, and the episodes, sources and cast scroll independently beside them — so
    // choosing an episode no longer means scrolling the poster away first.
    //
    // An episode page takes over the whole screen, so it opts out.
    val twoPaneDetail = LocalWindowSize.current.supportsTwoPanes && episodePage == null
    val detailHeroPane: @Composable () -> Unit = {
        DetailHero(
          detail = detail,
          backdrop = backdrop,
          pageBackground = dominant,
          metadataLine = metadataLine,
          style = uiState.detailPageStyle,
          scrollOffset = { if (listState.firstVisibleItemIndex == 0) listState.firstVisibleItemScrollOffset else 0 },
          autoPlayTrailer = uiState.heroTrailerAutoplay && trailerReleased && episodePage == null && !uiState.detailIsLive,
          trailerResolution = uiState.heroTrailerResolution,
          trailerMuted = uiState.heroTrailerMuted,
          onTrailerMutedChange = onTrailerMutedChange,
          // Same condition as autoPlayTrailer above, minus the delay having elapsed.
          trailerAutoplayPending = uiState.heroTrailerAutoplay && !trailerReleased && episodePage == null && !uiState.detailIsLive,
          hazeState = detailHazeState,
          streamCount = streamCount,
          streamLoading = uiState.streamLoading,
          selectedTab = selectedTab,
          showEpisodes = detail.type == "tv" && !uiState.detailIsLive,
          inWatchlist = inWatchlist,
          showMediaActions = !uiState.detailIsLive,
          showFavouriteAction = uiState.detailIsLive,
          isFavourite = isFavouriteChannel,
          proxyStatus = proxyStatus,
          externalRatingsEnabled = uiState.externalRatingsEnabled,
          enabledRatingProviders = uiState.enabledRatingProviders,
          overview = overview,
          overviewExpanded = overviewExpanded,
          onOverviewExpandedChange = { overviewExpanded = it },
          showStreamsList = uiState.showStreamsList && !isUnreleasedMovie,
          primaryPlayLabel = primaryPlayLabel,
          showWatchedAction = detail.type == "movie" && !uiState.detailIsLive,
          watched = movieWatched,
          onPlay = { onPlayBestStream(selectedEpisode) },
          onTrailer = { if (!detail.trailerUrl.isNullOrBlank()) trailerPopupUrl = detail.trailerUrl },
          onAbout = { selectedTab = DetailTab.About.name; onDetailTabChange(DetailTab.About.name) },
          onStreams = {
            if (uiState.showStreamsList && (detail.type != "tv" || uiState.detailIsLive)) {
              selectedTab = DetailTab.Streams.name
              onDetailTabChange(DetailTab.Streams.name)
            }
          },
          onEpisodes = { selectedTab = DetailTab.Episodes.name; onDetailTabChange(DetailTab.Episodes.name) },
          onSave = { onToggleWatchlist(watchlistItem) },
          onToggleFavourite = onToggleFavourite,
          onToggleWatched = { persistMovieWatched(!movieWatched) },
        )
    }
    val detailSections: androidx.compose.foundation.lazy.LazyListScope.() -> Unit = {
      when (selectedTab) {
        DetailTab.About.name -> {
          if (!uiState.detailIsLive) {
            item { DetailFactsSection(detail = detail) }
          }
          item { DetailCastSection(cast = detail.cast, onOpenPerson = onOpenPerson) }
          item { DetailAvailableOnSection(detail = detail) }
          if (!uiState.detailIsLive) {
            item { DetailTraktCommentSection(detail = detail, uiState = uiState) }
          }
          item { DetailMoreLikeThisSection(items = detail.similarTitles, onOpen = onOpenRelated) }
        }
        DetailTab.Episodes.name -> {
          if (detail.type == "tv" && detail.seasons.isNotEmpty()) {
            item {
              Column(modifier = Modifier.fillMaxWidth(), verticalArrangement = Arrangement.spacedBy(14.dp)) {
                Row(modifier = Modifier.padding(horizontal = 24.dp), verticalAlignment = Alignment.CenterVertically, horizontalArrangement = Arrangement.spacedBy(12.dp)) {
                  Text("Episodes", style = MaterialTheme.typography.headlineMedium, fontWeight = FontWeight.Black, color = MaterialTheme.colorScheme.onBackground, modifier = Modifier.weight(1f))
                  val selectedSeasonIds = uiState.selectedSeasonEpisodes.map { watchedEpisodeKey(detail.id, it.seasonNumber, it.episodeNumber) }
                  val fullSeasonWatched = selectedSeasonIds.isNotEmpty() && selectedSeasonIds.all { it in watchedEpisodeIds }
                  OutlinedButton(
                    onClick = {
                      onSetSeasonWatched(detail, uiState.selectedSeasonEpisodes, !fullSeasonWatched)
                    },
                    enabled = selectedSeasonIds.isNotEmpty(),
                    shape = StreamDekRadius.pill,
                    border = BorderStroke(1.dp, if (fullSeasonWatched) Color(0xFF22C55E) else MaterialTheme.colorScheme.onBackground.copy(alpha = 0.34f)),
                    contentPadding = PaddingValues(horizontal = 12.dp, vertical = 8.dp),
                  ) {
                    Icon(Icons.Rounded.CheckCircle, contentDescription = null, tint = if (fullSeasonWatched) Color(0xFF22C55E) else MaterialTheme.colorScheme.onBackground.copy(alpha = 0.76f), modifier = Modifier.size(16.dp))
                    Spacer(modifier = Modifier.width(6.dp))
                    Text(if (fullSeasonWatched) "Mark Season as Unwatched" else "Mark Season as Watched", fontWeight = FontWeight.Bold)
                  }
                }
                SeasonSelector(
                  seasons = detail.seasons,
                  selectedSeasonNumber = uiState.selectedSeasonNumber,
                  style = uiState.seasonTabStyle,
                  fallbackPoster = detail.poster ?: detail.backdrop,
                  onSelect = { season -> onLoadSeason(detail.id, season.seasonNumber) },
                )
                if (uiState.seasonLoading) {
                  SeasonSelectorSkeleton(style = uiState.seasonTabStyle)
                } else {
                  SeasonEpisodeStrip(
                    detailId = detail.id,
                    seasonNumber = uiState.selectedSeasonNumber,
                    episodes = uiState.selectedSeasonEpisodes,
                    watchedEpisodeIds = watchedEpisodeIds,
                    progressRecords = uiState.playbackProgressRecords,
                    selectedEpisodeId = selectedEpisode?.id,
                    blurUnwatched = uiState.blurUnwatchedEpisodes,
                    foreground = streamsForeground,
                    accent = streamsAccent,
                    onAccent = onStreamsAccent,
                    onToggleWatched = { episode ->
                      onToggleEpisodeWatched(detail, episode, watchedEpisodeKey(detail.id, episode.seasonNumber, episode.episodeNumber) in watchedEpisodeIds)
                    },
                    onOpen = { episode ->
                      if (uiState.showStreamsList) {
                        episodePageId = episode.id
                        onLoadStreams(episode)
                      } else {
                        onPlayBestStream(episode)
                      }
                    },
                  )
                }
              }
            }
          }
        }
        DetailTab.Streams.name -> {
          if (uiState.showStreamsList) {
            item(key = "sources-anchor") { Spacer(modifier = Modifier.height(1.dp)) }
            item(key = "sources-content") {
              // Everything the tab remembers survives a trip to another tab and back. Without this
              // the item is discarded on every tab change and the viewer returns to a list whose
              // groups have all snapped shut again.
              streamsStateHolder.SaveableStateProvider("streams-tab-${detail.id}") {
                val searching = uiState.streamLoading
                val failedSources = uiState.failedStreamSources
                Column(modifier = Modifier.fillMaxWidth(), verticalArrangement = Arrangement.spacedBy(12.dp)) {
                  Row(
                    modifier = Modifier.fillMaxWidth().padding(horizontal = 24.dp),
                    verticalAlignment = Alignment.CenterVertically,
                    horizontalArrangement = Arrangement.spacedBy(12.dp),
                  ) {
                    Text("Sources", style = MaterialTheme.typography.headlineSmall, fontWeight = FontWeight.Black, color = streamsForeground, modifier = Modifier.weight(1f))
                    StreamsRefreshControl(
                      loading = searching,
                      foreground = streamsForeground,
                      accent = streamsAccent,
                      onClick = { onLoadStreams(selectedEpisode) },
                    )
                  }
                  // The same chips as the episode sources page, inline rather than in a pinned
                  // band: this tab lives inside the title page's own scroll, and pinning a bar
                  // over it would change how that page scrolls.
                  if (streamProviders.isNotEmpty()) {
                    StreamSourceFilterRow(
                      providers = streamProviders,
                      providerCounts = streamProviderCounts,
                      totalCount = uiState.availableStreams.size,
                      selectedProvider = streamProviderFilter,
                      onProviderSelected = { streamProviderFilter = it },
                      filterRowState = streamsFilterRowState,
                      foreground = streamsForeground,
                      accent = streamsAccent,
                      onAccent = onStreamsAccent,
                      horizontalPadding = 24.dp,
                    )
                  }
                  if (searching || failedSources.isNotEmpty()) {
                    StreamSearchStatusRow(
                      modifier = Modifier.fillMaxWidth().height(SourceToolbarStatusHeight),
                      searching = searching,
                      refreshing = searching && uiState.streamRefreshing,
                      searchedSources = (uiState.totalStreamSources - uiState.pendingStreamSources).coerceAtLeast(0),
                      totalSources = uiState.totalStreamSources,
                      pendingSources = uiState.searchingStreamSources,
                      failedSources = failedSources,
                      foreground = streamsForeground,
                      accent = streamsAccent,
                      reducedMotion = LocalReducedMotion.current,
                      onRetry = { onLoadStreams(selectedEpisode) },
                      horizontalPadding = 24.dp,
                    )
                  }
                  StreamsSectionBody(
                    uiState = uiState,
                    selectedEpisode = selectedEpisode,
                    subjectLabel = selectedEpisode
                      ?.let { "S${it.seasonNumber}E${it.episodeNumber} of ${detail.title}" }
                      ?: detail.title,
                    downloadTitle = detail.title,
                    providerFilter = streamProviderFilter,
                    onProviderFilterChange = { streamProviderFilter = it },
                    providerCounts = streamProviderCounts,
                    searching = searching,
                    foreground = streamsForeground,
                    accent = streamsAccent,
                    onAccent = onStreamsAccent,
                    horizontalPadding = 24.dp,
                    onReload = { onLoadStreams(selectedEpisode) },
                    onManageSources = onManageSources,
                    onPlayStream = { stream -> if (!uiState.playerLaunching) onPlayStream(stream, selectedEpisode) },
                    onDownloadStream = onDownloadStream,
                    isStreamDownloadEligible = isStreamDownloadEligible,
                  )
                }
              }
            }
          }
        }
      }
    }

    if (twoPaneDetail) {
      Row(modifier = Modifier.fillMaxSize()) {
        // The hero keeps the larger share: it carries the artwork and the play button.
        Box(
          modifier = Modifier
            .weight(0.46f)
            .fillMaxHeight()
            .verticalScroll(rememberScrollState())
            // Clears the floating navigation, which otherwise sits over the play button and the
            // tab row at the foot of this pane.
            .padding(bottom = 132.dp),
        ) { detailHeroPane() }
        LazyColumn(
          state = listState,
          modifier = Modifier.weight(0.54f).fillMaxHeight(),
          contentPadding = PaddingValues(top = 26.dp, bottom = 132.dp),
          verticalArrangement = Arrangement.spacedBy(26.dp),
          content = detailSections,
        )
      }
    } else {
      LazyColumn(
        state = listState,
        modifier = Modifier.fillMaxSize(),
        contentPadding = PaddingValues(bottom = 132.dp),
        verticalArrangement = Arrangement.spacedBy(26.dp),
      ) {
        item { detailHeroPane() }
        detailSections()
      }
    }

    GlassCircleButton(
      modifier = Modifier.align(Alignment.TopStart).statusBarsPadding().padding(start = 26.dp, top = 18.dp),
      hazeState = detailHazeState,
      navigationHazeStyle = true,
      onClick = onBack,
    ) {
      Icon(Icons.AutoMirrored.Rounded.ArrowBack, contentDescription = "Back", tint = Color.White)
    }

    if (uiState.personLoading) {
      Box(modifier = Modifier.fillMaxSize().background(Color.Black.copy(alpha = 0.38f)), contentAlignment = Alignment.Center) {
        CircularProgressIndicator(color = Color.White)
      }
    }
    uiState.selectedPerson?.let { person ->
      PersonDetailDialog(
        person = person,
        onDismiss = onClosePerson,
        onOpenWork = { item ->
          onClosePerson()
          onOpenRelated(item)
        },
      )
    }
    trailerPopupUrl?.let { url ->
      TrailerDialog(
        title = detail.title,
        url = url,
        backdropUrl = detail.backdrop ?: detail.poster,
        maxHeight = uiState.heroTrailerResolution,
        alternateUrls = detail.trailerCandidateUrls(),
        preferredUrl = rememberKinocheckTrailerUrl(detail),
        onDismiss = { trailerPopupUrl = null },
        onOpenExternal = { openTrailer(context, url) },
      )
    }
    episodePage?.let { episode ->
      val watchedKey = watchedEpisodeKey(detail.id, episode.seasonNumber, episode.episodeNumber)
      EpisodeStreamsPage(
        detail = detail,
        episode = episode,
        uiState = uiState,
        watched = watchedKey in watchedEpisodeIds,
        onBack = {
          episodePageId = null
          onClearPlayerReturnTarget()
        },
        onReload = { onLoadStreams(episode) },
        onToggleWatched = {
          onToggleEpisodeWatched(detail, episode, watchedKey in watchedEpisodeIds)
        },
        onMarkPreviousWatched = { onMarkPreviousEpisodesWatched(detail, episode) },
        onPlayStream = onPlayEpisodeStream,
        onDownloadStream = onDownloadStream,
        isStreamDownloadEligible = isStreamDownloadEligible,
        onManageSources = onManageSources,
      )
    }
  }

}
private fun openTrailer(context: Context, trailerUrl: String?) {
  if (trailerUrl.isNullOrBlank()) return
  runCatching {
    context.startActivity(Intent(Intent.ACTION_VIEW, Uri.parse(trailerUrl)).addFlags(Intent.FLAG_ACTIVITY_NEW_TASK))
  }
}

private fun isDirectTrailerUrl(url: String): Boolean {
  val lower = url.lowercase()
  return lower.endsWith(".mp4") || lower.endsWith(".m3u8") || lower.endsWith(".webm") || lower.contains("/trailers/")
}

private fun youtubeTrailerKey(url: String): String? {
  val uri = runCatching { Uri.parse(url) }.getOrNull() ?: return null
  val host = uri.host.orEmpty().lowercase()
  val segments = uri.pathSegments
  return when {
    "youtu.be" in host -> uri.lastPathSegment
    "youtube.com" in host -> when {
      uri.getQueryParameter("v") != null -> uri.getQueryParameter("v")
      segments.firstOrNull().equals("embed", ignoreCase = true) -> segments.getOrNull(1)
      segments.firstOrNull().equals("shorts", ignoreCase = true) -> segments.getOrNull(1)
      else -> segments.lastOrNull()
    }
    else -> null
  }?.substringBefore('?')?.substringBefore('&')?.ifBlank { null }
}

/**
 * The title's other videos, for the resolver to choose between.
 *
 * The metadata service returns these newest first, which puts the promotional run — theatre stings,
 * ticket spots, social cutdowns — ahead of the trailer itself, so the first entry is routinely a
 * fifteen-second notice rather than the trailer. Handing over the whole list lets the resolver
 * pick on running time instead of on position.
 */
private fun MediaDetail.trailerCandidateUrls(): List<String> =
  trailerKeys.mapNotNull { key -> key.trim().takeIf { it.isNotEmpty() }?.let { "https://www.youtube.com/watch?v=$it" } }

/**
 * KinoCheck's trailer for this title, once it has answered.
 *
 * Null until then and null if they do not carry it, and the trailer path treats null as "use the
 * metadata service's list" — so the lookup never delays or blocks playback. It is a composable
 * rather than a call at each site because three screens raise trailers and they should all ask the
 * same question.
 */
@Composable
private fun rememberKinocheckTrailerUrl(detail: MediaDetail): String? {
  val context = LocalContext.current
  val resetToken = TrailerResetSignal.current()
  val key by produceState<String?>(null, detail.id, detail.type, resetToken) {
    value = kinocheckTrailerKey(detail.id, detail.type, context)
  }
  return key?.let { "https://www.youtube.com/watch?v=$it" }
}

private fun vimeoTrailerKey(url: String): String? {
  val uri = runCatching { Uri.parse(url) }.getOrNull() ?: return null
  val host = uri.host.orEmpty().lowercase()
  if (!host.contains("vimeo.com")) return null
  return uri.pathSegments.lastOrNull()?.ifBlank { null }
}

private fun trailerEmbedUrl(url: String, autoPlay: Boolean, muted: Boolean): String {
  val autoplayFlag = if (autoPlay) 1 else 0
  val muteFlag = if (muted) 1 else 0
  youtubeTrailerKey(url)?.let { key ->
    return "https://www.youtube.com/embed/$key?autoplay=$autoplayFlag&mute=$muteFlag&playsinline=1&controls=0&disablekb=1&fs=0&iv_load_policy=3&rel=0&modestbranding=1&enablejsapi=1&origin=https%3A%2F%2Fstreamdek.com"
  }
  vimeoTrailerKey(url)?.let { key ->
    return "https://player.vimeo.com/video/$key?autoplay=$autoplayFlag&muted=$muteFlag&title=0&byline=0&portrait=0"
  }
  return url
}

private fun trailerEmbedHtml(url: String, autoPlay: Boolean, muted: Boolean): String {
  val youtubeKey = youtubeTrailerKey(url)
  if (youtubeKey != null) {
    val autoplayFlag = if (autoPlay) 1 else 0
    val muteFlag = if (muted) 1 else 0
    return """
      <!doctype html>
      <html>
        <head>
          <meta name="viewport" content="width=device-width, initial-scale=1, maximum-scale=1, user-scalable=no" />
          <style>
            html, body, #player, iframe {
              position: fixed !important;
              inset: 0 !important;
              width: 100vw !important;
              height: 100vh !important;
              margin: 0 !important;
              padding: 0 !important;
              border: 0 !important;
              overflow: hidden !important;
              background: #000 !important;
              pointer-events: none !important;
            }
          </style>
        </head>
        <body>
          <div id="player"></div>
          <script>
            let streamdekState = 'LOADING';
            let streamdekPlayer = null;
            function onYouTubeIframeAPIReady() {
              streamdekPlayer = new YT.Player('player', {
                videoId: '$youtubeKey',
                playerVars: {
                  autoplay: $autoplayFlag,
                  controls: 0,
                  disablekb: 1,
                  fs: 0,
                  iv_load_policy: 3,
                  rel: 0,
                  playsinline: 1,
                  modestbranding: 1,
                  origin: 'https://www.youtube.com'
                },
                events: {
                  onReady: function(event) {
                    if ($muteFlag === 1) event.target.mute(); else event.target.unMute();
                    if ($autoplayFlag === 1) event.target.playVideo();
                    streamdekState = 'READY';
                  },
                  onStateChange: function(event) {
                    if (event.data === YT.PlayerState.ENDED) streamdekState = 'ENDED';
                    else if (event.data === YT.PlayerState.PLAYING || event.data === YT.PlayerState.BUFFERING) streamdekState = 'READY';
                  },
                  onError: function() { streamdekState = 'ERROR'; }
                }
              });
            }
            window.streamdekPlayback = function() {
              if (streamdekState === 'READY' && streamdekPlayer) {
                return 'READY:' + (streamdekPlayer.getPlayerState() !== YT.PlayerState.PLAYING) + ':' + (streamdekPlayer.getCurrentTime() || 0);
              }
              return streamdekState;
            };
          </script>
          <script src="https://www.youtube.com/iframe_api"></script>
        </body>
      </html>
    """.trimIndent()
  }
  val embedUrl = trailerEmbedUrl(url, autoPlay = autoPlay, muted = muted)
  return """
    <html><head><meta name="viewport" content="width=device-width, initial-scale=1" />
    <style>html,body,iframe{position:fixed;inset:0;width:100vw;height:100vh;margin:0;border:0;overflow:hidden;background:#000}</style></head>
    <body><iframe src="$embedUrl" allow="autoplay; encrypted-media; picture-in-picture" referrerpolicy="origin"></iframe></body></html>
  """.trimIndent()
}
@Composable
private fun TrailerDialog(title: String, url: String, backdropUrl: String?, maxHeight: Int = 720, alternateUrls: List<String> = emptyList(), preferredUrl: String? = null, onDismiss: () -> Unit, onOpenExternal: () -> Unit) {
  var trailerReady by remember(url) { mutableStateOf(false) }
  var trailerFailed by remember(url) { mutableStateOf(false) }
  Dialog(
    onDismissRequest = onDismiss,
    properties = DialogProperties(usePlatformDefaultWidth = false),
  ) {
    Surface(
      modifier = Modifier.fillMaxWidth(0.94f),
      color = Color(0xFF050505),
      shape = StreamDekRadius.panelShape,
      border = BorderStroke(1.dp, Color.White.copy(alpha = 0.14f)),
    ) {
      Column(verticalArrangement = Arrangement.spacedBy(12.dp), modifier = Modifier.padding(14.dp)) {
        Row(modifier = Modifier.fillMaxWidth(), horizontalArrangement = Arrangement.spacedBy(10.dp), verticalAlignment = Alignment.CenterVertically) {
          Text(title, color = Color.White, fontWeight = FontWeight.Black, style = MaterialTheme.typography.titleMedium, modifier = Modifier.weight(1f), maxLines = 1, overflow = TextOverflow.Ellipsis)
          TextButton(onClick = onOpenExternal) { Text("Open") }
          TextButton(onClick = onDismiss) { Text("Close") }
        }
        Box(modifier = Modifier.fillMaxWidth().aspectRatio(16f / 9f).background(Color.Black)) {
          if (!backdropUrl.isNullOrBlank()) {
            AsyncImage(
              model = backdropUrl,
              contentDescription = null,
              modifier = Modifier.fillMaxSize(),
              contentScale = ContentScale.Crop,
            )
          }
          TrailerPlaybackView(
            url = url,
            modifier = Modifier.fillMaxSize(),
            autoPlay = true,
            muted = false,
            maxHeight = maxHeight,
            preferWebEmbed = false,
            alternateUrls = alternateUrls,
            preferredUrl = preferredUrl,
            onReadyChanged = { ready -> trailerReady = ready; if (ready) trailerFailed = false },
            onLoadFailed = { trailerFailed = true },
            onEnded = onDismiss,
          )
          if (!trailerReady && !trailerFailed) {
            Box(modifier = Modifier.fillMaxSize(), contentAlignment = Alignment.Center) { CircularProgressIndicator(color = Color.White) }
          }
          if (trailerFailed) {
            Column(
              modifier = Modifier.align(Alignment.Center).padding(horizontal = 24.dp),
              horizontalAlignment = Alignment.CenterHorizontally,
              verticalArrangement = Arrangement.spacedBy(10.dp),
            ) {
              Text("Trailer could not be loaded.", color = Color.White, style = MaterialTheme.typography.titleSmall, fontWeight = FontWeight.Bold, textAlign = androidx.compose.ui.text.style.TextAlign.Center)
              OutlinedButton(onClick = onOpenExternal, shape = StreamDekRadius.pill) { Text("Open Externally") }
            }
          }
        }
      }
    }
  }
}

@Composable
private fun TrailerPlaybackView(
  url: String,
  modifier: Modifier = Modifier,
  autoPlay: Boolean = true,
  muted: Boolean = true,
  maxHeight: Int = 720,
  preferWebEmbed: Boolean = false,
  alternateUrls: List<String> = emptyList(),
  /** KinoCheck's pick, tried ahead of the metadata service's list. See [resolveTrailerPlaybackSource]. */
  preferredUrl: String? = null,
  onReadyChanged: (Boolean) -> Unit = {},
  onLoadFailed: () -> Unit = {},
  onEnded: () -> Unit = {},
) {
  val isYoutubeTrailer = youtubeTrailerKey(url) != null
  val isVimeoTrailer = vimeoTrailerKey(url) != null
  val context = LocalContext.current
  // Keyed into everything below, so clearing trailer state re-resolves the trailer already on screen
  // rather than waiting for the app to be restarted.
  val trailerResetToken = TrailerResetSignal.current()
  var nativeRetryKey by rememberSaveable(url, trailerResetToken) { mutableIntStateOf(0) }
  var resolution by remember(url, maxHeight, trailerResetToken) { mutableStateOf<TrailerPlaybackResolution?>(null) }
  var resolved by remember(url, maxHeight, trailerResetToken) { mutableStateOf(false) }

  if (!isYoutubeTrailer && isVimeoTrailer && preferWebEmbed) {
    LaunchedEffect(url, autoPlay, muted) { onReadyChanged(false) }
    TrailerWebView(
      url = url,
      modifier = modifier,
      autoPlay = autoPlay,
      muted = muted,
      onReadyChanged = onReadyChanged,
      onLoginRequired = {},
      onLoadFailed = onLoadFailed,
      onEnded = onEnded,
      controlledEmbed = false,
    )
    return
  }

  var nativePlaybackFailed by remember(url, maxHeight, nativeRetryKey) { mutableStateOf(false) }
  // googlevideo hands out short-lived, effectively single-use playback links, so one that was fine
  // when it was resolved can be refused a moment later. Re-resolving costs a single request and
  // produces a fresh link, which is nearly always the whole fix — worth one automatic attempt
  // before giving up on native playback and dropping to the iframe embed.
  var freshSourceAttempted by rememberSaveable(url, maxHeight) { mutableStateOf(false) }

  // Keyed on the preferred URL as well, so a trailer already showing from the metadata service's
  // list is replaced once KinoCheck answers with the real one.
  LaunchedEffect(url, maxHeight, nativeRetryKey, preferredUrl) {
    onReadyChanged(false)
    resolved = false
    // Deliberately never the viewer's cookies.
    //
    // These were read out of the WebView the iframe fallback runs in — cookies this app creates
    // itself by playing one trailer through the embed. Today they reach nothing: the resolver only
    // attaches them for the WEB and TVHTML5 clients, and neither is in the client list any more. But
    // that is the whole danger. TVHTML5 used to be in that list, and when one of these cookies
    // existed it was tried ahead of IOS, answered `status=OK`, and handed back a URL that 403'd the
    // moment the player fetched it — so one visit to the embed silently broke every trailer after
    // it, and the client that would have worked was never reached.
    //
    // Nothing here needs a signed-in identity: both clients in use are anonymous by design. Passing
    // null means putting a client back in that list cannot re-arm that trap by accident.
    val youtubeCookies: String? = null
    resolution = resolveTrailerPlaybackSource(url, maxHeight, youtubeCookies, alternateUrls, preferredUrl)
    resolved = true
  }

  val source = resolution?.source
  // When native extraction fails (YouTube regularly changes its internal API and
  // bot-checks even signed-in requests), fall back to the official iframe embed —
  // it keeps playing no matter what happens to the extraction path. A video the player API
  // reported as needing sign-in lands here too: the embed plays age-gated and bot-walled
  // trailers the API refused, and it is the reason nothing is asked of the viewer.
  val useYoutubeWebFallback = isYoutubeTrailer && resolved && (nativePlaybackFailed || source == null)
  if (useYoutubeWebFallback) {
    // KinoCheck's pick, when there is one, rather than the metadata service's first entry.
    //
    // The embed was handed `url` — the head of a list that is roughly newest first, which around a
    // release is a wall of ticket adverts. So every time extraction was refused the fallback played
    // a promo sting, and the one video actually marked as the trailer was never seen. The embed is
    // the path that survives the bot wall, which makes it exactly the path that most needs to be
    // pointed at the right video.
    val embedUrl = preferredUrl?.trim()?.takeIf { youtubeTrailerKey(it) != null } ?: url
    TrailerWebView(
      url = embedUrl,
      modifier = modifier,
      autoPlay = autoPlay,
      muted = muted,
      onReadyChanged = onReadyChanged,
      // Treated as an ordinary failure. YouTube reports its "confirm you're not a bot" wall
      // through the same signal as a genuine age gate, and that wall is about a proof-of-origin
      // token rather than about who is asking — so a sign-in prompt could not answer it, and the
      // one that used to open here simply reappeared on every trailer.
      onLoginRequired = onLoadFailed,
      onLoadFailed = onLoadFailed,
      onEnded = onEnded,
      controlledEmbed = true,
    )
    return
  }
  if (source == null) {
    if (resolved && !isYoutubeTrailer) {
      LaunchedEffect(url, nativeRetryKey) { onLoadFailed() }
    }
    Box(modifier = modifier)
    return
  }
  Media3TextureTrailerPlayer(
    url = source.url,
    modifier = modifier,
    playWhenReady = autoPlay,
    muted = muted,
    audioUrl = source.audioUrl,
    requestHeaders = source.requestHeaders,
    maxHeight = source.height ?: maxHeight,
    startPositionMs = source.startPositionMs,
    endTrimMs = source.endTrimMs,
    onReady = { onReadyChanged(true) },
    onError = {
      onReadyChanged(false)
      when {
        isYoutubeTrailer && !freshSourceAttempted -> {
          freshSourceAttempted = true
          nativeRetryKey += 1
        }
        isYoutubeTrailer -> nativePlaybackFailed = true
        else -> onLoadFailed()
      }
    },
    onEnded = onEnded,
  )
}

private val trailerViewportScript = """
  (function() {
    document.documentElement.style.setProperty('background', '#000', 'important');
    if (document.body) document.body.style.setProperty('background', '#000', 'important');
    let style = document.getElementById('streamdek-trailer-style');
    if (!style) {
      style = document.createElement('style');
      style.id = 'streamdek-trailer-style';
      style.textContent = `
        html, body, #player, #movie_player, .html5-video-player, .html5-video-container {
          position: fixed !important;
          inset: 0 !important;
          width: 100vw !important;
          height: 100vh !important;
          margin: 0 !important;
          padding: 0 !important;
          overflow: hidden !important;
          background: #000 !important;
        }
        video.html5-main-video {
          position: absolute !important;
          inset: 0 !important;
          width: 100% !important;
          height: 100% !important;
          object-fit: cover !important;
          transform: none !important;
        }
        .ytp-chrome-top, .ytp-chrome-bottom, .ytp-gradient-top, .ytp-gradient-bottom,
        .ytp-title, .ytp-watermark, .ytp-pause-overlay, .ytp-cued-thumbnail-overlay,
        .ytp-ce-element, .ytp-endscreen-content, .ytp-show-cards-title, .ytp-cards-button,
        .ytp-player-content, .ytp-spinner, .ytp-bezel {
          display: none !important;
          opacity: 0 !important;
          pointer-events: none !important;
        }
      `;
      (document.head || document.documentElement).appendChild(style);
    }
    return true;
  })();
""".trimIndent()

@Composable
private fun TrailerWebView(
  url: String,
  modifier: Modifier = Modifier,
  autoPlay: Boolean,
  muted: Boolean,
  onReadyChanged: (Boolean) -> Unit,
  onLoginRequired: () -> Unit,
  onLoadFailed: () -> Unit,
  onEnded: () -> Unit,
  controlledEmbed: Boolean,
) {
  val latestReadyChanged = rememberUpdatedState(onReadyChanged)
  val latestLoginRequired = rememberUpdatedState(onLoginRequired)
  val latestLoadFailed = rememberUpdatedState(onLoadFailed)
  val latestEnded = rememberUpdatedState(onEnded)
  // Rebuilt from scratch when trailer state is cleared. Clearing cookies and site storage does not
  // reach a WebView that is already alive — it keeps the session it was refused under, which is why
  // a clear used to need an app restart before trailers came back. `key` disposes this one and
  // constructs a new one, and the old instance is destroyed by AndroidView's onRelease.
  key(TrailerResetSignal.current()) {
  AndroidView(
    modifier = modifier.background(Color.Transparent),
    factory = { context ->
      WebView(context).apply {
        setBackgroundColor(android.graphics.Color.BLACK)
        setLayerType(android.view.View.LAYER_TYPE_HARDWARE, null)
        isVerticalScrollBarEnabled = false
        isHorizontalScrollBarEnabled = false
        isClickable = false
        isFocusable = false
        setOnTouchListener { _, _ -> true }
        webChromeClient = WebChromeClient()
        webViewClient = object : WebViewClient() {
          private fun inspectPlayback(view: WebView, loadingAttempt: Int) {
            if (!controlledEmbed) view.evaluateJavascript(trailerViewportScript, null)
            val playbackProbe = if (controlledEmbed) {
              "(function(){return window.streamdekPlayback ? window.streamdekPlayback() : 'LOADING';})()"
            } else {
              "(function(){const t=((document.body&&document.body.innerText)||'').toLowerCase();if(t.includes('sign in to confirm')||t.includes('not a bot')||t.includes('login required'))return 'LOGIN_REQUIRED';const v=document.querySelector('video');if(v&&v.ended)return 'ENDED';if(v&&v.readyState>=2)return 'READY:'+v.paused+':'+v.currentTime;if(t.includes('video unavailable')||t.includes('an error occurred'))return 'ERROR';return 'LOADING';})()"
            }
            view.evaluateJavascript(playbackProbe) { state ->
              android.util.Log.d("TrailerWebView", "playback=$state attempt=$loadingAttempt")
              when {
                state.contains("LOGIN_REQUIRED") -> latestLoginRequired.value()
                state.contains("ENDED") -> latestEnded.value()
                state.contains("READY:") -> {
                  latestReadyChanged.value(true)
                  view.postDelayed({ inspectPlayback(view, 0) }, 1_000)
                }
                state.contains("ERROR") -> latestLoadFailed.value()
                loadingAttempt < 15 -> view.postDelayed({ inspectPlayback(view, loadingAttempt + 1) }, 1_000)
                controlledEmbed && youtubeTrailerKey(url) != null -> latestLoginRequired.value()
                else -> latestLoadFailed.value()
              }
            }
          }

          override fun onPageFinished(view: WebView, pageUrl: String?) {
            super.onPageFinished(view, pageUrl)
            android.util.Log.d("TrailerWebView", "loaded url=$pageUrl title=${view.title}")
            if (!controlledEmbed) view.evaluateJavascript(trailerViewportScript, null)
            view.postDelayed({ inspectPlayback(view, 0) }, 500)
          }

          override fun onReceivedError(view: WebView, request: android.webkit.WebResourceRequest, error: android.webkit.WebResourceError) {
            super.onReceivedError(view, request, error)
            if (request.isForMainFrame) {
              android.util.Log.w("TrailerWebView", "main-frame error=${error.errorCode} ${error.description}")
              latestLoadFailed.value()
            }
          }
        }
        settings.javaScriptEnabled = true
        settings.userAgentString = WebSettings.getDefaultUserAgent(context)
        settings.domStorageEnabled = true
        settings.mediaPlaybackRequiresUserGesture = !autoPlay
        settings.cacheMode = WebSettings.LOAD_DEFAULT
        settings.loadsImagesAutomatically = true
        settings.useWideViewPort = false
        settings.loadWithOverviewMode = false
        val cookieManager = android.webkit.CookieManager.getInstance()
        cookieManager.setAcceptCookie(true)
        cookieManager.setAcceptThirdPartyCookies(this, true)
        val embedUrl = trailerEmbedUrl(url, autoPlay = autoPlay, muted = muted)
        tag = "${if (controlledEmbed) "controlled" else "direct"}:$embedUrl"
        if (controlledEmbed) {
          loadDataWithBaseURL("https://www.youtube.com/", trailerEmbedHtml(url, autoPlay, muted), "text/html", "UTF-8", null)
        } else {
          loadUrl(embedUrl, mapOf("Referer" to "https://streamdek.com/"))
        }
      }
    },
    update = { webView ->
      webView.settings.mediaPlaybackRequiresUserGesture = !autoPlay
      val embedUrl = trailerEmbedUrl(url, autoPlay = autoPlay, muted = muted)
      val pageKey = "${if (controlledEmbed) "controlled" else "direct"}:$embedUrl"
      if (webView.tag != pageKey) {
        webView.tag = pageKey
        if (controlledEmbed) {
          webView.loadDataWithBaseURL("https://www.youtube.com/", trailerEmbedHtml(url, autoPlay, muted), "text/html", "UTF-8", null)
        } else {
          webView.loadUrl(embedUrl, mapOf("Referer" to "https://streamdek.com/"))
        }
      }
    },
    onRelease = { webView ->
      webView.stopLoading()
      webView.loadUrl("about:blank")
      webView.destroy()
    },
  )
  }
}
@androidx.annotation.OptIn(UnstableApi::class)
@Composable
private fun Media3TextureTrailerPlayer(
  url: String,
  modifier: Modifier = Modifier,
  playWhenReady: Boolean,
  muted: Boolean,
  audioUrl: String?,
  requestHeaders: Map<String, String>,
  maxHeight: Int,
  /** Where to begin, for sources that carry a lead-in worth skipping. */
  startPositionMs: Long = 0L,
  /** Stop this far short of the end. See TrailerPlaybackSource.endTrimMs. */
  endTrimMs: Long = 0L,
  onReady: () -> Unit,
  onError: () -> Unit,
  onEnded: () -> Unit,
) {
  val context = LocalContext.current
  val lifecycleOwner = LocalLifecycleOwner.current
  val latestOnReady = rememberUpdatedState(onReady)
  val latestOnError = rememberUpdatedState(onError)
  val latestOnEnded = rememberUpdatedState(onEnded)
  var attachedContainer by remember(url) { mutableStateOf<TrailerTextureContainer?>(null) }

  val player = remember(url, audioUrl, requestHeaders, maxHeight) {
    val trackSelector = DefaultTrackSelector(context).apply {
      parameters = buildUponParameters()
        .setMaxVideoSize(Int.MAX_VALUE, maxHeight.coerceAtLeast(360))
        .build()
    }
    val loadControl = DefaultLoadControl.Builder()
      .setBufferDurationsMs(12_000, 45_000, 1_500, 4_000)
      .setPrioritizeTimeOverSizeThresholds(true)
      .build()
    // googlevideo refuses an open-ended byte request on these URLs, which is what a progressive
    // source issues by default — see ChunkedGoogleVideoDataSource.
    val dataSourceFactory = trailerDataSourceFactory(context, requestHeaders)
    ExoPlayer.Builder(context).setTrackSelector(trackSelector).setLoadControl(loadControl).build().apply {
      val factory = ProgressiveMediaSource.Factory(dataSourceFactory)
      // YouTube HLS manifests come from manifest.googlevideo.com without a .m3u8
      // extension, so detect HLS explicitly — a progressive source cannot parse them.
      val looksLikeHls = url.contains(".m3u8", ignoreCase = true) ||
        url.contains("/hls_", ignoreCase = true) ||
        url.contains("api/manifest/hls", ignoreCase = true)
      when {
        !audioUrl.isNullOrBlank() -> setMediaSource(
          MergingMediaSource(
            factory.createMediaSource(ExoMediaItem.fromUri(url)),
            factory.createMediaSource(ExoMediaItem.fromUri(audioUrl)),
          ),
        )
        looksLikeHls -> setMediaSource(HlsMediaSource.Factory(dataSourceFactory).createMediaSource(ExoMediaItem.fromUri(url)))
        else -> setMediaSource(factory.createMediaSource(ExoMediaItem.fromUri(url)))
      }
      repeatMode = Player.REPEAT_MODE_OFF
      volume = if (muted) 0f else 1f
      // Deliberately *not* seeking before prepare.
      //
      // These URLs are not read with HTTP Range headers: ChunkedGoogleVideoDataSource asks
      // googlevideo for a span through its own `&range=` query parameter, and a first request that
      // does not start at byte zero is answered 403. Seeking here therefore did not skip the
      // opening — it broke playback outright, on every trailer. The seek is applied once the source
      // is prepared instead; see the listener below.
      prepare()
    }
  }

  DisposableEffect(player, lifecycleOwner) {
    var playbackEnded = false
    // Applied once, after the source is prepared, because a seek before that makes the first
    // chunk request start mid-file and googlevideo answers it 403. By this point the opening bytes
    // have been read, so the seek is an ordinary one and the span it asks for is accepted.
    var startApplied = startPositionMs <= 0L
    val listener = object : Player.Listener {
      override fun onPlaybackStateChanged(playbackState: Int) {
        if (playbackState == Player.STATE_READY && !startApplied) {
          startApplied = true
          player.seekTo(startPositionMs)
        }
        if (playbackState == Player.STATE_READY) latestOnReady.value()
        if (playbackState == Player.STATE_ENDED && !playbackEnded) {
          playbackEnded = true
          latestOnEnded.value()
        }
      }
      override fun onVideoSizeChanged(videoSize: VideoSize) {
        attachedContainer?.setVideoSize(videoSize)
      }
      override fun onPlayerError(error: PlaybackException) {
        // A source that faults as it runs out has still shown the viewer the whole trailer.
        // Reporting it would send the YouTube path off to resolve a fresh link and play the
        // trailer through a second time.
        if (playbackEnded) return
        latestOnError.value()
      }
    }
    val observer = LifecycleEventObserver { _, event ->
      when (event) {
        Lifecycle.Event.ON_START -> { if (playWhenReady) player.play() }
        Lifecycle.Event.ON_STOP -> player.pause()
        else -> Unit
      }
    }
    player.addListener(listener)
    if (player.playbackState == Player.STATE_READY) latestOnReady.value()
    attachedContainer?.setVideoSize(player.videoSize)
    lifecycleOwner.lifecycle.addObserver(observer)
    onDispose {
      lifecycleOwner.lifecycle.removeObserver(observer)
      player.removeListener(listener)
      player.release()
    }
  }

  // Treat the trailer as over [endTrimMs] before the file is, so a KinoCheck upload ends on its own
  // last frame rather than running into the channel outro.
  //
  // Polled rather than driven off player events: Media3 emits nothing as position advances through
  // steady playback, so a listener would only notice once the file had already ended. Half a second
  // is finer than anyone can see against a ten-second trim and costs one field read.
  LaunchedEffect(player, endTrimMs) {
    if (endTrimMs <= 0L) return@LaunchedEffect
    while (true) {
      val duration = player.duration
      if (duration != androidx.media3.common.C.TIME_UNSET && duration > endTrimMs && player.currentPosition >= duration - endTrimMs) {
        player.pause()
        latestOnEnded.value()
        return@LaunchedEffect
      }
      delay(500)
    }
  }

  LaunchedEffect(player, playWhenReady) {
    player.playWhenReady = playWhenReady
  }

  LaunchedEffect(player, muted) {
    player.volume = if (muted) 0f else 1f
  }

  AndroidView(
    modifier = modifier,
    factory = { viewContext ->
      TrailerTextureContainer(viewContext).also { container ->
        attachedContainer = container
        container.layoutParams = android.view.ViewGroup.LayoutParams(
          android.view.ViewGroup.LayoutParams.MATCH_PARENT,
          android.view.ViewGroup.LayoutParams.MATCH_PARENT,
        )
        container.attachPlayer(player)
        container.setVideoSize(player.videoSize)
      }
    },
    update = { view ->
      attachedContainer = view
      view.attachPlayer(player)
      view.setVideoSize(player.videoSize)
    },
    onRelease = { view ->
      if (attachedContainer === view) attachedContainer = null
      view.detachPlayer(player)
    },
  )
}

private class TrailerTextureContainer(context: Context) : FrameLayout(context) {
  private val textureView = TextureView(context)
  private val textureTransform = Matrix()
  private var videoAspectRatio = 16f / 9f
  private var attachedPlayer: ExoPlayer? = null

  init {
    clipChildren = false
    clipToPadding = false
    isFocusable = false
    isClickable = false
    addView(textureView, LayoutParams(LayoutParams.MATCH_PARENT, LayoutParams.MATCH_PARENT))
    textureView.isFocusable = false
    textureView.isClickable = false
  }

  fun attachPlayer(player: ExoPlayer) {
    if (attachedPlayer === player) return
    attachedPlayer?.clearVideoTextureView(textureView)
    attachedPlayer = player
    player.setVideoTextureView(textureView)
  }

  fun detachPlayer(player: ExoPlayer) {
    if (attachedPlayer === player) {
      player.clearVideoTextureView(textureView)
      attachedPlayer = null
    }
  }

  private fun updateScaleTransform() {
    val w = width.toFloat()
    val h = height.toFloat()
    if (w <= 0f || h <= 0f || videoAspectRatio <= 0f) return
    val viewAR = w / h
    textureTransform.reset()
    if (viewAR > videoAspectRatio) {
      textureTransform.setScale(1f, viewAR / videoAspectRatio, w / 2f, h / 2f)
    } else {
      textureTransform.setScale(videoAspectRatio / viewAR, 1f, w / 2f, h / 2f)
    }
    textureView.setTransform(textureTransform)
  }

  fun setVideoSize(videoSize: VideoSize) {
    if (videoSize.width <= 0 || videoSize.height <= 0) return
    videoAspectRatio = videoSize.width * videoSize.pixelWidthHeightRatio / videoSize.height
    updateScaleTransform()
  }

  override fun onSizeChanged(w: Int, h: Int, oldW: Int, oldH: Int) {
    super.onSizeChanged(w, h, oldW, oldH)
    updateScaleTransform()
  }
}

@Composable
private fun ClassicDetailHero(
  detail: MediaDetail,
  backdrop: String?,
  metadataLine: String,
  scrollOffset: () -> Int,
  autoPlayTrailer: Boolean,
  trailerResolution: Int,
  hazeState: HazeState,
  streamCount: Int,
  streamLoading: Boolean,
  primaryPlayLabel: String,
  selectedTab: String,
  showEpisodes: Boolean,
  showStreamsList: Boolean,
  inWatchlist: Boolean,
  showMediaActions: Boolean,
  showWatchedAction: Boolean,
  watched: Boolean,
  externalRatingsEnabled: Boolean,
  enabledRatingProviders: Set<String>,
  overview: String,
  overviewExpanded: Boolean,
  onOverviewExpandedChange: (Boolean) -> Unit,
  onPlay: () -> Unit,
  onTrailer: () -> Unit,
  onAbout: () -> Unit,
  onStreams: () -> Unit,
  onEpisodes: () -> Unit,
  onSave: () -> Unit,
  onToggleWatched: () -> Unit,
  showFavouriteAction: Boolean = false,
  isFavourite: Boolean = false,
  proxyStatus: Boolean? = null,
  onToggleFavourite: () -> Unit = {},
  trailerMuted: Boolean = true,
  onTrailerMutedChange: (Boolean) -> Unit = {},
  /** Autoplay is on but its start delay has not elapsed yet. */
  trailerAutoplayPending: Boolean = false,
  /** The dominant-colour page background, when one is in use. Null keeps the theme's. */
  pageBackground: Color? = null,
) {
  BoxWithConstraints(modifier = Modifier.fillMaxWidth()) {
    val artworkHeight = (maxWidth * 1.18f).coerceIn(440.dp, 670.dp)
    val foreground = MaterialTheme.colorScheme.onBackground
    // The colour the page is actually painted with. In Dominant mode the scrims below fade the
    // artwork into that rather than into the theme background, which is what stops the hero ending
    // on a band of black over a coloured page.
    val background = pageBackground ?: MaterialTheme.colorScheme.background
    val lightDetail = background.luminance() > 0.5f

    val trailerControlContent = if (lightDetail) MaterialTheme.colorScheme.onSurface else Color.White
    var overviewCanExpand by remember(overview) { mutableStateOf(false) }
    var titleLogoFailed by remember(detail.id, detail.titleLogo) { mutableStateOf(false) }
    var trailerPlaying by rememberSaveable(detail.id, "classicTrailer") { mutableStateOf(autoPlayTrailer && !detail.trailerUrl.isNullOrBlank()) }
    var trailerReady by remember(detail.id, detail.trailerUrl) { mutableStateOf(false) }
    var trailerFailed by remember(detail.id, detail.trailerUrl) { mutableStateOf(false) }
    var trailerPlaybackKey by rememberSaveable(detail.id, "classicTrailerKey") { mutableIntStateOf(0) }
    // Autoplay gets one turn per title. Set once the trailer has run to the end, been stopped, or
    // failed - after that the hero image stays put and the replay button is the only way back.
    var trailerAutoplayUsed by rememberSaveable(detail.id, "classicTrailerUsed") { mutableStateOf(false) }
    // Symmetric on purpose. `trailerPlaying` is seeded from autoPlayTrailer at first composition,
    // and autoPlayTrailer is held false until the page has drawn — so by the time it turns true
    // the seed has already been taken as false and rememberSaveable will not re-run. Handling only
    // the false edge left the trailer permanently stopped, reachable only through the replay
    // button. Starting here is also what lets the gate open later without losing autoplay.
    LaunchedEffect(autoPlayTrailer) {
      if (autoPlayTrailer) {
        if (!detail.trailerUrl.isNullOrBlank() && !trailerFailed && !trailerAutoplayUsed) trailerPlaying = true
      } else {
        trailerPlaying = false
        trailerReady = false
        trailerFailed = false
      }
    }
    Column(modifier = Modifier.fillMaxWidth()) {
      // Half an artwork-height taller than the artwork itself, so the scrim's mirrored lower half
      // has somewhere to live. Overflowing this box instead was tried and does not work — the
      // oversized child gets measured back down to the parent, which squeezed the whole gradient
      // into the artwork's height and left its brightest point sitting on the very edge it was
      // supposed to hide. The content below is pulled up by the same amount, so nothing moves.
      Box(modifier = Modifier.fillMaxWidth().height(artworkHeight * 1.5f)) {
        Box(modifier = Modifier.fillMaxWidth().height(artworkHeight).align(Alignment.TopCenter).clip(RectangleShape)) {
          AsyncImage(
            model = backdrop,
            contentDescription = detail.title,
            modifier = Modifier.fillMaxSize().graphicsLayer {
              translationY = scrollOffset().toFloat() * 0.42f
              scaleX = 1.04f
              scaleY = 1.04f
            },
            contentScale = ContentScale.Crop,
            alignment = Alignment.TopCenter,
          )
          if (trailerPlaying && !detail.trailerUrl.isNullOrBlank()) {
            key(trailerPlaybackKey) {
              // Drifts with the backdrop so the page scrolls over the trailer rather than shoving
              // it up the screen — the same 0.42 factor the still image uses, so swapping between
              // them mid-scroll does not change how the hero moves.
              //
              // Deliberately `offset` and not `graphicsLayer`. The video view is a platform surface
              // and transforming one while a LazyColumn scrolls can take RenderThread down on some
              // OnePlus/OPPO GPUs, which is why the parallax was stripped from here in the first
              // place. An offset is resolved during placement — the view is positioned somewhere
              // else rather than drawn through a matrix — so it buys the same movement without
              // putting the surface inside a transformed layer. Reading scrollOffset() in the
              // lambda also keeps it in the placement phase, off the recomposition path.
              TrailerPlaybackView(
                url = detail.trailerUrl,
                modifier = Modifier
                  .fillMaxSize()
                  .offset { IntOffset(0, (scrollOffset() * 0.42f).roundToInt()) },
                autoPlay = true,
                muted = trailerMuted,
                maxHeight = trailerResolution,
                alternateUrls = detail.trailerCandidateUrls(),
                preferredUrl = rememberKinocheckTrailerUrl(detail),
                onReadyChanged = { trailerReady = it },
                onLoadFailed = { trailerFailed = true; trailerPlaying = false; trailerAutoplayUsed = true },
                onEnded = { trailerPlaying = false; trailerReady = false; trailerAutoplayUsed = true },
              )
            }
          }
        }
        if (!lightDetail) {
        // The bottom fade, mirrored about the artwork's bottom edge.
        //
        // One box and one brush rather than two stacked scrims: the halves have to meet at exactly
        // full `background` with no seam of their own, and two separately composited gradients
        // cannot guarantee that — the pair would show a faint band wherever their end stops did not
        // land on the same pixel.
        //
        // The box is 1.5x the artwork, so the edge sits at 0.667 of the brush. Everything above it
        // is the original fade at its original proportions (0.50/0.76/0.93/1.00 of the artwork,
        // divided by 1.5); everything below is those same steps walked back out again. The result
        // is darkest exactly on the cut and falls away symmetrically, so the hard bottom of the
        // artwork has nothing to read against — it is the middle of a gradient rather than an end.
        //
        // Only visible where something sits under the hero to darken, which is the vivid-ambient
        // backdrop. On a plain background the lower half paints background over background and
        // costs nothing.
        Box(
          modifier = Modifier
            .fillMaxSize()
            .background(
              Brush.verticalGradient(
                colorStops = arrayOf(
                  0.0000f to Color.Black.copy(alpha = 0.04f),
                  0.3333f to Color.Transparent,
                  0.5067f to background.copy(alpha = 0.42f),
                  0.6200f to background.copy(alpha = 0.94f),
                  0.6667f to background,
                  0.7133f to background.copy(alpha = 0.94f),
                  0.8267f to background.copy(alpha = 0.42f),
                  1.0000f to Color.Transparent,
                ),
              ),
            ),
        )
        }

        if (trailerPlaying) {
          if (!lightDetail) {
            // Anchored to the artwork's bottom edge rather than to this box's, which is now half an
            // artwork-height lower. Still straddles that edge 90dp either side, as it always meant
            // to — its lower half was being clipped away entirely until the box stopped clipping.
            Column(
              modifier = Modifier
                .align(Alignment.TopCenter)
                .offset(y = artworkHeight - 90.dp)
                .fillMaxWidth()
                .height(180.dp),
            ) {
              Box(modifier = Modifier.fillMaxWidth().weight(1f).background(Brush.verticalGradient(listOf(Color.Transparent, background))))
              Box(modifier = Modifier.fillMaxWidth().weight(1f).background(Brush.verticalGradient(listOf(background, Color.Transparent))))
            }
          }
          // Only over the artwork. Filling this box would now reach down over the poster and title,
          // where a tap means something else.
          Box(
            modifier = Modifier
              .fillMaxWidth()
              .height(artworkHeight)
              .align(Alignment.TopCenter)
              .clickable(interactionSource = remember { MutableInteractionSource() }, indication = null) { onTrailerMutedChange(!trailerMuted) },
          )
        }
        // No spinner while the trailer loads. The backdrop is already on screen and the trailer
        // fades in over it when it is ready, so a spinner only announces a wait the viewer would
        // not otherwise notice — and draws the eye to the one part of the page that is not ready.
        if (autoPlayTrailer && !detail.trailerUrl.isNullOrBlank()) {
          Row(
            modifier = Modifier.align(Alignment.TopEnd).statusBarsPadding().padding(14.dp),
            horizontalArrangement = Arrangement.spacedBy(8.dp),
          ) {
            FrostedGlassSurface(
              modifier = Modifier.size(48.dp),
              shape = CircleShape,
                // Sample the same page-level haze state as the back button so the
                // controls share its frosted backdrop-blur look.
                hazeStateOverride = hazeState,
                blurRadius = 68f,
                tintAlpha = if (lightDetail) 0.14f else 0.06f,
                borderAlpha = if (lightDetail) 0.10f else 0.08f,
                baseAlpha = if (lightDetail) 0.28f else 0.08f,
                fillColorOverride = if (lightDetail) null else Color.White,
                showEdgeGradient = false,
              ) {
              IconButton(
                onClick = {
                  if (trailerPlaying) {
                    onTrailerMutedChange(!trailerMuted)
                  } else {
                    // Replay keeps whatever the viewer last chose to hear; it used to force the
                    // sound back off, which undid an unmute every time a trailer was restarted.
                    trailerFailed = false
                    trailerReady = false
                    trailerPlaybackKey += 1
                    trailerPlaying = true
                  }
                },
              ) {
                Icon(
                  imageVector = if (!trailerPlaying) Icons.Rounded.Refresh else if (trailerMuted) Icons.AutoMirrored.Rounded.VolumeOff else Icons.AutoMirrored.Rounded.VolumeUp,
                  contentDescription = if (!trailerPlaying) "Replay trailer" else if (trailerMuted) "Unmute trailer" else "Mute trailer",
                  tint = Color.White,
                )
              }
            }
            if (trailerPlaying) {
              FrostedGlassSurface(
                modifier = Modifier.size(48.dp),
                shape = CircleShape,
                // Sample the same page-level haze state as the back button so the
                // controls share its frosted backdrop-blur look.
                hazeStateOverride = hazeState,
                blurRadius = 68f,
                tintAlpha = if (lightDetail) 0.14f else 0.06f,
                borderAlpha = if (lightDetail) 0.10f else 0.08f,
                baseAlpha = if (lightDetail) 0.28f else 0.08f,
                fillColorOverride = if (lightDetail) null else Color.White,
                showEdgeGradient = false,
              ) {
                IconButton(
                  onClick = {
                    trailerPlaying = false
                    trailerReady = false
                    trailerAutoplayUsed = true
                  },
                ) {
                  Icon(Icons.Rounded.Close, contentDescription = "Stop trailer", tint = trailerControlContent)
                }
              }
            }
          }
        }
      }
      Column(
        modifier = Modifier
          .fillMaxWidth()
          .layout { measurable, constraints ->
            val placeable = measurable.measure(constraints)
            // The artwork box carries half an artwork-height of scrim below the picture, so the
            // pull-up absorbs that as well as the original 112dp overlap. Without it the poster
            // and title would sit that far further down and the page would grow by the same.
            val overlap = (112.dp + artworkHeight / 2).roundToPx()
            layout(placeable.width, (placeable.height - overlap).coerceAtLeast(0)) {
              placeable.placeRelative(0, -overlap)
            }
          }
          .padding(horizontal = 24.dp),
        verticalArrangement = Arrangement.spacedBy(18.dp),
      ) {
        Row(
          modifier = Modifier.fillMaxWidth(),
          horizontalArrangement = Arrangement.spacedBy(18.dp),
          verticalAlignment = Alignment.Bottom,
        ) {
          if (!detail.poster.isNullOrBlank()) {
            AsyncImage(
              model = detail.poster,
              contentDescription = "${detail.title} poster",
              modifier = Modifier.width(112.dp).height(168.dp).clip(StreamDekRadius.cardShape).border(1.dp, Color.White.copy(alpha = 0.24f), StreamDekRadius.cardShape),
              contentScale = ContentScale.Crop,
            )
          }
          Column(
            // Light mode has no bottom fade on the hero, so anchor the title block to the
            // top of the overlapped row: the hero's bottom edge sits exactly 112dp below
            // the row top, letting us pin the logo just above the edge (with padding) and
            // start the tagline just below it.
            modifier = if (lightDetail) Modifier.weight(1f).align(Alignment.Top) else Modifier.weight(1f).padding(bottom = 6.dp),
            verticalArrangement = Arrangement.spacedBy(if (lightDetail) 8.dp else 9.dp),
          ) {
            if (!detail.titleLogo.isNullOrBlank() && !titleLogoFailed) {
              HeroTitleArtwork(
                url = detail.titleLogo,
                title = detail.title,
                modifier = if (lightDetail) Modifier.fillMaxWidth().height(106.dp).padding(bottom = 8.dp) else Modifier.fillMaxWidth().height(74.dp),
                alignment = if (lightDetail) Alignment.BottomStart else Alignment.CenterStart,
                onError = { titleLogoFailed = true },
              )
            } else if (lightDetail) {
              Box(modifier = Modifier.fillMaxWidth().height(106.dp).padding(bottom = 8.dp), contentAlignment = Alignment.BottomStart) {
                Text(detail.title, color = foreground, style = MaterialTheme.typography.headlineMedium.copy(shadow = Shadow(Color.Black.copy(alpha = 0.48f), Offset(0f, 1.5f), 4f)), fontWeight = FontWeight.Black, maxLines = 3, overflow = TextOverflow.Ellipsis)
              }
            } else {
              Text(detail.title, color = foreground, style = MaterialTheme.typography.headlineMedium, fontWeight = FontWeight.Black, maxLines = 3, overflow = TextOverflow.Ellipsis)
            }
            detail.tagline?.takeIf { it.isNotBlank() }?.let {
              Text("\"$it\"", color = foreground.copy(alpha = 0.64f), style = MaterialTheme.typography.bodyMedium, fontStyle = androidx.compose.ui.text.font.FontStyle.Italic, maxLines = 2, overflow = TextOverflow.Ellipsis)
            }
            if (metadataLine.isNotBlank()) Text(metadataLine, color = foreground.copy(alpha = 0.62f), style = MaterialTheme.typography.bodySmall, fontWeight = FontWeight.Bold, maxLines = 1, overflow = TextOverflow.Ellipsis)
          }
        }
        Box(modifier = Modifier.fillMaxWidth(), contentAlignment = Alignment.Center) {
          DetailRatingBadges(detail, externalRatingsEnabled, enabledRatingProviders)
        }
        if (proxyStatus != null) {
          Box(modifier = Modifier.fillMaxWidth(), contentAlignment = Alignment.Center) {
            LiveProxyStatusBadge(proxied = proxyStatus)
          }
        }
        StreamDekDetailActions(
          streamCount = streamCount, streamLoading = streamLoading, primaryPlayLabel = primaryPlayLabel, selectedTab = selectedTab,
          showEpisodes = showEpisodes, showStreamsList = showStreamsList, inWatchlist = inWatchlist, showMediaActions = showMediaActions,
          showWatchedAction = showWatchedAction, watched = watched, autoPlayTrailer = autoPlayTrailer && !detail.trailerUrl.isNullOrBlank(),
          trailerAutoplayPending = trailerAutoplayPending,
          onPlay = onPlay, hasTrailer = showMediaActions && !detail.trailerUrl.isNullOrBlank(), onTrailer = onTrailer, onAbout = onAbout,
          onStreams = onStreams, onEpisodes = onEpisodes, onSave = onSave, onToggleWatched = onToggleWatched,
          showFavouriteAction = showFavouriteAction, isFavourite = isFavourite, onToggleFavourite = onToggleFavourite,
        )
        if (overview.isNotBlank()) {
          Column(verticalArrangement = Arrangement.spacedBy(5.dp)) {
            Text(
              overview,
              color = foreground.copy(alpha = 0.76f),
              style = MaterialTheme.typography.bodyMedium,
              lineHeight = 23.sp,
              maxLines = if (overviewExpanded) 8 else 4,
              overflow = TextOverflow.Ellipsis,
              onTextLayout = { if (!overviewExpanded) overviewCanExpand = it.hasVisualOverflow },
            )
            if (overviewCanExpand || overviewExpanded) {
              Text(if (overviewExpanded) "Show less" else "Show more", color = foreground.copy(alpha = 0.62f), style = MaterialTheme.typography.bodyMedium, fontWeight = FontWeight.Bold, modifier = Modifier.clickable { onOverviewExpandedChange(!overviewExpanded) })
            }
          }
        }
      }
    }
  }
}

@Composable
private fun DetailHero(
  detail: MediaDetail,
  backdrop: String?,
  metadataLine: String,
  style: DetailPageStyle,
  scrollOffset: () -> Int,
  autoPlayTrailer: Boolean,
  trailerResolution: Int,
  hazeState: HazeState,
  streamCount: Int,
  streamLoading: Boolean,
  primaryPlayLabel: String,
  selectedTab: String,
  showEpisodes: Boolean,
  showStreamsList: Boolean,
  inWatchlist: Boolean,
  showMediaActions: Boolean,
  showWatchedAction: Boolean,
  watched: Boolean,
  externalRatingsEnabled: Boolean,
  enabledRatingProviders: Set<String>,
  overview: String,
  overviewExpanded: Boolean,
  onOverviewExpandedChange: (Boolean) -> Unit,
  onPlay: () -> Unit,
  onTrailer: () -> Unit,
  onAbout: () -> Unit,
  onStreams: () -> Unit,
  onEpisodes: () -> Unit,
  onSave: () -> Unit,
  onToggleWatched: () -> Unit,
  showFavouriteAction: Boolean = false,
  isFavourite: Boolean = false,
  proxyStatus: Boolean? = null,
  onToggleFavourite: () -> Unit = {},
  trailerMuted: Boolean = true,
  onTrailerMutedChange: (Boolean) -> Unit = {},
  /** Autoplay is on but its start delay has not elapsed yet. */
  trailerAutoplayPending: Boolean = false,
  /** The dominant-colour page background, when one is in use. */
  pageBackground: Color? = null,
) {
  if (style == DetailPageStyle.Classic) {
    ClassicDetailHero(
      detail, backdrop, metadataLine, scrollOffset, autoPlayTrailer, trailerResolution, hazeState, streamCount, streamLoading, primaryPlayLabel, selectedTab, showEpisodes, showStreamsList, inWatchlist, showMediaActions, showWatchedAction, watched, externalRatingsEnabled, enabledRatingProviders, overview, overviewExpanded, onOverviewExpandedChange, onPlay, onTrailer, onAbout, onStreams, onEpisodes, onSave, onToggleWatched,
      showFavouriteAction = showFavouriteAction, isFavourite = isFavourite, proxyStatus = proxyStatus, onToggleFavourite = onToggleFavourite,
      trailerMuted = trailerMuted, onTrailerMutedChange = onTrailerMutedChange,
      trailerAutoplayPending = trailerAutoplayPending,
      pageBackground = pageBackground,
    )
    return
  }
  BoxWithConstraints(modifier = Modifier.fillMaxWidth()) {
    val heroHeight = ((maxWidth * if (style == DetailPageStyle.Centered) 1.36f else 1.30f).coerceIn(500.dp, 760.dp))
    // The colour the page is actually painted with, which is the artwork's own in Dominant mode.
    // Everything below fades the hero into this rather than into the theme background — fading to
    // black over a coloured page leaves a band of black across the join, which is the same seam
    // the Classic hero had before it was given the page colour to work with.
    val background = pageBackground ?: MaterialTheme.colorScheme.background
    val lightDetail = background.luminance() > 0.5f

    val detailForeground = MaterialTheme.colorScheme.onBackground
    val trailerControlContent = if (lightDetail) MaterialTheme.colorScheme.onSurface else Color.White
    var overviewCanExpand by remember(overview) { mutableStateOf(false) }
    var titleLogoFailed by remember(detail.id, detail.titleLogo) { mutableStateOf(false) }
    var trailerReady by remember(detail.id, detail.trailerUrl) { mutableStateOf(false) }
    var trailerFailed by remember(detail.id, detail.trailerUrl) { mutableStateOf(false) }
    var trailerPlaying by rememberSaveable(detail.id, detail.trailerUrl) { mutableStateOf(autoPlayTrailer && !detail.trailerUrl.isNullOrBlank()) }
    var trailerPlaybackKey by rememberSaveable(detail.id, detail.trailerUrl) { mutableIntStateOf(0) }
    // Autoplay gets one turn per title. Set once the trailer has run to the end, been stopped, or
    // failed - after that the hero image stays put and the replay button is the only way back.
    //
    // It has to survive this composable leaving the composition, which the hero does every time it
    // is scrolled out of the list: the effect below runs again on the way back in, and without this
    // it restarted a trailer the viewer had already watched to the end.
    var trailerAutoplayUsed by rememberSaveable(detail.id, detail.trailerUrl) { mutableStateOf(false) }
    // Symmetric on purpose. `trailerPlaying` is seeded from autoPlayTrailer at first composition,
    // and autoPlayTrailer is held false until the page has drawn — so by the time it turns true
    // the seed has already been taken as false and rememberSaveable will not re-run. Handling only
    // the false edge left the trailer permanently stopped, reachable only through the replay
    // button. Starting here is also what lets the gate open later without losing autoplay.
    LaunchedEffect(autoPlayTrailer) {
      if (autoPlayTrailer) {
        if (!detail.trailerUrl.isNullOrBlank() && !trailerFailed && !trailerAutoplayUsed) trailerPlaying = true
      } else {
        trailerPlaying = false
        trailerReady = false
        trailerFailed = false
      }
    }
    Column(modifier = Modifier.fillMaxWidth()) {
      Box(
        modifier = Modifier
          .fillMaxWidth()
          .height(heroHeight)
          .clip(RectangleShape),
      ) {
        AsyncImage(
          model = backdrop,
          contentDescription = detail.title,
          modifier = Modifier
            .fillMaxSize()
            .graphicsLayer {
              translationY = scrollOffset().toFloat() * 0.5f
              scaleX = 1.08f
              scaleY = 1.08f
            },
          contentScale = ContentScale.Crop,
          alignment = Alignment.Center,
        )
        androidx.compose.animation.AnimatedVisibility(
          visible = trailerPlaying && !detail.trailerUrl.isNullOrBlank(),
          // Same parallax as the static hero image, so scrolling glides the page content over the
          // trailer while the video drifts at half speed. This is what the comment here always
          // claimed; the modifier that did it was missing, so the trailer was pushed up the screen
          // one-for-one while the still image it replaced stayed put.
          //
          // `offset` rather than the image's `graphicsLayer`: the video is a platform surface and
          // transforming one mid-scroll can take RenderThread down on some OnePlus/OPPO GPUs. An
          // offset moves it during placement instead, which is the same movement without the
          // transformed layer.
          modifier = Modifier
            .fillMaxSize()
            .offset { IntOffset(0, (scrollOffset() * 0.5f).roundToInt()) },
          // Two crossfades in, and longer still on the way out: the still image underneath has to
          // be fully there before the video surface goes, or the handover flashes the background.
          enter = fadeIn(animationSpec = StreamDekMotion.crossfadeSpec(MotionDuration.crossfade * 2)),
          exit = fadeOut(animationSpec = StreamDekMotion.crossfadeSpec((MotionDuration.crossfade * 2.4f).toInt())),
        ) {
          key(trailerPlaybackKey) {
            TrailerPlaybackView(
              url = detail.trailerUrl.orEmpty(),
              modifier = Modifier.fillMaxSize(),
              autoPlay = true,
              muted = trailerMuted,
              maxHeight = trailerResolution,
              alternateUrls = detail.trailerCandidateUrls(),
              preferredUrl = rememberKinocheckTrailerUrl(detail),
              onReadyChanged = { trailerReady = it },
              onLoadFailed = { trailerFailed = true; trailerPlaying = false; trailerAutoplayUsed = true },
              onEnded = { trailerPlaying = false; trailerReady = false; trailerAutoplayUsed = true },
            )
          }
        }
        if (trailerPlaying) {
          Box(
            modifier = Modifier
              .fillMaxSize()
              .clickable(interactionSource = remember { MutableInteractionSource() }, indication = null) { onTrailerMutedChange(!trailerMuted) },
          )
        }
        // No spinner while the trailer loads. The backdrop is already on screen and the trailer
        // fades in over it when it is ready, so a spinner only announces a wait the viewer would
        // not otherwise notice — and draws the eye to the one part of the page that is not ready.
        if (autoPlayTrailer && !detail.trailerUrl.isNullOrBlank()) {
          Row(
            modifier = Modifier.align(Alignment.TopEnd).statusBarsPadding().padding(14.dp),
            horizontalArrangement = Arrangement.spacedBy(8.dp),
          ) {
            FrostedGlassSurface(
              modifier = Modifier.size(48.dp),
              shape = CircleShape,
                // Sample the same page-level haze state as the back button so the
                // controls share its frosted backdrop-blur look.
                hazeStateOverride = hazeState,
                blurRadius = 68f,
                tintAlpha = if (lightDetail) 0.14f else 0.06f,
                borderAlpha = if (lightDetail) 0.10f else 0.08f,
                baseAlpha = if (lightDetail) 0.28f else 0.08f,
                fillColorOverride = if (lightDetail) null else Color.White,
                showEdgeGradient = false,
              ) {
              IconButton(
                onClick = {
                  if (trailerPlaying) onTrailerMutedChange(!trailerMuted) else {
                    // Replay keeps whatever the viewer last chose to hear; it used to force the
                    // sound back off, which undid an unmute every time a trailer was restarted.
                    trailerFailed = false
                    trailerReady = false
                    trailerPlaybackKey += 1
                    trailerPlaying = true
                  }
                },
              ) {
                Icon(
                  imageVector = if (!trailerPlaying) Icons.Rounded.Refresh else if (trailerMuted) Icons.AutoMirrored.Rounded.VolumeOff else Icons.AutoMirrored.Rounded.VolumeUp,
                  contentDescription = if (!trailerPlaying) "Replay trailer" else if (trailerMuted) "Unmute trailer" else "Mute trailer",
                  tint = Color.White,
                )
              }
            }
            if (trailerPlaying) {
              FrostedGlassSurface(
                modifier = Modifier.size(48.dp),
                shape = CircleShape,
                // Sample the same page-level haze state as the back button so the
                // controls share its frosted backdrop-blur look.
                hazeStateOverride = hazeState,
                blurRadius = 68f,
                tintAlpha = if (lightDetail) 0.14f else 0.06f,
                borderAlpha = if (lightDetail) 0.10f else 0.08f,
                baseAlpha = if (lightDetail) 0.28f else 0.08f,
                fillColorOverride = if (lightDetail) null else Color.White,
                showEdgeGradient = false,
              ) {
                IconButton(onClick = { trailerPlaying = false; trailerReady = false; trailerAutoplayUsed = true }) {
                  Icon(Icons.Rounded.Close, contentDescription = "Stop trailer", tint = trailerControlContent)
                }
              }
            }
          }
        }
        if (!lightDetail) Box(modifier = Modifier.fillMaxSize().background(Color.Black.copy(alpha = 0.10f)))
        if (!lightDetail) {
        Box(
          modifier = Modifier
            .align(Alignment.BottomCenter)
            .fillMaxWidth()
            .height(360.dp)
            .background(
              Brush.verticalGradient(
                colorStops = arrayOf(
                  0.00f to Color.Transparent,
                  0.18f to background.copy(alpha = 0.08f),
                  0.42f to background.copy(alpha = 0.32f),
                  0.68f to background.copy(alpha = 0.70f),
                  1.00f to background,
                ),
              ),
            ),
        )
        }

        Column(
          modifier = Modifier
            .align(if (style == DetailPageStyle.Centered) Alignment.BottomCenter else Alignment.BottomStart)
            .fillMaxWidth()
            .padding(horizontal = 24.dp)
            .padding(bottom = 22.dp),
          horizontalAlignment = if (style == DetailPageStyle.Centered) Alignment.CenterHorizontally else Alignment.Start,
          verticalArrangement = Arrangement.spacedBy(8.dp),
        ) {
          if (!detail.titleLogo.isNullOrBlank() && !titleLogoFailed) {
            HeroTitleArtwork(
              url = detail.titleLogo,
              title = detail.title,
              modifier = Modifier.fillMaxWidth(if (style == DetailPageStyle.Centered) 1f else 0.68f).height(92.dp).padding(horizontal = if (style == DetailPageStyle.Centered) 40.dp else 0.dp),
              alignment = if (style == DetailPageStyle.Centered) Alignment.Center else Alignment.CenterStart,
              onError = { titleLogoFailed = true },
            )
          } else {
            Text(
              detail.title,
              style = MaterialTheme.typography.headlineMedium.copy(shadow = if (lightDetail) Shadow(Color.Black.copy(alpha = 0.62f), Offset(0f, 2f), 5f) else null),
              fontWeight = FontWeight.Black,
              maxLines = 3,
              overflow = TextOverflow.Ellipsis,
              color = Color.White,
              textAlign = if (style == DetailPageStyle.Centered) androidx.compose.ui.text.style.TextAlign.Center else androidx.compose.ui.text.style.TextAlign.Start,
            )
          }
          DetailRatingBadges(
            detail = detail,
            externalRatingsEnabled = externalRatingsEnabled,
            enabledRatingProviders = enabledRatingProviders,
          )
          if (metadataLine.isNotBlank()) {
            Text(
              metadataLine,
              color = Color.White.copy(alpha = 0.72f),
              style = MaterialTheme.typography.bodyMedium,
              fontWeight = FontWeight.Bold,
              maxLines = 1,
              overflow = TextOverflow.Ellipsis,
            )
          }
          if (proxyStatus != null) {
            LiveProxyStatusBadge(proxied = proxyStatus)
          }
        }
      }

      Column(
        modifier = Modifier
          .fillMaxWidth()
          .background(
            Brush.verticalGradient(
              colors = when {
                lightDetail && style == DetailPageStyle.Centered -> listOf(Color.Transparent, Color.Transparent, Color.Transparent)
                lightDetail -> listOf(background, background, background)
                else -> listOf(background, background.copy(alpha = 0.82f), Color.Transparent)
              },
            ),
          )
          .padding(horizontal = 24.dp)
          .padding(top = 2.dp, bottom = 2.dp),
        verticalArrangement = Arrangement.spacedBy(18.dp),
      ) {
        StreamDekDetailActions(
          streamCount = streamCount,
          streamLoading = streamLoading,
          selectedTab = selectedTab,
          showEpisodes = showEpisodes,
          showStreamsList = showStreamsList,
          inWatchlist = inWatchlist,
          showMediaActions = showMediaActions,
          autoPlayTrailer = autoPlayTrailer && !detail.trailerUrl.isNullOrBlank(),
          trailerAutoplayPending = trailerAutoplayPending,
          primaryPlayLabel = primaryPlayLabel,
          onPlay = onPlay,
          hasTrailer = !detail.trailerUrl.isNullOrBlank(),
          onTrailer = onTrailer,
          onAbout = onAbout,
          onStreams = onStreams,
          onEpisodes = onEpisodes,
          onSave = onSave,
          showWatchedAction = showWatchedAction,
          watched = watched,
          onToggleWatched = onToggleWatched,
          showFavouriteAction = showFavouriteAction,
          isFavourite = isFavourite,
          onToggleFavourite = onToggleFavourite,
          modifier = Modifier.padding(top = if (lightDetail && style == DetailPageStyle.Centered) 10.dp else 0.dp),
          actionSpacing = if (lightDetail && style == DetailPageStyle.Centered) 19.dp else 24.dp,
        )
        if (overview.isNotBlank()) {
          Column(verticalArrangement = Arrangement.spacedBy(5.dp)) {
            Text(
              overview,
              color = detailForeground.copy(alpha = 0.76f),
              style = MaterialTheme.typography.bodyMedium,
              lineHeight = 23.sp,
              maxLines = if (overviewExpanded) 8 else 4,
              overflow = TextOverflow.Ellipsis,
              onTextLayout = { layout ->
                if (!overviewExpanded) overviewCanExpand = layout.hasVisualOverflow
              },
            )
            if (overviewCanExpand || overviewExpanded) {
              Text(
                if (overviewExpanded) "Show less" else "Show more",
                color = detailForeground.copy(alpha = 0.58f),
                style = MaterialTheme.typography.bodyMedium,
                fontWeight = FontWeight.Bold,
                modifier = Modifier.clickable { onOverviewExpandedChange(!overviewExpanded) },
              )
            }
          }
        }
      }
    }
  }
}

private fun formatReleaseDate(value: String?): String {
  if (value.isNullOrBlank()) return "Unknown"
  val parsed = runCatching { SimpleDateFormat("yyyy-MM-dd", Locale.US).parse(value) }.getOrNull()
  if (parsed != null) return SimpleDateFormat("MMM dd, yyyy", Locale.US).format(parsed)
  return value
}

private fun isFutureReleaseDate(value: String?): Boolean {
  val date = value?.take(10) ?: return false
  if (!Regex("\\d{4}-\\d{2}-\\d{2}").matches(date)) return false
  val today = SimpleDateFormat("yyyy-MM-dd", Locale.US).format(java.util.Date())
  return date > today
}

private fun movieStatusLabel(detail: MediaDetail): String =
  if (detail.type == "movie" && isFutureReleaseDate(detail.releaseDate)) "Unreleased" else "Released"

@Composable
private fun StreamDekDetailActions(
  /** True while autoplay is on and the start delay has not elapsed yet. */
  trailerAutoplayPending: Boolean = false,
  streamCount: Int,
  streamLoading: Boolean,
  primaryPlayLabel: String,
  selectedTab: String,
  showEpisodes: Boolean,
  showStreamsList: Boolean,
  inWatchlist: Boolean,
  showMediaActions: Boolean,
  showWatchedAction: Boolean,
  watched: Boolean,
  autoPlayTrailer: Boolean,
  onPlay: () -> Unit,
  hasTrailer: Boolean,
  onTrailer: () -> Unit,
  onAbout: () -> Unit,
  onStreams: () -> Unit,
  onEpisodes: () -> Unit,
  onSave: () -> Unit,
  onToggleWatched: () -> Unit,
  modifier: Modifier = Modifier,
  actionSpacing: Dp = 24.dp,
  showFavouriteAction: Boolean = false,
  isFavourite: Boolean = false,
  onToggleFavourite: () -> Unit = {},
) {
  val foreground = MaterialTheme.colorScheme.onBackground
  val background = MaterialTheme.colorScheme.background
  val lightMode = background.luminance() > 0.5f
  val primaryContainer = if (lightMode) MaterialTheme.colorScheme.surface else foreground
  val primaryContent = if (lightMode) MaterialTheme.colorScheme.onSurface else background
  Column(modifier = modifier, verticalArrangement = Arrangement.spacedBy(actionSpacing), horizontalAlignment = Alignment.CenterHorizontally) {
    Row(modifier = Modifier.fillMaxWidth(), horizontalArrangement = Arrangement.spacedBy(10.dp)) {
      Button(
        onClick = onPlay,
        enabled = primaryPlayLabel != "Unreleased",
        modifier = Modifier.weight(1f).height(50.dp),
        shape = StreamDekRadius.pill,
        colors = ButtonDefaults.buttonColors(containerColor = primaryContainer, contentColor = primaryContent),
        elevation = ButtonDefaults.buttonElevation(defaultElevation = if (lightMode) 3.dp else 0.dp),
        contentPadding = PaddingValues(horizontal = 20.dp),
      ) {
        Icon(Icons.Rounded.PlayArrow, contentDescription = null, modifier = Modifier.size(20.dp))
        Spacer(modifier = Modifier.width(8.dp))
        Text(primaryPlayLabel, style = MaterialTheme.typography.titleSmall, fontWeight = FontWeight.Black)
      }
      // Hidden as soon as an autoplay trailer is *intended*, not once it has actually started.
      // Gating on autoPlayTrailer alone meant this button appeared for the length of the start
      // delay and then vanished under the viewer's thumb when the trailer arrived.
      if (showMediaActions && !autoPlayTrailer && !trailerAutoplayPending) {
        if (lightMode) {
          Button(
            onClick = onTrailer,
            enabled = hasTrailer,
            modifier = Modifier.size(50.dp),
            shape = StreamDekRadius.pill,
            colors = ButtonDefaults.buttonColors(containerColor = primaryContainer, contentColor = primaryContent),
            elevation = ButtonDefaults.buttonElevation(defaultElevation = 3.dp),
            contentPadding = PaddingValues(0.dp),
          ) {
            Icon(Icons.Rounded.Movie, contentDescription = "Trailer", modifier = Modifier.size(21.dp))
          }
        } else {
          OutlinedButton(
            onClick = onTrailer,
            enabled = hasTrailer,
            modifier = Modifier.size(50.dp),
            shape = StreamDekRadius.pill,
            border = BorderStroke(1.dp, foreground.copy(alpha = if (hasTrailer) 0.26f else 0.10f)),
            colors = ButtonDefaults.outlinedButtonColors(
              containerColor = foreground.copy(alpha = 0.08f),
              contentColor = foreground,
              disabledContentColor = foreground.copy(alpha = 0.34f),
            ),
            contentPadding = PaddingValues(0.dp),
          ) {
            Icon(Icons.Rounded.Movie, contentDescription = "Trailer", modifier = Modifier.size(21.dp))
          }
        }
      }
    }
    Row(
      modifier = Modifier.fillMaxWidth(),
      horizontalArrangement = Arrangement.spacedBy(8.dp),
      verticalAlignment = Alignment.CenterVertically,
    ) {
      DetailPillTab("About", selectedTab == DetailTab.About.name, onAbout, modifier = Modifier.weight(1f))
      if (showEpisodes) {
        DetailPillTab("Episodes", selectedTab == DetailTab.Episodes.name, onEpisodes, modifier = Modifier.weight(1.18f))
      } else if (showStreamsList) {
        DetailPillTab(
          "Streams ($streamCount)",
          selectedTab == DetailTab.Streams.name,
          onStreams,
          modifier = Modifier.weight(1.18f),
          loading = streamLoading,
          compactLabel = "⚡ $streamCount",
        )
      }
      if (showMediaActions) {
        DetailIconOnlyPill(if (inWatchlist) "Saved" else "Save", inWatchlist, onSave) { Icon(Icons.Rounded.Bookmark, contentDescription = null, modifier = Modifier.size(19.dp)) }
      }
      if (showFavouriteAction) {
        DetailIconOnlyPill(if (isFavourite) "Favourited" else "Favourite", isFavourite, onToggleFavourite) {
          Icon(if (isFavourite) Icons.Rounded.Star else Icons.Rounded.StarBorder, contentDescription = null, modifier = Modifier.size(19.dp))
        }
      }
      if (showWatchedAction) {
        DetailIconOnlyPill(if (watched) "Watched" else "Seen", watched, onToggleWatched) {
          Icon(Icons.Rounded.CheckCircle, contentDescription = null, tint = if (watched) Color(0xFF22C55E) else LocalContentColor.current, modifier = Modifier.size(19.dp))
        }
      }
    }
  }
}

/**
 * A tab pill that falls back to [compactLabel] when [label] will not fit.
 *
 * The pills share the row with About and up to three icon buttons, so on a narrow screen the
 * weight left for this one is not enough for "Streams (25)" and it ellipsised to something like
 * "Streams (2…" — the count, which is the useful part, was what got cut. The width is measured
 * rather than guessed from the screen size, so the swap happens exactly when it is needed and
 * only for the label that is genuinely too long.
 */
@Composable
private fun DetailPillTab(
  label: String,
  selected: Boolean,
  onClick: () -> Unit,
  modifier: Modifier = Modifier,
  loading: Boolean = false,
  compactLabel: String? = null,
) {
  val foreground = MaterialTheme.colorScheme.onBackground
  val textStyle = MaterialTheme.typography.labelMedium.copy(fontWeight = FontWeight.Bold)
  OutlinedButton(
    modifier = modifier,
    onClick = onClick,
    shape = StreamDekRadius.pill,
    border = BorderStroke(1.dp, foreground.copy(alpha = if (selected) 0.82f else 0.18f)),
    colors = ButtonDefaults.outlinedButtonColors(
      containerColor = foreground.copy(alpha = if (selected) 0.10f else 0.04f),
      contentColor = foreground,
    ),
    contentPadding = PaddingValues(horizontal = 14.dp, vertical = 7.dp),
  ) {
    // The spinner sits on top of the label rather than beside it. Laid out in a row it added
    // its own width plus a spacer to a pill that is already weight-constrained, which pushed
    // "Streams (25)" past the space available on a 360dp screen. Overlaying costs no width at
    // all, and the count stays readable underneath while sources are still arriving.
    BoxWithConstraints(contentAlignment = Alignment.Center) {
      val measurer = rememberTextMeasurer()
      val available = constraints.maxWidth
      val shown = remember(label, compactLabel, available, textStyle) {
        if (compactLabel == null) {
          label
        } else {
          val width = measurer.measure(AnnotatedString(label), textStyle, maxLines = 1).size.width
          if (width <= available) label else compactLabel
        }
      }
      Text(
        shown,
        style = textStyle,
        maxLines = 1,
        overflow = TextOverflow.Ellipsis,
        // The compact form is an icon plus a number, which reads as nothing useful aloud, so the
        // full wording is what assistive tech is given either way.
        modifier = Modifier.semantics { contentDescription = label },
      )
      if (loading) {
        CircularProgressIndicator(
          modifier = Modifier.size(16.dp),
          strokeWidth = 1.7.dp,
          color = foreground.copy(alpha = 0.55f),
        )
      }
    }
  }
}

@Composable
private fun DetailIconOnlyPill(label: String, selected: Boolean, onClick: () -> Unit, icon: @Composable () -> Unit) {
  val selectedColor = Color(0xFF22C55E)
  val foreground = MaterialTheme.colorScheme.onBackground
  OutlinedButton(
    onClick = onClick,
    shape = StreamDekRadius.pill,
    border = BorderStroke(1.dp, if (selected) selectedColor.copy(alpha = 0.92f) else foreground.copy(alpha = 0.16f)),
    colors = ButtonDefaults.outlinedButtonColors(
      containerColor = if (selected) selectedColor.copy(alpha = 0.18f) else foreground.copy(alpha = 0.04f),
      contentColor = if (selected) selectedColor else foreground,
    ),
    contentPadding = PaddingValues(0.dp),
    modifier = Modifier.size(48.dp),
  ) {
    AnimatedContent(targetState = selected, label = "detail_action_" + label) { _ -> icon() }
  }
}
@Composable
private fun DetailIconTab(label: String, selected: Boolean, onClick: () -> Unit) {
  OutlinedButton(
    onClick = onClick,
    shape = StreamDekRadius.pill,
    border = BorderStroke(1.dp, Color.White.copy(alpha = if (selected) 0.70f else 0.16f)),
    colors = ButtonDefaults.outlinedButtonColors(
      containerColor = if (selected) Color.White.copy(alpha = 0.08f) else Color.Black.copy(alpha = 0.12f),
      contentColor = Color.White,
    ),
    contentPadding = PaddingValues(horizontal = 12.dp, vertical = 7.dp),
  ) {
    Text(label, style = MaterialTheme.typography.labelMedium, fontWeight = FontWeight.Bold)
  }
}

@Composable
private fun DetailActionIconPill(icon: ImageVector, label: String, selected: Boolean, onClick: () -> Unit) {
  OutlinedButton(
    onClick = onClick,
    shape = StreamDekRadius.pill,
    border = BorderStroke(1.dp, Color.White.copy(alpha = if (selected) 0.70f else 0.16f)),
    colors = ButtonDefaults.outlinedButtonColors(
      containerColor = if (selected) Color.White.copy(alpha = 0.10f) else Color.Black.copy(alpha = 0.12f),
      contentColor = Color.White,
    ),
    contentPadding = PaddingValues(horizontal = 11.dp, vertical = 7.dp),
  ) {
    Icon(icon, contentDescription = label, modifier = Modifier.size(17.dp))
    Spacer(modifier = Modifier.width(6.dp))
    Text(label, style = MaterialTheme.typography.labelSmall, fontWeight = FontWeight.Bold)
  }
}
/**
 * Widest a fact card has to be before its contents fit on one line.
 *
 * "RELEASE DATE" at labelSmall with 1.1sp tracking needs about 90dp and "Feb 27, 2024" at
 * bodySmall bold about 84dp, on top of the card's own 28dp of horizontal padding. Three equal
 * columns only clear that from roughly 411dp of screen width upward, which is why the date was
 * ellipsized and the label wrapped on an ordinary phone.
 */
private val DetailFactCardMinWidth = 128.dp
private val DetailFactCardSpacing = 12.dp

@OptIn(androidx.compose.foundation.layout.ExperimentalLayoutApi::class)
@Composable
private fun DetailFactsSection(detail: MediaDetail) {
  Column(modifier = Modifier.padding(horizontal = 24.dp), verticalArrangement = Arrangement.spacedBy(14.dp)) {
    Text("Movie details", style = MaterialTheme.typography.headlineSmall, fontWeight = FontWeight.Black, color = MaterialTheme.colorScheme.onBackground)
    val facts = listOf(
      "RELEASE DATE" to formatReleaseDate(detail.releaseDate),
      "STATUS" to movieStatusLabel(detail),
      "DURATION" to (detail.runtimeMinutes?.let { "${it / 60}h ${it % 60}m" } ?: "N/A"),
    )
    BoxWithConstraints {
      // Cards are given an explicit width rather than a weight so the ones on a short final row
      // stay the same size as the rest instead of stretching. Two across from 320dp, three from
      // roughly 470dp, so wide phones and tablets keep the original single-row layout.
      val columns = ((maxWidth + DetailFactCardSpacing) / (DetailFactCardMinWidth + DetailFactCardSpacing))
        .toInt()
        .coerceIn(1, facts.size)
      val cardWidth = (maxWidth - DetailFactCardSpacing * (columns - 1)) / columns
      androidx.compose.foundation.layout.FlowRow(
        horizontalArrangement = Arrangement.spacedBy(DetailFactCardSpacing),
        verticalArrangement = Arrangement.spacedBy(DetailFactCardSpacing),
      ) {
        facts.forEach { (label, value) ->
          DetailFactCard(label, value, Modifier.width(cardWidth))
        }
      }
    }
  }
}

