private fun watchProviderUrl(provider: WatchProvider, title: String): String {
  provider.url?.takeIf { it.startsWith("http://") || it.startsWith("https://") }?.let { return it }
  val query = android.net.Uri.encode(title)
  return when {
    provider.name.contains("Netflix", true) -> "https://www.netflix.com/search?q=$query"
    provider.name.contains("Prime", true) || provider.name.contains("Amazon", true) -> "https://www.primevideo.com/search/ref=atv_nb_sr?phrase=$query"
    provider.name.contains("Disney", true) -> "https://www.disneyplus.com/search/$query"
    provider.name.contains("Apple TV", true) -> "https://tv.apple.com/search?term=$query"
    provider.name.contains("Paramount", true) -> "https://www.paramountplus.com/search/?q=$query"
    provider.name.contains("Hulu", true) -> "https://www.hulu.com/search?q=$query"
    provider.name.contains("Max", true) || provider.name.contains("HBO", true) -> "https://www.max.com/search?q=$query"
    provider.name.contains("Peacock", true) -> "https://www.peacocktv.com/search?q=$query"
    provider.name.contains("YouTube", true) -> "https://www.youtube.com/results?search_query=$query"
    else -> "https://www.google.com/search?q=" + android.net.Uri.encode("${provider.name} $title")
  }
}

private fun streamProviderNames(streams: List<AddonStream>): List<String> =
  streams.mapNotNull { it.addonName.takeIf(String::isNotBlank) ?: it.name?.takeIf(String::isNotBlank) }.distinct()

@Composable
private fun StreamListContent(
  uiState: AppUiState,
  selectedEpisode: EpisodeItem?,
  onPlayStream: (AddonStream, EpisodeItem?) -> Unit,
  onDownloadStream: (AddonStream) -> Unit = {},
  isStreamDownloadEligible: (AddonStream) -> Boolean = { false },
  compact: Boolean = false,
  selectedProviderOverride: String? = null,
  onProviderSelectedOverride: ((String) -> Unit)? = null,
  horizontalPadding: Dp = 24.dp,
) {
  val streamLightMode = MaterialTheme.colorScheme.background.luminance() > 0.5f
  val streamForeground = MaterialTheme.colorScheme.onSurface
  var longPressedStream by remember { mutableStateOf<AddonStream?>(null) }
  longPressedStream?.let { stream ->
    AlertDialog(
      onDismissRequest = { longPressedStream = null },
      title = { Text(stream.title?.takeIf { it.isNotBlank() } ?: stream.name?.takeIf { it.isNotBlank() } ?: "Stream options") },
      text = {
        Row(
          modifier = Modifier.fillMaxWidth().clip(StreamDekRadius.thumbShape).clickable {
            onDownloadStream(stream)
            longPressedStream = null
          }.padding(vertical = 12.dp, horizontal = 4.dp),
          horizontalArrangement = Arrangement.spacedBy(12.dp),
          verticalAlignment = Alignment.CenterVertically,
        ) {
          Icon(Icons.Rounded.Download, contentDescription = null, tint = MaterialTheme.colorScheme.primary)
          Text("Download for offline playback")
        }
      },
      confirmButton = {},
      dismissButton = { TextButton(onClick = { longPressedStream = null }) { Text("Cancel") } },
    )
  }
  val providers = remember(uiState.availableStreams) { streamProviderNames(uiState.availableStreams) }
  var localProviderFilter by rememberSaveable(providers) { mutableStateOf("All") }
  val providerFilter = selectedProviderOverride ?: localProviderFilter
  val onProviderSelected: (String) -> Unit = onProviderSelectedOverride ?: { localProviderFilter = it }
  LaunchedEffect(providers, providerFilter) {
    if (providerFilter != "All" && providerFilter !in providers) onProviderSelected("All")
  }
  val filteredStreams = remember(uiState.availableStreams, providerFilter) {
    if (providerFilter == "All") uiState.availableStreams
    else uiState.availableStreams.filter { (it.addonName.takeIf(String::isNotBlank) ?: it.name?.takeIf(String::isNotBlank)) == providerFilter }
  }

  if (uiState.streamLoading && uiState.availableStreams.isEmpty()) {
    Box(modifier = Modifier.padding(horizontal = horizontalPadding).fillMaxWidth().height(112.dp), contentAlignment = Alignment.Center) {
      CircularProgressIndicator(color = streamForeground)
    }
    return
  }
  if (uiState.availableStreams.isEmpty()) {
    // A known, permanent reason replaces the "keep waiting" wording, which would otherwise send
    // someone off refreshing a list that cannot fill.
    Text(
      uiState.streamsUnavailableReason
        ?: "Searching sources automatically. If none appear, refresh the Sources tab.",
      modifier = Modifier.padding(horizontal = horizontalPadding),
      color = streamForeground.copy(alpha = 0.68f),
      style = MaterialTheme.typography.bodyMedium,
    )
    return
  }
  // What a result is called when its own text names nothing — see [streamDisplayName].
  val fallbackName = remember(uiState.detail?.title, selectedEpisode) {
    listOfNotNull(
      uiState.detail?.title?.takeIf { it.isNotBlank() },
      selectedEpisode?.let { episode -> "S%02dE%02d".format(episode.seasonNumber, episode.episodeNumber) },
    ).joinToString(" · ").ifBlank { "Stream source" }
  }
  Column(modifier = Modifier.fillMaxWidth(), verticalArrangement = Arrangement.spacedBy(10.dp)) {
    if (compact) {
      // The short preview that sits under a poster. No headers: there is not enough of a list here
      // for a grouping to describe anything.
      filteredStreams.take(3).forEach { stream ->
        key(addonStreamPlaybackIdentity(stream)) {
          StreamResultCard(
            stream = stream,
            uiState = uiState,
            fallbackName = fallbackName,
            downloadable = isStreamDownloadEligible(stream),
            horizontalPadding = horizontalPadding,
            onPlay = { onPlayStream(stream, selectedEpisode) },
            onDownload = { onDownloadStream(stream) },
            onLongPress = { longPressedStream = stream },
          )
        }
      }
      return@Column
    }
    // Source, then quality, then size. Grouped rather than run together into one ranked list
    // because the question this page is asked is not "what is best" — the app already answers that
    // by playing the top result — it is "what has each source got", and a hundred results from
    // eight places interleaved by score cannot be read that way. Nothing is dropped on the way in:
    // every source that answered gets a section, whatever its results look like.
    val sections = remember(filteredStreams, uiState.preferredQuality) {
      buildStreamSourceSections(filteredStreams, uiState.preferredQuality)
    }
    sections.forEachIndexed { index, section ->
      key(section.source) {
        StreamSourceSection(
          section = section,
          uiState = uiState,
          fallbackName = fallbackName,
          horizontalPadding = horizontalPadding,
          // The first source opens; the rest are one tap away. With every section open, a title
          // with a dozen sources scrolls a long way before reaching the second one.
          initiallyExpanded = index == 0,
          isStreamDownloadEligible = isStreamDownloadEligible,
          onPlayStream = { stream -> onPlayStream(stream, selectedEpisode) },
          onDownloadStream = onDownloadStream,
          onLongPressStream = { stream -> longPressedStream = stream },
        )
      }
    }
  }
}

/** One source's results, split into quality bands. */
internal data class StreamSourceGroup(
  val source: String,
  /**
   * Any one of the section's results, for anything that has to ask where the section came from.
   *
   * The origin label itself is deliberately not resolved here: working it out means reading the
   * installed plugin and CloudStream collections, which is a live app singleton, and grouping is
   * otherwise pure arithmetic over the list it is handed.
   */
  val representative: AddonStream,
  val total: Int,
  val bands: List<StreamQualityBand>,
)

internal data class StreamQualityBand(val tier: StreamQualityTier, val streams: List<AddonStream>)

/**
 * Splits a result list by source, then by quality, then orders each band largest file first.
 *
 * Size descending rather than ascending: within a single quality the larger file is the better
 * encode often enough to be the right default, and anyone after the small one is looking at a band
 * that is already short. Results whose size could not be read sort to the end of their own band
 * rather than being treated as zero — an unknown size is not a small one.
 *
 * [preferredQuality] is the Streams setting, and it decides which band a source opens on. Grouping
 * must not quietly overrule a choice that was already made: somebody who asked for 1080p should
 * find 1080p at the top of every source, not have to scroll past 4K to reach it. On Auto the bands
 * fall in resolution order, highest first, which is what the ranking would have produced anyway.
 */
internal fun buildStreamSourceSections(
  streams: List<AddonStream>,
  preferredQuality: String = "Auto",
): List<StreamSourceGroup> =
  streams
    // groupBy keeps first-appearance order, and the list arriving here is already ranked, so the
    // source holding the best single result leads.
    .groupBy { stream -> stream.addonName.takeIf(String::isNotBlank) ?: stream.name?.takeIf(String::isNotBlank) ?: "Unknown source" }
    .map { (source, items) ->
      StreamSourceGroup(
        source = source,
        representative = items.first(),
        total = items.size,
        bands = items
          .groupBy(::streamQualityTier)
          .toList()
          .sortedBy { (tier, _) -> streamQualityBandOrder(tier, preferredQuality) }
          .map { (tier, banded) -> StreamQualityBand(tier, banded.sortedByDescending { streamSizeGiB(it) ?: -1.0 }) },
      )
    }

/** How many results a quality band shows before it offers the rest. */
private const val STREAM_BAND_PREVIEW_ROWS = 6

@Composable
private fun StreamSourceSection(
  section: StreamSourceGroup,
  uiState: AppUiState,
  fallbackName: String,
  horizontalPadding: Dp,
  initiallyExpanded: Boolean,
  isStreamDownloadEligible: (AddonStream) -> Boolean,
  onPlayStream: (AddonStream) -> Unit,
  onDownloadStream: (AddonStream) -> Unit,
  onLongPressStream: (AddonStream) -> Unit,
) {
  val foreground = MaterialTheme.colorScheme.onSurface
  // Keyed on where the section sits as well as on its name. Filtering to one source used to leave
  // that source collapsed - it had been remembered as "not the first section" from the unfiltered
  // list - so choosing a provider produced a page with one closed header and nothing under it.
  // Re-keying on the lead position means a section that becomes the first one opens, and a manual
  // collapse still survives everything short of the list re-ordering around it.
  var expanded by rememberSaveable(section.source, initiallyExpanded) { mutableStateOf(initiallyExpanded) }
  Column(modifier = Modifier.fillMaxWidth(), verticalArrangement = Arrangement.spacedBy(8.dp)) {
    Row(
      modifier = Modifier
        .padding(horizontal = horizontalPadding)
        .fillMaxWidth()
        .clip(StreamDekRadius.thumbShape)
        .clickable { expanded = !expanded }
        .padding(vertical = 6.dp),
      horizontalArrangement = Arrangement.spacedBy(10.dp),
      verticalAlignment = Alignment.CenterVertically,
    ) {
      // A short accent stroke rather than a filled header bar: it marks where a source begins
      // without turning every group into a slab the results then have to sit inside.
      Box(modifier = Modifier.width(3.dp).height(26.dp).clip(StreamDekRadius.pill).background(MaterialTheme.colorScheme.primary))
      Column(modifier = Modifier.weight(1f), verticalArrangement = Arrangement.spacedBy(1.dp)) {
        Text(
          section.source,
          color = foreground,
          style = MaterialTheme.typography.titleSmall,
          fontWeight = FontWeight.Black,
          maxLines = 1,
          overflow = TextOverflow.Ellipsis,
        )
        streamOriginLabel(section.representative)?.let {
          Text(it, color = foreground.copy(alpha = 0.48f), style = MaterialTheme.typography.labelSmall, maxLines = 1, overflow = TextOverflow.Ellipsis)
        }
      }
      Box(
        modifier = Modifier.clip(StreamDekRadius.pill).background(foreground.copy(alpha = 0.10f)).padding(horizontal = 9.dp, vertical = 3.dp),
      ) {
        Text("${section.total}", color = foreground.copy(alpha = 0.72f), style = MaterialTheme.typography.labelSmall, fontWeight = FontWeight.Black)
      }
      Icon(
        if (expanded) Icons.Rounded.KeyboardArrowUp else Icons.Rounded.KeyboardArrowDown,
        contentDescription = if (expanded) "Hide ${section.source} results" else "Show ${section.source} results",
        tint = foreground.copy(alpha = 0.58f),
      )
    }
    AnimatedVisibility(visible = expanded) {
      Column(modifier = Modifier.fillMaxWidth(), verticalArrangement = Arrangement.spacedBy(8.dp)) {
        section.bands.forEach { band ->
          key(band.tier) {
            StreamQualityBandContent(
              band = band,
              uiState = uiState,
              fallbackName = fallbackName,
              horizontalPadding = horizontalPadding,
              isStreamDownloadEligible = isStreamDownloadEligible,
              onPlayStream = onPlayStream,
              onDownloadStream = onDownloadStream,
              onLongPressStream = onLongPressStream,
            )
          }
        }
      }
    }
  }
}

@Composable
private fun StreamQualityBandContent(
  band: StreamQualityBand,
  uiState: AppUiState,
  fallbackName: String,
  horizontalPadding: Dp,
  isStreamDownloadEligible: (AddonStream) -> Boolean,
  onPlayStream: (AddonStream) -> Unit,
  onDownloadStream: (AddonStream) -> Unit,
  onLongPressStream: (AddonStream) -> Unit,
) {
  val foreground = MaterialTheme.colorScheme.onSurface
  val accent = streamQualityTierColor(band.tier, foreground)
  var showAll by rememberSaveable(band.tier) { mutableStateOf(false) }
  val visible = if (showAll) band.streams else band.streams.take(STREAM_BAND_PREVIEW_ROWS)
  Column(modifier = Modifier.fillMaxWidth(), verticalArrangement = Arrangement.spacedBy(7.dp)) {
    Row(
      modifier = Modifier.padding(horizontal = horizontalPadding, vertical = 2.dp).fillMaxWidth(),
      horizontalArrangement = Arrangement.spacedBy(10.dp),
      verticalAlignment = Alignment.CenterVertically,
    ) {
      Box(
        modifier = Modifier.clip(StreamDekRadius.badgeShape).background(accent.copy(alpha = 0.16f)).padding(horizontal = 8.dp, vertical = 3.dp),
      ) {
        Text(band.tier.label, color = accent, style = MaterialTheme.typography.labelSmall, fontWeight = FontWeight.Black, maxLines = 1)
      }
      // The rule carries the eye across to the count and gives the band a floor to sit on, which
      // is what stops a long list reading as one undifferentiated run of cards.
      Box(modifier = Modifier.weight(1f).height(1.dp).background(foreground.copy(alpha = 0.09f)))
      Text("${band.streams.size}", color = foreground.copy(alpha = 0.42f), style = MaterialTheme.typography.labelSmall, fontWeight = FontWeight.Bold)
    }
    visible.forEach { stream ->
      key(addonStreamPlaybackIdentity(stream)) {
        StreamResultCard(
          stream = stream,
          uiState = uiState,
          fallbackName = fallbackName,
          downloadable = isStreamDownloadEligible(stream),
          horizontalPadding = horizontalPadding,
          onPlay = { onPlayStream(stream) },
          onDownload = { onDownloadStream(stream) },
          onLongPress = { onLongPressStream(stream) },
        )
      }
    }
    if (band.streams.size > STREAM_BAND_PREVIEW_ROWS) {
      // Deferred, never dropped. A band opens on its largest few and keeps the rest one tap away,
      // so a source that answered with sixty results still has all sixty here.
      Text(
        if (showAll) "Show fewer" else "Show all ${band.streams.size}",
        color = MaterialTheme.colorScheme.primary,
        style = MaterialTheme.typography.labelMedium,
        fontWeight = FontWeight.Black,
        modifier = Modifier
          .padding(horizontal = horizontalPadding)
          .clip(StreamDekRadius.controlShape)
          .clickable { showAll = !showAll }
          .padding(horizontal = 8.dp, vertical = 6.dp),
      )
    }
  }
}

/**
 * One result.
 *
 * Lifted out of the list so the grouped view and the compact preview render an identical row, and
 * so the row itself has one job: say what this is, where it came from, how big it is, and offer
 * the two things that can be done with it.
 */
@Composable
private fun StreamResultCard(
  stream: AddonStream,
  uiState: AppUiState,
  fallbackName: String,
  downloadable: Boolean,
  horizontalPadding: Dp,
  onPlay: () -> Unit,
  onDownload: () -> Unit,
  onLongPress: () -> Unit,
) {
  val streamLightMode = MaterialTheme.colorScheme.background.luminance() > 0.5f
  val streamForeground = MaterialTheme.colorScheme.onSurface
  val streamCardColor = if (streamLightMode) MaterialTheme.colorScheme.onSurface.copy(alpha = 0.12f) else Color.White.copy(alpha = 0.075f)
  // Formatted mode is capped at three single lines: headline, provider, detail. Everything is
  // collapsed onto one line each and ellipsized, so one verbose source cannot push the next
  // result off screen.
  val primaryText = streamDisplayName(stream, fallbackName)
  // Where this result came from, in the television's words: the source's own name, and beside
  // it whether that source is an add-on, a plugin out of a named collection, or a file already
  // here. The name on its own never distinguished those, and a list of a hundred results from
  // eight places was unreadable because of it.
  val originText = streamOriginLabel(stream)
  val attributionText = listOfNotNull(
    stream.addonName.takeIf { it.isNotBlank() },
    stream.source?.takeIf { it.isNotBlank() },
  ).distinct().joinToString(" • ")
  val readyProvider = stream.cachedBy.firstOrNull()
  val secondaryText = listOf(stream.title, stream.description, stream.filename)
    .firstNotNullOfOrNull { candidate -> streamSingleLine(candidate)?.takeIf { it != primaryText } }
  // Whether this is the row the app is currently turning into a playback URL. Marked with a ring
  // around the card and nothing else: the inside of the card belongs to whoever sent the result,
  // and an overlay on top of it would hide the very text somebody chose the row by.
  val resolving = uiState.playerLaunching && uiState.launchingStreamKey == addonStreamPlaybackIdentity(stream)
  val resolvingRing = MaterialTheme.colorScheme.primary
  Card(
    modifier = Modifier
      .padding(horizontal = horizontalPadding)
      .fillMaxWidth()
      // Was a bare gesture detector, which drew nothing at all while the finger was down - so on a
      // slow resolve the row gave no sign it had been hit and got tapped again.
      .pressable(
        stream,
        onClick = onPlay,
        onLongPress = if (downloadable) onLongPress else null,
      )
      .then(
        if (resolving) Modifier.border(1.5.dp, resolvingRing.copy(alpha = 0.72f), StreamDekRadius.panelShape) else Modifier,
      ),
    colors = CardDefaults.cardColors(containerColor = streamCardColor),
    shape = StreamDekRadius.panelShape,
  ) {
    Box(modifier = Modifier.fillMaxWidth()) {
    Column(modifier = Modifier.padding(horizontal = 14.dp, vertical = 13.dp), verticalArrangement = Arrangement.spacedBy(7.dp)) {
      // "Top" places the badges at the very top of the card so the setting is
      // visibly honored for every addon result, including ones without a
      // secondary description line.
      if (uiState.fusionBadgesEnabled && uiState.badgePosition.equals("Top", ignoreCase = true)) {
        FusionBadgeRow(
          stream = stream,
          uiState = uiState,
          modifier = Modifier.padding(end = if (readyProvider != null) 174.dp else 0.dp),
        )
      }
      Row(verticalAlignment = Alignment.CenterVertically, horizontalArrangement = Arrangement.spacedBy(10.dp)) {
        Column(modifier = Modifier.weight(1f), verticalArrangement = Arrangement.spacedBy(2.dp)) {
          // Above the result rather than under it, and in both modes.
          //
          // The television puts it first because it is the thing you scan by when the same
          // release is offered by five sources. Verbatim mode keeps it too: that mode's promise
          // is that the add-on's own text is never rewritten, and a line the app adds above it
          // does not touch a word of what was sent.
          if (attributionText.isNotEmpty() || originText != null) {
            Row(
              modifier = Modifier.fillMaxWidth().padding(end = if (readyProvider != null) 174.dp else 0.dp),
              horizontalArrangement = Arrangement.spacedBy(7.dp),
              verticalAlignment = Alignment.CenterVertically,
            ) {
              // The attribution and the origin travel together and give up their space to the
              // badge, which is pinned to the right of this row rather than left where it began.
              Row(
                modifier = Modifier.weight(1f),
                horizontalArrangement = Arrangement.spacedBy(7.dp),
                verticalAlignment = Alignment.CenterVertically,
              ) {
                if (attributionText.isNotEmpty()) {
                  Text(
                    attributionText,
                    color = MaterialTheme.colorScheme.primary,
                    style = MaterialTheme.typography.labelMedium,
                    fontWeight = FontWeight.Black,
                    maxLines = 1,
                    overflow = TextOverflow.Ellipsis,
                    modifier = Modifier.weight(1f, fill = false),
                  )
                }
                originText?.let {
                  Text(
                    it,
                    color = streamForeground.copy(alpha = 0.48f),
                    style = MaterialTheme.typography.labelSmall,
                    maxLines = 1,
                    overflow = TextOverflow.Ellipsis,
                  )
                }
              }
            }
          }
          if (uiState.streamDekFormattingEnabled) {
            Text(primaryText, color = streamForeground, style = MaterialTheme.typography.titleSmall, fontWeight = FontWeight.Black, maxLines = 1, overflow = TextOverflow.Ellipsis)
          } else {
            // Verbatim. Stremio add-ons put deliberate structure in these two fields — `name`
            // is the short label ("Torrentio\n4k"), `title`/`description` the detail block with
            // its own line breaks, emoji and columns. No line cap, no ellipsis and no
            // substitution between fields: whatever it sent is what shows. The one thing added
            // is a headline when neither field named anything — a row reading only "1080p" is
            // not the add-on's text being respected, it is a result nobody can identify.
            val rawLabel = stream.name?.takeIf { it.isNotBlank() }
            // The detail line is the add-on's detail block -- unless it is the label over again.
            // Plenty of sources fill `name` and `title` with the same string, and every one of
            // their results rendered as two identical lines because of it. A line printed twice is
            // not the add-on's text being respected, so a field that repeats the label is skipped
            // and the next one with something else to say is used instead.
            val rawLabelPrint = rawLabel?.let(::streamTextFingerprint)
            val rawDetail = listOfNotNull(stream.title, stream.description)
              .firstOrNull { it.isNotBlank() && streamTextFingerprint(it) != rawLabelPrint }
            if (!streamTextNamesTitle(rawLabel) && !streamTextNamesTitle(rawDetail)) {
              Text(
                primaryText,
                color = streamForeground,
                style = MaterialTheme.typography.titleSmall,
                fontWeight = FontWeight.Black,
              )
            }
            rawLabel?.let {
              Text(it, color = streamForeground, style = MaterialTheme.typography.titleSmall, fontWeight = FontWeight.Black)
            }
            rawDetail?.let {
              Text(it, color = streamForeground.copy(alpha = 0.82f), style = MaterialTheme.typography.bodyMedium)
            }
          }
        }
        // Single size badge for the card — the duplicate that used to render
        // inside the badge row below has been removed.
        //
        // In both modes now, and gated only on the viewer's own Size Badges switch. The badge is
        // read out of what the add-on already sent -- the same field the player's loading screen
        // prints beside the release name -- so a result that showed no size here and "5.01 GB" a
        // second later on the loading screen was hiding one it had all along. Verbatim mode's
        // promise is that the add-on's own text is never rewritten, and a badge beside that text
        // does not touch a word of it.
        //
        // It is still only as good as what can be scraped: add-ons that put something other than a
        // size in that field render whole phrases as a pill, which is why it stays a narrow
        // right-hand badge rather than anything the row's layout depends on.
        if (uiState.showSizeBadges) {
          streamSizeLabel(stream)?.let { size ->
            Box(
              modifier = Modifier.clip(StreamDekRadius.badgeShape).background(oxbloodRed).padding(horizontal = 9.dp, vertical = 4.dp),
              contentAlignment = Alignment.Center,
            ) {
              Text(
                size,
                color = Color.White,
                style = MaterialTheme.typography.labelMedium,
                fontWeight = FontWeight.Black,
                maxLines = 1,
              )
            }
          }
        }
        // On the row itself rather than behind a long press, and only when this result can
        // actually be saved — which already accounts for the Downloads switch in settings, for
        // live channels, and for results that are a torrent hash rather than a file. A row with
        // no icon is a row with nothing to download.
        if (downloadable) {
          IconButton(onClick = onDownload, modifier = Modifier.size(34.dp)) {
            Icon(
              Icons.Rounded.Download,
              contentDescription = "Download this result",
              tint = streamForeground.copy(alpha = 0.68f),
              modifier = Modifier.size(20.dp),
            )
          }
        }
      }
      // Only in formatted mode: the raw branch above already renders the add-on's own detail
      // text in full, so repeating it here would duplicate it.
      if (uiState.streamDekFormattingEnabled) {
        secondaryText?.let {
          // Third and final line. It sits below the badge row rather than in the title column
          // so it gets the card's full width instead of whatever the badges leave over.
          Text(
            it,
            color = streamForeground.copy(alpha = 0.76f),
            style = MaterialTheme.typography.bodyMedium,
            maxLines = 1,
            overflow = TextOverflow.Ellipsis,
          )
        }
      }
      if (uiState.fusionBadgesEnabled && uiState.badgePosition.equals("Bottom", ignoreCase = true)) {
        FusionBadgeRow(stream = stream, uiState = uiState)
      }
    }
      // Availability is card-level state, so pin it to the card rather than to the title column.
      // The size/download rail no longer pushes this badge toward the middle of wide cards.
      readyProvider?.let { provider ->
        Box(
          modifier = Modifier
            .align(Alignment.TopEnd)
            .padding(top = 13.dp, end = 14.dp)
            .clip(StreamDekRadius.pill)
            .background(streamForeground)
            .padding(horizontal = 9.dp, vertical = 4.dp),
        ) {
          Text(
            "Ready · ${debridProviderLabel(provider)}",
            color = MaterialTheme.colorScheme.surface,
            style = MaterialTheme.typography.labelSmall,
            fontWeight = FontWeight.Black,
            maxLines = 1,
          )
        }
      }
    }
  }
}

private val oxbloodRed = Color(0xFF5B1216)

private fun ratingColor(rating: Double, lightMode: Boolean = false): Color = when {
  rating >= 7.0 -> if (lightMode) Color(0xFF087F3D) else Color(0xFF00E676)
  rating >= 5.0 -> if (lightMode) Color(0xFF9A6700) else Color(0xFFFFD740)
  else -> Color(0xFFC97070)
}

private fun ratingProviderLogoRes(provider: String): Int = when (provider.lowercase()) {
  "imdb" -> R.drawable.rating_imdb_logo
  "trakt" -> R.drawable.rating_trakt_logo
  "rt", "rotten", "tomatoes", "rotten tomatoes" -> R.drawable.rating_rotten_tomatoes_logo
  "metacritic" -> R.drawable.rating_metacritic_logo
  "letterboxd" -> R.drawable.rating_letterboxd_logo
  "audience score", "audience" -> R.drawable.rating_audience_score
  else -> R.drawable.rating_tmdb_logo
}

private fun ratingProviderId(provider: String): String {
  val key = provider.trim().lowercase().replace(Regex("[^a-z]"), "")
  return when (key) {
    "imdb" -> "imdb"
    "tmdb", "themoviedb" -> "tmdb"
    "rt", "rotten", "tomatoes", "rottentomatoes", "rottentomato" -> "tomatoes"
    "mc", "metacritic", "metascore" -> "metacritic"
    "trakt" -> "trakt"
    "lb", "letterbox", "letterboxd" -> "letterboxd"
    "aud", "audience", "audiencescore", "rtaudience", "popcornmeter" -> "audience"
    else -> key
  }
}

private fun normalizedRatingProvider(provider: String): String {
  val key = provider.lowercase().replace(" ", "").replace("_", "").replace("-", "")
  return when {
    key == "tmdb" || key == "themoviedb" || key.contains("themoviedb") -> "TMDB"
    key == "imdb" -> "IMDb"
    key == "rottentomatoes" || key == "tomatoes" || key.contains("tomato") || key == "rt" || key == "rotten" -> "Rotten Tomatoes"
    key == "metacritic" -> "Metacritic"
    key == "trakt" -> "Trakt"
    key == "letterboxd" -> "Letterboxd"
    key == "audience" || key == "audiencescore" || key == "rtaudience" || key == "popcornmeter" -> "Audience Score"
    else -> provider
  }
}

@Composable
private fun ImdbInlineRating(rating: Double, scale: Float = 1f, modifier: Modifier = Modifier) {
  Row(
    modifier = modifier
      .graphicsLayer { scaleX = scale; scaleY = scale }
      .clip(StreamDekRadius.pill)
      .background(Color.Black.copy(alpha = 0.58f))
      .border(1.dp, Color.White.copy(alpha = 0.12f), StreamDekRadius.pill)
      .padding(horizontal = 6.dp, vertical = 4.dp),
    horizontalArrangement = Arrangement.spacedBy(5.dp),
    verticalAlignment = Alignment.CenterVertically,
  ) {
    Box(
      modifier = Modifier.height(20.dp).clip(StreamDekRadius.badgeShape).background(Color(0xFFF5C518)).padding(horizontal = 6.dp, vertical = 2.dp),
      contentAlignment = Alignment.Center,
    ) {
      Text("IMDb", color = Color.Black, fontWeight = FontWeight.Black, style = MaterialTheme.typography.labelSmall)
    }
    Text(
      "${"%.1f".format(rating)}",
      color = Color.White,
      fontWeight = FontWeight.Black,
      style = MaterialTheme.typography.labelLarge,
      maxLines = 1,
    )
  }
}
@Composable
private fun BoxScope.CardImdbRatingBadge(rating: Double?, topPadding: Dp = 5.dp) {
  if (!LocalCardRatingsEnabled.current) return
  rating ?: return
  ImdbInlineRating(
    rating = rating,
    scale = 0.70f,
    modifier = Modifier.align(Alignment.TopCenter).padding(top = topPadding),
  )
}

private fun ratingLabelForProvider(provider: String, rating: Double?): String {
  if (rating == null) return ""
  val normalized = normalizedRatingProvider(provider)
  return when (normalized) {
    "Rotten Tomatoes", "Audience Score" -> "${rating.toInt()}%"
    "TMDB", "Metacritic", "Trakt" -> if (rating > 10.0) rating.toInt().toString() else "${"%.1f".format(rating)}"
    else -> "${"%.1f".format(rating)}"
  }
}

@Composable
private fun RatingProviderBadge(
  provider: String,
  rating: Double?,
  modifier: Modifier = Modifier,
  label: String? = null,
) {
  val lightMode = MaterialTheme.colorScheme.background.luminance() > 0.5f
  Row(
    modifier = modifier,
    horizontalArrangement = Arrangement.spacedBy(4.dp),
    verticalAlignment = Alignment.CenterVertically,
  ) {
    Image(
      painter = painterResource(ratingProviderLogoRes(provider)),
      contentDescription = provider,
      modifier = Modifier.height(14.dp),
      contentScale = ContentScale.Fit,
    )
    Text(
      label?.takeIf { it.isNotBlank() } ?: ratingLabelForProvider(provider, rating).ifBlank { normalizedRatingProvider(provider) },
      style = MaterialTheme.typography.labelSmall,
      fontWeight = FontWeight.Black,
      color = rating?.let { ratingColor(it, lightMode) } ?: MaterialTheme.colorScheme.onBackground.copy(alpha = 0.86f),
      maxLines = 1,
    )
  }
}

@Composable
private fun LiveProxyStatusBadge(proxied: Boolean, modifier: Modifier = Modifier) {
  val tint = if (proxied) Color(0xFF22C55E) else Color(0xFF94A3B8)
  Row(
    modifier = modifier
      .clip(StreamDekRadius.pill)
      .background(tint.copy(alpha = 0.16f))
      .border(1.dp, tint.copy(alpha = 0.38f), StreamDekRadius.pill)
      .padding(horizontal = 10.dp, vertical = 5.dp),
    horizontalArrangement = Arrangement.spacedBy(5.dp),
    verticalAlignment = Alignment.CenterVertically,
  ) {
    Icon(if (proxied) Icons.Rounded.Shield else Icons.Rounded.Public, contentDescription = null, tint = tint, modifier = Modifier.size(13.dp))
    Text(if (proxied) "Proxied Stream" else "Direct Stream", style = MaterialTheme.typography.labelSmall, fontWeight = FontWeight.Bold, color = tint)
  }
}

@Composable
private fun DetailRatingBadges(
  detail: MediaDetail,
  externalRatingsEnabled: Boolean,
  enabledRatingProviders: Set<String>,
  modifier: Modifier = Modifier,
) {
  // The master "Show Ratings" preference is card-only. Detail-page ratings remain independent;
  // their breadth is controlled by "Show More Rating Services" and the provider switches.
  if (enabledRatingProviders.isEmpty()) return
  val externalByProvider = if (externalRatingsEnabled) {
    detail.externalRatings
      .filter { it.rating != null }
      .map { it.copy(provider = normalizedRatingProvider(it.provider)) }
      .groupBy { ratingProviderId(it.provider) }
  } else {
    emptyMap()
  }
  val ratings = buildList {
    DEFAULT_RATING_PROVIDER_ORDER.forEach { providerId ->
      if (providerId !in enabledRatingProviders) return@forEach
      val external = externalByProvider[providerId]?.firstOrNull()
      when {
        external != null -> add(external)
        providerId == "imdb" && detail.imdbRating != null -> add(ExternalRating("IMDb", detail.imdbRating))
        providerId == "tmdb" && detail.tmdbRating != null -> add(ExternalRating("TMDB", detail.tmdbRating))
      }
    }
  }
  AnimatedVisibility(
    visible = ratings.isNotEmpty(),
    enter = fadeIn(animationSpec = StreamDekMotion.enterSpec()) + slideInVertically(initialOffsetY = { it / 3 }, animationSpec = StreamDekMotion.enterSpec(MotionDuration.long)),
    exit = fadeOut(animationSpec = StreamDekMotion.exitSpec()),
  ) {
    Row(
      modifier = modifier.horizontalScroll(rememberScrollState()),
      horizontalArrangement = Arrangement.spacedBy(8.dp),
      verticalAlignment = Alignment.CenterVertically,
    ) {
      ratings.forEach { item ->
        RatingProviderBadge(provider = item.provider, rating = item.rating, label = item.label)
      }
    }
  }
}

@Composable
private fun FusionBadgeRow(stream: AddonStream, uiState: AppUiState, modifier: Modifier = Modifier) {
  val sources = activeFusionSources(uiState)
  val configKey = remember(uiState.fusionBadgeSources, uiState.activeFusionBadgeUrl, uiState.fusionBadgeUrls) {
    uiState.activeFusionBadgeUrl.orEmpty() + "|" + uiState.fusionBadgeUrls.joinToString(",") +
      "|" + sources.sumOf { source -> source.filters.count { it.isEnabled } }
  }
  val badges = remember(stream, configKey) { cachedFusionBadges(stream, sources, configKey).take(10) }
  if (badges.isEmpty()) return
  val context = LocalContext.current
  val badgeShape = StreamDekRadius.badgeShape
  Row(
    modifier = modifier,
    horizontalArrangement = Arrangement.spacedBy(7.dp),
    verticalAlignment = Alignment.CenterVertically,
  ) {
    badges.forEach { badge ->
      val isFlag = badge.groupId == LANGUAGE_BADGE_GROUP_ID
      Box(
        modifier = Modifier
          .height(24.dp)
          .width(if (isFlag) 24.dp else 46.dp)
          .clip(badgeShape)
          .padding(horizontal = 4.dp, vertical = 3.dp),
        contentAlignment = Alignment.Center,
      ) {
        AsyncImage(
          model = ImageRequest.Builder(context)
            .data(badge.imageUrl)
            .diskCachePolicy(CachePolicy.ENABLED)
            .memoryCachePolicy(CachePolicy.ENABLED)
            .networkCachePolicy(CachePolicy.ENABLED)
            .crossfade(false)
            .build(),
          contentDescription = badge.name,
          modifier = Modifier.fillMaxSize(),
          contentScale = ContentScale.Fit,
        )
      }
    }
  }
}
@Composable
private fun PosterCard(
  item: MediaItem,
  showMeta: Boolean = true,
  dimmed: Boolean = false,
  /**
   * Wide 16:9 card using the item's backdrop instead of its poster.
   *
   * For New Episodes, where the backdrop holds the episode's own still. The meta block underneath
   * is unchanged, so the two shapes read as the same card at different proportions rather than as
   * two different components.
   */
  landscape: Boolean = false,
  onClick: () -> Unit,
  onLongPress: () -> Unit = {},
) {
  // Width and height take the same multiplier, so the artwork keeps its proportions exactly: a
  // Compact poster is the Relaxed one at four fifths, not a differently shaped card.
  val home = LocalHomeLayout.current
  Column(
    modifier = Modifier
      // A scrolling row already answers a wider window by showing more of itself, so this grows
      // only slightly — just enough that a poster is not a postage stamp on a 13-inch screen.
      .width(home.card(if (landscape) homeRowPosterWidth() * 1.62f else homeRowPosterWidth()))
      .alpha(if (dimmed) 0.4f else 1f)
      .pressable(item.id, item.type, onClick = onClick, onLongPress = onLongPress),
    verticalArrangement = Arrangement.spacedBy(home.cardMetaGap),
  ) {
    Box(
      modifier = Modifier
        .fillMaxWidth()
        .height(home.card(if (landscape) 118.dp else 204.dp))
        .clip(StreamDekRadius.cardShape)
        .background(Color(0xFF171717)),
    ) {
      AsyncImage(
        model = if (landscape) item.backdrop ?: item.poster else item.poster ?: item.backdrop,
        contentDescription = item.title,
        modifier = Modifier.fillMaxSize(),
        contentScale = ContentScale.Crop,
      )
      Box(
        modifier = Modifier.fillMaxSize().background(
          Brush.verticalGradient(
            colors = listOf(Color.Transparent, Color.Transparent, Color(0x8C000000)),
          ),
        ),
      )

      CardImdbRatingBadge(rating = item.rating)
    }
    if (showMeta) {
      // The caption is rebalanced rather than scaled with the poster: it is reserved a little more
      // height than a straight multiplier would give it, and its two lines come down by 8% instead
      // of 20%, because a card that fits more titles on screen is no use if the titles cannot be
      // read. The block still has a fixed height, so a row's cards keep one bottom edge.
      Column(modifier = Modifier.height(home.cardMetaHeight), verticalArrangement = Arrangement.spacedBy(home.card(4.dp))) {
        Text(
          item.title,
          maxLines = 2,
          overflow = TextOverflow.Ellipsis,
          fontWeight = FontWeight.SemiBold,
          fontSize = home.text(12.sp),
          lineHeight = home.text(16.sp),
        )
        Text(
          item.cardSubtitle ?: item.year ?: item.type.replaceFirstChar(Char::uppercase),
          fontSize = home.text(11.sp),
          maxLines = 1,
          overflow = TextOverflow.Ellipsis,
          fontWeight = if (item.cardHighlight) FontWeight.Bold else FontWeight.Normal,
          color = if (item.cardHighlight) {
            MaterialTheme.colorScheme.primary
          } else {
            MaterialTheme.colorScheme.onBackground.copy(alpha = 0.68f)
          },
        )
      }
    }
  }
}

@Composable
private fun ContinueWatchingCard(item: MediaItem, style: ContinueWatchingStyle, onClick: () -> Unit, onLongPress: () -> Unit = {}) {
  val watchedPercent = (item.progress ?: 0.0).toInt().coerceIn(0, 100)
  val progressFraction = (watchedPercent / 100f).coerceIn(0f, 1f)
  val imageModel = item.backdrop ?: item.poster
  // Each of the five shapes below scales the same way: every dimension and every inset through
  // `card`, every type size through `text`. The progress bar, the badges, the long-press actions
  // and the pressed animation are all untouched — a Compact card is the same card, smaller.
  val home = LocalHomeLayout.current
  val progressBar: @Composable () -> Unit = {
    Box(
      modifier = Modifier
        .fillMaxWidth()
        .height(home.card(5.dp))
        .clip(StreamDekRadius.pill)
        .background(MaterialTheme.colorScheme.onSurface.copy(alpha = 0.16f)),
    ) {
      Box(
        modifier = Modifier
          .fillMaxWidth(progressFraction)
          .height(home.card(5.dp))
          .clip(StreamDekRadius.pill)
          .background(MaterialTheme.colorScheme.primary),
      )
    }
  }

  when (style) {
    ContinueWatchingStyle.Cinematic, ContinueWatchingStyle.Glass -> {
      val overlayAlpha = if (style == ContinueWatchingStyle.Glass) 0.54f else 0.76f
      val cardHazeState = rememberHazeState()
      Box(
        modifier = Modifier
          .width(home.card(288.dp))
          .aspectRatio(16f / 9f)
          .clip(StreamDekRadius.thumbShape)
          .background(Color(0xFF141414))
          .border(1.dp, Color.White.copy(alpha = 0.12f), StreamDekRadius.thumbShape)
          .pressable(item.id, item.type, style, onClick = onClick, onLongPress = onLongPress),
      ) {
        AsyncImage(
          model = imageModel,
          contentDescription = item.title,
          modifier = Modifier
            .fillMaxSize()
            .then(if (style == ContinueWatchingStyle.Glass) Modifier.hazeSource(cardHazeState) else Modifier),
          contentScale = ContentScale.Crop,
        )
        Box(modifier = Modifier.fillMaxSize().background(Color.Black.copy(alpha = if (style == ContinueWatchingStyle.Glass) 0.26f else 0.38f)))
        if (style == ContinueWatchingStyle.Glass) {
          FrostedGlassSurface(
            modifier = Modifier.align(Alignment.BottomCenter).fillMaxWidth().height(home.card(60.5.dp)),
            shape = RectangleShape,
            hazeStateOverride = cardHazeState,
            blurRadius = 38f,
            tintAlpha = 0.10f,
            borderAlpha = 0f,
            baseAlpha = 0.08f,
            fillColorOverride = Color.Black,
            showEdgeGradient = false,
          ) {}
        }
        Column(
          modifier = Modifier
            .align(Alignment.BottomStart)
            .fillMaxWidth()
            .background(Brush.verticalGradient(colors = listOf(Color.Transparent, Color.Black.copy(alpha = overlayAlpha), Color.Black.copy(alpha = 0.94f))))
            .padding(horizontal = home.card(14.dp), vertical = home.card(12.dp)),
          verticalArrangement = Arrangement.spacedBy(home.card(6.dp)),
        ) {
          Text(item.title, maxLines = 1, overflow = TextOverflow.Ellipsis, fontWeight = FontWeight.ExtraBold, style = home.text(MaterialTheme.typography.titleMedium), color = Color.White)
          Text(item.cardSubtitle ?: item.year ?: item.type.replaceFirstChar(Char::uppercase), maxLines = 1, overflow = TextOverflow.Ellipsis, style = home.text(MaterialTheme.typography.bodySmall), color = Color.White.copy(alpha = 0.72f))
          progressBar()
          Text("$watchedPercent% watched", style = home.text(MaterialTheme.typography.bodySmall), color = Color.White.copy(alpha = 0.78f))
        }
      }
    }
    ContinueWatchingStyle.Ticket -> {
      Box(
        modifier = Modifier
          .width(home.card(316.dp))
          .height(home.card(88.dp))
          .clip(StreamDekRadius.thumbShape)
          .background(Color(0xFF121212))
          .border(1.dp, Color.White.copy(alpha = 0.10f), StreamDekRadius.thumbShape)
          .pressable(item.id, item.type, style, onClick = onClick, onLongPress = onLongPress),
      ) {
        AsyncImage(model = imageModel, contentDescription = item.title, modifier = Modifier.fillMaxSize(), contentScale = ContentScale.Crop)
        Box(modifier = Modifier.fillMaxSize().background(Color.Black.copy(alpha = 0.72f)))
        Row(modifier = Modifier.fillMaxSize().padding(horizontal = home.card(14.dp), vertical = home.card(12.dp)), verticalAlignment = Alignment.CenterVertically) {
          Column(modifier = Modifier.weight(1f), verticalArrangement = Arrangement.spacedBy(home.card(6.dp))) {
            // cardText, not text: this shape's height is fixed, so its type has to come down with
            // the box or a two-line title would squeeze the line below it harder here than it does
            // at Relaxed. See [HomeLayoutMetrics.cardText].
            Text(item.title, maxLines = 2, overflow = TextOverflow.Ellipsis, fontWeight = FontWeight.ExtraBold, style = home.cardText(MaterialTheme.typography.titleMedium), color = Color.White)
            Text(item.cardSubtitle ?: listOfNotNull(item.year, item.rating?.takeIf { LocalCardRatingsEnabled.current }?.let { "%.1f".format(it) }).joinToString(" • ").ifBlank { item.type.replaceFirstChar(Char::uppercase) }, maxLines = 1, overflow = TextOverflow.Ellipsis, style = home.cardText(MaterialTheme.typography.bodySmall), color = Color.White.copy(alpha = 0.72f))
          }
          Text("$watchedPercent%", color = Color.White, fontWeight = FontWeight.Black, style = home.cardText(MaterialTheme.typography.bodyMedium))
        }
        Box(modifier = Modifier.align(Alignment.BottomStart).fillMaxWidth()) { progressBar() }
      }
    }
    ContinueWatchingStyle.Mini -> {
      Row(
        modifier = Modifier
          .width(home.card(292.dp))
          .height(home.card(78.dp))
          .clip(StreamDekRadius.controlShape)
          .background(Color(0xFF121218))
          .border(1.dp, Color.White.copy(alpha = 0.12f), StreamDekRadius.controlShape)
          .pressable(item.id, item.type, style, onClick = onClick, onLongPress = onLongPress),
      ) {
        AsyncImage(model = imageModel, contentDescription = item.title, modifier = Modifier.width(home.card(120.dp)).fillMaxSize(), contentScale = ContentScale.Crop)
        Column(modifier = Modifier.weight(1f).padding(horizontal = home.card(10.dp), vertical = home.card(9.dp)), verticalArrangement = Arrangement.SpaceBetween) {
          Text(item.title, maxLines = 2, overflow = TextOverflow.Ellipsis, fontWeight = FontWeight.Bold, fontSize = home.text(12.sp), lineHeight = home.text(16.sp), color = Color.White)
          Text(item.cardSubtitle ?: item.year ?: item.type.replaceFirstChar(Char::uppercase), maxLines = 1, overflow = TextOverflow.Ellipsis, fontSize = home.text(10.sp), color = Color.White.copy(alpha = 0.66f))
          progressBar()
        }
      }
    }
    ContinueWatchingStyle.Stacked -> {
      Column(
        modifier = Modifier
          .width(home.card(155.dp))
          .clip(StreamDekRadius.controlShape)
          .background(Color(0xFF121218))
          .border(1.dp, Color.White.copy(alpha = 0.12f), StreamDekRadius.controlShape)
          .pressable(item.id, item.type, style, onClick = onClick, onLongPress = onLongPress),
      ) {
        Box(modifier = Modifier.fillMaxWidth().height(home.card(88.dp))) {
          AsyncImage(model = imageModel, contentDescription = item.title, modifier = Modifier.fillMaxSize(), contentScale = ContentScale.Crop)
          Box(modifier = Modifier.align(Alignment.BottomStart).fillMaxWidth()) { progressBar() }
        }
        Column(modifier = Modifier.padding(horizontal = home.card(9.dp), vertical = home.card(9.dp)), verticalArrangement = Arrangement.spacedBy(home.card(4.dp))) {
          // Two lines are always reserved, whether the title needs them or not. The row lays these
          // out side by side, so a card whose title fits on one line used to be a line shorter than
          // its neighbours and the row's bottom edge came out ragged. Every card now takes the
          // height of the tallest, and the artwork and progress bars line up across the row.
          Text(item.title, minLines = 2, maxLines = 2, overflow = TextOverflow.Ellipsis, fontWeight = FontWeight.Bold, fontSize = home.text(12.sp), lineHeight = home.text(16.sp), color = Color.White)
          Text(item.cardSubtitle ?: item.year ?: item.type.replaceFirstChar(Char::uppercase), maxLines = 1, overflow = TextOverflow.Ellipsis, fontSize = home.text(10.sp), color = Color.White.copy(alpha = 0.66f))
          Text("$watchedPercent% watched", fontSize = home.text(10.sp), color = Color.White.copy(alpha = 0.72f))
        }
      }
    }
  }
}
